QTF("gharib",1,[[1,1,"﴿بِسۡمِ ٱللَّهِ﴾: أبتدِئُ القراءةَ مُسْتعينًا باللهِ.\n\n﴿ٱلرَّحۡمَـٰنِ﴾: ذي الرَّحمةِ العامَّةِ لجميع الخَلْقِ.\n\n﴿ٱلرَّحِيمِ﴾: ذي الرَّحمةِ الخاصَّةِ بِالمؤمنين."],[2,2,"﴿ٱلۡحَمۡدُ﴾: الثَّناءُ على اللهِ بصفاتِه، وبنِعَمِه كلِّها.\n\n﴿ٱلۡعَـٰلَمِينَ﴾: جميعِ الخلْقِ."],[4,4,"﴿يَوۡمِ ٱلدِّينِ﴾: يومِ القيامةِ الذي يكونُ فيه الجزاءُ."],[5,5,"﴿إِيَّاكَ نَعۡبُدُ﴾: نَخُصُّك بالعبادةِ."],[6,6,"﴿ٱلصِّرَ ٰ⁠طَ ٱلۡمُسۡتَقِيمَ﴾: الطَّريقَ الواضحَ، المُوصِلَ إلى رِضوانِ اللهِ، وهو الإسلامُ."],[7,7,"﴿أَنۡعَمۡتَ عَلَيۡهِمۡ﴾: مَنَنْتَ عليهم بالهدايةِ والتَّوفيقِ.\n\n﴿ٱلۡمَغۡضُوبِ عَلَيۡهِمۡ﴾: الذين عَرَفُوا الحقَّ، ولم يَعْمَلُوا به.\n\n﴿وَلَا ٱلضَّآلِّينَ﴾: الذين لم يَهْتَدُوا، جَهْلًا منهم."]]);
QTF("gharib",2,[[1,1,"﴿الٓمٓ﴾: هذه الحروفُ المقطَّعَةُ تُشيرُ إلى أنّ القرآنَ مركَّبٌ من هذه الحروفِ التي تألَّفَتْ منها لغةُ العربِ، وقد عَجَزَ العربُ وغيرُهم عَنِ الإتيانِ بمثلِ القرآنِ، فدلَّ هذا على أن القرآنَ وحْيٌ من اللهِ."],[2,2,"﴿ٱلۡكِتَـٰبُ﴾: القرآنُ.\n\n﴿لَا رَيۡبَۛ فِيهِ﴾: لا شكَّ أنّه مِن عندِ اللهِ.\n\n﴿لِّلۡمُتَّقِينَ﴾: الذين يَخافون اللهَ، ويتَّبعون أحكامَه."],[3,3,"﴿يُؤۡمِنُونَ﴾: يُصَدِّقُون.\n\n﴿بِٱلۡغَيۡبِ﴾: بما لا يُدْرَكُ بالحواسِّ والعُقولِ، فلا يُعْرَفُ إلا بالوَحْيِ، كالإيمانِ بالملائكةِ.\n\n﴿وَيُقِيمُونَ﴾: يحافظون على أدائِها في مواقيتِها وفْقَ ما شَرَعَ اللهُ."],[4,4,"﴿بِمَآ أُنزِلَ إِلَيۡكَ﴾: إلى محمدٍ ﷺ، مِنَ القرآنِ والسُّنةِ.\n\n﴿وَمَآ أُنزِلَ مِن قَبۡلِكَ﴾: مِن كُتُبٍ كالتَّوراةِ والإنجيلِ\n\n﴿وَبِٱلۡـَٔاخِرَةِ هُمۡ يُوقِنُونَ﴾: يُصَدِّقُون بدارِ الحياةِ بعد الموتِ، وما فيها مِنَ الحِسابِ."],[5,5,"﴿ٱلۡمُفۡلِحُونَ﴾: الفائِزون."],[6,6,"﴿كَفَرُواْ﴾: جَحَدُوا ما أُنْزِلَ إليك من ربِّك.\n\n﴿سَوَآءٌ﴾: مُتَساوٍ.\n\n﴿ءَأَنذَرۡتَهُمۡ﴾: أخَوَّفْتَهم، وحَذَّرْتَهم."],[7,7,"﴿خَتَمَ﴾: طَبَعَ عليها، فلا تَعِي خيرًا.\n\n﴿غِشَـٰوَةࣱ﴾: غطاءٌ، فلم يُوَفِّقْهم للهُدى.\n\n﴿عَذَابٌ﴾: نارُ جَهنَّمَ في الآخِرَةِ."],[8,8,"﴿وَمِنَ ٱلنَّاسِ﴾: فريقُ المُنافقين الذين يَقُولون بألسِنَتِهم: صَدَّقْنا، وهم في باطنِهم كاذِبُون."],[9,9,"﴿يُخَـٰدِعُونَ﴾: يُظْهِرُون خِلافَ ما يُضْمِرُون.\n\n﴿وَمَا يَشۡعُرُونَ﴾: وما يُحِسُّون بذلك؛ لفسادِ قُلوبهِم."],[10,10,"﴿مَّرَضࣱ﴾: شكٌّ وفسادٌ."],[11,11,"﴿لَا تُفۡسِدُواْ﴾: بالمعاصِي، وإفشاءِ أسرارِ المؤمنين ومُوالاةِ الكافرين."],[13,13,"﴿ءَامِنُواْ﴾: صَدِّقُوا بقُلوبِكم، وألسنتِكم، وجَوارِحِكم.\n\n﴿ٱلسُّفَهَآءُ﴾: ضعافُ العقولِ والرأيِ، يَعْنُون بهم الصَّحابةَ.\n\n﴿لَّا يَعۡلَمُونَ﴾: ما هم فيه مِنَ الخُسرانِ."],[14,14,"﴿شَيَـٰطِينِهِمۡ﴾: زُعَمائِهم.\n\n﴿مُسۡتَهۡزِءُونَ﴾: مُسْتَخِفُّون بالمؤمنين، ساخرُون منهم."],[15,15,"﴿وَيَمُدُّهُمۡ﴾: يُمْهِلُهم.\n\n﴿طُغۡيَـٰنِهِمۡ﴾: ضَلالَتِهم.\n\n﴿يَعۡمَهُونَ﴾: يَتَردَّدُون."],[16,16,"﴿ٱشۡتَرَوُاْ ٱلضَّلَـٰلَةَ بِٱلۡهُدَىٰ﴾: استبدَلُوا الكفرَ بالإيمانِ."],[17,17,"﴿مَثَلُهُمۡ﴾: شَبَهُ المنافقين.\n\n﴿ٱسۡتَوۡقَدَ﴾: أوقَدَ.\n\n﴿أَضَآءَتۡ﴾: سَطَعَتْ وأنارَتْ."],[18,18,"﴿صُمُّۢ﴾: عَنْ سَماعِ الحقِّ سماعَ تَدَبُّر، والصَّمَمُ: الانسدادُ.\n\n﴿بُكۡمٌ﴾: عن النُّطقِ بالحق، والبُكْمُ: الخُرْسُ.\n\n﴿عُمۡيࣱ﴾: عَنْ إبصارِ نورِ الهدايةِ.\n\n﴿لَا يَرۡجِعُونَ﴾: لا يعُودون إلى الإيمانِ."],[19,19,"﴿أَوۡ﴾: هذا شَبَهُ فريقٍ آخرَ من المنافقين الذين يَظْهَرُ لهم الحقُّ تارةً، ويَشُكُّون فيه تارة.\n\n﴿كَصَيِّبࣲ﴾: الصَّيِّب: المَطَرُ الشَّديدُ، والمعنى: كأصحابِ صَيِّبٍ.\n\n﴿ٱلصَّوَ ٰ⁠عِقِ﴾: جَمْعُ صاعِقَةٍ، وهي العذابُ المُهْلِكُ المُحْرِقُ.\n\n﴿مُحِيطُۢ بِٱلۡكَـٰفِرِينَ﴾: لا يَفُوتونه، ولا يُعْجِزُونه."],[20,20,"﴿يَكَادُ﴾: يُقارِبُ.\n\n﴿يَخۡطَفُ﴾: يَسْلُبُ من شِدَّةِ لَمَعانِه.\n\n﴿قَامُواْ﴾: وقَفُوا في أماكنِهم مُتَحَيِّرين."],[21,21,"﴿لَعَلَّكُمۡ تَتَّقُونَ﴾: لتَتَّقُوه بطاعَتِه."],[22,22,"﴿جَعَلَ﴾: صَيَّر.\n\n﴿فِرَ ٰ⁠شࣰا﴾: بسِاطًا تَسْهُلُ حياتُكم عليه.\n\n﴿أَندَادࣰا﴾: نُظَراءَ في العبادةِ.\n\n﴿تَعۡلَمُونَ﴾: تَعْلَمُون تَفَرُّدَه بالخَلْقِ والرِّزقِ، واستحقاقَه العبوديةَ."],[23,23,"﴿رَيۡبࣲ﴾: شكٍ.\n\n﴿مِّن مِّثۡلِهِۦ﴾: تُماثِلُ سورةً منه.\n\n﴿شُهَدَآءَكُم﴾: أعوانَكم الذين يَشْهدون لكم."],[24,24,"﴿لَن تَفۡعَلُواْ﴾: مستقبلًا.\n\n﴿وَقُودُهَا﴾: حَطَبُها.\n\n﴿أُعِدَّتۡ﴾: هُيِّئَتْ."],[25,25,"﴿وَبَشِّرِ﴾: أخبِرْهم بما يَسُرُّهم.\n\n﴿مِن تَحۡتِهَا﴾: من تحتِ قُصُورِ الجنّاتِ العاليةِ وأشجارِها الظَّليلةِ.\n\n﴿مِن قَبۡلُ﴾: في الدُّنيا.\n\n﴿مُتَشَـٰبِهࣰا﴾: وجَدُوا طَعمًا جديدًا، وإنْ تَشابَه مع سابقِه.\n\n﴿مُّطَهَّرَةࣱ﴾: من الدَّنَسِ الحِسِّي كالَحيْضِ، والمعنويِّ كالكَذِبِ."],[26,26,"﴿لَا يَسۡتَحۡيِۦٓ﴾: من الحقِّ أنَ يذْكُرَ شيئًا مّا، صغيرًا أو كبيرًا.\n\n﴿فَمَا فَوۡقَهَا﴾: فما هو أكبرُ منها.\n\n﴿ٱلۡفَـٰسِقِينَ﴾: الخارجين عن طاعةِ الله."],[27,27,"﴿يَنقُضُونَ﴾: يَنْكُثون.\n\n﴿عَهۡدَ ٱللَّهِ﴾: العهدَ الذي أخذه عليهم بالتوحيدِ والطّاعةِ.\n\n﴿مِنۢ بَعۡدِ مِيثَـٰقِهِۦ﴾: مِن بعدِ تأكيدِه باليمينِ."],[28,28,"﴿أَمۡوَ ٰ⁠تࣰا﴾: عَدَمًا غيرَ مخلوقِين.\n\n﴿فَأَحۡيَـٰكُمۡ﴾: فأنشأكم بَشَرًا سويًّا.\n\n﴿يُحۡيِيكُمۡ﴾: يوَم الَبْعثِ."],[29,29,"﴿ٱسۡتَوَىٰٓ إِلَى ٱلسَّمَآءِ﴾: ارتفعَ وقَصَدَ إلى خَلْق السمواتِ، وتقديرِ ما في كلِّ واحدةٍ.\n\n﴿فَسَوَّىٰهُنَّ﴾: خَلَقَهُنَّ مُسْتَوِياتٍ، ودبَّرَهُنَّ."],[30,30,"﴿خَلِيفَةࣰ﴾: قومًا يَخْلُف بعضُهم بعضًا لعِمارةِ الأرضِ.\n\n﴿يَسۡفِكُ ٱلدِّمَآءَ﴾: يُريقُها بغيرِ حَقٍّ.\n\n﴿نُسَبِّحُ بِحَمۡدِكَ﴾: نُنَزِّهُك التنزيهَ اللائقَ.\n\n﴿وَنُقَدِّسُ لَكَ﴾: نُمَجِّدُك، ونُطَهِّرُ ذِكْرَك عَمّا لا يَليقُ بك."],[31,31,"﴿ٱلۡأَسۡمَآءَ﴾: أسماءَ الأشياءِ التي يَتَعارَفُ بها الناسُ.\n\n﴿هَـٰٓؤُلَآءِ﴾: الموجوداتِ التي عَلَّمَها آدمَ."],[32,32,"﴿سُبۡحَـٰنَكَ﴾: تَنْزيهًا للهِ."],[33,33,"﴿بِأَسۡمَآئِهِمۡ﴾: بأسماءِ الأشياءِ التي عَجَزُوا عن معرفتِها.\n\n﴿تُبۡدُونَ﴾: تُظْهِرُون.\n\n﴿تَكۡتُمُونَ﴾: تُخْفُون."],[34,34,"﴿ٱسۡجُدُواْ لِـَٔادَمَ﴾: إكرامًا له، وإظهارًا لفَضْلهِ.\n\n﴿أَبَىٰ﴾: تَكَبُّرًا وحَسَدًا.\n\n﴿وَٱسۡتَكۡبَرَ﴾: استعظمَ نفسَه."],[35,35,"﴿رَغَدًا﴾: هنيئًا واسعًا.\n\n﴿ٱلظَّـٰلِمِينَ﴾: المتجاوِزين أمرَ اللِه."],[36,36,"﴿فَأَزَلَّهُمَا ٱلشَّيۡطَـٰنُ عَنۡهَا﴾: فأوْقَعَهما الشيطانُ في الخطيئةِ ليُبْعِدَهما عَنِ الجنةِ.\n\n﴿بَعۡضُكُمۡ لِبَعۡضٍ﴾: آدمُ، وحواءُ، والشيطانُ.\n\n﴿مَتَـٰعٌ﴾: انتفاعٌ، واستمتاعٌ.\n\n﴿إِلَىٰ حِينࣲ﴾: إلى وقتِ انتهاءِ آجالِكم."],[37,37,"﴿كَلِمَـٰتࣲ﴾: ما ألْهمه اللهُ مِن كلماتٍ للتَّوبةِ."],[38,38,"﴿فَلَا خَوۡفٌ﴾: آمِنُون من أهوالِ القيامةِ.\n\n﴿وَلَا هُمۡ يَحۡزَنُونَ﴾: على ما فاتَهم من الدُّنيا."],[40,40,"﴿ٱذۡكُرُواْ نِعۡمَتِيَ﴾: اصطفائي للرُّسُلِ منكم، وإنزالَ الكتبِ عليكم، ونجاتكم من فرعونَ.\n\n﴿وَأَوۡفُواْ بِعَهۡدِيٓ﴾: أتِمُّوا وصِيَّتي لكم بالإيمان بكتبي وبرُسُلي جميعًا.\n\n﴿أُوفِ بِعَهۡدِكُمۡ﴾: ما وعَدْتُكم به من الرحمةِ في الدنيا والآخرةِ."],[41,41,"﴿أَوَّلَ كَافِرِۭ بِهِۦ﴾: بالقرآنِ.\n\n﴿وَلَا تَشۡتَرُواْ بِـَٔايَـٰتِي ثَمَنࣰا قَلِيلࣰا﴾: ولا تَبيعُوا ما آتيكم به من العِلْم بما في كتابِكم من أمرِ محمدٍ ﷺ، بثمَنٍ بَخْس."],[42,42,"﴿وَلَا تَلۡبِسُواْ﴾: ولا تَخْلِطُوا.\n\n﴿وَتَكۡتُمُواْ ٱلۡحَقَّ﴾: وتُخْفُوا صفةَ محمدٍ ﷺ في التوراةِ."],[44,44,"﴿بِٱلۡبِرِّ﴾: بالطاعةِ، والعملِ الصالحِ.\n\n﴿ٱلۡكِتَـٰبَ﴾: التوراةَ."],[45,45,"﴿لَكَبِيرَةٌ﴾: شاقةٌ ثقيلةٌ.\n\n﴿ٱلۡخَـٰشِعِينَ﴾: الخاضِعين لطاعَتهِ."],[46,46,"﴿يَظُنُّونَ﴾: يُوقِنون."],[47,47,"﴿ٱلۡعَـٰلَمِينَ﴾: عالَمِي زمانِكم؛ بكثرةِ الأنبياءِ، وإنزالِ الكتبِ."],[48,48,"﴿يَوۡمࣰا﴾: يومَ القيامةِ.\n\n﴿لَّا تَجۡزِي نَفۡسٌ﴾: لا يُغني أحدٌ عن أحدٍ شيئًا.\n\n﴿عَدۡلࣱ﴾: فِدْيةٌ."],[49,49,"﴿نَجَّيۡنَـٰكُم﴾: نَجَّينا آباءَكم.\n\n﴿يَسۡتَحۡيُونَ نِسَآءَكُمۡ﴾: يَسْتَبْقُونَهُن للخِدْمةِ والامتهانِ.\n\n﴿بَلَآءࣱ﴾: اختبارٌ."],[50,50,"﴿فَرَقۡنَا بِكُمُ ٱلۡبَحۡرَ﴾: فَصَلْنا لكم البحرَ، وجَعَلْنا فيه طُرُقًا يابسةً لعُبورِكم."],[51,51,"﴿ٱتَّخَذۡتُمُ ٱلۡعِجۡلَ﴾: أي مَعبْودًا لكم من دونِ اللهِ."],[53,53,"﴿ٱلۡكِتَـٰبَ﴾: التوراةَ.\n\n﴿ٱلۡفُرۡقَانَ﴾: الفارقَ بينَ الحقِّ والباطلِ."],[54,54,"﴿فَٱقۡتُلُوٓاْ أَنفُسَكُمۡ﴾: بأَنْ يَقْتُلَ بعضُكم بعضًا."],[55,55,"﴿جَهۡرَةࣰ﴾: عِيانًا.\n\n﴿ٱلصَّـٰعِقَةُ﴾: نارٌ مِنَ السماءِ."],[57,57,"﴿ٱلۡغَمَامَ﴾: السَّحابَ.\n\n﴿ٱلۡمَنَّ﴾: شيءٌ يُشْبه الصَّمْغَ، طَعْمُه كالعَسَلِ.\n\n﴿ٱلسَّلۡوَىٰ﴾: طيرٌ يُشْبِهُ السُّمانى."],[58,58,"﴿ٱلۡقَرۡيَةَ﴾: بيتَ المَقْدِسِ.\n\n﴿رَغَدࣰا﴾: هنيئًا.\n\n﴿حِطَّةࣱ﴾: ربَّنا ضَعْ عنا ذُنوبَنا."],[59,59,"﴿رِجۡزࣰا﴾: عذابًا.\n\n﴿يَفۡسُقُونَ﴾: يَخْرُجون عن طاعةِ اللهِ."],[60,60,"﴿ٱسۡتَسۡقَىٰ﴾: سألَ اللهَ أنَ يَسْقِيَ قومَه.\n\n﴿وَلَا تَعۡثَوۡاْ﴾: ولا تُفْرِطُوا في الفسادِ."],[61,61,"﴿وَقِثَّآئِهَا﴾: جَمْعُ قِثّاءَةٍ، وهو نَبْتٌ ثِمارُه تُشْبِهُ الخِيارَ، ولكنه أطولُ منه.\n\n﴿وَفُومِهَا﴾: الحِنْطَةِ.\n\n﴿ٱلَّذِي هُوَ أَدۡنَىٰ﴾: الطعامَ الذي هو أقلُّ قَدْرًا وقيمةً.\n\n﴿مِصۡرࣰا﴾: أيَّ مدينةٍ.\n\n﴿ٱلۡمَسۡكَنَةُ﴾: الفاقَةُ، والحاجَةُ.\n\n﴿وَبَآءُو﴾: رَجَعُوا."],[62,62,"﴿وَٱلَّذِينَ هَادُواْ﴾: اليهودَ.\n\n﴿ٱلصَّـٰبِـِٔينَ﴾: قومٌ بَقُوا على فِطْرتهم، ولا دينَ مقرَّرٌ لهم.\n\n﴿وَلَا هُمۡ يَحۡزَنُونَ﴾: على ما فاتَهُمْ من أمورِ الدُّنيا."],[63,63,"﴿مِيثَـٰقَكُمۡ﴾: العهدَ المؤكَّدَ منكم بالإيمان.\n\n﴿ٱلطُّورَ﴾: جبلَ سيناءَ.\n\n﴿مَآ ءَاتَيۡنَـٰكُم﴾: الكتابَ الذي أعطيناكم وهو التَّوراةُ.\n\n﴿بِقُوَّةࣲ﴾: بجِدٍّ."],[64,64,"﴿تَوَلَّيۡتُم﴾: عَصَيْتُم."],[65,65,"﴿فِي ٱلسَّبۡتِ﴾: في هذا اليومِ الذي أُمِرُوا بتعظيمِه.\n\n﴿خَـٰسِـِٔينَ﴾: أذِلَّةً صاغِرين."],[66,66,"﴿نَكَـٰلࣰا﴾: عقوبةً.\n\n﴿لِّمَا بَيۡنَ يَدَيۡهَا﴾: من الذنوبِ."],[67,67,"﴿هُزُوࣰا﴾: مَوْضِعَ سُخْرِيَةٍ واستِخْفافٍ."],[68,68,"﴿فَارِضࣱ﴾: المُسِنَّةُ الهَرِمَةُ.\n\n﴿بِكۡرٌ﴾: الصغيرةُ الفتيةُ.\n\n﴿عَوَانُۢ﴾: متوسطةٌ بين البِكْرِ والهَرِمَةِ."],[69,69,"﴿فَاقِعࣱ لَّوۡنُهَا﴾: شديدةُ الصُّفْرَةِ."],[70,70,"﴿تَشَـٰبَهَ﴾: التبسَ."],[71,71,"﴿لَّا ذَلُولࣱ تُثِيرُ ٱلۡأَرۡضَ﴾: غيرُ مُذَلَّلَةٍ للعَمَلِ في حِراثةِ الأرضِ.\n\n﴿ٱلۡحَرۡثَ﴾: الزرعَ.\n\n﴿مُسَلَّمَةࣱ﴾: خاليةٌ مِنَ العيوبِ.\n\n﴿لَّا شِيَةَ فِيهَا﴾: لا لونَ فيها يخالِفُ لونَ جِلْدِها."],[72,72,"﴿فَٱدَّ ٰ⁠رَ ٰ⁠ـٔتُمۡ﴾: فاختلفتم، كلٌّ يَدْفَعُ عن نفسِه تُهْمَةَ القتلِ.\n\n﴿مُخۡرِجࣱ﴾: مُظْهِرٌ."],[73,73,"﴿بِبَعۡضِهَا﴾: بجُزْءٍ مِنَ البقرةِ المذبوحةِ.\n\n﴿ءَايَـٰتِهِۦ﴾: معجزاتهِ، وحُجَجَه."],[75,75,"﴿أَن يُؤۡمِنُواْ لَكُمۡ﴾: أن يُصَدِّقَ اليهودُ بدينِكم.\n\n﴿كَلَـٰمَ ٱللَّهِ﴾: التوراةَ.\n\n﴿يُحَرِّفُونَهُۥ﴾: يَصْرِفُونه عن معناه.\n\n﴿عَقَلُوهُ﴾: فَهِمُوه بعقولهِم على الوجهِ الصَّحيحِ."],[76,76,"﴿بِمَا فَتَحَ﴾: بما بَيَّنَ اللهُ لكم في التوراةِ من أمْرِ محمدٍ ﷺ.\n\n﴿لِيُحَآجُّوكُم﴾: لتكونَ لهم الحُجَّةُ عليكم في الآخرةِ."],[78,78,"﴿وَمِنۡهُمۡ أُمِّيُّونَ﴾: ومن اليهودِ طائفةٌ يَجْهَلُون القراءةَ والكتابةَ.\n\n﴿ٱلۡكِتَـٰبَ﴾: التوراةَ وما فيها من صفاتِ محمدٍ ﷺ.\n\n﴿أَمَانِيَّ﴾: أكاذيبَ."],[79,79,"﴿فَوَيۡلࣱ﴾: فوعيدٌ شديدٌ.\n\n﴿ثَمَنࣰا قَلِيلࣰا﴾: عَرَضًا مِنَ الدنيا."],[80,80,"﴿عَهۡدࣰا﴾: ميثاقًا بهذا الزعمِ."],[81,81,"﴿سَيِّئَةࣰ﴾: شِرْكًا."],[83,83,"﴿مِيثَـٰقَ﴾: العهدَ المؤكَّدَ.\n\n﴿ٱلۡيَتَـٰمَىٰ﴾: الأولادِ الذين ماتَ آباؤُهم وهم دونَ البُلوغِ.\n\n﴿وَٱلۡمَسَـٰكِينِ﴾: الذين لا يَمْلِكُون ما يَكْفيهم.\n\n﴿حُسۡنࣰا﴾: أطيبَ الكلامِ.\n\n﴿مُّعۡرِضُونَ﴾: مستمرُّون في تكذيبِهم."],[84,84,"﴿مِيثَـٰقَكُمۡ﴾: العهدَ المؤكَّدَ في التَّوراة.\n\n﴿أَقۡرَرۡتُمۡ﴾: اعترفتُمْ."],[85,85,"﴿هَـٰٓؤُلَآءِ﴾: يا هؤلاءِ.\n\n﴿تَظَـٰهَرُونَ عَلَيۡهِم﴾: يتَقَوّى كلٌّ منكم على إخوانِه بالأعداءِ.\n\n﴿تُفَـٰدُوهُمۡ﴾: تُحَرِّرُوهم مِنَ الأَسْرِ بدَفْعِ الفِدْيَةِ.\n\n﴿ٱلۡكِتَـٰبِ﴾: التوراةِ."],[86,86,"﴿ٱشۡتَرَوُاْ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا﴾: استحَبُّوها."],[87,87,"﴿وَقَفَّيۡنَا﴾: أتْبَعْنا بعضَهم خَلْفَ بعضٍ.\n\n﴿ٱلۡبَيِّنَـٰتِ﴾: المعجزاتِ الواضحاتِ.\n\n﴿بِرُوحِ ٱلۡقُدُسِ﴾: جبريلَ."],[88,88,"﴿وَقَالُواْ﴾: وقال بنو إسرائيلَ.\n\n﴿غُلۡفُۢ﴾: مُغَطّاةٌ لا يَنْفُذُ إليها قولُك."],[89,89,"﴿جَآءَهُمۡ﴾: جاء اليهودَ.\n\n﴿كِتَـٰبࣱ﴾: هو القرآنُ الكريمُ.\n\n﴿مُصَدِّقࣱ﴾: موافِقٌ.\n\n﴿لِّمَا مَعَهُمۡ﴾: من التوراة.\n\n﴿مِن قَبۡلُ﴾: مِن قَبْلِ بِعْثَةِ محمدٍ ﷺ.\n\n﴿يَسۡتَفۡتِحُونَ﴾: يَسْتَنْصِرُون بالنبيِّ الذي ينتظرونه."],[90,90,"﴿بِئۡسَمَا﴾: قَبُحَ.\n\n﴿ٱشۡتَرَوۡاْ﴾: باعوا.\n\n﴿بَغۡيًا﴾: ظُلمًا وحَسَدًا.\n\n﴿أَن يُنَزِّلَ﴾: من أجْلِ أن يُنَزِّلَ.\n\n﴿مِن فَضۡلِهِۦ﴾: هو تنزيلُ القرآنِ على محمدٍ ﷺ.\n\n﴿فَبَآءُو﴾: فرَجَعُوا.\n\n﴿بِغَضَبٍ﴾: بغَضَبِ اللهِ بسببِ تكذيبِهم للنبيَّ ﷺ.\n\n﴿عَلَىٰ غَضَبࣲ﴾: بعد غضبهِ بسببِ تحريفِهم للتوراةِ."],[91,91,"﴿بِمَا وَرَآءَهُۥ﴾: بما أنزل اللهُ بعدَ التوراةِ.\n\n﴿لِّمَا مَعَهُمۡ﴾: من التَّوراةِ."],[92,92,"﴿بِٱلۡبَيِّنَـٰتِ﴾: بالمُعْجِزاتِ الواضحاتِ.\n\n﴿ٱتَّخَذۡتُمُ ٱلۡعِجۡلَ﴾: أي مَعْبودًا."],[93,93,"﴿مِيثَـٰقَكُمۡ﴾: العهدَ المؤكَّدَ.\n\n﴿ٱلطُّورَ﴾: جبلَ الطُّورِ.\n\n﴿وَأُشۡرِبُواْ فِي قُلُوبِهِمُ ٱلۡعِجۡلَ﴾: امتزجَ حُبُّ عبادَةِ العِجْلِ بقُلوبهِم."],[94,94,"﴿خَالِصَةࣰ﴾: خاصةً بكم.\n\n﴿فَتَمَنَّوُاْ ٱلۡمَوۡتَ﴾: ادْعُوا بالموتِ على الكاذبِ."],[95,95,"﴿قَدَّمَتۡ﴾: كَسَبَتْ."],[96,96,"﴿بِمُزَحۡزِحِهِۦ﴾: مُبْعِدِه، ومُنْجِيه.\n\n﴿أَن يُعَمَّرَ﴾: طولُ العُمْرِ."],[97,97,"﴿مَن كَانَ﴾: هم اليهودُ الزاعمون أنّ جبريلَ عَدُوٌّ لهم.\n\n﴿لِّمَا بَيۡنَ يَدَيۡهِ﴾: لما قبلَه مِنَ الكُتُب."],[99,99,"﴿بَيِّنَـٰتࣲ﴾: علاماتٍ دالّاتٍ على نُبُوَّتك.\n\n﴿ٱلۡفَـٰسِقُونَ﴾: الخارجون عن دينِ اللهِ."],[100,100,"﴿عَهۡدࣰا﴾: هو الميثاقُ الذي أعطاه اليهودُ رَبَّهم.\n\n﴿نَّبَذَهُۥ﴾: نَقَضَه."],[102,102,"﴿مَا تَتۡلُواْ ٱلشَّيَـٰطِينُ﴾: ما تُحَدِّثُ به الشياطينُ السَّحَرَةَ.\n\n﴿عَلَىٰ مُلۡكِ﴾: على عَهْدِ.\n\n﴿وَمَآ أُنزِلَ﴾: وكذلك اتَّبَعَ اليهودُ السِّحْرَ الذي أُنْزِلَ على الملَكَين. وقد عَلَّم اللهُ الملَكَين السِّحْرَ ابتلاءً منه.\n\n﴿فِتۡنَةࣱ﴾: ابتلاءٌ يَختبرُ اللهُ بهما عبادَه، وهو تعليمُ إنذارٍ من السِّحْرِ، لا تعليمُ دعوةٍ.\n\n﴿فَلَا تَكۡفُرۡ﴾: بتعَلُّمِ السِّحْرِ، وطاعةِ الشياطين.\n\n﴿ٱشۡتَرَىٰهُ﴾: اختار السِّحْرَ، واستحَبَّه.\n\n﴿خَلَـٰقࣲ﴾: نصيبٍ في الخيرِ."],[103,103,"﴿لَمَثُوبَةࣱ﴾: ثوابُ اللهِ."],[104,104,"﴿رَ ٰ⁠عِنَا﴾: أي: سَمْعَك، فافهَمْ عنا، وأفْهِمْنا.\n\n﴿ٱنظُرۡنَا﴾: انظُرْ إلينا وتَعَهَّدْنا."],[105,105,"﴿يَخۡتَصُّ﴾: يُؤْثِرُ."],[106,106,"﴿مَا نَنسَخۡ﴾: ما نُبَدِّلْ.\n\n﴿نُنسِهَا﴾: نَمْحُها مِنَ القُلوبِ."],[107,107,"﴿وَلِيࣲّ﴾: قَيِّمٍ بأمرِكم."],[108,108,"﴿سَوَآءَ ٱلسَّبِيلِ﴾: طريقَ اللهِ المستقيم."],[109,109,"﴿يَرُدُّونَكُم﴾: يُرْجِعُونكم.\n\n﴿بِأَمۡرِهِۦٓ﴾: بحُكْمِه فيهم."],[110,110,"﴿وَمَا تُقَدِّمُواْ﴾: وما تَعْمَلُوا مِن عَمَلٍ."],[111,111,"﴿أَمَانِيُّهُمۡ﴾: أوهامُهم الفاسدةُ.\n\n﴿بُرۡهَـٰنَكُمۡ﴾: حُجَّتَكم."],[112,112,"﴿أَسۡلَمَ﴾: أخلَصَ لطاعَتِه.\n\n﴿وَهُوَ مُحۡسِنࣱ﴾: مُتَّبِعٌ للرسولِ ﷺ."],[113,113,"﴿عَلَىٰ شَيۡءࣲ﴾: أي: من الدِّينِ الصَّحيحِ.\n\n﴿وَهُمۡ يَتۡلُونَ ٱلۡكِتَـٰبَ﴾: يَقْرَؤون التوراةَ والإنجيلَ، وفيهما الإيمانُ بالأنبياءِ جميعًا.\n\n﴿ٱلَّذِينَ لَا يَعۡلَمُونَ﴾: هم مُشْرِكو العربِ وغيرُهم.\n\n﴿يَحۡكُمُ﴾: يَفْصِلُ، ويَقْضي."],[114,114,"﴿وَمَنۡ أَظۡلَمُ﴾: لا أحدَ أظلمُ.\n\n﴿خِزۡيࣱ﴾: ذِلَّةٌ وهَوانٌ."],[115,115,"﴿تُوَلُّواْ﴾: تَتَوَجَّهُوا.\n\n﴿فَثَمَّ وَجۡهُ﴾: فإنكم مُبْتَغُون وجْهَه.\n\n﴿وَ ٰ⁠سِعٌ﴾: واسعُ الرحمةِ بعبادِه."],[116,116,"﴿سُبۡحَـٰنَهُۥ﴾: تَنَزَّهَ عن هذا الباطلِ.\n\n﴿قَـٰنِتُونَ﴾: خاضِعُون له، مُطيعون."],[117,117,"﴿بَدِيعُ﴾: مُبْدِعٌ على غيرِ مثالٍ سَبَقَ."],[118,118,"﴿لَوۡلَا﴾: هَلّا.\n\n﴿ءَايَةࣱ﴾: مُعْجزةٌ.\n\n﴿تَشَـٰبَهَتۡ﴾: في الكُفرِ والعِنادِ.\n\n﴿يُوقِنُونَ﴾: يُصَدِّقُون ويَتَّبِعُون الرسولَ ﷺ."],[119,119,"﴿بَشِيرࣰا﴾: للمؤمنين بخَيْرَي الدُّنيا و الآخرةِ.\n\n﴿وَنَذِيرࣰا﴾: ومُخَوِّفًا للمعانِدِين بالعذابِ."],[120,120,"﴿مِلَّتَهُمۡ﴾: دينَهم.\n\n﴿هُوَ ٱلۡهُدَىٰ﴾: الدِّينُ الصحيحُ.\n\n﴿وَلِيࣲّ﴾: قريبٍ يمنعُك من عذابِ اللهِ."],[121,121,"﴿حَقَّ تِلَاوَتِهِۦٓ﴾: يَتَّبِعُونه حَقَّ اتِّباعِه."],[122,122,"﴿ٱلۡعَـٰلَمِينَ﴾: عالَمِي زَمانِكم بكثرةِ الأنبياءِ، وإنزالِ الكُتُبِ."],[123,123,"﴿لَّا تَجۡزِي﴾: لا تُغْني.\n\n﴿عَدۡلࣱ﴾: فِدْيَةٌ تُنْجِيها من العذابِ.\n\n﴿شَفَـٰعَةࣱ﴾: وساطةٌ في حُصولِ النفعِ."],[124,124,"﴿ٱبۡتَلَىٰٓ﴾: اختبرَ.\n\n﴿بِكَلِمَـٰتࣲ﴾: بما شَرَع له من تعاليمَ.\n\n﴿فَأَتَمَّهُنَّ﴾: فأدّاهن على الوجهِ الأكمَلِ.\n\n﴿إِمَامࣰا﴾: قُدوةً للناس.\n\n﴿وَمِن ذُرِّيَّتِي﴾: واجعَلْ بعضَ نَسْلي مَن يُقْتَدى به.\n\n﴿عَهۡدِي﴾: الإمامةُ في الدِّين."],[125,125,"﴿ٱلۡبَيۡتَ﴾: الكعبةَ.\n\n﴿مَثَابَةࣰ﴾: مَرْجِعًا ومَجْمَعًا للناسِ.\n\n﴿مَّقَامِ إِبۡرَ ٰ⁠هِـۧمَ﴾: الحَجَرِ الذي وقَفَ عليه.\n\n﴿وَعَهِدۡنَآ﴾: وأَوْحَينا.\n\n﴿ٱلۡعَـٰكِفِينَ﴾: المقيمينَ فيه للعبادةِ."],[126,126,"﴿أُمَتِّعُهُۥ﴾: فأَرْزُقُه في حياتهِ.\n\n﴿أَضۡطَرُّهُۥٓ﴾: أُلْجِئُه.\n\n﴿ٱلۡمَصِيرُ﴾: المَرْجِعُ."],[127,127,"﴿ٱلۡقَوَاعِدَ مِنَ ٱلۡبَيۡتِ﴾: أُسُس الكعبةِ التي تنهضُ عليها."],[128,128,"﴿مُسۡلِمَيۡنِ لَكَ﴾: منقادَيْن لأحكامِك.\n\n﴿مُّسۡلِمَةࣰ﴾: منقادةً.\n\n﴿وَأَرِنَا مَنَاسِكَنَا﴾: بَصِّرْنا بمعالِم عِبادتِنا."],[129,129,"﴿فِيهِمۡ﴾: في هذه الأمةِ.\n\n﴿مِّنۡهُمۡ﴾: من ذريةِ إسماعيلَ.\n\n﴿ٱلۡكِتَـٰبَ وَٱلۡحِكۡمَةَ﴾: القرآنَ، والسُنَّةَ.\n\n﴿وَيُزَكِّيهِمۡ﴾: يُطَهِّرُهم من الشِّرْكِ، وسوءِ الأخلاقِ."],[130,130,"﴿يَرۡغَبُ عَن مِّلَّةِ إِبۡرَ ٰ⁠هِـۧمَ﴾: يُعْرِضُ عن دينِه.\n\n﴿سَفِهَ نَفۡسَهُۥ﴾: جَهِلَتْ نَفْسُه ما ينفعُها.\n\n﴿ٱصۡطَفَيۡنَـٰهُ﴾: اختَرناه."],[131,131,"﴿أَسۡلِمۡ﴾: أخْلِصْ نفسَك لله."],[132,132,"﴿ٱصۡطَفَىٰ﴾: اختارَ."],[133,133,"﴿كُنتُمۡ﴾: أيُّها اليهودُ.\n\n﴿شُهَدَآءَ﴾: حاضِرِين، فلا تَدَّعُوا الأباطيلَ.\n\n﴿مُسۡلِمُونَ﴾: مُنْقادُون، خاضِعُون."],[134,134,"﴿خَلَتۡ﴾: مَضَتْ.\n\n﴿مَا كَسَبَتۡ﴾: ما عَمِلَتْ."],[135,135,"﴿تَهۡتَدُواْ﴾: تُصِيبوا الحقَّ.\n\n﴿بَلۡ مِلَّةَ إِبۡرَ ٰ⁠هِـۧمَ﴾: بل الهدايةُ أن نتَّبعَ دينَ إبراهيمَ.\n\n﴿حَنِيفࣰا﴾: مائلًا عن الباطلِ."],[136,136,"﴿وَٱلۡأَسۡبَاطِ﴾: هم الأنبياءُ من ولَدِ يعقوبَ في قبائلِ بني إسرائيلَ الاثنتي عَشْرَةَ.\n\n﴿مُسۡلِمُونَ﴾: خاضعون."],[137,137,"﴿تَوَلَّوۡاْ﴾: أعْرَضُوا.\n\n﴿شِقَاقࣲ﴾: خلافٍ شديدٍ.\n\n﴿فَسَيَكۡفِيكَهُمُ ٱللَّهُ﴾: سيَكْفيك شَرَّهم."],[138,138,"﴿صِبۡغَةَ ٱللَّهِ﴾: الزَمُوا دينَ اللهِ الإسلامَ.\n\n﴿صِبۡغَةࣰ﴾: دِينًا."],[139,139,"﴿أَتُحَآجُّونَنَا﴾: أتجادِلُوننا وتخاصِمُوننا؟\n\n﴿مُخۡلِصُونَ﴾: لا نعبدُ أحدًا غيره."],[140,140,"﴿وَمَنۡ أَظۡلَمُ﴾: لا أحدَ أظلمُ.\n\n﴿كَتَمَ﴾: أخْفى، وادَّعى خِلافَها."],[141,141,"﴿خَلَتۡ﴾: مَضَتْ.\n\n﴿كَسَبَتۡ﴾: عَمِلَتْ."],[142,142,"﴿ٱلسُّفَهَآءُ﴾: الجُهّالُ وضِعافُ العقولِ، وهم اليهودُ.\n\n﴿مَا وَلَّىٰهُمۡ﴾: أيُّ شيءٍ صَرَفَ المسلمين؟\n\n﴿عَن قِبۡلَتِهِمُ﴾: عن بيتِ المقْدِسِ، وهي قِبلة المسلمين أولَ الإسلامِ.\n\n﴿صِرَ ٰ⁠طࣲ﴾: طريقٍ."],[143,143,"﴿وَسَطࣰا﴾: عُدُولًا خِيارًا، لا إفراطَ عندكم، ولا تفْريطَ.\n\n﴿لِّتَكُونُواْ شُهَدَآءَ﴾: لتَشْهَدُوا على الأممِ في الآخرةِ أنّ رُسُلَهم بَلَّغُوا.\n\n﴿شَهِيدࣰا﴾: يشهدُ أنه بَلَّغَ الرسالةَ إلى أمَّتِه.\n\n﴿ٱلَّتِي كُنتَ عَلَيۡهَآ﴾: التي صَرَفْناك عنها إلى الكعبةِ.\n\n﴿يَنقَلِبُ عَلَىٰ عَقِبَيۡهِ﴾: يَرْتَدُّ عن دينِه.\n\n﴿وَإِن كَانَتۡ﴾: وإنّ تحويلَ الِقْبلَةِ.\n\n﴿لَكَبِيرَةً﴾: لَثقيلةً شاقةً.\n\n﴿لِيُضِيعَ إِيمَـٰنَكُمۡ﴾: يُبْطِلَ صلاتَكم إلى القِبْلَةِ السّابقةِ."],[144,144,"﴿فِي ٱلسَّمَآءِ﴾: أي: انتظارًا للوَحْي في شأنِ القِبْلَةِ.\n\n﴿فَلَنُوَلِّيَنَّكَ﴾: فَلنُوَجِّهَنّك.\n\n﴿فَوَلِّ وَجۡهَكَ﴾: اصرِفْ وجْهَك.\n\n﴿شَطۡرَ﴾: جِهَةَ.\n\n﴿فَوَلُّواْ﴾: فَتَوجَّهُوا.\n\n﴿أَنَّهُ ٱلۡحَقُّ﴾: أن تحويلَكَ إلى الكعبةِ هو الثابتُ في كُتُبهِم."],[145,145,"﴿ءَايَةࣲ﴾: حُجَّةٍ.\n\n﴿ٱلظَّـٰلِمِينَ﴾: لأنفسِهم، المخالِفِين لأمرِ ربِّهم."],[146,146,"﴿ٱلَّذِينَ ءَاتَيۡنَـٰهُمُ ٱلۡكِتَـٰبَ﴾: هم أحبارُ اليهود، وعلماءُ النَّصارى.\n\n﴿يَعۡرِفُونَهُۥ﴾: يَعْرِفُون محمدًا، أو يَعْرِفُون أن البيتَ الحرامَ قِبْلَتُهم، وقبلةُ الأنبياءِ السابقين."],[147,147,"﴿ٱلۡمُمۡتَرِينَ﴾: الشّاكِّين."],[148,148,"﴿وَلِكُلࣲّ وِجۡهَةٌ﴾: ولكلِّ أهلِ دينٍ قبلةٌ.\n\n﴿هُوَ مُوَلِّيهَا﴾: مُتَوَجِّهٌ إليها في صلاتِه.\n\n﴿فَٱسۡتَبِقُواْ﴾: فبادِرُوا، وسارِعُوا.\n\n﴿يَأۡتِ بِكُمُ﴾: يومَ القيامةِ."],[149,149,"﴿فَوَلِّ وَجۡهَكَ﴾: تَوَجَّهْ.\n\n﴿شَطۡرَ﴾: نَحْوَ.\n\n﴿وَإِنَّهُۥ﴾: وإنّ تَوَجُّهَك إليه."],[150,150,"﴿حُجَّةٌ﴾: هي قولُهم حينَ تَوَجَّهَ إلى المسجدِ الحرامِ: اشتاقَ إلى دينِ قومِه.\n\n﴿ٱلَّذِينَ ظَلَمُواْ﴾: هم مشركُو قريشٍ، أو المعاندون أهلُ الكتابِ، فسيَبْقَون على جِدالهم وعِنادهِم.\n\n﴿وَلِأُتِمَّ نِعۡمَتِي﴾: باختيار أكملِ الشَّرائعِ لكم."],[151,151,"﴿كَمَآ أَرۡسَلۡنَا﴾: كما أنَعمْنا عليكم باستقبالِ الكعبةِ أرسَلْنا.\n\n﴿يُزَكِّيكُمۡ﴾: يُطَهِّرُكم من الشِّرك، وسوءِ الأخلاقِ.\n\n﴿ٱلۡحِكۡمَةَ﴾: السُّنَّةَ."],[152,152,"﴿فَٱذۡكُرُونِيٓ﴾: بالطاعةِ.\n\n﴿أَذۡكُرۡكُمۡ﴾: بالثَّوابِ والمغفرةِ."],[154,154,"﴿أَحۡيَآءࣱ﴾: حياةً خاصةً بهم في قُبورِهم.\n\n﴿لَّا تَشۡعُرُونَ﴾: لا تُحِسُّون بهذه الحياةِ."],[155,155,"﴿وَلَنَبۡلُوَنَّكُم﴾: ولَنَخْتَبِرَنَّكم."],[156,156,"﴿إِنَّا لِلَّهِ﴾: إنّا عَبيدٌ له، مُدَبَّرُون بتصريفِه."],[157,157,"﴿صَلَوَ ٰ⁠تࣱ﴾: مغفرةٌ، وثناءٌ حَسَنٌ."],[158,158,"﴿شَعَآئِرِ ٱللَّهِ﴾: منْ معالمِ دينِه، وأعلامِ مَناسِكِه.\n\n﴿حَجَّ ٱلۡبَيۡتَ﴾: قَصَدَه للحجِّ أو العمرةِ.\n\n﴿فَلَا جُنَاحَ﴾: فلا حَرَجَ ولا إثمَ، بل يجبُ السَّعْيُ.\n\n﴿يَطَّوَّفَ بِهِمَا﴾: يَسْعى بينهما.\n\n﴿تَطَوَّعَ﴾: فَعَلَ الطاعةَ مِن نفسِه."],[159,159,"﴿يَكۡتُمُونَ﴾: يُخْفُون. وهم أحبارُ اليهودِ، وعلماءُ النصارى، وكلُّ مَن كَتَمَ الحقَّ.\n\n﴿ٱلۡبَيِّنَـٰتِ﴾: الآياتِ الواضحاتِ الدالَّةِ على نُبُوَّةِ محمدٍ ﷺ.\n\n﴿بَيَّنَّـٰهُ﴾: أظْهَرْناه في التوراةِ والإنجيلِ."],[160,160,"﴿وَأَصۡلَحُواْ﴾: ما أفْسَدُوه."],[161,161,"﴿لَعۡنَةُ ٱللَّهِ﴾: الطَّرْدُ مِن رحمته."],[162,162,"﴿خَـٰلِدِينَ فِيهَا﴾: دائمِين في اللَّعْنَةِ والنارِ.\n\n﴿يُنظَرُونَ﴾: يُمْهَلُون لكي يَعْتَذِرُوا."],[164,164,"﴿ٱخۡتِلَـٰفِ ٱلَّيۡلِ وَٱلنَّهَارِ﴾: تعاقُبِهما.\n\n﴿ٱلۡفُلۡكِ﴾: السُّفُن.\n\n﴿بَعۡدَ مَوۡتِهَا﴾: بعد قَحْطِها وجَفافِها.\n\n﴿بَثَّ﴾: نَشَر، وفَرَّقَ.\n\n﴿دَآبَّةࣲ﴾: كلِّ ما دَبَّ على وجهِ الأرضِ.\n\n﴿وَتَصۡرِيفِ ٱلرِّيَـٰحِ﴾: تَوْجيهِها، وهُبوبِها، وفْقَ ما يريدُ.\n\n﴿ٱلۡمُسَخَّرِ﴾: المُسَيَّرِ.\n\n﴿لَـَٔايَـٰتࣲ﴾: لَعلاماتٍ ودَلالاتٍ على قُدْرةِ اللهِ."],[165,165,"﴿أَندَادࣰا﴾: نُظَراءَ كالأصنامِ والأولياءِ.\n\n﴿كَحُبِّ ٱللَّهِ﴾: يَمْنحونهم من التعظيم ما لا يَليقُ إلا باللهِ.\n\n﴿إِذۡ يَرَوۡنَ ٱلۡعَذَابَ أَنَّ ٱلۡقُوَّةَ لِلَّهِ جَمِيعࣰا﴾: أي: ليعلَمُوا حين يَرَوْنَ عذابَ جهنَّمَ أن اللهَ هو المتفرِّدُ بالقوةِ."],[166,166,"﴿ٱلَّذِينَ ٱتُّبِعُواْ﴾: هم الرؤساءُ.\n\n﴿ٱلۡأَسۡبَابُ﴾: الصِّلاتُ من القَرابَةِ والأَتْباعِ وغيرِ ذلك."],[167,167,"﴿كَرَّةࣰ﴾: عودةً إلى الدنيا.\n\n﴿كَذَ ٰ⁠لِكَ﴾: أي: كما أراهم عذابه، يُريهم أعمالَهم الفاسدةَ.\n\n﴿حَسَرَ ٰ⁠تٍ﴾: نَداماتٍ."],[168,168,"﴿خُطُوَ ٰ⁠تِ ٱلشَّيۡطَـٰنِ﴾: طُرُقَه، وآثارَه."],[169,169,"﴿وَٱلۡفَحۡشَآءِ﴾: المعصيةِ البالغةِ القُبْحِ."],[170,170,"﴿أَلۡفَيۡنَا﴾: وجَدْنا.\n\n﴿أَوَلَوۡ كَانَ ءَابَآؤُهُمۡ لَا يَعۡقِلُونَ﴾: أي: يَتَّبِعُونهم؟"],[171,171,"﴿وَمَثَلُ ٱلَّذِينَ كَفَرُواْ﴾: صِفَتُهم مع مَن يَدْعُوهم إلى الهُدى.\n\n﴿ٱلَّذِي يَنۡعِقُ﴾: هو الرّاعِي الذي يَصيحُ بالبهائمِ، ويَزْجُرُها، وهي لا تَفْهَمُ معنى كلامِه، وإنما تَسْمَعُ صوته.\n\n﴿صُمُّۢ﴾: سَدُّوا أسماعَهم عن الحقِّ.\n\n﴿بُكۡمٌ﴾: أسْكَتُوا ألسنتَهم عن النُّطْقِ بالحقِّ.\n\n﴿عُمۡيࣱ﴾: لا يَرَوْن أدلَّةَ الحقِّ."],[173,173,"﴿وَمَآ أُهِلَّ بِهِۦ لِغَيۡرِ ٱللَّهِ﴾: هي الذَّبائحُ التي يُذْكَرُ عند ذَبْحِها غيرُ اللهِ.\n\n﴿غَيۡرَ بَاغࣲ﴾: غيرَ طالِبٍ للمُحَرَّمِ، مع كونهِ لا يجدُ غيرَ ما ذُكِرَ، مما أحَلَّه اللهُ.\n\n﴿وَلَا عَادࣲ﴾: ولا مُتَجاوزٍ حَدَّ الضَّرورةِ."],[174,174,"﴿ٱلَّذِينَ يَكۡتُمُونَ﴾: هم أهلُ الكتابِ الذين يُخْفُون.\n\n﴿مَآ أَنزَلَ ٱللَّهُ مِنَ ٱلۡكِتَـٰبِ﴾: من صفةِ محمدٍ ﷺ وغيرِ ذلك من الحقِّ.\n\n﴿وَيَشۡتَرُونَ بِهِۦ ثَمَنࣰا قَلِيلًا﴾: يأخذون مُقابِلَ الإخفاءِ قليلًا مِن عَرَضِ الدُّنيا.\n\n﴿إِلَّا ٱلنَّارَ﴾: إلا ما يُورِدُهم النارَ.\n\n﴿وَلَا يُكَلِّمُهُمُ﴾: ولا يُطَهِّرُهم"],[176,176,"﴿شِقَاقِۭ بَعِيدࣲ﴾: مُنازَعَةٍ بعيدةٍ عن الصَّوابِ."],[177,177,"﴿ٱلۡبِرَّ﴾: الخيرَ.\n\n﴿أَن تُوَلُّواْ﴾: أن تَتَوَجَّهُوا في الصَّلاةِ.\n\n﴿قِبَلَ﴾: جِهَةَ.\n\n﴿مَنۡ ءَامَنَ﴾: بِرَّ مَن آمَنَ.\n\n﴿عَلَىٰ حُبِّهِۦ﴾: وهو للمالِ مُحِبٌّ.\n\n﴿وَٱبۡنَ ٱلسَّبِيلِ﴾: هو المسافِرُ المحتاجُ.\n\n﴿وَفِي ٱلرِّقَابِ﴾: في تحريرِ العبيدِ، والأسرى.\n\n﴿ٱلۡبَأۡسَآءِ﴾: البؤسِ والفقرِ.\n\n﴿ٱلضَّرَّآءِ﴾: المرضِ.\n\n﴿ٱلۡبَأۡسِ﴾: مواطِنِ القتالِ."],[178,178,"﴿كُتِبَ﴾: فَرَضَ اللهُ.\n\n﴿ٱلۡقِصَاصُ﴾: أن يُوقَعَ على الجاني مثلُ ما جَنى.\n\n﴿فَمَنۡ عُفِيَ لَهُۥ﴾: مَن سامَحه وليُّ المقتولِ بالعفوِ عَنِ القِصاصِ والاكتفاءِ بالدِّيَةِ.\n\n﴿فَٱتِّبَاعُۢ﴾: فاتِّباعُ ما أوجبه اللهُ نحوَ القاتِلِ من الدِّيَةِ.\n\n﴿بِٱلۡمَعۡرُوفِ﴾: من غير عُنفٍ من قِبَلِ وليِّ المقتولِ.\n\n﴿وَأَدَآءٌ إِلَيۡهِ﴾: أداءُ ما لَزِمَ وليَّ القاتلِ إلى أولياءِ المقتولِ.\n\n﴿بِإِحۡسَـٰنࣲ﴾: من غيرِ تأخيرٍ، ولا نَقْصٍ.\n\n﴿ٱعۡتَدَىٰ﴾: تجاوَزَ بعد أخْذِ الدِّيةِ."],[179,179,"﴿حَيَوٰةࣱ﴾: أي: آمِنةٌ لكم، وفيه عقوبةٌ لأهلِ السَّفَهِ.\n\n﴿ٱلۡأَلۡبَـٰبِ﴾: العُقولِ السَّليمةِ."],[180,180,"﴿كُتِبَ﴾: فَرَضَ اللهُ.\n\n﴿ٱلۡمَوۡتُ﴾: علاماتُه ومقدِّماتُه.\n\n﴿خَيۡرًا﴾: مالًا.\n\n﴿بِٱلۡمَعۡرُوفِ﴾: بالعدلِ."],[181,181,"﴿بَدَّلَهُۥ﴾: غَيَّرَ ما وصّى به الميتُ.\n\n﴿إِثۡمُهُۥ﴾: إثمُ التغييرِ."],[182,182,"﴿جَنَفًا أَوۡ إِثۡمࣰا﴾: مَيْلًا عَنِ الحَقِّ على سبيل الخطأ أو العَمْدِ.\n\n﴿بَيۡنَهُمۡ﴾: أطرافِ المَيتِ.\n\n﴿فَلَآ إِثۡمَ عَلَيۡهِ﴾: فلا ذَنْبَ عليه بتغييرِ الوصيةِ."],[183,183,"﴿ٱلَّذِينَ مِن قَبۡلِكُمۡ﴾: هم أهلُ الكتابِ."],[184,184,"﴿أَيَّامࣰا مَّعۡدُودَ ٰ⁠تࣲ﴾: أيامًا مُحْصَياتٍ، وهي شهرُ رمضانَ.\n\n﴿فَعِدَّةࣱ مِّنۡ أَيَّامٍ أُخَرَ﴾: فعليه صيامٌ بقَدْرِ ما أفْطَرَ، من أيامٍ أُخَرَ.\n\n﴿يُطِيقُونَهُۥ﴾: يَتَكَلَّفُون صيامَه ويَشُقُّ عليهم.\n\n﴿مِسۡكِينࣲ﴾: هو المحتاجُ الذي لا يَمْلِكُ ما يَكْفيه.\n\n﴿تَطَوَّعَ خَيۡرࣰا﴾: زاد في قَدْرِ الفِدْيةِ تَبَرُّعًا منه."],[185,185,"﴿هُدࣰى﴾: إرشادًا إلى سبيلِ الحقِّ.\n\n﴿وَبَيِّنَـٰتࣲ﴾: دلائلَ واضحةً من البيان.\n\n﴿وَٱلۡفُرۡقَانِ﴾: والفَصْل بينَ الحقِّ والباطلِ.\n\n﴿ٱلۡعِدَّةَ﴾: عدةَ الصيامِ شهرًا، أو عدةَ ما أفْطَرَ فيه المريضُ والمسافرُ.\n\n﴿وَلِتُكَبِّرُواْ ٱللَّهَ﴾: ولِتُعَظِّمُوه بذِكْرِه، وذلك هو التكبيرُ يومَ الفِطْرِ."],[186,186,"﴿فَلۡيَسۡتَجِيبُواْ لِي﴾: فليُطيعوني فيما أمَرْتُهُم به، ونَهَيْتُهم عنه.\n\n﴿يَرۡشُدُونَ﴾: يَهْتدون."],[187,187,"﴿ٱلرَّفَثُ﴾: الجِماعُ.\n\n﴿لِبَاسࣱ﴾: سِتْرٌ وسَكَنٌ.\n\n﴿تَخۡتَانُونَ﴾: تَخُونون. وكانوا يُجامِعُون نساءَهم بعدالعِشاء، وكان هذا مُحَرَّمًا أولَ الإسلامِ.\n\n﴿بَـٰشِرُوهُنَّ﴾: جامِعُوهنَّ.\n\n﴿ٱبۡتَغُواْ مَا كَتَبَ ٱللَّهُ لَكُمۡ﴾: واطْلبُوا ما قدَّره اللهُ من الوَلَدِ.\n\n﴿ٱلۡخَيۡطُ ٱلۡأَبۡيَضُ﴾: ضوءُ الصبحِ.\n\n﴿ٱلۡخَيۡطِ ٱلۡأَسۡوَدِ﴾: سوادِ الليلِ.\n\n﴿ءَايَـٰتِهِۦ﴾: أحكامَه."],[188,188,"﴿بِٱلۡبَـٰطِلِ﴾: بسببٍ باطلٍ كاليمينِ الكاذبةِ والرَّشوةِ.\n\n﴿وَتُدۡلُواْ بِهَآ إِلَى ٱلۡحُكَّامِ لِتَأۡكُلُواْ فَرِيقࣰا مِّنۡ أَمۡوَ ٰ⁠لِ ٱلنَّاسِ﴾: لا تُلْقُوا بأموالِكم إلى الحُكّام؛ لتأكلوا أموالَ طائفةٍ من الناسِ بالحُجَجِ الباطلةِ.\n\n﴿وَأَنتُمۡ تَعۡلَمُونَ﴾: تحريمَ ذلك."],[189,189,"﴿ٱلۡأَهِلَّةِ﴾: جمعُ هِلالٍ، أي: عَنْ تَغَيُّر أحوالهِا بزيادةٍ أو نقصانٍ.\n\n﴿مَوَ ٰ⁠قِيتُ﴾: علاماتٌ على أوقات العبادةِ والمعاملاتِ.\n\n﴿ٱلۡبِرُّ﴾: الخير.\n\n﴿بِأَن تَأۡتُواْ ٱلۡبُيُوتَ مِن ظُهُورِهَا﴾: كانوا أولَ الإسلام إذا أحْرَمُوا بحَجّ أو عُمْرَةٍ فَعَلُوا ذلك.\n\n﴿مَنِ ٱتَّقَىٰ﴾: فِعْلُ مَن اتَّقى."],[190,190,"﴿وَلَا تَعۡتَدُوٓاْ﴾: لا تَرْتَكِبُوا المَناهيَ كقَتْلِ مَن لا يحِلُّ قَتْلُه."],[191,191,"﴿ثَقِفۡتُمُوهُمۡ﴾: وجَدْتُموهم في أيِّ مكانٍ تَمَكَّنْتُم مِن قَتْلهِم.\n\n﴿وَٱلۡفِتۡنَةُ﴾: الشِّرْك باللهِ."],[192,192,"﴿فَإِنِ ٱنتَهَوۡاْ﴾: تَرَكُوا ما هم فيه من الكفرِ والقِتالِ."],[193,193,"﴿فِتۡنَةࣱ﴾: شِرْكٌ بالله، أو فتنةٌ للمسلمين عن دينِهم.\n\n﴿ٱلدِّينُ لِلَّهِ﴾: خالصًا لله، لا يُعْبَدُ معه غيرُه."],[194,194,"﴿ٱلشَّهۡرُ ٱلۡحَرَامُ﴾: الشهرُ الذي حَرَّمَ اللهُ القتالَ فيه.\n\n﴿بِٱلشَّهۡرِ ٱلۡحَرَامِ﴾: إذا قاتَلُوكم فيه قاتَلْتُموهم فيه.\n\n﴿وَٱلۡحُرُمَـٰتُ قِصَاصࣱ﴾: مَن هَتَكَ حُرْمَةً عليكم فلكم أن تَهْتِكُوا حُرْمَةً عليه، مُساواةً."],[195,195,"﴿ٱلتَّهۡلُكَةِ﴾: المَهالِك، وهو كلُّ ما صَدَقَ عليه أنه تَهْلُكَةٌ في الدِّين، أو الدُّنيا."],[196,196,"﴿وَأَتِمُّواْ﴾: أدُّوهما تامَّيْنِ من غيرِ مَحْظورٍ.\n\n﴿أُحۡصِرۡتُمۡ﴾: حَبَسَكم حابِسٌ عن إتمامِهما بعد الإحرام بِهما.\n\n﴿فَمَا ٱسۡتَيۡسَرَ﴾: فعليكم ذَبْحُ ما تَيَسَّرَ.\n\n﴿ٱلۡهَدۡيِ﴾: ما يُهدى إلى البيت من الإبِلِ، أو البقر، أو الغنمِ.\n\n﴿وَلَا تَحۡلِقُواْ رُءُوسَكُمۡ﴾: لا تُحِلُّوا من الإحرام بالَحلْقِ إن كنتم مُحْصَرِين.\n\n﴿مَحِلَّهُۥ﴾: الموضع الذي حُصِرْتُم فيه.\n\n﴿أَوۡ نُسُكࣲ﴾: أو ذبيحةٍ، وهي شاة لفقراءِ الحرمِ.\n\n﴿أَمِنتُمۡ﴾: كنتم في أمْنٍ وصحةٍ.\n\n﴿تَمَتَّعَ بِٱلۡعُمۡرَةِ إِلَى ٱلۡحَجِّ﴾: أحرمَ بعُمْرَةٍ، ثم أقامَ حلالًا بمكةَ إلى أن يُحْرِمَ بالحجِّ.\n\n﴿ذَ ٰ⁠لِكَ﴾: أي بالهَدْيِ وما تَرَتَّبَ عليه من الصِّيامِ.\n\n﴿حَاضِرِي ٱلۡمَسۡجِدِ ٱلۡحَرَامِ﴾: ساكنِي أرضِ الحَرمِ."],[197,197,"﴿ٱلۡحَجُّ أَشۡهُرࣱ مَّعۡلُومَـٰتࣱ﴾: وقتُ الحجِّ أشهرٌ معلوماتٌ، هي: شوالٌ وذو القِعْدَةِ وعَشْرُ ذي الحِجَّةِ.\n\n﴿فَرَضَ﴾: أوْجَبَ الحَجَّ على نفسِه، وعَزَمَ.\n\n﴿رَفَثَ﴾: الجِماعَ ومقدِّماتِه.\n\n﴿فُسُوقَ﴾: الخُروجَ عن طاعةِ اللهِ بإتيانِ ما نُهِيَ عنه في حال إحرامِه لحَجِّه.\n\n﴿وَلَا جِدَالَ﴾: ولا تنازُعَ، ولا مِراءَ.\n\n﴿وَتَزَوَّدُواْ﴾: خُذُوا زادًا من الطَّعامِ والشَّرابِ، وزادًا من صالحِ الأعمالِ.\n\n﴿يَـٰٓأُوْلِي ٱلۡأَلۡبَـٰبِ﴾: يا أصحاب العقولِ السليمةِ."],[198,198,"﴿جُنَاحٌ﴾: حَرَجٌ.\n\n﴿فَضۡلࣰا﴾: التماسَ الرزقِ بالتجارةِ وقْتَ الحَجِّ.\n\n﴿أَفَضۡتُم﴾: دَفَعْتُم.\n\n﴿ٱلۡمَشۡعَرِ ٱلۡحَرَامِ﴾: المَعْلَمِ الحَرامِ، وهو مُزْدَلِفَةُ.\n\n﴿كَمَا هَدَىٰكُمۡ﴾: على الوَجْهِ الصَّحيحِ الذي هداكم إليه.\n\n﴿وَإِن كُنتُم﴾: ولقد كنتم."],[199,199,"﴿مِنۡ حَيۡثُ أَفَاضَ ٱلنَّاسُ﴾: كما عَمِلَ إبراهيمُ عليه السلامُ."],[200,200,"﴿قَضَيۡتُم مَّنَـٰسِكَكُمۡ﴾: فَرَغْتُم مِن حَجِّكم، وذَبَحْتُم النُّسُكَ.\n\n﴿خَلَـٰقࣲ﴾: نَصِيبٍ."],[201,201,"﴿فِي ٱلدُّنۡيَا حَسَنَةࣰ﴾: عافيةً ورزقًا.\n\n﴿وَفِي ٱلۡـَٔاخِرَةِ حَسَنَةࣰ﴾: الَجنّةَ."],[202,202,"﴿نَصِيبࣱ مِّمَّا كَسَبُواْ﴾: حَظٌّ من أعمالهِم.\n\n﴿سَرِيعُ ٱلۡحِسَابِ﴾: مُحْصٍ أعمالَ عبادِه، ومُجازِيهم بها."],[203,203,"﴿فِيٓ أَيَّامࣲ مَّعۡدُودَ ٰ⁠تࣲ﴾: هي أيامُ الحادي عشر والثاني عشرَ والثالثَ عشرَ مِن ذِي الحِجّةِ، في مِنى.\n\n﴿تَعَجَّلَ﴾: نَفرَ من مِنى في اليومِ الثاني عشرَ.\n\n﴿فَلَآ إِثۡمَ﴾: فلا حَرَجَ، ولا ذَنْبَ عليه في تَعَجُّله.\n\n﴿وَمَن تَأَخَّرَ﴾: فنَفَرَ في اليومِ الثالثَ عَشَرَ."],[204,204,"﴿وَمِنَ ٱلنَّاسِ﴾: من المنافقين.\n\n﴿عَلَىٰ مَا فِي قَلۡبِهِۦ﴾: من محبَّةِ الإسلامِ.\n\n﴿أَلَدُّ ٱلۡخِصَامِ﴾: شديدُ العَداوةِ والمخاصَمَةِ."],[205,205,"﴿تَوَلَّىٰ﴾: خَرَجَ مِن عندِك.\n\n﴿ٱلۡحَرۡثَ﴾: الزَّرْعَ.\n\n﴿وَٱلنَّسۡلَ﴾: نَسْلَ كلِّ دابَّةٍ."],[206,206,"﴿أَخَذَتۡهُ ٱلۡعِزَّةُ﴾: حَمَلَه الكِبْرُ وحَمِيَّةُ الجاهليةِ.\n\n﴿فَحَسۡبُهُۥ﴾: فكافيتُه.\n\n﴿ٱلۡمِهَادُ﴾: الفِراشُ."],[207,207,"﴿يَشۡرِي﴾: يَبيعُ."],[208,208,"﴿ٱلسِّلۡمِ﴾: شرائعِ الإسلامِ.\n\n﴿كَآفَّةࣰ﴾: في جميعِ أحكامِه، فلا تُضَيِّعُوا منها شيئًا.\n\n﴿خُطُوَ ٰ⁠تِ ٱلشَّيۡطَـٰنِ﴾: طُرُقَه وآثارَه.\n\n﴿مُّبِينࣱ﴾: ظاهرُ العَداوةِ."],[209,209,"﴿زَلَلۡتُم﴾: أخْطَأْتُم الحقَّ.\n\n﴿ٱلۡبَيِّنَـٰتُ﴾: الحُجَجُ الواضحَةُ.\n\n﴿عَزِيزٌ﴾: في نِقْمَتِه.\n\n﴿حَكِيمٌ﴾: يَضَعُ كلَّ شيءٍ في مَوْضِعِه المناسِبِ."],[210,210,"﴿هَلۡ يَنظُرُونَ﴾: ما ينتظرُ هؤلاء الكافرونَ.\n\n﴿يَأۡتِيَهُمُ ٱللَّهُ﴾: على الوجهِ الذي يَليقُ به.\n\n﴿ظُلَلࣲ﴾: جمعُ ظُلَّةٍ، وهي ما يُسْتَظَلُّ به.\n\n﴿ٱلۡغَمَامِ﴾: السَّحابِ.\n\n﴿وَقُضِيَ ٱلۡأَمۡرُ﴾: وفُصِلَ القضاءُ بالعَدْلِ."],[211,211,"﴿ءَايَةِۭ بَيِّنَةࣲ﴾: علامةٍ واضحةٍ، كعَصا موسى ويدِه.\n\n﴿نِعۡمَةَ ٱللَّهِ﴾: الإسلامَ، وما فَرَضَ من شرائعِ دينِه."],[212,212,"﴿زُيِّنَ﴾: حُسِّنَ.\n\n﴿وَيَسۡخَرُونَ﴾: ويَسْتهزِئُون.\n\n﴿فَوۡقَهُمۡ﴾: يُدْخِلُهم اللهُ أعلى درجاتِ الجنةِ."],[213,213,"﴿أُمَّةࣰ وَ ٰ⁠حِدَةࣰ﴾: جماعةً واحدةً متفقين على دينٍ واحدٍ.\n\n﴿مُبَشِّرِينَ﴾: مَن أطاع اللهَ بالجنةِ.\n\n﴿وَمُنذِرِينَ﴾: ومُحَذِّرينَ مَن عصاه النارَ.\n\n﴿ٱلۡكِتَـٰبَ﴾: الكُتُبَ السماويةَ.\n\n﴿فِيهِ﴾: في الكتابِ الذي أنزلَه اللهُ.\n\n﴿أُوتُوهُ﴾: أُعْطُوا الكتابَ.\n\n﴿ٱلۡبَيِّنَـٰتُ﴾: حُجَجُ اللهِ، وأدِلَّتهُ.\n\n﴿بَغۡيَۢا﴾: حَسَدًا، وحِرْصًا على الدنيا.\n\n﴿فَهَدَى ٱللَّهُ﴾: فوفَّقَ أمةَ محمدٍ ﷺ إلى الحَقِّ.\n\n﴿صِرَ ٰ⁠طࣲ﴾: طريقٍ."],[214,214,"﴿خَلَوۡاْ﴾: مضَوا.\n\n﴿ٱلۡبَأۡسَآءُ﴾: الفقرُ والشِّدَّةُ.\n\n﴿ٱلضَّرَّآءُ﴾: الأمراضُ.\n\n﴿زُلۡزِلُواْ﴾: أُزعِجُوا إزعاجًا شديدًا."],[215,215,"﴿وَٱلۡيَتَـٰمَىٰ﴾: والذين مات آباؤُهم وهم دونَ البُلوغِ.\n\n﴿وَٱلۡمَسَـٰكِينِ﴾: والمحتاجِين الذين لا يملكونَ ما يَكْفيهم.\n\n﴿وَٱبۡنِ ٱلسَّبِيلِ﴾: والمسافرِ المحتاجِ."],[216,216,"﴿كُتِبَ﴾: فَرَضَ اللهُ.\n\n﴿وَٱللَّهُ يَعۡلَمُ﴾: ما هو خيرٌ لكم."],[217,217,"﴿يَسۡـَٔلُونَكَ﴾: يَسْألك المُشْركون.\n\n﴿قِتَالࣲ فِيهِ﴾: هل يَحِلُّ القِتالُ فيه؟\n\n﴿وَصَدٌّ﴾: ومَنعٌ.\n\n﴿وَكُفۡرُۢ بِهِۦ﴾: وكُفْرٌ باللهِ.\n\n﴿وَٱلۡمَسۡجِدِ ٱلۡحَرَامِ﴾: وصَدٌّ عن المسجدِ الحرامِ كذلك.\n\n﴿وَٱلۡفِتۡنَةُ﴾: الشِّرْكُ.\n\n﴿أَكۡبَرُ مِنَ ٱلۡقَتۡلِ﴾: أعظمُ من القَتْلِ في الشهرِ الحرامِ.\n\n﴿حَبِطَتۡ﴾: بَطَلَتْ، وفَسَدَتْ."],[219,219,"﴿وَٱلۡمَيۡسِرِ﴾: القِمارِ.\n\n﴿إِثۡمࣱ﴾: أضرارٌ، ومفاسدُ.\n\n﴿وَمَنَـٰفِعُ﴾: مِن جهةِ كَسْبِ المالِ واللَّذَّةِ وغيرِهما، وهذا قبلَ التحريمِ.\n\n﴿ٱلۡعَفۡوَ﴾: الفَضْلَ الزائدَ على الحاجةِ."],[220,220,"﴿إِصۡلَاحࣱ لَّهُمۡ﴾: مُخالَطَتُهم على وجهِ الإصلاحِ لأموالِهم.\n\n﴿لَأَعۡنَتَكُمۡ﴾: لَأَوقَعكُم فيما فيه الحَرَجُ والمَشَقَّةُ بتحريمِ مخالطَتِهم.\n\n﴿حَكِيمࣱ﴾: يتَصَرَّفُ في مُلْكِه بما تَقْتضيه حِكْمَتُه."],[221,221,"﴿ٱلۡمُشۡرِكَـٰتِ﴾: الوثنيّاتِ.\n\n﴿وَلَأَمَةࣱ﴾: المملوكةُ الرقيقةُ.\n\n﴿أُوْلَـٰٓئِكَ﴾: المشركون رجالًا ونساءً.\n\n﴿إِلَى ٱلنَّارِ﴾: إلى الأعمالِ المُوجبةِ للنارِ.\n\n﴿بِإِذۡنِهِۦ﴾: بأمرهِ، وتوفيقِه."],[222,222,"﴿فَٱعۡتَزِلُواْ﴾: اجتنِبُوا الجِماعَ، لا المجالسةَ، أو الملامسةَ.\n\n﴿وَلَا تَقۡرَبُوهُنَّ﴾: ولا تجامِعُوهُنَّ.\n\n﴿يَطۡهُرۡنَ﴾: ينقطِعُ دَمُهُن.\n\n﴿تَطَهَّرۡنَ﴾: اغتسَلْن.\n\n﴿فَأۡتُوهُنَّ مِنۡ حَيۡثُ أَمَرَكُمُ ٱللَّهُ﴾: فجامِعُوهن في الموضعِ الذي أحلَّه اللهُ وهو القُبُلُ."],[223,223,"﴿حَرۡثࣱ لَّكُمۡ﴾: موضعُ زَرْعٍ لنُطَفِكم.\n\n﴿أَنَّىٰ شِئۡتُمۡ﴾: من أيِّ جهةٍ شِئْتم، في موضع الحَرْثِ.\n\n﴿وَقَدِّمُواْ لِأَنفُسِكُمۡ﴾: من التقرُّبِ إلى اللهِ بفعلِ الخيراتِ."],[224,224,"﴿عُرۡضَةࣰ لِّأَيۡمَـٰنِكُمۡ﴾: مانعًا لكم، وحاجزًا من البِرّ، وفِعْلِ الخيرِ. فإذا دُعِيتم إلى فِعْلِه قُلْتم: إنّكم أقْسَمْتُم ألّا تفعلُوه، فالحالِفُ يُمْكِنُه أن يفعلَ البِرَّ، ثم يُكَفِّرَ.\n\n﴿أَن تَبَرُّواْ﴾: مانعًا من بِرِّكم، وإصلاحِكم."],[225,225,"﴿بِٱللَّغۡوِ﴾: هو اليمينُ بغير إرادةٍ لها وقَصْدٍ.\n\n﴿كَسَبَتۡ قُلُوبُكُمۡ﴾: قَصَدَتْه قُلوبُكم."],[226,226,"﴿يُؤۡلُونَ﴾: يَحْلِفُون ألّا يُجامِعُوا نساءَهم أكثرَ من أربعةِ أشهرٍ.\n\n﴿تَرَبُّصُ أَرۡبَعَةِ أَشۡهُرࣲ﴾: عليهم انتظارُ أربعةِ أشهرٍ.\n\n﴿فَآءُو﴾: رَجَعُوا قبلَ فواتِ الأشهرِ الأربعةِ.\n\n﴿غَفُورࣱ﴾: لا يُؤاخِذُهم بتلك اليمينِ."],[227,227,"﴿عَزَمُواْ ٱلطَّلَـٰقَ﴾: وقَعَ العَزْمُ منهم على الطَّلاقِ باستمرارِهم في اليمينِ."],[228,228,"﴿يَتَرَبَّصۡنَ﴾: ينتَظِرْن دُونَ نكاحٍ بعدَ الطَّلاقِ.\n\n﴿ثَلَـٰثَةَ قُرُوٓءࣲ﴾: ثلاثةَ أوقاتٍ من الطُّهر أو الحيضِ للتأكدِ من فراغِ الرَّحِم.\n\n﴿يَكۡتُمۡنَ﴾: يُخْفِينَ الحَمْلَ، أو الحيضَ.\n\n﴿وَبُعُولَتُهُنَّ﴾: هم أزواجُ المطلقاتِ.\n\n﴿أَحَقُّ بِرَدِّهِنَّ﴾: أحقُّ بمُراجَعَتِهِنَّ في العِدَّةِ.\n\n﴿دَرَجَةࣱ﴾: منزلةٌ زائدةٌ من القِوامةِ على البيتِ، والإنفاقِ، والزيادةِ في الميراث، وغيرِ ذلك."],[229,229,"﴿ٱلطَّلَـٰقُ مَرَّتَانِ﴾: أي: الذي تحصُلُ به الرَّجْعَةُ، وهو مرة بعدَ مرة.\n\n﴿بِمَعۡرُوفٍ﴾: حُسْنِ العِشْرةِ بعدَ مراجَعَتِها.\n\n﴿تَسۡرِيحُۢ بِإِحۡسَـٰنࣲ﴾: تَخْلِيةُ سبيلِها، مع أداءِ حُقوقِها.\n\n﴿شَيۡـًٔا﴾: ممّا أعْطَيْتُموه من المَهْر ونحوِه على وجهِ المُضارَّةِ.\n\n﴿إِلَّآ أَن يَخَافَآ﴾: يخافَ الزوجان ألّا يقوما بالحقوقِ الزوجيَّةِ. وهي المُخالَعَةُ بالمعروفِ.\n\n﴿فَإِنۡ خِفۡتُمۡ﴾: أي: الأولياءُ، أو المتوسِّطون بين الزوجَيْن.\n\n﴿فِيمَا ٱفۡتَدَتۡ﴾: فيما تدفَعُه المرأةُ للزوجِ مقابلَ الطلاقِ، وهو الخُلْعُ.\n\n﴿فَلَا تَعۡتَدُوهَا﴾: فلا تَتَجاوَزُوها."],[230,230,"﴿فَإِن طَلَّقَهَا﴾: أي الطَّلْقَةَ الثالثةَ.\n\n﴿نكِحَ﴾: بزَواجٍ صَحيحٍ وجِماعٍ.\n\n﴿فَإِن طَلَّقَهَا﴾: أي الزوجُ الثاني.\n\n﴿فَلَا جُنَاحَ عَلَيۡهِمَآ﴾: أي على الزوجِ الأولِ والمرأةِ.\n\n﴿أَن يَتَرَاجَعَآ﴾: أن يتزوَّجا بعَقْدٍ جديدٍ، ومَهْرٍ جديدٍ."],[231,231,"﴿فَبَلَغۡنَ أَجَلَهُنَّ﴾: فقارَبْنَ انقضاءَ العِدَّةِ.\n\n﴿فَأَمۡسِكُوهُنَّ﴾: فراجِعُوهُنَّ.\n\n﴿بِمَعۡرُوفٍ﴾: مِن غيرِ قَصْدٍ لضِرارٍ.\n\n﴿سَرِّحُوهُنَّ﴾: اترُكُوهُنَّ، حتى تنقضِيَ العِدَّةُ.\n\n﴿وَلَا تُمۡسِكُوهُنَّ ضِرَارࣰا﴾: لا تَكُنْ مُراجَعَتُهن بقَصْدِ الاعتداءِ، والظلمِ لهن.\n\n﴿هُزُوࣰا﴾: لَعِبًا بها بالتجرُّؤِ عليها.\n\n﴿وَٱلۡحِكۡمَةِ﴾: السُّنَّةِ."],[232,232,"﴿وَإِذَا طَلَّقۡتُمُ﴾: خطابٌ لأولياءِ المطلقةِ دونَ الثلاثِ، إذا خَرَجَتْ من العِدَّةِ، وأرادَتْ زوجَها بنِكاحٍ جديدٍ.\n\n﴿فَبَلَغۡنَ أَجَلَهُنَّ﴾: انتهَتْ عِدَّتُهن من غيرِ مراجعَةٍ لهنَّ.\n\n﴿فَلَا تَعۡضُلُوهُنَّ﴾: فلا يجوزُ لوَلِيِّها أن يَمْنَعَها من التزوُّجِ بعَقْدٍ جديدٍ.\n\n﴿ذَ ٰ⁠لِكُمۡ﴾: تمكينُ الأزواجِ من نكاحِ زوجاتِهِم.\n\n﴿أَزۡكَىٰ﴾: أكثرُ نماءً وأنفعُ."],[233,233,"﴿حَوۡلَيۡنِ﴾: سنتَيْنِ.\n\n﴿وَعَلَى ٱلۡمَوۡلُودِ لَهُۥ﴾: هو الأبُ.\n\n﴿رِزۡقُهُنَّ﴾: رِزْقُ المُرضِعاتِ المُطَلَّقاتِ.\n\n﴿وُسۡعَهَا﴾: قَدْرَ طاقَتِها.\n\n﴿لَا تُضَآرَّ وَ ٰ⁠لِدَةُۢ بِوَلَدِهَا﴾: لا يَحِلُّ للوالدَين أن يَجْعلوا المولودَ وسيلةً للمُضارَّةِ بينهما.\n\n﴿وَعَلَى ٱلۡوَارِثِ مِثۡلُ ذَ ٰ⁠لِكَ﴾: أي: عند مَوْتِ الوالدِ وجَبَ على وارثِه مثلُ ما يجبُ على الوالدِ مِنَ النفقةِ والكِسْوةِ.\n\n﴿أَرَادَا﴾: الوالدان.\n\n﴿فِصَالًا﴾: فِطامَ المولودِ عن الرَّضاعةِ قبل السنتَين.\n\n﴿تَسۡتَرۡضِعُوٓاْ﴾: إرضاعَ المولودِ من مُرْضِعَةٍ أخرى.\n\n﴿إِذَا سَلَّمۡتُم﴾: سَلَّم الوالدُ للأمِّ حَقَّها، وسَلَّمَ للمُرْضِعَةِ أجْرَها."],[234,234,"﴿يَتَرَبَّصۡنَ﴾: ينتظِرْنَ في منزلِ الزوجِ.\n\n﴿بَلَغۡنَ أَجَلَهُنَّ﴾: انقضَتِ المدةُ المذكورةُ.\n\n﴿فِيمَا فَعَلۡنَ﴾: مِنَ الخروجِ والتَّزيُّنِ والتعرُّضِ للخُطّابِ."],[235,235,"﴿وَلَا جُنَاحَ﴾: ولا إثمَ.\n\n﴿عَرَّضۡتُم بِهِۦ مِنۡ خِطۡبَةِ ٱلنِّسَآءِ﴾: لَمَّحْتُم مِن طَلَبِ الزواج مِنَ المُتوفّى عنهن أزواجُهُنَّ، أو المطلقاتِ طلاقًا بائنًا، في أثناءِ العِدَّةِ.\n\n﴿أَكۡنَنتُمۡ﴾: أضْمَرْتُم من نيةِ الزواجِ بهنَّ بعد انتهاءِ عِدَّتِهن.\n\n﴿لَّا تُوَاعِدُوهُنَّ سِرًّا﴾: على النِّكاح.\n\n﴿قَوۡلࣰا مَّعۡرُوفࣰا﴾: أي: يُفْهَمُ منه أنّ مِثْلَها يُرْغَبُ فيها.\n\n﴿حَتَّىٰ يَبۡلُغَ ٱلۡكِتَـٰبُ﴾: حتى تنقضِيَ عِدَّتُها."],[236,236,"﴿لَّا جُنَاحَ﴾: لا إثمَ. والمرادُ به التَّبِعَةُ من المهرِ ونحوِه.\n\n﴿إِن طَلَّقۡتُمُ﴾: قبلَ المسيسِ، وفَرْضِ المَهْرِ.\n\n﴿أَوۡ تَفۡرِضُواْ لَهُنَّ﴾: قبلَ أن تُحَدِّدوا مَهْرًا لهنَّ.\n\n﴿وَمَتِّعُوهُنَّ﴾: أي: بشيءٍ ينتفِعْنَ به جَبْرًا لهن.\n\n﴿عَلَى ٱلۡمُوسِعِ قَدَرُهُۥ﴾: على المُطَلِّق الغنيِّ قَدْرُ سَعَةِ رزقِه.\n\n﴿ٱلۡمُقۡتِرِ﴾: المُطَلِّقِ الفقيرِ.\n\n﴿قَدَرُهُۥ﴾: قَدَرُ ما يَمْلِكُه.\n\n﴿حَقًّا عَلَى ٱلۡمُحۡسِنِينَ﴾: أي: حَقًّا ثابتًا على الذين يُحْسِنون إلى الُمطَلَّقاتِ."],[237,237,"﴿وَإِن طَلَّقۡتُمُوهُنَّ﴾: بعد العَقْدِ.\n\n﴿تَمَسُّوهُنَّ﴾: تُجامِعُوهن.\n\n﴿فَرَضۡتُمۡ لَهُنَّ فَرِيضَةࣰ﴾: التَزمْتُم لهنَّ بمَهْرٍ معينٍ.\n\n﴿إِلَّآ أَن يَعۡفُونَ﴾: إلا أن يَتَسامَحَ المُطَلَّقاتُ، فيترُكْنَ نصفَ المَهْرِ المستحَقِّ لهنَّ.\n\n﴿أَوۡ يَعۡفُوَاْ ٱلَّذِي﴾: أو يتسامَحَ الزوجُ، فيتركَ للمطلقةِ المهرَ كلَّه.\n\n﴿ٱلۡفَضۡلَ﴾: الإحسانَ، والتسامحَ في الحقوقِ."],[238,238,"﴿حَـٰفِظُواْ﴾: واظِبُوا.\n\n﴿وَٱلصَّلَوٰةِ ٱلۡوُسۡطَىٰ﴾: هي صلاةُ العَصْرِ.\n\n﴿قَـٰنِتِينَ﴾: خاشِعين ذلِيلِين."],[239,239,"﴿فَرِجَالًا﴾: ماشِين.\n\n﴿رُكۡبَانࣰا﴾: راكبين.\n\n﴿فَٱذۡكُرُواْ ٱللَّهَ﴾: أقيمُوا صلاتَكم كما أُمِرْتُمْ."],[240,240,"﴿مَّتَـٰعًا﴾: يُمَتَّعْنَ بالسُّكنى والنفقةِ في منزلِ الزوجِ، وذلك قبلَ النَّسْخِ.\n\n﴿إِلَى ٱلۡحَوۡلِ﴾: إلى سنةٍ كاملةٍ.\n\n﴿غَيۡرَ إِخۡرَاجࣲ﴾: لا يُخْرِجُهُنَّ الوَرَثَةُ.\n\n﴿فَإِنۡ خَرَجۡنَ﴾: باختيارِهنَّ قبلَ الحَوْلِ.\n\n﴿فَلَا جُنَاحَ﴾: فلا إثمَ.\n\n﴿مِن مَّعۡرُوفࣲ﴾: من أمورٍ مُباحَةٍ."],[241,241,"﴿مَتَـٰعُۢ﴾: من كِسوةٍ ونفقةٍ."],[245,245,"﴿يُقۡرِضُ﴾: يُنْفِقُ في سبيلِ اللهِ.\n\n﴿يَقۡبِضُ﴾: يُضَيِّقُ في الرِّزقِ.\n\n﴿وَيَبۡصُۜطُ﴾: ويُوَسِّعُ فيه."],[246,246,"﴿ٱلۡمَلَإِ﴾: الأشرافِ.\n\n﴿هَلۡ عَسَيۡتُمۡ﴾: هل الأمرُ كما أتَوَقَّعُه منكم، وهو الجُبْنُ عن القتالِ؟\n\n﴿كُتِبَ﴾: فُرِضَ.\n\n﴿تَوَلَّوۡاْ﴾: فَرُّوا."],[247,247,"﴿أَنَّىٰ يَكُونُ لَهُ ٱلۡمُلۡكُ﴾: كيف يكونُ له المُلْكُ، وهو لا يستحِقُّه؟\n\n﴿ٱصۡطَفَىٰهُ﴾: اختارَه.\n\n﴿بَسۡطَةࣰ﴾: سَعَةً وقوةً.\n\n﴿وَ ٰ⁠سِعٌ﴾: واسعُ الفَضْلِ."],[248,248,"﴿ءَايَةَ﴾: علامةَ.\n\n﴿ٱلتَّابُوتُ﴾: الصندوقُ الذي فيه التوراةُ، وكان الأعداءُ قد انتزَعُوه.\n\n﴿سَكِينَةࣱ﴾: طمأنينةٌ تُثَبِّتُ قلوبَ المُخْلِصين.\n\n﴿وَبَقِيَّةࣱ﴾: هي الألواحُ وعَصا موسى، وغيرُ ذلك."],[249,249,"﴿فَصَلَ﴾: خَرَجَ.\n\n﴿مُبۡتَلِيكُم﴾: مُخْتَبِركُم.\n\n﴿فَلَيۡسَ مِنِّي﴾: ليس من أهلِ ديني وطاعتي.\n\n﴿لَّمۡ يَطۡعَمۡهُ﴾: لم يَشْرَبْه.\n\n﴿ٱغۡتَرَفَ﴾: أخَذَ منه قليلًا.\n\n﴿جَاوَزَهُۥ هُوَ﴾: عَبَرَ طالوتُ النهرَ مع القلَّةِ المؤمنَةِ.\n\n﴿قَالُواْ﴾: قال الذين عَبَرُوا، وحَصَلَ معهم استضعافٌ لأنفسهم.\n\n﴿لَا طَاقَةَ﴾: لا قُدْرَةَ.\n\n﴿يَظُنُّونَ﴾: يَسْتيقِنون."],[250,250,"﴿وَلَمَّا بَرَزُواْ﴾: ولمّا صارُوا في مُتَّسَعٍ مِنَ الأرضِ.\n\n﴿لِجَالُوتَ﴾: قائدِ الجبابرةِ."],[251,251,"﴿وَٱلۡحِكۡمَةَ﴾: النبوَّةَ.\n\n﴿وَلَوۡلَا دَفۡعُ ٱللَّهِ﴾: بأن يَدْفَعَ صالحُهم المفسدين بأنْ يَصُدُّوهم عن محاولةِ الفَسادِ.\n\n﴿لَّفَسَدَتِ ٱلۡأَرۡضُ﴾: لَفَسَدَ ما عليها، واختَلَّ نظامُها."],[253,253,"﴿مَّن كَلَّمَ ٱللَّهُ﴾: كموسى عليه السلامُ.\n\n﴿وَرَفَعَ بَعۡضَهُمۡ دَرَجَـٰتࣲ﴾: كمحمدٍ ﷺ بعمومِ رسالتِه، وخَتْمِ النبوةِ به.\n\n﴿ٱلۡبَيِّنَـٰتِ﴾: المُعْجِزاتِ الباهراتِ كإحياء الموتى بإذنِ الله.\n\n﴿بِرُوحِ ٱلۡقُدُسِ﴾: جبريلَ عليه السلامُ.\n\n﴿مِنۢ بَعۡدِهِم﴾: من بعدِ هؤلاءِ الرُّسُل."],[254,254,"﴿أَنفِقُواْ﴾: بإخراجِ الزَّكاةِ المفروضةِ وغيرها من الصدقاتِ.\n\n﴿لَّا بَيۡعࣱ﴾: فيكونَ معه رِبحٌ تَفْتَدَون به أنفسَكم.\n\n﴿وَلَا خُلَّةࣱ﴾: ولا صَداقةٌ.\n\n﴿شَفَـٰعَةࣱ﴾: شفاعةُ شافعٍ مُؤَثِّرةٌ."],[255,255,"﴿ٱلۡقَيُّومُ﴾: القائمُ على كلِّ شيءٍ.\n\n﴿سِنَةࣱ﴾: نُعاسٌ.\n\n﴿كُرۡسِيُّهُ﴾: موضعُ قَدَمَي الرَّبِّ، ولا يَعْلَمُ كيفيتَه إلا اللهُ.\n\n﴿وَلَا يَـُٔودُهُۥ﴾: ولا يُثْقِلُه."],[256,256,"﴿لَآ إِكۡرَاهَ فِي ٱلدِّينِ﴾: لاتُكْرِهُوا أحدًا على الدُّخولِ في دينِ الإسلامِ.\n\n﴿ٱلرُّشۡدُ﴾: الحقُّ أو الإيمانُ.\n\n﴿ٱلۡغَيِّ﴾: الباطِلُ أو الكفرُ.\n\n﴿بِٱلطَّـٰغُوتِ﴾: بكلِّ ما عُبِدَ من دونِ اللهِ.\n\n﴿بِٱلۡعُرۡوَةِ ٱلۡوُثۡقَىٰ﴾: الطريقةِ المثلى، أو الإسلامِ.\n\n﴿لَا ٱنفِصَامَ لَهَا﴾: لا انقطاعَ، ولا انكسارَ لها."],[257,257,"﴿ٱللَّهُ وَلِيُّ ٱلَّذِينَ ءَامَنُواْ﴾: اللَّهُ يَتَوَلّاهم بتوفيقِه.\n\n﴿مِّنَ ٱلظُّلُمَـٰتِ﴾: من ظُلُماتِ الكفرِ.\n\n﴿إِلَى ٱلنُّورِ﴾: إلى نورِ الإيمانِ.\n\n﴿أَوۡلِيَآؤُهُمُ ٱلطَّـٰغُوتُ﴾: أنصارُهم هم الذين يَعْبُد ونَهم من دونِ اللهِ."],[258,258,"﴿أَلَمۡ تَرَ﴾: ألم يَنْتهِ عِلْمُك.\n\n﴿حَآجَّ﴾: جادَلَ، وهومَلِكُ بابلَ نَمْرُوذُ.\n\n﴿فِي رَبِّهِۦٓ﴾: في وجودِ ربِّه.\n\n﴿أَنۡ ءَاتَىٰهُ ٱللَّهُ ٱلۡمُلۡكَ﴾: لأنه أعطاه الُملْكَ فتَجَبَّر.\n\n﴿أَنَا۠ أُحۡيِۦ وَأُمِيتُ﴾: أقتلُ مَن أرَدْتُ، وأعفُو عَمَّنْ أرَدْتُ قَتْلَه.\n\n﴿فَبُهِتَ﴾: فَتَحَيَّر، وقامَتْ عليه الحُجَّةُ."],[259,259,"﴿كَٱلَّذِي﴾: عُزَيْرٌ.\n\n﴿قَرۡيَةࣲ﴾: بيت المقدس.\n\n﴿خَاوِيَةٌ عَلَىٰ عُرُوشِهَا﴾: تَهَدَّمَتْ دُورُها، واشتدَّ خَرابُها.\n\n﴿أَنَّىٰ﴾: كيف؟ وهو استبعادٌ لإحيائِها.\n\n﴿لَمۡ يَتَسَنَّهۡ﴾: لم يتغَيَّرْ.\n\n﴿ءَايَةࣰ﴾: دَلالةً على قدرةِ اللهِ على البعثِ.\n\n﴿نُنشِزُهَا﴾: نرفعُها، ونُرَكِّبُ بعضَها على بعضٍ."],[260,260,"﴿أَرِنِي﴾: رؤيةَ العينِ.\n\n﴿لِّيَطۡمَئِنَّ قَلۡبِي﴾: ليُؤْمِنَ قلبي.\n\n﴿فَصُرۡهُنَّ إِلَيۡكَ﴾: فاضْمُمْهُنَّ إليك، واجمَعْهُنَّ، ثم قَطِّعْهُنَّ.\n\n﴿سَعۡيࣰا﴾: مُسْرِعَةً."],[261,261,"﴿أَنۢبَتَتۡ سَبۡعَ سَنَابِلَ﴾: أخْرَجَتْ ساقًا تَشَعَّبَ منه سَبْعُ شُعَبٍ، في كل شُعبةٍ سنبلةٌ.\n\n﴿يُضَـٰعِفُ﴾: الأجْرَ."],[262,262,"﴿مَنࣰّا﴾: التحَدُّثَ بما أعْطى، حتى يَبْلُغَ ذلك المُعْطى، فيؤذِيَه.\n\n﴿أَذࣰى﴾: التطاولَ على المُعْطى.\n\n﴿وَلَا خَوۡفٌ عَلَيۡهِمۡ﴾: فيما يَسْتقبلونه من أجْر الآخرةِ.\n\n﴿وَلَا هُمۡ يَحۡزَنُونَ﴾: على شيءٍ فاتَهم في الدنيا."],[263,263,"﴿قَوۡلࣱ مَّعۡرُوفࣱ﴾: رَدٌّ جميل يُرَدُّ به السّائلُ.\n\n﴿وَمَغۡفِرَةٌ﴾: وعَفْوٌ عمّا بَدَرَ من السّائلِ مِن إلحاحٍ."],[264,264,"﴿كَٱلَّذِي﴾: لا تُبْطِلُوها كما تَبْطُلُ صَدَقَةُ الذي.\n\n﴿رِئَآءَ ٱلنَّاسِ﴾: ليراه الناسُ فَيمدَحُوه.\n\n﴿صَفۡوَانٍ﴾: حجرٍ أملسَ.\n\n﴿وَابِلࣱ﴾: مطرٌ غزيرٌ.\n\n﴿فَتَرَكَهُۥ صَلۡدࣰا﴾: أملسَ يابِسًا لا شي ءَ عليه. وكذلك شأنُ المُرائِي لاتنفَعُه نفقتُه.\n\n﴿لَّا يَقۡدِرُونَ﴾: لا ينتفعون."],[265,265,"﴿وَتَثۡبِيتࣰا﴾: ويقينًا راسخًا بأنّ اللهَ سيَجْزيهم.\n\n﴿بِرَبۡوَةٍ﴾: بأرضٍ عاليةٍ.\n\n﴿وَابِلࣱ﴾: مطرٌ غزيرٌ.\n\n﴿أُكُلَهَا﴾: ثَمَرَتَها.\n\n﴿فَطَلࣱّ﴾: فالمطرُ الضعيفُ يَكْفيها."],[266,266,"﴿أَيَوَدُّ أَحَدُكُمۡ﴾: نَزَلَتِ الآيةُ في رجلٍ غنيٍّ يعملُ بطاعةِ اللهِ، ثم يعملُ بالمعاصي.\n\n﴿إِعۡصَارࣱ﴾: ريحٌ شديدةٌ فيها نارٌ مُحرقةٌ.\n\n﴿كَذَ ٰ⁠لِكَ﴾: هكذا حالُ غيرِ المخلصينَ في نفقاتِهم."],[267,267,"﴿مِن طَيِّبَـٰتِ مَا كَسَبۡتُمۡ﴾: من جَيِّدِه، وحَلالِه.\n\n﴿وَلَا تَيَمَّمُواْ ٱلۡخَبِيثَ﴾: ولا تَقْصِدُوا بالإنفاقِ الرَّديءَ من المالِ.\n\n﴿وَلَسۡتُم بِـَٔاخِذِيهِ إِلَّآ أَن تُغۡمِضُواْ فِيهِ﴾: وإنْ أُعْطِيتُموه لم تأخُذُوه إلاإذا تَغاضَيْتُم عن رَداءتِه."],[268,268,"﴿يَعِدُكُمُ ٱلۡفَقۡرَ﴾: يُخَوِّفُكم، ويُغْرِيكم بالبُخْلِ.\n\n﴿بِٱلۡفَحۡشَآءِ﴾: بالمعاصي."],[269,269,"﴿ٱلۡحِكۡمَةَ﴾: الإصابةَ في القولِ والفعلِ.\n\n﴿ٱلۡأَلۡبَـٰبِ﴾: العقولِ السليمةِ."],[270,270,"﴿نَّذۡرࣲ﴾: ما تُوجِبُه على نفسِك.\n\n﴿لِلظَّـٰلِمِينَ﴾: المانعين لحقِّ اللهِ في المالِ."],[271,271,"﴿إِن تُبۡدُواْ ٱلصَّدَقَـٰتِ﴾: إنْ تُظْهِروها.\n\n﴿فَنِعِمَّا هِيَ﴾: فنِعْمَ ما تَصَدَّقْتُم به."],[272,272,"﴿فَلِأَنفُسِكُمۡ﴾: يعودُ نَفْعُه عليكم."],[273,273,"﴿أُحۡصِرُواْ﴾: لايَسْتطيعون السَّفرَ طَلَبًا للرِّزقِ، لانشغالهِم بالجهادِ.\n\n﴿ضَرۡبࣰا﴾: سَفَرًا لطَلَبِ الرِّزْق.\n\n﴿بِسِيمَـٰهُمۡ﴾: بعلاماتِهم، وآثارِ الحاجةِ فيهم.\n\n﴿إِلۡحَافࣰا﴾: إلحاحًا إن اضْطُرُّوا للسؤالِ."],[275,275,"﴿يَأۡكُلُونَ ٱلرِّبَوٰاْ﴾: يتعامَلُون به. والرِّبا: ما يُؤَدِّيه المُقْتَرِضُ زيادةً على ما اقترضَ، مشروطةً في العَقْدِ.\n\n﴿لَا يَقُومُونَ﴾: أي: في الآخرةِ حينَ يُبْعَثُون مِن قُبورِهم.\n\n﴿يَتَخَبَّطُهُ ٱلشَّيۡطَـٰنُ﴾: يُوقِعُه في الاضطرابِ.\n\n﴿ٱلۡمَسِّ﴾: الجنونِ.\n\n﴿فَٱنتَهَىٰ﴾: فارتدَعَ.\n\n﴿مَا سَلَفَ﴾: ما مَضى قبلَ التحريمِ، فلا إثمَ عليه فيه.\n\n﴿وَمَنۡ عَادَ﴾: أي: إلى الرِّبا."],[276,276,"﴿يَمۡحَقُ﴾: يُذْهِبُ.\n\n﴿وَيُرۡبِي﴾: يُنَمِّي، ويُضاعِفُ الأجْرَ."],[277,277,"﴿وَلَا خَوۡفٌ عَلَيۡهِمۡ﴾: في الآخرةِ.\n\n﴿وَلَا هُمۡ يَحۡزَنُونَ﴾: على ما فاتَهم في الدُّنيا."],[278,278,"﴿وَذَرُواْ﴾: اترُكُوا طَلبَ.\n\n﴿مَا بَقِيَ مِنَ ٱلرِّبَوٰٓاْ﴾: ما بَقِيَ لكم من زيادةٍ على رؤوسِ أموالِكم."],[279,279,"﴿فَأۡذَنُواْ﴾: اعْلَمُوا ذلك، واستَيْقِنُوه.\n\n﴿لَا تَظۡلِمُونَ وَلَا تُظۡلَمُونَ﴾: لا تَأْخُذُون باطلًا لا يَحِلُّ لكم، ولا تُنْقَصُون من أموالِكم."],[280,280,"﴿ذُو عُسۡرَةࣲ﴾: غيرُقادرٍ على السَّدادِ.\n\n﴿فَنَظِرَةٌ إِلَىٰ مَيۡسَرَةࣲ﴾: فعليكم أن تُمْهِلُوه إلى أن يُيَسِّرَ اللهُ عليه الأداءَ.\n\n﴿وَأَن تَصَدَّقُواْ﴾: أي: على المُعْسِرِ."],[281,281,"﴿تُوَفَّىٰ كُلُّ نَفۡسࣲ مَّا كَسَبَتۡ﴾: تُجازى بما عَمِلَتْ."],[282,282,"﴿تَدَايَنتُم﴾: تبايَعْتُمْ، وتَعاطَيْتُم بالدَّين.\n\n﴿أَجَلࣲ مُّسَمࣰّى﴾: وقتٍ معلومٍ.\n\n﴿وَلۡيُمۡلِلِ ٱلَّذِي عَلَيۡهِ ٱلۡحَقُّ﴾: يُمْلي المَدينُ ما عليه من الدَّين.\n\n﴿وَلَا يَبۡخَسۡ﴾: ولا يُنْقِصْ.\n\n﴿سَفِيهًا﴾: مُبَذِّرًا مُتلاعِبًا.\n\n﴿وَلِيُّهُۥ﴾: القائمُ بأَمْرِه.\n\n﴿أَن تَضِلَّ إِحۡدَىٰهُمَا﴾: مَخافةَ أنْ تَنْسى إحداهما.\n\n﴿وَلَا يَأۡبَ ٱلشُّهَدَآءُ إِذَا مَا دُعُواْ﴾: لا يَمْتنعون من الإجابة إذا دُعُوا لإقامةِ الشهادةِ.\n\n﴿وَلَا تَسۡـَٔمُوٓاْ﴾: ولا تَمَلُّوا من كتابةِ الدَّيْن.\n\n﴿إِلَىٰٓ أَجَلِهِۦ﴾: إلى وقتِه المعلومِ.\n\n﴿أَقۡسَطُ﴾: أعدَلُ.\n\n﴿وَأَقۡوَمُ﴾: وأصْوَبُ.\n\n﴿وَأَدۡنَىٰٓ أَلَّا تَرۡتَابُوٓاْ﴾: وأقربُ إلى نَفْيِ الشَّكِّ.\n\n﴿وَلَا يُضَآرَ﴾: لا يجوزُ الإضرارُبهما.\n\n﴿فُسُوقُۢ﴾: خروجٌ عن طاعةِ اللهِ."],[283,283,"﴿فَرِهَـٰنࣱ مَّقۡبُوضَةࣱ﴾: ادفَعُوا إلى صاحبِ الحقِّ شيئًا لضَمانِ حَقِّه.\n\n﴿فَإِنَّهُۥٓ ءَاثِمࣱ قَلۡبُهُۥ﴾: فهو ذو قَلْبٍ فاجرٍ."],[284,284,"﴿تُبۡدُواْ﴾: تُظْهِروا."],[285,285,"﴿لَا نُفَرِّقُ﴾: نُؤْمِنُ بجميعِ الرسُلِ.\n\n﴿غُفۡرَانَكَ﴾: نَطْلُبُ مغفرتَك."],[286,286,"﴿وُسۡعَهَا﴾: قَدْرَ ما تُطيقُ.\n\n﴿لَهَا مَا كَسَبَتۡ﴾: أي: مَن فَعَلَ خيرًا نال أجْرَه.\n\n﴿وَعَلَيۡهَا مَا ٱكۡتَسَبَتۡ﴾: أي: ومَن فَعَلَ شرًّا نال جَزاءَه.\n\n﴿إِصۡرࣰا﴾: عَهْدًا لا نُطيقُ القيامَ به.\n\n﴿مَا لَا طَاقَةَ لَنَا بِهِۦ﴾: ما لانَسْتطيعُه.\n\n﴿أَنتَ مَوۡلَىٰنَا﴾: أنت وليُّنا، وناصِرُنا."]]);
QTF("gharib",3,[[1,1,"﴿الٓمٓ﴾: سَبَقَ شَرْحُها في الآية"],[2,2,"﴿ٱلۡقَيُّومُ﴾: القائمُ بنفسِه، والمُقيمُ لأحوالِ خَلْقِه."],[3,3,"﴿ٱلۡكِتَـٰبَ﴾: القرآنَ.\n\n﴿مُصَدِّقࣰا لِّمَا بَيۡنَ يَدَيۡهِ﴾: يَشْهَدُ على صِدْقِ ما قبلَه من كُتُبٍ."],[4,4,"﴿ٱلۡفُرۡقَانَ﴾: ما يُفَرِّقُ بينَ الحقِّ والباطلِ، وهو القرآنُ."],[6,6,"﴿كَيۡفَ يَشَآءُ﴾: مِن ذَكَرٍ وأنثى، وشَقِيٍّ وسعيدٍ، وغيرِ ذلك."],[7,7,"﴿مُّحۡكَمَـٰتٌ﴾: واضحاتُ المعنى، ظاهراتُ الدَّلالةِ.\n\n﴿أُمُّ ٱلۡكِتَـٰبِ﴾: أصلُه الذي يُرْجَعُ إليه عندَ الاشتِباهِ.\n\n﴿مُتَشَـٰبِهَـٰتࣱ﴾: لا يتعَيَّنُ معناها، ولا تَظْهَرُ دَلالتُها.\n\n﴿زَيۡغࣱ﴾: مَيْلٌ.\n\n﴿فَيَتَّبِعُونَ مَا تَشَـٰبَهَ مِنۡهُ﴾: يَتَّبعون الآياتِ المتشابهاتِ، فيُشَكِّكُون بها على المؤمنين.\n\n﴿ٱبۡتِغَآءَ ٱلۡفِتۡنَةِ﴾: طَلَبًا منهم للتَّلبيسِ عليهم في دينِهم.\n\n﴿وَٱبۡتِغَآءَ تَأۡوِيلِهِۦ﴾: ولتأويلِهم لها على الوجه الذي يوافِقُ مذهبَهم.\n\n﴿وَٱلرَّ ٰ⁠سِخُونَ﴾: والمتمَكِّنُونَ.\n\n﴿كُلࣱّ﴾: كلُّ القرآنِ.\n\n﴿وَمَا يَذَّكَّرُ﴾: وما يتدبَّرُ المعانيَ على وجْهِها الصحيحِ.\n\n﴿أُوْلُواْ ٱلۡأَلۡبَـٰبِ﴾: أصحابُ العقولِ السليمةِ."],[8,8,"﴿لَا تُزِغۡ قُلُوبَنَا﴾: لاتَصْرِفْ قلوبَنا عن الإيمانِ بك."],[10,10,"﴿لَن تُغۡنِيَ عَنۡهُمۡ﴾: لن تنفعَهم، ولن تُنْجِيَهم.\n\n﴿مِّنَ ٱللَّهِ﴾: من عقوبتهِ، إن أحَلَّها بهم عاجلًا في الدنيا.\n\n﴿وَقُودُ ٱلنَّارِ﴾: حَطَبُ النارِ."],[11,11,"﴿كَدَأۡبِ ءَالِ فِرۡعَوۡنَ﴾: شَأْنُ الكافرين في تكذيبهِم ومايَنْزِلُ بهم من العقوبةِ مِثْلُ شأنِ آلِ فرعونَ.\n\n﴿فَأَخَذَهُمُ ٱللَّهُ﴾: فعاجَلَهم بالعُقوبةِ."],[12,12,"﴿لِّلَّذِينَ كَفَرُواْ﴾: لليهودِ.\n\n﴿وَتُحۡشَرُونَ﴾: وتُجْمَعون، وتُساقُون.\n\n﴿ٱلۡمِهَادُ﴾: الفِراشُ."],[13,13,"﴿ءَايَةࣱ﴾: دَلالَةٌ عظيمةٌ.\n\n﴿ٱلۡتَقَتَا﴾: أي: في معركةِ بدرٍ.\n\n﴿يَرَوۡنَهُم مِّثۡلَيۡهِمۡ﴾: يرى المشركون المسلمين في العددِ مثلَيْهم.\n\n﴿لَعِبۡرَةࣰ﴾: لعِظَةً.\n\n﴿لِّأُوْلِي ٱلۡأَبۡصَـٰرِ﴾: لأصحابِ البصائرِ."],[14,14,"﴿زُيِّنَ﴾: حُسِّنَ.\n\n﴿وَٱلۡقَنَـٰطِيرِ ٱلۡمُقَنطَرَةِ﴾: والأموالِ الكثيرةِ.\n\n﴿ٱلۡمُسَوَّمَةِ﴾: المُعَلَّمَةِ الحِسانِ.\n\n﴿وَٱلۡأَنۡعَـٰمِ﴾: من الإبِلِ والبقرِوالغَنَمِ.\n\n﴿وَٱلۡحَرۡثِ﴾: الأرضِ المتخَذَةِ للزِّراعةِ.\n\n﴿ٱلۡمَـَٔابِ﴾: المَرْجِعِ."],[15,15,"﴿مِّن ذَ ٰ⁠لِكُمۡ﴾: ممّا حُسِّنَ للناسِ في الحياةِ الدُّنيا.\n\n﴿مُّطَهَّرَةࣱ﴾: من الحَيْضِ والنِّفاسِ، وسوءِ الخُلُقِ.\n\n﴿وَرِضۡوَ ٰ⁠نࣱ﴾: ورِضا."],[16,16,"﴿وَقِنَا﴾: ونَجِّنا."],[17,17,"﴿وَٱلصَّـٰدِقِينَ﴾: الذين صَدَقُوا اللهَ، فعَمِلُوا بماجاء به.\n\n﴿وَٱلۡقَـٰنِتِينَ﴾: والمطيعين له.\n\n﴿بِٱلۡأَسۡحَارِ﴾: بآخِرِ الليلِ."],[18,18,"﴿وَٱلۡمَلَـٰٓئِكَةُ﴾: أي: يَشْهَدُون كذلك.\n\n﴿بِٱلۡقِسۡطِ﴾: بالعَدْلِ."],[19,19,"﴿مِنۢ بَعۡدِ مَا جَآءَهُمُ ٱلۡعِلۡمُ﴾: أي: المقتضي لعَدَمِ الاختلافِ، بما تَضَمَّنَتْه كُتُبُهم المنزَّلةُ.\n\n﴿بَغۡيَۢا بَيۡنَهُمۡ﴾: حَسَدًا وطَلَبًا للدُّنيا، فصَدَّهم عن اتِّباعِ الَحقِّ.\n\n﴿سَرِيعُ ٱلۡحِسَابِ﴾: يحفَظُ ذلك عليهم بغيرِ كُلْفَةٍ."],[20,20,"﴿حَآجُّوكَ﴾: جادَلُوك أيُّها الرسولُ.\n\n﴿أَسۡلَمۡتُ﴾: أخلَصْتُ.\n\n﴿وَمَنِ ٱتَّبَعَنِ﴾: وكذلك أسْلَمَ وجهَه مَنِ اتَّبعَني.\n\n﴿وَٱلۡأُمِّيِّـۧنَ﴾: مُشْركي العربِ الذين لايكتبُون.\n\n﴿تَوَلَّوۡاْ﴾: أعْرَضُوا."],[21,21,"﴿بِٱلۡقِسۡطِ﴾: بالعَدْلِ."],[22,22,"﴿حَبِطَتۡ﴾: بَطَلَتْ."],[23,23,"﴿إِلَى ٱلَّذِينَ﴾: إلى اليهودِ الذين كانوا في زمن النبيِّ ﷺ مِمَّن أُوتي عِلْمًا.\n\n﴿نَصِيبࣰا مِّنَ ٱلۡكِتَـٰبِ﴾: حَظًّا من التوراةِ.\n\n﴿كِتَـٰبِ ٱللَّهِ﴾: التوراةِ.\n\n﴿يَتَوَلَّىٰ﴾: يأبى."],[24,24,"﴿ذَ ٰ⁠لِكَ﴾: الانصرافُ عن الحقِّ.\n\n﴿وَغَرَّهُمۡ﴾: وخَدَعَهم.\n\n﴿يَفۡتَرُونَ﴾: يختلِقُون من الأكاذيبِ في ادِّعائِهم أنهم أبناءُ اللهِ وأحِبّاؤُه."],[25,25,"﴿فَكَيۡفَ﴾: أي: فكيف يكونُ حالهُم؟\n\n﴿وَوُفِّيَتۡ﴾: وجُوزِيَتْ.\n\n﴿مَّا كَسَبَتۡ﴾: ما عَمِلَتْ من خيرٍ أو شَرٍّ."],[26,26,"﴿تَنزِعُ﴾: تَسْلُبُ."],[27,27,"﴿تُولِجُ﴾: تُدْخِلُ.\n\n﴿وَتُخۡرِجُ ٱلۡحَيَّ مِنَ ٱلۡمَيِّتِ﴾: تُخْرِجُ الإنسانَ الحَيَّ من النُّطْفةِ الميتةِ.\n\n﴿وَتُخۡرِجُ ٱلۡمَيِّتَ مِنَ ٱلۡحَيِّ﴾: تُخْرِجُ النُّطْفَةَ الميتة من الإنسانِ الحيِّ.\n\n﴿بِغَيۡرِ حِسَابࣲ﴾: بغير مُحاسَبةٍ."],[28,28,"﴿لَّا يَتَّخِذِ ٱلۡمُؤۡمِنُونَ ٱلۡكَـٰفِرِينَ أَوۡلِيَآءَ﴾: لا تَتَّخِذُوا أيها المؤمنون الكافرين أنصارًا.\n\n﴿إِلَّآ أَن تَتَّقُواْ مِنۡهُمۡ تُقَىٰةࣰ﴾: إلاأن تكونوا ضِعافًا، فرَخَّص لكم في مُهادنتِهم اتقاءً لشَرِّهم.\n\n﴿ٱلۡمَصِيرُ﴾: رجوعُ الخلائقِ للحِسابِ."],[29,29,"﴿تُبۡدُوهُ﴾: تُظْهِرُوه."],[30,30,"﴿مُّحۡضَرࣰا﴾: مُوَفَّرًا.\n\n﴿أَمَدَۢا﴾: زَمَنًا وأجَلًا."],[32,32,"﴿تَوَلَّوۡاْ﴾: أعْرَضُوا."],[33,33,"﴿ٱصۡطَفَىٰٓ﴾: اختار.\n\n﴿عَلَى ٱلۡعَـٰلَمِينَ﴾: جَعَلَهم أفضلَ أهلِ زمانِهم."],[34,34,"﴿ذُرِّيَّةَۢ بَعۡضُهَا مِنۢ بَعۡضࣲ﴾: تَسَلْسَلَ الفَضْلُ في ذَراريهم."],[35,35,"﴿ٱمۡرَأَتُ عِمۡرَ ٰ⁠نَ﴾: أمُّ مريمَ.\n\n﴿نَذَرۡتُ﴾: جَعَلْتُه لخِدْمَةِ بيتِ المقدسِ.\n\n﴿مُحَرَّرࣰا﴾: خالصًا لعبادتِك."],[36,36,"﴿وَضَعۡتُهَآ أُنثَىٰ﴾: أي: لاتَصْلُحُ للخِدْمةِ.\n\n﴿وَلَيۡسَ ٱلذَّكَرُ كَٱلۡأُنثَىٰ﴾: ليس الذَّكَرُ الذي أرَدْتُ للخدمةِ كالأنثى التي لا تَصْلُحُ لذلك.\n\n﴿أُعِيذُهَا﴾: أُحَصِّنُها.\n\n﴿ٱلرَّجِيمِ﴾: المَطْرودِ من رحمتك."],[37,37,"﴿وَأَنۢبَتَهَا نَبَاتًا حَسَنࣰا﴾: تَوَلّى ابْنَتَها، فكَمُلَتْ بذلك أحوالُها.\n\n﴿ٱلۡمِحۡرَابَ﴾: مَحَلَّ عبادتهِ."],[38,38,"﴿هُنَالِكَ﴾: عند رؤيةِ زكريّا ما عندَ مريمَ من رزقِ اللهِ، وفَضْلهِ.\n\n﴿ذُرِّيَّةࣰ طَيِّبَةً﴾: ولَدًا مباركًا. وتُطْلَقُ الذُّرِّيَّةُ على الجمعِ والواحدِ."],[39,39,"﴿ٱلۡمِحۡرَابِ﴾: مُقَدَّم المسجدِ، وهو مكانُ عبادتِه.\n\n﴿مُصَدِّقَۢا بِكَلِمَةࣲ مِّنَ ٱللَّهِ﴾: يُصَدِّقُ بعيسى عليه السلامُ.\n\n﴿وَسَيِّدࣰا﴾: شريفًا في العِلْمِ والعبادةِ.\n\n﴿وَحَصُورࣰا﴾: يَكُفُّ عن النساءِ، فيمتنعُ عنهنَّ مع القُدرةِ."],[40,40,"﴿أَنَّىٰ﴾: من أيِّ وجهٍ؟\n\n﴿ٱلۡكِبَرُ﴾: الشيخوخةُ.\n\n﴿عَاقِرࣱ﴾: عَقيمٌ.\n\n﴿كَذَ ٰ⁠لِكَ ٱللَّهُ﴾: هَيِّنٌ عليه أن يخلقَ ولدًا من الكبيرِ والعقيمِ."],[41,41,"﴿ءَايَةࣰ﴾: علامةً أسْتَدِلُّ بها على وجودِ الوَلَدِ.\n\n﴿رَمۡزࣰا﴾: إشارةً وإيماءً.\n\n﴿بِٱلۡعَشِيِّ﴾: مِن زوالِ الشمسِ إلى أن تَغِيبَ.\n\n﴿وَٱلۡإِبۡكَـٰرِ﴾: من مَطْلَعِ الفجرِ إلى وقتِ الضُّحى."],[42,42,"﴿ٱصۡطَفَىٰكِ﴾: اختارَكِ لطاعتِه.\n\n﴿ٱلۡعَـٰلَمِينَ﴾: عالَمِي زمانِك."],[43,43,"﴿ٱقۡنُتِي﴾: أخْلِصي الطاعةَ لربِّك."],[44,44,"﴿وَمَا كُنتَ لَدَيۡهِمۡ﴾: أي: نحن نُعْلِمُك أخبارَهم.\n\n﴿يُلۡقُونَ أَقۡلَـٰمَهُمۡ﴾: يُجْرُون القُرْعَةَ، بإلقاءِ سِهامِهم على كَفالةِ مريمَ، فأصابَتْ زكريا."],[45,45,"﴿بِكَلِمَةࣲ مِّنۡهُ﴾: يكونُ وجودُه بكلمةٍ من اللهِ، وهي قولُه: «كن»، فيكونُ.\n\n﴿وَجِيهࣰا﴾: له الجاهُ العظيمُ عندَ اللهِ."],[46,46,"﴿فِي ٱلۡمَهۡدِ﴾: في مَضْجَعِ الصبيِّ في رَضاعِه.\n\n﴿وَكَهۡلࣰا﴾: مَن كان بينَ سِنِّ الشَّبابِ والشيخوخةِ."],[47,47,"﴿أَنَّىٰ﴾: من أيِّ وجه؟"],[48,48,"﴿ٱلۡكِتَـٰبَ﴾: الكتابةَ."],[49,49,"﴿بِـَٔايَةࣲ﴾: بعلامةٍ دالَّةٍ على أني مُرْسَلٌ من اللهِ.\n\n﴿فِيهِ﴾: في ذلك الخَلْقِ.\n\n﴿ٱلۡأَكۡمَهَ﴾: مَن وُلِدَ أعمى.\n\n﴿وَٱلۡأَبۡرَصَ﴾: مَن يَظْهَرُ في جِلْده بياضٌ.\n\n﴿تَدَّخِرُونَ﴾: تُخَبِّئون لوقتِ الحاجةِ."],[50,50,"﴿وَمُصَدِّقࣰا﴾: وجِئتُكم مُصَدِّقًا.\n\n﴿بَعۡضَ ٱلَّذِي حُرِّمَ عَلَيۡكُمۡ﴾: مثلَ لحومِ الإبلِ، والشُّحومِ، وغيرِها."],[51,51,"﴿صِرَ ٰ⁠طࣱ﴾: طريقٌ."],[52,52,"﴿إِلَى ٱللَّهِ﴾: مُتَوَجِّهًا إلى اللهِ.\n\n﴿ٱلۡحَوَارِيُّونَ﴾: هم أصْفِياءُ عيسى عليه السلامُ."],[53,53,"﴿ٱلشَّـٰهِدِينَ﴾: الذين شَهِدُوا بالحقِّ، وأقَرُّوا بالتوحيدِ."],[54,54,"﴿وَمَكَرُواْ﴾: أرادوا قَتْلَ عيسى عليه السلام.\n\n﴿وَمَكَرَ ٱللَّهُ﴾: بحَقٍّ على ما يَلِيقُ به، وذلك من إلقائِه شَبَهَ عيسى على بعض أتباعِه حتى قَتَلُوه، ورَفْعِ عيسى إليه."],[55,55,"﴿مُتَوَفِّيكَ﴾: قابضُك من الأرضِ.\n\n﴿وَمُطَهِّرُكَ﴾: ومُخَلِّصُك.\n\n﴿ٱلَّذِينَ ٱتَّبَعُوكَ﴾: هم خُلَّصُ أصحابِك الذين لم يَغْلُوا فيك.\n\n﴿فَوۡقَ ٱلَّذِينَ كَفَرُوٓاْ﴾: ظاهرين على الذين جَحَدُوا نبوَّتَك."],[56,56,"﴿فِي ٱلدُّنۡيَا﴾: بالقَتْلِ والصَّغارِ."],[57,57,"﴿فَيُوَفِّيهِمۡ أُجُورَهُمۡ﴾: فيُعْطِيهم ثوابَ أعمالِهم كاملًا."],[58,58,"﴿مِنَ ٱلۡـَٔايَـٰتِ﴾: من الدَّلائلِ الواضحةِ على صحةِ رسالتِك.\n\n﴿وَٱلذِّكۡرِ ٱلۡحَكِيمِ﴾: القُرآنِ الذي يَفْصِلُ بينَ الحَقِّ والباطلِ"],[59,59,"﴿كَمَثَلِ ءَادَمَ﴾: مَثَلُه كمَثَلِ خَلْقِ آدمَ من غير أبٍ، ولا أمٍّ."],[60,60,"﴿ٱلۡمُمۡتَرِينَ﴾: الشاكِّين."],[61,61,"﴿حَآجَّكَ فِيهِ﴾: جادَلَك في عيسى.\n\n﴿نَبۡتَهِلۡ﴾: نَتَوَجَّهْ إلى اللهِ بالدُّعاء."],[63,63,"﴿تَوَلَّوۡاْ﴾: أعْرَضُوا عن تصديِقك."],[64,64,"﴿سَوَآءِۭ﴾: عَدْلٍ وحَقّ، نلتزمُ بها.\n\n﴿وَلَا يَتَّخِذَ بَعۡضُنَا بَعۡضًا أَرۡبَابࣰا﴾: ماكان بطاعةِ الأتباعِ للرؤساءِ فيما أمروهُم به من المعاصِي.\n\n﴿مُسۡلِمُونَ﴾: خاضِعُون لرَبِّنا."],[65,65,"﴿تُحَآجُّونَ فِيٓ إِبۡرَ ٰ⁠هِيمَ﴾: تُجادِلُون في أنّ إبراهيمَ على مِلَّتِكم."],[66,66,"﴿حَـٰجَجۡتُمۡ﴾: جادَلْتُم.\n\n﴿فِيمَا لَكُم بِهِۦ عِلۡمࣱ﴾: في أمْرِ دينِكم مِمّا تعتقدون صِحَّتَه."],[67,67,"﴿حَنِيفࣰا﴾: مُتَّبِعًا أمْرَ الله.\n\n﴿مُّسۡلِمࣰا﴾: خاشِعًا لربِّه، مُلْتَزِمًا بأحكامِه."],[68,68,"﴿أَوۡلَى﴾: أحَقُّ.\n\n﴿وَهَـٰذَا ٱلنَّبِيُّ﴾: محمدٌ ﷺ."],[69,69,"﴿لَوۡ يُضِلُّونَكُمۡ﴾: عن الإسلامِ."],[70,70,"﴿لِمَ تَكۡفُرُونَ بِـَٔايَـٰتِ ٱللَّهِ﴾: لِمَ تَجْحَدُون بآياتِ اللهِ التي أنزلها على رُسُلهِ في كُتُبِكم؟\n\n﴿وَأَنتُمۡ تَشۡهَدُونَ﴾: أنه الحقُّ، فتَجِدُونه مكتوبًا عندَكم ثم تُنْكِرونه."],[71,71,"﴿تَلۡبِسُونَ﴾: تَخْلِطُون.\n\n﴿ٱلۡحَقَّ﴾: الذي في كُتُبِكم.\n\n﴿بِٱلۡبَـٰطِلِ﴾: بما حَرَّفْتُموه بأيدِيكم.\n\n﴿وَتَكۡتُمُونَ ٱلۡحَقَّ﴾: وتُخْفُون ما في كُتبِكم من مَبْعَثِ محمدٍ ﷺ."],[72,72,"﴿ءَامِنُواْ﴾: صَدِّقوا.\n\n﴿وَجۡهَ ٱلنَّهَارِ﴾: أوَّلَه.\n\n﴿لَعَلَّهُمۡ يَرۡجِعُونَ﴾: لعلَّهم يَتَشَكَّكُون في دينِهم، ويَرْجِعُون عنه."],[73,73,"﴿وَلَا تُؤۡمِنُوٓاْ﴾: ولاتُصَدِّقوا.\n\n﴿أَن يُؤۡتَىٰٓ أَحَدࣱ مِّثۡلَ مَآ أُوتِيتُمۡ﴾: لا تُصَدِّقُوهم لئلا يَعْلَمُوا مثلَ ما عَلِمْتُم.\n\n﴿يُحَآجُّوكُمۡ﴾: يَتَّخِذُوه حُجَّةً."],[74,74,"﴿ذُو ٱلۡفَضۡلِ﴾: ذو العَطاءِ"],[75,75,"﴿بِقِنطَارࣲ﴾: على كثيرٍ من المالِ.\n\n﴿قَآئِمࣰا﴾: أي: بالمطالبةِ.\n\n﴿ٱلۡأُمِّيِّـۧنَ﴾: العربِ.\n\n﴿سَبِيلࣱ﴾: حَرَجٌ في أموالهِم؛ لأنّ اللهَ أحَلَّها لنا."],[76,76,"﴿مَنۡ أَوۡفَىٰ بِعَهۡدِهِۦ﴾: مَن أدّى أمانتَه."],[77,77,"﴿يَشۡتَرُونَ بِعَهۡدِ ٱللَّهِ﴾: يَسْتبدلون بوصيةِ اللهِ باتِّباعِ محمدٍ ﷺ.\n\n﴿وَأَيۡمَـٰنِهِمۡ﴾: الكاذبةِ.\n\n﴿لَا خَلَـٰقَ﴾: لا نصِيبَ.\n\n﴿وَلَا يُزَكِّيهِمۡ﴾: ولا يُطَهِّرُهم مِن دَنَسِ ذُنوبِهم."],[78,78,"﴿يَلۡوُۥنَ أَلۡسِنَتَهُم بِٱلۡكِتَـٰبِ﴾: يُحَرِّفُون الكلامَ، ويُبَدِّلون آياتِ اللهِ."],[79,79,"﴿رَبَّـٰنِيِّـۧنَ﴾: جَمْعُ رَبّانِيّ، وهو الذي يُصْلِحُ أمورَ الناسِ، ويقومُ بها."],[81,81,"﴿مِيثَـٰقَ ٱلنَّبِيِّـۧنَ﴾: العهدَ المؤكَّدَ على الأنبياءِ في تصديقِ بعضِهم بعضًا.\n\n﴿لَمَآ﴾: لَئِنْ.\n\n﴿إِصۡرِي﴾: عَهْدِي الُموَثَّقَ."],[82,82,"﴿تَوَلَّىٰ﴾: أعْرَضَ.\n\n﴿ٱلۡفَـٰسِقُونَ﴾: الخارجون عن طاعةِ اللهِ."],[83,83,"﴿يَبۡغُونَ﴾: يريدون.\n\n﴿أَسۡلَمَ﴾: استسلمَ، وخَضَعَ.\n\n﴿طَوۡعࣰا﴾: طَواعيةً، كالملائكةِ والأنبياءِ.\n\n﴿وَكَرۡهࣰا﴾: رَغْمًا عنه، كمَن أسلمَ مخافةَ القتلِ."],[84,84,"﴿وَٱلۡأَسۡبَاطِ﴾: الأنبياءِ الذين كانُوا في قبائلِ بني إسرائيل مِن ولَدِ يعقوبَ.\n\n﴿مُسۡلِمُونَ﴾: مُنقادُون بالطاعةِ."],[86,86,"﴿يَهۡدِي﴾: يُوَفِّقُ للإيمانِ، ويُرْشِدُ للصَّوابِ.\n\n﴿ٱلۡبَيِّنَـٰتُ﴾: الدَّلائلُ الواضحاتُ."],[87,87,"﴿لَعۡنَةَ ٱللَّهِ﴾: الطَّرْدَ من رحمةِ اللهِ."],[88,88,"﴿وَلَا هُمۡ يُنظَرُونَ﴾: ولا يُؤَخَّرُ عنهم لمعذِرَةٍ يَعْتَذِرُون بها."],[89,89,"﴿وَأَصۡلَحُواْ﴾: ما أفسَدُوه."],[90,90,"﴿لَّن تُقۡبَلَ تَوۡبَتُهُمۡ﴾: عند حُضورِ الموتِ."],[91,91,"﴿وَلَوِ ٱفۡتَدَىٰ بِهِۦٓ﴾: ولو دَفَعَ هذا المالَ ليَفْتَدِيَ نفسَه من العذابِ."],[92,92,"﴿ٱلۡبِرَّ﴾: الجنةَ."],[93,93,"﴿إِلَّا مَا حَرَّمَ﴾: هو يعقوبُ، إذ حَرَّمَ على نفسِه -دونَ أتباعِه- لمرضٍ ألَمَّ به، ولمّا نَزَلَتِ التوراةُ حَرَّمَ اللهُ على بني إسرائيلَ بعضَ الأطعمةِ لظُلْمِهم.\n\n﴿إِن كُنتُمۡ صَـٰدِقِينَ﴾: في دَعْواكم أنّ اللهَ أنزلَ في التوراةِ تحريمَ ماحَرَّمه يعقوبُ على نفسِه."],[95,95,"﴿صَدَقَ ٱللَّهُ﴾: فيما أخبرَ به.\n\n﴿حَنِيفࣰا﴾: مستقيمًا لا عِوَجَ فيه."],[96,96,"﴿بِبَكَّةَ﴾: بمكةَ.\n\n﴿مُبَارَكࣰا﴾: تُضاعَفُ فيه الحَسَناتُ."],[97,97,"﴿ءَايَـٰتُۢ﴾: علاماتٌ.\n\n﴿مَّقَامُ إِبۡرَ ٰ⁠هِيمَ﴾: وهو الحَجَرُ الذي كان يَقِفُ عليه حين كان يرفعُ القَواعدَ من البيت.\n\n﴿سَبِيلࣰا﴾: سَعَةً.\n\n﴿وَمَن كَفَرَ﴾: ومَن جَحَدَ وُجوبَه."],[98,98,"﴿لِمَ تَكۡفُرُونَ بِـَٔايَـٰتِ ٱللَّهِ﴾: لِمَ تُنْكِرُون ما في كتبِكم من دلائلَ على أن الدينَ هو الإسلامُ؟"],[99,99,"﴿تَصُدُّونَ﴾: تمنعون.\n\n﴿عِوَجࣰا﴾: مَيْلًا عن القصدِ، والاستقامةِ.\n\n﴿شُهَدَآءُ﴾: عالِمُون أنّ ما جِئْتُ به هو الحقُّ."],[100,100,"﴿يَرُدُّوكُم بَعۡدَ إِيمَـٰنِكُمۡ كَـٰفِرِينَ﴾: يُلْقُوا إليكم الشُّبَهَ، فتَرْجِعُوا جاحِدِين للحقِّ."],[101,101,"﴿ءَايَـٰتُ ٱللَّهِ﴾: القرآنُ الكريمُ.\n\n﴿وَفِيكُمۡ رَسُولُهُۥ﴾: يُبَلِّغُها لكم، وهو حُجَّةٌ أخرى للهِ عليكم.\n\n﴿يَعۡتَصِم بِٱللَّهِ﴾: يتمسَّكْ بدِينِه، وطاعتِه.\n\n﴿هُدِيَ﴾: وُفِّقَ.\n\n﴿صِرَ ٰ⁠طࣲ﴾: طريقٍ."],[102,102,"﴿مُّسۡلِمُونَ﴾: مُذْعِنُون له بالطاعةِ."],[103,103,"﴿وَٱعۡتَصِمُواْ بِحَبۡلِ ٱللَّهِ﴾: وتمسَّكُوا بدينِ اللهِ.\n\n﴿فَأَلَّفَ﴾: فجَمَعَ.\n\n﴿إِخۡوَ ٰ⁠نࣰا﴾: مُتَحابِّين.\n\n﴿شَفَا﴾: حافَةٍ وطَرفٍ."],[104,104,"﴿أُمَّةࣱ﴾: جماعةٌ."],[105,105,"﴿كَٱلَّذِينَ تَفَرَّقُواْ﴾: من أهلِ الكتابِ.\n\n﴿ٱلۡبَيِّنَـٰتُ﴾: الحُجَجُ الواضحاتُ."],[106,106,"﴿تَبۡيَضُّ وُجُوهࣱ﴾: هم أهلُ السَّعادَةِ.\n\n﴿وَتَسۡوَدُّ وُجُوهࣱ﴾: هم أهلُ الشَّقاءِ.\n\n﴿أَكَفَرۡتُم﴾: فُيقال لهم توبيخًا"],[108,108,"﴿بِٱلۡحَقِّ﴾: بالصِّدْقِ واليقينِ."],[109,109,"﴿تُرۡجَعُ ٱلۡأُمُورُ﴾: مَصِيرُ أمْرِ جميعِ الخَلْقِ، فيُجازي كُلًّا بما يستحِقُّ."],[110,110,"﴿كُنتُمۡ﴾: أنتم يا أمةَ محمدٍ ﷺ، على الشَّرْطِ المذكورِ.\n\n﴿ٱلۡفَـٰسِقُونَ﴾: الخارِجُون عن دينِ اللهِ."],[111,111,"﴿إِلَّآ أَذࣰى﴾: إلا ما يُؤْذِي أسماعَكم من الكَذِبِ على اللهِ والتحريفِ.\n\n﴿يُوَلُّوكُمُ ٱلۡأَدۡبَارَ﴾: يُهْزَموا."],[112,112,"﴿ٱلذِّلَّةُ﴾: الهَوانُ والصَّغارُ.\n\n﴿ثُقِفُوٓاْ﴾: وُجِدُوا.\n\n﴿إِلَّا بِحَبۡلࣲ مِّنَ ٱللَّهِ﴾: إلا بعَهْدٍ من الله يأمَنُون به على أنفسِهم.\n\n﴿وَحَبۡلࣲ مِّنَ ٱلنَّاسِ﴾: بذِمَّةٍ من الناسِ.\n\n﴿وَبَآءُو﴾: واستحَقُّوا غَضَبَ اللهِ.\n\n﴿ٱلۡمَسۡكَنَةُ﴾: ذُلُّ الفاقةِ والفقرِ."],[113,113,"﴿أُمَّةࣱ قَآئِمَةࣱ﴾: جماعةٌ ثابتةٌ على الحقِّ.\n\n﴿ءَانَآءَ ٱلَّيۡلِ﴾: جَمْعُ إنى، وهي ساعاتُه."],[115,115,"﴿فَلَن يُكۡفَرُوهُ﴾: فلن يُعْدَمُوا ثوابَه."],[116,116,"﴿لَن تُغۡنِيَ﴾: لن تَدْفَعَ عنهم.\n\n﴿مِّنَ ٱللَّهِ﴾: من عذابِ اللهِ."],[117,117,"﴿مَا يُنفِقُونَ﴾: في وجوهِ الخيرِ.\n\n﴿صِرٌّ﴾: بَرْدٌ شديدٌ.\n\n﴿أَصَابَتۡ حَرۡثَ قَوۡمࣲ﴾: هَبَّتْ علىَ زَرْعِ قومٍ كانوا يَرْجُون خيرَه. وكذلك إنفاقُ الكافرِ لا ينفَعُه."],[118,118,"﴿بِطَانَةࣰ مِّن دُونِكُمۡ﴾: أصفياءَ مِن دونِ المؤمنين، تُطْلِعُونَهم على أسرارِكم.\n\n﴿لَا يَأۡلُونَكُمۡ خَبَالࣰا﴾: لا يُقَصِّرُون في إفسادِ حالِكم.\n\n﴿مَا عَنِتُّمۡ﴾: مَشَقَّتَكم.\n\n﴿ٱلۡـَٔايَـٰتِ﴾:: الحُجَجَ."],[119,119,"﴿وَتُؤۡمِنُونَ بِٱلۡكِتَـٰبِ كُلِّهِۦ﴾: وتؤمنون بالكُتُبِ المنَّزلَةِ كلها، وهم لا يُؤمنون بكتابِكم.\n\n﴿مِنَ ٱلۡغَيۡظِ﴾: من شِدَّةِ الغَضَبِ."],[120,120,"﴿كَيۡدُهُمۡ﴾: أذى مَكْرِهم."],[121,121,"﴿غَدَوۡتَ مِنۡ أَهۡلِكَ﴾: خَرَجْتَ من بيتِك يومَ أُحُدٍ.\n\n﴿تُبَوِّئُ ٱلۡمُؤۡمِنِينَ﴾: تَتَّخِذُ لهم."],[122,122,"﴿طَّآئِفَتَانِ﴾: هما بنو سَلِمَةَ وبنو حارثةَ، حَدَّثَتْهم أنفسُهم يومَ أُحُدٍ بالرُّجوعِ عن لقاءِ العدوِّ، ولكنَّ اللهَ عَصَمَهم.\n\n﴿تَفۡشَلَا﴾: تَجْبُنا.\n\n﴿وَلِيُّهُمَا﴾: الدافعُ عنهما الضَّعْفَ."],[123,123,"﴿أَذِلَّةࣱ﴾: قليلو العَدَدِ والعُدَّةِ."],[124,124,"﴿مُنزَلِينَ﴾: من السماءِ يُقاتِلون معكم."],[125,125,"﴿وَيَأۡتُوكُم﴾: ويأتي كفارُ مكةَ لقتالِكم.\n\n﴿مِّن فَوۡرِهِمۡ هَـٰذَا﴾: مِن ساعَتِهم هذه.\n\n﴿مُسَوِّمِينَ﴾: مُعْلِمِين أنفسَهم بعلاماتٍ واضِحاتٍ."],[126,126,"﴿وَمَا جَعَلَهُ﴾: وما جَعَلَ هذا الإمدادَ بالملائكةِ."],[127,127,"﴿لِيَقۡطَعَ طَرَفࣰا﴾: ليُهلِكَ فريقًامن الكفّارِ بالقَتْلِ.\n\n﴿أَوۡ يَكۡبِتَهُمۡ﴾: أو يُغِيظَهم، ويُحْزِنَهم.\n\n﴿فَيَنقَلِبُواْ خَآئِبِينَ﴾: فيعودُوا غيرَ ظافِرين بمَطْلَبِهم."],[130,130,"﴿أَضۡعَـٰفࣰا مُّضَـٰعَفَةࣰ﴾: كانوا في الجاهليةِ إذا حانَ موعِدُ السَّدادِ يقولُ المقترضُ: أخِّرْ عني، وأَزِيدُك."],[134,134,"﴿ٱلسَّرَّآءِ﴾: في اليُسْرِ وسَعَةِ العيشِ.\n\n﴿وَٱلضَّرَّآءِ﴾: الضِّيقِ والشدةِ.\n\n﴿وَٱلۡكَـٰظِمِينَ﴾: الذين يُمْسِكون مافي أنفسِهم من الغيظِ بالصبر.\n\n﴿وَٱلۡعَافِينَ﴾: والذين يَصْفَحُون عمَّن ظَلَمَهم."],[135,135,"﴿فَـٰحِشَةً﴾: هي الفعْلَةُ القبيحةُ الخارجةُ عَمّا أذِنَ اللهُ.\n\n﴿ظَلَمُوٓاْ أَنفُسَهُمۡ﴾: بارتكابِ مادونَ الفاحشةِ.\n\n﴿ذَكَرُواْ ٱللَّهَ﴾: ذكَروا وعيدَه على المعصية.\n\n﴿وَلَمۡ يُصِرُّواْ﴾: ولم يَثْبُتوا على ما أتَوا من الذُّنوبِ.\n\n﴿وَهُمۡ يَعۡلَمُونَ﴾: قُبْحَه."],[136,136,"﴿أَجۡرُ ٱلۡعَـٰمِلِينَ﴾: ثوابُ المطيعين."],[137,137,"﴿خَلَتۡ﴾: مضَتْ.\n\n﴿سُنَنࣱ﴾: ماسَنَّه اللهُ في الأممِ المكذِّبة والسُّنَّةُ: المثالُ المُتَّبَعُ.\n\n﴿عَـٰقِبَةُ ٱلۡمُكَذِّبِينَ﴾: قد أُمْهِلُ المكذِّبين وأسْتَدْرِجُهم إلى أجَلٍ، ثم أُحِلُّ بهم عُقوبتي، وهذا ماحدَث مع المشركين يومَ أُحُدٍ."],[138,138,"﴿هَـٰذَا﴾: الذي أوضَحْتُه لكم بما تَقَدَّم أو القرآنُ."],[139,139,"﴿وَلَا تَهِنُواْ﴾: ولا تضْعُفُوا بالذي نالَكم يومَ أُحُدٍ.\n\n﴿ٱلۡأَعۡلَوۡنَ﴾: الغالِبُون على عَدُوِّكم بالنصرِ."],[140,140,"﴿قَرۡحࣱ﴾: جِراْحٌ وقَتْلٌ يومَ أُحُد.\n\n﴿مِّثۡلُهُۥ﴾: يومَ بدرٍ.\n\n﴿نُدَاوِلُهَا﴾: يُصَرِّفُها اللهُ، فيظفَرُ المؤمنُ بالكافر، والكافرُ بالمؤمن.\n\n﴿وَيَتَّخِذَ مِنكُمۡ شُهَدَآءَ﴾: ويُكَرِّمَ أقوامًا بالشهادةِ."],[141,141,"﴿وَلِيُمَحِّصَ﴾: ولِيَخْتبرَ.\n\n﴿وَيَمۡحَقَ﴾: ويُهْلِكَهم."],[142,142,"﴿وَلَمَّا يَعۡلَمِ﴾: أي: عِلْمًا ظاهرًا للخَلْقِ."],[143,143,"﴿ٱلۡمَوۡتَ﴾: أسبابَه. وكان قومٌ من الصَّحابة مِمَّنْ لم يَشْهدوا بدرًا تمنَّوا أن يجاهِدُوا.\n\n﴿فَقَدۡ رَأَيۡتُمُوهُ﴾: حَصَلَ ذلك يومَ أُحُدٍ، ولكن فَرَّ بعضُهم، وصَبَر بعضُهم."],[144,144,"﴿خَلَتۡ﴾: مَضَتْ، فسوف يَقْبِضُه اللهُ إليه عند انقضاءِ أجَلِه.\n\n﴿ٱنقَلَبۡتُمۡ عَلَىٰٓ أَعۡقَـٰبِكُمۡ﴾: ارتَددْتُم عن دينِكم.\n\n﴿فَلَن يَضُرَّ ٱللَّهَ﴾: فلن يُوهِنَ ذلك عزةَ اللهِ ولا سُلطانَه، وإنما يَضُرُّ نفسَه.\n\n﴿ٱلشَّـٰكِرِينَ﴾: على نِعْمَةِ الإسلامِ، الثابتين على دينِهم."],[145,145,"﴿بِإِذۡنِ ٱللَّهِ﴾: بقَدَرِه حتى يَسْتوفيَ مُدَّتَه.\n\n﴿كِتَـٰبࣰا﴾: كَتَبَ اللهُ ذلك كتابًا.\n\n﴿مُّؤَجَّلࣰا﴾: مؤقتًا لا يتقدَّمُ على أجَلهِ ولا يتأخَّرُ.\n\n﴿نُؤۡتِهِۦ مِنۡهَا﴾: أي: ما قُسِم له فيها من رزقٍ."],[146,146,"﴿وَكَأَيِّن﴾: كثيرٌ.\n\n﴿رِبِّيُّونَ كَثِيرࣱ﴾: جموعٌ كثيرةٌ من أصحابِهم، أو علماءُ.\n\n﴿وَهَنُواْ﴾: ضَعُفُوا.\n\n﴿وَمَا ٱسۡتَكَانُواْ﴾: ما ذَلُّوا لعَدُوِّهم."],[147,147,"﴿وَإِسۡرَافَنَا﴾: من الذُّنوبِ الكَبائرِ."],[148,148,"﴿ثَوَابَ ٱلدُّنۡيَا﴾: بالنصر، والتمكينِ في الأرض.\n\n﴿وَحُسۡنَ ثَوَابِ ٱلۡـَٔاخِرَةِ﴾: وخيرَ جزاءِ الآخرةِ.\n\n﴿وَٱللَّهُ يُحِبُّ ٱلۡمُحۡسِنِينَ﴾: مَن أحسنَ عبادتَه لربِّه."],[149,149,"﴿يَرُدُّوكُمۡ عَلَىٰٓ أَعۡقَـٰبِكُمۡ﴾: يُضِلُّوكم عن طريقِ الحقِّ."],[150,150,"﴿مَوۡلَىٰكُمۡ﴾: ناصِرُكم."],[151,151,"﴿سَنُلۡقِي فِي قُلُوبِ ٱلَّذِينَ كَفَرُواْ ٱلرُّعۡبَ﴾: لأنّ المشركين عَزَمُوا على استئصالِ المسلمين بعد أُحُدٍ، ولكنَّ اللهَ قَذَفَ فيهم الرُّعْبَ، فرجَعوا عَمّا هَمُّوا به.\n\n﴿سُلۡطَـٰنࣰا﴾: دليلًا على استحقاقِها العبادةَ.\n\n﴿مَثۡوَى﴾: مكانُ الإقامةِ."],[152,152,"﴿صَدَقَكُمُ ٱللَّهُ وَعۡدَهُۥٓ﴾: حَقَّقَ ما وعَدَكم مِن نَصْرٍ في أُحُدٍ قبلَ تَرْكِ الرُّماةِ مقاعِدَهم.\n\n﴿تَحُسُّونَهُم﴾: تستأصِلُونهم بالقَتْلِ.\n\n﴿فَشِلۡتُمۡ﴾: جَبُنتم. وجواب «إذا» مقدرٌ: امتُحِنْتُم.\n\n﴿وَتَنَـٰزَعۡتُمۡ﴾: اختلَفْتم: هل تَبْقَون في مَواقِعِكم، أو تتركونها للغَنائم؟\n\n﴿صَرَفَكُمۡ﴾: رَدَّكم عنهم بالهزيمةِ.\n\n﴿لِيَبۡتَلِيَكُمۡ﴾: ليَخْتَبِرَكم."],[153,153,"﴿تُصۡعِدُونَ﴾: تَسِيرون في مستوى الأرضِ وبُطونِ الأوديةِ هاربين.\n\n﴿وَلَا تَلۡوُۥنَ﴾: لاتَلْتَفِتُون إلى أحَدٍ.\n\n﴿فِيٓ أُخۡرَىٰكُمۡ﴾: في الطائفةِ المتأخرةِ.\n\n﴿فَأَثَـٰبَكُمۡ﴾: فجازاكم.\n\n﴿غَمَّۢا بِغَمࣲّ﴾: الغَمُّ الأولُ ما أُشيعَ من قَتْل الرسولِ ﷺ، والثاني: ما نالهم من القَتْلِ والجِراحِ.\n\n﴿عَلَىٰ مَا فَاتَكُمۡ﴾: من نَصْرٍ وغنيمةٍ. وفَعَلَ بكم ذلك تدريبًا لاحتمالِ الشدائدِ."],[154,154,"﴿أَمَنَةࣰ﴾: أمانًا.\n\n﴿طَآئِفَةࣰ مِّنكُمۡ﴾: هم أهلُ الإخلاصِ.\n\n﴿أَهَمَّتۡهُمۡ أَنفُسُهُمۡ﴾: خَلاصُ أنفسِهم من القَتْلِ، وهم المنافقون.\n\n﴿ظَنَّ ٱلۡجَـٰهِلِيَّةِ﴾: بأنّ الإسلامَ لن تقومَ له قائمةٌ.\n\n﴿هَل لَّنَا مِنَ ٱلۡأَمۡرِ مِن شَيۡءࣲ﴾: هل كان لنا من اختيارٍ في الخروجِ للقتالِ؟\n\n﴿يُخۡفُونَ﴾: من الحَسْرةِ على خروجِهم للقتالِ.\n\n﴿إِلَىٰ مَضَاجِعِهِمۡ﴾: إلى المواضع التي كُتِبَ عليهم أنْ يُقْتَلَوا فيها.\n\n﴿مَا فِي صُدُورِكُمۡ﴾: من الشَّكِّ، والنفاق.\n\n﴿وَلِيُمَحِّصَ﴾: ليمِيزَ الخبيثَ من الطَّيِّبِ."],[155,155,"﴿تَوَلَّوۡاْ﴾: فَرُّوا.\n\n﴿ٱلۡتَقَى ٱلۡجَمۡعَانِ﴾: أي: يومَ أُحُدٍ، والجَمْعان: المؤمنون، والمشركون.\n\n﴿ٱسۡتَزَلَّهُمُ﴾: أوْقَعَهم.\n\n﴿مَا كَسَبُواْ﴾: من الذُّنوبِ."],[156,156,"﴿كَٱلَّذِينَ كَفَرُواْ﴾: من المنافقين.\n\n﴿ضَرَبُواْ فِي ٱلۡأَرۡضِ﴾: سَفَرًا للبحث عن معاشِهم فماتوا.\n\n﴿غُزࣰّى﴾: غازين.\n\n﴿ذَ ٰ⁠لِكَ﴾: هذا القولُ."],[157,157,"﴿مِّمَّا يَجۡمَعُونَ﴾: ممّا يجْمَعُه أهلُ الدنيا."],[159,159,"﴿فَبِمَا رَحۡمَةࣲ﴾: فبرحمةٍ.\n\n﴿فَظًّا﴾: سَيِّئَ الخُلُقِ جافيًا.\n\n﴿لَٱنفَضُّواْ﴾: لَتَفرَّقُوا عنك.\n\n﴿وَشَاوِرۡهُمۡ﴾: لتقتديَ بك الأمةُ، وذلك في غير ما ورَدَ به الشَّرعُ.\n\n﴿فَإِذَا عَزَمۡتَ﴾: عَقِبَ المُشاورةِ، وقَصَدْتَ إمضاءَ الأمرِ."],[161,161,"﴿أَن يَغُلَّ﴾: أن يَخُونَ أصحابَه بأن يأخذَ من الغنيمةِ غيرَ ما اخْتَصَّه اللهُ.\n\n﴿بِمَا غَلَّ﴾: بما أخَذَه حاملًا له ليُفضحَ به."],[162,162,"﴿كَمَنۢ بَآءَ بِسَخَطࣲ﴾: كمَن رَجَعَ بغضبٍ شديدٍ."],[163,163,"﴿هُمۡ دَرَجَـٰتٌ﴾: ذوو دَرَجاتٍ، فدَرجاتُ مَنِ اتَّبعَ رضوانَه ليسَتْ كدرجاتِ الآخَرين."],[164,164,"﴿مَنَّ﴾: أنعمَ.\n\n﴿مِّنۡ أَنفُسِهِمۡ﴾: من أهلِ لسانِهم.\n\n﴿وَيُزَكِّيهِمۡ﴾: ويُطَهِّرُهم.\n\n﴿وَٱلۡحِكۡمَةَ﴾: والسُّنَّةَ.\n\n﴿وَإِن كَانُواْ﴾: وإنّهم كانوا."],[165,165,"﴿مُّصِيبَةࣱ﴾: يومَ أُحدٍ.\n\n﴿أَصَبۡتُم مِّثۡلَيۡهَا﴾: يومَ بدرٍ من المشركين.\n\n﴿أَنَّىٰ هَـٰذَا﴾: كيف يكونُ هذا، ونحن مسلمون فينا نبيُّ اللهِ؟\n\n﴿مِنۡ عِندِ أَنفُسِكُمۡ﴾: عقوبةٌ لكم بسببِ مخالفتِكم أمْرَ رسولِكم."],[166,166,"﴿يَوۡمَ ٱلۡتَقَى ٱلۡجَمۡعَانِ﴾: يومَ أُحُدٍ.\n\n﴿فَبِإِذۡنِ ٱللَّهِ﴾: بعِلْمِه."],[167,167,"﴿ٱدۡفَعُواْ﴾: كونوا عَوْنًا لنا بتكثيرِكم سَوادَنا."],[168,168,"﴿لَوۡ أَطَاعُونَا﴾: بتَرْكِ الخروجِ من المدينةِ.\n\n﴿فَٱدۡرَءُواْ﴾: فادفَعُوا."],[169,169,"﴿أَحۡيَآءٌ﴾: حياةً بَرْزَخيةً.\n\n﴿عِندَ رَبِّهِمۡ﴾: في الجنةِ."],[170,170,"﴿وَيَسۡتَبۡشِرُونَ﴾: ويَفْرحون.\n\n﴿أَلَّا خَوۡفٌ عَلَيۡهِمۡ﴾: فيما يَسْتقبلون من أمورِ الآخرةِ.\n\n﴿وَلَا هُمۡ يَحۡزَنُونَ﴾: على مافاتَهم في الدنيا."],[172,172,"﴿ٱلَّذِينَ ٱسۡتَجَابُواْ﴾: هم الذين خرجُوا يَتَعَقَّبون المشركين في «حمراءِ الأسَدِ»، بعد هزيمتِهم في أُحُدٍ.\n\n﴿ٱلۡقَرۡحُ﴾: الجراحُ من معركةِ أُحُدٍ."],[173,173,"﴿قَالَ لَهُمُ ٱلنَّاسُ﴾: هم بعضُ المشركين، قالوا: إن أبا سفيان ومَن معه سيعودون إليكم.\n\n﴿حَسۡبُنَا ٱللَّهُ﴾: اللهُ كافِينا."],[174,174,"﴿فَٱنقَلَبُواْ﴾: فرَجَعُوا من حمراءِ الأسَدِ."],[175,175,"﴿يُخَوِّفُ أَوۡلِيَآءَهُۥ﴾: يُخَوِّفُكم بأوليائِه."],[176,176,"﴿حَظࣰّا﴾: نصيبًا."],[177,177,"﴿ٱشۡتَرَوُاْ﴾: استبدلُوا."],[178,178,"﴿وَلَا يَحۡسَبَنَّ ٱلَّذِينَ كَفَرُوٓاْ﴾: إذا أطَلْنا أعمارَهم، ومَتَّعْناهم.\n\n﴿إِنَّمَا نُمۡلِي لَهُمۡ﴾: نُؤَخِّرُ أجَلَهم، وعذابَهم.\n\n﴿إِثۡمࣰا﴾: ظلمًا وطُغيانًا."],[179,179,"﴿لِيَذَرَ﴾: لِيَدَعَ.\n\n﴿عَلَىٰ مَآ أَنتُمۡ عَلَيۡهِ﴾: من التباسِ المؤمن مِنكم بالمنافقِ.\n\n﴿عَلَى ٱلۡغَيۡبِ﴾: الذي يَعْلَمُه من عبادِه، فتَعْرِفُوا المؤمنَ منهم من المنافقِ، ولكنه يَمِيزُهم بالمِحَنِ.\n\n﴿يَجۡتَبِي﴾: يَصْطَفي مِن رُسُله ليُطْلِعَه على شيءٍ من غيبهِ."],[180,180,"﴿سَيُطَوَّقُونَ﴾: سيكونُ طَوْقًا من نارٍ يُوضَعُ في أعناقِهم."],[181,181,"﴿ٱلَّذِينَ قَالُوٓاْ﴾: هم اليهودُ.\n\n﴿إِنَّ ٱللَّهَ فَقِيرࣱ﴾: يَطْلبُ منا أن نُقْرِضَه مالًا، وهذا للتشكيكِ على المسلمين."],[182,182,"﴿بِمَا قَدَّمَتۡ أَيۡدِيكُمۡ﴾: من المعاصي."],[183,183,"﴿عَهِدَ إِلَيۡنَآ﴾: في التوراةِ.\n\n﴿بِقُرۡبَانࣲ﴾: بصَدَقَةٍ يُتَقَرَّبُ بها إلى الله، فتنزلُ نارٌ من السماءِ فتحرقُها."],[184,184,"﴿بِٱلۡبَيِّنَـٰتِ﴾: بالمعجزاتِ الواضحاتِ.\n\n﴿وَٱلزُّبُرِ﴾: الكتبِ التي أنزلها اللهُ."],[185,185,"﴿مَتَـٰعُ ٱلۡغُرُورِ﴾: مُتْعَةٌ زائلةٌ، فلا تَغْترُّوا بها."],[186,186,"﴿لَتُبۡلَوُنَّ﴾: لَتُخْتَبَرُنَّ.\n\n﴿فِيٓ أَمۡوَ ٰ⁠لِكُمۡ﴾: بإخراجِ النفقاتِ الواجبةِ والمُسْتَحَبَّةِ، وبالجوائح التي تُصيبها.\n\n﴿وَأَنفُسِكُمۡ﴾: بما يجبُ عليكم من الطاعاتِ، وما يَحُلُّ بكم من الجِراح، وفَقْدِ الأحبابِ.\n\n﴿مِنۡ عَزۡمِ ٱلۡأُمُورِ﴾: من الأمورِ التي يُتنافَسُ فيها."],[187,187,"﴿مِيثَـٰقَ﴾: العهدَ المُوَثَّقَ.\n\n﴿فَنَبَذُوهُ﴾: تركُوا العملَ به\n\n﴿وَٱشۡتَرَوۡاْ بِهِۦ ثَمَنࣰا قَلِيلࣰا﴾: أخذُوا ثمنًا بَخْسًا مقابلَ كِتْمانِهم الحقَّ، وتحريفِهم كتبَهم."],[188,188,"﴿ٱلَّذِينَ يَفۡرَحُونَ﴾: أهلَ الكتابِ ومَن كان مثلَهم من الذين أخَذَ ميثاقَهم.\n\n﴿بِمَآ أَتَواْ﴾: بكِتْمانهم أنّ النبيَّ ﷺ مُرْسَلٌ بالحقِّ.\n\n﴿بِمَفَازَةࣲ﴾: بمَنجاةٍ."],[190,190,"﴿وَٱخۡتِلَـٰفِ ٱلَّيۡلِ وَٱلنَّهَارِ﴾: في تَعاقُبِهِما واختلافِهما طُولًا وقِصَرًا.\n\n﴿لَـَٔايَـٰتࣲ﴾: لَدلائلَ.\n\n﴿ٱلۡأَلۡبَـٰبِ﴾: العقولِ السليمةِ."],[191,191,"﴿وَيَتَفَكَّرُونَ﴾: ويتدبَّرون.\n\n﴿بَـٰطِلࣰا﴾: عَبَثًا.\n\n﴿سُبۡحَـٰنَكَ﴾: نُنَزِّهُك."],[192,192,"﴿أَخۡزَيۡتَهُۥ﴾: أهَنْتَه، وهو الخالدُ فيها."],[193,193,"﴿مُنَادِيࣰا﴾: هو محمدٌ ﷺ.\n\n﴿ٱلۡأَبۡرَارِ﴾: الصالحين."],[194,194,"﴿وَلَا تُخۡزِنَا﴾: ولاتَفْضَحْنا بذنوبِنا."],[195,195,"﴿بَعۡضُكُم مِّنۢ بَعۡضࣲ﴾: هم سَواءُ في الجزاءِ على العملِ."],[196,196,"﴿لَا يَغُرَّنَّكَ تَقَلُّبُ ٱلَّذِينَ كَفَرُواْ﴾: لا تَغْتَرَّ بما عليه أهلُ الكفرِ من تَصَرُّفِهم في الأرضِ وضَرْبِهم فيها."],[197,197,"﴿مَأۡوَىٰهُمۡ﴾: مصيرُهم.\n\n﴿ٱلۡمِهَادُ﴾: الفِراشُ والمَضْجَعُ."],[198,198,"﴿نُزُلࣰا﴾: هوما يُهَيَّأ للنَّزيلِ ضِيافةً."],[199,199,"﴿ثَمَنࣰا قَلِيلًا﴾: من حُطامِ الدُّنيا، فلايكتُمون ما أنزلَ اللهُ ولايُحَرِّفُونه."],[200,200,"﴿وَصَابِرُواْ﴾: أي غالِبُوا أعداءَكم في الصَّبْرِ.\n\n﴿وَرَابِطُواْ﴾: وأقِيمُوا على جهادِ العَدُوِّ."]]);
QTF("gharib",4,[[1,1,"﴿مِّن نَّفۡسࣲ وَ ٰ⁠حِدَةࣲ﴾: هي آدَمُ.\n\n﴿زَوۡجَهَا﴾: هي حَوّاءُ، خُلِقَتْ من ضِلْعٍ من أضلاعِ آدمَ.\n\n﴿وَبَثَّ مِنۡهُمَا﴾: نَشَر من آدمَ وحَواءَ.\n\n﴿تَسَآءَلُونَ بِهِۦ﴾: يَسْألُ به بعضُكم بعضًا، فيقولُ السائلُ: أسألُك باللهِ.\n\n﴿وَٱلۡأَرۡحَامَ﴾: واتقوا الأرحامَ أن تقطعُوها."],[2,2,"﴿وَءَاتُواْ﴾: وأَعطُوا يا أوصياءَ اليتامى.\n\n﴿ٱلۡيَتَـٰمَىٰٓ﴾: هم مَن ماتَ آباؤهم وهم دونَ البلوغ. وإعطاؤُهم المالَ إذا وصَلُوا سِنَّ البُلوغِ، وأصبح لديهم قُدْرَةٌ على حِفْظِ المالِ.\n\n﴿وَلَا تَتَبَدَّلُواْ ٱلۡخَبِيثَ بِٱلطَّيِّبِ﴾: ولا تأخُذوا الجيِّدَ من أموالهِم، وتجعلُوا مكانَه الرديءَ من أموالِكم.\n\n﴿وَلَا تَأۡكُلُوٓاْ أَمۡوَ ٰ⁠لَهُمۡ إِلَىٰٓ أَمۡوَ ٰ⁠لِكُمۡ﴾: ولا تَخْلِطُوا أموالَهم بأموالِكم، فتأكلُوها مع أموالِكم.\n\n﴿حُوبࣰا﴾: إثْمًا وظُلمًا."],[3,3,"﴿تُقۡسِطُواْ﴾: تَعْدِلُوا.\n\n﴿فِي ٱلۡيَتَـٰمَىٰ﴾: في يَتامى النساءِ اللاتي تحتَ أيديكم بألّا تُعْطُوهنَّ مهورَهنَّ كغيرِهنَّ، فلا تَنْكِحُوهن، وانكِحُوا غيرَهن.\n\n﴿طَابَ﴾: حَلَّ.\n\n﴿أَدۡنَىٰٓ أَلَّا تَعُولُواْ﴾: أقربُ إلى ألّا تَجُوروا، ولا تَميلوا."],[4,4,"﴿صَدُقَـٰتِهِنَّ﴾: مُهورِهنَّ.\n\n﴿نِحۡلَةࣰ﴾: عَطِيةً واجبةً.\n\n﴿شَيۡءࣲ مِّنۡهُ﴾: شيءٍ من المَهْرِ، فوَهَبْنَه لكم."],[5,5,"﴿ٱلسُّفَهَآءَ﴾: المضَيِّعين لما لِهم بسوءِ تَدْبيرِهم.\n\n﴿قِيَـٰمࣰا﴾: قِوامَكم في مَعايِشكم."],[6,6,"﴿وَٱبۡتَلُواْ﴾: واختبِرُوهم لمعرفةِ قُدُراتِهم.\n\n﴿بَلَغُواْ ٱلنِّكَاحَ﴾: وصَلُوا إلى سِنِّ البلوغِ.\n\n﴿ءَانَسۡتُم مِّنۡهُمۡ رُشۡدࣰا﴾: عَلِمْتُمْ منهم صَلاحًا في العقلِ والدِّين.\n\n﴿إِسۡرَافࣰا﴾: بغيرِ ما أباحَه اللهُ لكم.\n\n﴿وَبِدَارًا﴾: ومُبادرةً لأَكْلِها.\n\n﴿أَن يَكۡبَرُواْ﴾: قبل أن يكبَرُوا فيأ خُذُوها منكم.\n\n﴿بِٱلۡمَعۡرُوفِ﴾: بقَدْرِ حاجتِه عند الضرورةِ على وجْه القَرْضِ.\n\n﴿فَأَشۡهِدُواْ﴾: بأَنْ يَشْهَدَ شهودٌ معكم.\n\n﴿حَسِيبࣰا﴾: محاسِبًا."],[7,7,"﴿لِّلرِّجَالِ﴾: للذُّكورِ من أولادِ الميتِ صغارًا وكبارًا."],[8,8,"﴿أُوْلُواْ ٱلۡقُرۡبَىٰ﴾: ممَّن لا حَقَّ لهم في التَّرِكَةِ.\n\n﴿فَٱرۡزُقُوهُم مِّنۡهُ﴾: على وجهِ الاستحبابِ."],[9,9,"﴿فَلۡيَتَّقُواْ ٱللَّهَ﴾: في ذلك النهيُ عن الإجحافِ بالورثةِ الضعفاءِ، فلايزيدُ في وصيَّتِه لغيرِهمِ على الثلث، وكذلك إنْ تَرَكهم أغنياءَ حَسُنَ أن يُوصيَ لغيرِهم."],[10,10,"﴿سَعِيرࣰا﴾: نارًا مُوقدةً."],[11,11,"﴿لِلذَّكَرِ مِثۡلُ حَظِّ ٱلۡأُنثَيَيۡنِ﴾: إذا لم يكن هناك وارثٌ غيرُ أولادِه.\n\n﴿فَلِأُمِّهِ ٱلثُّلُثُ﴾: ولأبيه الباقي.\n\n﴿مِنۢ بَعۡدِ وَصِيَّةࣲ﴾: هذه القِسْمَةُ للتَّرِكَةِ بعد إخراجِ وصيةِ الميتِ بما لايتجاوزُ الثلثَ."],[12,12,"﴿لَّهُنَّ وَلَدࣱ﴾: ذكرًا أو أنثى.\n\n﴿مِنۢ بَعۡدِ وَصِيَّةࣲ﴾: من بعدِ إنفاذِ وصِيَّتِهنّ الجائزةِ.\n\n﴿لَّكُمۡ وَلَدࣱ﴾: ذَكَرًا أو أنثى، منهن، أو من غيرِهنّ.\n\n﴿كَلَـٰلَةً﴾: هو الميتُ الذي لا ولَدَ له ولا والدَ\n\n﴿أَخٌ أَوۡ أُخۡتࣱ﴾: من أُمّ.\n\n﴿غَيۡرَ مُضَآرࣲّ﴾: لا ضَرَرَ فيه على الوَرَثَةِ، فإنْ قَصَدَ صاحبُها الضَّرَرَ لوَرَثَتِه فهو باطلٌ لا يَنْفُذُ."],[14,14,"﴿مُّهِينࣱ﴾: مُخْزٍ."],[15,15,"﴿ٱلۡفَـٰحِشَةَ﴾: الزِّنى.\n\n﴿فَأَمۡسِكُوهُنَّ﴾: فاحبِسُوهُنَّ، وكان هذا قبل نَسْخِها.\n\n﴿سَبِيلࣰا﴾: مَخْرَجًا، والسبيلُ هو: الحُكْمُ بالرَّجْمِ للمُحْصَنِ والمحصَنةِ، والجلْدِ مئةَ جَلْدَةٍ، وتَغْريبِ عامٍ لغيرهما."],[16,16,"﴿يَأۡتِيَـٰنِهَا﴾: أي: فاحشةَ الزِّنى.\n\n﴿فَـَٔاذُوهُمَا﴾: بالضَّرْبِ، والهَجْرِ والتوبيخِ، ثم نُسِخَ بالجلْدِ والرَّجْمِ."],[17,17,"﴿عَلَى ٱللَّهِ﴾: فهو الذي يقبَلُها.\n\n﴿بِجَهَـٰلَةࣲ﴾: بجَهْلٍ منهم لعاقِبَتِها، وإيجابِها لسَخَطِ اللهِ."],[19,19,"﴿كَرۡهࣰا﴾: هُنَّ كارهاتٌ لذلك، وكانوا في الجاهليَّةِ يجعلون نِساءَ الآباءِ والأقاربِ من التَّرِكَةِ، فيتزوَّجُون بهنَّ.\n\n﴿وَلَا تَعۡضُلُوهُنَّ﴾: لا يَحِلُّ لكم أن تَحْبِسُوا زوجاتِكم عندَكم مع عَدَمِ رغبتِكم فيهن، وذلك لقَصْدِ أن يفتَدِينَ ببعضِ المهْرِ من الحبْسِ.\n\n﴿بِفَـٰحِشَةࣲ مُّبَيِّنَةࣲ﴾: بالزِّنى البيِّنِ، أو بذاءةِ اللسانِ، أو النُّشوزِ."],[20,20,"﴿إِحۡدَىٰهُنَّ﴾: هي مَن تُريدون طَلاقَها.\n\n﴿قِنطَارࣰا﴾: مالًا كثيرًا مَهْرًا لها.\n\n﴿بُهۡتَـٰنࣰا﴾: ظُلمًا بغيرِ حَقّ."],[21,21,"﴿أَفۡضَىٰ﴾: بالجِماعِ.\n\n﴿مِّيثَـٰقًا غَلِيظࣰا﴾: إمساكَهُنَّ بمعروفٍ، أو تَسْرِيحَهُنَّ بإحسانٍ."],[22,22,"﴿سَلَفَ﴾: مضى في الجاهلية، فلا مُؤاخَذَةَ فيه.\n\n﴿وَمَقۡتࣰا﴾: وبُغْضًا، أي: يُبْغِضُ اللهُ فاعلَه."],[23,23,"﴿أُمَّهَـٰتُكُمۡ﴾: ويَدْخُلُ فيه الجَدّاتُ.\n\n﴿وَبَنَاتُكُمۡ﴾: ويشْمَلُ بناتِ الأولادِ.\n\n﴿وَأَخَوَ ٰ⁠تُكُمۡ﴾: الشقيقاتُ، أو لأبٍ، أو لأمّ.\n\n﴿وَأُمَّهَـٰتُ نِسَآئِكُمۡ﴾: سواءٌ أدخَلْتُمْ بنسائكم أم لا.\n\n﴿وَرَبَـٰٓئِبُكُمُ﴾: وبناتُ نسائِكم من غيرِكم، اللاتي يتربَّينَ في بيوتِكم، فإن لم يكونوا كذلك، ولم تَدْخُلوا بأمَّهاتِهن وطَلَّقْتموهن، أو مِتْنَ قبلَ الدُّخولِ، فلا جُناحَ عليكم أن تنكِحُوهنّ.\n\n﴿وَحَلَـٰٓئِلُ أَبۡنَآئِكُمُ﴾: زوجاتُ أبنائِكم ممَّن دَخَلَ الابنُ بها، أو لَم يدْخُلْ."],[24,24,"﴿وَٱلۡمُحۡصَنَـٰتُ﴾: يَحْرُمُ نِكاحُ ذَواتِ الأزواج غيرِ المَسْبِيّات.\n\n﴿مَا مَلَكَتۡ أَيۡمَـٰنُكُمۡ﴾: مَن سَبَيْتم في الجهادِ، فيَحِلُّ النكاحُ بعد الاستِبْراءِ بحَيْضَةٍ، من غير طلاقِ زوجِها الحربيِّ لها.\n\n﴿مَّا وَرَآءَ ذَ ٰ⁠لِكُمۡ﴾: مِن سِواهنّ.\n\n﴿مُّحۡصِنِينَ﴾: أعِفّاءَ.\n\n﴿غَيۡرَ مُسَـٰفِحِينَ﴾: غيرَ زانِين.\n\n﴿أُجُورَهُنَّ﴾: مُهورَهُنَّ وهذا في النِّكاحِ الشَّرْعيِّ.\n\n﴿مِنۢ بَعۡدِ ٱلۡفَرِيضَةِ﴾: من زيادةٍ أو نقصانٍ في المهْرِ، فذلك سائغٌ عند التَّراضي."],[25,25,"﴿طَوۡلًا﴾: قُدرةً وسَعَةً، وهو المَهْرُ لنِكاحِ الحَرائرِ.\n\n﴿بَعۡضُكُم مِّنۢ بَعۡضࣲ﴾: في النسَبِ والدِّينِ.\n\n﴿بِإِذۡنِ أَهۡلِهِنَّ﴾: بموافقةِ سَيّدِهن؛ لأنّ منافعَهنّ له.\n\n﴿أَخۡدَانࣲ﴾: ولا مُسِرّاتٍ بالزِّنى باتخاذِ أصدقاءَ.\n\n﴿فَعَلَيۡهِنَّ﴾: فعلى الإماءِ خمسون جَلْدَةً، ونَفْيُ ستةِ أشهرٍ، وليس على الإماءِ رَجْمٌ لأنه لايَتَنَصَّفُ.\n\n﴿ذَ ٰ⁠لِكَ﴾: أي: ما أُبيحَ لكم من نِكاحِ الإماءِ.\n\n﴿خَشِيَ ٱلۡعَنَتَ﴾: خوفَ الوقوعِ في الزِّنى والمشقَّةِ.\n\n﴿وَأَن تَصۡبِرُواْ﴾: عن نكاحِ الإماء مع العفَّةِ."],[26,26,"﴿سُنَنَ﴾: طُرُقَ الأنبياءِ وأتباعِهم لتَقْتَدُوا بها."],[27,27,"﴿يَتَّبِعُونَ ٱلشَّهَوَ ٰ⁠تِ﴾: يَنْقادُون لشهَواتِ أنفسِهم من أهلِ الباطلِ.\n\n﴿تَمِيلُواْ﴾: تَنْحَرفُوا عن الدِّينِ بإتيانِكم ما حَرَّمَ عليكم."],[28,28,"﴿أَن يُخَفِّفَ﴾: أن يُيَسِّرَ عليكم."],[29,29,"﴿بِٱلۡبَـٰطِلِ﴾: كالرِّبا والقِمار.\n\n﴿تِجَـٰرَةً﴾: موافِقَةً للشَّرعِ.\n\n﴿وَلَا تَقۡتُلُوٓاْ أَنفُسَكُمۡ﴾: بألّا تُهْلِكُوها بارتكابِ المعاصي، وألّا يقتلَ بعضُكم بعضًا، وألّا يقتلَ نفسَه حقيقةً."],[30,30,"﴿ذَ ٰ⁠لِكَ﴾: ما نهى اللهُ عنه مما تقدَّم.\n\n﴿عُدۡوَ ٰ⁠نࣰا﴾: متجاوِزًا حَدَّ الشَّرْعِ."],[31,31,"﴿كَبَآئِرَ مَا تُنۡهَوۡنَ عَنۡهُ﴾: هي كلُّ ذَنْبٍ رَتَّبَ اللهُ عليه الحَدَّ، أو صَرَّح بالوعيدِ فيه.\n\n﴿سَيِّـَٔاتِكُمۡ﴾: الصَّغائرَ.\n\n﴿مُّدۡخَلࣰا كَرِيمࣰا﴾: الجنةَ."],[32,32,"﴿مَا فَضَّلَ ٱللَّهُ بِهِۦ بَعۡضَكُمۡ عَلَىٰ بَعۡضࣲ﴾: ما فَضَّل اللهُ به غيرَكم عليكم في المواهِبِ والأرزاقِ.\n\n﴿نَصِيبࣱ﴾: مقدارٌ من الجزاءِ بحسَبِ العملِ.\n\n﴿مِن فَضۡلِهِۦٓ﴾: من عَوْنِه، وتوفيقِه."],[33,33,"﴿وَلِكُلࣲّ﴾: ولكلِّ واحدٍ.\n\n﴿مَوَ ٰ⁠لِيَ﴾: ورَثَةٌ يرثُون.\n\n﴿عَقَدَتۡ أَيۡمَـٰنُكُمۡ﴾: تحالَفْتُم معهم بالأيمانِ على النُّصرةِ، وإعطائِهم قَدْرًا من الميراثِ، وهذا منسوخٌ."],[34,34,"﴿قَوَّ ٰ⁠مُونَ﴾: أهلُ قيامٍ بمصالحهنَّ.\n\n﴿بِمَا فَضَّلَ ٱللَّهُ﴾: بما خَصَّهم من القِوامةِ والتفضيلِ، كالإنفاقِ وكفايةِ المؤونةِ.\n\n﴿قَـٰنِتَـٰتٌ﴾: مطيعاتٌ لله، قائماتٌ بحقوقِ الزوج.\n\n﴿حَـٰفِظَـٰتࣱ لِّلۡغَيۡبِ﴾: حافظاتٌ لمايَجبُ حِفْظُه عند غَيبةِ أزواجِهنَّ عنهن.\n\n﴿بِمَا حَفِظَ ٱللَّهُ﴾: بحِفْظِ اللهِ، وتوفيقِه لهن.\n\n﴿نُشُوزَهُنَّ﴾: استعلاءَهن على أزواجِهنَّ.\n\n﴿فَعِظُوهُنَّ﴾: بالكلمةِ الطيبةِ، إن نفعَتْ.\n\n﴿ٱلۡمَضَاجِعِ﴾: جَمْعُ مَضْجَع، وهو الفِراشُ، فلا تَقْرَبُوهنَّ، إنْ نَفَعَ ذلك.\n\n﴿وَٱضۡرِبُوهُنَّ﴾: ضَرْبًا غيرَ مُبَرِّحٍ أومؤثِّرٍ.\n\n﴿فَلَا تَبۡغُواْ عَلَيۡهِنَّ سَبِيلًا﴾: فاحذَرُوا ظُلْمَهنَّ."],[35,35,"﴿فَٱبۡعَثُواْ﴾: أي: إلى الزوجَيْن.\n\n﴿حَكَمࣰا﴾: عَدْلًا ممَّنْ يَصْلُحُ لذلك.\n\n﴿بَيۡنَهُمَآ﴾: بينَ الزوجَين، أو الحكَمَين."],[36,36,"﴿وَٱلۡيَتَـٰمَىٰ﴾: الأولادِ الذين ماتَ أباؤُهم وهم دونَ البُلوغ.\n\n﴿وَٱلۡمَسَـٰكِينِ﴾: الذين لا يملِكُون ما يَكْفيهم.\n\n﴿ٱلۡجُنُبِ﴾: البعيدِ.\n\n﴿وَٱلصَّاحِبِ بِٱلۡجَنۢبِ﴾: الرفيقِ في السَّفَر والحَضَرِ.\n\n﴿وَٱبۡنِ ٱلسَّبِيلِ﴾: المسافرِ المحتاجِ.\n\n﴿وَمَا مَلَكَتۡ أَيۡمَـٰنُكُمۡ﴾: الرقيقِ ذكورًا وإناثًا."],[37,37,"﴿وَأَعۡتَدۡنَا﴾: وأَعْدَدْنا.\n\n﴿مُّهِينࣰا﴾: مُخْزِيًا."],[38,38,"﴿رِئَآءَ ٱلنَّاسِ﴾: من أجلِ الرِّياءِ والسُّمعةِ.\n\n﴿قَرِينࣰا﴾: مُلازِمًا له، ويعملُ بطاعتِه."],[39,39,"﴿وَمَاذَا عَلَيۡهِمۡ﴾: وأيُّ ضررٍ يَلْحقهم؟"],[40,40,"﴿لَا يَظۡلِمُ مِثۡقَالَ ذَرَّةࣲ﴾: لا يُنْقِصُ أحدًا من جزاءِ عَمَلِه مقدارَ ذَرّة."],[41,41,"﴿فَكَيۡفَ﴾: فكيف يكون حالُ الناسِ يومَ القيامةِ؟\n\n﴿بِكَ﴾: أيها الرسولُ.\n\n﴿عَلَىٰ هَـٰٓؤُلَآءِ﴾: على أمَّتِك.\n\n﴿شَهِيدࣰا﴾: شاهدًا على الأمَّةِ بما عَمِلت."],[42,42,"﴿تُسَوَّىٰ بِهِمُ ٱلۡأَرۡضُ﴾: يجعلهم الله والأرضَ سواءً، فيصيرون ترابًا.\n\n﴿وَلَا يَكۡتُمُونَ﴾: ولا يُخْفُون عن اللهِ شيئًا، وسوف تَشْهَدُ على عَمَلِهم جَوارحُهم."],[43,43,"﴿وَأَنتُمۡ سُكَـٰرَىٰ﴾: نَزَلَ هذا الحكمُ قبلَ تحريمِ الخمرِ.\n\n﴿عَابِرِي سَبِيلٍ﴾: مَن كان مُجتازًا من باب المسجد، أوهو المسافر.\n\n﴿لَـٰمَسۡتُمُ﴾: جامَعْتُمْ.\n\n﴿فَتَيَمَّمُواْ صَعِيدࣰا طَيِّبࣰا﴾: فاقصِدوا ترابًا طاهرًا."],[44,44,"﴿نَصِيبࣰا مِّنَ ٱلۡكِتَـٰبِ﴾: حَظًّا من العِلْم بالتوراةِ.\n\n﴿ٱلسَّبِيلَ﴾: الطريقَ المستقيمَ."],[45,45,"﴿وَلِيࣰّا﴾: يَتَوَلّاكم."],[46,46,"﴿هَادُواْ﴾: هم اليهودُ.\n\n﴿يُحَرِّفُونَ ٱلۡكَلِمَ﴾: بتغييرِ اللفظِ أو المعنى أو هما جميعًا.\n\n﴿غَيۡرَ مُسۡمَعࣲ﴾: لا سَمِعْتَ، وهذا من قَبيلِ الاستهزاءِ.\n\n﴿وَرَ ٰ⁠عِنَا﴾: افهَمْ عنا، وأفْهِمْنا.\n\n﴿لَيَّۢا بِأَلۡسِنَتِهِمۡ﴾: يَلْوُون ألسنتَهم عن الحق.\n\n﴿وَٱسۡمَعۡ﴾: دونَ «غيرَ مُسْمَعٍ».\n\n﴿وَٱنظُرۡنَا﴾: انتظِرْنا نَفْهَمْ عنك، بَدَلَ «راعِنا».\n\n﴿وَأَقۡوَمَ﴾: وأصوبَ قولًا.\n\n﴿لَّعَنَهُمُ﴾: طَرَدَهم من رحمتِه."],[47,47,"﴿لِّمَا مَعَكُم﴾: من الكُتُبِ.\n\n﴿أَن نَّطۡمِسَ وُجُوهࣰا فَنَرُدَّهَا عَلَىٰٓ أَدۡبَارِهَآ﴾: نَمْحُوَ الوجوهَ، ونجعلَ أبصارَها في أدبارِ الوجوهِ.\n\n﴿أَصۡحَـٰبَ ٱلسَّبۡتِ﴾: هم اليهودُ الذين نُهُوا عن الصَّيدِ في يومِ السبت، فلم يَنْتَهُوا.\n\n﴿مَفۡعُولًا﴾: كائنًا لا محالةَ."],[49,49,"﴿يُزَكُّونَ﴾: يُثْنُون، وهم اليهودُ."],[51,51,"﴿نَصِيبࣰا﴾: حَظًّا.\n\n﴿بِٱلۡجِبۡتِ وَٱلطَّـٰغُوتِ﴾: هما كلُّ معبودٍ من دونِ اللهِ، أو مُطاعٍ في معصيته."],[53,53,"﴿نَصِيبࣱ﴾: حَظٌّ.\n\n﴿فَإِذࣰا لَّا يُؤۡتُونَ﴾: إن جُعِلَ لهم ذلك فإذن لايُعْطُون، لشِدَّةِ بُخْلِهم.\n\n﴿نَقِيرًا﴾: النُّقطةَ في ظَهْر النَّواةِ، أو وسَطِها."],[54,54,"﴿ٱلنَّاسَ﴾: محمدًا وأصحابَه.\n\n﴿فَضۡلِهِۦ﴾: النبوَّةِ، والنصْرِ.\n\n﴿فَقَدۡ ءَاتَيۡنَآ ءَالَ إِبۡرَ ٰ⁠هِيمَ﴾: فكيف لا يَحْسُدون آلَ إبراهيمَ، واليهودُ يعترفون به؟ فما آتينا محمدًا ليس ببِدْعٍ حتى يُحْسَدَ عليه.\n\n﴿ٱلۡحِكۡمَةَ﴾: ما أُوحِي إليهم من غيرِ الكتابِ.\n\n﴿مُّلۡكًا عَظِيمࣰا﴾: مُلْكَ سليمانَ."],[55,55,"﴿سَعِيرًا﴾: نارًا تُوقَدُ عليهم."],[56,56,"﴿نَضِجَتۡ﴾: احترقَتْ."],[57,57,"﴿مُّطَهَّرَةࣱ﴾: من كلِّ دَنَسٍ يكونُ في نساءِ أهلِ الدُّنيا.\n\n﴿ظَلِيلًا﴾: كثيفًا ممتدًّا."],[58,58,"﴿نِعِمَّا﴾: نِعْمَ الشيءُ."],[59,59,"﴿وَأُوْلِي ٱلۡأَمۡرِ﴾: الأئمةَ، ومَن ولّاه المسلمون، مالم يَكُنْ في طاعتِهم معصيةٌ.\n\n﴿فَرُدُّوهُ﴾: أرْجِعُوا الحُكْمَ فيه.\n\n﴿تَأۡوِيلًا﴾: عاقبةً ومَرْجِعًا."],[60,60,"﴿أُنزِلَ إِلَيۡكَ﴾: هوالقرآنُ.\n\n﴿ٱلطَّـٰغُوتِ﴾: غيرِ ما شَرَع الله."],[61,61,"﴿يَصُدُّونَ﴾: يُعْرِضُون."],[62,62,"﴿فَكَيۡفَ﴾: فكيف يكون حالُهم؟\n\n﴿وَتَوۡفِيقًا﴾: بين الخُصومِ."],[63,63,"﴿وَعِظۡهُمۡ﴾: خَوِّفْهم من النِّفاقِ.\n\n﴿بَلِيغࣰا﴾: مُؤَثِّرًا، زاجرًا لهم."],[65,65,"﴿شَجَرَ بَيۡنَهُمۡ﴾: وقَعَ بينَهم من نِزاعٍ.\n\n﴿حَرَجࣰا﴾: ضِيقًا.\n\n﴿وَيُسَلِّمُواْ﴾: ويَنْقادوا."],[66,66,"﴿كَتَبۡنَا﴾: فَرَضْنا.\n\n﴿ٱقۡتُلُوٓاْ أَنفُسَكُمۡ﴾: أن يقتُلَ بعضُكم بعضًا.\n\n﴿مَا يُوعَظُونَ بِهِۦ﴾: مايُنْصَحُون به.\n\n﴿تَثۡبِيتࣰا﴾: تَصْديقًا."],[68,68,"﴿صِرَ ٰ⁠طࣰا﴾: طريقًا."],[71,71,"﴿خُذُواْ حِذۡرَكُمۡ﴾: بالاستعدادِ لعدوِّكم.\n\n﴿ثُبَاتٍ﴾: جَمْعُ ثُبَة، وهي الجماعةُ بعدَ جماعةٍ."],[72,72,"﴿شَهِيدࣰا﴾: حاضِرًا، فيُصِبْني شيءٌ."],[73,73,"﴿كَأَن لَّمۡ تَكُنۢ بَيۡنَكُمۡ وَبَيۡنَهُۥ مَوَدَّةࣱ﴾: كأنه ليس منكم، ولا بينَكم وبينَه مودةُ الإيمانِ؛ حَسَدًا منه."],[74,74,"﴿يَشۡرُونَ﴾: يَبِيعون."],[75,75,"﴿ٱلۡقَرۡيَةِ﴾: مكَّةَ."],[76,76,"﴿ٱلطَّـٰغُوتِ﴾: البَغْيِ والفسادِ في الأرضِ.\n\n﴿كَيۡدَ ٱلشَّيۡطَـٰنِ﴾: تدبيرَه."],[77,77,"﴿كُفُّوٓاْ أَيۡدِيَكُمۡ﴾: لا تُقاتِلوا، وذلك قبلَ الإذنِ بالجِهادِ.\n\n﴿أَجَلࣲ﴾: وقتٍ.\n\n﴿فَتِيلًا﴾: مقدارَ الخيطِ في شِقِّ نَواةِ التمرةِ."],[78,78,"﴿بُرُوجࣲ مُّشَيَّدَةࣲ﴾: حُصونٍ مَنيعةٍ.\n\n﴿مِنۡ عِندِكَ﴾: أيُّها الرسولُ، وهذا من جَهْلِهم."],[79,79,"﴿فَمِن نَّفۡسِكَ﴾: بذَنْبٍ اكْتَسَبْتَه.\n\n﴿شَهِيدࣰا﴾: على صِدْقِ رسالتِك."],[80,80,"﴿تَوَلَّىٰ﴾: أعْرَضَ عن طاعةِ الله ورسولِه.\n\n﴿حَفِيظࣰا﴾: حافظًا لما يعملون، مُحاسِبًا."],[81,81,"﴿طَاعَةࣱ﴾: أمْرُنا طاعةٌ.\n\n﴿بَرَزُواْ﴾: خَرَجُوا.\n\n﴿بَيَّتَ﴾: دَبَّر بلَيْلٍ.\n\n﴿غَيۡرَ ٱلَّذِي تَقُولُ﴾: غيرَ ما أعْلَنُوه من الطاعةِ.\n\n﴿وَكِيلًا﴾: ناصرًا."],[83,83,"﴿جَآءَهُمۡ﴾: جاء هذه الطائفةَ المُبَيِّتَةَ.\n\n﴿أَذَاعُواْ بِهِۦ﴾: أفشَوْه، وأعْلَنُوه.\n\n﴿لَعَلِمَهُ ٱلَّذِينَ يَسۡتَنۢبِطُونَهُۥ﴾: لَعَلِمَ حقيقةَ معناه أهلُ الفقهِ والاستنباطِ منهم، فهم يعلمون ما ينبغي أن يُفْشى، أو يُكْتَمَ."],[84,84,"﴿لَا تُكَلَّفُ إِلَّا نَفۡسَكَ﴾: لا تُلْزَمُ فِعْلَ غيرِك، ولا تُؤاخَذُ به.\n\n﴿وَحَرِّضِ ٱلۡمُؤۡمِنِينَ﴾: وحُضَّهم على الجهادِ.\n\n﴿يَكُفَّ﴾: يَمْنَعَ.\n\n﴿بَأۡسَ﴾: شدَّةَ.\n\n﴿تَنكِيلࣰا﴾: عقوبةً."],[85,85,"﴿شَفَـٰعَةً حَسَنَةࣰ﴾: هي السَّعْيُ لحصولِ الآخَرينَ على الخيرِ.\n\n﴿مِّنۡهَا﴾: نصيبٌ مِن ثوابِها.\n\n﴿كِفۡلࣱ﴾: نَصِيبٌ من إثمِها.\n\n﴿مُّقِيتࣰا﴾: قديرًا، أو حفيظًا شاهدًا."],[86,86,"﴿حَسِيبًا﴾: مُجازِيًا."],[88,88,"﴿فِئَتَيۡنِ﴾: فِرْقَتَين.\n\n﴿أَرۡكَسَهُم﴾: رَدَّهم إلى الكفرِ، وأوقعَهم فيه.\n\n﴿سَبِيلࣰا﴾: طَريقًا."],[89,89,"﴿سَوَآءࣰ﴾: كُفّارًا مِثْلَهم.\n\n﴿أَوۡلِيَآءَ﴾: أصفياءَ.\n\n﴿تَوَلَّوۡاْ﴾: أعرضُوا."],[90,90,"﴿يَصِلُونَ إِلَىٰ قَوۡمِۭ﴾: يَتَّصِلُون بقومٍ.\n\n﴿مِّيثَـٰقٌ﴾: عَهْدٌ.\n\n﴿حَصِرَتۡ﴾: ضاقَتْ.\n\n﴿ٱلسَّلَمَ﴾: الاستسلامَ."],[91,91,"﴿ءَاخَرِينَ﴾: من المنافقين.\n\n﴿ٱلۡفِتۡنَةِ﴾: الشِّركِ.\n\n﴿أُرۡكِسُواْ﴾: ارتَدُّوا، ووَقَعُوا.\n\n﴿يَعۡتَزِلُوكُمۡ﴾: يَنْصَرِفُوا عنكم.\n\n﴿ٱلسَّلَمَ﴾: الاستسلامَ.\n\n﴿ثَقِفۡتُمُوهُمۡ﴾: وجَدْتُموهم.\n\n﴿سُلۡطَـٰنࣰا﴾: حُجَّةً بَيِّنَةً على قَتْلِهِم، أو أسْرِهم."],[92,92,"﴿خَطَـࣰٔا﴾: مِن غيرِ عَمْدٍ.\n\n﴿إِلَّآ أَن يَصَّدَّقُواْ﴾: إلا أن يَتَصدَّقُوا بها عليه، ويَعْفُوا.\n\n﴿مِّيثَـٰقࣱ﴾: عهدٌ."],[94,94,"﴿فَتَبَيَّنُواْ﴾: كُونُوا على بَيِّنَةٍ فيمَن تقتُلونه.\n\n﴿ٱلسَّلَـٰمَ﴾: بدا منه شيءٌ من علاماتِ الإسلام، لأنه قد يكونُ مؤمنًا يُخفي إيمانَه.\n\n﴿كُنتُم مِّن قَبۡلُ﴾: تُخْفُون إيمانَكم عن قومِكم المشركين.\n\n﴿فَمَنَّ ٱللَّهُ عَلَيۡكُمۡ﴾: فأعَزَّكم بالإيمانِ، والقوةِ."],[95,95,"﴿ٱلۡقَـٰعِدُونَ﴾: المتخلِّفون عن الجهادِ.\n\n﴿أُوْلِي ٱلضَّرَرِ﴾: أصحابِ الأعذارِ.\n\n﴿وَكُلࣰّا﴾: وكلَّ أحدٍ من المجاهدين والقاعدين، من أهلِ الأعذارِ.\n\n﴿ٱلۡحُسۡنَىٰ﴾: الجنةَ."],[96,96,"﴿دَرَجَـٰتࣲ﴾: منازلَ."],[97,97,"﴿ظَالِمِيٓ أَنفُسِهِمۡ﴾: بقُعودِهم في دارِ الكفرِ، وتَرْكِ الهجرةِ."],[98,98,"﴿لَا يَسۡتَطِيعُونَ حِيلَةࣰ﴾: لايَقْدِرُون على دَفْعِ الظُّلمِ عنهم."],[100,100,"﴿مُرَ ٰ⁠غَمࣰا﴾: مُتَحَوَّلًا.\n\n﴿سَعَةࣰ﴾: في الرِّزقِ."],[101,101,"﴿ضَرَبۡتُمۡ﴾: سافَرْتُم.\n\n﴿يَفۡتِنَكُمُ﴾: يَعْتدِيَ عليكم."],[102,102,"﴿كُنتَ﴾: أي: في ساحةِ القتالِ، وأُقيمَت الصلاةُ.\n\n﴿وَلۡيَأۡخُذُوٓاْ أَسۡلِحَتَهُمۡ﴾: هم الطائفةُ التي تُصَلِّي معه، تحملُ سلاحَها، وتُصَلي مع الإمامِ رَكعةً واحدةً، ثم يأخُذون مكانَ الطائفةِ التي لم تُصَلِّ.\n\n﴿فَلۡيَكُونُواْ﴾: هم الطائفةُ القائمةُ بإزاءِ العدوِّ.\n\n﴿مِن وَرَآئِكُمۡ﴾: من وراءِ المُصَلِّين.\n\n﴿فَلۡيُصَلُّواْ مَعَكَ﴾: وهم الذين لم يُصَلُّوا، فيُصَلُّون مع الإمامِ رَكْعَةً.\n\n﴿فَيَمِيلُونَ عَلَيۡكُم مَّيۡلَةࣰ وَ ٰ⁠حِدَةࣰ﴾: فَيقْضُون عليكم.\n\n﴿وَلَا جُنَاحَ﴾: ولا إثمَ."],[103,103,"﴿فَأَقِيمُواْ ٱلصَّلَوٰةَ﴾: كاملةً برُكوعِها وسجودِها.\n\n﴿مَّوۡقُوتࣰا﴾: في أوقاتٍ معلومةٍ."],[104,104,"﴿وَلَا تَهِنُواْ﴾: ولا تَضْعُفوا.\n\n﴿فِي ٱبۡتِغَآءِ ٱلۡقَوۡمِ﴾: في طَلَبِ عَدوِّكم.\n\n﴿تَأۡلَمُونَ﴾: من القتالِ.\n\n﴿وَتَرۡجُونَ﴾: من الثوابِ والنَّصْرِ."],[105,105,"﴿بِمَآ أَرَىٰكَ ٱللَّهُ﴾: بما أوْحى إليك، وبَصَّرَكَ به.\n\n﴿خَصِيمࣰا﴾: مُدافِعًا عنهم."],[107,107,"﴿وَلَا تُجَـٰدِلۡ﴾: ولا تُدافِعْ، وتخاصِمْ.\n\n﴿يَخۡتَانُونَ﴾: يَخُونون بمعصيةِ اللهِ.\n\n﴿خَوَّانًا﴾: كثيرَ الخيانةِ.\n\n﴿أَثِيمࣰا﴾: كثيرَ الذَّنْبِ."],[108,108,"﴿يَسۡتَخۡفُونَ﴾: يَسْتَتِرُون.\n\n﴿وَهُوَ مَعَهُمۡ﴾: بعِلْمِه.\n\n﴿يُبَيِّتُونَ﴾: يُدَبِّرُون ليلًا."],[109,109,"﴿وَكِيلࣰا﴾: مُجادِلًا يقومُ بأمرِهم."],[110,110,"﴿يَظۡلِمۡ نَفۡسَهُۥ﴾: بارتكابِ معصيةٍ."],[111,111,"﴿يَكۡسِبُهُۥ عَلَىٰ نَفۡسِهِۦ﴾: يَضُرُّها."],[112,112,"﴿إِثۡمࣰا﴾: ذَنبًا عن عَمْدٍ.\n\n﴿ٱحۡتَمَلَ بُهۡتَـٰنࣰا﴾: تَحَمَّلَ كَذِبًا.\n\n﴿مُّبِينࣰا﴾: بَيِّنًا."],[113,113,"﴿فَضۡلُ ٱللَّهِ﴾: بالنبوَّةِ، فعَصَمَك بتوفيقِه.\n\n﴿يُضِلُّوكَ﴾: يُزِلُّوك عن الحقِّ.\n\n﴿ٱلۡحِكۡمَةَ﴾: السُّنَّةَ."],[114,114,"﴿نَّجۡوَىٰهُمۡ﴾: كلامِهم سِرًّا.\n\n﴿مَعۡرُوفٍ﴾: أعمالِ البِرِّ، والخيرِ."],[115,115,"﴿يُشَاقِقِ﴾: يُخالِفْ، ويُعادِ.\n\n﴿تَبَيَّنَ﴾: ظَهَرَ.\n\n﴿نُوَلِّهِۦ مَا تَوَلَّىٰ﴾: نَتْرُكْه وما تَوَجَّه إليه."],[116,116,"﴿مَا دُونَ ذَ ٰ⁠لِكَ﴾: ما دونَ الشِّرك."],[117,117,"﴿إِنَـٰثࣰا﴾: أوثانًا لها أسماءٌ مؤنثةٌ.\n\n﴿مَّرِيدࣰا﴾: متمرِّدًا على اللهِ، وهو إبليسُ."],[118,118,"﴿لَّعَنَهُ ٱللَّهُ﴾: طَرَدَه من رَحْمَتِه.\n\n﴿نَصِيبࣰا مَّفۡرُوضࣰا﴾: جُزْءًا منهم معلومًا، وبَيَّن ذلك بما بعدَه."],[119,119,"﴿وَلَأُضِلَّنَّهُمۡ﴾: ولَأَصْرِفَنَّهم عن طريقِ الهدايةِ.\n\n﴿وَلَأُمَنِّيَنَّهُمۡ﴾: لَأَعِدَنَّهم بالأماني الكاذبةِ.\n\n﴿فَلَيُبَتِّكُنَّ﴾: لَأَدْعُوَنَّهم إلى تَقْطِيعِ.\n\n﴿خَلۡقَ ٱللَّهِ﴾: في الفِطْرَةِ والهيئةِ."],[120,120,"﴿يَعِدُهُمۡ﴾: بالوعودِ الكاذبةِ.\n\n﴿وَيُمَنِّيهِمۡ﴾: بالأماني الباطلةِ.\n\n﴿غُرُورًا﴾: خديعةً."],[121,121,"﴿مَحِيصࣰا﴾: مَلْجَأً."],[122,122,"﴿قِيلࣰا﴾: قولًا."],[123,123,"﴿لَّيۡسَ بِأَمَانِيِّكُمۡ﴾: لا يُنالُ هذا الفضلُ بالأماني."],[124,124,"﴿نَقِيرࣰا﴾: النُّقطةَ في ظَهْرِ النَّواةِ."],[125,125,"﴿وَهُوَ مُحۡسِنࣱ﴾: عاملٌ للحَسَناتِ.\n\n﴿مِلَّةَ﴾: دينَ.\n\n﴿حَنِيفࣰا﴾: مائلًا عن العقائدِ الفاسدةِ.\n\n﴿خَلِيلࣰا﴾: صَفِيًّا."],[127,127,"﴿وَمَا يُتۡلَىٰ عَلَيۡكُمۡ﴾: أي: والقرآنُ الذي يُتْلى عليكم يُفْتِيكم فيهنَّ.\n\n﴿وَٱلۡمُسۡتَضۡعَفِينَ﴾: أي: ما يُتْلى عليكم في اليتامى، والمستضعفين.\n\n﴿بِٱلۡقِسۡطِ﴾: بالعَدْلِ."],[128,128,"﴿بَعۡلِهَا﴾: زَوْجِها.\n\n﴿نُشُوزًا﴾: استعلاءً بنفسِه عنها.\n\n﴿فَلَا جُنَاحَ﴾: فلا حَرَجَ.\n\n﴿وَأُحۡضِرَتِ ٱلۡأَنفُسُ ٱلشُّحَّ﴾: وجُبِلَتِ الأنفسُ على شُحِّ كلٍّ من الزوجَيْن بنصيبِه."],[129,129,"﴿أَن تَعۡدِلُواْ﴾: العَدْلَ التامَّ في مَيْلِ القلبِ.\n\n﴿فَلَا تَمِيلُواْ﴾: فلا تُعْرِضُوا عن المرغوبِ عنها.\n\n﴿فَتَذَرُوهَا﴾: فَتتْرُكوها.\n\n﴿كَٱلۡمُعَلَّقَةِ﴾: لا هيَ مُطَلَّقةٌ، ولا هي ذاتُ زوجٍ."],[130,130,"﴿يُغۡنِ ٱللَّهُ كُلࣰّا﴾: يَجْعَلْه مُسْتغنيًا عن الآخَر."],[131,131,"﴿وَإِيَّاكُمۡ﴾: وصَّينا أُمَّةَ محمدٍ ﷺ."],[132,132,"﴿وَكِيلًا﴾: قائمًا بشؤونِ خَلْقِه."],[134,134,"﴿ثَوَابَ ٱلدُّنۡيَا﴾: عَرَضَ الدنيا.\n\n﴿فَعِندَ ٱللَّهِ ثَوَابُ ٱلدُّنۡيَا وَٱلۡـَٔاخِرَةِ﴾: هَلّا طَلَب بعَمَلِه ما عندَ اللهِ من ثوابِ الدنيا والآخرةِ."],[135,135,"﴿قَوَّ ٰ⁠مِينَ﴾: ليتكرَّرْ منكم القيامُ.\n\n﴿بِٱلۡقِسۡطِ﴾: بالعَدْلِ، والإقرارِ بما عليكم من الحقوقِ.\n\n﴿شُهَدَآءَ لِلَّهِ﴾: مُؤَدِّين للشَّهادةِ، لمرضاةِ اللهِ.\n\n﴿إِن يَكُنۡ﴾: المشهودُ عليه.\n\n﴿أَوۡلَىٰ بِهِمَا﴾: أحقُّ منكم بكلِّ واحدٍ منهما.\n\n﴿أَن تَعۡدِلُواْ﴾: مخافةَ أن تَعْدِلُوا عن الحقِّ، فتَجُوروا.\n\n﴿تَلۡوُۥٓاْ﴾: تُحَرِّفُوا الشهادةَ.\n\n﴿أَوۡ تُعۡرِضُواْ﴾: بتَرْكِ أدائِها، أو كِتمانِها."],[137,137,"﴿سَبِيلَۢا﴾: طريقًا."],[139,139,"﴿أَوۡلِيَآءَ﴾: أنصارًا.\n\n﴿أَيَبۡتَغُونَ﴾: أيَطْلُبون؟\n\n﴿ٱلۡعِزَّةَ﴾: النُّصْرَةَ، والمنَعَةَ."],[140,140,"﴿مِّثۡلُهُمۡ﴾: في الكفرِ، لأنكم رَضِيتم بالكفرِ والاستهزاءِ."],[141,141,"﴿ٱلَّذِينَ يَتَرَبَّصُونَ بِكُمۡ﴾: المنافقون ينتظرون ما يَحُلُّ بكم.\n\n﴿فَتۡحࣱ﴾: نَصْرٌ، وغنيمةٌ.\n\n﴿نَسۡتَحۡوِذۡ﴾: نساعِدْكم، ونَغْلِبْ عليكم.\n\n﴿وَنَمۡنَعۡكُم﴾: بتَخْذِيلهم، وتَثْبيطِهم عنكم.\n\n﴿سَبِيلًا﴾: تَسَلُّطًا، وطريقًا ما داموا عاملين بالحقِّ."],[142,142,"﴿يُخَـٰدِعُونَ ٱللَّهَ﴾: بما يُظْهِرُونه من الإيمان، ويُبْطِنون الكفرَ، ظنًّا منهم أنه يَخْفى عليه.\n\n﴿وَهُوَ خَـٰدِعُهُمۡ﴾: يُوصِلُ إليهم العقوبةَ بطريقٍ خَفِيّ.\n\n﴿يُرَآءُونَ﴾: يَقْصِدُون بصَلاتِهم الرياءَ والسُّمْعةَ."],[143,143,"﴿مُّذَبۡذَبِينَ﴾: لايَسْتقِرُّون على حالٍ، بل هم مُتَحَيِّرون.\n\n﴿سَبِيلࣰا﴾: طريقًا إلى الحقِّ."],[144,144,"﴿سُلۡطَـٰنࣰا مُّبِينًا﴾: حُجَّةً ظاهرةً على كَذِبِكم في إيمانِكم."],[145,145,"﴿ٱلدَّرۡكِ﴾: الطَّبَقَةِ."],[148,148,"﴿مَن ظُلِمَ﴾: فلا حَرَجَ أن يُخْبِرَ بما أُسِيءَ إليه."],[150,150,"﴿بَيۡنَ ذَ ٰ⁠لِكَ﴾: بين الإيمانِ والكُفرِ، دِينًا متوسِّطًا بينهما."],[152,152,"﴿أُجُورَهُمۡ﴾: ثوابَهم."],[153,153,"﴿جَهۡرَةࣰ﴾: عِيانًا نَنْظُرُ إليه.\n\n﴿ٱلصَّـٰعِقَةُ﴾: النارُ نَزَلَتْ عليهم، فأهلَكَتْهُم.\n\n﴿سُلۡطَـٰنࣰا﴾: حُجَّةً تُؤَيِّدُ صِدْقَ نبوَّتهِ."],[154,154,"﴿ٱلطُّورَ﴾: جَبَلَ الطُّورِ.\n\n﴿بِمِيثَـٰقِهِمۡ﴾: امتَنَعُوا عن الالتزامِ بالعَهْدِ المؤكَّدِ للعملِ بالتَوْراة، فَرفَعَ اللهُ عليهم جَبَلَ الطُّور، فقَبِلُوها.\n\n﴿ٱلۡبَابَ﴾: بابَ بيتِ المَقْدِسِ.\n\n﴿سُجَّدࣰا﴾: خاضِعين لله، لكنهم دَخَلُوا يزحَفُون على أستاهِهم.\n\n﴿لَا تَعۡدُواْ فِي ٱلسَّبۡتِ﴾: لا تَعْتَدُوا بالصَّيدِ يومَ السَّبْتِ، ولكنهم خالَفُوا.\n\n﴿مِّيثَـٰقًا غَلِيظࣰا﴾: عهدًا مؤكَّدًا، فنقضُوه."],[155,155,"﴿فَبِمَا نَقۡضِهِم مِّيثَـٰقَهُمۡ﴾: لَعَنّاهم بسببِ نَقْضِهم العهودَ المؤكَّدةَ.\n\n﴿غُلۡفُۢ﴾: عليها أغطِيَةٌ، لاتفقَهُ ما تقولُ.\n\n﴿طَبَعَ﴾: خَتَمَ.\n\n﴿إِلَّا قَلِيلࣰا﴾: إلا إيمانًا قليلًا كإيمانِهم بموسى عليه السلامُ والتوراةِ."],[156,156,"﴿بُهۡتَـٰنًا﴾: افتراءً برَمْيِها بالزِّنى."],[157,157,"﴿شُبِّهَ لَهُمۡ﴾: قَتَلُوا رجلًا يُشْبِهُه.\n\n﴿يَقِينَۢا﴾: مُتَيَقِّنِين بأنه عيسى، بل كانوا شاكِّين مُتَوَهِّمين فيه."],[159,159,"﴿لَيُؤۡمِنَنَّ بِهِۦ﴾: أي: بعدَ نُزولِه آخرَ الزَّمانِ.\n\n﴿شَهِيدࣰا﴾: شاهدًا عليهم بتكذيبِ مَن كذَّبه، وغالى فيه."],[161,161,"﴿وَأَعۡتَدۡنَا﴾: وأَعْدَدْنا."],[162,162,"﴿ٱلرَّ ٰ⁠سِخُونَ﴾: المُتَمَكِّنون.\n\n﴿وَٱلۡمُقِيمِينَ ٱلصَّلَوٰةَ﴾: أي: وأمدَحُ هؤلاء."],[163,163,"﴿وَٱلۡأَسۡبَاطِ﴾: الأنبياءِ الذين كانوا في قبائِلِ بني إسرائيلَ الاثنتي عشرةَ مِن ولدِ يعقوبَ.\n\n﴿زَبُورࣰا﴾: اسمُ الكتابِ الذي أُنْزلَ على داودَ، وهو صُحُفٌ مكتوبةٌ."],[165,165,"﴿مُّبَشِّرِينَ﴾: أي: بثوابي.\n\n﴿وَمُنذِرِينَ﴾: بعقابي.\n\n﴿بَعۡدَ ٱلرُّسُلِ﴾: بعد إرسالِ الرُّسُلِ."],[166,166,"﴿وَكَفَىٰ بِٱللَّهِ شَهِيدًا﴾: حَسْبُك اللهُ شاهدًا على صِدْقِك."],[170,170,"﴿فَإِنَّ لِلَّهِ مَا فِي ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ﴾: أي: فإنه غَنِيٌّ عنكم، وعن إيمانِكم لأنه مالكُ ما في السمواتِ والأرضِ."],[171,171,"﴿لَا تَغۡلُواْ﴾: لا تُجاوِزُوا الحقَّ، فتُفْرِطُوا.\n\n﴿وَكَلِمَتُهُۥٓ﴾: وخَلَقَه بالكلمةِ التي أرسلَ جبريلَ بها إلى مريمَ، وهي قولُه: «كن» فكان.\n\n﴿وَرُوحࣱ مِّنۡهُ﴾: كان إنسانًا بإحياءِ اللهِ له بقولِه: «كن».\n\n﴿وَلَا تَقُولُواْ ثَلَـٰثَةٌ﴾: ولا تجعلُوا عيسى وأمَّه مع اللهِ شريكَيْن.\n\n﴿وَكِيلࣰا﴾: مُدَبِّرًا، وكَلَ الخَلْقُ أمورَهم إليه."],[172,172,"﴿لَّن يَسۡتَنكِفَ﴾: لن يأْنَفَ، ويَسْتَكْبِرَ."],[174,174,"﴿بُرۡهَـٰنࣱ﴾: محمدٌ ﷺ.\n\n﴿نُورࣰا﴾: قرآنًا."],[175,175,"﴿وَٱعۡتَصَمُواْ بِهِۦ﴾: تَمَسَّكُوا به.\n\n﴿صِرَ ٰ⁠طࣰا مُّسۡتَقِيمࣰا﴾: طريقًا لاعِوَجَ فيه."],[176,176,"﴿يَسۡتَفۡتُونَكَ﴾: يَطْلُبون حُكْمَك.\n\n﴿فِي ٱلۡكَلَـٰلَةِ﴾: في ميراثِ مَن مات، وليس له ولدٌ، ولا والد.\n\n﴿فَإِن كَانَتَا ٱثۡنَتَيۡنِ﴾: مَن مات كَلالةً وله أختان.\n\n﴿حَظِّ﴾: نصيبِ.\n\n﴿أَن تَضِلُّواْ﴾: لئلّا تَضِلُّوا عن الحقِّ."]]);
QTF("gharib",5,[[1,1,"﴿أَوۡفُواْ بِٱلۡعُقُودِ﴾: أتِمُّوا عهودَ اللهِ الموَثَّقَةَ.\n\n﴿ٱلۡأَنۡعَـٰمِ﴾: الإبِلِ، والبَقَرِ، والغَنَمِ.\n\n﴿إِلَّا مَا يُتۡلَىٰ عَلَيۡكُمۡ﴾: إلا ما نَصَّ الله على تحريمِه كالميتةِ، ولحمِ الخِنْزيرِ.\n\n﴿غَيۡرَ مُحِلِّي ٱلصَّيۡدِ﴾: أُحِلَّتْ لكم الأنعامُ حالَ تحريمِ الصيدِ عليكم.\n\n﴿وَأَنتُمۡ حُرُمٌ﴾: بدخولِكم في الإحرامِ بالحجِّ أوالعُمرةِ."],[2,2,"﴿لَا تُحِلُّواْ﴾: لا يَقَعْ منكم الإخلالُ.\n\n﴿شَعَـٰٓئِرَ ٱللَّهِ﴾: جَمْعُ شَعيرةٍ، وهي حُرُماتُه، ومعالمُه.\n\n﴿وَلَا ٱلشَّهۡرَ ٱلۡحَرَامَ﴾: لا تَسْتَحِلُّوا القتالَ في الأشهرِ الحُرُم وهي: ذو القِعْدةِ وذو الحِجَّةِ والمحرمُ ورَجَبٌ.\n\n﴿وَلَا ٱلۡهَدۡيَ﴾: ولا تَسْتَحِلُّوا أن تأخذُوا ما أهداه المرءُ من الأنعامِ إلى بيتِ اللهِ، أو تَحُولُوا بينَه وبينَ المكانِ الذي يُهدى إليه.\n\n﴿وَلَا ٱلۡقَلَـٰٓئِدَ﴾: بأن تُؤْخَذَ غَصْبًا، و هي ضفائرُ صوفٍ يَضَعُونها في رَقَبَةِ البَهيمةِ علامةً على أنها هَدْيٌ.\n\n﴿وَلَآ ءَآمِّينَ ٱلۡبَيۡتَ ٱلۡحَرَامَ﴾: ولا تَسْتَحِلُّوا قتالَ قاصدي البيتِ الحرامِ.\n\n﴿حَلَلۡتُمۡ﴾: من إحرامِكم.\n\n﴿وَلَا يَجۡرِمَنَّكُمۡ﴾: ولا يَحْمِلَنَّكم.\n\n﴿شَنَـَٔانُ﴾: بُغْضُ.\n\n﴿أَن صَدُّوكُمۡ﴾: لأَجْل صَدِّهم إياكم.\n\n﴿ٱلۡبِرِّ﴾: العمل بِما أمَرَ اللهُ بالعملِ به.\n\n﴿وَٱلتَّقۡوَىٰ﴾: اجتنابِ ما أمرَ اللهُ باجتنابِه.\n\n﴿ٱلۡإِثۡمِ﴾: هوكلُّ فِعْلٍ أو قولٍ يُوجِبُ الذَّنْبَ.\n\n﴿وَٱلۡعُدۡوَ ٰ⁠نِ﴾: التعَدِّي على الناسِ بما فيه ظُلْمٌ."],[3,3,"﴿ٱلۡمَيۡتَةُ﴾: الحيَوانُ الذي تُفارِقُه الحياةُ من دونِ ذَبْحٍ.\n\n﴿وَٱلدَّمُ﴾: أي: السائلُ.\n\n﴿وَمَآ أُهِلَّ لِغَيۡرِ ٱللَّهِ﴾: ما ذُكِرَ عليه غيرُ اسمِ اللهِ عند الذَّبْحِ.\n\n﴿وَٱلۡمُنۡخَنِقَةُ﴾: التي حُبِسَ نَفَسُها حتى ماتَتْ.\n\n﴿وَٱلۡمَوۡقُوذَةُ﴾: التي ضُرِبَتْ بعصا أو حَجَرٍ حتى ماتَتْ.\n\n﴿وَٱلۡمُتَرَدِّيَةُ﴾: التي سَقطَتْ من مكانٍ عالٍ، فماتَتْ.\n\n﴿وَٱلنَّطِيحَةُ﴾: التي نَطَحَتْها شاةٌ أو بقرةٌ، فماتَتْ.\n\n﴿ٱلسَّبُعُ﴾: كالأسدِ والنَّمِرِ.\n\n﴿ذَكَّيۡتُمۡ﴾: ذَبَحْتُم قبلَ أن يموتَ، فهو حَلالٌ.\n\n﴿ٱلنُّصُبِ﴾: حجارةٍ كان المشركونَ يذْبحون عليها في الجاهليةِ تَقَرُّبًا إلى الأصنامِ.\n\n﴿وَأَن تَسۡتَقۡسِمُواْ بِٱلۡأَزۡلَـٰمِ﴾: القِداحِ التي كانوا يَطْلُبون بها عِلْمَ ما قُسِمَ لهم.\n\n﴿فِسۡقٌ﴾: خُروجٌ عن طاعةِ اللهِ.\n\n﴿ٱلۡيَوۡمَ﴾: يومَ فتحِ مكةَ في السنةِ الثامنةِ من الهجرة.\n\n﴿نِعۡمَتِي﴾: بإكمالِ الدين، وفتحِ مكةَ، وقَهْرِ الكُفّارِ.\n\n﴿مَخۡمَصَةٍ﴾: مَجاعةٍ.\n\n﴿مُتَجَانِفࣲ﴾: مائلٍ.\n\n﴿لِّإِثۡمࣲ﴾: حَرامٍ."],[4,4,"﴿وَمَا عَلَّمۡتُم﴾: أي: صَيْدُ ما دَرَّبْتُموه من الكِلابِ ونحوِها.\n\n﴿مُكَلِّبِينَ﴾: جَمْعُ مُكَلِّبٍ، وهو مُعَلِّمُ الكِلابِ طريقةَ الاصطيادِ."],[5,5,"﴿وَٱلۡمُحۡصَنَـٰتُ﴾: أي: ونكاحُ الحَرائرِ من النساءِ المؤمناتِ.\n\n﴿أُجُورَهُنَّ﴾: مُهورَهُنَّ.\n\n﴿مُحۡصِنِينَ﴾: أعِفّاءَ.\n\n﴿غَيۡرَ مُسَـٰفِحِينَ﴾: غيرمرتكبين للزِّنى.\n\n﴿أَخۡدَانࣲ﴾: عشيقاتٍ يَزْنُون بهنَّ سِرًّا.\n\n﴿حَبِطَ﴾: بَطَلَ."],[6,6,"﴿إِذَا قُمۡتُمۡ﴾: إذا أرَدْتُم القيامَ، وأنتم على غير طُهْرٍ.\n\n﴿ٱلۡمَرَافِقِ﴾: جمعُ مِرْفَقٍ، وهو المِفْصَلُ الذي بينَ الذِّراعِ والعَضُدِ.\n\n﴿وَأَرۡجُلَكُمۡ﴾: واغسِلُوا أرجُلَكم.\n\n﴿إِلَى ٱلۡكَعۡبَيۡنِ﴾: هما العَظْمان البارِزان عند مُلْتقى السّاقِ بالقَدَمِ.\n\n﴿فَٱطَّهَّرُواْ﴾: بالاغتسالِ.\n\n﴿مِّنَ ٱلۡغَآئِطِ﴾: من قَضاءِ الحاجةِ.\n\n﴿لَـٰمَسۡتُمُ ٱلنِّسَآءَ﴾: جامَعْتُموهُنَّ.\n\n﴿فَتَيَمَّمُواْ صَعِيدࣰا﴾: فاضرِبُوا بأيدِيكم وجهَ الأرضِ.\n\n﴿حَرَجࣲ﴾: ضِيقٍ."],[7,7,"﴿نِعۡمَةَ ٱللَّهِ عَلَيۡكُمۡ﴾: بهدايتِكم للإسلامِ.\n\n﴿وَمِيثَـٰقَهُ﴾: وعَهْدَه الذي أخَذَه عليكم حين بايَعْتم الرسولَ ﷺ على السَّمْعِ والطاعةِ."],[8,8,"﴿قَوَّ ٰ⁠مِينَ﴾: أي بالحقِّ ابتغاءَ وجهِ اللهِ.\n\n﴿شُهَدَآءَ بِٱلۡقِسۡطِ﴾: تَشْهَدون بالعدلِ.\n\n﴿وَلَا يَجۡرِمَنَّكُمۡ﴾: ولا يَحْمِلَنَّكم.\n\n﴿شَنَـَٔانُ﴾: عَداوةُ."],[11,11,"﴿هَمَّ﴾: عَزَمَ.\n\n﴿أَن يَبۡسُطُوٓاْ إِلَيۡكُمۡ أَيۡدِيَهُمۡ﴾: أنَ يبْطِشَ يهودُ بني النَّضِيرِ بكم، يومَ سار إليهم الرسولُ ﷺ ونَفَرٌ من أصحابِه في شأنٍ معهم.\n\n﴿فَكَفَّ﴾: فصَرَفَ."],[12,12,"﴿مِيثَـٰقَ﴾: العهدَ المؤكَّدَ بالوفاءِ به.\n\n﴿ٱثۡنَيۡ عَشَرَ نَقِيبࣰا﴾: عَريفًا من كبارِ القومِ، بعَددِ فروعِهم، يأخُذُون عليهم العهدَ.\n\n﴿وَعَزَّرۡتُمُوهُمۡ﴾: ونَصَرْتُموهم، وعَظَّمتُموهم.\n\n﴿وَأَقۡرَضۡتُمُ ٱللَّهَ﴾: وأنْفَقْتم في سبيلهِ.\n\n﴿ضَلَّ سَوَآءَ ٱلسَّبِيلِ﴾: أخطأ وسَطَ طريقِ الحقِّ."],[13,13,"﴿فَبِمَا﴾: فبسببِ.\n\n﴿لَعَنَّـٰهُمۡ﴾: طَرَدْناهم مِن رحمتِنا.\n\n﴿قَـٰسِيَةࣰ﴾: غليظةً لا تَعِي خيرًا.\n\n﴿ٱلۡكَلِمَ﴾: التوراةَ.\n\n﴿وَنَسُواْ حَظࣰّا﴾: تَرَكُوا قَدْرًا مِمّا أُمِرُوا به.\n\n﴿وَلَا تَزَالُ تَطَّلِعُ عَلَىٰ خَآئِنَةࣲ مِّنۡهُمۡ﴾: ولا تزال أيها الرسولُ تَقِفُ من اليهودِ على خيانةٍ، وغَدْرٍ."],[14,14,"﴿مِيثَـٰقَهُمۡ﴾: العهدَ المؤكَّدَ على طاعتي\n\n﴿فَأَغۡرَيۡنَا﴾: فأَلْقَيْنا.\n\n﴿بَيۡنَهُمُ﴾: بينَ النصارى، فكلُّ فِرْقَةٍ تُعادي صاحبتَها."],[15,15,"﴿رَسُولُنَا﴾: محمدٌ ﷺ.\n\n﴿مِّمَّا كُنتُمۡ تُخۡفُونَ﴾: كالرَّجْمِ للزّاني.\n\n﴿وَيَعۡفُواْ عَن كَثِيرࣲ﴾: ممّا تُخْفُونه، فيَتْرُكُ بيانَه.\n\n﴿نُورࣱ﴾: محمدٌ ﷺ.\n\n﴿وَكِتَـٰبࣱ﴾: القرآنُ الكريمُ."],[16,16,"﴿سُبُلَ ٱلسَّلَـٰمِ﴾: طريقَ اللهِ الذي شَرَعَه.\n\n﴿صِرَ ٰ⁠طࣲ مُّسۡتَقِيمࣲ﴾: طريقٍ لاعِوَجَ فيه."],[17,17,"﴿فَمَن يَمۡلِكُ مِنَ ٱللَّهِ شَيۡـًٔا﴾: فمَنِ الذي يَقْدِرُ أن يمنعَ من أمْرِ اللهِ؟"],[18,18,"﴿نَحۡنُ أَبۡنَـٰٓؤُاْ ٱللَّهِ﴾: فقالت اليهودُ: عزيرٌ ابنُ اللهِ، وقالت النصارى: المسيحُ ابنُ اللهِ.\n\n﴿أَنتُم بَشَرࣱ﴾: أنتم خَلْقٌ مثلُ سائرِ بني آدمَ يحاسبُهم على أعمالهم.\n\n﴿ٱلۡمَصِيرُ﴾: المَرْجِعُ."],[19,19,"﴿رَسُولُنَا﴾: محمدٌ ﷺ\n\n﴿عَلَىٰ فَتۡرَةࣲ مِّنَ ٱلرُّسُلِ﴾: على انقطاعٍ من الرسلِ مُدّةً من الزمانِ.\n\n﴿أَن تَقُولُواْ﴾: لئلّا تقُولوا."],[20,20,"﴿وَجَعَلَكُم مُّلُوكࣰا﴾: وجْهُ الامتنانِ كثرةُ الملوكِ والأنبياءِ فيهم، أو أنكم تملكون أمرَكم بعد أن كنتم مملوكين لفرعونَ.\n\n﴿مِّنَ ٱلۡعَـٰلَمِينَ﴾: عالَمِي زمانِكم."],[21,21,"﴿ٱلۡأَرۡضَ ٱلۡمُقَدَّسَةَ﴾: المطهَّرَةَ المباركةَ، وهي بيتُ المَقْدِسِ وما حولَها.\n\n﴿وَلَا تَرۡتَدُّواْ عَلَىٰٓ أَدۡبَارِكُمۡ﴾: ولا تَرْجِعُوا عن قتالِ الأشدّاء."],[22,22,"﴿جَبَّارِينَ﴾: أشدّاءَ، لاطاقَةَ لنا بحَرْبِهم."],[23,23,"﴿يَخَافُونَ﴾: أي: اللهَ.\n\n﴿ٱدۡخُلُواْ عَلَيۡهِمُ ٱلۡبَابَ﴾: ادخُلوا على هؤلاءِ الأشدّاءِ بابَ مدينتِهم."],[24,24,"﴿لَن نَّدۡخُلَهَآ﴾: لن نَدْخُلَ مدينةَ الجبّارين."],[25,25,"﴿لَآ أَمۡلِكُ﴾: لا أقْدِرُ أن أحملَ أحدًا على ما أُحِبُّ.\n\n﴿فَٱفۡرُقۡ﴾: فاقضِ\n\n﴿ٱلۡفَـٰسِقِينَ﴾: الخارجينَ عن طاعةِ اللهِ."],[26,26,"﴿فَإِنَّهَا﴾: الأرضَ المقدسةَ.\n\n﴿فَلَا تَأۡسَ﴾: فلاتحزَنْ."],[27,27,"﴿ٱبۡنَيۡ ءَادَمَ﴾: قابيلَ، وهابيلَ.\n\n﴿قَرَّبَا قُرۡبَانࣰا﴾: قَدَّما ما يُتَقَرَّبُ به إلى اللهِ.\n\n﴿أَحَدِهِمَا﴾: هابيل."],[29,29,"﴿تَبُوٓأَ بِإِثۡمِي﴾: تَرْجِعَ حاملًا ذَنْبَ قَتْلي.\n\n﴿وَإِثۡمِكَ﴾: الذي صار عليك بذنوبِك من قَبْلِ قَتْلي."],[30,30,"﴿فَطَوَّعَتۡ﴾: فشَجَّعَتْ."],[31,31,"﴿يَبۡحَثُ﴾: يَحْفِرُ حُفْرَةً.\n\n﴿سَوۡءَةَ﴾: ما تسوءُ رؤيتُه، وهو الجَسَدُ المتغيِّرُ.\n\n﴿فَأُوَ ٰ⁠رِيَ﴾: فأَسْتُرَ."],[32,32,"﴿مِنۡ أَجۡلِ ذَ ٰ⁠لِكَ﴾: بسببِ جنايةِ القَتْلِ.\n\n﴿بِغَيۡرِ نَفۡسٍ﴾: تُوجِبُ القِصاصَ.\n\n﴿فَسَادࣲ﴾: مُوجِبٍ للقَتْلِ.\n\n﴿لَمُسۡرِفُونَ﴾: لمتجاوِزُون حُدودَ الله."],[33,33,"﴿أَوۡ يُصَلَّبُوٓاْ﴾: بأن يُشَدَّ الجاني على خَشَبةٍ.\n\n﴿مِّنۡ خِلَـٰفٍ﴾: بقَطْعِ يُمنى اليدَيْن مع يُسْرى الرِّجْلَين، أو يُسرى اليدين مع يُمنى الرِّجْلَين.\n\n﴿أَوۡ يُنفَوۡاْ﴾: أو يُنْفَوا إلى بلدٍ غيرِ بلدِهم، ويُحْبَسُوا.\n\n﴿خِزۡيࣱ﴾: ذُلٌّ."],[35,35,"﴿ٱلۡوَسِيلَةَ﴾: مايُتَقَرَّبُ به إلى اللهِ بطاعتِه."],[36,36,"﴿وَمِثۡلَهُۥ﴾: ومَلكُوا مِثْلَه."],[37,37,"﴿مُّقِيمࣱ﴾: دائمٌ."],[38,38,"﴿نَكَـٰلࣰا﴾: عقوبةً."],[39,39,"﴿ظُلۡمِهِۦ﴾: سَرِقَتِه."],[41,41,"﴿فِي ٱلۡكُفۡرِ﴾: في إنكارِ نبوَّتِك.\n\n﴿ءَامَنَّا بِأَفۡوَ ٰ⁠هِهِمۡ﴾: هم المنافقون.\n\n﴿وَمِنَ ٱلَّذِينَ هَادُواْ﴾: لا يَحْزُنْك تَسَرُّعُ اليهودِ إلى إنكارِ نبوَّتِكِ.\n\n﴿لِلۡكَذِبِ﴾: مايفْتَريه أحبارُ اليهودِ.\n\n﴿لَمۡ يَأۡتُوكَ﴾: لم يَحْضُروا مجلسَك تَكَبُّرًا.\n\n﴿ٱلۡكَلِمَ﴾: التوراةَ، هي جمعُ «كلمة».\n\n﴿مِنۢ بَعۡدِ مَوَاضِعِهِۦ﴾: من بعدِ ما عَقَلُوه موضوعًا في مواضِعِه.\n\n﴿أُوتِيتُمۡ هَـٰذَا﴾: إنْ جاءكم محمدٌ ﷺ بما يُوافِقُ الحكمَ الذي بَدَّ لْناه من أحكامِ التوراةِ.\n\n﴿فِتۡنَتَهُۥ﴾: ضَلالتَه.\n\n﴿فَلَن تَمۡلِكَ﴾: فلن تستطيعَ دَفْعَ ذلك.\n\n﴿خِزۡيࣱ﴾: ذُلٌّ."],[42,42,"﴿لِلسُّحۡتِ﴾: للمال الحَرامِ كالرَّشوة.\n\n﴿بِٱلۡقِسۡطِ﴾: بالعدلِ.\n\n﴿ٱلۡمُقۡسِطِينَ﴾: العادِلين."],[43,43,"﴿يَتَوَلَّوۡنَ مِنۢ بَعۡدِ ذَ ٰ⁠لِكَ﴾: من بعدِ حُكْمِك إذا لم يُرْضِهم."],[44,44,"﴿أَسۡلَمُواْ﴾: انقادُوا لحُكْمِ اللهِ.\n\n﴿لِلَّذِينَ هَادُواْ﴾: اليهودِ.\n\n﴿وَٱلرَّبَّـٰنِيُّونَ﴾: والعُبّادُ.\n\n﴿وَٱلۡأَحۡبَارُ﴾: والعلماء.\n\n﴿ٱسۡتُحۡفِظُواْ﴾: اسْتُودِعُوا عِلْمَه.\n\n﴿وَكَانُواْ عَلَيۡهِ شُهَدَآءَ﴾: أي: الربّانيُّون والأحبارُ شهداءُ لمحمدٍ ﷺ بأنه نبيٌّ يَقْضي بالحقِّ.\n\n﴿وَلَا تَشۡتَرُواْ بِـَٔايَـٰتِي ثَمَنࣰا قَلِيلࣰا﴾: ولا تأخُذُوا بتَرْكِ حُكمي مُقابِلًا حقيرًا."],[45,45,"﴿بِٱلنَّفۡسِ﴾: تُقْتَلُ بالنفسِ.\n\n﴿وَٱلۡجُرُوحَ قِصَاصࣱ﴾: يُقْتَصُّ في الجُروحِ.\n\n﴿تَصَدَّقَ بِهِۦ﴾: تجاوَزَ عن حَقِّه.\n\n﴿كَفَّارَةࣱ﴾: تكفيرٌ لذنوبهِ."],[46,46,"﴿وَقَفَّيۡنَا﴾: وأتْبَعْنا.\n\n﴿عَلَىٰٓ ءَاثَـٰرِهِم﴾: على آثارِ النبيِّين.\n\n﴿مُصَدِّقࣰا لِّمَا بَيۡنَ يَدَيۡهِ﴾: مصدِّقًا للتوراةِ، عاملًا بمافيها ممّالم يَنْسَخْه كتابُه الإنجيلُ."],[47,47,"﴿ٱلۡفَـٰسِقُونَ﴾: الخارجون عن طاعةِ اللهِ."],[48,48,"﴿إِلَيۡكَ﴾: إلى محمدٍ ﷺ.\n\n﴿مُصَدِّقࣰا لِّمَا بَيۡنَ يَدَيۡهِ﴾: أنزَلْناه بتصديقِ ماقبلَه.\n\n﴿مِنَ ٱلۡكِتَـٰبِ﴾: من الكُتُبِ.\n\n﴿وَمُهَيۡمِنًا عَلَيۡهِ﴾: وشاهِدًا بصحةِ الكتبِ المنزَّلَةِ، ورقيبًا عليها، وحافظًا لما فِيها.\n\n﴿لِكُلࣲّ﴾: لكلِّ أمةٍ.\n\n﴿شِرۡعَةࣰ﴾: شريعةً.\n\n﴿وَمِنۡهَاجࣰا﴾: وطريقًا واضحًا. وهذا قبلَ نَسْخِ الشَّرائعِ السابقةِ بالقرآنِ، وأمّا بعدَه فلا مِنهاجَ إلا ما جاءَ به.\n\n﴿لَجَعَلَكُمۡ﴾: لَجعَلَ شرائعَكم.\n\n﴿لِّيَبۡلُوَكُمۡ﴾: شاءَ الابتلاءَليختبرَكم، فيتميَّزَ المطيعُ من العاصي.\n\n﴿فَٱسۡتَبِقُواْ﴾: فسارِعُوا."],[49,49,"﴿يَفۡتِنُوكَ﴾: يَصْرِفُوك، فلا تعمَلَ بما فيه.\n\n﴿فَإِن تَوَلَّوۡاْ﴾: فإن أعْرَضُوا عَمّا تَحْكُمُ به\n\n﴿بِبَعۡضِ ذُنُوبِهِمۡ﴾: بسببِ ذنوبٍ اكتسبوها."],[51,51,"﴿أَوۡلِيَآءَ﴾: أنصارًا على أهلِ الإيمان.\n\n﴿بَعۡضُهُمۡ أَوۡلِيَآءُ بَعۡضࣲ﴾: بعضُ اليهودِ أولياءُ بعضهم الآخَرِ، وكذا النَّصارى."],[52,52,"﴿مَّرَضࣱ﴾: نفاقٌ، وشكٌّ.\n\n﴿يُسَـٰرِعُونَ فِيهِمۡ﴾: يبادِرُون في مُوالاةِ اليهودِ.\n\n﴿دَآئِرَةࣱ﴾: مايَدُور من المَكارهِ، فينتصرُ اليهودُ، فينالون منّا.\n\n﴿بِٱلۡفَتۡحِ﴾: فتحِ مكة.\n\n﴿مَآ أَسَرُّواْ﴾: ما أضمَرُوه من موالاةِ الكافرين."],[53,53,"﴿جَهۡدَ أَيۡمَـٰنِهِمۡ﴾: بأغلظِ الأَيْمانِ.\n\n﴿حَبِطَتۡ﴾: بَطَلَتْ، فلاثَوابَ لها."],[54,54,"﴿أَذِلَّةٍ﴾: رُحماءَ.\n\n﴿أَعِزَّةٍ﴾: أشدّاءَ."],[55,55,"﴿وَلِيُّكُمُ﴾: ناصرُكم.\n\n﴿رَ ٰ⁠كِعُونَ﴾: خاضِعُون للهِ."],[57,57,"﴿هُزُوࣰا﴾: سُخْرِيَّةً واستهزاءً."],[58,58,"﴿لَّا يَعۡقِلُونَ﴾: أي: حقيقةَ العبادةِ."],[59,59,"﴿وَأَنَّ أَكۡثَرَكُمۡ فَـٰسِقُونَ﴾: وإيمانَنا بأنّ أكثرَكم خارجون عن طاعةِ اللهِ."],[60,60,"﴿مَثُوبَةً﴾: جزاءً.\n\n﴿وَعَبَدَ﴾: ومَن عَبَدَ.\n\n﴿ٱلطَّـٰغُوتَ﴾: كلُّ مَن عُبِدَ من دونِ اللهِ.\n\n﴿شَرࣱّ مَّكَانࣰا﴾: ساء مكانُهم في الآخرة.\n\n﴿سَوَآءِ ٱلسَّبِيلِ﴾: الطريقِ الصحيحِ."],[61,61,"﴿جَآءُوكُمۡ﴾: هم أناسٌ من اليهود جاؤُوكم بالكفرِ."],[62,62,"﴿ٱلۡإِثۡمِ﴾: الكفرِ.\n\n﴿ٱلسُّحۡتَ﴾: الحَرامَ كالرَّشوةِ."],[63,63,"﴿لَوۡلَا﴾: هَلّا.\n\n﴿ٱلرَّبَّـٰنِيُّونَ﴾: أئمتُهم.\n\n﴿وَٱلۡأَحۡبَارُ﴾: علماؤُهم."],[64,64,"﴿مَغۡلُولَةٌ﴾: مَحْبوسةٌ عن فِعْلِ الخيرِ.\n\n﴿طُغۡيَـٰنࣰا﴾: غُلُوًّا في إنكارِ ما عَلِمُوا صِحَّتَه مِن نبوَّةِ محمدٍ ﷺ.\n\n﴿بَيۡنَهُمُ﴾: بين طوائفِ اليهودِ."],[65,65,"﴿لَكَفَّرۡنَا﴾: لَمَحَوْنا."],[66,66,"﴿مِن فَوۡقِهِمۡ﴾: لَأَنْزَلَ عليهم المطرَ، فتنبُتُ لهم به الأرضُ.\n\n﴿وَمِن تَحۡتِ أَرۡجُلِهِم﴾: مما تُخْرِجُه الأرض من بَرَكَتِها.\n\n﴿مُّقۡتَصِدَةࣱ﴾: معتدلةٌ، ليسَتْ غاليةً."],[67,67,"﴿يَعۡصِمُكَ﴾: يَحْفَظُك، فلا تُنالُ بسوءٍ."],[68,68,"﴿لَسۡتُمۡ عَلَىٰ شَيۡءٍ﴾: لَسْتُمْ على حَظٍّ من الدِّين يُعْتَدُّ به.\n\n﴿طُغۡيَـٰنࣰا وَكُفۡرࣰا﴾: تَجَبُّرًا وجُحودًا.\n\n﴿فَلَا تَأۡسَ﴾: فلا تَحْزَنْ."],[69,69,"﴿وَٱلصَّـٰبِـُٔونَ﴾: أي: كذلك، وهم قومٌ باقون على فِطْرتِهم، ولادِينَ مقرَّرٌلهم."],[70,70,"﴿مِيثَـٰقَ﴾: العهدَ المؤكَّدَ."],[71,71,"﴿وَحَسِبُوٓاْ أَلَّا تَكُونَ فِتۡنَةࣱ﴾: وظنَّ هؤلاء اليهودُ ألّا يقعَ عليهم من اللهِ ابتلاءٌ بالشدائدِ."],[73,73,"﴿ثَالِثُ ثَلَـٰثَةࣲ﴾: الأبُ، والابنُ، وروحُ القُدُسِ."],[75,75,"﴿خَلَتۡ﴾: تَقَدَّمَتْ.\n\n﴿يَأۡكُلَانِ ٱلطَّعَامَ﴾: يحتاجان إليه كسائرِ البَشَرِ، وليس هذا شأنَ الربِّ.\n\n﴿يُؤۡفَكُونَ﴾: يُصْرَفون عن الحقِّ الذي بَيَّنتُه لهم."],[77,77,"﴿لَا تَغۡلُواْ﴾: لا تتجاوزُوا الحقَّ.\n\n﴿قَوۡمࣲ﴾: هم اليهودُ.\n\n﴿سَوَآءِ ٱلسَّبِيلِ﴾: قَصْدِ الطَّريقِ."],[78,78,"﴿لُعِنَ﴾: طُرِدَ من رحمةِ اللهِ."],[79,79,"﴿لَا يَتَنَاهَوۡنَ﴾: لا ينتَهُون، ولا يَنْهى بعضُهم بعضًا."],[80,80,"﴿أَن سَخِطَ ٱللَّهُ عَلَيۡهِمۡ﴾: ما قَدَّمَتْ لهم أنفسُهم هو سَخَطُ اللهِ عليهم."],[81,81,"﴿فَـٰسِقُونَ﴾: خارجُون عن طاعةِ اللهِ."],[82,82,"﴿ٱلَّذِينَ قَالُوٓاْ﴾: هم وفْدُ نَصارى الحبشةِ، وقد دَخَلُوا في الإسلامِ.\n\n﴿رُهۡبَانࣰا﴾: مُتَعَبِّدين."],[83,83,"﴿ٱلشَّـٰهِدِينَ﴾: الذين يَشْهَدُون لأنبيائِك يومَ القيامةِ أنهم قد بَلَّغُوا أمَمهم رسالاتِك."],[87,87,"﴿وَلَا تَعۡتَدُوٓاْ﴾: ولا تتجاوَزُوا حدودَ ما حَرَّم اللهُ."],[89,89,"﴿بِٱللَّغۡوِ﴾: بما لا تَقْصِدُون عَقْدَه.\n\n﴿عَقَّدتُّمُ﴾: بما أوْجَبْتُموه على أنفسِكم.\n\n﴿مِنۡ أَوۡسَطِ﴾: ممّا تعتادُونه من غير إسرافٍ أو تَقْتيرٍ.\n\n﴿وَٱحۡفَظُوٓاْ أَيۡمَـٰنَكُمۡ﴾: باجتنابِ المسارعةِ إلى الحَلْفِ، والحِنْثِ به."],[90,90,"﴿ٱلۡمَيۡسِرُ﴾: القِمارُ.\n\n﴿وَٱلۡأَنصَابُ﴾: الحجارةُ التي يَذْبَحُون عندها تعظيمًا لها.\n\n﴿وَٱلۡأَزۡلَـٰمُ﴾: القِداحُ التي يَسْتَقْسِمُون بها قبلَ الشُّروعِ في شيءٍ.\n\n﴿رِجۡسࣱ﴾: إثمٌ وقَذَرٌ."],[92,92,"﴿تَوَلَّيۡتُمۡ﴾: أعْرَضْتُم."],[93,93,"﴿جُنَاحࣱ﴾: حَرَجٌ في شُرْبِهم الخمرَ قبلَ تحريمِها."],[94,94,"﴿لَيَبۡلُوَنَّكُمُ﴾: لَيختبرَنَّكم.\n\n﴿لِيَعۡلَمَ ٱللَّهُ﴾: عِلْمًا ظاهرًا للخَلْقِ.\n\n﴿ٱعۡتَدَىٰ﴾: تجاوزَ حدودَ اللهِ."],[95,95,"﴿حُرُمࣱ﴾: مُحْرِمُون بحَجٍّ أو عُمْرَةٍ.\n\n﴿مِّثۡلُ مَا قَتَلَ مِنَ ٱلنَّعَمِ﴾: يَذْبَحُ مثلَ ذلك الصيدِ من بهيمةِ الأنعامِ: الإبلِ، أو البقرِ، أو الغنمِ.\n\n﴿ٱلۡكَعۡبَةِ﴾: الحَرَمِ.\n\n﴿طَعَامُ مَسَـٰكِينَ﴾: يَشْتري بقيمةِ المِثْل من النَّعَمِ طعامًا يُهديه لفقراءِ الحَرَمِ.\n\n﴿عَدۡلُ ذَ ٰ⁠لِكَ﴾: ما عادَلَه من غيرِ جِنْسِه، فيصومُ بدَلَ الإطعامِ يومًا عن كل نصفِ صاعٍ. والجاني مُخَيَّرٌ بين الأنواعِ المذكورة.\n\n﴿وَبَالَ أَمۡرِهِۦ﴾: عاقبةَ فِعْلهِ.\n\n﴿سَلَفَ﴾: مضى قبلَ التحريمِ."],[96,96,"﴿ٱلۡبَحۡرِ﴾: هوكلُّ ماءٍ فيه صَيْدٌ.\n\n﴿وَطَعَامُهُۥ﴾: ماقَذَفَ به البحرُ، وطَفا عليه ميتًا.\n\n﴿مَتَـٰعࣰا لَّكُمۡ﴾: منفعةً وقُوتًا للمُقيمين منكم.\n\n﴿وَلِلسَّيَّارَةِ﴾: جَمْعُ سَيّار، وهو المسافرُ.\n\n﴿حُرُمࣰا﴾: مُحْرِمين بحَجٍ أو عُمرةٍ."],[97,97,"﴿قِيَـٰمࣰا لِّلنَّاسِ﴾: صَلاحًا لدينهم، وقِوامًا لأمرِهم، وأمْنًا لمَن تَوَجَّه إليها.\n\n﴿وَٱلشَّهۡرَ ٱلۡحَرَامَ﴾: وهي الأشهُر التي حَرَّمَ اللهُ فيها القتالَ، وهي: ذو القِعدةِ وذو الحِجَّةِ والمحرمُ ورَجَبٌ، يدفَعُ اللهُ بعضَ الناس عن بعضٍ بها.\n\n﴿وَٱلۡهَدۡيَ﴾: مايُهدى إلى الحَرَم من بهيمةِ الأنعام.\n\n﴿وَٱلۡقَلَـٰٓئِدَ﴾: ماقُلِّد إشعارًا بأنه يُقْصَدُ به النُّسُكُ، وهي ضَفائرُ صُوفٍ يَضَعُونها في رَقَبَةِ البَهيمةِ."],[100,100,"﴿ٱلۡخَبِيثُ وَٱلطَّيِّبُ﴾: كلُّ ما يَتَّصِفُ بوَصْفِ الخُبْثِ والطَّيبِ من الأشخاصِ، والأعمالِ، والأقوالِ.\n\n﴿يَـٰٓأُوْلِي ٱلۡأَلۡبَـٰبِ﴾: يا أصحابَ العقولِ السِّليمةِ."],[101,101,"﴿لَا تَسۡـَٔلُواْ عَنۡ أَشۡيَآءَ﴾: عَمّالاحاجةَ لكم بالسؤالِ عنه.\n\n﴿تُبۡدَ لَكُمۡ﴾: (الثانية): تَظْهَرْ لكم بجوابِ النبيِّ ﷺ، أو بما يَنْزِلُ به الوحيُ، فيكونُ ذلك سببًا للتكاليفِ الشاقّةِ.\n\n﴿عَفَا ٱللَّهُ عَنۡهَا﴾: عمّا سَلَفَ من مَسْألَتِكم."],[102,102,"﴿ثُمَّ أَصۡبَحُواْ بِهَا كَـٰفِرِينَ﴾: فلمّا أُمِرُوا بها جَحَدُوها."],[103,103,"﴿مَا جَعَلَ ٱللَّهُ﴾: ما شَرَعَ اللهُ للمشركين ما ابتدَعُوه في بهيمةِ الأنعامِ من تَرْكِ الانتفاعِ بها، وتَرْكِها للأصنامِ.\n\n﴿مِنۢ بَحِيرَةࣲ﴾: هي التي تُشَقُّ أُذُنُها إذا ولَدَتْ عددًا من البُطونِ، أو التي لا يَحْلُبها أحدٌ من الناسِ.\n\n﴿وَلَا سَآئِبَةࣲ﴾: هي التي تُترك للأصنام إثْر نَذْرٍ.\n\n﴿وَلَا وَصِيلَةࣲ﴾: هي التي تتصلُ وِلادتُها بأنثى بعد أنثى.\n\n﴿وَلَا حَامࣲ﴾: هو الذَّكَرُ من الإبِلِ إذا نُتِجَ مِن صُلْبِه عددٌ من الإبِلِ، أو الذي يُعفى من الحَمْلِ."],[104,104,"﴿حَسۡبُنَا﴾: كافينا."],[105,105,"﴿عَلَيۡكُمۡ أَنفُسَكُمۡ﴾: ألْزِمُوا أنفسَكم بطاعةِ اللهِ."],[106,106,"﴿شَهَـٰدَةُ بَيۡنِكُمۡ﴾: فليَشْهَدْ على الوصيةِ.\n\n﴿ٱلۡمَوۡتُ﴾: علاماتُ الموتِ.\n\n﴿ذَوَا عَدۡلࣲ﴾: ذوا رُشْدٍ وأمانةٍ.\n\n﴿غَيۡرِكُمۡ﴾: من غيرِ المسلمين عند الحاجةِ في السفرِ للوصيةِ.\n\n﴿تَحۡبِسُونَهُمَا﴾: تَسْتَوْقِفونهما.\n\n﴿ٱلصَّلَوٰةِ﴾: صلاةِ العصرِ.\n\n﴿إِنِ ٱرۡتَبۡتُمۡ﴾: في شَهادتِهما، فإن صَدَّقْتُموهما فلا حاجةَ إلى القَسَم، وليس على شهودِ المسلمين إقسامٌ.\n\n﴿لَا نَشۡتَرِي بِهِۦ ثَمَنࣰا﴾: لا نأخُذُ عِوَضًا من الدُّنيا، ولا نُحابي أحدًا.\n\n﴿وَلَوۡ كَانَ ذَا قُرۡبَىٰ﴾: ولو كانَ المشهودُ له قريبًا."],[107,107,"﴿فَإِنۡ عُثِرَ عَلَىٰٓ أَنَّهُمَا ٱسۡتَحَقَّآ إِثۡمࣰا﴾: إنْ ظَهَرَ لأولياءِ الميتِ أنّ الشاهدَين الكافرَين قد أثِما بالخيانةِ في الشهادةِ.\n\n﴿مِنَ ٱلَّذِينَ ٱسۡتَحَقَّ عَلَيۡهِمُ ٱلۡأَوۡلَيَـٰنِ﴾: أي: الأَجْدران من الذين وجَبَ عليهم أن يكونا أقربَ أولياءِ الميتِ إليه.\n\n﴿وَمَا ٱعۡتَدَيۡنَآ﴾: وما تجاوَزْنا الحقَّ في أيْمانِنا."],[108,108,"﴿ذَ ٰ⁠لِكَ أَدۡنَىٰٓ أَن يَأۡتُواْ بِٱلشَّهَـٰدَةِ عَلَىٰ وَجۡهِهَآ﴾: ذلك الحكمُ عند الارتيابِ في الشاهدَين الكافرَين من الحَلْفِ أقربُ إلى أن يأتُوا بالشهادة على حقيقتِها.\n\n﴿أَوۡ يَخَافُوٓاْ أَن تُرَدَّ أَيۡمَـٰنُۢ بَعۡدَ أَيۡمَـٰنِهِمۡ﴾: أو خَشْيَةَ أن تُرَدَّ اليمينُ الكاذبةُ من قِبَلِ أصحابِ الحقِّ الذين يَحْلِفُون بما يتضَمَّنُ كَذِبَ الكافرين."],[109,109,"﴿مَاذَآ أُجِبۡتُمۡ﴾: ماذا أجابَتْكم أممكُم؟\n\n﴿لَا عِلۡمَ لَنَآ﴾: لا نعلمُ ما في صدورِهم، وما أحدَثُوا بعدنا."],[110,110,"﴿نِعۡمَتِي عَلَيۡكَ﴾: إذ خَلَقْتُك من غيرِ أبٍ.\n\n﴿وَعَلَىٰ وَ ٰ⁠لِدَتِكَ﴾: إذ رَفَعْتُ شأنَها، وبَرَّأتُها مما نُسِبَ إليها.\n\n﴿بِرُوحِ ٱلۡقُدُسِ﴾: جبريلَ.\n\n﴿فِي ٱلۡمَهۡدِ﴾: وأنت رضيعٌ قبل أوانِ الكلامِ.\n\n﴿وَكَهۡلࣰا﴾: وكبيرًا، لا يتفاوَتُ كلامُك في الحالَين.\n\n﴿ٱلۡكِتَـٰبَ﴾: وعَلَّمْتُك الكتابةَ.\n\n﴿وَٱلۡحِكۡمَةَ﴾: قوةَ الفهمِ، والإدراكِ.\n\n﴿ٱلۡأَكۡمَهَ﴾: مَن وُلِدَ أعمى.\n\n﴿تُخۡرِجُ ٱلۡمَوۡتَىٰ﴾: من قُبورِهم أحياءً.\n\n﴿كَفَفۡتُ بَنِيٓ إِسۡرَ ٰ⁠ٓءِيلَ﴾: مَنَعْتُهم حين هَمُّوا بقَتْلِكَ."],[111,111,"﴿ٱلۡحَوَارِيِّـۧنَ﴾: خُلَصاءِ عيسى عليه السلام."],[112,112,"﴿مِنَ ٱلشَّـٰهِدِينَ﴾: على هذه الآيةِ، فتكونُ حُجّةً لك."],[114,114,"﴿تَكُونُ لَنَا عِيدࣰا﴾: نَتَّخِذُ يومَ نُزُولِها عيدًا لنا، فنُعَظِّمُه.\n\n﴿لِّأَوَّلِنَا وَءَاخِرِنَا﴾: لنا ولمَن بعدَنا من عَقِبِنا.\n\n﴿وَءَايَةࣰ﴾: وعلامةً على صِدْقِك."],[117,117,"﴿شَهِيدࣰا﴾: رقيبًا.\n\n﴿تَوَفَّيۡتَنِي﴾: وفَّيْتَ أجلي على الأرضِ ورَفَعْتَني إلى السماءِ حيًّا."]]);
QTF("gharib",6,[[1,1,"﴿وَجَعَلَ ٱلظُّلُمَـٰتِ وَٱلنُّورَ﴾: وخَلَقَ سَوادَ الليلِ، وضياءَ النهارِ.\n\n﴿يَعۡدِلُونَ﴾: يُشْرِكُون."],[2,2,"﴿خَلَقَكُم﴾: خَلَقَ أباكم آدمَ.\n\n﴿قَضَىٰٓ أَجَلࣰا﴾: قَدَّر مُدَّةَ بقائِكم في الدنيا.\n\n﴿وَأَجَلࣱ مُّسَمًّى عِندَهُۥ﴾: وقَدَّر أجلًا محدَّدًا هو يومُ القِيامةِ.\n\n﴿تَمۡتَرُونَ﴾: تَشُكُّون في أمرِ الساعةِ."],[3,3,"﴿سِرَّكُمۡ وَجَهۡرَكُمۡ﴾: ما تُخْفُونه، وما تُعْلِنُونه.\n\n﴿مَا تَكۡسِبُونَ﴾: جميعَ أعمالِكم."],[4,4,"﴿مِّنۡ ءَايَةࣲ﴾: من دليلٍ على أنّ اللهَ حقُّ."],[5,5,"﴿أَنۢبَـٰٓؤُاْ مَا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ﴾: أخبارُ ما استَهْزَؤُوا به، وهو القرآنُ، أو محمدٌ ﷺ."],[6,6,"﴿مِّن قَرۡنࣲ﴾: من أمةٍ مُكَذِّبَةٍ.\n\n﴿مَا لَمۡ نُمَكِّن لَّكُمۡ﴾: ما لم نُعْطِكم، كطُولِ الأعمارِ، وقوةِ الأبدانِ.\n\n﴿مِّدۡرَارࣰا﴾: مطرًا كثيرًا.\n\n﴿قَرۡنًا ءَاخَرِينَ﴾: أممًا أخرى."],[7,7,"﴿كِتَـٰبࣰا فِي قِرۡطَاسࣲ﴾: كتابًا مكتوبًا في صحيفةٍ."],[8,8,"﴿مَلَكࣰا﴾: أي: لِيُصَدِّقَه، ويُنْذِرَ معه.\n\n﴿لَّقُضِيَ ٱلۡأَمۡرُ﴾: بإهلاكِهم، والمعاجَلَةِ بعقوبتِهم.\n\n﴿لَا يُنظَرُونَ﴾: لا يُمْهَلُون للتوبةِ."],[9,9,"﴿وَلَوۡ جَعَلۡنَـٰهُ﴾: ولو جَعَلْنا الرسولَ المُرْسَلَ إلى النبيِّ ﷺ.\n\n﴿وَلَلَبَسۡنَا عَلَيۡهِم مَّا يَلۡبِسُونَ﴾: ولَكان الأمرُ مختلِطًا عليهم بسببِ ما لَبَسُوه على أنفسِهم."],[10,10,"﴿فَحَاقَ﴾: فَنَزَل وأحاطَ.\n\n﴿مَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ﴾: هو العذابُ الذي كانوا يستنكرونه."],[13,13,"﴿مَا سَكَنَ﴾: ما استقرَّ."],[14,14,"﴿وَلِيࣰّا﴾: مَعْبُودًا.\n\n﴿فَاطِرِ﴾: خالقِ.\n\n﴿أَسۡلَمَ﴾: انقادَ، واستسلمَ"],[16,16,"﴿مَّن يُصۡرَفۡ عَنۡهُ﴾: أي: العذابُ."],[18,18,"﴿ٱلۡقَاهِرُ﴾: الغالِبُ."],[19,19,"﴿وَمَنۢ بَلَغَ﴾: كلَّ مَن بَلَغَه."],[22,22,"﴿أَيۡنَ شُرَكَآؤُكُمُ﴾: أين آلهتُكم لينفعُوكُم؟"],[23,23,"﴿فِتۡنَتُهُمۡ﴾: جوابُهم حين يُخْتَبَرُون بهذا السؤالِ."],[24,24,"﴿وَضَلَّ عَنۡهُم﴾: وغابَ عنهم.\n\n﴿مَّا كَانُواْ يَفۡتَرُونَ﴾: ما كانوا يعتقدونه مِن نَفْعِ آلهتِهم له."],[25,25,"﴿أَكِنَّةً﴾: أغْطِيةً فلا تفقهُ القرآنَ فِقْهَ انتفاعٍ به.\n\n﴿وَقۡرࣰا﴾: ثِقَلًا، وصَمَمًا.\n\n﴿يُجَـٰدِلُونَكَ﴾: يُخاصِمُونك.\n\n﴿أَسَـٰطِيرُ﴾: ما سَطَّرُوه من الأباطيلِ."],[26,26,"﴿يَنۡهَوۡنَ عَنۡهُ﴾: يَنْهَون الناسَ عن اتِّباع محمدٍ ﷺ.\n\n﴿وَيَنۡـَٔوۡنَ عَنۡهُ﴾: ويَبْتَعِدُون عنه."],[27,27,"﴿وُقِفُواْ﴾: حُبِسُوا.\n\n﴿نُرَدُّ﴾: إلى الدُّنيا."],[28,28,"﴿بَدَا﴾: ظَهَرَ.\n\n﴿مَّا كَانُواْ يُخۡفُونَ﴾: أي: عن أتْباعهِم من أمْرِ البعثِ، وصِدْقِ الرُّسُلِ.\n\n﴿لَكَـٰذِبُونَ﴾: في أنهم لو عادُوا إلى الدنيا لآمَنوا."],[29,29,"﴿بِمَبۡعُوثِينَ﴾: بعد الموتِ."],[30,30,"﴿وُقِفُواْ﴾: حُبِسوا.\n\n﴿هَـٰذَا﴾: أي: البعثُ الذي كنتم تُنْكِرونه."],[31,31,"﴿ٱلسَّاعَةُ﴾: يومُ القيامةِ.\n\n﴿عَلَىٰ مَا فَرَّطۡنَا فِيهَا﴾: على ما قَدَّمْناه في حياتِنا الدُّنيا.\n\n﴿أَوۡزَارَهُمۡ﴾: ذنوبَهم.\n\n﴿يَزِرُونَ﴾: يَحْمِلون."],[33,33,"﴿لَا يُكَذِّبُونَكَ﴾: في قَرارةِ أنفسِهم، بل يعتقدون صِدْقَك."],[34,34,"﴿لِكَلِمَـٰتِ ٱللَّهِ﴾: لِآياتِه التي وعَدَ فيها النبيَّ ﷺ بالنصرِ."],[35,35,"﴿نَفَقࣰا﴾: مَنفَذًا، وسَرَبًا.\n\n﴿سُلَّمࣰا﴾: دَرَجًا تَرْتقي عليه.\n\n﴿فَتَأۡتِيَهُم بِـَٔايَةࣲ﴾: بغيرِما جِئْنا به."],[36,36,"﴿يَسۡمَعُونَ﴾: سَماعَ تَفَهُّمٍ لِما تَقْتَضيه العقولُ.\n\n﴿وَٱلۡمَوۡتَىٰ﴾: هم الكفارُ."],[37,37,"﴿لَوۡلَا﴾: هَلّا.\n\n﴿ءَايَةࣱ﴾: علامةٌ تَدُلُّ على صِدْقِه، وتَضْطَرُّهُمْ إلى الإيمانِ.\n\n﴿لَا يَعۡلَمُونَ﴾: أي: إنّ الإنزالَ يكونُ وفْقَ حِكْمَتِه تعالى."],[38,38,"﴿أُمَمٌ﴾: جماعاتٌ متجانِسَةٌ في الخَلْقِ والرِّزقِ.\n\n﴿مَّا فَرَّطۡنَا﴾: ما أغفَلْنا.\n\n﴿ٱلۡكِتَـٰبِ﴾: اللوحِ المحفوظِ."],[39,39,"﴿صُمࣱّ﴾: لا يَسْمَعُون ما ينفَعُهم.\n\n﴿وَبُكۡمࣱ﴾: لا يتكلَّمُون بالحقِّ.\n\n﴿فِي ٱلظُّلُمَـٰتِ﴾: في ظلماتِ الكفرِ، والحَيْرةِ.\n\n﴿صِرَ ٰ⁠طࣲ﴾: طريقٍ."],[40,40,"﴿أَرَءَيۡتَكُمۡ﴾: أخْبرُوني.\n\n﴿عَذَابُ ٱللَّهِ﴾: في الدُّنيا.\n\n﴿إِن كُنتُمۡ صَـٰدِقِينَ﴾: أي: في أنّ آلهتَكُم تنفَعُ، أو تضرُّ."],[41,41,"﴿وَتَنسَوۡنَ مَا تُشۡرِكُونَ﴾: وتَتْرُكون آلهتَكم."],[42,42,"﴿بِٱلۡبَأۡسَآءِ﴾: في الأموالِ.\n\n﴿وَٱلضَّرَّآءِ﴾: في الأبدانِ.\n\n﴿يَتَضَرَّعُونَ﴾: يَتَذَلَّلُون لربِّهم."],[43,43,"﴿فَلَوۡلَآ﴾: فَهَلّا.\n\n﴿بَأۡسُنَا﴾: بَلاؤُنا."],[44,44,"﴿أَبۡوَ ٰ⁠بَ كُلِّ شَيۡءٍ﴾: من الخيرِ كالرزقِ والعافيةِ، استدراجًا منّا.\n\n﴿بَغۡتَةࣰ﴾: فَجأة.\n\n﴿مُّبۡلِسُونَ﴾: يائِسون من كلِّ خيرٍ."],[45,45,"﴿فَقُطِعَ دَابِرُ ٱلۡقَوۡمِ﴾: فاسْتُؤصِلُوا جميعًا."],[46,46,"﴿وَخَتَمَ عَلَىٰ قُلُوبِكُم﴾: وطَبَعَ عليها.\n\n﴿بِهِ﴾: بذلك المأخوذِ منكم.\n\n﴿نُصَرِّفُ ٱلۡـَٔايَـٰتِ﴾: نَجِيءُ بالحُجَجِ على وجوهٍ متعددةٍ.\n\n﴿يَصۡدِفُونَ﴾: يُعْرِضُون."],[47,47,"﴿بَغۡتَةً﴾: من غيرِ مُقَدِّماتٍ.\n\n﴿جَهۡرَةً﴾: بعد مُقَدِّماتٍ تَدُلُّ عليه."],[49,49,"﴿يَفۡسُقُونَ﴾: يَخْرُجُون عن طاعةِ اللهِ."],[50,50,"﴿وَلَآ أَعۡلَمُ ٱلۡغَيۡبَ﴾: أي: فأُخْبِرَكم بما سيكونُ مستقبلًا.\n\n﴿ٱلۡأَعۡمَىٰ وَٱلۡبَصِيرُ﴾: الضالُّ والمهتدي."],[51,51,"﴿وَأَنذِرۡ بِهِ﴾: وأعْلِمْ، وخَوِّفْ -أيها الرسولُ- بالقرآنِ.\n\n﴿وَلِيࣱّ﴾: ناصرٌ يَنْصُرُهم.\n\n﴿وَلَا شَفِيعࣱ﴾: يَشْفَعُ لهم من دونِ اللهِ."],[52,52,"﴿وَلَا تَطۡرُدِ ٱلَّذِينَ﴾: ولا تُبْعِدْ عن مَجالسِك الضُّعفاءَ؛ موافَقَةً لمن طَلَبَ منك.\n\n﴿بِٱلۡغَدَوٰةِ وَٱلۡعَشِيِّ﴾: أولِ النهار، وآخرِه."],[53,53,"﴿فَتَنَّا﴾: ابتَلَيْنا عبادَنا باختلافِ حظوظِهم في الرِّزْقِ والُخلُقِ، اختبارًا منا.\n\n﴿لِّيَقُولُوٓاْ﴾: ليقولَ الكافرون الأغنياءُ.\n\n﴿أَهَـٰٓؤُلَآءِ﴾: الضعفاءُ من المسلمين.\n\n﴿مَنَّ ٱللَّهُ عَلَيۡهِم﴾: أي: بالهدايةِ دونَنا."],[54,54,"﴿ٱلَّذِينَ يُؤۡمِنُونَ﴾: يُصَدِّقُون.\n\n﴿بِجَهَـٰلَةࣲ﴾: أي: منه لعاقبتِها."],[55,55,"﴿وَلِتَسۡتَبِينَ سَبِيلُ﴾: ولتظهَرَ طريقُ."],[57,57,"﴿بَيِّنَةࣲ﴾: بَصيرةٍ، ويقينٍ.\n\n﴿وَكَذَّبۡتُم بِهِۦ﴾: بالحقِّ الذي جاءني من الله.\n\n﴿مَا تَسۡتَعۡجِلُونَ بِهِۦٓ﴾: من العذابِ.\n\n﴿ٱلۡفَـٰصِلِينَ﴾: بين الحقِّ والباطلِ."],[59,59,"﴿مَفَاتِحُ ٱلۡغَيۡبِ﴾: خزائنُ الغيبِ تُخَزَّنُ فيها، كعِلْمِ الساعةِ وعِلْمِ ما يَسْتَعْجِلُه الكفّارُ من العذابِ.\n\n﴿كِتَـٰبࣲ مُّبِينࣲ﴾: هو اللَّوحُ المحفوظُ الذي لا لَبْسَ فيه."],[60,60,"﴿يَتَوَفَّىٰكُم﴾: في أثناءِ نومِكم، فيَقْبِضُ نفوسَكم التي بها تُمَيِّزُون.\n\n﴿جَرَحۡتُم﴾: كسَبْتُم بجَوارِ حِكم من الخيرِ والشرِّ.\n\n﴿يَبۡعَثُكُمۡ﴾: باليقظةِ من النومِ.\n\n﴿فِيهِ﴾: في النهارِ.\n\n﴿لِيُقۡضَىٰٓ أَجَلࣱ مُّسَمࣰّى﴾: لتُقْضى آجالُكم المحدَّدةُ في الدنيا."],[61,61,"﴿حَفَظَةً﴾: ملائكةً يَحْفَظُون أعمالَكم ورِزْقَكم وأَجَلَكم.\n\n﴿رُسُلُنَا﴾: من الملائكةِ المُكَلَّفين بذلك.\n\n﴿لَا يُفَرِّطُونَ﴾: لا يُضَيِّعُون ما أُمِرُوا به."],[63,63,"﴿تَضَرُّعࣰا﴾: دعاءَ تَذَلُّلٍ جَهْرًا."],[64,64,"﴿كَرۡبࣲ﴾: شِدَّةٍ وغَمّ."],[65,65,"﴿مِّن فَوۡقِكُمۡ﴾: كالطُّوفان.\n\n﴿مِن تَحۡتِ أَرۡجُلِكُمۡ﴾: كالزِّلزالِ.\n\n﴿يَلۡبِسَكُمۡ شِيَعࣰا﴾: يَخْلِطَ أمْرَكم عليكم، فتكونوا فِرَقًا متناحِرَةً يَتَشَيَّعُ بعضُها لبعضٍ.\n\n﴿وَيُذِيقَ بَعۡضَكُم بَأۡسَ بَعۡضٍ﴾: يَقْتلَ بعضُكم بعضًا.\n\n﴿نُصَرِّفُ ٱلۡـَٔايَـٰتِ﴾: نَجيءُ بالحُجَجِ على وجوهٍ متعددةٍ."],[66,66,"﴿بِهِۦ﴾: بالقرآنِ، أو العذابِ.\n\n﴿بِوَكِيلࣲ﴾: بحفيظٍ على أعمالِكم حتى أُجازيَكم بها."],[67,67,"﴿لِّكُلِّ نَبَإࣲ مُّسۡتَقَرࣱّ﴾: لكلِّ شيءٍ وقْتٌ يَقَعُ فيه."],[68,68,"﴿يَخُوضُونَ﴾: بالاستهزاءِ والباطلِ.\n\n﴿وَإِمَّا يُنسِيَنَّكَ﴾: وإنْ أنساك.\n\n﴿ٱلذِّكۡرَىٰ﴾: تَذَكُّرِك."],[69,69,"﴿مِنۡ حِسَابِهِم مِّن شَيۡءࣲ﴾: ليس على المؤمنين شيءٌ من حِسابِ اللهِ على استهزاءِ المشركين.\n\n﴿وَلَـٰكِن ذِكۡرَىٰ﴾: ولكنْ على المؤمنين أن يُذَكِّروا المشركين ليُمْسِكوا عن الخوضِ."],[70,70,"﴿وَذَرِ﴾: واتْرُك.\n\n﴿بِهِۦٓ﴾: بالقرآن.\n\n﴿أَن تُبۡسَلَ نَفۡسُۢ﴾: لكيلا تُحْبَسَ، وتُفْضَحَ.\n\n﴿وَلِيࣱّ﴾: ناصرٌ.\n\n﴿وَلَا شَفِيعࣱ﴾: يَشْفَعُ لها في الآخرة.\n\n﴿وَإِن تَعۡدِلۡ كُلَّ عَدۡلࣲ﴾: وإن تَفْتَدِ بأيِّ فداءٍ.\n\n﴿حَمِيمࣲ﴾: شديدِ الحرارةِ، وهو ما يَسِيلُ من صديدِهم."],[71,71,"﴿وَنُرَدُّ عَلَىٰٓ أَعۡقَابِنَا﴾: ونَرْجِعُ إلى الضَّلالةِ.\n\n﴿ٱسۡتَهۡوَتۡهُ﴾: هَوَتْ به، وأضَلَّتْه.\n\n﴿لِنُسۡلِمَ﴾: لنَنْقادَ، ونُخْلِصَ."],[73,73,"﴿ٱلصُّورِ﴾: القَرْنِ الذي يُنفَخُ فيه للبعثِ.\n\n﴿وَٱلشَّهَـٰدَةِ﴾: وما تُشاهِدُونه."],[74,74,"﴿مُّبِينࣲ﴾: واضحٍ."],[75,75,"﴿وَكَذَ ٰ⁠لِكَ نُرِيٓ﴾: كما أرَيْناه الحقَّ نُرِيه.\n\n﴿مَلَكُوتَ﴾: المُلْكَ العظيمَ.\n\n﴿ٱلۡمُوقِنِينَ﴾: الراسِخين في الإيمان."],[76,76,"﴿جَنَّ﴾: أظلمَ.\n\n﴿هَـٰذَا رَبِّي﴾: حَكى ما يعتقدونه لأَجْلِ إلْزامِهم الحُجَّةَ.\n\n﴿أَفَلَ﴾: غابَ."],[77,77,"﴿بَازِغࣰا﴾: طالعًا."],[79,79,"﴿وَجَّهۡتُ وَجۡهِيَ﴾: قَصَدْتُ بعبادتي.\n\n﴿فَطَرَ﴾: خَلَقَ.\n\n﴿حَنِيفࣰا﴾: مائلًا عن الشِّرْكِ."],[80,80,"﴿وَحَآجَّهُۥ قَوۡمُهُۥ﴾: وجادَلَه قومُه.\n\n﴿وَلَآ أَخَافُ مَا تُشۡرِكُونَ بِهِۦٓ﴾: لاأخافُ آلهتَكم، فلن تَضُرَّني."],[81,81,"﴿سُلۡطَـٰنࣰا﴾: حُجَّةً بيِّنةً.\n\n﴿بِٱلۡأَمۡنِ﴾: أي: من عذابِ اللهِ."],[82,82,"﴿يَلۡبِسُوٓاْ﴾: يَخْلِطُوا.\n\n﴿بِظُلۡمٍ﴾: بشِرْكٍ."],[83,83,"﴿وَتِلۡكَ حُجَّتُنَآ﴾: وتلك البراهينُ التي أوْرَدَها إبراهيمُ."],[86,86,"﴿ٱلۡعَـٰلَمِينَ﴾: من أهلِ زمانِهم."],[87,87,"﴿وَٱجۡتَبَيۡنَـٰهُمۡ﴾: واختَرْناهم."],[88,88,"﴿لَحَبِطَ﴾: لَبَطَلَ."],[89,89,"﴿وَٱلۡحُكۡمَ﴾: والعِلْمَ.\n\n﴿هَـٰٓؤُلَآءِ﴾: أهلُ مكةَ.\n\n﴿وَكَّلۡنَا بِهَا﴾: ألْزَمْنا بالإيمانِ بها."],[90,90,"﴿أُوْلَـٰٓئِكَ﴾: أي: الأنبياءُ.\n\n﴿إِنۡ هُوَ إِلَّا ذِكۡرَىٰ﴾: ما القرآنُ إلا تذكيرٌ."],[91,91,"﴿وَمَا قَدَرُواْ ٱللَّهَ حَقَّ قَدۡرِهِۦٓ﴾: وما عَرَفَ هؤلاء المشركون رَبَّهم حَقَّ مَعْرفَتِه.\n\n﴿تَجۡعَلُونَهُۥ قَرَاطِيسَ﴾: تكتبون عنه دفاترَ وكتبًا مُقَطَّعةً؛ فيَتِمُّ لكم ما تُريدونه من التحريفِ.\n\n﴿خَوۡضِهِمۡ﴾: باطِلِهم."],[92,92,"﴿بَيۡنَ يَدَيۡهِ﴾: ماتَقَدَّمَه من الكتبِ السماويةِ.\n\n﴿أُمَّ ٱلۡقُرَىٰ﴾: مكةَ."],[93,93,"﴿غَمَرَ ٰ⁠تِ ٱلۡمَوۡتِ﴾: أهوالِه وشدائدِه.\n\n﴿بَاسِطُوٓاْ أَيۡدِيهِمۡ﴾: لقَبْضِ أرواحِ الكفّارِ، وتَعْذ يبهم.\n\n﴿أَخۡرِجُوٓاْ أَنفُسَكُمُ﴾: يقولون لهم: أخْرِجُوا أنفسَكم إلينا.\n\n﴿ٱلۡهُونِ﴾: الهَوانِ والذُّلِّ."],[94,94,"﴿مَّا خَوَّلۡنَـٰكُمۡ﴾: ما مَكَّنّاكم فيه من الدنيا، كالأموالِ والأولادِ، فلم تَنْتَفعوا.\n\n﴿أَنَّهُمۡ فِيكُمۡ شُرَكَـٰٓؤُاْ﴾: شركاءُ للهِ يَسْتحقون العبادةَ.\n\n﴿بَيۡنَكُمۡ﴾: تَواصُلُكم الذي كان بينَكم في الحياةِ الدنيا.\n\n﴿وَضَلَّ﴾: ذهبَ، وغابَ."],[95,95,"﴿فَالِقُ ٱلۡحَبِّ﴾: يَشُقُّه، فيَخْرُجُ منه الزَّرع.\n\n﴿وَٱلنَّوَىٰ﴾: جَمْعِ النَّواة، وهي البِذْرةُ.\n\n﴿يُخۡرِجُ ٱلۡحَيَّ مِنَ ٱلۡمَيِّتِ﴾: كالإنسانِ من النُّطفةِ.\n\n﴿وَمُخۡرِجُ ٱلۡمَيِّتِ مِنَ ٱلۡحَيِّ﴾: كالنُّطفةِ من الإنسانِ.\n\n﴿فَأَنَّىٰ تُؤۡفَكُونَ﴾: فكيف تُصْرَفون عن الحقِّ، وتَعْبُدُون مع الله غيرَه؟"],[96,96,"﴿فَالِقُ ٱلۡإِصۡبَاحِ﴾: يَشُقُّ ضياءَ الصَّباحِ من ظلامِ الليلِ.\n\n﴿حُسۡبَانࣰا﴾: جَعَلَهُما محلَّ حسابٍ لمصالحِ العباد، وأَجْراهما بحِسابٍ مُقَدَّرٍ."],[98,98,"﴿مِّن نَّفۡسࣲ وَ ٰ⁠حِدَةࣲ﴾: آدمَ عليه السلام.\n\n﴿فَمُسۡتَقَرࣱّ﴾: هي أرحامُ النساءِ.\n\n﴿وَمُسۡتَوۡدَعࣱ﴾: هي أصلابُ الرجالِ."],[99,99,"﴿فَأَخۡرَجۡنَا مِنۡهُ﴾: من النَّباتِ.\n\n﴿خَضِرࣰا﴾: زَرْعًا، وشَجَرًا أخضرَ.\n\n﴿مُّتَرَاكِبࣰا﴾: يَرْكَبُ بعضُه بعضًا كسَنابلِ القَمْحِ.\n\n﴿مِن طَلۡعِهَا﴾: الطَّلْعُ: ما تنشأُ فيه عناقيدُ الرُّطَبِ.\n\n﴿قِنۡوَانࣱ﴾: جمعُ قِنْو، وهو عُنقودُ النَّخْلِ.\n\n﴿دَانِيَةࣱ﴾: قريبةٌ إلى الأرض.\n\n﴿مُشۡتَبِهࣰا﴾: في المنظرِ.\n\n﴿وَغَيۡرَ مُتَشَـٰبِهٍ﴾: في الطَّعْمِ.\n\n﴿ٱنظُرُوٓاْ﴾: فَكِّرُوا في قُدْرَةِ خالقهِ.\n\n﴿وَيَنۡعِهِۦٓ﴾: ونُضْجِه."],[100,100,"﴿وَخَرَقُواْ﴾: واختَلَقُوا، ونَسَبُوا."],[101,101,"﴿بَدِيعُ﴾: مُبْدِعٌ على غيرِ مثالٍ سَبَقَ.\n\n﴿أَنَّىٰ﴾: كيف؟"],[102,102,"﴿وَكِيلࣱ﴾: رقيبٌ مُدَبِّرٌ لأمورِ خَلْقِه."],[103,103,"﴿لَّا تُدۡرِكُهُ﴾: لا تُحيطُ به، ولا تَبْلُغُ كُنْهَ حَقيقتِه."],[104,104,"﴿بَصَآئِرُ﴾: براهينُ واضحةٌ.\n\n﴿فَعَلَيۡهَا﴾: فعلى نفسِه يعودُ وبالُ ذلك.\n\n﴿بِحَفِيظࣲ﴾: أُحْصِي أعمالَكم، بل أنا مُبَلِّغٌ."],[105,105,"﴿نُصَرِّفُ ٱلۡـَٔايَـٰتِ﴾: نُبَيِّنُ البراهينَ، والحُجَجَ.\n\n﴿وَلِيَقُولُواْ دَرَسۡتَ﴾: أي: لتقومَ الحُجَّةُ عليهم، وليقولوا: تَعَلَّمْتَ من أهلِ الكتابِ."],[107,107,"﴿حَفِيظࣰا﴾: رقيبًا تحفَظُ أقوالَهم وأعمالَهم.\n\n﴿بِوَكِيلࣲ﴾: مُوَكَّلٍ على أمورِهم."],[108,108,"﴿ٱلَّذِينَ يَدۡعُونَ مِن دُونِ ٱللَّهِ﴾: هم الأصنامُ.\n\n﴿عَدۡوَۢا﴾: اعتداءً.\n\n﴿زَيَّنَّا﴾: حَسَّنّا."],[109,109,"﴿جَهۡدَ أَيۡمَـٰنِهِمۡ﴾: بأيمانٍ مُؤَكَّدةٍ.\n\n﴿ءَايَةࣱ﴾: معجزةٌ خارقةٌ:\n\n﴿وَمَا يُشۡعِرُكُمۡ﴾: وما يُدْريكم.\n\n﴿أَنَّهَآ﴾: لعلَّ المعجزاتِ."],[110,110,"﴿وَنُقَلِّبُ أَفۡـِٔدَتَهُمۡ﴾: فنَحُولُ بينَهم وبينَ الإيمانِ.\n\n﴿فِي طُغۡيَـٰنِهِمۡ﴾: في تَمَرُّدِهم.\n\n﴿يَعۡمَهُونَ﴾: يَتَحَيَّرون، فلا يَهْتَدُون إلى الحقِّ."],[111,111,"﴿وَحَشَرۡنَا﴾: وجَمَعْنا.\n\n﴿قُبُلࣰا﴾: فعايَنُوه مُواجَهةً."],[112,112,"﴿شَيَـٰطِينَ ٱلۡإِنسِ﴾: هم المَرَدَةُ العُتاةُ من الإنسِ.\n\n﴿زُخۡرُفَ ٱلۡقَوۡلِ﴾: هو القولُ المُزَيَّنُ.\n\n﴿غُرُورࣰا﴾: ليَغْتَرَّ به سامِعُه.\n\n﴿وَمَا يَفۡتَرُونَ﴾: وما يَخْتَلِقُونه من كَذِبٍ."],[113,113,"﴿وَلِتَصۡغَىٰٓ إِلَيۡهِ﴾: ولتَمِيلَ إلى القولِ المُزَيَّنِ.\n\n﴿وَلِيَقۡتَرِفُواْ﴾: ولِيكْتَسِبُوا من الأعمالِ السيئةِ."],[114,114,"﴿أَبۡتَغِي﴾: أطْلُبُ.\n\n﴿ٱلۡمُمۡتَرِينَ﴾: الشّاكِّين."],[115,115,"﴿كَلِمَتُ رَبِّكَ﴾: القرآنُ الكريمُ.\n\n﴿لَّا مُبَدِّلَ لِكَلِمَـٰتِهِۦ﴾: لا أحدَ مُغَيِّرٌ لما حَكَمَ به."],[116,116,"﴿يَخۡرُصُونَ﴾: يظنُّون، يَكْذِبُون."],[119,119,"﴿وَمَا لَكُمۡ أَلَّا﴾: وأيُّ شيءٍ يَمْنَعُكم؟"],[120,120,"﴿ظَـٰهِرَ ٱلۡإِثۡمِ وَبَاطِنَهُۥٓ﴾: عَلانِيَتُه وسِرُّه.\n\n﴿يَقۡتَرِفُونَ﴾: يكتسِبُون."],[121,121,"﴿لَفِسۡقࣱ﴾: لَخُروجٌ عن طاعةِ اللهِ.\n\n﴿لَيُوحُونَ﴾: لَيُوَسْوِسُون لهم بما يخالِفُ الحقَّ.\n\n﴿لِيُجَـٰدِلُوكُمۡ﴾: ليُثيروا الشبهاتِ لمجادَلَتِكم."],[122,122,"﴿مَيۡتࣰا﴾: في الضلالةِ.\n\n﴿زُيِّنَ﴾: حُسِّنَ."],[123,123,"﴿أَكَـٰبِرَ مُجۡرِمِيهَا﴾: رُؤَساءَها وعُظماءَها.\n\n﴿لِيَمۡكُرُواْ فِيهَا﴾: بالصَّدِّ عن دينِ اللهِ.\n\n﴿وَمَا يَمۡكُرُونَ إِلَّا بِأَنفُسِهِمۡ﴾: وبالُ مَكْرِهم عائدٌ عليهم."],[124,124,"﴿أَعۡلَمُ حَيۡثُ يَجۡعَلُ رِسَالَتَهُۥ﴾: أعلمُ بمَن يَسْتحِقُّ أن يجعلَه رسولًا، فدَعُوا طَلَبَ ماليسَ مِن شأنِكم.\n\n﴿صَغَارٌ﴾: ذلٌّ، وهَوانٌ."],[125,125,"﴿حَرَجࣰا﴾: شديدَ الضِّيقِ.\n\n﴿يَصَّعَّدُ﴾: يتكَلَّفُ ما لا يُطيقُ من الصُّعود.\n\n﴿ٱلرِّجۡسَ﴾: الشيطانَ."],[126,126,"﴿صِرَ ٰ⁠طُ رَبِّكَ﴾: الإسلاُم.\n\n﴿ٱلۡـَٔايَـٰتِ﴾: البراهينَ."],[127,127,"﴿دَارُ ٱلسَّلَـٰمِ﴾: دارُ السَّلامةِ من المكروه، وهي الجنةُ.\n\n﴿وَلِيُّهُم﴾: ناصِرُهم."],[128,128,"﴿يَحۡشُرُهُمۡ﴾: أي: جميعَ الثَّقَلَيْن من الجنِّ والإنسِ.\n\n﴿ٱسۡتَكۡثَرۡتُم مِّنَ ٱلۡإِنسِ﴾: بإضلالهِم، وصَدِّهم عن سبيلِ اللهِ.\n\n﴿ٱسۡتَمۡتَعَ بَعۡضُنَا بِبَعۡضࣲ﴾: استمتاعُ الجنِّ بالإنس: تَلَذُّذهم باتِّباع الإنسِ لهم، واستمتاعُ الإنس بالجن: قَبولُهم تحسينَ المعاصي منهم، فوقَعُوا فيها، وتَلَذَّ ذُوا بها.\n\n﴿وَبَلَغۡنَآ أَجَلَنَا﴾: بانقضاءِ حياتِنا الدنيا، ووُصولِنا إلى دارِ الجَزاءِ.\n\n﴿مَثۡوَىٰكُمۡ﴾: موضعُ مَقامِكم.\n\n﴿إِلَّا مَا شَآءَ ٱللَّهُ﴾: أي: شاءَ عَدَمَ خُلودِه، من عُصاةِ المُوَحِّدِين."],[129,129,"﴿نُوَلِّي بَعۡضَ ٱلظَّـٰلِمِينَ بَعۡضَۢا﴾: نُسَلِّط بعضَ الظّالمين من الإنسِ على بعضٍ في الدنيا."],[130,130,"﴿رُسُلࣱ مِّنكُمۡ﴾: الرسُلُ هم من الإنسِ، ورسُلُ الجِنِّ هم الذين يُنْذِرُون قومَهم.\n\n﴿وَغَرَّتۡهُمُ﴾: وخَدَعَتْهم زِينتُها، فاطمأنُّوا إليها."],[131,131,"﴿بِظُلۡمࣲ﴾: بسببِ ظُلْمِ مَن يَظْلِمُ.\n\n﴿وَأَهۡلُهَا غَـٰفِلُونَ﴾: أي: لا يُهلِكُهم إلا بعد إرسالِ الرسل، وارتفاعِ الغفلةِ عنهم بذلك، وتَحَقُّقِ الإنذارِ."],[132,132,"﴿دَرَجَـٰتࣱ﴾: مراتبُ."],[133,133,"﴿كَمَآ أَنشَأَكُم مِّن ذُرِّيَّةِ قَوۡمٍ ءَاخَرِينَ﴾: أحْدَثَكم من نَسْلِ خَلْقٍ آخرين كانوا قبلَكم."],[134,134,"﴿بِمُعۡجِزِينَ﴾: بفائتين عَمّا هو نازلٌ بكم."],[135,135,"﴿مَكَانَتِكُمۡ﴾: طريقتِكم، فاثبُتُوا عليها.\n\n﴿عَـٰقِبَةُ ٱلدَّارِ﴾: الجنةُ."],[136,136,"﴿ذَرَأَ﴾: خَلَقَ.\n\n﴿ٱلۡحَرۡثِ﴾: ثمراتِ الزَّرْعِ.\n\n﴿لِشُرَكَآئِنَا﴾: للأصنامِ التي يعبُدونها."],[137,137,"﴿قَتۡلَ أَوۡلَـٰدِهِمۡ﴾: وهو دَفْنُ البناتِ وهُنَّ أحياءٌ.\n\n﴿شُرَكَآؤُهُمۡ﴾: رؤساؤُهم، وشياطينُهم.\n\n﴿لِيُرۡدُوهُمۡ﴾: ليُهْلِكُوهم.\n\n﴿وَلِيَلۡبِسُواْ﴾: ولِيَخْلِطُوا."],[138,138,"﴿وَحَرۡثٌ﴾: وزَرْعٌ.\n\n﴿حِجۡرࣱ﴾: ممنوعةٌ، فهي لأصنامِهم.\n\n﴿حُرِّمَتۡ﴾: فلا يركبونَها."],[139,139,"﴿خَالِصَةࣱ﴾: حلالٌ.\n\n﴿أَزۡوَ ٰ⁠جِنَا﴾: نسائِنا.\n\n﴿شُرَكَآءُ﴾: يأكلُ منه الذكورُ والإناثُ.\n\n﴿وَصۡفَهُمۡ﴾: جزاءَ وصْفِهم."],[140,140,"﴿سَفَهَۢا﴾: طَيشًا.\n\n﴿مَا رَزَقَهُمُ﴾: من الأنعام."],[141,141,"﴿جَنَّـٰتࣲ مَّعۡرُوشَـٰتࣲ﴾: بساتينَ مرفوعاتٍ عن الأرض كالعِنَبِ.\n\n﴿وَغَيۡرَ مَعۡرُوشَـٰتࣲ﴾: قائمةً على سُوقِها كالنَّخْلِ، أوما خَرَج في البَرِّ.\n\n﴿مُتَشَـٰبِهࣰا﴾: في المنظرِ.\n\n﴿وَغَيۡرَ مُتَشَـٰبِهࣲ﴾: في الطَّعْمِ.\n\n﴿وَءَاتُواْ حَقَّهُۥ﴾: بالزَّكاةِ والصدقات."],[142,142,"﴿حَمُولَةࣰ﴾: مُهَيَّأً للحَمْلِ عليه.\n\n﴿وَفَرۡشࣰا﴾: صِغارَ الأنعامِ."],[143,143,"﴿ثَمَـٰنِيَةَ أَزۡوَ ٰ⁠جࣲ﴾: هذه الأنعامُ ثمانيةُ أصنافٍ، أربعةٌ منها في الغنم، وهي: الضَّأْنُ ذُكورًا وإناثًا، والمَعْزُ ذكورًا وإناثًا، وأربعةٌ في الإبِلِ والبقَرِ، ذكورًا وإناثًا.\n\n﴿أَمَّا ٱشۡتَمَلَتۡ عَلَيۡهِ﴾: أي: هل حَرَّمَ ما اشتملت عليه؟ فإن كان التحريمُ منه فإن ذلك يَسْتَلْزِم ُ تحريمَ الجميعِ، فلماذا حَلَّلُوا بعضَها، وحَرَّمُوا بعضَها الآخر؟"],[144,144,"﴿شُهَدَآءَ﴾: حاضِرين."],[145,145,"﴿مُحَرَّمًا﴾: أي: طعامًا محرَّمًا.\n\n﴿عَلَىٰ طَاعِمࣲ يَطۡعَمُهُۥٓ﴾: على مَن يأكلُه.\n\n﴿مَّسۡفُوحًا﴾: جاريًا.\n\n﴿رِجۡسٌ﴾: نَجَسٌ.\n\n﴿أُهِلَّ لِغَيۡرِ ٱللَّهِ بِهِۦ﴾: هو المذبوحُ الذي ذُكِرَ عليه اسمُ غيرِ اللهِ.\n\n﴿فَمَنِ ٱضۡطُرَّ﴾: إلى الأَكْلِ من هذه المحرَّماتِ.\n\n﴿غَيۡرَ بَاغࣲ﴾: غيرَ طالبٍ بأَكْلِه التلذُّذَ.\n\n﴿وَلَا عَادࣲ﴾: ولا متجاوزٍ حَدَّ الضَّرورةِ."],[146,146,"﴿إِلَّا مَا حَمَلَتۡ ظُهُورُهُمَآ﴾: إلا الشَّحْمَ المخالِطَ لظُهورِهما.\n\n﴿أَوِ ٱلۡحَوَايَآ﴾: أو المخالِطَ للأمعاءِ.\n\n﴿بِبَغۡيِهِمۡ﴾: بأعمالهِم السيئةِ."],[147,147,"﴿وَلَا يُرَدُّ بَأۡسُهُۥ﴾: ولا يُدْفَعُ عِقابُه إنْ أنْزَلَه بهم."],[148,148,"﴿وَلَا حَرَّمۡنَا مِن شَيۡءࣲ﴾: أي: لو شاءَ ما حَرَّمْنا على أنفسِنا شيئًا من الأنعام.\n\n﴿بَأۡسَنَا﴾: عقابَنا.\n\n﴿تَخۡرُصُونَ﴾: تَتَوَهَّمون، وتظنون."],[149,149,"﴿ٱلۡحُجَّةُ ٱلۡبَـٰلِغَةُ﴾: هي القاطِعَةُ لشُبَهِهِم، وهذه الحُجَّةُ هي الرُّسُلُ، وما جاؤُوا به من كُتُبٍ، ومعجزاتٍ."],[150,150,"﴿هَلُمَّ﴾: هاتُوا.\n\n﴿حَرَّمَ هَـٰذَا﴾: حَرَّم ماحَرَّمْتُم من الأنعام.\n\n﴿فَلَا تَشۡهَدۡ﴾: لأنّ شهادتَهم باطلةٌ.\n\n﴿يَعۡدِلُونَ﴾: يُشْرِكون."],[151,151,"﴿إِمۡلَـٰقࣲ﴾: فَقْرٍ.\n\n﴿مَا ظَهَرَ﴾: ما أُعْلِنَ منها.\n\n﴿وَمَا بَطَنَ﴾: ما خَفِيَ منها."],[152,152,"﴿بِٱلَّتِي هِيَ أَحۡسَنُ﴾: بما يُصْلِحُ مالَه، وينتفعُ به.\n\n﴿يَبۡلُغَ أَشُدَّهُۥ﴾: وهو سِنُّ البُلوغِ مع الرُّشْدِ، فادفعُوا إليه ماله.\n\n﴿بِٱلۡقِسۡطِ﴾: بالعدلِ.\n\n﴿وُسۡعَهَا﴾: طاقَتَها.\n\n﴿وَبِعَهۡدِ ٱللَّهِ أَوۡفُواْ﴾: بما عَهِدَ به إليكم من الالتزامِ بشرعِه."],[153,153,"﴿هَـٰذَا صِرَ ٰ⁠طِي﴾: الإسلامُ طريقي.\n\n﴿ٱلسُّبُلَ﴾: طُرُقَ الضَّلالِ والبِدَعِ.\n\n﴿فَتَفَرَّقَ بِكُمۡ﴾: فتميلَ بكم."],[154,154,"﴿تَمَامًا عَلَى ٱلَّذِيٓ أَحۡسَنَ﴾: تمامًا لنِعْمَتِه على المُحْسنين من مِلَّتِه."],[155,155,"﴿وَهَـٰذَا﴾: أي: القرآنُ."],[156,156,"﴿أَن تَقُولُوٓاْ﴾: لئلّا تقولُوا أيها الكفارُ.\n\n﴿طَآئِفَتَيۡنِ﴾: اليهودِ والنصارى.\n\n﴿وَإِن كُنَّا﴾: وإنّنا كنّا.\n\n﴿دِرَاسَتِهِمۡ﴾: تلاوةِ كتبِهم بلُغاتها.\n\n﴿لَغَـٰفِلِينَ﴾: لاندْري ما فيها."],[157,157,"﴿أَهۡدَىٰ مِنۡهُمۡ﴾: أشَدَّ استقامةً على الحقِّ.\n\n﴿وَصَدَفَ﴾: أعرَضَ."],[158,158,"﴿يَنظُرُونَ﴾: ينتظر المُعْرِضون.\n\n﴿ٱلۡمَلَـٰٓئِكَةُ﴾: المختصُّون بقَبْضِ الأرواحِ.\n\n﴿يَأۡتِيَ رَبُّكَ﴾: للفَصْل بين عبادِه يومَ القيامةِ.\n\n﴿بَعۡضُ ءَايَـٰتِ رَبِّكَ﴾: بعضُ علاماتِ السّاعةِ.\n\n﴿مِن قَبۡلُ﴾: من قبلِ إتيانِ هذه الآياتِ.\n\n﴿خَيۡرࣰا﴾: عملًا صالحًا."],[159,159,"﴿فَرَّقُواْ دِينَهُمۡ﴾: جَعَلُوه متفرِّقًا، فأخذوا ببعضِه، وتركوا بعضَه.\n\n﴿شِيَعࣰا﴾: فِرَقًا وأحزابًا."],[161,161,"﴿صِرَ ٰ⁠طࣲ مُّسۡتَقِيمࣲ﴾: طريقٍ لا عِوَجَ فيه، وهو الإسلامُ.\n\n﴿قِيَمࣰا﴾: يقومُ بأمْرِ الدنيا والآخرةِ.\n\n﴿حَنِيفࣰا﴾: مائلًا إلى الحقِّ."],[162,162,"﴿وَنُسُكِي﴾: وذَبْحي للأنعام.\n\n﴿وَمَحۡيَايَ﴾: ما أعمَلُه في حياتي.\n\n﴿وَمَمَاتِي﴾: ما يُقَدِّره عليّ في الموتِ."],[163,163,"﴿أَوَّلُ ٱلۡمُسۡلِمِينَ﴾: أولُ مَن انقادَ للهِ من هذه الأمةِ."],[164,164,"﴿أَبۡغِي﴾: أطْلُبُ.\n\n﴿وَلَا تَكۡسِبُ كُلُّ نَفۡسٍ إِلَّا عَلَيۡهَا﴾: لا يُؤاخَذُ ممّا أتَتْ به من الذَّنبِ سِواها.\n\n﴿وَلَا تَزِرُ وَازِرَةࣱ وِزۡرَ أُخۡرَىٰ﴾: ولا تَحْمِلُ نفسٌ آثمةٌ إثمَ نفسٍ أخرى."],[165,165,"﴿خَلَـٰٓئِفَ﴾: خُلَفاءَ الأممِ الماضيةِ.\n\n﴿وَرَفَعَ بَعۡضَكُمۡ فَوۡقَ بَعۡضࣲ﴾: في الرِّزقِ والقوةِ وغيرِهما.\n\n﴿دَرَجَـٰتࣲ﴾: مراتبَ.\n\n﴿لِّيَبۡلُوَكُمۡ﴾: ليختبرَكم.\n\n﴿فِي مَآ ءَاتَىٰكُمۡ﴾: أي: من نِعَمِه."]]);
QTF("gharib",7,[[1,1,"﴿الٓمٓصٓ﴾: سبقَ شرحُ الحروفِ المقطَّعة أولَ سورة البقرة."],[2,2,"﴿حَرَجࣱ﴾: ضِيقٌ منه لتبليغِه.\n\n﴿وَذِكۡرَىٰ﴾: وتذكيرٍ."],[3,3,"﴿أَوۡلِيَآءَ﴾: أنصارًا كالشياطين والأحبارِ."],[4,4,"﴿أَهۡلَكۡنَـٰهَا﴾: أرَدْنا إهلاكَها.\n\n﴿بَأۡسُنَا﴾: عذابُنا.\n\n﴿بَيَـٰتًا﴾: نائمين ليلًا.\n\n﴿قَآئِلُونَ﴾: حالَ استراحتِهم وسطَ النهارِ."],[7,7,"﴿عَلَيۡهِم﴾: على الرسُلِ والمُرْسَلِ إليهم.\n\n﴿بِعِلۡمࣲ﴾: عالمِين بما يُسِرُّون، وما يُعْلِنون."],[8,8,"﴿وَٱلۡوَزۡنُ يَوۡمَئِذٍ ٱلۡحَقُّ﴾: وزنُ صحائفِ الأعمالِ بالميزانِ العَدْلِ.\n\n﴿ثَقُلَتۡ مَوَ ٰ⁠زِينُهُۥ﴾: بثِقَلِ ما فيها من أعمالٍ حسنةٍ."],[10,10,"﴿مَكَّنَّـٰكُمۡ﴾: جَعَلْنا لكم مكانًا.\n\n﴿مَعَـٰيِشَ﴾: ما تعيشُون به من مَأْكَلٍ، ومَشْرَبٍ."],[11,11,"﴿خَلَقۡنَـٰكُمۡ﴾: خَلَقْنا أباكم آدمَ من ترابٍ.\n\n﴿صَوَّرۡنَـٰكُمۡ﴾: صَوَّرْناه على الهيئةِ المفضَّلَةِ."],[12,12,"﴿مَا مَنَعَكَ أَلَّا تَسۡجُدَ﴾: ما مَنَعَكَ من السجودِ فأَحْوَجَك ألّا تسجدَ."],[13,13,"﴿فَٱهۡبِطۡ مِنۡهَا﴾: فانْزِلْ من الجنةِ.\n\n﴿تَتَكَبَّرَ فِيهَا﴾: تَتَعالى في الجنةِ عن أمري وطاعتي.\n\n﴿ٱلصَّـٰغِرِينَ﴾: الذَّلِيلِين الحقيرِين."],[14,14,"﴿أَنظِرۡنِيٓ﴾: أمْهِلْني.\n\n﴿يَوۡمِ يُبۡعَثُونَ﴾: يومَ يُحيي اللهُ الخَلْقَ."],[15,15,"﴿مِنَ ٱلۡمُنظَرِينَ﴾: ممن كَتَبْتُ عليهم تأخيرَ الأجَلِ إلى النفخةِ الأولى."],[16,16,"﴿فَبِمَآ أَغۡوَيۡتَنِي﴾: فبسببِ إضلالِكَ لي.\n\n﴿لَأَقۡعُدَنَّ لَهُمۡ﴾: لَأَتَرَبَّصَنَّ في إغواءِ بني آدمَ.\n\n﴿صِرَ ٰ⁠طَكَ ٱلۡمُسۡتَقِيمَ﴾: طريقَك القويمَ، وهو الإسلامُ."],[17,17,"﴿شَـٰكِرِينَ﴾: ذاكِرين نعمتَك مُثْنِين بها عليك."],[18,18,"﴿مَذۡءُومࣰا﴾: ممقُوتًا مَعِيبًا.\n\n﴿مَّدۡحُورࣰا﴾: مُبْعَدًا مَطْرودًا."],[19,19,"﴿ٱلظَّـٰلِمِينَ﴾: المتجاوِزِين حُدودَ اللهِ."],[20,20,"﴿فَوَسۡوَسَ لَهُمَا﴾: فألقى الشيطانُ لآدمَ وحواءَ وسْوَسَةً لإيقاعِهما في معصيةِ اللهِ.\n\n﴿مَا وُۥرِيَ﴾: ما سُتِرَ.\n\n﴿سَوۡءَ ٰ⁠ تِهِمَا﴾: عَوْراتِهما.\n\n﴿ٱلۡخَـٰلِدِينَ﴾: في الجنةِ، الماكثين فيها أبدًا."],[21,21,"﴿وَقَاسَمَهُمَآ﴾: وحَلَفَ الشيطانُ باللهِ لآدمَ وحوّاءَ."],[22,22,"﴿فَدَلَّىٰهُمَا﴾: فأوقعهما وجَرَّأهما على ما أراد.\n\n﴿بِغُرُورࣲ﴾: بخِداعِه.\n\n﴿وَطَفِقَا﴾: وأَخَذا.\n\n﴿يَخۡصِفَانِ﴾: يَلْصَقانِ على عَوْراتهِما."],[23,23,"﴿ظَلَمۡنَآ أَنفُسَنَا﴾: بمخالفةِ أمْرِك."],[24,24,"﴿ٱهۡبِطُواْ﴾: انزِلُوا من الجنةِ إلى الأرضِ.\n\n﴿وَمَتَـٰعٌ﴾: ما تتمتعون به.\n\n﴿إِلَىٰ حِينࣲ﴾: إلى وقتِ انقضاءِ آجالِكم."],[25,25,"﴿تُخۡرَجُونَ﴾: تُبْعَثُون أحياءً من الأرض يومَ القيامةِ."],[26,26,"﴿أَنزَلۡنَا﴾: جَعَلْنا لكم.\n\n﴿يُوَ ٰ⁠رِي﴾: يَسْتُرُ.\n\n﴿سَوۡءَ ٰ⁠ تِكُمۡ﴾: عَوْراتِكم.\n\n﴿وَرِيشࣰا﴾: لباسًا للزِّينةِ والتجمُّلِ.\n\n﴿وَلِبَاسُ ٱلتَّقۡوَىٰ﴾: ولباسُ تقوى الله بفِعْل الأوامرِ واجتنابِ النواهي."],[27,27,"﴿لَا يَفۡتِنَنَّكُمُ﴾: لا يَخْدَعَنَّكم الشيطانُ بتزيينِ المعصيةِ.\n\n﴿لِيُرِيَهُمَا سَوۡءَ ٰ⁠ تِهِمَآ﴾: لتنكشِفَ لهما عوراتُهما.\n\n﴿وَقَبِيلُهُۥ﴾: ذريّةُ الشيطانِ.\n\n﴿أَوۡلِيَآءَ﴾: أنصارًا."],[28,28,"﴿فَـٰحِشَةࣰ﴾: قَبيحًا من الفِعْلِ."],[29,29,"﴿بِٱلۡقِسۡطِ﴾: بالعدلِ.\n\n﴿وَأَقِيمُواْ وُجُوهَكُمۡ﴾: وأخْلِصُوا لله العبادةَ.\n\n﴿عِندَ كُلِّ مَسۡجِدࣲ﴾: في كلِّ موضعٍ من مواضعِ العبادةِ، ولا سِيَّما المساجدُ.\n\n﴿ٱلدِّينَ﴾: الطاعةَ والعبادةَ."],[30,30,"﴿حَقَّ عَلَيۡهِمُ﴾: ثَبَتَتْ لهم، ووَجَبَتْ عليهم."],[31,31,"﴿زِينَتَكُمۡ﴾: الزينةَ المشروعةَ من ثيابٍ ساترةٍ، ونظافةٍ، وطهارةٍ.\n\n﴿عِندَ كُلِّ مَسۡجِدࣲ﴾: عند أداءِ كلِّ صلاةٍ.\n\n﴿وَلَا تُسۡرِفُوٓاْ﴾: ولا تتجاوزُوا حدودَ الاعتدالِ."],[32,32,"﴿زِينَةَ ٱللَّهِ﴾: اللِّباسَ الحسنَ الذي جَعَلَه اللهُ زينةً لكم.\n\n﴿خَالِصَةࣰ﴾: مخصوصةً بالمؤمنين."],[33,33,"﴿ٱلۡفَوَ ٰ⁠حِشَ﴾: القبائحَ من الأعمالِ.\n\n﴿وَمَا بَطَنَ﴾: وما كان خفيًّا.\n\n﴿وَٱلۡإِثۡمَ﴾: المعاصيَ كلَّها.\n\n﴿وَٱلۡبَغۡيَ﴾: الاعتداءَ على الناس.\n\n﴿سُلۡطَـٰنࣰا﴾: دليلًا وبرهانًا.\n\n﴿وَأَن تَقُولُواْ عَلَى ٱللَّهِ مَا لَا تَعۡلَمُونَ﴾: وحَرَّم اللهُ أن تَنْسِبوا إليه ما لم يَشْرَعْه."],[34,34,"﴿أَجَلࣱ﴾: وقتٌ لحُلولِ العقوبةِ.\n\n﴿لَا يَسۡتَأۡخِرُونَ﴾: لا يتأخَّرُون عنه.\n\n﴿وَلَا يَسۡتَقۡدِمُونَ﴾: ولا يتقدَّمُون عليه."],[35,35,"﴿يَقُصُّونَ﴾: يَتْلُون ويُبَيِّنُون.\n\n﴿ءَايَـٰتِي﴾: آياتِ كتابي، وأدلَّتي على صِدْقِ ما جاؤُوا به."],[36,36,"﴿وَٱسۡتَكۡبَرُواْ عَنۡهَآ﴾: استعْلَوا عن اتِّباع دلائلِ توحيدِ اللهِ."],[37,37,"﴿ٱفۡتَرَىٰ﴾: اختلَقَ.\n\n﴿نَصِيبُهُم﴾: حَظُّهم من خيرٍ وشّرٍ في الدَنيا.\n\n﴿مِّنَ ٱلۡكِتَـٰبِ﴾: مما كُتِبَ لهم في اللَّوحِ المحفوظِ.\n\n﴿رُسُلُنَا﴾: مَلَكُ الموتِ وأعوانُه.\n\n﴿يَتَوَفَّوۡنَهُمۡ﴾: يقبِضُون أرواحَهم.\n\n﴿ضَلُّواْ عَنَّا﴾: ذهَبُوا عنّا.\n\n﴿وَشَهِدُواْ﴾: واعتَرفوا."],[38,38,"﴿فِيٓ أُمَمࣲ﴾: في جملةِ جماعاتٍ من أمثالِكم في الكفر.\n\n﴿خَلَتۡ﴾: سَبَقتْ.\n\n﴿لَّعَنَتۡ أُخۡتَهَا﴾: لَعَنَتِ الجماعةُ الداخلةُ النارَ،نظيرتَها من أهلِ ملَّتِها.\n\n﴿ٱدَّارَكُواْ فِيهَا﴾: اجتمعَتِ الأممُ في النار جميعًا.\n\n﴿أُخۡرَىٰهُمۡ﴾: منزلةً ودخولًا، وهم الأتباعُ.\n\n﴿لِأُولَىٰهُمۡ﴾: منزلةً ودخولًا، وهم الرؤساءُ والقادةُ في الضلالِ.\n\n﴿ضِعۡفࣰا﴾: زائدًا على مِثْلِه مرَّةً أو مرّاتٍ.\n\n﴿لَّا تَعۡلَمُونَ﴾: لا تدْرِكُون -أيها الأتباعُ- ما لكلِّ فريقٍ منكم من العذابِ."],[39,39,"﴿فَمَا كَانَ لَكُمۡ عَلَيۡنَا مِن فَضۡلࣲ﴾: نحن القادةُ متساوون معكم-أيُّها الأتباعُ- في الضَّلالِ واستحقاقِ العذابِ."],[40,40,"﴿بِـَٔايَـٰتِنَا﴾: بحُجَجِنا وآياتِنا الدالَّةِ على وحْدانيَّتِنا.\n\n﴿وَٱسۡتَكۡبَرُواْ عَنۡهَا﴾: واستعْلَوْا عن التصديقِ بها، والعملِ بَشْرعِنا.\n\n﴿لَا تُفَتَّحُ لَهُمۡ أَبۡوَ ٰ⁠بُ ٱلسَّمَآءِ﴾: لا يَصْعَدُ لهم في الحياةِ إلى اللهِ عملٌ صالحٌ، ولا تُفَتَّحُ لأرواحِهم إذا ماتوا أبوابُ السماءِ.\n\n﴿حَتَّىٰ يَلِجَ﴾: إلا إذا دَخَلَ.\n\n﴿سَمِّ ٱلۡخِيَاطِ﴾: ثَقْبِ الإبرةِ."],[41,41,"﴿مِهَادࣱ﴾: فراشٌ مِن تحتهم.\n\n﴿غَوَاشࣲ﴾: أغطيةٌ من النارِ."],[42,42,"﴿إِلَّا وُسۡعَهَآ﴾: إلّا ما تُطيقُ من الأعمالِ."],[43,43,"﴿وَنَزَعۡنَا﴾: وأذهبَ اللهُ تعالى.\n\n﴿مِّنۡ غِلࣲّ﴾: من حِقْدٍ وضغائنَ كانت من بعضِهم في الدُّنيا.\n\n﴿مِن تَحۡتِهِمُ﴾: من تحتِ غُرَفِهم ومنازلهِم.\n\n﴿هَدَىٰنَا لِهَـٰذَا﴾: وفَّقَنا للعملِ الصالحِ.\n\n﴿أُورِثۡتُمُوهَا﴾: آلَ أمرُكم إليها."],[44,44,"﴿مَا وَعَدَنَا رَبُّنَا﴾: على ألسنةِ رُسُلِه من إثابةِ أهلِ طاعتِه.\n\n﴿مَّا وَعَدَ رَبُّكُمۡ﴾: على ألسنةِ رسُلِه من عِقابِ أهلِ معصيتِه.\n\n﴿فَأَذَّنَ مُؤَذِّنُۢ﴾: فنادى منادٍ.\n\n﴿لَّعۡنَةُ ٱللَّهِ﴾: غَضَبُ اللهِ وسَخَطُه.\n\n﴿ٱلظَّـٰلِمِينَ﴾: الذين كفرُوا، وتجاوَزُوا حدودَه."],[45,45,"﴿وَيَبۡغُونَهَا عِوَجࣰا﴾: ويَطْلُبون أن تكونَ سبيلُ اللهِ غيرَ مستقيمةٍ."],[46,46,"﴿وَبَيۡنَهُمَا﴾: وبينَ أصحابِ الجنةِ وأصحابِ النارِ.\n\n﴿حِجَابࣱ﴾: حاجزٌ عظيمٌ يسمّى ب «الأعراف».\n\n﴿وَعَلَى ٱلۡأَعۡرَافِ رِجَالࣱ﴾: وعلى أعالي ذلك السُّورِ رجالٌ استوَتْ حسناتُهم وسيئاتُهم.\n\n﴿كُلَّۢا﴾: من أهلِ الجنةِ والنارِ.\n\n﴿بِسِيمَىٰهُمۡ﴾: بعلاماتِهم، كبياضِ وجوهِ أهلِ الجنةِ، وسوادِ وجوهِ أهلِ النارِ.\n\n﴿يَطۡمَعُونَ﴾: يَرْجُون دخولَ الجنةِ."],[47,47,"﴿صُرِفَتۡ﴾: حُوِّلَتْ.\n\n﴿تِلۡقَآءَ﴾: جِهةَ."],[48,48,"﴿مَآ أَغۡنَىٰ عَنكُمۡ﴾: ما نَفَعكم.\n\n﴿جَمۡعُكُمۡ﴾: ما كنتم تَجْمعون من الأموالِ والرجالِ."],[49,49,"﴿أَهَـٰٓؤُلَآءِ﴾: أي: الضعفاءُ والفقراءُ.\n\n﴿لَا يَنَالُهُمُ ٱللَّهُ بِرَحۡمَةٍ﴾: لا يُدْخِلُهم الجنةَ."],[50,50,"﴿أَفِيضُواْ﴾: صُبُّوا بكثرةٍ.\n\n﴿رَزَقَكُمُ ٱللَّهُ﴾: من الطعام."],[51,51,"﴿ٱتَّخَذُواْ دِينَهُمۡ لَهۡوࣰا وَلَعِبࣰا﴾: جَعَلُوا ما أمرَهم اللهُ باتِّباعِه لهوًا وباطلًا.\n\n﴿وَغَرَّتۡهُمُ﴾: وخَدَعَتْهم.\n\n﴿نَنسَىٰهُمۡ﴾: نُعامِلُهم معاملةَ الشيء المَنسِيِّ.\n\n﴿كَمَا نَسُواْ﴾: كما تركُوا العملَ.\n\n﴿يَوۡمِهِمۡ هَـٰذَا﴾: يومِ القيامةِ.\n\n﴿بِـَٔايَـٰتِنَا يَجۡحَدُونَ﴾: يُنكرون أدلةَ اللهِ وبراهينَه مع عِلْمِهم بأنها حقٌّ."],[52,52,"﴿بِكِتَـٰبࣲ﴾: بقرآنٍ أنزَلْناه إليك.\n\n﴿فَصَّلۡنَـٰهُ﴾: بيَّناه أتمَّ بَيانٍ."],[53,53,"﴿هَلۡ يَنظُرُونَ﴾: ما ينتظرون.\n\n﴿تَأۡوِيلَهُۥ﴾: ما يَؤولُ إليه أمرُهم من العقابِ.\n\n﴿نَسُوهُ مِن قَبۡلُ﴾: تَرَكُوا الإيمانَ بالقرآنِ في الدنيا.\n\n﴿أَوۡ نُرَدُّ﴾: أو نُعادُ إلى الدنيا.\n\n﴿خَسِرُوٓاْ أَنفُسَهُمۡ﴾: صاروا إلى الهَلاكِ بدخولِهم النارَ وخُلودِهم فيها.\n\n﴿وَضَلَّ﴾: وذَهَبَ.\n\n﴿يَفۡتَرُونَ﴾: يَعْبُدُونه من دونِ اللهِ."],[54,54,"﴿ٱسۡتَوَىٰ﴾: علا وارتفعَ، استواءً يَليق بجَلالِه وعَظَمَتِه.\n\n﴿ٱلۡعَرۡشِ﴾: سريرِ المُلْكِ الذي استوى عليه الرحمنُ، وتَحْمِلُه الملائكة، وهو أعظمُ المخلوقات، وهو سَقْفُ الجنةِ.\n\n﴿يُغۡشِي ٱلَّيۡلَ ٱلنَّهَارَ﴾: يُدْخِلُ سبحانَه الليلَ على النهارِ حتى يَذْهَبَ نورُه، ويُدْخِلُ النهارَ على الليل حتى يَذْهَبَ ظلامُه.\n\n﴿يَطۡلُبُهُۥ﴾: كلٌّ من الليلِ والنهارِ يَطْلُبُ الآخَرَ.\n\n﴿حَثِيثࣰا﴾: طَلَبًا سريعًا دائمًا.\n\n﴿مُسَخَّرَ ٰ⁠تِۭ﴾: مُذَلَّلاتٍ خاضعاتٍ.\n\n﴿لَهُ ٱلۡخَلۡقُ﴾: إيجادُ الأشياءِ من العَدَمِ.\n\n﴿وَٱلۡأَمۡرُ﴾: التدبيرُ والتصرُّفُ في مخلوقاتِه كما يشاءُ.\n\n﴿تَبَارَكَ ٱللَّهُ﴾: كَثُرَتْ بَرَكَتُه واتسعَتْ."],[55,55,"﴿تَضَرُّعࣰا﴾: تَذَلُّلًا.\n\n﴿وَخُفۡيَةً﴾: سِرًّا.\n\n﴿ٱلۡمُعۡتَدِينَ﴾: المتجاوِزِين حدودَ ما شَرَعَه اللهُ."],[56,56,"﴿بَعۡدَ إِصۡلَـٰحِهَا﴾: ببعثةِ الرسلِ وعُمْرانِها بطاعةِ اللهِ."],[57,57,"﴿بُشۡرَۢا﴾: مُبَشِّراتٍ بالمطرِ قبلَ نزولِه.\n\n﴿بَيۡنَ يَدَيۡ رَحۡمَتِهِۦ﴾: أمامَ نزولِ المطرِ.\n\n﴿أَقَلَّتۡ﴾: حَمَلَتْ.\n\n﴿ثِقَالࣰا﴾: مُحمَّلًا بالمطرِ.\n\n﴿لِبَلَدࣲ مَّيِّتࣲ﴾: لأرضٍ لا نباتَ فيها ولا مَرْعى."],[58,58,"﴿وَٱلۡبَلَدُ ٱلطَّيِّبُ يَخۡرُجُ نَبَاتُهُۥ﴾: مَثَلٌ ضربَه اللهُ للمؤمنِ بأنه طَيِّبٌ وعَمَلَه طيبٌ.\n\n﴿وَٱلَّذِي خَبُثَ﴾: مَثَلٌ ضَرَبَه اللهُ للكافرِ بأنه خبيثٌ وعَمَلَه خبيثٌ.\n\n﴿نَكِدࣰا﴾: عسِرًا رديئًا لا نَفْعَ فيه.\n\n﴿نُصَرِّفُ﴾: نُبَيِّنُ.\n\n﴿ٱلۡـَٔايَـٰتِ﴾: الحُجَجَ والبراهينَ."],[60,60,"﴿ٱلۡمَلَأُ﴾: أشرافُ القومِ وسادتُهم.\n\n﴿ضَلَـٰلࣲ﴾: ذَهابٍ عن الحقِّ والصوابِ."],[62,62,"﴿وَأَعۡلَمُ مِنَ ٱللَّهِ﴾: وأَعْلَمُ مما أوحاه الله إليَّ من شريعتِه."],[64,64,"﴿ٱلۡفُلۡكِ﴾: السفينةِ.\n\n﴿بِـَٔايَـٰتِنَآ﴾: بحُجَجِنا الواضحةِ.\n\n﴿عَمِينَ﴾: جَمْعُ عَمٍ، أي: لا تُبْصِرُ قلوبُهم الحقَّ والإيمان."],[65,65,"﴿عَادٍ﴾: قومِ هودٍ عليه السلام، وهم قبيلةٌ من العربِ."],[66,66,"﴿سَفَاهَةࣲ﴾: خِفَّةِ عقلٍ وحَماقةٍ.\n\n﴿لَنَظُنُّكَ﴾: لَنُوقِنُ بأنك."],[68,68,"﴿أَمِينٌ﴾: على ما أقولُ من وحْيِ اللهِ."],[69,69,"﴿خُلَفَآءَ﴾: تَخْلُفُون في الأرض مَن قبلَكم.\n\n﴿بَصۜۡطَةࣰ﴾: قوةً وضَخامةً وطُولًا.\n\n﴿ءَالَآءَ ٱللَّهِ﴾: جَمْعُ إلىً، وهي نِعَمُه الكثيرةُ عليكم."],[70,70,"﴿وَنَذَرَ﴾: ونَتْرُكَ.\n\n﴿بِمَا تَعِدُنَآ﴾: بما تُخَوِّفُنا به من العذابِ."],[71,71,"﴿رِجۡسࣱ﴾: عذابٌ.\n\n﴿وَغَضَبٌ﴾: سُخْطٌ وانتقامٌ.\n\n﴿أَسۡمَآءࣲ سَمَّيۡتُمُوهَآ﴾: أصنامٍ سَمَّيتُموها آلهةً.\n\n﴿سُلۡطَـٰنࣲ﴾: حُجَّةٍ ومَعْذِرةٍ تعتذرون بها.\n\n﴿فَٱنتَظِرُوٓاْ﴾: نزولَ عذابِ الله عليكم."],[72,72,"﴿وَقَطَعۡنَا دَابِرَ﴾: وأهْلَك اللهُ الكفارَ من قومِ عادٍ، واستأصَلَهم بالريحِ."],[73,73,"﴿ثَمُودَ﴾: قومِ صالحٍ عليه السلام، وهم قبيلةٌ من العربِ.\n\n﴿بَيِّنَةࣱ﴾: برهانٌ على صِدْقِ نبيِّكم.\n\n﴿ءَايَةࣰ﴾: دليلًا على نبوَّتي.\n\n﴿فَذَرُوهَا﴾: فاترُكُوها.\n\n﴿بِسُوٓءࣲ﴾: بأيِّ أذى."],[74,74,"﴿خُلَفَآءَ﴾: تَخْلُفُون في الأرضِ مَن قبلَكم.\n\n﴿وَبَوَّأَكُمۡ﴾: ومَكَّن لكم وأَنْزَلَكم.\n\n﴿فِي ٱلۡأَرۡضِ﴾: أرضِ الحِجْرِ.\n\n﴿قُصُورࣰا﴾: بيوتًا عظيمةً.\n\n﴿وَلَا تَعۡثَوۡاْ﴾: ولا تُفْرِطُوا في الفَساد."],[75,75,"﴿ٱسۡتَكۡبَرُواْ﴾: استَعْلَوْا عن الإيمان."],[77,77,"﴿فَعَقَرُواْ ٱلنَّاقَةَ﴾: فنَحرُوها.\n\n﴿وَعَتَوۡاْ﴾: وتجاوَزُوا الحَدَّ في الاستِكْبار.\n\n﴿بِمَا تَعِدُنَآ﴾: بما تتوعَّدُنا به من العَذابِ."],[78,78,"﴿ٱلرَّجۡفَةُ﴾: الزَّلزلةُ الشديدةُ من الأرضِ.\n\n﴿جَـٰثِمِينَ﴾: لاصِقِين بالأرضِ على رُكَبهِم ووُجوهِهم، لا حَراكَ بهم."],[79,79,"﴿فَتَوَلَّىٰ﴾: فأَعْرَضَ."],[80,80,"﴿ٱلۡفَـٰحِشَةَ﴾: الفَعْلَةَ المُنْكَرةُ، وهي إتيانُ الرِّجالِ."],[81,81,"﴿مِّن دُونِ ٱلنِّسَآءِ﴾: تاركين ما أحلَّه اللهُ لكم من نسائِكم.\n\n﴿مُّسۡرِفُونَ﴾: متجاوِزُون ما أحلَّه اللهُ لكم إلى الحَرامِ."],[82,82,"﴿يَتَطَهَّرُونَ﴾: يتنزَّهُون عن إتيانِ الرجالِ في أدبارِهم."],[83,83,"﴿ٱلۡغَـٰبِرِينَ﴾: الهالِكين الباقين في العذابِ."],[84,84,"﴿وَأَمۡطَرۡنَا عَلَيۡهِم﴾: وأرسل اللهُ على الكفارِ من قومِ لوطٍ.\n\n﴿مَّطَرࣰا﴾: حجارةً متتابعةً."],[85,85,"﴿مَدۡيَنَ﴾: قومِ شُعَيبٍ عليه السَّلام، وهم قبيلةٌ من العربِ.\n\n﴿بَيِّنَةࣱ﴾: حُجَّةٌ ظاهرةٌ.\n\n﴿فَأَوۡفُواْ﴾: فأتِمُّوا.\n\n﴿وَلَا تَبۡخَسُواْ﴾: ولا تَنْقُصُوا.\n\n﴿بَعۡدَ إِصۡلَـٰحِهَا﴾: بشرائعِ الأنبياءِ، وعُمْرانِها بطاعَةِ اللهِ."],[86,86,"﴿صِرَ ٰ⁠طࣲ﴾: طريقٍ.\n\n﴿تُوعِدُونَ﴾: تُخَوِّفون الناسَ بالقَتْل إن لم يُعْطُوكم أموالَهم.\n\n﴿وَتَبۡغُونَهَا عِوَجࣰا﴾: وتُريدون أن تكونَ سبيلُ اللهِ مائلة وفْقَ أهوائِكم."],[87,87,"﴿فَٱصۡبِرُواْ﴾: فانتظرُوا أيُّها المكذِّبون.\n\n﴿يَحۡكُمَ ٱللَّهُ بَيۡنَنَا﴾: يَفْصِلَ بينَنا وبينكَم."],[88,88,"﴿ٱسۡتَكۡبَرُواْ﴾: استعلَوْا عن الإيمانِ.\n\n﴿مِلَّتِنَا﴾: دينِنا."],[89,89,"﴿ٱفۡتَحۡ﴾: احكُمْ.\n\n﴿ٱلۡفَـٰتِحِينَ﴾: الحاكمين."],[91,91,"﴿ٱلرَّجۡفَةُ﴾: الزَّلزلةُ الشديدةُ من الأرضِ.\n\n﴿جَـٰثِمِينَ﴾: لاصِقين بالأرضِ على رُكَبِهم ووجوهِهم، لا حَراكَ بهم."],[92,92,"﴿كَأَن لَّمۡ يَغۡنَوۡاْ فِيهَا﴾: كأنّ قومَ شُعَيبٍ لم يُقيموا في ديارِهم، و يتمتَّعوا فيها."],[93,93,"﴿فَتَوَلَّىٰ﴾: فأَعرَضَ.\n\n﴿ءَاسَىٰ﴾: أحْزَنُ."],[94,94,"﴿مِّن نَّبِيٍّ﴾: أي: كذَّبه قومُه.\n\n﴿أَخَذۡنَآ﴾: ابتلَينا.\n\n﴿بِٱلۡبَأۡسَآءِ﴾: البؤسِ وضيقِ المعيشةِ.\n\n﴿وَٱلضَّرَّآءِ﴾: ما يَضرُّ الإنسانَ في نفسِه أو معيشتِه.\n\n﴿يَضَّرَّعُونَ﴾: يُظْهِرُون الخضوعَ والاستكانةَ للهِ."],[95,95,"﴿ٱلسَّيِّئَةِ﴾: الحالِ السيئةِ من البلاءِ والجَدْبِ.\n\n﴿ٱلۡحَسَنَةَ﴾: الحالَ الحسنةَ من الرَّخاءِ والنِّعمةِ والعافيةِ.\n\n﴿حَتَّىٰ عَفَواْ﴾: حتى كَثُروا وكَثُرَتْ أموالُهم.\n\n﴿فَأَخَذۡنَـٰهُم﴾: فأهلَكْناهم.\n\n﴿بَغۡتَةࣰ﴾: فَجْأةً."],[96,96,"﴿وَٱتَّقَوۡاْ﴾: واجتَنَبُوا ما نهاهم اللهُ عنه.\n\n﴿بَرَكَـٰتࣲ مِّنَ ٱلسَّمَآءِ وَٱلۡأَرۡضِ﴾: ما يتتابعُ عليهم من الخير من كلِّ وجْهٍ."],[97,97,"﴿بَأۡسُنَا﴾: عذابُ اللهِ.\n\n﴿بَيَـٰتࣰا﴾: ليلًا."],[98,98,"﴿يَلۡعَبُونَ﴾: يشتغلون بما لا يعودُ عليهم بفائدةٍ."],[99,99,"﴿مَكۡرَ ٱللَّهِ﴾: استدراجَه للمكذِّبين بما أنعمَ به عليهم، وعقوبتَهم."],[100,100,"﴿يَهۡدِ﴾: يتبيَّنْ.\n\n﴿يَرِثُونَ ٱلۡأَرۡضَ﴾: بالسُّكنى.\n\n﴿مِنۢ بَعۡدِ أَهۡلِهَآ﴾: من بعدِ إهلاكِ أهلِها السابقين.\n\n﴿وَنَطۡبَعُ﴾: ونَخْتِمُ.\n\n﴿لَا يَسۡمَعُونَ﴾: الموعظةَ سماعَ منتفعٍ بها."],[101,101,"﴿نَقُصُّ﴾: نَذْكُرُ.\n\n﴿أَنۢبَآئِهَا﴾: أخبارِها.\n\n﴿بِٱلۡبَيِّنَـٰتِ﴾: بالحُجَجِ الظاهرةِ الدالَّةِ على صِدْقِهم.\n\n﴿ٱلۡكَـٰفِرِينَ﴾: الذين كَتَبَ اللهُ عليهم ألّا يُؤمنوا."],[102,102,"﴿مِّنۡ عَهۡدࣲ﴾: مِن وفاءٍ بما وصّاهم اللهُ به.\n\n﴿لَفَـٰسِقِينَ﴾: لخارجينَ عن طاعةِ اللهِ وامتثالِ أمرِه."],[103,103,"﴿بِـَٔايَـٰتِنَآ﴾: بالمعجزاتِ الظاهرةِ الدالَّةِ على صِدْقِه.\n\n﴿فِرۡعَوۡنَ﴾: لَقَبٌ لكلِّ مَن مَلَك مِصْرَ في القديم.\n\n﴿فَظَلَمُواْ بِهَا﴾: فَجحَدُوا وكَفَروا بها."],[105,105,"﴿حَقِيقٌ﴾: جديرٌ وحَرِيٌّ.\n\n﴿بِبَيِّنَةࣲ﴾: ببُرهانٍ وحُجَّةٍ واضحةٍ على صِدْقِ ما أقولُ."],[107,107,"﴿ثُعۡبَانࣱ﴾: حَيَّةٌ عظيمةٌ.\n\n﴿مُّبِينࣱ﴾: ظاهرةٌ لكلِّ مَن يَراها."],[108,108,"﴿وَنَزَعَ يَدَهُۥ﴾: وأخرجَ يدَه من فتحةِ قميصِه، أو من تحتِ إبْطِه."],[109,109,"﴿ٱلۡمَلَأُ﴾: أشرافُ القومِ وسادَتُهم."],[110,110,"﴿تَأۡمُرُونَ﴾: تُشيرون عليَّ أيها الأشرافُ."],[111,111,"﴿أَرۡجِهۡ وَأَخَاهُ﴾: أخِّرْ موسى وأخاه هارونَ، ولا تَفْصِلْ في شأنِهما الآن.\n\n﴿فِي ٱلۡمَدَآئِنِ﴾: في مُدُنِ مِصْرَ وأقاليمِها.\n\n﴿حَـٰشِرِينَ﴾: مَن يَحْشُرُ السَّحَرَةَ فيَجْمَعُهم إليك."],[116,116,"﴿سَحَرُوٓاْ أَعۡيُنَ ٱلنَّاسِ﴾: صَرَفُوها عن حقيقةِ إدراكِها، فخُيِّلَ إلى الأبصارِ أنّ ما فعلُوه حقيقةٌ.\n\n﴿وَٱسۡتَرۡهَبُوهُمۡ﴾: وأخافوا الناسَ إخافةً شديدةً."],[117,117,"﴿تَلۡقَفُ﴾: تبتلِعُ بسرعة.\n\n﴿مَا يَأۡفِكُونَ﴾: ما يُلْقُونه من الحِبال والعِصِيِّ، ويُوهِمونَ الناسَ أنه حقٌّ."],[118,118,"﴿فَوَقَعَ ٱلۡحَقُّ﴾: فظهر الحقُّ في أمرِ موسى عليه السلام."],[119,119,"﴿وَٱنقَلَبُواْ﴾: وانصرفَ فرعونُ وقومُه.\n\n﴿صَـٰغِرِينَ﴾: أذلّاءَ بما لَحِقَهم من الهزيمةِ والخَيبةِ."],[123,123,"﴿ءَاذَنَ لَكُمۡ﴾: أسْمَحَ لكم بالإيمان بما يَدْعُو إليه موسى.\n\n﴿لَمَكۡرࣱ مَّكَرۡتُمُوهُ﴾: إن إيمانَكم بالله وإقرارَكم بنبوَّةِ موسى لَحيلةٌ احتَلْتُموها."],[124,124,"﴿مِّنۡ خِلَـٰفࣲ﴾: بقَطْع اليدِ اليمنى والرِّجلِ اليسرى، أو اليدِ اليسرى والرِّجلِ اليمنى.\n\n﴿لَأُصَلِّبَنَّكُمۡ﴾: لَأُبالِغَنَّ في شَدِّ أطرافِكم وتعليقِكم على جُذوع النَّخْلِ."],[125,125,"﴿مُنقَلِبُونَ﴾: راجِعُون إلى اللهِ."],[126,126,"﴿وَمَا تَنقِمُ﴾: ولَسْتَ تَعِيبُ منا -يا فرعونُ- وتُنْكِرُ.\n\n﴿بِـَٔايَـٰتِ رَبِّنَا﴾: بحُجَجِه وأدلَّتِه.\n\n﴿أَفۡرِغۡ﴾: أنْزِلْ وأسبِغْ."],[127,127,"﴿أَتَذَرُ﴾: أتَتْرُك.\n\n﴿لِيُفۡسِدُواْ فِي ٱلۡأَرۡضِ﴾: في أرضِ مصرَ بتغييرِ دينِ الناسِ إلى عبادةِ اللهِ وحدَه.\n\n﴿وَيَذَرَكَ وَءَالِهَتَكَ﴾: وقد تَرَكَك وتَرَكَ عبادةَ آلهتِك؟\n\n﴿وَنَسۡتَحۡيِۦ نِسَآءَهُمۡ﴾: ونَسْتبقيهنَّ أحياءً للخدمةِ والامتهانِ.\n\n﴿قَـٰهِرُونَ﴾: عالُون عليهم بقَهْرِ المُلْكِ والسلطانِ."],[129,129,"﴿مِن قَبۡلِ أَن تَأۡتِيَنَا﴾: برسالةِ اللهِ إلينا.\n\n﴿وَمِنۢ بَعۡدِ مَا جِئۡتَنَا﴾: برسالةِ اللهِ.\n\n﴿وَيَسۡتَخۡلِفَكُمۡ فِي ٱلۡأَرۡضِ﴾: ويَجْعَلَكم خلفاءَ في أرضِ مصرَ بعد هَلاكِ فرعونَ وقومِه."],[130,130,"﴿أَخَذۡنَآ﴾: ابتَلَيْنا.\n\n﴿بِٱلسِّنِينَ﴾: بالقحطِ والجَدْبِ."],[131,131,"﴿ٱلۡحَسَنَةُ﴾: العافيةُ والرَّخاءُ والخِصْبُ.\n\n﴿سَيِّئَةࣱ﴾: بلاءٌ وجَدْبٌ.\n\n﴿يَطَّيَّرُواْ﴾: يتشاءمُوا.\n\n﴿طَـٰٓئِرُهُمۡ﴾: ما يُصيبُهم من البلاءِ والجَدْبِ.\n\n﴿عِندَ ٱللَّهِ﴾: بقضاءِ اللهِ وقَدَرِه."],[132,132,"﴿مِنۡ ءَايَةࣲ﴾: من دَلالةٍ وحُجَّةٍ."],[133,133,"﴿وَٱلۡقُمَّلَ﴾: حشراتٌ تُفْسِدُ الثمار، وتَقْضي على الحَيَوانِ والنباتِ.\n\n﴿وَٱلدَّمَ﴾: فصارَتْ مياهُ القِبْط دمًا، ولم يَجِدوا ماءً صالحًا للشُّربِ.\n\n﴿مُّفَصَّلَـٰتࣲ﴾: مُفَرَّقاتٍ بعضُها في إثرِ بعضٍ."],[134,134,"﴿وَقَعَ﴾: نَزَلَ.\n\n﴿ٱلرِّجۡزُ﴾: العذابُ.\n\n﴿بِمَا عَهِدَ عِندَكَ﴾: بما أوحى إليك مِن رَفْعِ العذاب بالتوبةِ."],[135,135,"﴿يَنكُثُونَ﴾: يَنْقُضُون عُهودَهم، ويبْقَوْن على كُفْرِهم وضلالهِم."],[136,136,"﴿بِـَٔايَـٰتِنَا﴾: بحُجَجِنا، وما أرَيْناهم من المعجزاتِ على يدِ موسى.\n\n﴿غَـٰفِلِينَ﴾: مُعْرِضِين."],[137,137,"﴿يُسۡتَضۡعَفُونَ﴾: يُسْتَذَلُّون للخِدْمَةِ والامتهانِ.\n\n﴿مَشَـٰرِقَ ٱلۡأَرۡضِ وَمَغَـٰرِبَهَا﴾: بلادَ الشامِ.\n\n﴿كَلِمَتُ رَبِّكَ ٱلۡحُسۡنَىٰ﴾: ما وعَدَهم من تمكينِهم في الأرضِ ونَصْرِه إياهم على فرعونَ وقومِه.\n\n﴿يَعۡرِشُونَ﴾: يَبْنُون من الأبنيةِ والقصورِ وغيرِهما."],[138,138,"﴿يَعۡكُفُونَ﴾: يُقيمون ويُواظِبون من أجلِ العبادةِ."],[139,139,"﴿مُتَبَّرࣱ مَّا هُمۡ فِيهِ﴾: مُهْلَكٌ ما هم فيه من الدِّين الباطِل والشِّرْكِ بالله."],[140,140,"﴿فَضَّلَكُمۡ﴾: بكثرةِ الأنبياء وإهلاكِ عدوِّكم.\n\n﴿عَلَى ٱلۡعَـٰلَمِينَ﴾: من أهلِ عَصْرِكم."],[141,141,"﴿يَسُومُونَكُمۡ﴾: يُذيقُونكم.\n\n﴿وَيَسۡتَحۡيُونَ نِسَآءَكُمۡ﴾: ويَسْتَبْقُون نساءَكم للخِدْمَةِ والامتهانِ.\n\n﴿بَلَآءࣱ﴾: اختبارٌ ونعمةٌ."],[142,142,"﴿وَأَصۡلِحۡ﴾: واحمِلْ بني إسرائيلَ على عبادةِ اللهِ وطاعتِه."],[143,143,"﴿لَن تَرَىٰنِي﴾: لن تَقْدِرَ على رؤيتي في الدنيا.\n\n﴿تَجَلَّىٰ رَبُّهُۥ لِلۡجَبَلِ﴾: ظَهَرَ ربُّه للجَبَلِ على الوجهِ اللائقِ بجَلالِه.\n\n﴿دَكࣰّا﴾: مُسْتويًا بالأرض.\n\n﴿وَخَرَّ﴾: وسقط.\n\n﴿صَعِقࣰا﴾: مَغْشِيًّا عليه؛ لعِظَمِ ما رأى.\n\n﴿أَوَّلُ ٱلۡمُؤۡمِنِينَ﴾: بك من قومي."],[144,144,"﴿ٱصۡطَفَيۡتُكَ﴾: اختَرْتُك.\n\n﴿وَبِكَلَـٰمِي﴾: وبتكليمي إياك من غيرِ واسطةٍ."],[145,145,"﴿فِي ٱلۡأَلۡوَاحِ﴾: ألواحِ التوراةِ.\n\n﴿مِن كُلِّ شَيۡءࣲ﴾: يحتاجون إليه في دينِهم، وما يُصْلِحُ معاشَهم.\n\n﴿فَخُذۡهَا بِقُوَّةࣲ﴾: فخُذِ التوراةَ بجِدٍّ واجتهاد.\n\n﴿بِأَحۡسَنِهَا﴾: بحَسَنِها، وكلُّها حَسَنٌ بما شَرَعَ اللهُ فيها.\n\n﴿دَارَ ٱلۡفَـٰسِقِينَ﴾: مصيرَهم في الآخرة، وهي النارُ."],[146,146,"﴿عَنۡ ءَايَـٰتِيَ﴾: عن فَهْمِ حُجَجِ الله وأدلَّتِه وكتابِه.\n\n﴿ٱلۡغَيِّ﴾: الضلالِ."],[147,147,"﴿حَبِطَتۡ أَعۡمَـٰلُهُمۡ﴾: بطَلَتْ أعمالُهم، فلا ثوابَ عليها."],[148,148,"﴿مِنۢ بَعۡدِهِۦ﴾: مِن بعدِ ما فارَقَهم لمناجاةِ ربِّه.\n\n﴿عِجۡلࣰا جَسَدࣰا﴾: معبودًا مِن ذَهَبِهم على صورةِ العجلِ بلا رُوحٍ.\n\n﴿لَّهُۥ خُوَارٌ﴾: له صوتٌ يُشْبِهُ صوتَ البقرِ."],[149,149,"﴿وَلَمَّا سُقِطَ فِيٓ أَيۡدِيهِمۡ﴾: ولما نَدِمُوا على عبادةِ العجلِ عند رجوعِ موسى عليه السلام."],[150,150,"﴿أَسِفࣰا﴾: حزينًا على عبادةِ قومِه العجلَ.\n\n﴿أَعَجِلۡتُمۡ أَمۡرَ رَبِّكُمۡ﴾: أستعجَلْتم مجيئي إليكم وما وصَّيتُكم به من التوحيدِ، فَعَبدْتُم العِجْلَ؟\n\n﴿فَلَا تُشۡمِتۡ﴾: فلا تَسُرَّ."],[152,152,"﴿ٱلۡمُفۡتَرِينَ﴾: المكذِّبين المبتدِعين."],[154,154,"﴿يَرۡهَبُونَ﴾: يخافون أشدَّ الخوفِ من ربِّهم."],[155,155,"﴿لِّمِيقَـٰتِنَا﴾: للوقتِ الذي واعَدَ اللهُ موسى أن يَلْقاه فيه؛ للتوبةِ والاعتذارِ عَمّا فعلَ سُفَهاءُ بني إسرائيل.\n\n﴿ٱلرَّجۡفَةُ﴾: الزَّلزلةُ الشديدةُ.\n\n﴿ٱلسُّفَهَآءُ﴾: ضِعافُ العقولِ.\n\n﴿إِنۡ هِيَ إِلَّا فِتۡنَتُكَ﴾: ما عبادةُ قومي للعِجْلِ إلا ابتلاءٌ واختبارٌ."],[156,156,"﴿وَٱكۡتُبۡ لَنَا﴾: واجعَلْنا ممَّن كَتَبْتَ له.\n\n﴿حَسَنَةࣰ﴾: الصالحاتِ من الأعمالِ.\n\n﴿يَتَّقُونَ﴾: يخافون اللهَ ويخشَونَ عقابَه.\n\n﴿بِـَٔايَـٰتِنَا﴾: بدلائلِ توحيدِنا."],[157,157,"﴿ٱلۡأُمِّيَّ﴾: الذي لا يقرأُ ولا يكتبُ.\n\n﴿يَجِدُونَهُۥ﴾: يَجِدونَ صفتَه ونبوَّتَه.\n\n﴿ٱلۡخَبَـٰٓئِثَ﴾: من المطاعمِ والمشاربِ والمناكحِ.\n\n﴿وَيَضَعُ عَنۡهُمۡ﴾: ويَرْفَعُ عنهم بالتخفيفِ أو الإذهاب.\n\n﴿إِصۡرَهُمۡ وَٱلۡأَغۡلَـٰلَ ٱلَّتِي كَانَتۡ عَلَيۡهِمۡ﴾: ما أُلْزِمُوا العملَ به من التكاليفِ الشاقةِ في التوراة.\n\n﴿وَعَزَّرُوهُ﴾: وعَظَّموه ووَقَّرُوه.\n\n﴿ٱلنُّورَ﴾: القرآنَ."],[158,158,"﴿وَكَلِمَـٰتِهِۦ﴾: ما أُنْزِلَ إلى النبي ﷺ من ربِّه والنبيين من قبلِه."],[159,159,"﴿يَهۡدُونَ بِٱلۡحَقِّ﴾: يستقيمون على الحقِّ، ويَدْعُون الناسَ إلى الهدايةِ."],[160,160,"﴿وَقَطَّعۡنَـٰهُمُ﴾: وفَرَّقْنا قومَ موسى من بني إسرائيلَ.\n\n﴿أَسۡبَاطًا﴾: جمعُ سِبْطٍ، وهو ولَدُ الوَلَدِ، والمرادُ: قبائلُ بعددِ الأسباطِ مِن ولَدِ يعقوبَ.\n\n﴿فَٱنۢبَجَسَتۡ﴾: فانفجرَتْ.\n\n﴿ٱلۡغَمَـٰمَ﴾: السَّحابَ.\n\n﴿ٱلۡمَنَّ﴾: شيءٌ يُشْبِهُ الصَّمْغَ، طعمُه كالعَسَل.\n\n﴿وَٱلسَّلۡوَىٰ﴾: طائرٌ يُشْبِهُ السُّمانى."],[161,161,"﴿ٱلۡقَرۡيَةَ﴾: بيتَ المَقْدِسِ:\n\n﴿حِطَّةࣱ﴾: مسألتُنا حِطَّةٌ، أي: حُطَّ عنا ذنوبَنا.\n\n﴿سُجَّدࣰا﴾: خاضِعين للهِ تواضُعًا."],[162,162,"﴿رِجۡزࣰا﴾: عذابًا."],[163,163,"﴿حَاضِرَةَ ٱلۡبَحۡرِ﴾: قريبةً من البحرِ الأحمرِ مُشْرِفةً عليه.\n\n﴿إِذۡ يَعۡدُونَ﴾: إذ يعتدي أهلُ القريةِ بصيدِ السمكِ.\n\n﴿فِي ٱلسَّبۡتِ﴾: في يومِ السبتِ الذي أُمِرُوا بتعظيمِه.\n\n﴿شُرَّعࣰا﴾: ظاهرةً على وجهِ البحرِ قريبةً من الشاطئ.\n\n﴿وَيَوۡمَ لَا يَسۡبِتُونَ﴾: وفي سائرِ الأيام غيرِ يومِ السبتِ.\n\n﴿نَبۡلُوهُم﴾: نَخْتَبِرُهم."],[164,164,"﴿قَالُواْ مَعۡذِرَةً﴾: نَعِظُهم لنُعْذَرَ فيهم عندَ اللهِ."],[165,165,"﴿بَـِٔيسِۭ﴾: أليمٍ شديدٍ."],[166,166,"﴿عَتَوۡاْ﴾: تمرَّدوا وتكبَّروا."],[167,167,"﴿تَأَذَّنَ﴾: أعلمَ.\n\n﴿لَيَبۡعَثَنَّ﴾: ليُسَلِّطَنَّ.\n\n﴿يَسُومُهُمۡ﴾: يُذيقُهم."],[168,168,"﴿وَقَطَّعۡنَـٰهُمۡ﴾: وفَرَّقْنا بني إسرائيلَ.\n\n﴿وَبَلَوۡنَـٰهُم﴾: واخَتَبْرناهم."],[169,169,"﴿خَلۡفࣱ﴾: مَن يَخْلُفُ غيرَه بالسُّوءِ.\n\n﴿عَرَضَ هَـٰذَا ٱلۡأَدۡنَىٰ﴾: ما يَعْرِضُ لهم من متاعِ الدنيا مِن دنيءِ المكاسبِ، كالرِّشوةِ والتحريفِ.\n\n﴿عَرَضࣱ مِّثۡلُهُۥ﴾: متاعٌ زائلٌ من أنواعِ الكسبِ الحرامِ.\n\n﴿مِّيثَـٰقُ ٱلۡكِتَـٰبِ﴾: ما أخذه اللهُ عليهم من العهودِ في التوراةِ على العملِ بها.\n\n﴿وَدَرَسُواْ مَا فِيهِ﴾: وعَلِمُوا ما في التوراةِ، فضيَّعوها وتَرَكُوا العملَ بها."],[170,170,"﴿يُمَسِّكُونَ﴾: يتمسَّكون."],[171,171,"﴿نَتَقۡنَا﴾: اقتلَعْنا ورَفَعْنا.\n\n﴿ظُلَّةࣱ﴾: سَحابةٌ تُظِلُّهم.\n\n﴿وَظَنُّوٓاْ﴾: وأيقَنُوا.\n\n﴿وَاقِعُۢ بِهِمۡ﴾: إن لم يقبَلُوا أحكامَ التوراةِ.\n\n﴿بِقُوَّةࣲ﴾: بجِدٍّ واجتهادٍ.\n\n﴿وَٱذۡكُرُواْ مَا فِيهِ﴾: بالعملِ بما فيه."],[172,172,"﴿أَخَذَ﴾: استخرج.\n\n﴿وَأَشۡهَدَهُمۡ عَلَىٰٓ أَنفُسِهِمۡ﴾: وقرَّرَهم -جميعًا- بتوحيدِه بما أوْدَعَه في فِطَرِهم.\n\n﴿أَن تَقُولُواْ﴾: لئلا تقولوا."],[173,173,"﴿أَفَتُهۡلِكُنَا﴾: أفتعذِّبُنا.\n\n﴿ٱلۡمُبۡطِلُونَ﴾: الذين أبْطَلُوا أعمالهم بالإشراكِ بالله."],[174,174,"﴿نُفَصِّلُ﴾: نبيِّنُ."],[175,175,"﴿وَٱتۡلُ﴾: واقصُصْ.\n\n﴿نَبَأَ﴾: خبرَ رجلٍ من بني إسرائيلَ.\n\n﴿ءَاتَيۡنَـٰهُ ءَايَـٰتِنَا﴾: أتاه اللهُ علمًا ببعض الكتبِ المنزَّلَةِ.\n\n﴿فَٱنسَلَخَ مِنۡهَا﴾: ثم كَفَرَ بها وجَعَلَها وراءَ ظهرِه.\n\n﴿فَأَتۡبَعَهُ ٱلشَّيۡطَـٰنُ﴾: لَحِقه فأدركَه فصارَ قرينَه.\n\n﴿ٱلۡغَاوِينَ﴾: الضالِّين الراسِخين في الضلالِ."],[176,176,"﴿لَرَفَعۡنَـٰهُ﴾: لَرَفَعْنا قَدْرَه بالعلمِ والعملِ بها.\n\n﴿أَخۡلَدَ إِلَى ٱلۡأَرۡضِ﴾: رَكَنَ إلى الدُّنيا، واطمأَنَّ بها."],[177,177,"﴿سَآءَ﴾: قَبُحَ.\n\n﴿يَظۡلِمُونَ﴾: بالتكذيب وأنواع المعاصي."],[178,178,"﴿مَن يَهۡدِ ٱللَّهُ﴾: مَن يُوَفِّقْه للإيمانِ والعَمَلِ الصالحِ."],[179,179,"﴿ذَرَأۡنَا﴾: خَلَقْنا.\n\n﴿لَّا يَفۡقَهُونَ بِهَا﴾: لا يفْهمون بها الحقَّ ولا يَعْقلون.\n\n﴿كَٱلۡأَنۡعَـٰمِ﴾: كالبَهائمِ التي لا تفقَهُ ما يُقالُ لها، ولا تُمَيِّزُ."],[180,180,"﴿فَٱدۡعُوهُ بِهَا﴾: فاطْلُبُوا من الله بأسمائِه ما تُريدون.\n\n﴿وَذَرُواْ﴾: واترُكُوا.\n\n﴿يُلۡحِدُونَ فِيٓ أَسۡمَـٰٓئِهِۦ﴾: يَميلون بها عَمّا جُعِلَتْ له."],[181,181,"﴿يَهۡدُونَ بِٱلۡحَقِّ﴾: يَسْتقيمون على الحقِّ، ويَدْعُون الناسَ إلى الهدايةِ.\n\n﴿وَبِهِۦ يَعۡدِلُونَ﴾: وبالحقِّ يقْضُون بينَ الناسِ."],[182,182,"﴿سَنَسۡتَدۡرِجُهُم﴾: سَنُدْنِيهم -في حالِ اغْتِرارِهم- إلى ما يُهْلِكُهم ويضاعِفُ عِقابَهم."],[183,183,"﴿وَأُمۡلِي لَهُمۡ﴾: وأمْهِلُهم مدةً طويلةً.\n\n﴿مَتِينٌ﴾: قويٌّ لا يُدْفَعُ."],[184,184,"﴿جِنَّةٍ﴾: جُنونٍ."],[185,185,"﴿مَلَكُوتِ﴾: المُلْكِ العظيمِ. (زِيدت فيه الواوُ والتاء للمبالغةِ).\n\n﴿بَعۡدَهُۥ﴾: بعد القرآنِ العظيمِ."],[186,186,"﴿وَيَذَرُهُمۡ﴾: ويَتْرُكُهم.\n\n﴿طُغۡيَـٰنِهِمۡ﴾: ضَلالِهم وكُفْرِهم.\n\n﴿يَعۡمَهُونَ﴾: يتردَّدُون مُتَحَيِّرين."],[187,187,"﴿مُرۡسَىٰهَا﴾: قيامُها.\n\n﴿لَا يُجَلِّيهَا﴾: لا يُظْهِرُها.\n\n﴿ثَقُلَتۡ فِي ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ﴾: ثَقُلَ عِلْمُ قيامِ الساعةِ، وخَفِيَ على أهلِ السمواتِ والأرض.\n\n﴿بَغۡتَةࣰ﴾: فجأةً.\n\n﴿حَفِيٌّ عَنۡهَا﴾: عالِمٌ بها، مُسْتَقْصٍ بالسؤالِ عنها."],[189,189,"﴿نَّفۡسࣲ وَ ٰ⁠حِدَةࣲ﴾: هي آدمُ عليه السلام.\n\n﴿وَجَعَلَ مِنۡهَا﴾: وخَلَقَ منها.\n\n﴿زَوۡجَهَا﴾: هي حواءُ.\n\n﴿لِيَسۡكُنَ إِلَيۡهَا﴾: ليأنسَ ويطمئِنَّ بها.\n\n﴿تَغَشَّىٰهَا﴾: جامَعَها، والمرادُ جنسُ الزوجين مِن ذريةِ آدمَ.\n\n﴿فَمَرَّتۡ بِهِۦ﴾: استمرَّ بذلك الحَمْلِ إلى تمامهِ.\n\n﴿أَثۡقَلَت﴾: صارت ذات ثِقَلٍ بكِبَرِ الحَمْلِ.\n\n﴿صَـٰلِحࣰا﴾: أي: خَلْقًا سَوِيًّا صالحًا."],[190,190,"﴿جَعَلَا﴾: أي: الزوجان من ذريةِ آدمَ.\n\n﴿لَهُۥ شُرَكَآءَ﴾: أي: للهِ في ذلك الوَلَدِ، كنَحْوِ تسميتِه: عبدَ العُزّى."],[195,195,"﴿أَلَهُمۡ﴾: ألهذه الآلهة؟\n\n﴿يَبۡطِشُونَ﴾: يأخذُون بها، فَيدْفَعُون عنكم.\n\n﴿فَلَا تُنظِرُونِ﴾: فلا تُمْهلوني بعد تدبيرِ كَيْدِكم."],[196,196,"﴿وَلِـِّۧيَ﴾: مُتَوَلِّي حِفْظي وجميعِ أموري.\n\n﴿ٱلۡكِتَـٰبَ﴾: القرآنَ العظيمَ."],[199,199,"﴿خُذِ﴾: اقْبَلْ أنتَ وأمَّتُكَ.\n\n﴿ٱلۡعَفۡوَ﴾: ما تيسَّرَ من أخلاقِ الناسِ وأعمالِهم.\n\n﴿بِٱلۡعُرۡفِ﴾: هو كلُّ ما عُرِفَ حُسْنُه في الشَّرْعِ والعَقْلِ."],[200,200,"﴿يَنزَغَنَّكَ﴾: يُصِيبَنَّك وسْوَسَةٌ.\n\n﴿فَٱسۡتَعِذۡ بِٱللَّهِ﴾: فاستَجِرْ به والَجأْ إليه."],[201,201,"﴿ٱتَّقَوۡاْ﴾: خافُوا اللهَ بفِعْلِ أوامرِه وتَرْكِ نواهِيه.\n\n﴿طَـٰٓئِفࣱ مِّنَ ٱلشَّيۡطَـٰنِ﴾: عارضٌ من وسْوَسَتِه.\n\n﴿تَذَكَّرُواْ﴾: عقابَ اللهِ وثوابَه.\n\n﴿مُّبۡصِرُونَ﴾: مُنْتَهُون عن المعصيةِ على بَصيرةٍ."],[202,202,"﴿وَإِخۡوَ ٰ⁠نُهُمۡ﴾: وإخوانُ الشَّياطين.\n\n﴿يَمُدُّونَهُمۡ﴾: يَزيدُونهم.\n\n﴿ٱلۡغَيِّ﴾: الضَّلالِ.\n\n﴿لَا يُقۡصِرُونَ﴾: لا يَكُفُّون عن الإغواءِ."],[203,203,"﴿بِـَٔايَةࣲ﴾: بعلامةٍ دالَّةٍ على صِدْقِك.\n\n﴿ٱجۡتَبَيۡتَهَا﴾: اختلَقْتَها واخترَعْتَها.\n\n﴿هَـٰذَا﴾: أي القرآنُ المجيدُ.\n\n﴿بَصَآئِرُ﴾: جمعُ بَصيرةٍ، وهي الحُجَجُ والبراهينُ التي يُسْتَبصَرُ بها.\n\n﴿وَهُدࣰى﴾: بيانٌ يَهْدي المؤمنين."],[205,205,"﴿تَضَرُّعࣰا﴾: تَذَلُّلًا وخُضوعًا.\n\n﴿وَخِيفَةࣰ﴾: خائفًا منه تعالى.\n\n﴿وَدُونَ ٱلۡجَهۡرِ﴾: متوسِّطًا بين الَجهْرِ والإسرارِ.\n\n﴿بِٱلۡغُدُوِّ﴾: أولِ النهارِ.\n\n﴿وَٱلۡـَٔاصَالِ﴾: جمعُ أصيلٍ، وهو من العَصْرِ إلى المغربِ، والمرادُ: آخرُ النهارِ."],[206,206,"﴿وَيُسَبِّحُونَهُۥ﴾: يُنَزِّهُونه عن كلِّ ما لا يليقُ به."]]);
QTF("gharib",8,[[1,1,"﴿ٱلۡأَنفَالِ﴾: جَمْعُ نَفَل، وهي: الغنائمُ في غزوةِ «بَدْر».\n\n﴿ذَاتَ بَيۡنِكُمۡ﴾: الصِّلَةُ التي تَرْبِطُ بعضَكم ببعض."],[2,2,"﴿وَجِلَتۡ﴾: خافَتْ وفَزِعَتْ.\n\n﴿وَعَلَىٰ رَبِّهِمۡ يَتَوَكَّلُونَ﴾: يعتمدون عليه ويُفَوِّضون أمرَهم إليه."],[4,4,"﴿دَرَجَـٰتٌ﴾: منازلُ عاليةٌ."],[5,5,"﴿كَمَآ أَخۡرَجَكَ﴾: هذه الحالُ في كراهةِ فريقٍ من المؤمنين للقتالِ بعد تَبَيُّنِه، مثلُ إخراجِك في حالِ كراهتِهم."],[6,6,"﴿فِي ٱلۡحَقِّ﴾: في القتالِ."],[7,7,"﴿ٱلطَّآئِفَتَيۡنِ﴾: القافلةِ الآتيةِ من الشام وما تحمِلُه من أرزاقٍ، أو النَّفيرِ لقتالِ الأعداءِ.\n\n﴿غَيۡرَ ذَاتِ ٱلشَّوۡكَةِ﴾: غيرَ ذاتِ السِّلاحِ والقُوَّةِ، وهي: القافلةُ.\n\n﴿وَيَقۡطَعَ دَابِرَ ٱلۡكَـٰفِرِينَ﴾: الدابِرُ: الآخِرُ، أي: ويستأصِلَ الكافرين بالهَلاكِ."],[8,8,"﴿لِيُحِقَّ ٱلۡحَقَّ﴾: ليُظْهِرَه للناسِ ويُبَيِّنَه."],[9,9,"﴿تَسۡتَغِيثُونَ﴾: تَطْلُبون النَّصْرَ على عَدُوِّكم.\n\n﴿مُرۡدِفِينَ﴾: يَتْبَعُ بعضُهم بعضًا."],[10,10,"﴿وَمَا جَعَلَهُ ٱللَّهُ﴾: وما جَعَلَ الإمدادَ.\n\n﴿وَلِتَطۡمَئِنَّ﴾: ولِتَسْكُنَ وتُوقِنَ بنَصْرِ اللهِ."],[11,11,"﴿يُغَشِّيكُمُ﴾: يُلْقي اللهُ عليكم.\n\n﴿أَمَنَةࣰ مِّنۡهُ﴾: أمانًا من الله لكم.\n\n﴿وَيُذۡهِبَ﴾: ويُزيلَ.\n\n﴿رِجۡزَ ٱلشَّيۡطَـٰنِ﴾: وساوِسَه بما خَطَرَ لهم من الخوفِ والفَشَلِ.\n\n﴿وَلِيَرۡبِطَ عَلَىٰ قُلُوبِكُمۡ﴾: وليُقَوِّيَها بالصَّبرِ والشَّجاعةِ."],[12,12,"﴿أَنِّي مَعَكُمۡ﴾: بإعانتي ونَصْري.\n\n﴿فَثَبِّتُواْ ٱلَّذِينَ ءَامَنُواْ﴾: فَقَوُّوا عزائمَهم، وبَشِّرُوهم بالنَّصْرِ.\n\n﴿ٱلرُّعۡبَ﴾: الخوفَ الشديدَ.\n\n﴿فَوۡقَ ٱلۡأَعۡنَاقِ﴾: رؤوسَ الكفارِ.\n\n﴿كُلَّ بَنَانࣲ﴾: كلَّ طَرَفٍ ومِفْصَلٍ في الجسمِ."],[13,13,"﴿ذَ ٰ⁠لِكَ﴾: ما وقَعَ عليهم من القَتْل.\n\n﴿شَآقُّواْ ٱللَّهَ﴾: خالَفُوا أمْرَه."],[15,15,"﴿زَحۡفࣰا﴾: مُتقارِبين يَدْنُو كلُّ فريقٍ من الآخَرِ.\n\n﴿فَلَا تُوَلُّوهُمُ ٱلۡأَدۡبَارَ﴾: فلا تُدِيروا لهم ظُهورَكم مُنْهَزِمين."],[16,16,"﴿مُتَحَرِّفࣰا لِّقِتَالٍ﴾: مائِلًا عن موقفِه إلى موضعٍ أصلَحَ للقتالِ فيه.\n\n﴿مُتَحَيِّزًا﴾: مُنْحازًا ومنضَمًّا.\n\n﴿فِئَةࣲ﴾: جماعةٍ من المسلمين في ميدانِ القتالِ.\n\n﴿بَآءَ بِغَضَبࣲ مِّنَ ٱللَّهِ﴾: استحَقَّ غضَبه."],[17,17,"﴿وَلِيُبۡلِيَ ٱلۡمُؤۡمِنِينَ﴾: وليختبرَ اللهُ المؤمنين بنِعَمِه وإحسانِه."],[18,18,"﴿مُوهِنُ﴾: مُضْعِفُ ومُبْطِلُ.\n\n﴿كَيۡدِ ٱلۡكَـٰفِرِينَ﴾: مَكْرِهم واحتيالِهم."],[19,19,"﴿تَسۡتَفۡتِحُواْ﴾: تطلُبوا النَّصْرَ أيها الكفارُ.\n\n﴿جَآءَكُمُ ٱلۡفَتۡحُ﴾: تَهَكُّمٌ بالكفارِ، فقد نَصَرَ اللهُ المؤمنين ب «بَدْرٍ».\n\n﴿وَإِن تَعُودُواْ﴾: إلى الكفرِ وقتالِ النبيِّ ﷺ.\n\n﴿نَعُدۡ﴾: بهزيمَتِكم ونَصْرِه - ﷺ - عليكم.\n\n﴿فِئَتُكُمۡ﴾: جماعتُكم.\n\n﴿مَعَ ٱلۡمُؤۡمِنِينَ﴾: بتأييدِه ونَصْرِه."],[20,20,"﴿وَلَا تَوَلَّوۡاْ﴾: ولا تُعْرِضُوا عن طاعةِ اللهِ ورسولهِ.\n\n﴿تَسۡمَعُونَ﴾: ما يُتلى عليكم من الحُجَجِ والبراهينِ."],[22,22,"﴿ٱلدَّوَآبِّ﴾: جَمْعُ دابّة، وهي: ما دَبَّ على الأرضِ مِن خَلْقِ اللهِ.\n\n﴿ٱلصُّمُّ﴾: مَنِ انسَدَّتْ آذانُهم عن سماعِ الحقِّ.\n\n﴿ٱلۡبُكۡمُ﴾: مَن خَرِسَتْ ألسنتُهم عن النُّطقِ به."],[23,23,"﴿لَّأَسۡمَعَهُمۡ﴾: مواعِظَ القرآنِ وعِبَرَه.\n\n﴿لَتَوَلَّواْ﴾: لَأَعْرَضُوا عن الإيمان عِنادًا.\n\n﴿مُّعۡرِضُونَ﴾: صادُّون عنه."],[24,24,"﴿لِمَا يُحۡيِيكُمۡ﴾: لما فيه الحياةُ الأبديةُ.\n\n﴿بَيۡنَ ٱلۡمَرۡءِ وَقَلۡبِهِۦ﴾: بين الإنسانِ وخواطِرِ قلبِه، فاللهُ أملكُ لقلوبِ عبادِه منهم."],[25,25,"﴿فِتۡنَةࣰ﴾: ابتلاءً ومِحْنَةً تنزِلُ بكم."],[26,26,"﴿مُّسۡتَضۡعَفُونَ﴾: قليلُو العَدَدِ، مَقْهُورون.\n\n﴿يَتَخَطَّفَكُمُ﴾: يَأْخُذَكُم بسُرعةٍ.\n\n﴿ٱلنَّاسُ﴾: كفارُ قريشٍ.\n\n﴿فَـَٔاوَىٰكُمۡ﴾: جَعَلَ اللهُ لكم «المدينةَ» مَأْوىً تَأْوُون إليه."],[27,27,"﴿لَا تَخُونُواْ ٱللَّهَ﴾: بتَرْكِ ما أوْجَبَه عليكم، وارتكابِ ما نَهاكم عنه.\n\n﴿أَمَـٰنَـٰتِكُمۡ﴾: ما ائتُمِنتُم عليه من التكاليفِ الشرعيةِ."],[28,28,"﴿فِتۡنَةࣱ﴾: اختبارٌ لكم."],[29,29,"﴿فُرۡقَانࣰا﴾: فَصْلًا بين الحَقِّ والباطِلِ."],[30,30,"﴿يَمۡكُرُ بِكَ﴾: يَكِيدُ لك.\n\n﴿لِيُثۡبِتُوكَ﴾: ليَحْبِسُوك.\n\n﴿يُخۡرِجُوكَ﴾: من بلدِك «مكةَ»."],[31,31,"﴿أَسَـٰطِيرُ ٱلۡأَوَّلِينَ﴾: جَمْعُ أُسْطُورة، وهي: ما سُطِّرَ في كُتُبِ السابقين من الأخبارِ المكذوبةِ."],[32,32,"﴿إِن كَانَ هَـٰذَا﴾: ما جاءَ به محمدٌ."],[33,33,"﴿وَأَنتَ فِيهِمۡ﴾: وأنت مقيمٌ بينَهم في «مكةَ»."],[34,34,"﴿وَمَا لَهُمۡ أَلَّا يُعَذِّبَهُمُ ٱللَّهُ﴾: وأيُّ شيءٍ يَمْنَعُ من عذابه لهم؟\n\n﴿يَصُدُّونَ﴾: يَمْنَعُون.\n\n﴿عَنِ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ﴾: عن الطَّوافِ بالكعبةِ، والصَّلاةِ فيه.\n\n﴿وَمَا كَانُوٓاْ أَوۡلِيَآءَهُۥٓ﴾: وما كان الكفارُ أولياءَ اللهِ ولا المسجدِ الحرامِ."],[35,35,"﴿مُكَآءࣰ﴾: صَفيرًا.\n\n﴿وَتَصۡدِيَةࣰ﴾: وتَصْفيقًا.\n\n﴿فَذُوقُواْ ٱلۡعَذَابَ﴾: في الدنيا بالقَتْلِ والأَسْرِ في «بدرٍ»، وفي الآخرةِ بالنارِ."],[36,36,"﴿حَسۡرَةࣰ﴾: ندامةً وأَسَفًا."],[37,37,"﴿لِيَمِيزَ﴾: ليَفْصِلَ.\n\n﴿فَيَرۡكُمَهُۥ﴾: يَجْمَعَه ويَضُمَّ بعضَه إلى بعضٍ."],[38,38,"﴿إِن يَنتَهُواْ﴾: عن الكفرِ، ويَرْجِعُوا إلى الإيمان.\n\n﴿وَإِن يَعُودُواْ﴾: إلى قتالِ النبيِّ ﷺ.\n\n﴿مَضَتۡ﴾: سَبَقَتْ.\n\n﴿سُنَّتُ ٱلۡأَوَّلِينَ﴾: سنَّتُنا في عقوبةِ مَن كَذَّبَ واستمرَّ على كُفْرِه."],[39,39,"﴿فِتۡنَةࣱ﴾: شِرْكٌ وصَدٌّ عن سبيل الله.\n\n﴿وَيَكُونَ ٱلدِّينُ كُلُّهُۥ لِلَّهِ﴾: وتكونَ الطاعةُ والعبادةُ كلُّهاخالصةً لله.\n\n﴿فَإِنِ ٱنتَهَوۡاْ﴾: فإن انزجَرَ المشركون عن شِرْكِهم وفتنةِ المؤمنين."],[40,40,"﴿مَوۡلَىٰكُمۡ﴾: مُعينُكم وناصِرُكم."],[41,41,"﴿غَنِمۡتُم﴾: ظَفِرْتُمْ به من الأعداءِ بالجِهادِ.\n\n﴿وَلِذِي ٱلۡقُرۡبَىٰ﴾: قَرابةِ الرسولِ ﷺ، وهم بنو هاشمٍ وبنو المطَّلِبِ.\n\n﴿وَٱلۡيَتَـٰمَىٰ﴾: الأطفالِ الذين مات آباؤُهم وهم دونَ سِنِّ البُلوغ.\n\n﴿وَٱلۡمَسَـٰكِينِ﴾: أهلِ الحاجةِ الذين لا يَمْلِكُون ما يَكْفيهم.\n\n﴿وَٱبۡنِ ٱلسَّبِيلِ﴾: المسافرِ الذي انقطعَتْ به النفقةُ.\n\n﴿وَمَآ أَنزَلۡنَا﴾: من الملائكةِ والآياتِ والنَّصْرِ.\n\n﴿يَوۡمَ ٱلۡفُرۡقَانِ﴾: يومَ «بَدْرٍ» حينَ فَرَقَ اللهُ بينَ الحقِّ والباطلِ."],[42,42,"﴿بِٱلۡعُدۡوَةِ ٱلدُّنۡيَا﴾: جانبِ الوادي الأقربِ إلى «المدينة».\n\n﴿ٱلۡقُصۡوَىٰ﴾: البعيدةِ عن «المدينةِ».\n\n﴿وَٱلرَّكۡبُ﴾: عِيرُ التجارةِ وأصحابُها.\n\n﴿أَسۡفَلَ مِنكُمۡ﴾: في مكانٍ أسفلَ من مكانِكم جهةَ ساحلِ البحرِ الأحمرِ.\n\n﴿لِّيَقۡضِيَ ٱللَّهُ أَمۡرࣰا كَانَ مَفۡعُولࣰا﴾: بنَصْرِ أوليائِه وخِذْلانِ أعدائِه.\n\n﴿لِّيَهۡلِكَ مَنۡ هَلَكَ﴾: ليموتَ مَن يموتُ من الكفّارِ.\n\n﴿عَنۢ بَيِّنَةࣲ﴾: عن حُجَّةٍ عايَنَها.\n\n﴿وَيَحۡيَىٰ مَنۡ حَيَّ﴾: ويعيشَ مَن يعيشُ مِنهُم."],[43,43,"﴿لَّفَشِلۡتُمۡ﴾: لَجَبُنْتُم وضَعُفتم.\n\n﴿وَلَتَنَـٰزَعۡتُمۡ﴾: اختلَفْتُم.\n\n﴿فِي ٱلۡأَمۡرِ﴾: في القتالِ.\n\n﴿سَلَّمَ﴾: عَصَمَ من الضَّعْفِ والاختلافِ."],[46,46,"﴿رِيحُكُمۡ﴾: قُوَّتُكم ونَصْرُكم.\n\n﴿مَعَ ٱلصَّـٰبِرِينَ﴾: بالعَوْنِ والنصرِ والتأييدِ."],[47,47,"﴿بَطَرࣰا﴾: كِبْرًا.\n\n﴿وَرِئَآءَ ٱلنَّاسِ﴾: مراءاةً لهم وطَلَبًا للفَخْرِ."],[48,48,"﴿زَيَّنَ﴾: حَسَّنَ.\n\n﴿جَارࣱ لَّكُمۡ﴾: مُعينٌ وناصرٌ لكم.\n\n﴿تَرَآءَتِ ٱلۡفِئَتَانِ﴾: التقى المسلمون مع الكفارِ.\n\n﴿نَكَصَ عَلَىٰ عَقِبَيۡهِ﴾: رَجَعَ إلى الوراء ووَلّى هاربًا.\n\n﴿إِنِّيٓ أَرَىٰ مَا لَا تَرَوۡنَ﴾: مِن الملائكةِ الذين جاؤوا لنُصْرَةِ المؤمنين."],[49,49,"﴿ٱلۡمُنَـٰفِقُونَ﴾: جَمْعُ مُنافق، وهو: مَن يُظهِرُ الإسلامَ ويُبْطِنُ الكفرَ.\n\n﴿فِي قُلُوبِهِم مَّرَضٌ﴾: ضِعافُ الإيمانِ الشاكُّون من غيرِ نِفاقٍ.\n\n﴿غَرَّ هَـٰٓؤُلَآءِ دِينُهُمۡ﴾: أي: اغترَّ المسلمون بدينِهم حتى تَكَلَّفُوا قتالَ المشركين.\n\n﴿يَتَوَكَّلۡ عَلَى ٱللَّهِ﴾: يُفَوِّضْ أمرَه إليه ويعتمدْ عليه."],[50,50,"﴿يَتَوَفَّى﴾: يَقْبِضُ ويَنْتَزِعُ.\n\n﴿وَأَدۡبَـٰرَهُمۡ﴾: ظهورَهم.\n\n﴿ٱلۡحَرِيقِ﴾: المُحْرِقِ، وهو جهنَّمُ."],[51,51,"﴿بِمَا قَدَّمَتۡ أَيۡدِيكُمۡ﴾: بسبب أعمالِكم السيئةِ.\n\n﴿لَيۡسَ بِظَلَّـٰمࣲ﴾: ليس بذي ظُلْمٍ."],[52,52,"﴿كَدَأۡبِ ءَالِ فِرۡعَوۡنَ﴾: حالُ المشركين في الكفرِ واستحقاقِ العذابِ كحالِ آلِ فرعونَ.\n\n﴿فَأَخَذَهُمُ ٱللَّهُ﴾: أنزلَ بهم عقابَه."],[53,53,"﴿ذَ ٰ⁠لِكَ﴾: أي: التعذيبُ على الأعمالِ السيئة."],[55,55,"﴿ٱلدَّوَآبِّ﴾: جَمْعُ دابَّةٍ، وهي: ما دَبَّ على الأرضِ من خَلْقِ اللهِ."],[56,56,"﴿عَـٰهَدتَّ﴾: التزَمْتَ معهم بميثاقٍ.\n\n﴿يَنقُضُونَ﴾: يُبْطِلُون."],[57,57,"﴿فَإِمَّا تَثۡقَفَنَّهُمۡ﴾: فإن ظَفِرْتَ بهم وصادَفْتَهم.\n\n﴿فَشَرِّدۡ بِهِم﴾: ففرِّقْ وخَوِّفْ بقَتْلهِم والتنكيلِ بهم.\n\n﴿مَّنۡ خَلۡفَهُمۡ﴾: غيرَهم من المحاربين."],[58,58,"﴿فَٱنۢبِذۡ إِلَيۡهِمۡ﴾: فألْقِ إليهم عَهْدَهم.\n\n﴿عَلَىٰ سَوَآءٍ﴾: حتى يَسْتَوِيَ الفريقان في العِلْم بأنه لا عَهْدَ بينَهم."],[59,59,"﴿سَبَقُوٓاْ﴾: أفلَتُوا ونَجَوْا من الظَّفَرِ بهم.\n\n﴿لَا يُعۡجِزُونَ﴾: لن يُفْلِتُوا من عذابِ اللهِ."],[60,60,"﴿وَأَعِدُّواْ﴾: وهَيِّئوا.\n\n﴿رِّبَاطِ ٱلۡخَيۡلِ﴾: إعدادِها ورَبْطِها؛ انتظارًا للغَزْوِ عليها.\n\n﴿تُرۡهِبُونَ﴾: تُخَوِّفُون.\n\n﴿مِن دُونِهِمۡ﴾: مِن غيرِهم.\n\n﴿لَا تَعۡلَمُونَهُمُ﴾: لم تَظْهَرْ لكم عداوتُهم.\n\n﴿يُوَفَّ إِلَيۡكُمۡ﴾: يُخْلِفْه اللهُ لكم في الدنيا، ويَدَّخِرْ لكم ثوابَه في الآخرة.\n\n﴿لَا تُظۡلَمُونَ﴾: لا تُنْقَصُون شيئًا من أجرِ الإنفاقِ."],[61,61,"﴿جَنَحُواْ﴾: مالَ المحارِبُون.\n\n﴿لِلسَّلۡمِ﴾: للمُسالمةِ وتَرْكِ الحربِ.\n\n﴿فَٱجۡنَحۡ لَهَا﴾: فمِلْ إلى المصالحةِ.\n\n﴿وَتَوَكَّلۡ عَلَى ٱللَّهِ﴾: اعتمِدْ عليه وفَوِّضْ أمْرَك إليه."],[62,62,"﴿يَخۡدَعُوكَ﴾: يُدَبِّرُوا إيقاعَك فيما تَكْرَهُ.\n\n﴿حَسۡبَكَ ٱللَّهُ﴾: كافِيك وناصِرُك."],[63,63,"﴿وَأَلَّفَ﴾: وجَمَعَ."],[65,65,"﴿حَرِّضِ﴾: بالِغْ في الحَثِّ.\n\n﴿لَّا يَفۡقَهُونَ﴾: لا يَعْلمون ما أعَدَّه اللهُ للمجاهدين في سبيلِه."],[66,66,"﴿مَعَ ٱلصَّـٰبِرِينَ﴾: بتأييدِه ونَصْرِه."],[67,67,"﴿يُثۡخِنَ﴾: يُبالِغَ في قَتْلِ الأعداءِ.\n\n﴿عَرَضَ ٱلدُّنۡيَا﴾: حُطامَها، وهو: الفِداءُ من أسْرى «بدر».\n\n﴿يُرِيدُ ٱلۡـَٔاخِرَةَ﴾: ثوابَها، بإظهارِ الدِّين، وما يَحْصِلُ لكم من أجْر الجهادِ.\n\n﴿عَزِيزٌ﴾: قويٌّ قادرٌ لا يُقْهَرُ.\n\n﴿حَكِيمࣱ﴾: ذو حِكْمةٍ في أفعالِه كلِّها."],[68,68,"﴿كِتَـٰبࣱ مِّنَ ٱللَّهِ﴾: قَضاءٌ وحُكْمٌ منه.\n\n﴿سَبَقَ﴾: بإباحةِ الغنيمةِ وفِداءِ الأسرى.\n\n﴿لَمَسَّكُمۡ﴾: لَأصابَكم."],[69,69,"﴿مِمَّا غَنِمۡتُمۡ﴾: مِن قِتالِ عَدُوِّكم وفِداءِ الأسرى."],[70,70,"﴿مِّمَّآ أُخِذَ مِنكُمۡ﴾: من المالِ بأن يُيَسِّرَ اللهُ لكم من فَضْلِه خيرًا كثيرًا."],[71,71,"﴿خِيَانَتَكَ﴾: بالغَدْرِ بك وخِداعِكَ.\n\n﴿خَانُواْ ٱللَّهَ﴾: بمخالفةِ أمْرِه.\n\n﴿مِن قَبۡلُ﴾: قبلَ غزوةِ «بدرٍ».\n\n﴿فَأَمۡكَنَ مِنۡهُمۡ﴾: فأقدرك الله عليهم ونَصَرَك."],[72,72,"﴿وَهَاجَرُواْ﴾: انتقلُوا إلى دارِ الإسلام، أو بلدٍ يتمكَّنُون فيه من العبادةِ.\n\n﴿وَٱلَّذِينَ ءَاوَواْ﴾: هم الأنصارُ الذين أسكنُوا النبيَّ ﷺ والمهاجرين في دُورِهم.\n\n﴿أَوۡلِيَآءُ بَعۡضࣲ﴾: في النُّصْرَةِ والمعونةِ.\n\n﴿وَلَـٰيَتِهِم﴾: نُصْرَتهِم.\n\n﴿ٱسۡتَنصَرُوكُمۡ﴾: طلبُوا نُصْرَتَكم.\n\n﴿فِي ٱلدِّينِ﴾: بأنهم من أهلِ دينِكم.\n\n﴿مِّيثَـٰقࣱ﴾: عَهْدٌ مؤكَّدٌ."],[73,73,"﴿إِلَّا تَفۡعَلُوهُ﴾: أي: تَوَلِّيَ المؤمنين ونُصْرتهم.\n\n﴿فِتۡنَةࣱ﴾: للمؤمنين عن دينِهم.\n\n﴿وَفَسَادࣱ كَبِيرࣱ﴾: بالصَّدِّ عن سبيلِ اللهِ، وقوةِ الكفرِ."],[75,75,"﴿مِنۢ بَعۡدُ﴾: بعدَ السابقين إلى الإيمانِ والهجرةِ.\n\n﴿فَأُوْلَـٰٓئِكَ مِنكُمۡ﴾: أي: لهم ما لكم وعليهم ما عليكم.\n\n﴿وَأُوْلُواْ ٱلۡأَرۡحَامِ﴾: ذَوو القَراباتِ.\n\n﴿أَوۡلَىٰ بِبَعۡضࣲ﴾: في الميراثِ من عامَّةِ المسلمين.\n\n﴿كِتَـٰبِ ٱللَّهِ﴾: حُكْمِه الذي كَتَبَه في اللَّوحِ المحفوظِ."]]);
QTF("gharib",9,[[1,1,"﴿بَرَآءَةࣱ﴾: إعذارٌ وتَحَلُّلٌ من العهودِ.\n\n﴿عَـٰهَدتُّم﴾: التزَمْتُم معهم بميثاقٍ."],[2,2,"﴿فَسِيحُواْ﴾: فسِيروا آمنين.\n\n﴿غَيۡرُ مُعۡجِزِي ٱللَّهِ﴾: لن تُفْلِتُوا من عقوبةِ الله.\n\n﴿مُخۡزِي ٱلۡكَـٰفِرِينَ﴾: مُذِلُّهم في الدنيا والآخرة."],[3,3,"﴿وَأَذَ ٰ⁠نࣱ﴾: إعلامٌ وإنذارٌ.\n\n﴿يَوۡمَ ٱلۡحَجِّ ٱلۡأَكۡبَرِ﴾: يومَ النَّحرِ.\n\n﴿تُبۡتُمۡ﴾: رَجَعْتُم إلى الحقِّ وتَرَكْتُم الشِّركَ.\n\n﴿تَوَلَّيۡتُمۡ﴾: أعْرَضْتُم.\n\n﴿وَبَشِّرِ﴾: وأنذِرْ."],[4,4,"﴿لَمۡ يَنقُصُوكُمۡ شَيۡـࣰٔا﴾: لم يَخُونوا العهدَ ولا شروطَه.\n\n﴿وَلَمۡ يُظَـٰهِرُواْ﴾: ولم يُعاونوا.\n\n﴿إِلَىٰ مُدَّتِهِمۡ﴾: إلى مدةِ العهدِ المحددةِ."],[5,5,"﴿ٱنسَلَخَ﴾: خَرَجَ وانقَضى.\n\n﴿ٱلۡأَشۡهُرُ ٱلۡحُرُمُ﴾: الأشهرُ الأربعةُ التي أمَّنتم بها المشركين.\n\n﴿وَخُذُوهُمۡ﴾: وأْسِروهم.\n\n﴿وَٱحۡصُرُوهُمۡ﴾: اقصِدُوهم بالحِصارِ في معاقِلِهم، أو امنعُوهم من الخروجِ والتنقُّلِ في البلادِ.\n\n﴿كُلَّ مَرۡصَدࣲ﴾: كلَّ طريقٍ ومَرْقَبٍ.\n\n﴿تَابُواْ﴾: رَجَعُوا عن الكفر ودخلوا في الإسلام.\n\n﴿فَخَلُّواْ سَبِيلَهُمۡ﴾: فاترُكوهم ولا تتعرَّضوا لهم."],[6,6,"﴿ٱسۡتَجَارَكَ﴾: طَلَبَ جِوارَكَ، أي: حمايتَك وأمانَك.\n\n﴿فَأَجِرۡهُ﴾: فأمِّنْهُ.\n\n﴿كَلَـٰمَ ٱللَّهِ﴾: القرآنَ الكريمَ.\n\n﴿أَبۡلِغۡهُ مَأۡمَنَهُۥ﴾: أعِدْهُ من حيثُ أتى آمِنًا."],[7,7,"﴿كَيۡفَ يَكُونُ﴾: لا يكونُ.\n\n﴿عَهۡدٌ﴾: التزامٌ بميثاقٍ.\n\n﴿ٱلۡمَسۡجِدِ ٱلۡحَرَامِ﴾: الحَرَمِ كلِّه.\n\n﴿فَمَا ٱسۡتَقَـٰمُواْ لَكُمۡ﴾: فما أقاموا على الوفاءِ بعهدكم."],[8,8,"﴿يَظۡهَرُواْ عَلَيۡكُمۡ﴾: يَظْفَرُوا بكم ويَغْلِبوكم.\n\n﴿لَا يَرۡقُبُواْ﴾: لا يُراعُوا.\n\n﴿إِلࣰّا﴾: قَرابةً ولا حِلْفًا.\n\n﴿ذِمَّةࣰ﴾: عَهْدًا ولا حَقًّا."],[9,9,"﴿ٱشۡتَرَوۡاْ﴾: استبدَلُوا.\n\n﴿ثَمَنࣰا قَلِيلࣰا﴾: عَرَضَ الدنيا الزائلَ.\n\n﴿فَصَدُّواْ عَن سَبِيلِهِۦٓ﴾: فأعرضُوا عن الحقِّ، ومنعُوا غيرَهم عنه.\n\n﴿سَآءَ﴾: قَبُحَ."],[11,11,"﴿وَنُفَصِّلُ﴾: نُبيِّنُ."],[12,12,"﴿نَّكَثُوٓاْ﴾: نَقَضُوا.\n\n﴿أَيۡمَـٰنَهُم﴾: مواثيقَهم المؤكَّدةَ بالأَيْمان.\n\n﴿وَطَعَنُواْ فِي دِينِكُمۡ﴾: ذَمُّوا الإسلامَ وعابُوه.\n\n﴿لَآ أَيۡمَـٰنَ لَهُمۡ﴾: لا عهودَ لهم يُوَفّى بها."],[13,13,"﴿وَهَمُّواْ﴾: وعَزَمُوا وعَمِلوا.\n\n﴿بَدَءُوكُمۡ﴾: بالإيذاءِ والقتالِ.\n\n﴿أَوَّلَ مَرَّةٍ﴾: أولَ الأمرِ «بمكةَ» «وببَدْرٍ» وغيرِهما.\n\n﴿أَتَخۡشَوۡنَهُمۡ﴾: أتَخافُونهم، أو أتخافون ملاقاتَهم في الحربِ؟"],[14,14,"﴿يُعَذِّبۡهُمُ﴾: يَقْتُلْهم.\n\n﴿وَيُخۡزِهِمۡ﴾: ويُذِلّهم بالهزيمةِ والأَسْرِ.\n\n﴿وَيَشۡفِ﴾: يُزِلِ الغَمَّ ونحوَه."],[15,15,"﴿غَيۡظَ قُلُوبِهِمۡ﴾: غَضَبَها وما تحمِلُه من كراهةٍ للأعداءِ."],[16,16,"﴿تُتۡرَكُواْ﴾: دونَ اختبارٍ وابتلاءٍ.\n\n﴿وَلِيجَةࣰ﴾: بِطانةً وأولياءَ."],[17,17,"﴿مَا كَانَ﴾: ما صَحَّ ولا استقامَ.\n\n﴿أَن يَعۡمُرُواْ مَسَـٰجِدَ ٱللَّهِ﴾: أن يَبْنُوها ويَصُونوها، أو أن يُقيموا العبادةَ فيها.\n\n﴿حَبِطَتۡ﴾: بَطَلتْ."],[19,19,"﴿سِقَايَةَ ٱلۡحَآجِّ﴾: سَقْيَ الحُجّاجِ الماءَ.\n\n﴿لَا يَهۡدِي﴾: لا يُوَفِّقُ\n\n﴿ٱلظَّـٰلِمِينَ﴾: الكافرين."],[20,20,"﴿دَرَجَةً﴾: مَنزِلَةً."],[21,21,"﴿وَرِضۡوَ ٰ⁠نࣲ﴾: رضا اللهِ عنهم الذي لا سُخْطَ بعدَه.\n\n﴿مُّقِيمٌ﴾: دائمٌ لا يَزُولُ."],[23,23,"﴿أَوۡلِيَآءَ﴾: نصراءَ وأصدقاءَ.\n\n﴿ٱسۡتَحَبُّواْ ٱلۡكُفۡرَ﴾: اختارُوه ودامُوا عليه."],[24,24,"﴿وَعَشِيرَتُكُمۡ﴾: قبيلتُكم وذوو القَرابةِ القريبة.\n\n﴿ٱقۡتَرَفۡتُمُوهَا﴾: اكتسَبْتموها.\n\n﴿كَسَادَهَا﴾: عَدَمَ رَواجِها.\n\n﴿تَرۡضَوۡنَهَآ﴾: تُعْجِبُكم وتميلُ أنفسُكم إليها.\n\n﴿فَتَرَبَّصُواْ﴾: فانتظِرُوا.\n\n﴿بِأَمۡرِهِۦ﴾: بعقابِه."],[25,25,"﴿بِمَا رَحُبَتۡ﴾: مع وُسْعِها.\n\n﴿وَلَّيۡتُم﴾: فَرَرْتُم.\n\n﴿مُّدۡبِرِينَ﴾: مُنْهَزِمِين، جاعِلين ظُهورَكم جهةَ عدوِّكم."],[26,26,"﴿سَكِينَتَهُۥ﴾: طمأنينتَه وأَمْنَه.\n\n﴿جُنُودࣰا﴾: ملائكةً."],[28,28,"﴿نَجَسࣱ﴾: خُبَثاءُ في عقائدِهم وأعمالِهم الشِّرْكيةِ.\n\n﴿عَامِهِمۡ هَـٰذَا﴾: وهو العامُ التاسعُ من الهجرةِ.\n\n﴿عَيۡلَةࣰ﴾: فَقْرًا."],[29,29,"﴿وَلَا يَدِينُونَ دِينَ ٱلۡحَقِّ﴾: ولا يَلْتزمون أحكامَ الإسلام الذي ارتضاه الله دِينًا للناسِ.\n\n﴿ٱلۡجِزۡيَةَ﴾: ما قُدِّرَ على أهل الكِتابِ من المالِ كلَّ عامٍ؛ جزاءً لما مُنِحُوا من الأمنِ.\n\n﴿عَن يَدࣲ﴾: بأيدِيهم غيرَ ممتنعين.\n\n﴿صَـٰغِرُونَ﴾: خاضِعونَ أذلّاءُ."],[30,30,"﴿عُزَيۡرٌ﴾: حَبْرٌ من علماءِ اليهودِ، يُعَظِّمُونه؛ لعِلْمِه وعبادتِه.\n\n﴿يُضَـٰهِـُٔونَ﴾: يُشابِهُون.\n\n﴿قَـٰتَلَهُمُ ٱللَّهُ﴾: دعاءٌ عليهم بالهَلاكِ.\n\n﴿أَنَّىٰ يُؤۡفَكُونَ﴾: كيف يُصْرَفُون عن الحقِّ الواضحِ إلى الباطلِ؟"],[31,31,"﴿أَحۡبَارَهُمۡ﴾: جَمْعُ حَبْرٍ، وهم العلماءُ من اليهودِ.\n\n﴿وَرُهۡبَـٰنَهُمۡ﴾: جَمْعُ راهبٍ، وهم العُبّادُ من النَّصارى.\n\n﴿أَرۡبَابࣰا مِّن دُونِ ٱللَّهِ﴾: إذ أطاعُوهم في تحريمِ ما أحلَّ اللهُ، وتحليلِ ما حَرَّمه.\n\n﴿وَٱلۡمَسِيحَ ٱبۡنَ مَرۡيَمَ﴾: واتخذ النصارى عيسى عليه السلام إلهًا فعبدُوه.\n\n﴿سُبۡحَـٰنَهُۥ﴾: تَنَزَّه اللهُ وتَقَدَّسَ."],[32,32,"﴿يُرِيدُونَ﴾: يريدُ الكفّارُ بتكذيبهِم.\n\n﴿أَن يُطۡفِـُٔواْ﴾: أن يُبْطِلُوا.\n\n﴿نُورَ ٱللَّهِ﴾: دينَ الإسلامِ وما فيه من الهُدى والرَّشادِ.\n\n﴿يُتِمَّ نُورَهُۥ﴾: يُكْمِلَ اللهُ دينَه ويُظْهِرَه."],[33,33,"﴿بِٱلۡهُدَىٰ﴾: بالإيمانِ الصَّحيحِ، والعلمِ النافعِ.\n\n﴿وَدِينِ ٱلۡحَقِّ﴾: دينِ الإسلامِ.\n\n﴿لِيُظۡهِرَهُۥ﴾: ليُعْلِيَه.\n\n﴿عَلَى ٱلدِّينِ كُلِّهِۦ﴾: على الأديانِ جميعًا."],[34,34,"﴿لَيَأۡكُلُونَ أَمۡوَ ٰ⁠لَ ٱلنَّاسِ﴾: لَيأخُذُونها.\n\n﴿بِٱلۡبَـٰطِلِ﴾: بغيرِ حَقٍّ كالرِّشوةِ وغيرِها.\n\n﴿وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِ﴾: ويمنعون الناسَ من الدخولِ في الإسلامِ، أو اتباعِ الحقِّ.\n\n﴿يَكۡنِزُونَ ٱلذَّهَبَ وَٱلۡفِضَّةَ﴾: يجمعونَ الأموالَ.\n\n﴿وَلَا يُنفِقُونَهَا فِي سَبِيلِ ٱللَّهِ﴾: ولايُؤَدُّون زَكاتَها، ولايُخْرِجون منها الحقوقَ الواجبةَ."],[35,35,"﴿فَتُكۡوَىٰ﴾: تُحْرَقُ.\n\n﴿فَذُوقُواْ مَا كُنتُمۡ تَكۡنِزُونَ﴾: ذُوقوا سوءَ عاقبةِ جَمْعِكم."],[36,36,"﴿عِدَّةَ ٱلشُّهُورِ﴾: أي: عَدَدَها الذي يَتَألَّفُ منه العامُ.\n\n﴿فِي كِتَـٰبِ ٱللَّهِ﴾: في حُكْمِه القَدَريِّ الذي كُتب في اللَّوحِ المحفوظِ.\n\n﴿أَرۡبَعَةٌ حُرُمࣱ﴾: أي: ذاتُ حُرْمَةٍ وتعظيمٍ، وهي: رَجَبٌ، وذو القِعدة، وذو الحِجَّةِ، والمُحَرَّمُ.\n\n﴿ٱلۡقَيِّمُ﴾: المستقيمُ الذي لا عِوَجَ فيه.\n\n﴿فَلَا تَظۡلِمُواْ فِيهِنَّ أَنفُسَكُمۡ﴾: بارتكابِ ما حَرَّمَ اللهُ؛ لعِظَمِ حُرْمتِها.\n\n﴿كَآفَّةࣰ﴾: جميعًا، وفي كلِّ الشهورِ.\n\n﴿وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ مَعَ ٱلۡمُتَّقِينَ﴾: بالعَوْنِ والنَّصرِ."],[37,37,"﴿ٱلنَّسِيٓءُ﴾: تأخيرُ حُرْمَةِ شهرٍ إلى شهرٍ آخرَ، كما كانت تفعلُه العربُ في الجاهليةِ.\n\n﴿يُحِلُّونَهُۥ﴾: أي: النسيءَ.\n\n﴿لِّيُوَاطِـُٔواْ﴾: ليوافِقُوا بتحليلِ شهرٍ وتحريمِ آخرَ بَدَلَه.\n\n﴿عِدَّةَ﴾: عددَ.\n\n﴿مَا حَرَّمَ ٱللَّهُ﴾: من الأشهرِ، بحيث تكونُ أربعةً في العددِ.\n\n﴿لَا يَهۡدِي﴾: لا يُوَفِّقُ."],[38,38,"﴿ٱنفِرُواْ﴾: اخرُجُوا بخِفَّةٍ ونشاطٍ.\n\n﴿فِي سَبِيلِ ٱللَّهِ﴾: إلى الجهادِ لإعلاءِ كلمةِ اللهِ.\n\n﴿ٱثَّاقَلۡتُمۡ إِلَى ٱلۡأَرۡضِ﴾: تباطَأْتم في الخروجِ ومِلْتُم إلى الإقامةِ في أرضِكم ومساكِنِكُم.\n\n﴿مِنَ ٱلۡـَٔاخِرَةِ﴾: بدلَ نعيمِ الآخرةِ.\n\n﴿مَتَـٰعُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا﴾: ما يُتَمَتَّعُ به مِن لَذّاتِ الدنيا."],[39,39,"﴿يُعَذِّبۡكُمۡ﴾: يُنْزِلْ عقوبتَه بكم."],[40,40,"﴿إِلَّا تَنصُرُوهُ﴾: إن لم تَنْصُروا النبيَّ ﷺ.\n\n﴿ثَانِيَ ٱثۡنَيۡنِ﴾: أحدَ اثنين، والثاني هو أبوبكرٍ الصدّيقُ رضي الله عنه.\n\n﴿ٱلۡغَارِ﴾: النَّقْبِ في الَجبَلِ، وهو في جبلِ ثورٍ ب«مكةَ».\n\n﴿لِصَـٰحِبِهِۦ﴾: أبي بكرٍ الصديقِ رضي الله عنه.\n\n﴿سَكِينَتَهُۥ﴾: طمأنينتَه.\n\n﴿بِجُنُودࣲ﴾: هم الملائكةُ، يَحْرُسُونه ويَصْرِفُون أبصارَ الكفارِ عنه.\n\n﴿كَلِمَةَ ٱلَّذِينَ كَفَرُواْ﴾: أي: دعوةَ الشِّركِ والكفرِ.\n\n﴿ٱلسُّفۡلَىٰ﴾: المغلوبةَ.\n\n﴿كَلِمَةُ ٱللَّهِ﴾: كلمةُ التوحيدِ.\n\n﴿ٱلۡعُلۡيَا﴾: الغالبةُ."],[41,41,"﴿خِفَافࣰا﴾: على الصِّفةِ التي يَخِفُّ عليكم الجهادُ فيها.\n\n﴿وَثِقَالࣰا﴾: وعلى الصفةِ التي يَثْقُلُ عليكم الجهادُ فيها."],[42,42,"﴿لَوۡ كَانَ﴾: أي: ما دَعَوْتَهم إليه من الخروجِ للجهادِ.\n\n﴿عَرَضࣰا﴾: مَتاعًا وغَنيمةً.\n\n﴿قَرِيبࣰا﴾: سَهْلَ المأخَذِ.\n\n﴿قَاصِدࣰا﴾: متوسِّطًا بَيْنَ القُرْبِ والبُعْدِ لا مَشَقَّةَ فيه.\n\n﴿ٱلشُّقَّةُ﴾: المسافةُ البعيدةُ التي تُقْطَعُ بمَشَقَّةٍ.\n\n﴿يُهۡلِكُونَ أَنفُسَهُمۡ﴾: بالَحلِفِ الكاذبِ والنِّفاقِ."],[43,43,"﴿عَفَا ٱللَّهُ عَنكَ﴾: العَفْوُ: هو التجاوُزُ عن الخطأ وتَرْكُ المؤاخذةِ عليه."],[45,45,"﴿يَسۡتَـٔۡذِنُكَ﴾: يَطْلُبُ الإذنَ للتخَلُّفِ عن الجهادِ.\n\n﴿وَٱرۡتَابَتۡ قُلُوبُهُمۡ﴾: شَكَّتْ في الإسلامِ وشرائعِه.\n\n﴿يَتَرَدَّدُونَ﴾: يتَحيَّرُون."],[46,46,"﴿ٱلۡخُرُوجَ﴾: مَعَك إلى الجهادِ.\n\n﴿لَأَعَدُّواْ لَهُۥ عُدَّةࣰ﴾: لَتَأهَّبُوا له بإعدادِ السِّلاحِ، والزادِ، وما يُحتاجُ إليه.\n\n﴿ٱنۢبِعَاثَهُمۡ﴾: خروجَهم للجهادِ.\n\n﴿فَثَبَّطَهُمۡ﴾: مَنَعهم وعوَّقهم بقَضائِه وقَدَرِه.\n\n﴿ٱقۡعُدُواْ﴾: تَخَلَّفُوا عن الجِهادِ.\n\n﴿مَعَ ٱلۡقَـٰعِدِينَ﴾: من المرضى والضُّعَفاءِ والنِّساءِ والصِّبْيانِ."],[47,47,"﴿خَبَالࣰا﴾: شرًّا وفسادًا.\n\n﴿وَلَأَوۡضَعُواْ خِلَـٰلَكُمۡ﴾: أسْرَعُوا في المَشْيِ بينَكم بالنميمةِ وإفسادِ القلوبِ.\n\n﴿يَبۡغُونَكُمُ﴾: يُريدُون لكم.\n\n﴿ٱلۡفِتۡنَةَ﴾: ما تُفْتَنُون به؛ كي تتثاقَلُوا عن الجهادِ في سبيلِ اللهِ.\n\n﴿سَمَّـٰعُونَ لَهُمۡ﴾: مَن يَسْمعون كلام المنافقين، ويُطيعونهم."],[48,48,"﴿ٱبۡتَغَوُاْ﴾: طلبُوا وأرادوا.\n\n﴿ٱلۡفِتۡنَةَ﴾: فتنةَ المؤمنين وصَدَّهم عن دينِهم.\n\n﴿مِن قَبۡلُ﴾: من قبلِ غزوةِ «تبوكَ».\n\n﴿وَقَلَّبُواْ لَكَ ٱلۡأُمُورَ﴾: أرادُوا إبطالَ ما جِئْتَ به بتحايُلِهم ومَكْرِهم.\n\n﴿ٱلۡحَقُّ﴾: النصرُ من عندِ اللهِ.\n\n﴿وَظَهَرَ﴾: علا وغَلَبَ.\n\n﴿أَمۡرُ ٱللَّهِ﴾: دينُه، وهو الإسلامُ."],[49,49,"﴿وَمِنۡهُم﴾: ومن المنافقين.\n\n﴿ٱئۡذَن لِّي﴾: في التخَلُّف عن الجهادِ.\n\n﴿وَلَا تَفۡتِنِّيٓ﴾: لاتُوقِعْني في فتنةِ النِّساءِ حالةَ الخروجِ معك.\n\n﴿فِي ٱلۡفِتۡنَةِ﴾: فتنةِ النِّفاقِ والتخلُّفِ عن الجهادِ.\n\n﴿سَقَطُواْ﴾: وقعوا في الإثمِ لمخالَفَتِهم أمرَ اللهِ ورسولِه."],[50,50,"﴿حَسَنَةࣱ﴾: نصرٌ وغنيمةٌ.\n\n﴿مُصِيبَةࣱ﴾: مَكْرُوهٌ من هزيمةٍ أو شدَّةٍ.\n\n﴿قَدۡ أَخَذۡنَآ أَمۡرَنَا مِن قَبۡلُ﴾: قد احْتَطْنا لأنفسِنا حين تَخَلَّفْنا عن الجهادِ قبلَ هذه المصيبةِ.\n\n﴿وَيَتَوَلَّواْ﴾: وينصَرِفُوا."],[51,51,"﴿مَا كَتَبَ ٱللَّهُ لَنَا﴾: ما قَدَّرَه علينا.\n\n﴿هُوَ مَوۡلَىٰنَا﴾: ناصِرُنا ومُتَوَلِّي أمورِنا.\n\n﴿وَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ﴾: فلْيَعْتَمِدْ ولْيُفَوِّضْ أمرَه إليه."],[52,52,"﴿هَلۡ تَرَبَّصُونَ﴾: ما تنتظرون أن يَقَعَ.\n\n﴿إِحۡدَى ٱلۡحُسۡنَيَيۡنِ﴾: إحدى العاقبتَين: النصرَ، أوالشهادةَ في سبيلِ اللهِ."],[53,53,"﴿طَوۡعًا﴾: طائعِين.\n\n﴿كَرۡهࣰا﴾: كارهِين.\n\n﴿فَـٰسِقِينَ﴾: خارجِين عن دينِ اللهِ."],[54,54,"﴿كُسَالَىٰ﴾: متثاقلون عن الصَّلاةِ."],[55,55,"﴿لِيُعَذِّبَهُم بِهَا﴾: بما يَلْقَون من التعبِ في جَمْعِها، وبالمصائبِ التي تقعُ فيها.\n\n﴿وَتَزۡهَقَ﴾: تَخْرُجَ."],[56,56,"﴿يَفۡرَقُونَ﴾: يَخافُون."],[57,57,"﴿مَلۡجَـًٔا﴾: حِصْنًا ومأمَنًا يلجَؤُون إليه.\n\n﴿مَغَـٰرَ ٰ⁠تٍ﴾: جَمْعُ مَغارةٍ، وهي الكَهْفُ، أو الغارُ في الجبلِ يُؤْويهم.\n\n﴿مُدَّخَلࣰا﴾: مكانًا يَدْخلونه كالنَّفَقِ في الأرضِ.\n\n﴿لَّوَلَّوۡاْ﴾: لَأَقْبَلُوا.\n\n﴿يَجۡمَحُونَ﴾: يُسْرِعون في دخولِه لا يَمْنَعُهم شيءٌ."],[58,58,"﴿يَلۡمِزُكَ﴾: يَعِيبُك.\n\n﴿ٱلصَّدَقَـٰتِ﴾: في قِسْمةِ أموالِ الصَّدقاتِ."],[59,59,"﴿حَسۡبُنَا ٱللَّهُ﴾: كافِينا.\n\n﴿إِلَى ٱللَّهِ رَ ٰ⁠غِبُونَ﴾: مُحِبُّون أن يُغْنيَنا من فضلِه."],[60,60,"﴿ٱلصَّدَقَـٰتُ﴾: الزَّكَواتُ المفروضةُ.\n\n﴿لِلۡفُقَرَآءِ﴾: للمحتاجِين الذين لا يَمْلِكُون شيئًا.\n\n﴿وَٱلۡمَسَـٰكِينِ﴾: الذين لا يَمْلِكُون ما يَكْفيهم ويَسُدُّ حاجتَهم.\n\n﴿وَٱلۡعَـٰمِلِينَ عَلَيۡهَا﴾: السُّعاةُ الذين يَجْمعون الزكاةَ من أصحابِها.\n\n﴿وَٱلۡمُؤَلَّفَةِ قُلُوبُهُمۡ﴾: المستمالةِ قلوبُهم إلى الإسلام كمن يُرْجى إسلامُه أو قوَّةُ إيمانِه.\n\n﴿وَفِي ٱلرِّقَابِ﴾: وتُعطى الزكاةُ في عِتْقِ رقابِ العبيدِ والمكاتَبين.\n\n﴿وَٱلۡغَـٰرِمِينَ﴾: الذين استدانُوا لأنفسهم، ولا قُدَرةَ لهم على الوفاءِ، أو استدانُوا لإصلاحِ ذاتِ البَيْنِ.\n\n﴿وَفِي سَبِيلِ ٱللَّهِ﴾: وللغُزاةِ وللمرابطين في سبيل الله.\n\n﴿وَٱبۡنِ ٱلسَّبِيلِ﴾: المسافرِ المنقطعِ عن مالِه في سفرِه، وإن كان غنيًا في بلدِه.\n\n﴿فَرِيضَةࣰ مِّنَ ٱللَّهِ﴾: هذه القِسْمةُ فَرَضَها اللهُ فريضةً وقَدَّرها."],[61,61,"﴿أُذُنࣱ﴾: يستمعُ لكلِّ ما يُقالُ له ويُصَدِّقُه.\n\n﴿قُلۡ أُذُنُ خَيۡرࣲ لَّكُمۡ﴾: أي: أُذُنٌ في الخيرِ والحقِّ، وفيما يجبُ سَماعُه وقَبولُه.\n\n﴿وَيُؤۡمِنُ لِلۡمُؤۡمِنِينَ﴾: ويُصَدِّقُ المؤمنين فيما يُخبرونه."],[63,63,"﴿يُحَادِدِ﴾: يخالِفْ."],[64,64,"﴿تُنَبِّئُهُم﴾: تُخَبِّرُهم.\n\n﴿بِمَا فِي قُلُوبِهِمۡ﴾: بما يُضْمِرُونَه في قلوبِهم من الكفرِ.\n\n﴿مُخۡرِجࣱ مَّا تَحۡذَرُونَ﴾: مُظْهِرٌ ما تَخافُونه من الفضيحةِ."],[65,65,"﴿وَلَئِن سَأَلۡتَهُمۡ﴾: عَمّا قالوا من الطَّعْنِ في حَقِّك وحَقِّ أصحابِك.\n\n﴿نَخُوضُ وَنَلۡعَبُ﴾: نتحَدَّثُ بكلامٍ لم نَقْصِدْ به الإساءةَ."],[66,66,"﴿إِن نَّعۡفُ عَن طَآئِفَةࣲ مِّنكُمۡ﴾: بالتوفيق للتوبةِ والإخلاصِ فيها.\n\n﴿نُعَذِّبۡ طَآئِفَةَۢ﴾: بسبب تَرْكِ التوبةِ والإصرارِ على النِّفاقِ."],[67,67,"﴿بَعۡضُهُم مِّنۢ بَعۡضࣲ﴾: أي: مُتَشابهون في صفةِ النِّفاقِ والبُعْدِ عن الإيمانِ.\n\n﴿بِٱلۡمُنكَرِ﴾: بالكفرِ والمعاصي.\n\n﴿ٱلۡمَعۡرُوفِ﴾: هو كلُّ ما عُرِفَ حُسْنُه في الشَّرعِ والعَقْلِ.\n\n﴿وَيَقۡبِضُونَ أَيۡدِيَهُمۡ﴾: ويُمْسِكُون عن الإنفاقِ في طاعةِ اللهِ ومَرْضاتِه.\n\n﴿نَسُواْ ٱللَّهَ﴾: تَرَكُوا طاعتَه وأوامرَه.\n\n﴿فَنَسِيَهُمۡ﴾: فتركَهم من رحمتِه وثوابِه.\n\n﴿ٱلۡفَـٰسِقُونَ﴾: الخارجُون عن الإيمانِ والطاعة."],[68,68,"﴿حَسۡبُهُمۡ﴾: كافِيهم؛ عقابًا على كفرِهم.\n\n﴿وَلَعَنَهُمُ ٱللَّهُ﴾: طَرَدَهم مِن رحمتِه.\n\n﴿مُّقِيمࣱ﴾: دائمٌ لا ينقطعُ."],[69,69,"﴿بِخَلَـٰقِهِمۡ﴾: بنصيبِهم الذي قُدِّرَ لهم من مَلاذِّ الدنيا.\n\n﴿وَخُضۡتُمۡ﴾: ودَخَلْتُم في الباطلِ والطَّعْنِ في الدِّينِ.\n\n﴿حَبِطَتۡ﴾: بَطَلَتْ."],[70,70,"﴿نَبَأُ﴾: خبرُ.\n\n﴿وَأَصۡحَـٰبِ مَدۡيَنَ﴾: هم قومُ شعيبٍ عليه السلام.\n\n﴿وَٱلۡمُؤۡتَفِكَـٰتِ﴾: قُرى قومِ لوطٍ عليه السلام، التي انقلبَتْ بهم، فصار عالِيها سافلَها.\n\n﴿بِٱلۡبَيِّنَـٰتِ﴾: بالوَحْيِ والمعجزاتِ.\n\n﴿كَانُوٓاْ أَنفُسَهُمۡ يَظۡلِمُونَ﴾: بتعريضِها للعقابِ؛ بسببِ كُفْرِهم."],[71,71,"﴿أَوۡلِيَآءُ بَعۡضࣲ﴾: أنصارُ بعضٍ.\n\n﴿عَزِيزٌ﴾: لا يُعْجِزُه شيء عن إنجازِ وعْدِه بالمؤمنين، ووعيدِه بمَن عَصاه وكَفَرَ به.\n\n﴿حَكِيمࣱ﴾: يَضَعُ الأمورَ في محالِّها."],[72,72,"﴿مِن تَحۡتِهَا﴾: من تحتِ قصورِها وأشجارِها.\n\n﴿طَيِّبَةࣰ﴾: حسنةَ البناءِ، طَيِّبةَ القَرارِ.\n\n﴿جَنَّـٰتِ عَدۡنࣲ﴾: أي: إقامةٍ وخُلودٍ.\n\n﴿أَكۡبَرُ﴾: ممّا هم فيه من أنواعِ النعيمِ."],[73,73,"﴿وَٱغۡلُظۡ﴾: واشدُدْ في جهادِك.\n\n﴿وَمَأۡوَىٰهُمۡ﴾: مصيرُهم."],[74,74,"﴿كَلِمَةَ ٱلۡكُفۡرِ﴾: هي استهزاؤهُم بالرسولِ عليه الصلاةُ والسلام، وبالدِّينِ.\n\n﴿وَهَمُّواْ﴾: وصَمَّمَ المنافقون على قَتْلِ الرسولِ ﷺ.\n\n﴿بِمَا لَمۡ يَنَالُواْ﴾: بما لم يُمَكِّنْهم اللهُ منه.\n\n﴿وَمَا نَقَمُوٓاْ﴾: وما وجَدَ المنافقون شيئًا يَكْرَهُونه ويَعِيبونَه.\n\n﴿وَإِن يَتَوَلَّوۡاْ﴾: يُعْرِضُوا، أو يَسْتمِرُّوا على حالِهم.\n\n﴿وَلِيࣲّ﴾: يَلي أمورَهم وينفَعُهم.\n\n﴿وَلَا نَصِيرࣲ﴾: ولا ناصرٍ يَدْفَعُ عنهم ما هم فيه."],[75,75,"﴿عَـٰهَدَ ٱللَّهَ﴾: قَطَعَ على نفسِه العهدَ مع اللهِ."],[77,77,"﴿فَأَعۡقَبَهُمۡ نِفَاقࣰا﴾: فأَوْرَثَهم اللهُ جزاءَ صنيعِهم زيادةً في نفاقِهم."],[78,78,"﴿سِرَّهُمۡ﴾: ما انطَوتْ عليه نفوسُهم من النِّفاق.\n\n﴿وَنَجۡوَىٰهُمۡ﴾: ما يتحَدَّثون به بينهَم من الكَيْدِ والمَكْر."],[79,79,"﴿يَلۡمِزُونَ ٱلۡمُطَّوِّعِينَ﴾: يَعِيبُون المتصدِّقين ويَطْعَنُون في إخلاصِهم.\n\n﴿جُهۡدَهُمۡ﴾: طاقَتَهم وما تَبْلُغُه قُوَّتُهم."],[80,80,"﴿سَبۡعِينَ مَرَّةࣰ﴾: أي: مهما كَثُرَ استغفارُك لهم وتكرَّر.\n\n﴿لَا يَهۡدِي﴾: لا يُوَفِّقُ.\n\n﴿ٱلۡفَـٰسِقِينَ﴾: الخارجين عن دينِ الله."],[81,81,"﴿ٱلۡمُخَلَّفُونَ﴾: الذين تخلَّفُوا عن الجهادِ في غزوةِ «تبوكَ».\n\n﴿بِمَقۡعَدِهِمۡ﴾: أي: بقُعودِهم.\n\n﴿خِلَـٰفَ رَسُولِ ٱللَّهِ﴾: مخالِفِين رسولَ الله ﷺ.\n\n﴿لَا تَنفِرُواْ﴾: لا تَخْرُجُوا إلى الجهادِ."],[82,82,"﴿قَلِيلࣰا﴾: في الدنيا.\n\n﴿كَثِيرࣰا﴾: في الآخرةِ."],[83,83,"﴿أَوَّلَ مَرَّةࣲ﴾: هي غزوةُ «تبوكَ».\n\n﴿ٱلۡخَـٰلِفِينَ﴾: المتخلِّفين عن الجهادِ كالنِّساءِ والصِّبيانِ."],[84,84,"﴿وَلَا تَقُمۡ عَلَىٰ قَبۡرِهِۦٓ﴾: لأجلِ الدَّفْنِ، أو الزيارةِ، أو الدعاءِ له."],[85,85,"﴿أَن يُعَذِّبَهُم بِهَا﴾: بما يَلْقَون من التعب في جَمْعِها، وبالمصائبِ التي تقعُ فيها.\n\n﴿وَتَزۡهَقَ﴾: تَخْرُجَ."],[86,86,"﴿أُوْلُواْ ٱلطَّوۡلِ﴾: أصحابُ الغِنى والمقدرةِ على الجهادِ.\n\n﴿ذَرۡنَا﴾: اتْرُكْنا."],[87,87,"﴿ٱلۡخَوَالِفِ﴾: جَمعُ خالِفة، ويقال للمرأةِ والرجل، والمرادُ: النِّساءُ اللاتي تخلَّفْنَ في البيوتِ، أو الرجالُ العاجزون عن القتال.\n\n﴿وَطُبِعَ﴾: ختمَ اللهُ."],[88,88,"﴿ٱلۡخَيۡرَ ٰ⁠تُ﴾: في الدنيا والآخرةِ."],[90,90,"﴿ٱلۡمُعَذِّرُونَ﴾: المعتذرون بأعذارٍ كاذبةٍ عن عدمِ الخروجِ للغَزْوِ.\n\n﴿ٱلۡأَعۡرَابِ﴾: سُكّانِ الباديةِ.\n\n﴿وَقَعَدَ﴾: عن الغزوِ لغيرِ عُذْرٍ."],[91,91,"﴿حَرَجٌ﴾: إثمٌ.\n\n﴿نَصَحُواْ﴾: أخلَصُوا.\n\n﴿مِن سَبِيلࣲ﴾: من طريقٍ للمؤاخذةِ."],[92,92,"﴿لِتَحۡمِلَهُمۡ﴾: على ما يَرْكَبون عليه في الغَزْو.\n\n﴿تَوَلَّواْ﴾: انْصَرَفُوا مِن عندِك.\n\n﴿حَزَنًا﴾: أسَفًا على ما فاتَهم من شَرَفِ الجهادِ وثوابِه."],[93,93,"﴿ٱلسَّبِيلُ﴾: طريقُ العقوبةِ والمؤاخَذَةِ."],[94,94,"﴿إِذَا رَجَعۡتُمۡ إِلَيۡهِمۡ﴾: من الغَزْوِ.\n\n﴿لَن نُّؤۡمِنَ لَكُمۡ﴾: لن نُصَدِّقَكم."],[95,95,"﴿إِذَا ٱنقَلَبۡتُمۡ إِلَيۡهِمۡ﴾: رَجَعْتُم إليهم من الغَزْو.\n\n﴿لِتُعۡرِضُواْ عَنۡهُمۡ﴾: لتَتْرُكُوهم وتَصْفَحُوا عنهم.\n\n﴿رِجۡسࣱ﴾: خبثاءُ في بَواطِنِهم واعتقاداتِهم.\n\n﴿وَمَأۡوَىٰهُمۡ﴾: مصيرُهم."],[96,96,"﴿ٱلۡفَـٰسِقِينَ﴾: الخارجين عن دينِ اللهِ."],[97,97,"﴿ٱلۡأَعۡرَابُ﴾: سُكّانُ الباديةِ.\n\n﴿وَأَجۡدَرُ﴾: وأحَقُّ."],[98,98,"﴿مَغۡرَمࣰا﴾: غَرامةً وخَسارةً.\n\n﴿وَيَتَرَبَّصُ﴾: ينتظرُ.\n\n﴿ٱلدَّوَآئِرَ﴾: جَمْعُ دائرةٍ، وهي: تَقَلُّباتُ الدَّهْرِ ومصائبُه.\n\n﴿ٱلسَّوۡءِ﴾: كلُّ ما يسوءُ ويَضُرُّ."],[99,99,"﴿وَيَتَّخِذُ مَا يُنفِقُ﴾: ويحتسِبُ ما ينفقُه في سبيلِ اللهِ.\n\n﴿قُرُبَـٰتٍ عِندَ ٱللَّهِ﴾: جَمْعُ قُرْبَةٍ، وهي: ما يُتَقَرَّبُ به إلى اللهِ تعالى.\n\n﴿وَصَلَوَ ٰ⁠تِ ٱلرَّسُولِ﴾: جَمْعُ صلاةٍ، وهي هنا: الدعاُء، أي: ويَجْعَلُ إنفاقَه في سبيلِ اللهِ وسيلةً إلى دعاءِ الرسولِ ﷺ له."],[100,100,"﴿ٱلۡمُهَـٰجِرِينَ﴾: الذين هَجَرُوا قومَهم، وانتقلُوا من بلدِ الفتنةِ إلى دارِ الإسلامِ.\n\n﴿وَٱلۡأَنصَارِ﴾: الذين نصرُوا النبي ﷺ، وآوَوا المهاجرين.\n\n﴿بِإِحۡسَـٰنࣲ﴾: في الاعتقادِ والأقوالِ والأعمالِ.\n\n﴿تَحۡتَهَا﴾: تحتَ قصورِها وأشجارِها."],[101,101,"﴿مَرَدُواْ عَلَى ٱلنِّفَاقِ﴾: مَهَرُوا فيه واستمَرُّوا عليه.\n\n﴿سَنُعَذِّبُهُم مَّرَّتَيۡنِ﴾: الأولى: في الدنيا بفضيحتِهم، أو بأنواعِ المكارِهِ التي تنالُهم، والثانية: بعذابِ القبرِ.\n\n﴿عَذَابٍ عَظِيمࣲ﴾: نارِ جهنمَ."],[102,102,"﴿عَمَلࣰا صَـٰلِحࣰا﴾: ما سَبَقَ لهم من الجهادِ مع توبتِهم.\n\n﴿وَءَاخَرَ سَيِّئًا﴾: تَخَلُّفَهم عن غزوةِ «تبوكَ»."],[103,103,"﴿تُطَهِّرُهُمۡ﴾: تُزيلُ بها أثَرَ ذنوبِهم.\n\n﴿وَتُزَكِّيهِم بِهَا﴾: تُنَمِّي بها حَسَناتِهم وترفَعُهم إلى منازلِ المُخْلَصِين.\n\n﴿وَصَلِّ عَلَيۡهِمۡ﴾: ادْعُ لهم واستغفِرْ.\n\n﴿سَكَنࣱ لَّهُمۡ﴾: سكينةٌ لنفوسِهم وطُمَأنينةٌ لقلوبِهم."],[104,104,"﴿وَيَأۡخُذُ ٱلصَّدَقَـٰتِ﴾: يَقْبَلُها ويُثيبُ عليها."],[105,105,"﴿وَسَتُرَدُّونَ﴾: ستُرْجَعُون يومَ القيامةِ."],[106,106,"﴿مُرۡجَوۡنَ لِأَمۡرِ ٱللَّهِ﴾: مُؤَخَّرون لحُكمِ اللهِ فيهم."],[107,107,"﴿ضِرَارࣰا﴾: لأجل الضَّرَر بِالمؤمنين.\n\n﴿وَإِرۡصَادࣰا﴾: انتظارًا وإعدادًا.\n\n﴿لِّمَنۡ حَارَبَ ٱللَّهَ وَرَسُولَهُۥ﴾: هو أبو عامرٍ الفاسقُ.\n\n﴿مِن قَبۡلُ﴾: أي: من قَبْلِ بناءِ مسجدِ الضِّرارِ.\n\n﴿ٱلۡحُسۡنَىٰ﴾: الخيرَ والإحسانَ إلى المسلمين."],[108,108,"﴿لَا تَقُمۡ فِيهِ﴾: أي للصَّلاةِ في مَسْجدِ الضِّرارِ.\n\n﴿لَّمَسۡجِدٌ أُسِّسَ عَلَى ٱلتَّقۡوَىٰ﴾: هو مَسْجدُ قُباءٍ.\n\n﴿يُحِبُّونَ أَن يَتَطَهَّرُواْ﴾: طهارةً حسِّيةً من النجاساتِ، ومعنويةً من الذُّنوبِ والمعاصي."],[109,109,"﴿وَرِضۡوَ ٰ⁠نٍ﴾: ورجاءِ مَرْضاةِ اللهِ.\n\n﴿عَلَىٰ شَفَا جُرُفٍ﴾: على طَرَفِ حُفْرَةٍ، أو مكانٍ يَجْرُفُه الماءُ.\n\n﴿هَارࣲ﴾: مُشْرِفٍ على السُّقوط.\n\n﴿فَٱنۡهَارَ بِهِۦ﴾: فسَقَطَ المكانُ بالبُنيانِ مع بانيه.\n\n﴿لَا يَهۡدِي﴾: لا يُوَفِّقُ."],[110,110,"﴿بُنۡيَـٰنُهُمُ﴾: مسجدُ الضِّرارِ.\n\n﴿رِيبَةࣰ فِي قُلُوبِهِمۡ﴾: شَكًّا ونفاقًا راسخًا في قلوبِهم.\n\n﴿تَقَطَّعَ قُلُوبُهُمۡ﴾: تتقَطَّعَ قلوبُهم بَمْوتِهم، فالنِّفاقُ ملازمٌ لهم ماداموا أحياءً."],[111,111,"﴿فَٱسۡتَبۡشِرُواْ﴾: أظْهِرُوا السُّرورَ."],[112,112,"﴿ٱلسَّـٰٓئِحُونَ﴾: الصّائمون."],[114,114,"﴿مَّوۡعِدَةࣲ وَعَدَهَآ إِيَّاهُ﴾: وهي الاستغفارُ له.\n\n﴿لَأَوَّ ٰ⁠هٌ﴾: كثيرُ التضرُّعِ إلى اللهِ.\n\n﴿حَلِيمࣱ﴾: صَبُورٌ على الأذى، كثيرُ الصَّفْحِ عَمَّن نالَه بمَكْروه."],[115,115,"﴿مَّا يَتَّقُونَ﴾: ما يَجِبُ عليهم اتقاؤُه من المُحَرَّماتِ."],[116,116,"﴿وَلِيࣲّ﴾: يَتَوَلّى أمورَكم وينفَعُكم.\n\n﴿وَلَا نَصِيرࣲ﴾: يَنْصُرُكم ويَدْفَعُ عنكم ما أنتم فيه."],[117,117,"﴿سَاعَةِ ٱلۡعُسۡرَةِ﴾: وقتِ الشِّدةِ، وهي غزوةُ «تبوكَ».\n\n﴿يَزِيغُ قُلُوبُ﴾: تميلُ إلى التخَلُّفِ عن الجهادِ.\n\n﴿بِهِمۡ رَءُوفࣱ﴾: كثيرُ الرأفةِ والرحمةِ بهم في عاجِلِهم وآجِلِهم."],[118,118,"﴿وَعَلَى ٱلثَّلَـٰثَةِ﴾: أي: وتابَ على الثلاثةِ، وهم: كَعْبُ بنُ مالك، وهِلالُ ابنُ أميةَ، ومُرارةُ بنُ الرَّبِيعِ.\n\n﴿خُلِّفُواْ﴾: تَخَلَّفوا عن الجهادِ في غزوةِ «تبوكَ».\n\n﴿بِمَا رَحُبَتۡ﴾: أي: مع سَعَتِها؛ ندمًا بسبب تَخَلُّفِهم عن الغزوِ.\n\n﴿وَظَنُّوٓاْ﴾: أيقنوا.\n\n﴿ثُمَّ تَابَ عَلَيۡهِمۡ﴾: وفَّقهم اللهُ للتوبةِ.\n\n﴿لِيَتُوبُوٓاْ﴾: ليستمِرُّوا على التوبةِ ويثبتُوا عليها."],[120,120,"﴿مَا كَانَ لِأَهۡلِ ٱلۡمَدِينَةِ﴾: أي: ليس لهم.\n\n﴿وَلَا يَرۡغَبُواْ بِأَنفُسِهِمۡ عَن نَّفۡسِهِۦ﴾: لا يَرْضَوْا لها بالراحة، ورسولُ الله ﷺ في تعبٍ ومشقةٍ.\n\n﴿ظَمَأࣱ﴾: عَطَشٌ.\n\n﴿وَلَا نَصَبࣱ﴾: تَعَبٌ.\n\n﴿وَلَا مَخۡمَصَةࣱ﴾: جُوعٌ شديدٌ.\n\n﴿مَوۡطِئࣰا﴾: مكانًا.\n\n﴿يَغِيظُ﴾: يُغْضِبُ.\n\n﴿نَّيۡلًا﴾: بقَتْلٍ، أو أسْرٍ، أو جِراحَةٍ، أو غنيمةٍ ونحوِها."],[122,122,"﴿فَلَوۡلَا﴾: فهَلّا.\n\n﴿نَفَرَ﴾: خَرَج للغزوِ والجهادِ."],[123,123,"﴿يَلُونَكُم﴾: يجاوِرُونكم.\n\n﴿غِلۡظَةࣰ﴾: شدَّةً."],[124,124,"﴿فَمِنۡهُم﴾: فمِنَ المنافقين.\n\n﴿يَسۡتَبۡشِرُونَ﴾: يَفْرحُون بفضلِ اللهِ عليهم."],[125,125,"﴿مَّرَضࣱ﴾: شكٌّ ونِفاقٌ.\n\n﴿رِجۡسًا إِلَىٰ رِجۡسِهِمۡ﴾: نِفاقًا وكُفْرًا إلى كُفْرِهم."],[126,126,"﴿يُفۡتَنُونَ﴾: يُبْتلَوْن بأنواعِ البَلاءِ.\n\n﴿وَلَا هُمۡ يَذَّكَّرُونَ﴾: لا يَتَّعِظُون بما نَزَلَ بهم."],[127,127,"﴿نَّظَرَ بَعۡضُهُمۡ إِلَىٰ بَعۡضٍ﴾: تغامَزَ المنافقون بالعيونِ؛ إنكارًا لنزولِ السورةِ، وغيظًا لما فيها من بيانِ عيوبِهم.\n\n﴿هَلۡ يَرَىٰكُم مِّنۡ أَحَدࣲ﴾: يُريدون الهروبَ من مجلسِ النبيِّ ﷺ.\n\n﴿صَرَفَ ٱللَّهُ قُلُوبَهُم﴾: عن الإيمانِ.\n\n﴿لَّا يَفۡقَهُونَ﴾: لا يَفْهَمونَ لعَدَمِ تَدَبُّرِهم وإنصافِهم."],[128,128,"﴿مِّنۡ أَنفُسِكُمۡ﴾: من قومِكم.\n\n﴿عَزِيزٌ عَلَيۡهِ﴾: ما تَلْقَوْن من المكروهِ والمشقَّةِ.\n\n﴿رَءُوفࣱ﴾: عظيمُ الرحمةِ شفيقٌ."],[129,129,"﴿تَوَلَّوۡاْ﴾: أعْرَضُوا.\n\n﴿حَسۡبِيَ ٱللَّهُ﴾: يكفيني اللهُ.\n\n﴿عَلَيۡهِ تَوَكَّلۡتُ﴾: اعتمَدْتُ عليه وفوَّضْتُ جميعَ أموري إليه.\n\n﴿ٱلۡعَرۡشِ﴾: سريرِ المُلك الذي استوى عليه الرحمنُ، وتحمِلُه الملائكةُ، وهو أعظمُ المخلوقاتِ، وهو سَقْفُ الجنةِ."]]);
QTF("gharib",10,[[1,1,"﴿ٱلۡحَكِيمِ﴾: المُحْكَمِ في لَفْظِه ومعناه."],[2,2,"﴿قَدَمَ صِدۡقٍ﴾: أجرًا حسنًا؛ بما قَدَّموا من صالحِ الأعمالِ."],[3,3,"﴿ٱسۡتَوَىٰ﴾: علا وارتفعَ، استواءً يَليق بجَلالِه وعَظَمَتِه.\n\n﴿يُدَبِّرُ ٱلۡأَمۡرَ﴾: يَقْضِي أمورَ الدنيا والآخرةِ، ويُصَرِّفُها وحدَه على أكملِ الوجوهِ.\n\n﴿إِلَّا مِنۢ بَعۡدِ إِذۡنِهِۦ﴾: إلا أنْ يأذنَ اللهُ له بالشفاعةِ."],[4,4,"﴿مَرۡجِعُكُمۡ﴾: مَعادُكم يومَ القيامةِ.\n\n﴿بِٱلۡقِسۡطِ﴾: بالعَدْلِ.\n\n﴿حَمِيمࣲ﴾: ماءٍ شديدِ الحرارةِ."],[5,5,"﴿ضِيَآءࣰ﴾: ذاتَ ضياءٍ في النهار.\n\n﴿نُورࣰا﴾: ذاتَ نورٍ في الليل.\n\n﴿وَقَدَّرَهُۥ مَنَازِلَ﴾: وهَيَّأ للقَمَرِ منازلَ لا يتَعدّاها.\n\n﴿وَٱلۡحِسَابَ﴾: ولتعلمُوا حسابَ الأشهرِ والأيامِ.\n\n﴿ذَ ٰ⁠لِكَ﴾: أي: الَخلْقُ والتقديرُ.\n\n﴿إِلَّا بِٱلۡحَقِّ﴾: إلا لحكمةٍ عظيمةٍ بالغةٍ.\n\n﴿يُفَصِّلُ﴾: يُبَيِّنُ.\n\n﴿ٱلۡـَٔايَـٰتِ﴾: الحُجَجَ والأدَّلةَ الدالَّةَ على عَظَمَتِه."],[6,6,"﴿ٱخۡتِلَـٰفِ ٱلَّيۡلِ وَٱلنَّهَارِ﴾: إتيانِ أحدِهما بعد الآخَرِ."],[7,7,"﴿لَا يَرۡجُونَ لِقَآءَنَا﴾: لا يتوقَّعُون حسابَ الآخرةِ.\n\n﴿وَٱطۡمَأَنُّواْ بِهَا﴾: رَكَنُوا إليها.\n\n﴿ءَايَـٰتِنَا﴾: الكونيةِ والشرعيةِ.\n\n﴿غَـٰفِلُونَ﴾: ساهُون ومُعْرِضُون."],[9,9,"﴿يَهۡدِيهِمۡ﴾: يُرْشِدُهم، ويُوَفِّقُهم إلى العملِ المُوصِلِ إلى الجنة.\n\n﴿مِن تَحۡتِهِمُ﴾: مِن تحتِ غُرَفِهم ومنازلهِم."],[10,10,"﴿دَعۡوَىٰهُمۡ فِيهَا سُبۡحَـٰنَكَ ٱللَّهُمَّ﴾: دعاؤُهم الذي يَدْعُون به في الجنةِ التسبيحُ والتنزيهُ لله.\n\n﴿وَتَحِيَّتُهُمۡ﴾: من اللهِ وملائكتِه لهم، وتحيةُ بعضِهم بعضًا.\n\n﴿سَلَـٰمࣱ﴾: دعاءٌ لهم بالسَّلامةِ من كلِّ مكروهٍ."],[11,11,"﴿ٱلشَّرَّ﴾: إجابةَ دعائِهم في الشرِّ.\n\n﴿ٱسۡتِعۡجَالَهُم بِٱلۡخَيۡرِ﴾: تعجيلَ اللهِ لهم بالخيرِ.\n\n﴿لَقُضِيَ إِلَيۡهِمۡ أَجَلُهُمۡ﴾: لأُهْلِكُوا جميعًا.\n\n﴿فَنَذَرُ﴾: نَتْرُكُ.\n\n﴿طُغۡيَـٰنِهِمۡ﴾: تجاوُزِهم الَحدَّ في إنكارِ البعثِ.\n\n﴿يَعۡمَهُونَ﴾: يتردَّدُون متحَيِّرين."],[12,12,"﴿مَسَّ﴾: أصاب.\n\n﴿ٱلضُّرُّ﴾: الشِّدَّةُ والمكروهُ.\n\n﴿لِجَنۢبِهِۦٓ﴾: مُضْطجعًا على جَنْبِه.\n\n﴿مَرَّ كَأَن لَّمۡ يَدۡعُنَآ﴾: استمرَّ على ما كان عليه قبل أن يُبْتلى.\n\n﴿لِلۡمُسۡرِفِينَ﴾: المتجاوِزِين الَحدَّ في الكفرِ والمعاصي."],[13,13,"﴿ٱلۡقُرُونَ﴾: جَمْعُ قَرْن، وهم: القومُ المقتَرِنون في زمانٍ واحدٍ.\n\n﴿ظَلَمُواْ﴾: أشرَكُوا وكَذَّبُوا.\n\n﴿بِٱلۡبَيِّنَـٰتِ﴾: الدَّلالاتِ الواضحاتِ الدالَّةِ على صدقِهم."],[14,14,"﴿خَلَـٰٓئِفَ﴾: جَمْعُ خليفة، وهو مَن يَخْلُفُ غيرَه."],[15,15,"﴿بَيِّنَـٰتࣲ﴾: واضحاتٍ.\n\n﴿لَا يَرۡجُونَ لِقَآءَنَا﴾: لا يتَوقَّعُون حسابَ الآخرةِ.\n\n﴿أَوۡ بَدِّلۡهُ﴾: أو غَيِّرْ فيه بما ليس منه."],[16,16,"﴿وَلَآ أَدۡرَىٰكُم بِهِۦ﴾: ولا أعْلَمَكم به على لساني.\n\n﴿عُمُرࣰا﴾: زَمَنًا طويلًا، وهو أربعون سنةً."],[17,17,"﴿ٱفۡتَرَىٰ﴾: اختَلَق."],[18,18,"﴿شُفَعَـٰٓؤُنَا﴾: يَشْفَعُون لنا.\n\n﴿بِمَا لَا يَعۡلَمُ﴾: وهو أنّ له شفيعًا عندَه بغيرِ إذنِه.\n\n﴿سُبۡحَـٰنَهُۥ﴾: تنزيهًا له."],[19,19,"﴿أُمَّةࣰ وَ ٰ⁠حِدَةࣰ﴾: على دينٍ واحدٍ، وهو الإسلامُ.\n\n﴿وَلَوۡلَا كَلِمَةࣱ سَبَقَتۡ مِن رَّبِّكَ﴾: وهي تأخيرُه القضاءَ بينَهم إلى يومِ القيامةِ.\n\n﴿لَقُضِيَ بَيۡنَهُمۡ﴾: عاجلًا في الدُّنيا."],[20,20,"﴿لَوۡلَآ﴾: هَلّا.\n\n﴿ءَايَةࣱ﴾: علامةٌ حِسِّيةٌ مما اقترحُوه، كجَعْلِ الجبالِ ذَهَبًا.\n\n﴿إِنَّمَا ٱلۡغَيۡبُ لِلَّهِ﴾: نُزولُ الآيةِ غَيْبٌ، واللهُ هو المختصُّ به."],[21,21,"﴿ٱلنَّاسَ﴾: المشركين.\n\n﴿رَحۡمَةࣰ﴾: يُسْرًا ورَخاءً.\n\n﴿ضَرَّآءَ﴾: شِدَّةً وبَلاءً.\n\n﴿مَّكۡرࣱ فِيٓ ءَايَاتِنَا﴾: بالتكذيبِ والاستهزاءِ بها.\n\n﴿أَسۡرَعُ مَكۡرًا﴾: أسرعُ استدراجًا وعقوبةً لكم.\n\n﴿رُسُلَنَا﴾: الكَتَبةَ من الملائكةِ."],[22,22,"﴿ٱلۡفُلۡكِ﴾: السُّفُنِ.\n\n﴿طَيِّبَةࣲ﴾: سَهْلَةِ الهُبوبِ، موافِقَةٍ للغَرَضِ والمنفعةِ.\n\n﴿عَاصِفࣱ﴾: شديدةُ الهبوبِ.\n\n﴿وَظَنُّوٓاْ﴾: أيقَنُوا.\n\n﴿أُحِيطَ بِهِمۡ﴾: وقَعَ عليهم الهلاكُ.\n\n﴿ٱلدِّينَ﴾: الدُّعاءَ."],[23,23,"﴿يَبۡغُونَ فِي ٱلۡأَرۡضِ﴾: يُفْسِدُون فيها متجاوِزينَ الحَدَّ في المعاصي.\n\n﴿بَغۡيُكُمۡ عَلَىٰٓ أَنفُسِكُم﴾: مَصِيرُ فسادِكم عائدٌ عليكم.\n\n﴿مَّتَـٰعَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا﴾: تتمتعون به مَتاعًا زائلًا."],[24,24,"﴿مَثَلُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا﴾: حالُها في سُرْعَةِ انقضائِها وذَهابِ لَذّاتِها.\n\n﴿فَٱخۡتَلَطَ بِهِۦ نَبَاتُ ٱلۡأَرۡضِ﴾: فَنَبتَ بماءِ المطر أنواعٌ من النباتِ، تشابَكَتْ واختلَطَ بعضُها ببعض.\n\n﴿أَخَذَتِ ٱلۡأَرۡضُ زُخۡرُفَهَا﴾: ظَهَرَ حُسْنُها واستكمَلَت بهاءَها.\n\n﴿وَٱزَّيَّنَتۡ﴾: وتَزَيَّنَتْ بأصنافِ النباتِ وأشكالِه وألوانِه.\n\n﴿وَظَنَّ﴾: أيقنَ.\n\n﴿قَـٰدِرُونَ عَلَيۡهَآ﴾: مُتَمَكِّنون مِن جَنْي ثمارِها والانتفاعِ بها.\n\n﴿أَمۡرُنَا﴾: قضاؤُنا بهَلاكِ ما عليها من النباتِ والزينةِ.\n\n﴿فَجَعَلۡنَـٰهَا حَصِيدࣰا﴾: فجَعَلْنا زَرْعَها كالنَّباتِ المقطوعِ.\n\n﴿كَأَن لَّمۡ تَغۡنَ﴾: كأن لم تَكُنِ الزروعُ قائمةً على ظَهْرِ الأرض.\n\n﴿بِٱلۡأَمۡسِ﴾: في الماضي القريب.\n\n﴿نُفَصِّلُ﴾: نُبَيِّنُ.\n\n﴿ٱلۡـَٔايَـٰتِ﴾: الحُجَجَ والأدلَّةَ الواضحةَ."],[25,25,"﴿دَارِ ٱلسَّلَـٰمِ﴾: الجنةِ.\n\n﴿وَيَهۡدِي﴾: وُيَوفِّقُ.\n\n﴿صِرَ ٰ⁠طࣲ مُّسۡتَقِيمࣲ﴾: الطريقِ الواضحِ، وهو دينُ الإسلامِ."],[26,26,"﴿ٱلۡحُسۡنَىٰ﴾: الجنةُ.\n\n﴿وَزِيَادَةࣱ﴾: النظرُ إلى وجهِ اللهِ الكريمِ في الجنةِ.\n\n﴿وَلَا يَرۡهَقُ﴾: لا يَغْشى ولا يعلوُ.\n\n﴿قَتَرࣱ﴾: غبارٌ فيه سَوادٌ.\n\n﴿ذِلَّةٌ﴾: هَوانٌ وكآبةٌ."],[27,27,"﴿كَسَبُواْ﴾: عَمِلُوا.\n\n﴿مِّنَ ٱللَّهِ﴾: من عذابِه.\n\n﴿مِنۡ عَاصِمࣲ﴾: من مانعٍ.\n\n﴿قِطَعࣰا﴾: أجزاءً."],[28,28,"﴿قِطَعࣰا﴾: الزَمُوا مكانَكم في موقفِ الحسابِ.\n\n﴿أَنتُمۡ وَشُرَكَآؤُكُمۡ﴾: أنتم وآلهتكُم، حتى تَرَوْا ما يُفْعَلُ بكم.\n\n﴿فَزَيَّلۡنَا بَيۡنَهُمۡ﴾: فرَّقْنا بينَ المشركين ومَعْبُوديهم."],[30,30,"﴿تَبۡلُواْ﴾: تَخْتَبِرُ وتَعْلَمُ.\n\n﴿مَّآ أَسۡلَفَتۡ﴾: ما قَدَّمَتْ مِن عَمَلٍ.\n\n﴿وَضَلَّ﴾: ذَهَبَ وبَطَلَ.\n\n﴿يَفۡتَرُونَ﴾: يَعْبُدون مِن آلهةٍ مزعومةٍ."],[31,31,"﴿يُدَبِّرُ ٱلۡأَمۡرَ﴾: يَقْضي أمورَ الدُّنيا والآخرةِ ويُصَرِّفُها وحدَه على أكملِ الوجوهِ."],[32,32,"﴿فَأَنَّىٰ تُصۡرَفُونَ﴾: فكيف تُصْرَفون عن عبادةِ اللهِ إلى عبادةِ غيره؟"],[33,33,"﴿حَقَّتۡ﴾: وجَبَتْ.\n\n﴿كَلِمَتُ رَبِّكَ﴾: حُكْمُه وقضاؤُه.\n\n﴿فَسَقُوٓاْ﴾: خرجُوا عن طاعةِ اللهِ وكفرُوا به."],[34,34,"﴿فَأَنَّىٰ تُؤۡفَكُونَ﴾: فكيف تُصْرَفون عن الحقِّ إلى الباطلِ؟"],[35,35,"﴿يَهۡدِيٓ إِلَى ٱلۡحَقِّ﴾: يُرْشِدُ إليه.\n\n﴿يَهۡدِي لِلۡحَقِّ﴾: يُرْشِدُ ويُوَفِّقُ إليه.\n\n﴿لَّا يَهِدِّيٓ﴾: لا يهتدي بنفسه."],[36,36,"﴿ظَنًّا﴾: تَخْمينًا وتوهُّمًا."],[37,37,"﴿تَصۡدِيقَ ٱلَّذِي بَيۡنَ يَدَيۡهِ﴾: مُصَدِّقًا للكتبِ التي أنزلها اللهُ على أنبيائِه.\n\n﴿وَتَفۡصِيلَ ٱلۡكِتَـٰبِ﴾: ومُفَصِّلًا لما شَرَعَه اللهُ فيه من العقائِد والأحكامِ."],[38,38,"﴿وَٱدۡعُواْ مَنِ ٱسۡتَطَعۡتُم﴾: واستَعِينُوا بمَن أمْكَنَكم الاستعانةُ به."],[39,39,"﴿كَذَّبُواْ﴾: سارَعُوا إلى التكذيبِ.\n\n﴿بِمَا لَمۡ يُحِيطُواْ بِعِلۡمِهِۦ﴾: أي: بالقرآنِ، قبل أن يُدْرِكُوا ما اشتملَ عليه.\n\n﴿وَلَمَّا يَأۡتِهِمۡ تَأۡوِيلُهُۥ﴾: ولَمّا يأتِهم عاقبةُ ما تَوَعَّدَهم اللهُ به في القرآنِ."],[42,42,"﴿ٱلصُّمَّ﴾: الذين لا ينتفِعُون بسماعِ القرآنِ، ولا يَقْبَلُون ما فيه."],[43,43,"﴿يَنظُرُ إِلَيۡكَ﴾: يعايِنُ دلائلَ نبوَّتِك الصادقةِ، فلا ينتفعُ بها."],[45,45,"﴿لَّمۡ يَلۡبَثُوٓاْ﴾: لم يَمْكُثوا في الدنيا.\n\n﴿يَتَعَارَفُونَ بَيۡنَهُمۡ﴾: يَعْرِفُ بعضُهم بعضًا كحالِهم في الدنيا."],[46,46,"﴿أَوۡ نَتَوَفَّيَنَّكَ﴾: أي: قبلَ تعذيبِهم.\n\n﴿شَهِيدٌ عَلَىٰ مَا يَفۡعَلُونَ﴾: مُطَّلِعٌ على أعمالِهم، ومُجازِيهم عليها."],[47,47,"﴿جَآءَ رَسُولُهُمۡ﴾: في الدنيا، وبَلَّغَهم فكذَّبُوه، أو في الآخرةِ للشهادةِ عليهم.\n\n﴿بِٱلۡقِسۡطِ﴾: بالعَدْلِ."],[48,48,"﴿هَـٰذَا ٱلۡوَعۡدُ﴾: قيامُ الساعةِ والعذابُ الذي تُخَوِّفنا به."],[49,49,"﴿أَجَلٌ﴾: مدةٌ معلومةٌ لانقضاءِ آجالِهم.\n\n﴿فَلَا يَسۡتَـٔۡخِرُونَ﴾: لا يتأخَّرُون عنه.\n\n﴿وَلَا يَسۡتَقۡدِمُونَ﴾: لا يتقدَّمُون عليه."],[50,50,"﴿أَرَءَيۡتُمۡ﴾: أخْبِرُوني.\n\n﴿بَيَـٰتًا﴾: ليلًا.\n\n﴿مَّاذَا يَسۡتَعۡجِلُ مِنۡهُ﴾: أيُّ شيءٍ من أنواعِ العذابِ يَسْتعجلُونه؟"],[51,51,"﴿ءَآلۡـَٔـٰنَ﴾: أتؤمنون بالعذابِ حين لا ينفعُكم الإيمانُ؟"],[52,52,"﴿عَذَابَ ٱلۡخُلۡدِ﴾: الدائمَ الذي لا ينقطعُ، وهوجَهَنَّمُ."],[53,53,"﴿وَيَسۡتَنۢبِـُٔونَكَ﴾: ويستخبِرُك المشركون عن العذابِ.\n\n﴿إِي وَرَبِّيٓ﴾: نَعَمْ وربِّي.\n\n﴿وَمَآ أَنتُم بِمُعۡجِزِينَ﴾: بفائتين من عذابِ اللهِ بالهَرَبِ."],[54,54,"﴿ظَلَمَتۡ﴾: أشرَكَتْ وكَفَرَتْ.\n\n﴿لَٱفۡتَدَتۡ بِهِۦ﴾: لَجَعَلَتْه فِدْيَةً لها من عذابِ الآخرةِ.\n\n﴿وَأَسَرُّواْ ٱلنَّدَامَةَ﴾: أخْفَوا الغَمَّ والحَسْرَةَ.\n\n﴿بِٱلۡقِسۡطِ﴾: بالعَدْلِ."],[57,57,"﴿مَّوۡعِظَةࣱ﴾: هو القرآنُ العظيمُ."],[58,58,"﴿بِفَضۡلِ ٱللَّهِ﴾: الذي تَفَضَّلَ به عليكم، وهو الإسلامُ والإيمانُ.\n\n﴿وَبِرَحۡمَتِهِۦ﴾: التي رَحِمَكم بها، وهي إنزالُ القرآنِ."],[59,59,"﴿أَرَءَيۡتُم﴾: أخْبِروني.\n\n﴿مَّآ أَنزَلَ ٱللَّهُ﴾: ما خَلَقه اللهُ لأجلِ نَفْعِكم.\n\n﴿أَمۡ عَلَى ٱللَّهِ تَفۡتَرُونَ﴾: تَكْذِبُون بنسبةِ التحريمِ والتحليلِ إليه."],[60,60,"﴿وَمَا ظَنُّ ٱلَّذِينَ يَفۡتَرُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَ﴾: أيُّ شيءٍ ظَنُّهم، وما يُصْنَعُ بهم فيه؟"],[61,61,"﴿فِي شَأۡنࣲ﴾: في أمْرٍمن أمورِك.\n\n﴿شُهُودًا﴾: رُقَباءَ مُطَّلِعِين عليه.\n\n﴿تُفِيضُونَ فِيهِ﴾: تَشْرَعُون فيه وتَعْمَلُونه.\n\n﴿وَمَا يَعۡزُبُ﴾: ما يَغِيبُ ولا يَبْعُدُ.\n\n﴿مِّثۡقَالِ ذَرَّةࣲ﴾: وزنِ أصغرِ نملةٍ.\n\n﴿كِتَـٰبࣲ مُّبِينٍ﴾: واضحٍ، وهو اللَّوحُ المحفوظُ."],[62,62,"﴿وَلَا هُمۡ يَحۡزَنُونَ﴾: على ما فاتهم من حُظوظِ الدُّنيا."],[64,64,"﴿ٱلۡبُشۡرَىٰ﴾: البِشارةُ بما يَسُرُّهم.\n\n﴿لَا تَبۡدِيلَ لِكَلِمَـٰتِ ٱللَّهِ﴾: لا إخلافَ لوَعْدِ اللهِ."],[65,65,"﴿ٱلۡعِزَّةَ لِلَّهِ جَمِيعًا﴾: الغَلَبَةَ، والقوةَ والقدرةَ التامةَ له تعالى."],[66,66,"﴿ٱلظَّنَّ﴾: الشَّكَّ.\n\n﴿يَخۡرُصُونَ﴾: يَكْذِبُون فيما يَنْسُبونَه إلى اللهِ."],[67,67,"﴿مُبۡصِرًا﴾: مُضِيئًا يُبْصِرُ فيه الناسُ.\n\n﴿لَـَٔايَـٰتࣲ﴾: دَلالاتٍ وحججًا."],[68,68,"﴿سُبۡحَـٰنَهُۥ﴾: تَنْزِيهًا له عَمّا نَسَبُوه إليه.\n\n﴿إِنۡ عِندَكُم﴾: ليس لَدَيكم.\n\n﴿سُلۡطَـٰنِۭ﴾: حُجَّةٍ وبُرهانٍ."],[70,70,"﴿مَرۡجِعُهُمۡ﴾: مَصِيرُهم."],[71,71,"﴿كَبُرَ عَلَيۡكُم﴾: عَظُمَ وثَقُلَ عليكم.\n\n﴿مَّقَامِي﴾: إقامتي بينكم.\n\n﴿وَتَذۡكِيرِي﴾: ووَعْظِي إياكم.\n\n﴿بِـَٔايَـٰتِ ٱللَّهِ﴾: بحُجَجِه وبَراهينِه.\n\n﴿فَعَلَى ٱللَّهِ تَوَكَّلۡتُ﴾: اعتمَدْتُ وفوَّضْتُ أمري إليه.\n\n﴿فَأَجۡمِعُوٓاْ أَمۡرَكُمۡ﴾: اكتُمُوه واعزِمُوا عليه.\n\n﴿وَشُرَكَآءَكُمۡ﴾: وادْعُوا آلهتَكم؛ لنُصْرَتِكم.\n\n﴿غُمَّةࣰ﴾: مُسْتَتِرًا خَفِيًّا.\n\n﴿ٱقۡضُوٓاْ إِلَيَّ﴾: افعَلُوا ما تُريدون بي من العقوبةِ.\n\n﴿وَلَا تُنظِرُونِ﴾: ولا تُمهِلُوني."],[72,72,"﴿تَوَلَّيۡتُمۡ﴾: أعْرَضْتُم عن الإيمان."],[73,73,"﴿ٱلۡفُلۡكِ﴾: السَّفينةِ.\n\n﴿خَلَـٰٓئِفَ﴾: أي: يَخْلُفُون الذين هَلَكُوا بالغَرَقِ."],[74,74,"﴿بِٱلۡبَيِّنَـٰتِ﴾: بالمعجزاتِ الدالَّةِ على صِدْقِهم.\n\n﴿نَطۡبَعُ﴾: نَخْتِمُ.\n\n﴿ٱلۡمُعۡتَدِينَ﴾: المتجاوِزين حُدودَ اللهِ."],[75,75,"﴿وَمَلَإِيْهِۦ﴾: أشرافِ قومِه."],[76,76,"﴿ٱلۡحَقُّ﴾: المعجزاتُ التي أظْهرها موسى عليه السلام."],[78,78,"﴿لِتَلۡفِتَنَا﴾: لتَصْرِفَنا.\n\n﴿ٱلۡكِبۡرِيَآءُ﴾: المُلْكُ والسُّلْطانُ.\n\n﴿ٱلۡأَرۡضِ﴾: أرضِ مصرَ."],[79,79,"﴿عَلِيمࣲ﴾: مُتْقِنٍ للسِّحْرِ."],[82,82,"﴿وَيُحِقُّ ٱللَّهُ ٱلۡحَقَّ﴾: يُثَبِّتُه ويُظْهِره.\n\n﴿بِكَلِمَـٰتِهِۦ﴾: بقضائِه وأمْرِه."],[83,83,"﴿يَفۡتِنَهُمۡ﴾: يُعَذِّبَهم؛ ليَحْمِلَهم على الرجوعِ عن الإيمان.\n\n﴿لَعَالࣲ﴾: متكبِّرٌ متطاولٌ.\n\n﴿ٱلۡمُسۡرِفِينَ﴾: المتجاوِزِين الحَدَّ في الكفرِ والفسادِ."],[85,85,"﴿فِتۡنَةࣰ﴾: موضعَ ابتلاءٍ واختبارٍ."],[87,87,"﴿تَبَوَّءَا﴾: اتَّخِذا.\n\n﴿وَٱجۡعَلُواْ بُيُوتَكُمۡ﴾: أي: اجعَلُوها مساجدَ تُصَلُّون فيها عند الخوفِ."],[88,88,"﴿ٱطۡمِسۡ عَلَىٰٓ أَمۡوَ ٰ⁠لِهِمۡ﴾: أهْلِكْها وأتْلِفْها.\n\n﴿وَٱشۡدُدۡ عَلَىٰ قُلُوبِهِمۡ﴾: اخْتِمْ عليها."],[90,90,"﴿وَجَـٰوَزۡنَا بِبَنِيٓ إِسۡرَ ٰ⁠ٓءِيلَ ٱلۡبَحۡرَ﴾: قَطَعْناه بهم حتى تَرَكُوه وراءَهم.\n\n﴿فَأَتۡبَعَهُمۡ﴾: لَحِقَهم.\n\n﴿بَغۡيࣰا وَعَدۡوًا﴾: ظُلْمًا واعتداءً.\n\n﴿أَدۡرَكَهُ ٱلۡغَرَقُ﴾: أحاطَ به، وقَرُبَ هَلاكُه."],[91,91,"﴿ءَآلۡـَٔـٰنَ﴾: آلآن تُؤْمِنُ حين نَزَلَ بك الموتُ؟"],[92,92,"﴿نُنَجِّيكَ﴾: نَجْعَلُكَ على مُرْتفَعٍ من الأرضِ.\n\n﴿بِبَدَنِكَ﴾: بجَسَدِك الذي لا رُوحَ فيه.\n\n﴿خَلۡفَكَ﴾: بَعْدَك من الناسِ.\n\n﴿ءَايَةࣰ﴾: عِبرةً يعتبرون بك."],[93,93,"﴿بَوَّأۡنَا﴾: أنْزَلْنا وأسْكَنّا.\n\n﴿مُبَوَّأَ صِدۡقࣲ﴾: مَنزلًا كريمًا مختارًا.\n\n﴿يَقۡضِي﴾: يَحْكُمُ."],[94,94,"﴿ٱلۡكِتَـٰبَ﴾: التوراةَ والإنجيلَ.\n\n﴿ٱلۡمُمۡتَرِينَ﴾: الشاكِّين."],[95,95,"﴿بِـَٔايَـٰتِ ٱللَّهِ﴾: بحُجَجِه وأدِلَّتِه."],[96,96,"﴿حَقَّتۡ﴾: وجَبَتْ."],[97,97,"﴿ءَايَةٍ﴾: عِبْرةٍ وموعظةٍ."],[98,98,"﴿فَلَوۡلَا﴾: فهَلّا.\n\n﴿ٱلۡخِزۡيِ﴾: الذُّلِّ والهَوانِ.\n\n﴿إِلَىٰ حِينࣲ﴾: إلى وقتِ انقضاءِ آجالِهم."],[100,100,"﴿ٱلرِّجۡسَ﴾: عذابَ اللهِ وغَضَبَه."],[101,101,"﴿ٱنظُرُواْ﴾: تَفَكَّرُوا واعتَبِرُوا.\n\n﴿ٱلۡـَٔايَـٰتُ﴾: الدلائلُ والعِبَرُ.\n\n﴿وَٱلنُّذُرُ﴾: جَمْعُ نَذِير، وهم: الرسُلُ."],[102,102,"﴿مِثۡلَ أَيَّامِ ٱلَّذِينَ خَلَوۡاْ مِن قَبۡلِهِمۡ﴾: مثلَ ما حَلَّ بالأممِ السابقةِ من العذابِ."],[104,104,"﴿يَتَوَفَّىٰكُمۡ﴾: يُمِيتُكم."],[105,105,"﴿أَقِمۡ وَجۡهَكَ لِلدِّينِ﴾: استقِمْ على دينِ الإسلامِ مُخْلِصًا لله في عبادتِك وعَمَلِك.\n\n﴿حَنِيفࣰا﴾: مائلًا عن الأديانِ الباطلةِ."],[106,106,"﴿ٱلظَّـٰلِمِينَ﴾: المُشْركين."],[107,107,"﴿بِضُرࣲّ﴾: بشدَّةٍ أو بلاءٍ.\n\n﴿بِخَيۡرࣲ﴾: برَخاءٍ أو نِعْمةٍ."],[108,108,"﴿ٱلۡحَقُّ﴾: القرآنُ العظيمُ.\n\n﴿بِوَكِيلࣲ﴾: بحَفيظٍ أحفَظُ أمورَكم."]]);
QTF("gharib",11,[[1,1,"﴿أُحۡكِمَتۡ ءَايَـٰتُهُۥ﴾: جُعِلَتْ مُحْكَمَةً مُتقنةً، لا نَقْصَ فيها ولا عَيْبَ.\n\n﴿فُصِّلَتۡ﴾: بُيِّنَتْ فيها الأحكامُ والقِصصُ والمواعظُ."],[3,3,"﴿مَّتَـٰعًا حَسَنًا﴾: بطِيبِ الحياةِ وسَعَةِ الرِّزقِ.\n\n﴿إِلَىٰٓ أَجَلࣲ مُّسَمࣰّى﴾: إلى وقتِ انقضاءِ آجالِكم.\n\n﴿فَضۡلَهُۥ﴾: جزاءَ فَضْلِه في الدُّنيا والآخرةِ.\n\n﴿تَوَلَّوۡاْ﴾: تُعْرِضُوا."],[5,5,"﴿يَثۡنُونَ صُدُورَهُمۡ﴾: يَطْوُونها على الكفرِ والعَداوةِ.\n\n﴿يَسۡتَغۡشُونَ ثِيَابَهُمۡ﴾: يَتَغَطَّوْن بها."],[6,6,"﴿دَآبَّةࣲ﴾: كلُّ حَيَوانٍ يَمْشي -على هيئتهِ- على الأرضِ.\n\n﴿مُسۡتَقَرَّهَا﴾: مكانَ استقرارِها في حياتِها وبعدَ مَماتِها.\n\n﴿وَمُسۡتَوۡدَعَهَا﴾: موضعَ استيداعِها بعد موتِها.\n\n﴿كِتَـٰبࣲ مُّبِينࣲ﴾: واضحٍ، وهو اللَّوحُ المحفوظُ."],[7,7,"﴿عَرۡشُهُۥ﴾: العرشُ: سريرُ المُلْكِ الذي استوى عليه الرحمنُ، وتحمِلُه الملائكةُ، وهو أعظمُ المخلوقاتِ، وهو سَقْفُ الجنَّةِ.\n\n﴿لِيَبۡلُوَكُمۡ﴾: لِيَخْتَبِرَكم.\n\n﴿أَحۡسَنُ عَمَلࣰا﴾: أعْمَلُ بطاعةِ اللهِ وأَوْرَعُ عن مَحارمِه."],[8,8,"﴿أُمَّةࣲ مَّعۡدُودَةࣲ﴾: وقتٍ معلومٍ.\n\n﴿وَحَاقَ﴾: أحاطَ."],[9,9,"﴿مِنَّا رَحۡمَةࣰ﴾: نِعْمةً مِن نِعَمِنا الكثيرةِ.\n\n﴿نَزَعۡنَـٰهَا مِنۡهُ﴾: سَلَبْناها منه.\n\n﴿لَيَـُٔوسࣱ﴾: شديدُ اليأسِ من رحمةِ اللهِ.\n\n﴿كَفُورࣱ﴾: كثيرُ الجُحودِ للنِّعَمِ."],[10,10,"﴿ضَرَّآءَ مَسَّتۡهُ﴾: بَلْوى أصابَتْه.\n\n﴿ٱلسَّيِّـَٔاتُ﴾: المصائبُ والشَّدائدُ.\n\n﴿لَفَرِحࣱ﴾: بَطِرٌ بالنِّعْمةِ مُغْتَرٌّ بها.\n\n﴿فَخُورٌ﴾: كثيرُ التعاظُمِ على الناسِ."],[12,12,"﴿بَعۡضَ مَا يُوحَىٰٓ إِلَيۡكَ﴾: ما يَشُقُّ على المشركين سماعُه، ويُثيرُ غضَبَهم.\n\n﴿أَن يَقُولُواْ﴾: خشيةَ أن يقولوا على وجهِ التكذيبِ والاستهزاءِ.\n\n﴿لَوۡلَآ﴾: هَلّا.\n\n﴿وَكِيلٌ﴾: حفيظٌ يُدَبِّرُ جميعَ شؤونِ خَلْقهِ."],[13,13,"﴿ٱفۡتَرَىٰهُ﴾: أتى به مِن عندِ نفسِه.\n\n﴿مُفۡتَرَيَـٰتࣲ﴾: مُخْتَلَقاتٍ من عندِ أنفسِكم.\n\n﴿وَٱدۡعُواْ مَنِ ٱسۡتَطَعۡتُم﴾: واستعينُوا بمَن أمكنكم الاستعانةُ به."],[15,15,"﴿نُوَفِّ إِلَيۡهِمۡ أَعۡمَـٰلَهُمۡ﴾: نُعْطِهم جزاءَ أعمالِهم في الدنيا.\n\n﴿لَا يُبۡخَسُونَ﴾: لا يُنْقَصُون شيئًا ممّا قُسِمَ لهم."],[16,16,"﴿وَحَبِطَ﴾: بَطَلَ في الآخرةِ نَفْعُ ما عَمِلوه."],[17,17,"﴿بَيِّنَةࣲ مِّن رَّبِّهِۦ﴾: حُجَّةٍ وبَصيرةٍ من اللهِ.\n\n﴿وَيَتۡلُوهُ﴾: يَتْبَعُه ويُقَوِّيه.\n\n﴿شَاهِدࣱ مِّنۡهُ﴾: يَشْهَدُ على كَوْنِ القرآنِ من عندِ اللهِ.\n\n﴿كِتَـٰبُ مُوسَىٰٓ﴾: التوراةُ.\n\n﴿إِمَامࣰا﴾: يُؤتَمُّ به في الدِّين، ويُقْتدى به.\n\n﴿وَرَحۡمَةً﴾: نِعْمَةً عظيمةً من اللهِ.\n\n﴿ٱلۡأَحۡزَابِ﴾: الكفارِ الذين جَمَعهم تكذيبُ رسولِ اللهِ عليه الصلاة والسلام، وكَيْدُهم له.\n\n﴿مِرۡيَةࣲ مِّنۡهُ﴾: شَكٍّ من تنزيلِ القرآنِ من اللهِ."],[18,18,"﴿يُعۡرَضُونَ عَلَىٰ رَبِّهِمۡ﴾: سيُعْرَضون على اللهِ في موقفِ الحسابِ.\n\n﴿ٱلۡأَشۡهَـٰدُ﴾: جَمْعُ شاهِدٍ، وهم: الملائكةُ والأنبياءُ والمؤمنون.\n\n﴿لَعۡنَةُ ٱللَّهِ﴾: غَضَبُه وسُخْطُه."],[19,19,"﴿يَصُدُّونَ﴾: يَمْنَعُون الناسَ.\n\n﴿سَبِيلِ ٱللَّهِ﴾: الطريقِ المُوصِلَةِ إليه، وهي دينُ الإسلامِ.\n\n﴿وَيَبۡغُونَهَا عِوَجࣰا﴾: ويُريدون أن تكونَ سبيلُ اللهِ مائلةً وفْقَ أهوائِهم."],[20,20,"﴿مُعۡجِزِينَ﴾: فائتين من عذابِ اللهِ بالهَرَبِ.\n\n﴿أَوۡلِيَآءَ﴾: أنصارٍ."],[21,21,"﴿وَضَلَّ﴾: ذَهَبَ.\n\n﴿يَفۡتَرُونَ﴾: يَكْذِبُون على اللهِ من ادِّعاءِ الشفعاءِ، الذين يَتَوَهَّمُون شفاعتَهم."],[22,22,"﴿لَا جَرَمَ﴾: حقًا، أو لا مَحالةَ."],[23,23,"﴿وَأَخۡبَتُوٓاْ إِلَىٰ رَبِّهِمۡ﴾: أنابُوا إليه وخَضَعُوا له."],[24,24,"﴿ٱلۡفَرِيقَيۡنِ﴾: فريقَي الكُفْرِ والإيمانِ."],[25,25,"﴿نَذِيرࣱ مُّبِينٌ﴾: بَيِّنُ الإنذارِ بما أُرْسِلْتُ به."],[27,27,"﴿ٱلۡمَلَأُ﴾: الأشرافُ والسّادةُ.\n\n﴿أَرَاذِلُنَا﴾: سَفَلَةُ الناسِ منا وفُقَراؤُنا.\n\n﴿بَادِيَ ٱلرَّأۡيِ﴾: أي: اتّبعُوك من غيرِ تفكيرٍ ولا رَوِيَّةٍ."],[28,28,"﴿أَرَءَيۡتُمۡ﴾: أخْبِرُوني.\n\n﴿بَيِّنَةࣲ﴾: حُجَّةٍ وبرهانٍ، تَشْهَدُ بالنبوَّةِ.\n\n﴿وَءَاتَىٰنِي رَحۡمَةࣰ مِّنۡ عِندِهِۦ﴾: وهي الرِّسالةُ.\n\n﴿فَعُمِّيَتۡ﴾: أُخْفِيَتْ."],[31,31,"﴿خَزَآئِنُ ٱللَّهِ﴾: خزائنُ رزقِه، وما لا يَصِلُ إليه عِلْمُ الناسِ.\n\n﴿تَزۡدَرِيٓ أَعۡيُنُكُمۡ﴾: تَسْتَحْقِرُهم وتَسْتهينُ بهم.\n\n﴿خَيۡرًا﴾: توفيقًا وإيمانًا وأجرًا."],[33,33,"﴿بِمُعۡجِزِينَ﴾: بفائتين من عذابِ اللهِ بالهَرَبِ."],[34,34,"﴿يُغۡوِيَكُمۡ﴾: يُضِلَّكم."],[35,35,"﴿فَعَلَيَّ إِجۡرَامِي﴾: فعَلَيَّ إثمي وعُقوبتُه.\n\n﴿مِّمَّا تُجۡرِمُونَ﴾: ممّا تَقْترفونه من الكفرِ والتكذيب."],[36,36,"﴿فَلَا تَبۡتَئِسۡ﴾: لا تَحْزَنْ."],[37,37,"﴿ٱلۡفُلۡكَ﴾: السَّفينةَ.\n\n﴿بِأَعۡيُنِنَا﴾: بمَرْأى مِنّا وأنت في حِفْظِنا.\n\n﴿وَوَحۡيِنَا﴾: وبأَمْرِنا لك ومَعُونَتِنا.\n\n﴿وَلَا تُخَـٰطِبۡنِي فِي ٱلَّذِينَ ظَلَمُوٓاْ﴾: لا تَطْلُبْ مني إمهالَهم."],[39,39,"﴿يُخۡزِيهِ﴾: يُهينُه ويُذِلُّه.\n\n﴿وَيَحِلُّ عَلَيۡهِ﴾: ويَنْزِلُ به.\n\n﴿عَذَابࣱ مُّقِيمٌ﴾: دائمٌ لا ينقطِعُ، وهو النارُ."],[40,40,"﴿وَفَارَ ٱلتَّنُّورُ﴾: ونَبَعَ الماءُ بقوَّةٍ من المكانِ الذي يُخْبَزُ فيه.\n\n﴿مِن كُلࣲّ زَوۡجَيۡنِ ٱثۡنَيۡنِ﴾: من كلِّ نوعٍ من أنواعِ الحيَواناتِ ذكرًا وأنثى.\n\n﴿إِلَّا مَن سَبَقَ عَلَيۡهِ ٱلۡقَوۡلُ﴾: إلّا مَن تَقَدَّمَ حُكْمُ اللهِ عليه بأنه من المُغْرَقين."],[41,41,"﴿مَجۡرٜىٰهَا﴾: جَرْيُها على وجهِ الماء.\n\n﴿وَمُرۡسَىٰهَآ﴾: ومُنْتَهى سَيْرِها."],[42,42,"﴿مَعۡزِلࣲ﴾: مكانٍ عَزَلَ نفسَه فيه عن المؤمنين."],[43,43,"﴿سَـَٔاوِيٓ﴾: سألتجِئُ وأتحَصَّنُ.\n\n﴿لَا عَاصِمَ﴾: لا مانعَ ولا حافِظَ."],[44,44,"﴿أَقۡلِعِي﴾: أمْسِكِي عن إنزالِ المطرِ.\n\n﴿وَغِيضَ ٱلۡمَآءُ﴾: نَقَصَ وغارَ في الأرضِ.\n\n﴿وَقُضِيَ ٱلۡأَمۡرُ﴾: تَمَّ حُكْمُ اللهِ بإهلاكِ قومِ نوحٍ.\n\n﴿وَٱسۡتَوَتۡ عَلَى ٱلۡجُودِيِّ﴾: استقرَّتِ السفينةُ على جَبَلِ الجوديِّ.\n\n﴿بُعۡدࣰا﴾: هَلاكًا."],[47,47,"﴿أَعُوذُ بِكَ﴾: أعتصِمُ وأستجيرُ بك."],[48,48,"﴿بِسَلَـٰمࣲ مِّنَّا﴾: بأمانٍ وسَلامةٍ منّا.\n\n﴿وَبَرَكَـٰتٍ عَلَيۡكَ﴾: خيراتٍ ونِعَمٍ دائمةٍ عليك.\n\n﴿وَأُمَمࣱ سَنُمَتِّعُهُمۡ﴾: وهم الكفارُ."],[50,50,"﴿عَادٍ﴾: قومِ هودٍ عليه السلام، وهم قبيلةٌ من العَرَبِ.\n\n﴿مُفۡتَرُونَ﴾: كاذِبُون في إشراكِكم باللهِ."],[51,51,"﴿فَطَرَنِيٓ﴾: خَلَقَني."],[52,52,"﴿ٱلسَّمَآءَ﴾: المطرَ.\n\n﴿مِّدۡرَارࣰا﴾: كثيرًا مُتتابعًا من غيرِ إضْرارٍ.\n\n﴿وَلَا تَتَوَلَّوۡاْ﴾: لا تُعْرِضُوا عَمّا دَعَوْتُكم إليه."],[53,53,"﴿بِبَيِّنَةࣲ﴾: بحُجَّةٍ واضحةٍ.\n\n﴿عَن قَوۡلِكَ﴾: من أجلِ قولِك."],[54,54,"﴿إِن نَّقُولُ﴾: ما نقولُ.\n\n﴿ٱعۡتَرَىٰكَ﴾: أصابَكَ.\n\n﴿بِسُوٓءࣲ﴾: بجُنونٍ؛ لنَهْيِك عن عبادتِها."],[55,55,"﴿فَكِيدُونِي﴾: فاجتهِدُوا في إلحاقِ الضَّرَرِ بي.\n\n﴿لَا تُنظِرُونِ﴾: لا تُمْهِلُوني بما تُريدون كيدَه."],[56,56,"﴿تَوَكَّلۡتُ عَلَى ٱللَّهِ﴾: فَوَّضْتُ أمري إليه، واعتمَدْتُ عليه.\n\n﴿دَآبَّةٍ﴾: كلُّ حَيَوانٍ يَمْشِي -على هيئتِه- على الأرضِ.\n\n﴿ءَاخِذُۢ بِنَاصِيَتِهَآ﴾: مالِكُها وقادرٌ عليها."],[57,57,"﴿وَيَسۡتَخۡلِفُ رَبِّي قَوۡمًا غَيۡرَكُمۡ﴾: يأتي بقومٍ آخَرين بَعْدَكم.\n\n﴿حَفِيظࣱ﴾: رقيبٌ مُهَيْمِنٌ."],[58,58,"﴿جَآءَ أَمۡرُنَا﴾: أي: بهَلاكِ قومِ هودٍ.\n\n﴿غَلِيظࣲ﴾: شديدٍ، وهو الرِّيحُ الباردةُ التي أُهلِكَتْ بها عادٌ."],[59,59,"﴿جَبَّارٍ﴾: متكبِّرٍ.\n\n﴿عَنِيدࣲ﴾: لا يَقْبَلُ الحقَّ ولا يَتْبَعُه."],[60,60,"﴿لَعۡنَةࣰ﴾: سُخْطًا من اللهِ، وبُعْدًا من رحمتِه.\n\n﴿بُعۡدࣰا﴾: هَلاكًا."],[61,61,"﴿ثَمُودَ﴾: قومِ صالحٍ عليه السلامُ، وهم قبيلةٌ من العَرَبِ.\n\n﴿أَنشَأَكُم مِّنَ ٱلۡأَرۡضِ﴾: ابتدأ خَلْقَكم منها.\n\n﴿وَٱسۡتَعۡمَرَكُمۡ فِيهَا﴾: جَعَلَكم عُمّارَها وسكّانَها."],[62,62,"﴿مَرۡجُوࣰّا﴾: نرجو أن تكونَ فينا سَيِّدًا مُطاعًا.\n\n﴿مُرِيبࣲ﴾: مُوقِعٍ في القلقِ وعَدَمِ الاطمئنانِ."],[63,63,"﴿أَرَءَيۡتُمۡ﴾: أخْبِروني.\n\n﴿بَيِّنَةࣲ مِّن رَّبِّي﴾: حُجَّةٍ وبُرْهانٍ منه.\n\n﴿رَحۡمَةࣰ﴾: أي: النبوَّةَ والحِكْمةَ.\n\n﴿تَخۡسِيرࣲ﴾: إيقاعٍ في الخُسْرانِ وإبعادٍ عن الخير."],[64,64,"﴿ءَايَةࣰ﴾: علامةً دالَّةً على صِدْقي.\n\n﴿فَذَرُوهَا﴾: فاترُكوها.\n\n﴿بِسُوٓءࣲ﴾: بأيِّ أذى."],[65,65,"﴿فَعَقَرُوهَا﴾: فنَحَرُوا الناقةَ.\n\n﴿تَمَتَّعُواْ فِي دَارِكُمۡ﴾: استَمْتِعُوا بالعيشِ في بلدِكم."],[66,66,"﴿جَآءَ أَمۡرُنَا﴾: أي: بهَلاكِ قومِ صالحٍ.\n\n﴿خِزۡيِ﴾: ذُلِّ ومَهانَةِ."],[67,67,"﴿ٱلصَّيۡحَةُ﴾: الصوتُ الشديدُ المُهلِكُ.\n\n﴿جَـٰثِمِينَ﴾: لاصِقِين بالأرضِ على رُكَبهِم ووُجوهِهم لا حَراكَ بهم."],[68,68,"﴿كَأَن لَّمۡ يَغۡنَوۡاْ فِيهَآ﴾: كأنّ قومَ صالحٍ لم يُقيموا في ديارِهم ويَتمتَّعُوا فيها.\n\n﴿بُعۡدࣰا﴾: هَلاكًا."],[69,69,"﴿رُسُلُنَآ﴾: الملائكةُ.\n\n﴿بِٱلۡبُشۡرَىٰ﴾: ببِشارَتِه بالولَدِ.\n\n﴿حَنِيذࣲ﴾: مَشْويٍّ في النارِ، أو على حِجارةٍ مُحمّاةٍ بها."],[70,70,"﴿نَكِرَهُمۡ﴾: أنكرَ عَدَمَ أكلِهم.\n\n﴿وَأَوۡجَسَ مِنۡهُمۡ خِيفَةࣰ﴾: أحَسَّ في نفسِه خوْفًا منهم."],[72,72,"﴿يَـٰوَيۡلَتَىٰٓ﴾: كلمةٌ أرادَتْ بها التعجُّبَ.\n\n﴿بَعۡلِي﴾: زوجي.\n\n﴿شَيۡخًا﴾: كبيرًا في السِّن."],[73,73,"﴿حَمِيدࣱ﴾: محمودٌ في صفاتِه وأفعالِه.\n\n﴿مَّجِيدࣱ﴾: ذو شَرَفٍ وكَرَمٍ، أو كثيرُ الخيرِ والإحسانِ."],[74,74,"﴿ٱلرَّوۡعُ﴾: الخوفُ."],[75,75,"﴿لَحَلِيمٌ﴾: صَبُورٌ على الأذى، كثيرُ الصَّفْحِ عَمَّن ناله بمَكْروهٍ.\n\n﴿أَوَّ ٰ⁠هࣱ﴾: كثيرُ التضرُّعِ إلى اللهِ.\n\n﴿مُّنِيبࣱ﴾: رَجّاعٌ إلى اللهِ في أمورِه كلِّها."],[76,76,"﴿جَآءَ أَمۡرُ رَبِّكَ﴾: أي: بهَلاكِ قومِ لوطٍ."],[77,77,"﴿سِيٓءَ بِهِمۡ﴾: ساءَه حُضورُهم وأحْزَنَه.\n\n﴿وَضَاقَ بِهِمۡ ذَرۡعࣰا﴾: ضَعُفَتْ طاقَتُه عن تَدْبيرِ خَلاصِهم.\n\n﴿عَصِيبࣱ﴾: شديدٌ شَرُّه وبلاؤُه."],[78,78,"﴿يُهۡرَعُونَ﴾: يُسْرِعُون المشيَ إليه؛ لطَلَبِ الفاحشةِ.\n\n﴿هَـٰٓؤُلَآءِ بَنَاتِي﴾: نساؤُكم بناتي فتزوَّجُوهنَّ.\n\n﴿وَلَا تُخۡزُونِ﴾: لا تَفْضَحُوني ولا تُهينوني.\n\n﴿رَّشِيدࣱ﴾: حَسَنُ التقديرِ للأمورِ."],[79,79,"﴿مِنۡ حَقࣲّ﴾: من حاجةٍ أو رغبةٍ."],[80,80,"﴿لَوۡ أَنَّ لِي بِكُمۡ قُوَّةً﴾: لو وجَدْتُ مُعِينًا منكم لَمَنعْتُكم من أضيافي.\n\n﴿أَوۡ ءَاوِيٓ إِلَىٰ رُكۡنࣲ شَدِيدࣲ﴾: أو ألجأُ إلى عشيرةٍ قويَّة تمنعني منكم."],[81,81,"﴿فَأَسۡرِ بِأَهۡلِكَ﴾: فاخرُجْ أنتَ وأهلُك المؤمنون.\n\n﴿بِقِطۡعࣲ مِّنَ ٱلَّيۡلِ﴾: بآخِر الليلِ.\n\n﴿إِلَّا ٱمۡرَأَتَكَ﴾: فلا تَسْرِ بها."],[82,82,"﴿جَآءَ أَمۡرُنَا﴾: أي: بهلاكِ قومِ لوطٍ.\n\n﴿جَعَلۡنَا عَـٰلِيَهَا سَافِلَهَا﴾: جَعَلْنا عاليَ قُراهم سافِلَها فقَلَبْناها عليهم.\n\n﴿وَأَمۡطَرۡنَا﴾: أرْسَلْنا.\n\n﴿سِجِّيلࣲ﴾: من طِينٍ مُتَحَجِّر.\n\n﴿مَّنضُودࣲ﴾: مُتتابعٍ في النزولِ."],[83,83,"﴿مُّسَوَّمَةً عِندَ رَبِّكَ﴾: مُعَلَّمَةً عند الله بعَلامةٍ تميِّزُها."],[84,84,"﴿مَدۡيَنَ﴾: قومِ شُعيبٍ عليه السلام، وهم قبيلةٌ من العربِ.\n\n﴿يَوۡمࣲ مُّحِيطࣲ﴾: لا يَفْلِتُ فيه أحدٌ من العذاب."],[85,85,"﴿أَوۡفُواْ﴾: أتِمُّوا.\n\n﴿بِٱلۡقِسۡطِ﴾: بالعدلِ من غيرِ زيادةٍ ولا نقصٍ.\n\n﴿وَلَا تَبۡخَسُواْ﴾: ولا تَنْقُصُوا.\n\n﴿وَلَا تَعۡثَوۡاْ﴾: ولا تُفْرِطُوا في الفسادِ."],[86,86,"﴿بَقِيَّتُ ٱللَّهِ خَيۡرࣱ لَّكُمۡ﴾: ما أبقى اللهُ لكم من الحَلالِ فيه بَرَكَةٌ وخيرٌ لكم.\n\n﴿بِحَفِيظࣲ﴾: برقيبٍ أُحْصِي أعمالَكم."],[87,87,"﴿ٱلۡحَلِيمُ﴾: العاقلُ المتأنِّي.\n\n﴿ٱلرَّشِيدُ﴾: الحَسَنُ التدبيرِ في المالِ."],[88,88,"﴿بَيِّنَةࣲ﴾: حُجَّةٍ واضحةٍ.\n\n﴿حَسَنࣰا﴾: واسعًا حلالًا.\n\n﴿وَمَا تَوۡفِيقِيٓ﴾: وما هدايتي إلى إصابةِ الحقِّ والإصلاحِ.\n\n﴿تَوَكَّلۡتُ﴾: اعتمَدْتُ وفوَّضْتُ أمري.\n\n﴿وَإِلَيۡهِ أُنِيبُ﴾: أرْجِعُ في كلِّ أموري."],[89,89,"﴿لَا يَجۡرِمَنَّكُمۡ شِقَاقِيٓ﴾: لا تَحْمِلَنَّكم مُعاداتي.\n\n﴿وَمَا قَوۡمُ لُوطࣲ مِّنكُم بِبَعِيدࣲ﴾: أي: وما إهلاكُهم بزمانٍ ولا مكانٍ بعيدٍ منكم."],[90,90,"﴿وَدُودࣱ﴾: كثيرُ المودَّةِ والمحبَّةِ لِمَن تابَ إليه وأنابَ."],[91,91,"﴿مَا نَفۡقَهُ﴾: لا نَفْهَمُ ولا نُدْرِكُ.\n\n﴿رَهۡطُكَ﴾: عشيرتُك الأقربون.\n\n﴿لَرَجَمۡنَـٰكَ﴾: لَقَتَلْناك رَجْمًا بالحجارةِ."],[92,92,"﴿وَٱتَّخَذۡتُمُوهُ وَرَآءَكُمۡ ظِهۡرِيًّا﴾: نَبَذْتُم أمرَ اللهِ وراءَ ظُهورِكم، فلم تَمْتثلُوا له.\n\n﴿مُحِيطࣱ﴾: لا يَخْفى عليه شيءٌ من أقوالِكم وأفعالِكم."],[93,93,"﴿عَلَىٰ مَكَانَتِكُمۡ﴾: حالتِكم التي أنتم عليها من الكفر.\n\n﴿يُخۡزِيهِ﴾: يُهينُه ويُذِلُّه.\n\n﴿وَٱرۡتَقِبُوٓاْ﴾: وانتظِرُوا عاقبةَ أمرِكم.\n\n﴿رَقِيبࣱ﴾: مُنتظِرٌ."],[94,94,"﴿جَآءَ أَمۡرُنَا﴾: أي: بهَلاكِ قومِ شُعيبٍ.\n\n﴿ٱلصَّيۡحَةُ﴾: وهي الصوتُ الشديدُ المُهلِكُ.\n\n﴿جَـٰثِمِينَ﴾: لاصِقين بالأرض على رُكَبِهم ووجوهِهم لاحَراكَ بهم."],[95,95,"﴿كَأَن لَّمۡ يَغۡنَوۡاْ فِيهَآ﴾: كأنّ قومَ شعيبٍ لم يُقيموا في ديارهم ويتمتَّعوا فيها.\n\n﴿بُعۡدࣰا﴾: هَلاكًا."],[96,96,"﴿بِـَٔايَـٰتِنَا﴾: بالتوراةِ، وبما أعْطَيْناه من أدلَّةٍ على توحيدِنا.\n\n﴿وَسُلۡطَـٰنࣲ مُّبِينٍ﴾: حُجَّةٍ بينةٍ على صِدْقِه."],[97,97,"﴿وَمَلَإِيْهِۦ﴾: أشرافِ قومهِ وسادتِهم.\n\n﴿بِرَشِيدࣲ﴾: مُصيبٍ للحقِّ وللطريقِ السَّديدِ."],[98,98,"﴿يَقۡدُمُ قَوۡمَهُۥ﴾: يتقدَّمُهم.\n\n﴿فَأَوۡرَدَهُمُ ٱلنَّارَ﴾: فأدخَلَهم فيها.\n\n﴿ٱلۡوِرۡدُ ٱلۡمَوۡرُودُ﴾: المَدْخَلُ الذي يَدْخُلونه، وهو النارُ."],[99,99,"﴿وَأُتۡبِعُواْ﴾: أُلْحِقُوا.\n\n﴿فِي هَـٰذِهِۦ﴾: أي: الدنيا.\n\n﴿لَعۡنَةࣰ﴾: إبعادًا عن اللهِ.\n\n﴿ٱلرِّفۡدُ ٱلۡمَرۡفُودُ﴾: العطاءُ المعطى لهم، وهو لعنةُ الدنيا والآخرةِ."],[100,100,"﴿نَقُصُّهُۥ عَلَيۡكَ﴾: نُخْبِرُك به.\n\n﴿قَآئِمࣱ﴾: له آثارٌ باقية.\n\n﴿وَحَصِيدࣱ﴾: ما لا أثَر له."],[101,101,"﴿فَمَآ أَغۡنَتۡ عَنۡهُمۡ﴾: فما نَفَعَتْهم.\n\n﴿جَآءَ أَمۡرُ رَبِّكَ﴾: أي: بهَلاكِهم.\n\n﴿غَيۡرَ تَتۡبِيبࣲ﴾: غيرَ تَخْسيرٍ وإهلاكٍ."],[103,103,"﴿لَـَٔايَةࣰ﴾: لَعِبْرَةً وعِظةً."],[106,106,"﴿زَفِيرࣱ﴾: إخراجُ النَّفَسِ من الصَّدْرِ؛ من شِدَّةِ الحُزْنِ.\n\n﴿وَشَهِيقٌ﴾: رَدُّ النَّفَسِ إلى الصَّدْرِ مع طولٍ فيه."],[108,108,"﴿غَيۡرَ مَجۡذُوذࣲ﴾: غيرَ مقطوعٍ عنهم."],[109,109,"﴿مِرۡيَةࣲ﴾: شَكٍّ."],[110,110,"﴿ٱلۡكِتَـٰبَ﴾: التوراةَ.\n\n﴿كَلِمَةࣱ سَبَقَتۡ مِن رَّبِّكَ﴾: وهي حُكْمُه بتأخيرِ عذابِ الخَلْقِ إلى يومِ القيامةِ.\n\n﴿مُرِيبࣲ﴾: مُوقِعٍ في القَلَقِ وعدمِ الاطمئنانِ."],[112,112,"﴿وَلَا تَطۡغَوۡاْ﴾: ولا تتجاوَزُوا حدودَ اللهِ."],[113,113,"﴿وَلَا تَرۡكَنُوٓاْ﴾: ولا تَمِيلُوا بمَوَدَّةٍ.\n\n﴿أَوۡلِيَآءَ﴾: أنصارٍ."],[114,114,"﴿وَزُلَفࣰا مِّنَ ٱلَّيۡلِ﴾: جَمْعُ زُلْفَة، أي: ساعاتٍ من أوَّلِه."],[116,116,"﴿فَلَوۡلَا﴾: فهَلّا.\n\n﴿ٱلۡقُرُونِ﴾: جَمْعُ قَرْنٍ، وهم القومُ المقتَرنون في زمانٍ واحدٍ.\n\n﴿أُوْلُواْ بَقِيَّةࣲ﴾: أصحابُ خيرٍ وصلاحٍ.\n\n﴿مَآ أُتۡرِفُواْ فِيهِ﴾: ما مُتِّعُوا فيه من لذّاتِ الدُّنيا ونعيمِها."],[119,119,"﴿وَتَمَّتۡ﴾: وجَبَتْ.\n\n﴿كَلِمَةُ رَبِّكَ﴾: حُكْمُه وقضاؤُه.\n\n﴿ٱلۡجِنَّةِ﴾: الجِنِّ."],[120,120,"﴿نَّقُصُّ عَلَيۡكَ﴾: نُخْبِرُك ونُبيِّنُ لك.\n\n﴿نُثَبِّتُ﴾: نُقَوِّي ونُطَمْئِنُ."],[121,121,"﴿مَكَانَتِكُمۡ﴾: حالتِكم التي أنتم عليها من الكفرِ."],[123,123,"﴿وَلِلَّهِ غَيۡبُ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ﴾: عِلْمُ جميعِ ما هو غائبٌ عن العبادِ فيهما.\n\n﴿وَتَوَكَّلۡ عَلَيۡهِ﴾: اعتمِدْ وفَوِّضْ أمْرَك إليه وحدَه."]]);
QTF("gharib",12,[[1,1,"﴿ٱلۡمُبِينِ﴾: الواضِحِ في معانيه وأحكامِه."],[3,3,"﴿ٱلۡغَـٰفِلِينَ﴾: السّاهِين، أي: لم يَكُنْ لك عِلْمٌ بهذا الإخبارِ."],[4,4,"﴿سَـٰجِدِينَ﴾: أي: سجودَ تَكريمٍ واحترامٍ."],[5,5,"﴿فَيَكِيدُواْ لَكَ﴾: يَحْتالُوا من أجلِ إهلاكِك حَسَدًا.\n\n﴿مُّبِينࣱ﴾: ظاهرُ العداوةِ."],[6,6,"﴿يَجۡتَبِيكَ﴾: يختارُك لأمورٍ عظيمة.\n\n﴿تَأۡوِيلِ ٱلۡأَحَادِيثِ﴾: تفسيرِ الرُّؤى المناميةِ.\n\n﴿وَيُتِمُّ نِعۡمَتَهُۥ عَلَيۡكَ﴾: أي: بالنبوَّةِ والرسالةِ."],[7,7,"﴿ءَايَـٰتࣱ﴾: عِبَرٌ، وعلاماتٌ دالَّةٌ على قدرةِ اللهِ."],[8,8,"﴿عُصۡبَةٌ﴾: جماعةٌ من الرجالِ متناصِرُون.\n\n﴿ضَلَـٰلࣲ مُّبِينٍ﴾: خطأٍ بيِّنٍ في تفضيلِهما علينا."],[9,9,"﴿ٱطۡرَحُوهُ أَرۡضࣰا﴾: ألْقُوه في أرضٍ بعيدةٍ.\n\n﴿يَخۡلُ لَكُمۡ وَجۡهُ أَبِيكُمۡ﴾: يَخْلُصْ لكم حُبُّ أبيكم وإقبالُه عليكم.\n\n﴿مِنۢ بَعۡدِهِۦ﴾: من بعدِ قَتْلِ يوسفَ أو إبعادِه.\n\n﴿صَـٰلِحِينَ﴾: تائبين إلى اللهِ مِن فَعْلَتِكم."],[10,10,"﴿غَيَـٰبَتِ ٱلۡجُبِّ﴾: جوفِ البئرِ وأسفلِه حيثُ يَغيبُ خبرُه.\n\n﴿ٱلسَّيَّارَةِ﴾: المسافرين المارِّينَ بالبئرِ."],[12,12,"﴿يَرۡتَعۡ﴾: يَتَنعَّمْ في أكْلِ ما لَذَّ له وطابَ.\n\n﴿وَيَلۡعَبۡ﴾: يتسابَقْ ويرمِ بالسِّهام معنا."],[13,13,"﴿لَيَحۡزُنُنِيٓ﴾: لَيُؤْلمُ نفسي فِراقُ يوسفَ.\n\n﴿غَـٰفِلُونَ﴾: ساهُون."],[14,14,"﴿لَّخَـٰسِرُونَ﴾: عاجِزُون لا خيرَ فينا."],[15,15,"﴿وَأَجۡمَعُوٓاْ﴾: عَزَمُوا.\n\n﴿وَأَوۡحَيۡنَآ إِلَيۡهِ﴾: أعلمَ اللهُ يوسُفَ؛ تَطْمينًا لقَلْبِه.\n\n﴿لَتُنَبِّئَنَّهُم﴾: لتُخْبِرَنَّ إخوتَك."],[17,17,"﴿نَسۡتَبِقُ﴾: نتسابَقُ في الجَرْيِ والرَّمْيِ بالسِّهامِ.\n\n﴿مَتَـٰعِنَا﴾: ما ننتفِعُ به من الطَّعامِ والثيابِ ونحوِهما.\n\n﴿بِمُؤۡمِنࣲ لَّنَا﴾: بمُصَدِّقٍ لنا."],[18,18,"﴿سَوَّلَتۡ﴾: زَيَّنَتْ.\n\n﴿فَصَبۡرࣱ جَمِيلࣱ﴾: وهو ما لا جَزَعَ فيه، ولا شَكْوى معه لأحدٍ من الخَلْقِ."],[19,19,"﴿سَيَّارَةࣱ﴾: جماعةٌ من المسافرين.\n\n﴿وَارِدَهُمۡ﴾: مَن يتقدَّمُهم ليطلُبَ لهم الماءَ.\n\n﴿فَأَدۡلَىٰ دَلۡوَهُۥ﴾: فأَنْزَلَها الواردُ في البئرِ.\n\n﴿وَأَسَرُّوهُ﴾: وأخفى الوارِدُ وأصحابُه يوسفَ عن بقيةِ المسافرين.\n\n﴿بِضَـٰعَةࣰ﴾: متاعًا للتجارة."],[20,20,"﴿وَشَرَوۡهُ﴾: باعه إخوتُه.\n\n﴿بَخۡسࣲ﴾: قليلٍ ناقصٍ عن مِثْلِه.\n\n﴿ٱلزَّ ٰ⁠هِدِينَ﴾: المُعْرِضين عنه، غيرِ المبالِين به."],[21,21,"﴿أَكۡرِمِي مَثۡوَىٰهُ﴾: اجعلي مَقامَه عندنا كريمًا.\n\n﴿فِي ٱلۡأَرۡضِ﴾: أرضِ مصرَ.\n\n﴿وَٱللَّهُ غَالِبٌ عَلَىٰٓ أَمۡرِهِۦ﴾: لا يُعْجِزُه شيءٌ، ولا ينازعُه في حُكْمِه أحدٌ."],[22,22,"﴿أَشُدَّهُۥٓ﴾: منتهى قوتِه الجسميةِ، وتكامُلَ عَقْلِه.\n\n﴿حُكۡمࣰا﴾: حِكْمةً وفَهْمًا سديدًا، أو النبوَّةَ."],[23,23,"﴿وَرَ ٰ⁠وَدَتۡهُ﴾: ودَعَتْ امرأةُ العزيزِ يوسُفَ إلى نفسِها بلِينٍ ومُخادَعَةٍ.\n\n﴿هَيۡتَ لَكَ﴾: هلمَّ إليَّ وأقْبِلْ.\n\n﴿مَعَاذَ ٱللَّهِ﴾: أستجيرُ بالله وأعتصِمُ به ممّا تُريدين مني.\n\n﴿إِنَّهُۥ رَبِّيٓ﴾: إن زوجَكِ سيِّدي.\n\n﴿مَثۡوَايَ﴾: مَقامي عنده."],[24,24,"﴿هَمَّتۡ بِهِۦ﴾: مالَتْ إليه وعَزَمَتْ على فِعْلِ الفاحشةِ به.\n\n﴿وَهَمَّ بِهَا﴾: ما خَطَرَ بنفسِه من الميلِ بمقتضى الطبيعةِ البشريَّة.\n\n﴿بُرۡهَـٰنَ رَبِّهِۦ﴾: حُجَّةَ رَبِّه الواضحةَ التي مَنَعَتْه عن المَيْلِ لخَطَراتِ نفسِه.\n\n﴿ٱلسُّوٓءَ﴾: كلَّ ما يَسُوءُه، ومنه خيانةُ سَيِّدِه.\n\n﴿وَٱلۡفَحۡشَآءَ﴾: ما يَشْتَدُّ قُبْحُه من المعاصي، ومنه الزِّنى.\n\n﴿ٱلۡمُخۡلَصِينَ﴾: المختارِين لطاعةِ اللهِ ورسالتِه."],[25,25,"﴿وَٱسۡتَبَقَا ٱلۡبَابَ﴾: تسابَقا إليه، هو يريدُ الخروجَ وهي تمنعُه.\n\n﴿وَقَدَّتۡ قَمِيصَهُۥ مِن دُبُرࣲ﴾: شَقَّتْه طُولًا مِن خَلْفٍ.\n\n﴿وَأَلۡفَيَا سَيِّدَهَا﴾: وجدا زوجَها."],[26,26,"﴿وَشَهِدَ شَاهِدࣱ﴾: صَبِيٌّ في المهد أنطقَه اللهُ ببراءته."],[28,28,"﴿كَيۡدِكُنَّ﴾: احتيالِكنَّ ومَكْرِكنَّ."],[30,30,"﴿شَغَفَهَا حُبًّا﴾: دَخَلَ حُبُّه إلى غِلاف قلبِها، حتى تَمَكَّنَ."],[31,31,"﴿بِمَكۡرِهِنَّ﴾: باغتيابِهنَّ لها واحتيالِهنَّ في ذَمِّها.\n\n﴿أَعۡتَدَتۡ﴾: هَيَّأت.\n\n﴿مُتَّكَـࣰٔا﴾: ما يَتَّكِئْنَ عليه من الوَسائدِ ونحوِها.\n\n﴿أَكۡبَرۡنَهُۥ﴾: أعْظَمْنَه، ودَهِشْنَ من جَمالِه الرائعِ.\n\n﴿وَقَطَّعۡنَ أَيۡدِيَهُنَّ﴾: جَرَحْنَها بالسَّكاكين؛ لانشغالِهنَّ بحُسْنِه.\n\n﴿حَـٰشَ لِلَّهِ﴾: معاذَ اللهِ وتنزيهًا له."],[32,32,"﴿فَٱسۡتَعۡصَمَ﴾: امتنَع وأبى.\n\n﴿ٱلصَّـٰغِرِينَ﴾: الأذِلّاءِ المُهانِين."],[33,33,"﴿أَصۡبُ إِلَيۡهِنَّ﴾: أمِلْ إلى إجابتِهنَّ.\n\n﴿ٱلۡجَـٰهِلِينَ﴾: الذين يرتكِبُون الإثمَ؛ لجَهْلِهم بعواقِبه."],[35,35,"﴿بَدَا﴾: ظَهَر.\n\n﴿ٱلۡـَٔايَـٰتِ﴾: الأدلَّةَ على براءةِ يوسفَ وعِفَّتِه.\n\n﴿حَتَّىٰ حِينࣲ﴾: إلى زمنٍ غيرِ محدَّدٍ."],[36,36,"﴿خَمۡرࣰا﴾: عِنَبًا يصير خَمْرًا.\n\n﴿بِتَأۡوِيلِهِۦٓ﴾: بتفسيرِ ما رَأَيْنا."],[37,37,"﴿ذَ ٰ⁠لِكُمَا﴾: التعبيرُ للرؤيا، أو العِلْمُ بالغَيبِ."],[40,40,"﴿سَمَّيۡتُمُوهَآ﴾: جَعَلْتُموها آلهةً، تَوَهُّمًا منكم وضلالًا.\n\n﴿سُلۡطَـٰنٍ﴾: حُجَّةٍ تَدُلُّ على صحَّتِها.\n\n﴿ٱلۡقَيِّمُ﴾: المستقيمُ، والثابتُ الذي لا شَكَّ فيه."],[42,42,"﴿ظَنَّ﴾: عَلِمَ.\n\n﴿رَبِّكَ﴾: سيِّدِكَ الملِكِ.\n\n﴿فَأَنسَىٰهُ ٱلشَّيۡطَـٰنُ﴾: فأنسى الشيطانُ ساقِيَ المَلِكِ.\n\n﴿ذِكۡرَ رَبِّهِۦ﴾: ذِكْرَ يوسُفَ عند سيِّده الملِكِ.\n\n﴿بِضۡعَ﴾: من ثلاثٍ إلى تسعٍ."],[43,43,"﴿عِجَافࣱ﴾: جَمْعُ عَجْفاءَ، وهي التي بلغَتْ غايةَ الهُزال.\n\n﴿تَعۡبُرُونَ﴾: تُفَسِّرُون."],[44,44,"﴿أَضۡغَـٰثُ أَحۡلَـٰمࣲ﴾: تَخاليطُ مَناماتٍ كاذبةٍ.\n\n﴿بِتَأۡوِيلِ ٱلۡأَحۡلَـٰمِ﴾: بتفسيرِ ما يراه النائمون ممّا لا حقيقةَ له."],[45,45,"﴿وَٱدَّكَرَ﴾: تَذَكَّرَ أمْرَ يوسُفَ.\n\n﴿أُمَّةٍ﴾: مُدَّةٍ."],[47,47,"﴿دَأَبࣰا﴾: جادِّين على عادتِكم.\n\n﴿فَمَا حَصَدتُّمۡ﴾: ما قَطَعْتُموه حالَ نُضْجِه.\n\n﴿فَذَرُوهُ﴾: اترُكُوه وادَّخِرُوه."],[48,48,"﴿شِدَادࣱ﴾: شديدةُ الجَدْبِ.\n\n﴿يَأۡكُلۡنَ مَا قَدَّمۡتُمۡ لَهُنَّ﴾: يأكلُ الناسُ كلَّ ما ادَّخَرْتُم لأجْلِهنَّ.\n\n﴿تُحۡصِنُونَ﴾: تُخَبِّئونه من البَذْرِ للزِّراعةِ."],[49,49,"﴿يُغَاثُ ٱلنَّاسُ﴾: يأتيهم المطرُ.\n\n﴿يَعۡصِرُونَ﴾: ما يُعْصَرُ من الثِّمارِ؛ لكثرةِ الخيرِ."],[50,50,"﴿رَبِّكَ﴾: سيِّدِكَ الملِكِ.\n\n﴿مَا بَالُ ٱلنِّسۡوَةِ﴾: ما شأنُهنَّ وحقيقةُ أمْرِهنَّ معي؟\n\n﴿قَطَّعۡنَ أَيۡدِيَهُنَّ﴾: جَرَحْنَها بالسَّكاكين.\n\n﴿بِكَيۡدِهِنَّ﴾: باحتيالهنَّ ومَكْرِهنَّ."],[51,51,"﴿مَا خَطۡبُكُنَّ﴾: ما شأنكُنَّ؟\n\n﴿حَـٰشَ لِلَّهِ﴾: معاذَ اللهِ وتنزيهًا له.\n\n﴿حَصۡحَصَٱلۡحَقُّ﴾: ظَهَرَ بَعْدَ خَفائِه."],[52,52,"﴿ذَ ٰ⁠لِكَ﴾: أي: ما قُلْتُه في تنزيهِ يوسفَ، واعترافي بإغرائه.\n\n﴿لِيَعۡلَمَ﴾: أي: زوجي.\n\n﴿لَمۡ أَخُنۡهُ بِٱلۡغَيۡبِ﴾: لم تَقَعْ مني الفاحشةُ والأبوابُ مُغَلَّقَةٌ.\n\n﴿لَا يَهۡدِي﴾: لا يُوَفِّقُ."],[54,54,"﴿أَسۡتَخۡلِصۡهُ لِنَفۡسِي﴾: أجْعَلْ يوسفَ مِن خاصَّتي وأهلِ مَشُورتي.\n\n﴿مَكِينٌ﴾: ذو مَكانةٍ رفيعةٍ وقولٍ نافذٍ."],[55,55,"﴿ٱلۡأَرۡضِ﴾: أرضِ مصرَ."],[56,56,"﴿وَكَذَ ٰ⁠لِكَ﴾: وكما أنْعَمْنا على يوسفَ بالخَلاصِ من السِّجْنِ.\n\n﴿يَتَبَوَّأُ مِنۡهَا﴾: يَنْزِلُ من بلاد مِصرَ."],[58,58,"﴿مُنكِرُونَ﴾: لم يَعْرِفُوا يوسفَ لطولِ المدةِ، وتَغَيُّرِهيئتِه."],[59,59,"﴿جَهَّزَهُم بِجَهَازِهِمۡ﴾: هيَّأ لهم ما هم في حاجةٍ إليه من طعامٍ ومَتاعٍ.\n\n﴿ٱلۡمُنزِلِينَ﴾: المُضِيفِين."],[61,61,"﴿سَنُرَ ٰ⁠وِدُ عَنۡهُ أَبَاهُ﴾: سنجتهدُ في استمالةِ أبيه برِفْقٍ؛ ليُرْسِلَه معنا."],[62,62,"﴿لِفِتۡيَـٰنِهِ﴾: غِلْمانِ يوسفَ.\n\n﴿بِضَـٰعَتَهُمۡ فِي رِحَالِهِمۡ﴾: ثمنَ ما اشترَوْه في أمتعتِهم.\n\n﴿ٱنقَلَبُوٓاْ﴾: رَجَعُوا."],[63,63,"﴿مُنِعَ مِنَّا ٱلۡكَيۡلُ﴾: حُكِمَ بمَنعِه عنّا بعدَ هذه المرَّةِ.\n\n﴿نَكۡتَلۡ﴾: نَحصُلْ على ما نَحْتاج إليه مُقَدَّرًا بالكَيْلِ."],[65,65,"﴿مَتَـٰعَهُمۡ﴾: أوْعِيتَهم، أو أمتعتَهم.\n\n﴿مَا نَبۡغِي﴾: ماذا نَطْلُبُ أكثرَ من هذا الإكرامِ؟\n\n﴿وَنَمِيرُ أَهۡلَنَا﴾: نَجْلُبُ لهم الطعامَ."],[66,66,"﴿مَوۡثِقࣰا مِّنَ ٱللَّهِ﴾: عَهْدًا، وتُؤَكِّدُوه بالحَلِفِ باللهِ.\n\n﴿يُحَاطَ بِكُمۡ﴾: تُغْلَبُوا، فلا تَسْتطيعوا الإتيانَ به، أو تَهْلِكُوا جميعًا.\n\n﴿وَكِيلࣱ﴾: رقيبٌ مُطَّلعٌ."],[67,67,"﴿وَمَآ أُغۡنِي عَنكُم﴾: لا أدْفَعُ عنكم.\n\n﴿عَلَيۡهِ تَوَكَّلۡتُ﴾: اعتمَدْتُ على ربي وفَوَّضْتُ أمري إليه."],[68,68,"﴿حَاجَةࣰ فِي نَفۡسِ يَعۡقُوبَ﴾: وهي شَفَقَتُه على أولادِه أن تصيبَهم العَيْنُ.\n\n﴿قَضَىٰهَا﴾: أدْرَكَها، ووَصّى أولادَه باتِّقائِها."],[69,69,"﴿ءَاوَىٰٓ إِلَيۡهِ أَخَاهُ﴾: ضَمَّ إليه شقيقَه بِنْيامينَ.\n\n﴿فَلَا تَبۡتَئِسۡ﴾: فلا تَحْزَنْ."],[70,70,"﴿ٱلسِّقَايَةَ﴾: إناءٌ للشُّرْبِ، وهو هنا المِكيالُ الذي يُكالُ به الطَّعامُ.\n\n﴿أَذَّنَ مُؤَذِّنٌ﴾: نادى مُنادٍ.\n\n﴿ٱلۡعِيرُ﴾: القافلةُ المحمَّلةُ بالطَّعام."],[72,72,"﴿صُوَاعَ ٱلۡمَلِكِ﴾: المكيالَ الذي يَكيلُ به.\n\n﴿زَعِيمࣱ﴾: ضامِنٌ وكفيلٌ."],[75,75,"﴿جَزَ ٰ⁠ٓؤُهُۥ مَن وُجِدَ فِي رَحۡلِهِۦ﴾: عقوبةُ سَرِقَتِه استرقاقُ مَن وُجِدَ المِكْيالُ في مَتاعِه."],[76,76,"﴿كَذَ ٰ⁠لِكَ كِدۡنَا لِيُوسُفَ﴾: يَسَّرْنا له هذا التدبيرَ الخَفِيَّ للتوصُّلِ إلى غَرَضِه.\n\n﴿دِينِ ٱلۡمَلِكِ﴾: شريعةِ مَلِكِ مصرَ."],[77,77,"﴿أَسَرَّهَا﴾: فأخفى يوسفُ مقالَتَهم التي سَمِعَها مِن نِسْبَتِهم إياه إلى السَّرِقَةِ.\n\n﴿مَّكَانࣰا﴾: مَنزِلَةً."],[79,79,"﴿مَعَاذَ ٱللَّهِ﴾: نَسْتجيرُ باللّٰهِ ونعتصِمُ به.\n\n﴿مَتَـٰعَنَا﴾: مِكْيالَنا الَّذي نَكِيلُ به الطَّعامَ."],[80,80,"﴿ٱسۡتَيۡـَٔسُواْ مِنۡهُ﴾: يَئِسُوا من إجابةِ يوسفَ لمَطْلبِهم.\n\n﴿خَلَصُواْ﴾: انفردُوا عن الناسِ.\n\n﴿نَجِيࣰّا﴾: مُتَسارِّين يتشاوَرُون بينهم.\n\n﴿مَّوۡثِقࣰا مِّنَ ٱللَّهِ﴾: عَهْدًا وأكّدْتُموه بالحَلِفِ باللهِ.\n\n﴿مَا فَرَّطتُمۡ﴾: قَصَّرْتُم.\n\n﴿فَلَنۡ أَبۡرَحَ ٱلۡأَرۡضَ﴾: لن أُفارِقَ أرضَ مصرَ."],[81,81,"﴿وَمَا كُنَّا لِلۡغَيۡبِ حَـٰفِظِينَ﴾: ولم نَدْرِ حين عاهَدْناك على رَدِّه أنه سيَسْرِقُ."],[82,82,"﴿وَٱلۡعِيرَ﴾: القافلةَ.\n\n﴿أَقۡبَلۡنَا فِيهَا﴾: عُدْنا فيها."],[83,83,"﴿سَوَّلَتۡ﴾: زَيَّنَتْ.\n\n﴿فَصَبۡرࣱ جَمِيلٌ﴾: وهو ما لا جَزَعَ فيه، ولا شَكْوى معه لأحدٍ من الخَلْقِ."],[84,84,"﴿وَتَوَلَّىٰ عَنۡهُمۡ﴾: أعرضَ يعقوبُ عن خِطابِهم.\n\n﴿يَـٰٓأَسَفَىٰ﴾: يا حُزني الشديدَ.\n\n﴿وَٱبۡيَضَّتۡ عَيۡنَاهُ﴾: بذَهابِ سوادِهما، مما أدّى إلى ضَعْف بَصَرِه أو ذَهابِه.\n\n﴿كَظِيمࣱ﴾: ممتلئُ القلب حُزْنًا، يَكْتُمُه ولا يُبْدِيه."],[85,85,"﴿تَفۡتَؤُاْ﴾: لا تَزالُ.\n\n﴿حَرَضًا﴾: مُشرِفًا على الهَلاكِ."],[86,86,"﴿بَثِّي﴾: هَمِّي الشديدَ."],[87,87,"﴿فَتَحَسَّسُواْ مِن يُوسُفَ﴾: تَعَرَّفُوا وتَطَلَّبُوا خبرَه.\n\n﴿رَّوۡحِ ٱللَّهِ﴾: رحمتِه وفَرَجِه."],[88,88,"﴿ٱلضُّرُّ﴾: الشِّدَّةُ والجوعُ من الجَدْبِ.\n\n﴿مُّزۡجَىٰةࣲ﴾: رديئةٍ قليلةٍ."],[90,90,"﴿مَنَّ ٱللَّهُ عَلَيۡنَآ﴾: تَفضَّلَ علينا بالسَّلامةِ والاجتماعِ."],[91,91,"﴿ءَاثَرَكَ ٱللَّهُ عَلَيۡنَا﴾: اختارك وفَضَّلَكَ علينا بما خَصَّكَ به من صفاتِ الكمالِ."],[92,92,"﴿لَا تَثۡرِيبَ﴾: لا تأنيبَ ولا لَوْمَ."],[93,93,"﴿يَأۡتِ بَصِيرࣰا﴾: يَرْجِعُ إليه بَصَرُهُ."],[94,94,"﴿فَصَلَتِ ٱلۡعِيرُ﴾: خرجَتِ القافلةُ من مصرَ قاصدةً الشّامَ.\n\n﴿لَأَجِدُ رِيحَ يُوسُفَ﴾: لَأَشُمُّ رائحتَه.\n\n﴿تُفَنِّدُونِ﴾: تَسْخَرُوا مني وتنسِبُوني إلى العَجْزِ، وضَعْفِ الرأيِ، أو تُكَذِّبوني."],[95,95,"﴿ضَلَـٰلِكَ﴾: خَطَئِك وبُعْدِك عن الصوابِ في حُبِّ يوسفَ."],[96,96,"﴿ٱلۡبَشِيرُ﴾: الذي بَشَّرَ يعقوبَ بأنّ يوسفَ حيٌّ."],[99,99,"﴿ءَاوَىٰٓ إِلَيۡهِ أَبَوَيۡهِ﴾: ضَمَّهما وأنزلَهما عنده."],[100,100,"﴿وَرَفَعَ أَبَوَيۡهِ عَلَى ٱلۡعَرۡشِ﴾: أجْلَسَهما بجانبِه على سريرِ مُلْكِه؛ إكرامًا لهما.\n\n﴿وَخَرُّواْ﴾: هَوى أبوه وإخوتُه إلى الأرضِ.\n\n﴿لَهُۥ سُجَّدࣰا﴾: ساجدين تكريمًا ليوسفَ، على عادتِهم في تحيةِ الملُوك وأشباهِهم.\n\n﴿هَـٰذَا تَأۡوِيلُ رُءۡيَـٰيَ مِن قَبۡلُ﴾: أي: هذا السجودُ تفسيرٌ وتصديقٌ للرؤيا التي رأيتُها في صِغَري.\n\n﴿حَقࣰّا﴾: صِدْقًا، وليسَتْ من أكاذيبِ الأحلامِ.\n\n﴿أَحۡسَنَ بِيٓ﴾: أفاض اللهُ عليَّ من نِعَمِه.\n\n﴿ٱلۡبَدۡوِ﴾: باديةِ الشّامِ.\n\n﴿نَّزَغَ ٱلشَّيۡطَـٰنُ﴾: أفسَدَ وأغوى؛ لأنه هو سببُ الإفسادِ.\n\n﴿لَطِيفࣱ﴾: عليمٌ بخَفايا الأمورِ، مُدَبِّرٌ لها،ومُسَهِّلٌ لصعابِها."],[101,101,"﴿مِنَ ٱلۡمُلۡكِ﴾: مُلْكِ مِصْرَ.\n\n﴿تَأۡوِيلِ ٱلۡأَحَادِيثِ﴾: تفسير الرُّؤى، وغيرِها من العِلْمِ.\n\n﴿فَاطِرَ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ﴾: يا خالقَهما ومُبْدِعَهما.\n\n﴿وَلِيِّۦ﴾: مُتَوَلِّي حِفْظي وجميعِ شأني."],[102,102,"﴿ذَ ٰ⁠لِكَ﴾: ما ذُكِرَ من قصةِ يوسفَ وإخوانِه.\n\n﴿وَمَا كُنتَ لَدَيۡهِمۡ﴾: وما كنتَ حاضرًا مع إخوةِ يوسفَ.\n\n﴿أَجۡمَعُوٓاْ أَمۡرَهُمۡ﴾: حينَ دبَّرُوا إلقاءَه في جوفِ البئرِ وظُلْمَتِه.\n\n﴿وَهُمۡ يَمۡكُرُونَ﴾: يَحْتالُون في خُفْيَةٍ؛ لإيقاعِ الأذى والشَّرِّ به."],[103,103,"﴿ٱلنَّاسِ﴾: مُشْركِي قومِك."],[105,105,"﴿وَكَأَيِّن﴾: وكثيرٌ.\n\n﴿مِّنۡ ءَايَةࣲ﴾: من الدلائلِ الدالَّةِ على وحْدانيةِ اللهِ وقدرتِه.\n\n﴿يَمُرُّونَ عَلَيۡهَا﴾: يشاهِدُونها."],[106,106,"﴿وَهُم مُّشۡرِكُونَ﴾: فهم يَخْلِطُون مع إيمانِهم باللهِ ربًّا الإشراكَ في ألوهيَّتِه وعبادتِه."],[107,107,"﴿غَـٰشِيَةࣱ﴾: عقوبةٌ في الدنيا تَعُمُّهم.\n\n﴿بَغۡتَةࣰ﴾: فَجْأةً."],[108,108,"﴿بَصِيرَةٍ﴾: يقينٍ وحُجَّةٍ واضحةٍ."],[109,109,"﴿أَهۡلِ ٱلۡقُرَىٰٓ﴾: المدنِ والحاضرةِ."],[110,110,"﴿ٱسۡتَيۡـَٔسَ ٱلرُّسُلُ﴾: يَئِسوا من إيمانِ قومِهم.\n\n﴿وَظَنُّوٓاْ أَنَّهُمۡ قَدۡ كُذِبُواْ﴾: وظَنَّ المُرْسَلُ إليهم أن الرُّسَلَ قد كَذَبُوهم فيما أخبرُوهم عن اللهِ.\n\n﴿جَآءَهُمۡ نَصۡرُنَا﴾: جاء نَصْرُنا لرُسِلِنا عند شِدَّةِ الكَرْبِ.\n\n﴿بَأۡسُنَا﴾: عذابُنا."],[111,111,"﴿عِبۡرَةࣱ﴾: عِظَةٌ.\n\n﴿لِّأُوْلِي ٱلۡأَلۡبَـٰبِ﴾: أصحابِ العقولِ السليمةِ.\n\n﴿مَا كَانَ﴾: أي: هذا القرآنُ.\n\n﴿يُفۡتَرَىٰ﴾: يُخْتَلَقُ.\n\n﴿تَصۡدِيقَ ٱلَّذِي بَيۡنَ يَدَيۡهِ﴾: أي: القرآنُ يَشْهَدُ على صِدْقِ ما تقدَّمه من الكتبِ المنزَّلةِ، وأنها من عندِ اللهِ.\n\n﴿وَتَفۡصِيلَ كُلِّ شَيۡءࣲ﴾: تبيينَ ما يَحْتاجُ إليه العبادُ من أمورِ الدينِ."]]);
QTF("gharib",13,[[2,2,"﴿بِغَيۡرِ عَمَدࣲ﴾: بغيرِ دَعائمَ.\n\n﴿تَرَوۡنَهَا﴾: كما تَرَوْنَ خَلْقَ السمواتِ البديعَ.\n\n﴿ٱسۡتَوَىٰ﴾: علا وارتفعَ، استواءً يليقُ بجَلالِه وعَظَمتِه.\n\n﴿ٱلۡعَرۡشِ﴾: سريرِ المُلْكِ الذي استوى عليه الرحمنُ، وتَحملُه الملائكةُ، وهو أعظمُ المخلوقاتِ، وهو سَقْفُ الجنةِ.\n\n﴿وَسَخَّرَ ٱلشَّمۡسَ وَٱلۡقَمَرَ﴾: ذلَّلهما لمنافعِ الخَلْقِ ومصالِحهِم.\n\n﴿يُدَبِّرُ ٱلۡأَمۡرَ﴾: يَقضي أمورَ الدنيا والآخرةِ، ويُصَرِّفها وحدَه على أكملِ الوجوهِ.\n\n﴿يُفَصِّلُ ٱلۡـَٔايَـٰتِ﴾: يُبَيِّنُ دَلائلَ وحدانيتِه وقُدْرَتِه."],[3,3,"﴿مَدَّ ٱلۡأَرۡضَ﴾: بَسَطَها، وهَيَّأها للاستقرارِ والعيشِ فيها.\n\n﴿رَوَ ٰ⁠سِيَ﴾: جبالًا تُثبِّتُها؛ لئلا تضطرِبَ.\n\n﴿زَوۡجَيۡنِ﴾: صِنْفَين في اللونِ، أو الطَّعْم، أو القَدْرِ، ونحوِها.\n\n﴿يُغۡشِي ٱلَّيۡلَ ٱلنَّهَارَ﴾: يجعلُ الليلَ يُغَطِّي النَّهارَ ويَسْتُره بظُلْمتِه، بإدخالِه على النَّهارِ، أو العكس."],[4,4,"﴿قِطَعࣱ﴾: بقاعٌ مختلفةٌ في الأوصافِ والأحوالِ.\n\n﴿وَجَنَّـٰتࣱ﴾: بساتينُ.\n\n﴿وَنَخِيلࣱ صِنۡوَانࣱ﴾: النخيلُ المتفرعُ الذي يجمَعُه أصلٌ ومَنبَتٌ واحدٌ."],[5,5,"﴿وَإِن تَعۡجَبۡ﴾: أي: من عَدَمِ إيمانِ الكفّار.\n\n﴿ٱلۡأَغۡلَـٰلُ﴾: جَمْعُ غُلٍّ، وهو الطَّوقُ، أو القيدُ يُقَيَّدُ به، فيُجْعَلُ العُنُقُ في وسَطِه."],[6,6,"﴿خَلَتۡ﴾: مَضَتْ.\n\n﴿ٱلۡمَثُلَـٰتُ﴾: جَمْعُ مَثُلَة، وهي عقوباتُ اللهِ التي تكونُ مَثَلًا يَرْدَعُ."],[7,7,"﴿لَوۡلَآ﴾: هَلّا.\n\n﴿ءَايَةࣱ﴾: مُعْجِزَةٌ محسوسةٌ، كناقةِ صالحٍ.\n\n﴿هَادٍ﴾: داعٍ يرشُدُهم، وهو نبيُّهم."],[8,8,"﴿وَمَا تَغِيضُ ٱلۡأَرۡحَامُ﴾: ما تَنْقُصُه قبلَ اكتمالِ الحَمْلِ في بِنْيتِه أو مُدَّتِه، أو ما تُسْقِطُه ميتًا.\n\n﴿وَمَا تَزۡدَادُ﴾: ما يَزْدادُه الحَمْلُ في جِسْمِه، أو مُدَّتِه، أو عَدَدِه.\n\n﴿بِمِقۡدَارٍ﴾: بقَدْرٍ عندَ اللهِ لا يتعدّاه ولا يَنْقُصُ عنه."],[9,9,"﴿ٱلۡغَيۡبِ﴾: ما خَفِيَ عن الأبصارِ والحواسِّ.\n\n﴿وَٱلشَّهَـٰدَةِ﴾: ما هو مشاهَدٌ وحاضِرٌ.\n\n﴿ٱلۡكَبِيرُ﴾: في ذاتِه وأسمائِه وصفاتِه.\n\n﴿ٱلۡمُتَعَالِ﴾: المُسْتَعْلي على جميعِ خَلْقِه بذاتِه وقُدْرتِه وقَهْرِه."],[10,10,"﴿سَوَآءࣱ﴾: يستوي في عِلْمِ اللهِ تعالى.\n\n﴿مَّنۡ أَسَرَّ ٱلۡقَوۡلَ﴾: الذي أخفاه.\n\n﴿مُسۡتَخۡفِۭ بِٱلَّيۡلِ﴾: مُسْتَتِرٌ بأعمالِه في ظُلْمَةِ الليلِ عن الأَعْيُنِ.\n\n﴿وَسَارِبُۢ بِٱلنَّهَارِ﴾: ذاهبٌ في طريقِه وعَمَلِه نهارًا يُبْصِرُه كلُّ أحدٍ."],[11,11,"﴿لَهُۥ﴾: أي: لله، أو للمذكورِ من أحوالِ الإنسانِ.\n\n﴿مُعَقِّبَـٰتࣱ﴾: ملائكةٌ حَفَظَةٌ يتعاقبون على الإنسان ليلًا ونهارًا.\n\n﴿يَحۡفَظُونَهُۥ مِنۡ أَمۡرِ ٱللَّهِ﴾: بسبب أمرِ اللهِ لهم بحِفْظِه ورعايتِه.\n\n﴿وَالٍ﴾: وليٍّ ناصرٍ يتولّى أمورَهم ويَدْفَعُ عنهم ما هم فيه."],[12,12,"﴿خَوۡفࣰا﴾: من الصواعقِ المُحْرِقَةِ.\n\n﴿وَطَمَعࣰا﴾: في نزولِ المَطَرِ.\n\n﴿وَيُنشِئُ﴾: يُوجِدُ.\n\n﴿ٱلسَّحَابَ ٱلثِّقَالَ﴾: المُحَمَّلَةَ بالماءِ، فتَثْقُلُ لكثرةِ مائِها."],[13,13,"﴿وَهُمۡ يُجَـٰدِلُونَ فِي ٱللَّهِ﴾: والكفارُ يُجادِلون في وحْدانيةِ اللهِ وقدرتِه على البعثِ.\n\n﴿ٱلۡمِحَالِ﴾: المكايَدَةِ والقوةِ والبَطْشِ بأعدائِه."],[14,14,"﴿دَعۡوَةُ ٱلۡحَقِّ﴾: دعوةُ التوحيدِ.\n\n﴿فِي ضَلَـٰلࣲ﴾: في غايةِ البُعْدِ عن الصوابِ؛ بسببِ إشراكِهم مع اللهِ غيرَه."],[15,15,"﴿وَلِلَّهِ يَسۡجُدُ﴾: يخضَعُ لعظمَتِه، وينقادُ لأحكامِه.\n\n﴿طَوۡعࣰا وَكَرۡهࣰا﴾: يخضعُ له المؤمنون مُختارين، والكافِرُون رغمًا عنهم؛ لأنّ قدرتَه نافذةٌ في الكلِّ.\n\n﴿وَظِلَـٰلُهُم﴾: وتنقادُ وتخضعُ لعظمةِ اللهِ ظلال المخلوقات، فهي تحتَ قَهْرِه ومشيئتِه.\n\n﴿بِٱلۡغُدُوِّ﴾: جَمْعُ غَداة، وهي أولُ النهار.\n\n﴿وَٱلۡـَٔاصَالِ﴾: جَمْعُ أصِيل، وهو آخِرُ النَّهارِ."],[16,16,"﴿فَتَشَـٰبَهَ ٱلۡخَلۡقُ﴾: أي: خَلْقُ اللهِ وخَلْقُ الشُّركاءِ.\n\n﴿ٱلۡوَ ٰ⁠حِدُ﴾: الذي لا شبيهَ له ولا شريكَ، المستحِقُّ للعبادة.\n\n﴿ٱلۡقَهَّـٰرُ﴾: الغالبُ على ما سواه، وكلُّ شيءٍ تحتَ قَهْرِه ومشيئتِه."],[17,17,"﴿بِقَدَرِهَا﴾: بقَدْرِ تفاوُتِها صِغَرًا وكِبَرًا.\n\n﴿زَبَدࣰا﴾: ما يَعْلُو على وجهِ الماءِ عند جَرَيانِه، وهو الغُثاءُ.\n\n﴿رَّابِيࣰا﴾: مرتفعًا طافيًا فوقَ الماءِ.\n\n﴿وَمِمَّا يُوقِدُونَ عَلَيۡهِ فِي ٱلنَّارِ﴾: ومن المعادن التي يُوقِدُ الناسُ النارَ عليها لصَهْرِها.\n\n﴿ٱبۡتِغَآءَ حِلۡيَةٍ﴾: طَلَبًا للزِّينة كالذَّهَبِ.\n\n﴿أَوۡ مَتَـٰعࣲ﴾: أو طَلَبًا لمنافعَ ينتفعون بها كالنُّحاسِ.\n\n﴿زَبَدࣱ مِّثۡلُهُۥ﴾: الخَبَثُ الطافي عند إذابةِ المعادنِ، كالذي كان فوقَ الماءِ، لا فائدةَ منهما.\n\n﴿جُفَآءࣰ﴾: مَرْمِيًّا به، أو مُتَفرِّقًا."],[18,18,"﴿ٱلۡحُسۡنَىٰ﴾: الجنةُ.\n\n﴿لَٱفۡتَدَوۡاْ بِهِۦٓ﴾: لَبَذَلُوه فِداءً لأنفسِهم يومَ القيامةِ.\n\n﴿سُوٓءُ ٱلۡحِسَابِ﴾: الحسابُ السِّيِّئُ على ما قَدَّموه مِن عَمَلٍ.\n\n﴿ٱلۡمِهَادُ﴾: الفِراشُ والمستَقَرُّ."],[19,19,"﴿أَعۡمَىٰٓ﴾: لا يُبْصِرُ الحَقَّ ولا يَتَّبِعُه.\n\n﴿أُوْلُواْ ٱلۡأَلۡبَـٰبِ﴾: أصحابُ العقولِ السليمةِ."],[20,20,"﴿بِعَهۡدِ ٱللَّهِ﴾: ما أمَرَ اللهُ به.\n\n﴿ٱلۡمِيثَـٰقَ﴾: العهدَ المؤكَّدَ الذي عاهدُوا اللهَ عليه."],[22,22,"﴿ٱبۡتِغَآءَ وَجۡهِ رَبِّهِمۡ﴾: طَلَبًا لرِضاه.\n\n﴿وَيَدۡرَءُونَ﴾: يَدْفَعُون، أو يُتْبِعُونَ.\n\n﴿عُقۡبَى ٱلدَّارِ﴾: العاقبةُ المحمودةُ في الآخرةِ."],[23,23,"﴿جَنَّـٰتُ عَدۡنࣲ﴾: دارُ إقامةٍ خالدين فيها."],[24,24,"﴿سَلَـٰمٌ عَلَيۡكُم﴾: تحيةٌ خاصةٌ بكم، وسَلِمْتُم من كلِّ سوءٍ."],[25,25,"﴿ٱللَّعۡنَةُ﴾: الطَّرْدُ من رحمةِ اللهِ.\n\n﴿سُوٓءُ ٱلدَّارِ﴾: العاقبةُ السيئةُ في الآخرةِ، وهي النارُ."],[26,26,"﴿وَيَقۡدِرُ﴾: يُضَيِّق الرزقَ على مَن يشاءُ؛ لحكمةٍ.\n\n﴿وَفَرِحُواْ﴾: أي: الكفارُ، فَرَحَ طُغْيانٍ وبَطَرٍ.\n\n﴿مَتَـٰعࣱ﴾: شيءٌ قليلٌ يُتَمَتَّعُ به، سريعُ الزَّوالِ."],[27,27,"﴿لَوۡلَآ﴾: هَلّا.\n\n﴿ءَايَةࣱ﴾: مُعْجِزَةٌ محسوسةٌ، كناقةِ صالحٍ.\n\n﴿وَيَهۡدِيٓ﴾: يُرْشِدُ ويُوَفِّقُ.\n\n﴿مَنۡ أَنَابَ﴾: الذي رَجَعَ إلى اللهِ وطَلَبَ رِضْوانَه."],[28,28,"﴿تَطۡمَئِنُّ﴾: تَسْكُنُ وتستأنِسُ."],[29,29,"﴿طُوبَىٰ لَهُمۡ﴾: عَيْشٌ وحالٌ طيبةٌ في الآخرةِ.\n\n﴿مَـَٔابࣲ﴾: مَرْجِعٍ."],[30,30,"﴿كَذَ ٰ⁠لِكَ أَرۡسَلۡنَـٰكَ﴾: كما أرْسَلْنا الُمرْسَلين قبلَك أرْسَلْناك.\n\n﴿خَلَتۡ﴾: مَضَتْ.\n\n﴿تَوَكَّلۡتُ﴾: اعتمَدْتُ على ربي، وفوَّضْتُ أمري إليه.\n\n﴿مَتَابِ﴾: مَرْجِعي وتَوْبتي."],[31,31,"﴿سُيِّرَتۡ بِهِ ٱلۡجِبَالُ﴾: نُقِلَتْ عن أماكنِها.\n\n﴿قُطِّعَتۡ بِهِ ٱلۡأَرۡضُ﴾: شُقِّقَتْ به، فتَصِيرُ عيونًا وأنهارًا.\n\n﴿كُلِّمَ بِهِ ٱلۡمَوۡتَىٰ﴾: بأَنْ تُحْيا، ويُقْرَأَ عليهم فَيفْهَمُوه كالأحياءِ.\n\n﴿أَفَلَمۡ يَاْيۡـَٔسِ﴾: أفلم يَعْلَمْ ويتبيَّنْ.\n\n﴿قَارِعَةٌ﴾: مصيبةٌ تَنْزِلُ بهم وتُهْلِكُهُم.\n\n﴿وَعۡدُ ٱللَّهِ﴾: النصرُ عليهم، أو قيامُ الساعةِ."],[32,32,"﴿فَأَمۡلَيۡتُ﴾: أمْهَلْتُ مدةً طويلةً."],[33,33,"﴿قَآئِمٌ عَلَىٰ كُلِّ نَفۡسِۭ﴾: رقيبٌ وحافظٌ عليها، وهو اللهُ.\n\n﴿قُلۡ سَمُّوهُمۡ﴾: اذكُروا أسماءَ الشُّركاءِ وصِفاتِهم.\n\n﴿أَم بِظَـٰهِرࣲ مِّنَ ٱلۡقَوۡلِ﴾: بل أتُسَمُّونهم شركاءَ بقولٍ باطِلٍ لا حقيقةَ له.\n\n﴿زُيِّنَ﴾: حَسَّنَ الشَّيطانُ.\n\n﴿مَكۡرُهُمۡ﴾: كفْرُهم وقولُهم الباطِلَ.\n\n﴿هَادࣲ﴾: أحدٍ يُوَفِّقُه إلى الخيرِ."],[34,34,"﴿لَّهُمۡ عَذَابࣱ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا﴾: بالقَتْلِ والأسْرِ وغيرِهما.\n\n﴿وَاقࣲ﴾: مانعٍ وعاصمٍ."],[35,35,"﴿أُكُلُهَا دَآئِمࣱ﴾: ثَمَرُها لا انقطاعَ لأنواعِه.\n\n﴿وَظِلُّهَا﴾: دائمٌ لا يزولُ."],[36,36,"﴿ٱلۡكِتَـٰبَ﴾: التوراةَ والإنجيلَ.\n\n﴿وَمِنَ ٱلۡأَحۡزَابِ﴾: مَن تَحزَّبَ على الكفرِ من اليهودِ والنصارى.\n\n﴿وَإِلَيۡهِ مَـَٔابِ﴾: مَرْجِعي إلى اللهِ وحدَه."],[37,37,"﴿وَكَذَ ٰ⁠لِكَ أَنزَلۡنَـٰهُ حُكۡمًا عَرَبِيࣰّا﴾: وكما أنزَلْنا الكتبَ على الأنبياءِ بلسانِهم، أنزَلْنا القرآنَ بلغةِ العربِ؛ لتَحْكُمَ به.\n\n﴿وَلِيࣲّ﴾: ناصرٍ يَليِ أمْرَك، ويَدْفَعُ عنك."],[38,38,"﴿بِـَٔايَةٍ﴾: مُعْجِزَةٍ دالَّةٍ على صِدْقِه.\n\n﴿لِكُلِّ أَجَلࣲ كِتَابࣱ﴾: لكلِّ أمرٍ قضاه اللهُ كتابٌ وأجَلٌ كَتَبَه عنده، أو لكلِّ وقتٍ حُكْمٌ معيَّن يُكتَبُ على العباد."],[39,39,"﴿وَيُثۡبِتُ﴾: يُبْقي ما يشاءُ من الأحكامِ وغيرِها وفْقَ حِكْمَتِه.\n\n﴿أُمُّ ٱلۡكِتَـٰبِ﴾: أصلُه، وهو اللَّوحُ المحفوظُ الذي لا يَتغيَّرُ."],[41,41,"﴿نَنقُصُهَا مِنۡ أَطۡرَافِهَا﴾: نَفْتحُ أرضَ المشركين من جوانبِها، ونُلْحِقُها ببلادِ المسلمين.\n\n﴿لَا مُعَقِّبَ لِحُكۡمِهِۦ﴾: لا رادَّ ولا مُبْطِلَ لحُكْمِه وقضائِه."],[42,42,"﴿مَكَرَ ٱلَّذِينَ مِن قَبۡلِهِمۡ﴾: احتالُوا في خُفْيةٍ للكيدِ مِن رُسُلِهم.\n\n﴿فَلِلَّهِ ٱلۡمَكۡرُ جَمِيعࣰا﴾: لا يَلْتفِتُ إلى تدبيرِ غيرِه، فهو المُبطِلُ لمكْرِهم.\n\n﴿عُقۡبَى ٱلدَّارِ﴾: العاقبةُ المحمودةُ في الآخرةِ."],[43,43,"﴿وَمَنۡ عِندَهُۥ عِلۡمُ ٱلۡكِتَـٰبِ﴾: وكَفَتْ شهادةُ علماءِ اليهودِ والنصارى ممَّن آمَنَ برسالتي."]]);
QTF("gharib",14,[[1,1,"﴿بِإِذۡنِ رَبِّهِمۡ﴾: بأَمْرِه وتيسيرِه وتوفيقِه.\n\n﴿صِرَ ٰ⁠طِ﴾: طريقِ.\n\n﴿ٱلۡعَزِيزِ﴾: الغالبِ الذي لا يَقْدِرُ عليه أحدٌ.\n\n﴿ٱلۡحَمِيدِ﴾: المَحْمودِ في كلِّ حالٍ، المُثْنى عليه من نفسِه ومن عبادِه."],[2,2,"﴿وَوَيۡلࣱ﴾: هَلاكٌ ووَعيدٌ."],[3,3,"﴿يَسۡتَحِبُّونَ﴾: يختارون.\n\n﴿وَيَبۡغُونَهَا عِوَجًا﴾: ويُريدُون أن تكونَ سبيلُ اللهِ مائلةً وفْقَ أهوائِهم."],[4,4,"﴿وَيَهۡدِي﴾: يُوَفِّقُ مَن يشاءُ إلى الهدى."],[5,5,"﴿بِـَٔايَـٰتِنَآ﴾: بالمعجِزاتِ الدالَّةِ على صِدْقِه.\n\n﴿بِأَيَّىٰمِ ٱللَّهِ﴾: بنِعَمِه وبَلاياه التي وقعَتْ على الأممِ السابقةِ.\n\n﴿لَـَٔايَـٰتࣲ﴾: دلالاتٍ وعِبَرًا.\n\n﴿صَبَّارࣲ﴾: كثيرِ الصبرِ على الطاعاتِ والبلاءِ.\n\n﴿شَكُورࣲ﴾: كثيرِ الشُّكرِ على نِعَمِ اللهِ، قائمٍ بحقوقِه."],[6,6,"﴿يَسُومُونَكُمۡ﴾: يُذِيقُونكم.\n\n﴿وَيَسۡتَحۡيُونَ نِسَآءَكُمۡ﴾: يَسْتَبْقُونَهنَّ أحياءً؛ للخِدْمةِ والامتِهان.\n\n﴿بَلَآءࣱ﴾: اختبارٌ لكم بالنِّعَمِ والفِتَن."],[7,7,"﴿تَأَذَّنَ رَبُّكُمۡ﴾: أعْلَمَ إعلامًا مُؤَكَّدًا."],[9,9,"﴿بِٱلۡبَيِّنَـٰتِ﴾: بالبراهينِ الواضحاتِ على صِدْقِهم.\n\n﴿فَرَدُّوٓاْ أَيۡدِيَهُمۡ فِيٓ أَفۡوَ ٰ⁠هِهِمۡ﴾: عَضَّتِ الأممُ على أيديها؛ غيظًا واستكبارًا عن الإيمانِ.\n\n﴿مُرِيبࣲ﴾: مُوقعٍ في القَلَقِ وعَدَمِ الاطمئنانِ."],[10,10,"﴿فَاطِرِ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ﴾: خالِقِهما ومُبْدِعِهما.\n\n﴿إِلَىٰٓ أَجَلࣲ مُّسَمࣰّى﴾: مُدَّةِ بقائِكم في الدنيا، فلا يُعَذِّبكُم فيها.\n\n﴿بِسُلۡطَـٰنࣲ مُّبِينࣲ﴾: حُجَّةٍ ظاهرةٍ تَشْهَدُ على صِدْقِكم."],[11,11,"﴿يَمُنُّ عَلَىٰ مَن يَشَآءُ﴾: يَتَفَضَّلُ عليه فيَصْطَفِيه للرِّسالةِ.\n\n﴿بِإِذۡنِ ٱللَّهِ﴾: بأمْرِه ومشيئتِه.\n\n﴿وَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ﴾: فلْيَعْتَمِدْ عليه، ولْيُفَوِّضْ أمرَه إليه."],[12,12,"﴿هَدَىٰنَا سُبُلَنَا﴾: أرْشَدَنا إلى طريقِ النَّجاة، ووَفَّقنا إلى اتِّباعِ شَرْعِه."],[13,13,"﴿مِلَّتِنَا﴾: دينِنا."],[14,14,"﴿ٱلۡأَرۡضَ مِنۢ بَعۡدِهِمۡ﴾: أي: أرضَ الكافرين وديارَهم مِن بَعْدِ إهلاكِهم.\n\n﴿مَقَامِي﴾: مَوْقِفَه بين يَدَي اللهِ للحسابِ، أو: قيامي عليه ومراقبتي له."],[15,15,"﴿وَٱسۡتَفۡتَحُواْ﴾: سألَ الرُّسلُ ربَّهم النصرَ على أعدائِهم، أو طَلَبُوا منه الحُكْمَ بينهَم.\n\n﴿وَخَابَ﴾: خَسِرَ وهَلَكَ.\n\n﴿جَبَّارٍ﴾: مُتَعاظِمٍ في نفسِه، مُتَكَبِّرٍ على غيرِه وعن الحقِّ.\n\n﴿عَنِيدࣲ﴾: معاندٍ للحقِّ، مائلٍ عنه لا يَقْبَلُه."],[16,16,"﴿مِّن وَرَآئِهِۦ جَهَنَّمُ﴾: أمامَ هذا الكافرِ ما أعَدَّ اللهُ من العذابِ في النار.\n\n﴿صَدِيدࣲ﴾: ما يَسِيلُ من أجسادِ أهلِ النّارِ."],[17,17,"﴿يَتَجَرَّعُهُۥ﴾: يَتَكلَّفُ ابتلاعَه مرَّة بعدَ مرَّةٍ؛ لحرارتهِ مع غَلَبَةِ العَطَشِ عليه.\n\n﴿وَلَا يَكَادُ يُسِيغُهُۥ﴾: لا يَسْتطيعُ ابتلاعَه بسهولةٍ، بل يَشْرَبُه بعد عَناءٍ، فيُقَطِّعُ أمعاءَه.\n\n﴿وَمِن وَرَآئِهِۦ﴾: وله بعدَ هذا العذابِ.\n\n﴿غَلِيظࣱ﴾: شديدٌ مؤلمٌ."],[18,18,"﴿مَّثَلُ ٱلَّذِينَ كَفَرُواْ﴾: صفةُ أعمالِ الكفارِ في الدنيا وبُطْلانِها عندَ اللهِ بسببِ كُفْرِهم.\n\n﴿عَاصِفࣲ﴾: شديدِ الريحِ.\n\n﴿لَّا يَقۡدِرُونَ مِمَّا كَسَبُواْ عَلَىٰ شَيۡءࣲ﴾: لا يَجِدُون من أعمال البِرِّ ما يَنْفعُهم في الآخرةِ."],[19,19,"﴿بِٱلۡحَقِّ﴾: على الوجهِ الصحيحِ الدّالِّ على حكمتِه، وكمالِ قدرتِه."],[20,20,"﴿بِعَزِيزࣲ﴾: بممتنعٍ أو متعسِّرٍ."],[21,21,"﴿وَبَرَزُواْ﴾: خَرَجَ الخلائقُ من قبورِهم؛ للحسابِ.\n\n﴿ٱلضُّعَفَـٰٓؤُاْ﴾: ضعفاءُ الرأيِ، وهم الأتباعُ.\n\n﴿لِلَّذِينَ ٱسۡتَكۡبَرُوٓاْ﴾: وهم القادةُ والرؤساءُ.\n\n﴿تَبَعࣰا﴾: أتباعًا.\n\n﴿لَوۡ هَدَىٰنَا ٱللَّهُ﴾: لو وفَّقَنا إلى الإيمانِ.\n\n﴿لَهَدَيۡنَـٰكُمۡ﴾: لَأَرشَدْناكم إليه.\n\n﴿سَوَآءٌ عَلَيۡنَآ أَجَزِعۡنَآ﴾: يَسْتَوي ضَعْفُنا عن تَحمُّلِ ما نَزَلَ بنا جميعًا من العذابِ.\n\n﴿مَّحِيصࣲ﴾: مَهْرَبٍ ومَنجى."],[22,22,"﴿قُضِيَ﴾: أُحكِمَ، وفُرِغَ منه، وهو الحِسابُ، ودخولُ السُّعداءِ الجنةَ، والأشقياءِ النارَ.\n\n﴿وَعۡدَ ٱلۡحَقِّ﴾: بالبعثِ والجزاءِ.\n\n﴿وَوَعَدتُّكُمۡ﴾: وعْدًا باطلًا بعَدَمَ البعثِ والجَزاءِ.\n\n﴿سُلۡطَـٰنٍ﴾: تَسَلُّطٍ وإجبارٍ، أو حُجَّةٍ.\n\n﴿بِمُصۡرِخِكُمۡ﴾: بمُغِيثِكم مما أنتم فيه من العذابِ.\n\n﴿بِمُصۡرِخِيَّ﴾: بمُغِيثِيَّ مما أنا فيه منه.\n\n﴿بِمَآ أَشۡرَكۡتُمُونِ﴾: بإشراكِكم إياي مع الله في العبادةِ.\n\n﴿مِن قَبۡلُ﴾: في الدنيا."],[23,23,"﴿مِن تَحۡتِهَا﴾: من تحتِ أشجارِ الجِنانِ وقُصورِها.\n\n﴿بِإِذۡنِ رَبِّهِمۡ﴾: بأمرِه وتوفيقِه وفَضْلِه.\n\n﴿تَحِيَّتُهُمۡ فِيهَا﴾: من اللهِ والملائكةِ، ويُحيِّي بعضُهم بعضًا."],[24,24,"﴿كَلِمَةࣰ طَيِّبَةࣰ﴾: كلمةَ التوحيدِ: لا إلهَ إلا اللهُ.\n\n﴿كَشَجَرَةࣲ طَيِّبَةٍ﴾: كشَجَرَةٍ طيبةِ المنظرِ والثَّمَرِ، وهي النَّخْلَةُ.\n\n﴿ثَابِتࣱ﴾: متمكِّنٌ بعروقِه في الأرضِ.\n\n﴿وَفَرۡعُهَا فِي ٱلسَّمَآءِ﴾: وأعلاها مرتفِعٌ جهةَ العلوِّ."],[25,25,"﴿تُؤۡتِيٓ أُكُلَهَا﴾: تُعطي ثمارَها.\n\n﴿كُلَّ حِينِۭ بِإِذۡنِ رَبِّهَا﴾: كلَّ وقتٍ وقَّته اللهُ لإثْمارِها."],[26,26,"﴿كَلِمَةٍ خَبِيثَةࣲ﴾: هي كلمةُ الكفرِ.\n\n﴿كَشَجَرَةٍ خَبِيثَةٍ﴾: كشجرةٍ رديئةٍ فاسدةٍ في الرائحةِ والطَّعْمِ والمأكلِ، وهي شجرةُ الحَنْظَلِ.\n\n﴿ٱجۡتُثَّتۡ﴾: اقتُلِعَتْ من أصلِها.\n\n﴿قَرَارࣲ﴾: استقرارٍ وثباتٍ."],[27,27,"﴿ٱلثَّابِتِ﴾: الراسخِ الواضحِ، وهو كلمةُ الشهادتين.\n\n﴿وَفِي ٱلۡـَٔاخِرَةِ﴾: في القبرِ عندَ سؤالِ المَلَكَين."],[28,28,"﴿بَدَّلُواْ نِعۡمَتَ ٱللَّهِ كُفۡرࣰا﴾: اختارُوا الكفرَ بدلًا عن شُكْرِ نعمتِه.\n\n﴿وَأَحَلُّواْ﴾: أنْزَلُوا.\n\n﴿دَارَ ٱلۡبَوَارِ﴾: دارَ الهَلاك، وهي جهنمُ."],[29,29,"﴿يَصۡلَوۡنَهَا﴾: يَدْخُلُونها ويُقاسُون حَرَّها.\n\n﴿وَبِئۡسَ ٱلۡقَرَارُ﴾: ساء المستقَرُّ مُسْتَقَرُّهم."],[30,30,"﴿أَندَادࣰا﴾: شركاءَ ونُظَراءَ مع اللهِ في عبادتِه.\n\n﴿تَمَتَّعُواْ﴾: استمتِعُوا بالعيشِ في الحياةِ الدنيا."],[31,31,"﴿لَّا بَيۡعࣱ فِيهِ﴾: لا فِداءٌ فيه، بأن يبيعَ المرءُ ما يَفْدِي به نفسَه.\n\n﴿وَلَا خِلَـٰلٌ﴾: ولا صَداقَةٌ ولا مُوادَّةٌ تنفَعُ."],[32,32,"﴿وَسَخَّرَ لَكُمُ﴾: ذَلَّلَ لمنافِعِكم.\n\n﴿ٱلۡفُلۡكَ﴾: السُّفُنَ."],[33,33,"﴿دَآئِبَيۡنِ﴾: دائمَيْن في حركتِهما، ومنافِعِهما لكم."],[34,34,"﴿نِعۡمَتَ ٱللَّهِ﴾: نِعَمَه عليكم.\n\n﴿لَا تُحۡصُوهَآ﴾: لا تُطِيقوا حَصْرَها ولا القيامَ بشُكْرها؛ لكثرتِها وتنوُّعِها.\n\n﴿كَفَّارࣱ﴾: كثيرُ الجُحودِ لنِعَمِ رَبِّه."],[35,35,"﴿هَـٰذَا ٱلۡبَلَدَ﴾: أي: مكةَ.\n\n﴿وَٱجۡنُبۡنِي﴾: أبْعِدْني."],[36,36,"﴿فَمَن تَبِعَنِي﴾: اقتدى بي في التوحيدِ.\n\n﴿فَإِنَّهُۥ مِنِّي﴾: فهو على ديني وسُنَّتي."],[37,37,"﴿ٱلۡمُحَرَّمِ﴾: الذي يَحْرُمُ عندَه ما لا يَحْرُمُ في غيرِه.\n\n﴿تَهۡوِيٓ إِلَيۡهِمۡ﴾: تَحِنُّ وتُسْرِعُ إليهم شوقًا وحُبًّا."],[39,39,"﴿وَهَبَ لِي﴾: أعطاني ورزقني."],[40,40,"﴿مُقِيمَ ٱلصَّلَوٰةِ﴾: مُحافِظًا عليها، مُداومًا على أدائِها على أتمِّ أحوالِها.\n\n﴿وَتَقَبَّلۡ دُعَآءِ﴾: تقبَّلْ عبادتي، واستجِبْ دعائي."],[41,41,"﴿وَلِوَ ٰ⁠لِدَيَّ﴾: دعا لوالدِه بالمغفرةِ قبلَ أنْ يَتبيَّنَ له عداوتُه للهِ."],[42,42,"﴿تَشۡخَصُ فِيهِ ٱلۡأَبۡصَـٰرُ﴾: تَرْتَفِعُ فيه عيونُ أهلِ الموقفِ، فتبقى مفتوحةً لا تتحَّركُ؛ مِن هَوْلِ ما يَرَوْنه."],[43,43,"﴿مُهۡطِعِينَ﴾: مُسْرِعين إلى إجابةِ الداعي للحسابِ.\n\n﴿مُقۡنِعِي رُءُوسِهِمۡ﴾: رافِعيها من شدَّةِ الخوفِ.\n\n﴿لَا يَرۡتَدُّ إِلَيۡهِمۡ طَرۡفُهُمۡ﴾: لا تَرْجِعُ إليهم أجْفانُهم، بل تبقى عيونُهم مفتوحةً على حالِها.\n\n﴿وَأَفۡـِٔدَتُهُمۡ هَوَآءࣱ﴾: وقلوبُهم خاليةٌ لا تَعي شيئًا؛ من هَوْلِ ما تَرى، وشدَّةِ الدَّهْشةِ."],[44,44,"﴿وَأَنذِرِ﴾: خَوِّف أيُّها الرسولُ.\n\n﴿يَأۡتِيهِمُ ٱلۡعَذَابُ﴾: أي: عذابُ اللهِ يومَ القيامةِ.\n\n﴿أَجَلࣲ قَرِيبࣲ﴾: وقتٍ غيرِ بعيدٍ.\n\n﴿مَا لَكُم مِّن زَوَالࣲ﴾: لا زوالَ لكم عن الحياةِ الدُّنيا إلى الآخرةِ."],[45,45,"﴿وَتَبَيَّنَ لَكُمۡ كَيۡفَ فَعَلۡنَا بِهِمۡ﴾: وعَلِمْتُم بما تشاهدُونه في منازلِهم، وبما أُخْبِرْتُم، ما أنزَلْناه بهم من أنواعِ العقوباتِ."],[46,46,"﴿وَعِندَ ٱللَّهِ مَكۡرُهُمۡ﴾: عِلْمُه وجَزاؤُه.\n\n﴿وَإِن كَانَ مَكۡرُهُمۡ لِتَزُولَ مِنۡهُ ٱلۡجِبَالُ﴾: وما كان تدبيرُهم -وإن عَظُمَ- مُعَدًّا لإزالةِ الجبالِ؛ لضَعْفِه."],[47,47,"﴿وَعۡدِهِۦ رُسُلَهُۥٓ﴾: ما وعَدَهم به من النصرِ والتمكينِ، وإهلاكِ أعدائِهم.\n\n﴿عَزِيزࣱ﴾: غالِبٌ لا يمتنعُ عليه شيءٌ."],[48,48,"﴿وَبَرَزُواْ﴾: خَرَجَ الخَلْقُ من قُبورِهم؛ للحسابِ."],[49,49,"﴿مُّقَرَّنِينَ﴾: مُقَيَّدين، أو مَقْرونًا بعضُهم مع بعضٍ.\n\n﴿ٱلۡأَصۡفَادِ﴾: جَمْعُ صَفَدٍ، وهو ما يُوثَقُ به من القُيودِ."],[50,50,"﴿سَرَابِيلُهُم﴾: ثيابُهم، أو قُمْصانُهم.\n\n﴿قَطِرَانࣲ﴾: دُهْنٍ من عُصارةِ بعضِ الأشجارِ، أسودَ كالزِّفْتِ، وهو نَتِنٌ، حارٌّ، شديدُ الاشتعالِ.\n\n﴿وَتَغۡشَىٰ﴾: تَعْلُو وتُحيطُ."],[52,52,"﴿هَـٰذَا﴾: أي: القرآنُ.\n\n﴿أُوْلُواْ ٱلۡأَلۡبَـٰبِ﴾: أصحابُ العقولِ السليمةِ."]]);
QTF("gharib",15,[[1,1,"﴿مُّبِينࣲ﴾: واضحٍ في معانِيه وأحكامِه."],[2,2,"﴿رُّبَمَا﴾: أي: رُبَّ شيءٍ، وهو حرفٌ يَدُلُّ على أنّ ما بعدَه قليلُ الحصولِ.\n\n﴿يَوَدُّ﴾: يتمنّى."],[3,3,"﴿ذَرۡهُمۡ﴾: اترُكْ أيُّها الرسولُ الكفارَ.\n\n﴿وَيَتَمَتَّعُواْ﴾: يَسْتَمْتِعُوا بعيشِهم في الحياةِ الدنيا.\n\n﴿وَيُلۡهِهِمُ﴾: يَشْغَلْهم.\n\n﴿ٱلۡأَمَلُ﴾: رجاءُ البقاءِ في الدُّنيا والطمعِ فيها."],[4,4,"﴿كِتَابࣱ﴾: أجَلٌ.\n\n﴿مَّعۡلُومࣱ﴾: مُقَدَّرٌ ومُحَدَّدٌ لإهلاكِها."],[5,5,"﴿وَمَا يَسۡتَـٔۡخِرُونَ﴾: لا يتأخَّرُون عن موعدِ هلاكِهم."],[6,6,"﴿ٱلذِّكۡرُ﴾: القرآنُ."],[7,7,"﴿لَّوۡ مَا﴾: هَلّا، حَضُّوه على هذا الفِعْلِ؛ لتشهدَ الملائكةُ على صِدْقِه."],[8,8,"﴿بِٱلۡحَقِّ﴾: بالعذابِ الذي قدَّره اللهُ.\n\n﴿مُّنظَرِينَ﴾: مُؤَخَّرِين ومُمْهَلِين."],[9,9,"﴿لَحَـٰفِظُونَ﴾: نتكَفَّلُ بحِفْظِه من الزيادةِ أو النقصِ أو التحريفِ أو التبديلِ."],[10,10,"﴿شِيَعِ ٱلۡأَوَّلِينَ﴾: فِرَقِ الأمم السابقةِ."],[12,12,"﴿كَذَ ٰ⁠لِكَ﴾: كما أدخَلْنا التكذيبَ والاستهزاءَ في قلوبِ الأممِ السابقةِ.\n\n﴿نَسۡلُكُهُۥ﴾: نُدْخِلُه."],[13,13,"﴿خَلَتۡ﴾: مَضَتْ.\n\n﴿سُنَّةُ ٱلۡأَوَّلِينَ﴾: ما جَرى به قضاءُ الله وحُكْمُه من إهلاكِ المكذِّبين."],[14,14,"﴿يَعۡرُجُونَ﴾: يَصْعَدُون، فيَرَوْن عجائبَ مَلَكوتِ اللهِ."],[15,15,"﴿سُكِّرَتۡ﴾: سُدَّتْ ومُنِعَتْ عن الإبصارِ."],[16,16,"﴿بُرُوجࣰا﴾: منازلَ للكواكبِ السيّارةِ تَنْزِلُ بها."],[17,17,"﴿رَّجِيمٍ﴾: مَرْجومٍ، أي: مَطْرودٍ من رحمةِ اللهِ."],[18,18,"﴿ٱسۡتَرَقَ ٱلسَّمۡعَ﴾: خَطِفَ المسموعَ من كلامِ الملأِ الأعلى.\n\n﴿فَأَتۡبَعَهُۥ﴾: لَحِقَه.\n\n﴿شِهَابࣱ﴾: شُعْلَةُ نارٍ تُرى هابطةً من السماءِ.\n\n﴿مُّبِينࣱ﴾: منيرٌ واضحٌ."],[19,19,"﴿وَٱلۡأَرۡضَ مَدَدۡنَـٰهَا﴾: بَسَطَها اللهُ، وهَيَّأها للاستقرار والعيشِ فيها.\n\n﴿رَوَ ٰ⁠سِيَ﴾: جِبالًا تُثَبِّتُها.\n\n﴿مَّوۡزُونࣲ﴾: مُقَدَّرٍ بمقدارٍ معيَّنٍ."],[20,20,"﴿مَعَـٰيِشَ﴾: ما تَعيشُون به من الأرزاقِ."],[21,21,"﴿عِندَنَا خَزَآئِنُهُۥ﴾: قادِرُون على إيجادِه وتدبيرِه والإنعامِ به من جميعِ الأصنافِ.\n\n﴿بِقَدَرࣲ مَّعۡلُومࣲ﴾: بمقدارٍ مُحَدَّدٍ."],[22,22,"﴿لَوَ ٰ⁠قِحَ﴾: حَواملَ للسَّحابِ ولِلَقاحِ الشجَرِ، أو مُلقِّحاتٍ للسَّحابِ وللأشجارِ.\n\n﴿وَمَآ أَنتُمۡ لَهُۥ بِخَـٰزِنِينَ﴾: لَسْتم بقادرين على حِفْظِ الماءِ وادِّخاره."],[23,23,"﴿ٱلۡوَ ٰ⁠رِثُونَ﴾: للأرضِ ومَن عليها؛ لأنه سبحانه هو الباقي بعد فَناءِ الخَلْقِ."],[24,24,"﴿ٱلۡمُسۡتَقۡدِمِينَ﴾: الذين ماتُوا من لَدُنْ آدمَ عليه السَّلامُ.\n\n﴿ٱلۡمُسۡتَـٔۡخِرِينَ﴾: الأحياءَ، ومَن سيأتي إلى يوم القيامة."],[26,26,"﴿صَلۡصَـٰلࣲ﴾: طينٍ يابسٍ غيرِ مطبوخٍ، يُسْمَعُ له صَلْصَلةٌ، أي: صوتٌ حين النَّقْرِ عليه.\n\n﴿حَمَإࣲ﴾: طينٍ أسودَ.\n\n﴿مَّسۡنُونࣲ﴾: متغيِّرِ اللونِ والرائحةِ، أو مُصَوَّرٍ صورةَ إنسانٍ."],[27,27,"﴿وَٱلۡجَآنَّ﴾: أبا الجنِّ، وهو إبليسُ.\n\n﴿مِن قَبۡلُ﴾: من قَبْلِ خَلْقِ آدمَ.\n\n﴿نَّارِ ٱلسَّمُومِ﴾: نارٍ شديدةِ الحرارةِ لا دُخانَ لها."],[29,29,"﴿سَوَّيۡتُهُۥ﴾: أكمَلْتُ صورتَه، وأتممتُ خَلْقَه.\n\n﴿مِن رُّوحِي﴾: ما به حياتُه بأمري، فصارَ بَشَرًا.\n\n﴿سَـٰجِدِينَ﴾: سجودَ تحيةٍ وتكريمٍ."],[31,31,"﴿أَبَىٰٓ﴾: امتنعَ."],[32,32,"﴿مَا لَكَ﴾: ما مَنعَكَ."],[34,34,"﴿رَجِيمࣱ﴾: مَرْجُومٌ، أي: مَطْرودٌ من رحمةِ اللهِ."],[35,35,"﴿ٱللَّعۡنَةَ﴾: غَضَبَ اللهِ وسُخْطَه، والبعدَ من رحمتِه.\n\n﴿ٱلدِّينِ﴾: الجزاءِ والحِسابِ."],[36,36,"﴿فَأَنظِرۡنِيٓ﴾: أخِّرْني وأمْهِلْني."],[38,38,"﴿ٱلۡوَقۡتِ ٱلۡمَعۡلُومِ﴾: حين تموتُ الخلائقُ، وهو النَّفْخَةُ الأولى."],[39,39,"﴿بِمَآ أَغۡوَيۡتَنِي﴾: فبسببِ إضلالِك لي.\n\n﴿لَأُزَيِّنَنَّ لَهُمۡ﴾: لَأُحَسِّنَنَّ لذريَّةِ آدمَ المعاصيَ.\n\n﴿وَلَأُغۡوِيَنَّهُمۡ﴾: لَأَحْمِلنَّهم على تَرْكِ الهدى والرَّشادِ."],[40,40,"﴿ٱلۡمُخۡلَصِينَ﴾: المختارِين من عبادِك لطاعتِك."],[41,41,"﴿صِرَ ٰ⁠طٌ عَلَيَّ﴾: طريقٌ حقٌّ عليَّ أن أُراعِيَه."],[42,42,"﴿سُلۡطَـٰنٌ﴾: تَسَلُّطٌ.\n\n﴿ٱلۡغَاوِينَ﴾: الضالِّين والمُشْركين."],[44,44,"﴿جُزۡءࣱ مَّقۡسُومٌ﴾: نصيبٌ معيَّنٌ مَتميِّزٌ عن غيرِه بحسَبِ أعمالِهم."],[46,46,"﴿بِسَلَـٰمٍ﴾: سالمين من كلِّ سوءٍ."],[47,47,"﴿وَنَزَعۡنَا﴾: أذْهَبَ الله تعالى.\n\n﴿غِلٍّ﴾: حِقْدٍ وعَداوةٍ كانَتْ من بعضِهم في الدُّنيا.\n\n﴿مُّتَقَـٰبِلِينَ﴾: تتقابلُ وُجوهُهم؛ لمِا هم فيه من المحبةِ والتواصُلِ."],[48,48,"﴿نَصَبࣱ﴾: تَعَبٌ وإعياءٌ."],[49,49,"﴿نَبِّئۡ﴾: أخْبِرْ."],[50,50,"﴿ٱلۡأَلِيمُ﴾: المؤلمُ الموجِعُ."],[51,51,"﴿ضَيۡفِ إِبۡرَ ٰ⁠هِيمَ﴾: ضيوفِه عليه السلامُ من الملائكةِ الكرامِ."],[52,52,"﴿وَجِلُونَ﴾: خائفون فَزِعُون."],[53,53,"﴿عَلِيمࣲ﴾: ذي عِلْمٍ كثيرٍ، وهو إسحاقُ."],[54,54,"﴿عَلَىٰٓ أَن مَّسَّنِيَ ٱلۡكِبَرُ﴾: مع حالةِ كِبَرِ السِّنِّ."],[55,55,"﴿بِٱلۡحَقِّ﴾: بالخبرِ اليقينِ الذي لا شَكَّ فيه.\n\n﴿ٱلۡقَـٰنِطِينَ﴾: اليائسين من الوَلَدِ."],[56,56,"﴿ٱلضَّآلُّونَ﴾: البعيدون عن الحقِّ والصَّوابِ."],[57,57,"﴿فَمَا خَطۡبُكُمۡ﴾: ما أمْرُكم الخطيرُ الذي جِئْتُم من أجلِه؟"],[59,59,"﴿إِلَّآ ءَالَ لُوطٍ﴾: إلّا لوطًا وأهلَه المؤمنين به."],[60,60,"﴿قَدَّرۡنَآ﴾: قَضَيْنا وحَكَمْنا بأمرِ اللهِ.\n\n﴿ٱلۡغَـٰبِرِينَ﴾: الباقين في العذابِ."],[61,61,"﴿ءَالَ لُوطٍ﴾: أي: لوطًا عليه السلامُ."],[62,62,"﴿قَوۡمࣱ مُّنكَرُونَ﴾: لا أعْرِفُكم."],[63,63,"﴿فِيهِ يَمۡتَرُونَ﴾: يَشُكُّون في نزول العذاب بهم."],[64,64,"﴿بِٱلۡحَقِّ﴾: بالخبرِ اليقينِ الذي لا شَكَّ فيه."],[65,65,"﴿فَأَسۡرِ بِأَهۡلِكَ﴾: فاخرُجْ أنت وأهلُك المؤمنون.\n\n﴿بِقِطۡعࣲ مِّنَ ٱلَّيۡلِ﴾: بآخِر الليلِ.\n\n﴿وَٱتَّبِعۡ أَدۡبَـٰرَهُمۡ﴾: وسِرْ أنت وراءهم؛ لئلا يَتَخَلَّفَ منهم أحدٌ فيَهْلِكَ."],[66,66,"﴿وَقَضَيۡنَآ إِلَيۡهِ﴾: أوْحَيْنا إلى لوطٍ.\n\n﴿دَابِرَ هَـٰٓؤُلَآءِ مَقۡطُوعࣱ﴾: آخرَهم، والمرادُ: جميعُ قومِك مُهْلَكون، لايبقى منهم أحدٌ.\n\n﴿مُّصۡبِحِينَ﴾: وقتَ الصباحِ."],[67,67,"﴿يَسۡتَبۡشِرُونَ﴾: يُظْهِرُون سرورَهم؛ طَمَعًا في فِعْل الفاحِشَةِ."],[68,68,"﴿ضَيۡفِي﴾: ضُيوفي.\n\n﴿فَلَا تَفۡضَحُونِ﴾: لا تُظْهروا ما يُوجبُ العارَ لي."],[69,69,"﴿وَلَا تُخۡزُونِ﴾: لا تُوقعوني في الذُّل والهَوانِ؛ بإيذائِكم لضيوفي."],[70,70,"﴿عَنِ ٱلۡعَـٰلَمِينَ﴾: عن ضيافَةِ أحدٍ من الناسِ أو حمايتهِ."],[71,71,"﴿هَـٰٓؤُلَآءِ بَنَاتِيٓ﴾: نساؤُكم بناتي فتزوَّجوهنَّ."],[72,72,"﴿لَعَمۡرُكَ﴾: قَسَمٌ من اللهِ بحياةِ النبيِّ عليه الصلاة والسلام؛ تشريفًا له.\n\n﴿سَكۡرَتِهِمۡ﴾: ضَلالَتِهم وشِدَّةِ محبَّتِهم الفاحشةَ التي أزالَتْ عقولَهم.\n\n﴿يَعۡمَهُونَ﴾: يترَدَّدُون مُتَحَيِّرين."],[73,73,"﴿ٱلصَّيۡحَةُ﴾: الصوتُ الشديدُ المُهْلِكُ.\n\n﴿مُشۡرِقِينَ﴾: وقتَ شُروقِ الشمسِ."],[74,74,"﴿وَأَمۡطَرۡنَا﴾: أرسَلْنا.\n\n﴿سِجِّيلٍ﴾: طينٍ مُتَحَجِّرِ."],[75,75,"﴿لَـَٔايَـٰتࣲ﴾: لَدلائلَ وعِظاتٍ.\n\n﴿لِّلۡمُتَوَسِّمِينَ﴾: الناظرين المُعْتَبِرين."],[76,76,"﴿وَإِنَّهَا﴾: قُرى قومِ لوطٍ.\n\n﴿لَبِسَبِيلࣲ﴾: طريقٍ.\n\n﴿مُّقِيمٍ﴾: ثابتٍ واضحٍ، يَمُرُّ بها الناسُ ويَرَوْن آثارَها."],[77,77,"﴿لَـَٔايَةࣰ﴾: لَدلالةً وعِبْرَةً."],[78,78,"﴿أَصۡحَـٰبُ ٱلۡأَيۡكَةِ﴾: سكانُ مِنطَقَةِ الشجرِ الكثيرِ المُلتفِّ، وهم قومُ شعيبٍ عليه السلام."],[79,79,"﴿وَإِنَّهُمَا﴾: قرى قومِ لوطٍ، ومساكنَ قومِ شعيبٍ.\n\n﴿لَبِإِمَامࣲ مُّبِينࣲ﴾: طريقٍ واضحٍ، يَأْتمُّ به أهلُ القوافل، ويَسْلُكونه في سَفَرهم."],[80,80,"﴿أَصۡحَـٰبُ ٱلۡحِجۡرِ﴾: سكانُ وادٍ بين المدينةِ والشّامِ، وهم ثمودُ.\n\n﴿ٱلۡمُرۡسَلِينَ﴾: أي: صالحًا؛ لأنّ مَن كذَّبَ نبيًّا فقد كَذَّبهم جميعًا."],[81,81,"﴿ءَايَـٰتِنَا﴾: أدلَّتَنا وحُجَجَنا الدالَّهَ على صِدْقِ نبيِّهم، ومنها الناقةُ.\n\n﴿مُعۡرِضِينَ﴾: صادِّين عنها، لا يتفكرون."],[83,83,"﴿ٱلصَّيۡحَةُ﴾: الصوتُ الشديدُ المُهلِكُ.\n\n﴿مُصۡبِحِينَ﴾: وقتَ الصَّباحِ."],[84,84,"﴿فَمَآ أَغۡنَىٰ﴾: ما دَفَعَ عنهم العذابَ.\n\n﴿مَّا كَانُواْ يَكۡسِبُونَ﴾: ما حَصَّلُوه من بناءِ البيوتِ والحُصونِ في الجبالِ، وجَمْعِ الأموالِ."],[85,85,"﴿ٱلصَّفۡحَ ٱلۡجَمِيلَ﴾: أي: الحَسَنَ، الذي لا أذِيَّةَ فيه."],[87,87,"﴿سَبۡعࣰا مِّنَ ٱلۡمَثَانِي﴾: الفاتحةَ، وهي سبعُ آياتٍ تتكرَّر في كلِّ صلاةٍ."],[88,88,"﴿لَا تَمُدَّنَّ عَيۡنَيۡكَ﴾: لا تَطْمَحْ ببصَرِك.\n\n﴿إِلَىٰ مَا مَتَّعۡنَا بِهِۦٓ﴾: إلى ما عندَ غيرِك من حُطامِ الدنيا وزِينتِها.\n\n﴿أَزۡوَ ٰ⁠جࣰا﴾: أصنافًا.\n\n﴿وَٱخۡفِضۡ جَنَاحَكَ﴾: وتواضَعْ وأَلِنْ جانبَك."],[90,90,"﴿كَمَآ أَنزَلۡنَا﴾: أُنذِرُكم عذابَ اللهِ كما أنزلَه.\n\n﴿ٱلۡمُقۡتَسِمِينَ﴾: اليهودِ والنصارى وغيرِهم الذين قسَّمُوا القرآنَ، فآمنوا ببعضِه وكفرُوا ببعضٍ."],[91,91,"﴿عِضِينَ﴾: أجزاءً وأقسامًا؛ ليوافِقَ أهواءَهم."],[92,92,"﴿لَنَسۡـَٔلَنَّهُمۡ﴾: سُؤالَ توبيخٍ، فلَنُحاسِبَنَّهم ولَنَجْزِيَنَّهم."],[94,94,"﴿فَٱصۡدَعۡ بِمَا تُؤۡمَرُ﴾: اجهَرْ بدعوةِ الحقِّ وأظْهِرْها."],[97,97,"﴿يَضِيقُ صَدۡرُكَ﴾: يَنْقَبِضُ ألمًا وحُزْنًا."],[98,98,"﴿ٱلسَّـٰجِدِينَ﴾: المُصَلِّين العابِدين."],[99,99,"﴿ٱلۡيَقِينُ﴾: الموتُ، المتيقَّنُ حُدوثُه."]]);
QTF("gharib",16,[[1,1,"﴿أَتَىٰٓ﴾: قَرُبَ ودَنا.\n\n﴿أَمۡرُ ٱللَّهِ﴾: عقابُه للمُشْركين، أو القيامةُ.\n\n﴿سُبۡحَـٰنَهُۥ﴾: تنزيهًا لله."],[2,2,"﴿بِٱلرُّوحِ﴾: بالوَحْي؛ الذي فيه الحياةُ التامَّةُ.\n\n﴿مِنۡ عِبَادِهِۦٓ﴾: الذين اختصَّهم بالرسالة.\n\n﴿أَنذِرُوٓاْ﴾: خَوِّفُوا."],[4,4,"﴿نُّطۡفَةࣲ﴾: ماءِ الحياةِ، وهو المَنِيُّ.\n\n﴿خَصِيمࣱ﴾: شديدُ الخصومةِ والمجادَلةِ.\n\n﴿مُّبِينࣱ﴾: بيِّنُ الخُصومةِ واضحُها."],[5,5,"﴿وَٱلۡأَنۡعَـٰمَ﴾: هي الإبِلُ والبَقَرُ والغنم.\n\n﴿دِفۡءࣱ﴾: ما تَسْتَدْفِئُون به مِن صوفِها ووَبَرِها وشَعْرِها."],[6,6,"﴿جَمَالٌ﴾: زينةٌ تَسُرُّكم.\n\n﴿تُرِيحُونَ﴾: تَرُدُّونها في المساء إلى حَظائرِها.\n\n﴿تَسۡرَحُونَ﴾: تُخْرِجُونها في الصَّباح إلى مَراعِيها."],[7,7,"﴿أَثۡقَالَكُمۡ﴾: أمتعتَكم الثقيلةَ.\n\n﴿بِشِقِّ ٱلۡأَنفُسِ﴾: بجُهْدٍ شديدٍ ومشَقَّةٍ زائدةٍ عليها."],[8,8,"﴿وَزِينَةࣰ﴾: لتتزيَّنُوا بها حالَ ركوبِها، وحالَ جَمالِ منظرها."],[9,9,"﴿قَصۡدُ ٱلسَّبِيلِ﴾: بيانُ الطَّريقِ المستقيمِ، وهو الإسلامُ.\n\n﴿جَآئِرࣱ﴾: مائلٌ عن الاستقامةِ، وهو ما خالَفَ الإسلامَ."],[10,10,"﴿تُسِيمُونَ﴾: تَرعَوْن دَوابَّكم."],[11,11,"﴿لَـَٔايَةࣰ﴾: دلالةً واضحةً."],[12,12,"﴿وَسَخَّرَ لَكُمُ﴾: ذلَّلَ لمنافعِكم."],[13,13,"﴿ذَرَأَ﴾: خَلَقَ."],[14,14,"﴿لَحۡمࣰا طَرِيࣰّا﴾: هو السَّمَكُ.\n\n﴿حِلۡيَةࣰ﴾: ما تتحَلّى به النِّساءُ وتَتَزَيَّنُ، كاللؤلؤِ والمَرْجانِ.\n\n﴿ٱلۡفُلۡكَ﴾: السُّفُنَ.\n\n﴿مَوَاخِرَ فِيهِ﴾: تَشُقُّ الماءَ بجَرْيِها فيه ذَهابًا ورُجوعًا."],[15,15,"﴿رَوَ ٰ⁠سِيَ﴾: جبالًا ثوابِتَ.\n\n﴿أَن تَمِيدَ بِكُمۡ﴾: حتى لا تَمِيلَ بكم وتضطربَ.\n\n﴿وَسُبُلࣰا﴾: طُرُقًا.\n\n﴿تَهۡتَدُونَ﴾: إلى مقاصِدِكم."],[16,16,"﴿وَعَلَـٰمَـٰتࣲ﴾: معالمَ تَسْتَدِلُّون بها على الطُّرُقِ نهارًا."],[17,17,"﴿أَفَمَن يَخۡلُقُ﴾: وهو اللهُ تعالى.\n\n﴿كَمَن لَّا يَخۡلُقُ﴾: أتَجْعَلُونه في استحقاقِ العبادةِ كالآلهةِ المزعومةِ التي لا تملِك شيئًا؟"],[18,18,"﴿نِعۡمَةَ ٱللَّهِ﴾: نِعَمَه عليكم.\n\n﴿لَا تُحۡصُوهَآ﴾: لا تُطيقوا حَصْرَها ولا القيامَ بشُكْرها؛ لكثرتِها وتَنَوُّعِها."],[19,19,"﴿مَا تُسِرُّونَ﴾: ما تُخْفُونَه من أقوالِكم وأعمالِكم."],[21,21,"﴿أَيَّانَ﴾: وقتَ.\n\n﴿يُبۡعَثُونَ﴾: يُحْيَوْن مِن قُبورِهم."],[22,22,"﴿قُلُوبُهُم مُّنكِرَةࣱ﴾: جاحدةٌ وحدانيةَ اللهِ."],[23,23,"﴿لَا جَرَمَ﴾: حَقًّا، أو لا مَحالةَ."],[24,24,"﴿أَسَـٰطِيرُ ٱلۡأَوَّلِينَ﴾: جَمْعُ أُسْطورة، وهي: ما سُطِّرَ في كتب السابقينَ من الأخبارِ المكذوبةِ."],[25,25,"﴿أَوۡزَارَهُمۡ﴾: آثامَ ضلالِهم.\n\n﴿مَا يَزِرُونَ﴾: ما يَحْمِلُونه من آثامٍ."],[26,26,"﴿مَكَرَ﴾: دَبَّرَ في حِيلةٍ وخَفاءٍ.\n\n﴿فَأَتَى ٱللَّهُ بُنۡيَـٰنَهُم﴾: أهْلكَه وأفْناه.\n\n﴿مِّنَ ٱلۡقَوَاعِدِ﴾: من أساسِه.\n\n﴿فَخَرَّ﴾: سَقَطَ.\n\n﴿حَيۡثُ لَا يَشۡعُرُونَ﴾: من مَأْمَنِهم، ومن جهةٍ لا تَخْطُرُ ببالِهم."],[27,27,"﴿يُخۡزِيهِمۡ﴾: يُذِلُّهم اللهُ ويُهينُهم بالعذابِ.\n\n﴿شُرَكَآءِيَ﴾: الآلهةُ التي عَبَدْتُموها من دوني.\n\n﴿تُشَـٰٓقُّونَ فِيهِمۡ﴾: تُخاصِمُون وتُعادُون الأنبياءَ وأتباعَهم في شأنهم.\n\n﴿ٱلۡخِزۡيَ﴾: الذُّلَّ والهَوانَ.\n\n﴿وَٱلسُّوٓءَ﴾: العذابَ."],[28,28,"﴿تَتَوَفَّىٰهُمُ ٱلۡمَلَـٰٓئِكَةُ﴾: تَقْبِضُ أرواحَهم.\n\n﴿فَأَلۡقَوُاْ ٱلسَّلَمَ﴾: استَسْلَمُوا لأمرِ اللهِ حين رَأَوا الموتَ."],[29,29,"﴿مَثۡوَى ٱلۡمُتَكَبِّرِينَ﴾: مَأْواهم ومَقَرُّهم."],[30,30,"﴿حَسَنَةࣱ﴾: مَكْرُمَةٌ من اللهِ بالعيشِ الهنيءِ والرِّزقِ الواسعِ."],[31,31,"﴿جَنَّـٰتُ عَدۡنࣲ﴾: جناتُ إقامةٍ.\n\n﴿مِن تَحۡتِهَا﴾: من تحتِ قُصورِها وأشجارِها."],[32,32,"﴿طَيِّبِينَ﴾: طاهِرين زاكِيَةً أفعالُهم وأقوالُهم.\n\n﴿سَلَـٰمٌ عَلَيۡكُمُ﴾: تحيةٌ خاصةٌ بكم، وسَلِمْتُم من كلِّ آفةٍ."],[33,33,"﴿هَلۡ يَنظُرُونَ﴾: ما ينتظِرُ الكفارُ.\n\n﴿تَأۡتِيَهُمُ ٱلۡمَلَـٰٓئِكَةُ﴾: لقَبْضِ أرواحِهم.\n\n﴿أَمۡرُ رَبِّكَ﴾: عذابُ الاستئصالِ في الدنيا، أو القيامةُ التي فيها عذابُهم."],[34,34,"﴿وَحَاقَ﴾: نَزَلَ وأحاطَ."],[35,35,"﴿كَذَ ٰ⁠لِكَ فَعَلَ ٱلَّذِينَ مِن قَبۡلِهِمۡ﴾: بمِثْلِ هذا الاحتجاجِ الباطلِ احتجَّ الكفارُ السابقون."],[36,36,"﴿ٱلطَّـٰغُوتَ﴾: كلَّ معبودٍ باطلٍ، كالشيطانِ والأوثانِ والأمواتِ، وكلَّ داعٍ إلى ضَلالٍ.\n\n﴿حَقَّتۡ﴾: وجَبَتْ."],[38,38,"﴿جَهۡدَ أَيۡمَـٰنِهِمۡ﴾: غايةَ اجتهادِهم بالأيمانِ المؤكَّدةِ."],[39,39,"﴿لِيُبَيِّنَ لَهُمُ﴾: أي: يَبْعَثُ اللهُ جميعَ العبادِ؛ ليُظْهِرَ لهم حقيقةَ البعثِ."],[41,41,"﴿لَنُبَوِّئَنَّهُمۡ﴾: لَنُنْزِلَنَّهم.\n\n﴿حَسَنَةࣰ﴾: دارًا حسنةً، أو رزقًا واسعًا وعَيْشًا هنيئًا."],[42,42,"﴿يَتَوَكَّلُونَ﴾: يعتمدون عليه ويُفَوِّضُون أمرَهم إليه."],[43,43,"﴿أَهۡلَ ٱلذِّكۡرِ﴾: العلماءَ من أهلِ الكتبِ السابقةِ."],[44,44,"﴿بِٱلۡبَيِّنَـٰتِ﴾: وأرسَلْنا الرسلَ بالمعجزاتِ الواضحةِ الدالَّةِ على صِدْقِهم.\n\n﴿وَٱلزُّبُرِ﴾: وبالكتبِ المنزَّلةِ، المتضمِّنةِ للشرائعِ.\n\n﴿ٱلذِّكۡرَ﴾: القرآنَ؛ لما فيه من الموعظةِ والتنبيهِ."],[45,45,"﴿مَكَرُواْ ٱلسَّيِّـَٔاتِ﴾: دبَّروا المكايدَ بخَفاءٍ، وأشركوا مع اللهِ.\n\n﴿يَخۡسِفَ﴾: يُغيِّبَ."],[46,46,"﴿تَقَلُّبِهِمۡ﴾: أسفارِهم وتصرُّفِهم في أمورِهم.\n\n﴿بِمُعۡجِزِينَ﴾: بفائتين اللهَ بالفِرارِ من عَذابِه."],[47,47,"﴿عَلَىٰ تَخَوُّفࣲ﴾: على تَنَقُّصٍ شيئًا فشيئًا في الأموالِ والأنفسِ والثمراتِ حتى يَهْلِكُوا، أو على مخافَةٍ من العَذابِ."],[48,48,"﴿مِن شَيۡءࣲ﴾: أي: له ظِلٌّ، كالجبالِ والشجَرِ.\n\n﴿يَتَفَيَّؤُاْ ظِلَـٰلُهُ﴾: يَميلُ ظِلُّ الأشياءِ وينتقلُ من جانبٍ إلى آخَر.\n\n﴿سُجَّدࣰا لِّلَّهِ﴾: مُنْقادةً خاضعةً لعَظَمَةِ رِّبها، وتسخيرِه.\n\n﴿دَ ٰ⁠خِرُونَ﴾: أذلّاءُ مُنقادُون لحُكم الله تعالى."],[49,49,"﴿يَسۡجُدُ﴾: سجودَ طاعةٍ وعبادةٍ، أو سُجودَ تسخيرٍ وخضوعٍ.\n\n﴿دَآبَّةࣲ﴾: كلِّ حَيَوانٍ يمشي -على هيئته- على الأرضِ."],[51,51,"﴿لَا تَتَّخِذُوٓاْ﴾: لا تَعْبُدوا.\n\n﴿فَٱرۡهَبُونِ﴾: خافونِ دونَ غيري."],[52,52,"﴿وَلَهُ ٱلدِّينُ﴾: وللهِ وحدَه العبادةُ والإخلاصُ.\n\n﴿وَاصِبًا﴾: دائمًا، أو واجبًا لازمًا."],[53,53,"﴿مَسَّكُمُ﴾: أصابكم.\n\n﴿ٱلضُّرُّ﴾: سوءُ الحالِ بنَقْصٍ في الأموالِ أو الأنفسِ أو الثمراتِ.\n\n﴿تَجۡـَٔرُونَ﴾: ترفعونَ أصواتَكم بالدُّعاءِ والاستغاثةِ."],[55,55,"﴿بِمَآ ءَاتَيۡنَـٰهُمۡ﴾: من النِّعَمِ.\n\n﴿فَتَمَتَّعُواْ﴾: عِيشُوا في أمْنٍ وسلامةٍ، والتَذُّوا بالدنيا، والمرادُ التهديدُ."],[56,56,"﴿وَيَجۡعَلُونَ﴾: ويجعلُ المشركون على وجْهِ التقرُّبِ.\n\n﴿لِمَا لَا يَعۡلَمُونَ﴾: لآلهتِهم التي لا عِلْمَ لها، ولا تنفعُ ولا تَضُرُّ.\n\n﴿تَفۡتَرُونَ﴾: تَكْذِبُون على الله من الباطِلِ."],[57,57,"﴿مَّا يَشۡتَهُونَ﴾: ما يُحِبُّون من البنين."],[58,58,"﴿كَظِيمࣱ﴾: ممتلِئٌ غَمًّا وحُزْنًا وغَضَبًا."],[59,59,"﴿يَتَوَ ٰ⁠رَىٰ مِنَ ٱلۡقَوۡمِ﴾: يَسْتَخْفي من قومِه؟\n\n﴿أَيُمۡسِكُهُۥ﴾: أيُبقي مَوْلُودَه الأنثى حيًا.\n\n﴿هُونٍ﴾: ذُلٍّ وهَوانٍ.\n\n﴿يَدُسُّهُۥ﴾: يُخْفِيه، فَيدْفِنُه حيًّا حتى يموتَ."],[60,60,"﴿مَثَلُ ٱلسَّوۡءِ﴾: الصِّفةُ القبيحةُ من كراهةِ البناتِ، والجهلِ، والكفرِ باللهِ.\n\n﴿وَلِلَّهِ ٱلۡمَثَلُ ٱلۡأَعۡلَىٰ﴾: الصفةُ العُليا من استحقاقِ العبوديةِ، والكمالِ، والجلالِ، والغنى، والجودِ."],[61,61,"﴿أَجَلࣲ مُّسَمࣰّى﴾: وقتٍ محدَّدٍ هو نهايةُ آجالِهم.\n\n﴿وَلَا يَسۡتَقۡدِمُونَ﴾: لا يَتَقَدَّمون عليه."],[62,62,"﴿مَا يَكۡرَهُونَ﴾: ما لا يُحبون نِسْبتَه إلى أنفسِهم من البناتِ.\n\n﴿وَتَصِفُ﴾: تقولُ.\n\n﴿ٱلۡحُسۡنَىٰ﴾: حُسْنَ العاقبةِ.\n\n﴿لَا جَرَمَ﴾: حقًّا، أو لا مَحالةَ.\n\n﴿مُّفۡرَطُونَ﴾: مَتْرُوكون مَنسِيُّون فيها أبدًا."],[63,63,"﴿فَزَيَّنَ﴾: حَسَّنَ.\n\n﴿وَلِيُّهُمُ ٱلۡيَوۡمَ﴾: مُتَوَلٍّ إغواءَهم في الدنيا."],[64,64,"﴿ٱلۡكِتَـٰبَ﴾: القرآنَ العظيمَ.\n\n﴿لِتُبَيِّنَ لَهُمُ﴾: لتُوَضِّحَ للناسِ."],[65,65,"﴿لَـَٔايَةࣰ﴾: دليلًا وحُجَّةً على قُدرةِ الله."],[66,66,"﴿ٱلۡأَنۡعَـٰمِ﴾: وهي: الإبِلُ والبَقَرُ والغَنَمُ.\n\n﴿لَعِبۡرَةࣰ﴾: لعِظَةً.\n\n﴿فَرۡثࣲ﴾: خُلاصةِ المأكول في الكَرِشِ والأمعاءِ.\n\n﴿خَالِصࣰا﴾: مُصَفّى من جميعِ الشوائبِ.\n\n﴿سَآئِغࣰا﴾: سهلَ المُرورِ في الحَلْقِ، هنيئًا."],[67,67,"﴿سَكَرࣰا﴾: خَمْرًا (وهذا امتنانٌ قبلَ التحريمِ)."],[68,68,"﴿وَأَوۡحَىٰ﴾: وألْهَمَ.\n\n﴿وَمِمَّا يَعۡرِشُونَ﴾: وفيما يَبْنيه الناسُ من البيوتِ والخَلايا."],[69,69,"﴿سُبُلَ رَبِّكِ﴾: طُرُقَه التي ألْهَمكِ؛ لامتصاصِ ما في أزهارِ الثمار.\n\n﴿ذُلُلࣰا﴾: مُذَلَّلةً لكِ لا عُسْرَ فيها.\n\n﴿شَرَابࣱ﴾: هو العَسَلُ."],[70,70,"﴿يَتَوَفَّىٰكُمۡ﴾: يُميتكُم عندَ نهايةِ أعمارِكم.\n\n﴿أَرۡذَلِ ٱلۡعُمُرِ﴾: أردَئهِ وأحقَرِه، وهو وقتُ الهَرَمِ."],[71,71,"﴿فَهُمۡ فِيهِ سَوَآءٌ﴾: فهم لا يَرْضَوْن بالتساوي في الرزقِ، فكيف رَضُوا أن يَجْعلوا للهِ شركاءَ من عبيدِه؟"],[72,72,"﴿وَحَفَدَةࣰ﴾: جَمْعَ حَفِيدٍ، أي: أولادَ الأولادِ، أو أعوانًا وخَدَمًا."],[74,74,"﴿فَلَا تَضۡرِبُواْ لِلَّهِ ٱلۡأَمۡثَالَ﴾: لا تَجْعَلُوا للهِ أشباهًا مماثِلين له مِن خَلْقِه، تُشْرِكُونهم معه في العبادةِ."],[75,75,"﴿هَلۡ يَسۡتَوُۥنَ﴾: لا، فكذلك اللهُ المالكُ مع عبيدِه، فكيف تُسَوُّون بينَهما؟"],[76,76,"﴿أَبۡكَمُ﴾: أخْرَسُ منذُ ولادَتِه.\n\n﴿كَلٌّ﴾: عِبْءٌ يعتَمِدُ على غيرِه في معيشَتِه.\n\n﴿مَوۡلَىٰهُ﴾: مَن يلي أمرَه ويَعُولُه.\n\n﴿بِٱلۡعَدۡلِ﴾: بالحقِّ وعبادةِ اللهِ.\n\n﴿صِرَ ٰ⁠طࣲ﴾: طريقٍ."],[77,77,"﴿غَيۡبُ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ﴾: عِلْمُ ما غابَ فيهما.\n\n﴿كَلَمۡحِ ٱلۡبَصَرِ﴾: كنَظْرَةٍ سريعةٍ بالبَصَرِ."],[79,79,"﴿مُسَخَّرَ ٰ⁠تࣲ﴾: مُذَلَّلاتٍ للطَّيَرانِ."],[80,80,"﴿سَكَنࣰا﴾: مَسْكَنًا واستقرارًا لكم.\n\n﴿بُيُوتࣰا﴾: كالخِيام.\n\n﴿تَسۡتَخِفُّونَهَا﴾: تَجِدُونها خفيفةَ الحَمْلِ والنَّقْلِ.\n\n﴿يَوۡمَ ظَعۡنِكُمۡ﴾: وقتَ سَفَرِكم.\n\n﴿وَمِنۡ أَصۡوَافِهَا﴾: أي: أصوافِ الضَّأنِ.\n\n﴿وَأَوۡبَارِهَا﴾: أي: أوبارِ الإبِل، وهو ما يَعْلُو أجسادَها.\n\n﴿وَأَشۡعَارِهَآ﴾: أي: أشعارِ المَعْزِ.\n\n﴿أَثَـٰثࣰا﴾: مَتاعًا لبيوتِكم، كالأغطيةِ والفُرُشِ.\n\n﴿وَمَتَـٰعًا﴾: ما تتمتَّعُون وتنتفِعُون به.\n\n﴿إِلَىٰ حِينࣲ﴾: إلى وقتٍ محدَّدٍ في الدنيا."],[81,81,"﴿ظِلَـٰلࣰا﴾: ما تَسْتظِلُّون به من شدَّةِ الحرِّ.\n\n﴿أَكۡنَـٰنࣰا﴾: أماكنَ وِقايةٍ وسِتْرٍ، كالكهوفِ.\n\n﴿سَرَ ٰ⁠بِيلَ﴾: كلَّ ما يُلْبَس من ثيابٍ أو دُروعٍ.\n\n﴿بَأۡسَكُمۡ﴾: الشدَّةَ في حروبِكم، كالطَّعْنِ والضَّرْبِ والشَّظايا.\n\n﴿تُسۡلِمُونَ﴾: تَنقادُون وتَخْضَعُون لأمرِ اللهِ وحُكْمِه."],[82,82,"﴿تَوَلَّوۡاْ﴾: أعْرَضُوا.\n\n﴿ٱلۡمُبِينُ﴾: الواضحُ."],[84,84,"﴿شَهِيدࣰا﴾: هو رسولُهم يَشْهَدُ على مَن آمَنَ منهم، وعلى مَن كَفَرَ.\n\n﴿لَا يُؤۡذَنُ لِلَّذِينَ كَفَرُواْ﴾: بالاعتذار عَمّا وقَعَ منهم.\n\n﴿وَلَا هُمۡ يُسۡتَعۡتَبُونَ﴾: لا يُطْلَبُ منهم العُتْبى، أي: الرجوعُ إلى ما يُرْضي اللهَ من التوبةِ والعملِ الصّالحِ."],[85,85,"﴿يُنظَرُونَ﴾: يُمْهَلُون ويُؤَخَّرون عنه."],[86,86,"﴿شُرَكَآءَهُمۡ﴾: آلهتَهم المزعومةَ.\n\n﴿نَدۡعُواْ﴾: نعبدُ.\n\n﴿فَأَلۡقَوۡاْ إِلَيۡهِمُ ٱلۡقَوۡلَ﴾: رَدَّتِ الآلهةُ على عابدِيها قائلين."],[87,87,"﴿وَأَلۡقَوۡاْ إِلَى ٱللَّهِ يَوۡمَئِذٍ ٱلسَّلَمَ﴾: أظهرَ المشركونَ خُضوعَهم وانقيادَهم للهِ يومَ القيامةِ.\n\n﴿وَضَلَّ﴾: غابَ وضاعَ.\n\n﴿يَفۡتَرُونَ﴾: يختلِقُونَه مِن الأكاذيبِ."],[89,89,"﴿شَهِيدًا عَلَىٰ هَـٰٓؤُلَآءِ﴾: تَشْهَدُ على أمَّتِك أنكَ بَلَّغْتَهم رسالةَ ربِّك.\n\n﴿ٱلۡكِتَـٰبَ﴾: القرآنَ.\n\n﴿تِبۡيَـٰنࣰا﴾: بَيانًا وتوضيحًا.\n\n﴿لِّكُلِّ شَيۡءࣲ﴾: مما يَحْتاجُ إليه الناسُ من أمورِ الشريعةِ."],[90,90,"﴿بِٱلۡعَدۡلِ﴾: بالتوسُّطِ والإنصافِ في الأمور.\n\n﴿وَٱلۡإِحۡسَـٰنِ﴾: كمالِ العملِ وإتقانِه، وإيصالِ النفعِ إلى الخَلْقِ.\n\n﴿وَإِيتَآيِٕ ذِي ٱلۡقُرۡبَىٰ﴾: إعطاءِ القَرابةِ حَقَّهم من الصِّلةِ والبِرِّ.\n\n﴿ٱلۡفَحۡشَآءِ﴾: ما عَظُمَ قُبْحُه من الذنوبِ قولًا أو فعلًا.\n\n﴿وَٱلۡبَغۡيِ﴾: ظُلْمِ الناسِ وتجاوُزِ الحَدِّ في الاستعلاءِ والتعدِّي عليهم."],[91,91,"﴿بِعَهۡدِ ٱللَّهِ﴾: ما يَلْتَزِمُه المسلمُ باختيارِه بينَه وبينَ اللهِ، أو بينَ الناسِ.\n\n﴿وَلَا تَنقُضُواْ ٱلۡأَيۡمَـٰنَ﴾: لا تُبْطِلُوها وتَتْرُكُوا العَمَلَ بمُقْتضاها.\n\n﴿كَفِيلًا﴾: رَقيبًا أو ضامِنًا."],[92,92,"﴿غَزۡلَهَا﴾: ما فَتَلَتْه من صُوفٍ ونحوِه.\n\n﴿أَنكَـٰثࣰا﴾: جَمْعُ نِكْثٍ، وهو: ما حُلَّ فَتْلُه؛ ليُغْزَلَ ثانيةً.\n\n﴿دَخَلَۢا بَيۡنَكُمۡ﴾: خديعةً ومُنْكَرًا بينَكم.\n\n﴿أَرۡبَىٰ مِنۡ أُمَّةٍ﴾: أكثرَ عَددًَا وأوفرَ مالًا من الجماعة التي عاهَدْتموها.\n\n﴿يَبۡلُوكُمُ ٱللَّهُ﴾: يختبرُكم بالوفاءِ بِالعهودِ وعَدَمِ نَقْضِها."],[93,93,"﴿أُمَّةࣰ وَ ٰ⁠حِدَةࣰ﴾: أهلَ دينٍ واحدٍ، وهو الإسلامُ.\n\n﴿وَيَهۡدِي﴾: يُوَفِّقُ إلى الهدايةِ."],[94,94,"﴿فَتَزِلَّ قَدَمُۢ﴾: فتنحَرِفَ أقدامُكم عن محَجَّةِ الحقِّ.\n\n﴿ثُبُوتِهَا﴾: استقامتِها عليه.\n\n﴿ٱلسُّوٓءَ﴾: ما يَسُوءُكم من العذابِ في الدنيا."],[95,95,"﴿وَلَا تَشۡتَرُواْ﴾: لا تَسْتبدلوا."],[96,96,"﴿يَنفَدُ﴾: يزولُ ويَفْنى.\n\n﴿بَاقࣲ﴾: لا يزولُ ولا يَفْنى."],[97,97,"﴿طَيِّبَةࣰ﴾: سعيدةً في الدنيا، يصاحِبُها القناعة بما قَسَمهُ اللهُ وقَدَّره."],[98,98,"﴿فَإِذَا قَرَأۡتَ﴾: أي: فإذا أرَدْتَ أن تَقْرَأَ.\n\n﴿فَٱسۡتَعِذۡ بِٱللَّهِ﴾: فالتجِئْ واستَجِرْ به.\n\n﴿ٱلرَّجِيمِ﴾: المَرْجُومِ، أي: المَطْرودِ من رحمةِ اللهِ."],[99,99,"﴿سُلۡطَـٰنٌ﴾: تَسَلُّطٌ واستيلاءٌ.\n\n﴿يَتَوَكَّلُونَ﴾: يَعْتمدون عليه ويُفَوِّضُون أمرَهم إليه."],[100,100,"﴿يَتَوَلَّوۡنَهُۥ﴾: يَتِّخِذُونه مُعِينًا لهم ويُطيعونه.\n\n﴿هُم بِهِۦ﴾: بسببِ الشيطانِ وإغوائِه إيّاهم."],[101,101,"﴿بَدَّلۡنَآ ءَايَةࣰ﴾: أزَلْناها، أو أنْزَلْنا غيرَها.\n\n﴿مُفۡتَرِۭ﴾: كَذّابٌ تَختَلِقُ الباطِلَ على اللهِ مِن عندِك."],[102,102,"﴿رُوحُ ٱلۡقُدُسِ﴾: جبريلُ عليه السلامُ."],[103,103,"﴿لِّسَانُ﴾: لُغةُ وكلامُ.\n\n﴿يُلۡحِدُونَ إِلَيۡهِ﴾: يَنْسِبُون إليه التعليمَ.\n\n﴿أَعۡجَمِيࣱّ﴾: لا يُفْصِحُ عن مُرادِه.\n\n﴿مُّبِينٌ﴾: في غايةِ الوضوحِ والبيانِ."],[104,104,"﴿لَا يَهۡدِيهِمُ ٱللَّهُ﴾: لا يُوَفِّقُهم للإيمانِ؛ لعِلْمِه بعدَمِ قَبولِهم له."],[105,105,"﴿يَفۡتَرِي﴾: يَخْتِلقُ."],[106,106,"﴿مَن كَفَرَ بِٱللَّهِ﴾: فهم الكاذبون حقًّا، وعليهم غَضَبٌ من الله.\n\n﴿أُكۡرِهَ﴾: أُرْغِمَ على النُّطْقِ بالكفرِ فَتَلفَّظَ به؛ خَوْفًا من هَلاكِه.\n\n﴿شَرَحَ بِٱلۡكُفۡرِ صَدۡرࣰا﴾: اعتَقَدَه وطابَتْ نفسُه به."],[107,107,"﴿ٱسۡتَحَبُّواْ ٱلۡحَيَوٰةَ﴾: اختارُوها وفَضَّلُوها."],[108,108,"﴿طَبَعَ﴾: خَتَم."],[109,109,"﴿لَا جَرَمَ﴾: حقًّا، أو لا مَحالةَ."],[110,110,"﴿فُتِنُواْ﴾: اختُبِرُوا بتعذيبِهم، وتَلَفَّظُوا بالكُفرِ."],[111,111,"﴿تُجَـٰدِلُ عَن نَّفۡسِهَا﴾: تُخاصِمُ عن ذاتِها، وتسعى في خَلاصِها.\n\n﴿وَتُوَفَّىٰ﴾: تُعْطى وافيًا كامِلًا."],[112,112,"﴿قَرۡيَةࣰ﴾: أي: مكةَ.\n\n﴿رَغَدࣰا﴾: واسعًا كثيرًا، أو هنيئًا سهلًا.\n\n﴿لِبَاسَ ٱلۡجُوعِ وَٱلۡخَوۡفِ﴾: ما غَشِيَها من صُنوفِ البَلاءِ وإحاطَتِه بها كاللِّباس."],[113,113,"﴿مِّنۡهُمۡ﴾: من جنسِهم، يَعْرِفُون نَسَبَه وأمانتَه."],[114,114,"﴿وَٱشۡكُرُواْ نِعۡمَتَ ٱللَّهِ﴾: بالاعترافِ بها، واستعمالِها في طاعَتِه."],[115,115,"﴿ٱلۡمَيۡتَةَ﴾: ما لم يُذْبَحْ بطريقةٍ شَرْعِيَّةٍ من الحَيَوانِ.\n\n﴿وَٱلدَّمَ﴾: أي: المُراقَ من الذَّبِيحةِ.\n\n﴿وَمَآ أُهِلَّ لِغَيۡرِ ٱللَّهِ بِهِۦ﴾: ما ذُكِرَ عليه غيرُ اسمِ اللهِ عندَ ذَبْحِه.\n\n﴿فَمَنِ ٱضۡطُرَّ﴾: فمَن ألجأَتْه الضَّرورةُ إلى أكْلِ شيءٍ من هذه المُحَرَّماتِ.\n\n﴿غَيۡرَ بَاغࣲ﴾: غيرَ طالبٍ للمُحَرَّمِ وهو يَجِدُ غيرَه، أو غيرَ طالبٍ بأَكْلِه التلذُّذَ، أو غيرَ ظالمٍ لمضطرٍ آخرَ يُؤدِّي إلى هَلاكِه.\n\n﴿وَلَا عَادࣲ﴾: ولا متجاوزٍ ما يَسُدُّ جَوْعتَه."],[116,116,"﴿لِمَا تَصِفُ أَلۡسِنَتُكُمُ﴾: لمجرَّدِ وصْفِ ألسنتِكُم للشيء دونَ دليلٍ.\n\n﴿لِّتَفۡتَرُواْ﴾: تختَلِقُوا."],[118,118,"﴿ٱلَّذِينَ هَادُواْ﴾: اليهودِ."],[119,119,"﴿ٱلسُّوٓءَ﴾: الذُّنوبَ والمعاصِيَ.\n\n﴿بِجَهَـٰلَةࣲ﴾: بِجَهْلٍ منهم لعاقبتِها وإيجابِها سَخَطَ اللهِ.\n\n﴿وَأَصۡلَحُوٓاْ﴾: استقامُوا بعد تَوْبَتِهم."],[120,120,"﴿أُمَّةࣰ﴾: إمامًا قُدْوةً جامعًا لخِصالِ الخيرِ.\n\n﴿قَانِتࣰا لِّلَّهِ﴾: مُطيعًا خاضِعًا له.\n\n﴿حَنِيفࣰا﴾: مائلًا عن الأديانِ الباطلةِ إلى الدِّينِ الحقِ."],[121,121,"﴿ٱجۡتَبَىٰهُ﴾: اختاره اللهُ لرسالتِه.\n\n﴿وَهَدَىٰهُ﴾: أرْشَدَه ووَفَّقه."],[122,122,"﴿حَسَنَةࣰ﴾: نِعْمةً حسنةً، كالثَّناءِ الجميلِ عليه إلى يومِ القيامة، والاقتداءِ به."],[123,123,"﴿مِلَّةَ إِبۡرَ ٰ⁠هِيمَ﴾: شريعتَه، وهي الإسلامُ."],[124,124,"﴿جُعِلَ ٱلسَّبۡتُ﴾: فُرِضَ تَعْظِيمُه والتفرُّغُ للعبادةِ فيه.\n\n﴿ٱلَّذِينَ ٱخۡتَلَفُواْ فِيهِ﴾: هم اليهودُ، حيث أمَرَهم نبيُّهم بتعظيمِ يومِ الجُمُعَةِ، فاختاروا السَّبْتَ."],[125,125,"﴿بِٱلۡحِكۡمَةِ﴾: بالطريقةِ الحَكِيمةِ وفْقَ شَرْعِ اللهِ.\n\n﴿وَٱلۡمَوۡعِظَةِ ٱلۡحَسَنَةِ﴾: بالتذكيرِ المناسِبِ للأشخاصِ والأحوالِ."],[127,127,"﴿ضَيۡقࣲ﴾: حَرَجٍ وغَمٍّ."]]);
QTF("gharib",17,[[1,1,"﴿سُبۡحَـٰنَ ٱلَّذِيٓ﴾: تنزيهًا لله عن كلِّ سوءٍ، وتعظيمًا لشأنِه على كمالِ قدرتِه.\n\n﴿أَسۡرَىٰ﴾: الإسراءُ هو سَيْرُ الليلِ.\n\n﴿بِعَبۡدِهِۦ﴾: محمد ﷺ بجسَدِه ورُوحِه، حالَ اليَقَظةِ.\n\n﴿بَـٰرَكۡنَا حَوۡلَهُۥ﴾: أكْثَرْنا فيه الخيرَ بالخِصْبِ والثِّمارِ والمياهِ، وببَعْثِ كثيرٍ من الأنبياءِ منه.\n\n﴿مِنۡ ءَايَـٰتِنَآ﴾: من عجائبِ قدرةِ اللهِ وأدِلَّةِ وحْدانيتِه."],[2,2,"﴿ٱلۡكِتَـٰبَ﴾: التوراةَ.\n\n﴿وَكِيلࣰا﴾: معبودًا تُفَوِّضون إليه أمورَكم."],[3,3,"﴿ذُرِّيَّةَ مَنۡ حَمَلۡنَا مَعَ نُوحٍ﴾: يا سُلالةَ الذين نَجّاهم اللهُ من الغَرَقِ مع نوحٍ، لا تُشْرِكوا بالله."],[4,4,"﴿وَقَضَيۡنَآ إِلَىٰ بَنِيٓ إِسۡرَ ٰ⁠ٓءِيلَ﴾: وأَعْلَمْناهم.\n\n﴿ٱلۡكِتَـٰبِ﴾: التوراةِ.\n\n﴿فِي ٱلۡأَرۡضِ﴾: في بيتِ المَقْدِسِ والشامِ.\n\n﴿وَلَتَعۡلُنَّ﴾: لتَتَجاوَزُنَّ الحَدَّ في التكبُّرِ والظُّلْمِ."],[5,5,"﴿وَعۡدُ أُولَىٰهُمَا﴾: مَوْعِدُ أُولى مَرَّتَي الإفسادِ.\n\n﴿بَعَثۡنَا﴾: سَلَّطْنا.\n\n﴿أُوْلِي بَأۡسࣲ﴾: ذوي شجاعةٍ وقُوَّةٍ في الحروب.\n\n﴿فَجَاسُواْ﴾: طافُوا وعاثُوا.\n\n﴿خِلَـٰلَ ٱلدِّيَارِ﴾: وسْطَها بالإفسادِ.\n\n﴿مَّفۡعُولࣰا﴾: نافِذًا لابُدَّ من وقُوعِه."],[6,6,"﴿ٱلۡكَرَّةَ عَلَيۡهِمۡ﴾: الغَلَبَةَ والانتصارَ على عَدُوِّكم.\n\n﴿نَفِيرًا﴾: عددًا وعشيرةً."],[7,7,"﴿وَعۡدُ ٱلۡـَٔاخِرَةِ﴾: مَوْعِدُ المرَّةِ الثانيةِ من الإفسادِ.\n\n﴿لِيَسُـُٔواْ وُجُوهَكُمۡ﴾: ليجعَلُوا آثارَ الإهانةِ والَمذَلَّةِ باديةً فيها.\n\n﴿وَلِيُتَبِّرُواْ﴾: يُدَمِّرُوا ويُهْلِكُوا.\n\n﴿مَا عَلَوۡاْ﴾: ما استَوْلَوْا عليه.\n\n﴿تَتۡبِيرًا﴾: تَدْميرًا كاملًا."],[8,8,"﴿وَإِنۡ عُدتُّمۡ﴾: يا بني إسرائيلَ إلى الإفسادِ والظُّلمِ.\n\n﴿عُدۡنَا﴾: إلى عقابِكم ومَذلَّتِكم.\n\n﴿حَصِيرًا﴾: سِجْنًا يُحْبَسون فيه."],[9,9,"﴿يَهۡدِي﴾: يُرْشِدُ الناسَ ويَدْعُوهم.\n\n﴿هِيَ أَقۡوَمُ﴾: أحسنُ الطرقِ وأصوبُها."],[10,10,"﴿أَعۡتَدۡنَا﴾: أعدَدْنا."],[11,11,"﴿دُعَآءَهُۥ بِٱلۡخَيۡرِ﴾: مثلَ ما يَدْعُو بالخيرِ."],[12,12,"﴿ءَايَتَيۡنِ﴾: علامتَين في الدَّلالةِ على وحْدانيَّة اللهِ وقدرتِه.\n\n﴿ءَايَةَ ٱلَّيۡلِ﴾: علامتَه، وهي القمرُ.\n\n﴿ءَايَةَ ٱلنَّهَارِ﴾: علامتَه، وهي الشمسُ.\n\n﴿مُبۡصِرَةࣰ﴾: مضيئةً ومُبْصَرًا بها.\n\n﴿فَضۡلࣰا﴾: رِزْقًا؛ لأنّ النهارَ وقتٌ للتصرُّفِ في شؤونِ المعاشِ.\n\n﴿وَٱلۡحِسَابَ﴾: حسابَ الأشهرِ والأيامِ."],[13,13,"﴿طَـٰٓئِرَهُۥ﴾: ما عَمِلَه من خيرٍ أو شّرٍ.\n\n﴿كِتَـٰبࣰا﴾: وهو صحيفةُ أعمالِه.\n\n﴿يَلۡقَىٰهُ﴾: يَراه.\n\n﴿مَنشُورًا﴾: مفتوحًا غيرَ مَطْوِيٍّ."],[14,14,"﴿حَسِيبࣰا﴾: مُحاسِبًا."],[15,15,"﴿وَلَا تَزِرُ وَازِرَةࣱ﴾: ولا تحمِلُ نفسٌ آثمةٌ.\n\n﴿وِزۡرَ أُخۡرَىٰ﴾: إثْمَ نفسٍ مُذْنبةٍ غيرِها."],[16,16,"﴿أَمَرۡنَا﴾: بطاعةِ الله وتوحيدِه واتِّباعِ رُسُلِه.\n\n﴿مُتۡرَفِيهَا﴾: مُنَعَّمِيها، وهم الرؤساءُ والكبراءُ فيها.\n\n﴿فَفَسَقُواْ﴾: فخَرَجُوا عن أمرِ ربِّهم وعَصَوْه.\n\n﴿فَحَقَّ﴾: وجَبَ.\n\n﴿ٱلۡقَوۡلُ﴾: الوعيدُ والعذابُ.\n\n﴿فَدَمَّرۡنَـٰهَا تَدۡمِيرࣰا﴾: أهْلَكْناها إهلاكًا مُسْتأصِلًا."],[17,17,"﴿وَكَمۡ﴾: وكثيرًا.\n\n﴿ٱلۡقُرُونِ﴾: الأُمَمِ المكذِّبةِ."],[18,18,"﴿ٱلۡعَاجِلَةَ﴾: الحياةَ الدنيا.\n\n﴿يَصۡلَىٰهَا﴾: يَدْخُلها.\n\n﴿مَذۡمُومࣰا﴾: مَلُومًا.\n\n﴿مَّدۡحُورࣰا﴾: مَطْرودًا من رحمةِ اللهِ."],[19,19,"﴿مَّشۡكُورࣰا﴾: مقبولًا عندَ اللهِ، وسيُثِيبُهم عليه."],[20,20,"﴿كُلࣰّا نُّمِدُّ﴾: نَزيدُ كُلًّا من الفريقَين من غيرِ انقطاعٍ.\n\n﴿عَطَآءِ رَبِّكَ﴾: رزقِه.\n\n﴿مَحۡظُورًا﴾: ممنوعًا عن أحدٍ."],[22,22,"﴿فَتَقۡعُدَ﴾: فتَصيرَ.\n\n﴿مَذۡمُومࣰا﴾: من اللهِ وملائكتِه وصالحي المؤمنين."],[23,23,"﴿وَقَضَىٰ﴾: حَكَمَ وأَمَرَ.\n\n﴿أُفࣲّ﴾: كلمةٌ تَدُلُّ على التضجُّرِ والاستثقالِ.\n\n﴿وَلَا تَنۡهَرۡهُمَا﴾: لا يَصْدُرْ منك إليهما قولٌ قبيحٌ.\n\n﴿كَرِيمࣰا﴾: طَيِّبًا حَسَنًا مَقْرونًا بالاحترامِ والحياءِ."],[24,24,"﴿وَٱخۡفِضۡ لَهُمَا جَنَاحَ ٱلذُّلِّ﴾: وكُنْ متواضِعًا مُتَذَلِّلًا لأمِّك وأبيك.\n\n﴿مِنَ ٱلرَّحۡمَةِ﴾: لرِقَّتِك ورحمتِك بهما."],[25,25,"﴿لِلۡأَوَّ ٰ⁠بِينَ﴾: الرَّجّاعين إلى اللهِ بالتوبةِ والإنابةِ."],[26,26,"﴿وَءَاتِ﴾: وأعْطِ.\n\n﴿وَٱلۡمِسۡكِينَ﴾: الذي لا يَمْلِكُ ما يَكْفيه ويَسُدُّ حاجتَه.\n\n﴿وَٱبۡنَ ٱلسَّبِيلِ﴾: المسافرَ المنقطعَ عن مالِه في سَفَرِه، وإن كان غنيًا في بلدِه.\n\n﴿وَلَا تُبَذِّرۡ﴾: لا تُنْفِقْ مالَكَ في غيرِ موضِعِه الموافِقِ للشَّرعِ."],[27,27,"﴿إِخۡوَ ٰ⁠نَ ٱلشَّيَـٰطِينِ﴾: أشباهَهم وقُرَناءَهم في الفسادِ والمعاصي."],[28,28,"﴿ٱبۡتِغَآءَ رَحۡمَةࣲ﴾: طَلَبًا لرزقٍ تنتظرُه.\n\n﴿مَّيۡسُورࣰا﴾: لَيِّنًا لطيفًا."],[29,29,"﴿مَغۡلُولَةً﴾: مقبوضَةً عن الإنفاقِ في الخيرِ.\n\n﴿وَلَا تَبۡسُطۡهَا كُلَّ ٱلۡبَسۡطِ﴾: لا تُسْرِفْ، ولا تتوسَّعْ في النفقةِ فوقَ طاقَتِك.\n\n﴿مَّحۡسُورًا﴾: نادمًا على إسرافِك وضَياعِ مالِك."],[30,30,"﴿يَبۡسُطُ ٱلرِّزۡقَ﴾: يُوَسِّعُه.\n\n﴿وَيَقۡدِرُ﴾: ويُضَيِّقُه."],[31,31,"﴿إِمۡلَـٰقࣲ﴾: فَقْرٍ.\n\n﴿خِطۡـࣰٔا﴾: إثمًا."],[32,32,"﴿فَـٰحِشَةࣰ﴾: فَعْلَةً قبيحةً ظاهرةَ القُبْحِ.\n\n﴿وَسَآءَ سَبِيلࣰا﴾: بئسَ الطريقُ طريقُه."],[33,33,"﴿فَقَدۡ جَعَلۡنَا﴾: بما أذِنَ فيه الشَّرْعُ، كالقِصاصِ.\n\n﴿لِوَلِيِّهِۦ﴾: لِمَن يَلي أمرَه مِن وارثٍ أو حاكمٍ.\n\n﴿سُلۡطَـٰنࣰا﴾: حُجَّةً في طَلَبِ قَتْلِ القاتلِ أو الدِّيَةِ.\n\n﴿فَلَا يُسۡرِف فِّي ٱلۡقَتۡلِ﴾: لا يُجاوِزِ الحَدَّ المشروعَ فيه."],[34,34,"﴿ٱلۡيَتِيمِ﴾: مَن مات أبوه وهو دونَ سِنِّ البُلوغِ.\n\n﴿هِيَ أَحۡسَنُ﴾: بالطريقةِ الحُسنى.\n\n﴿يَبۡلُغَ أَشُدَّهُۥ﴾: قوتَه على حِفْظِ مالِه، وحُسْنِ التصرُّفِ فيه.\n\n﴿مَسۡـُٔولࣰا﴾: يُسأَل صاحبُ العهدِ عنه، ويحاسَبُ يومَ القيامةِ."],[35,35,"﴿بِٱلۡقِسۡطَاسِ ٱلۡمُسۡتَقِيمِ﴾: بالميزانِ السَّوِيِّ.\n\n﴿تَأۡوِيلࣰا﴾: مآلًا وعاقبةً عندَ اللهِ."],[36,36,"﴿وَلَا تَقۡفُ﴾: لا تَتَّبِعْ.\n\n﴿مَا لَيۡسَ لَكَ بِهِۦ عِلۡمٌ﴾: ما لا عِلْمَ لك به من قولٍ أو فِعْلٍ.\n\n﴿وَٱلۡفُؤَادَ﴾: القلبَ.\n\n﴿مَسۡـُٔولࣰا﴾: أي: صاحبُها، يُسْأَلُ عَمّا فَعَلَ بها."],[37,37,"﴿مَرَحًا﴾: فَخْرًا وتكبُّرًا.\n\n﴿لَن تَخۡرِقَ ٱلۡأَرۡضَ﴾: تَثْقُبَها بمَشْيِك عليها بهذه الصفةِ."],[38,38,"﴿كُلُّ ذَ ٰ⁠لِكَ﴾: ما تَقَدَّم ذِكْرُه من الأوامرِ والنَّواهي.\n\n﴿كَانَ سَيِّئُهُۥ﴾: السَّيِّئُ منه، هو الَمنْهِيّاتُ."],[39,39,"﴿ٱلۡحِكۡمَةِ﴾: الأحكامِ المُحْكَمَةِ التي لا يَتَطرَّقُ إليها الفسادُ.\n\n﴿مَّدۡحُورًا﴾: مَطْرودًا من رحمةِ اللهِ."],[40,40,"﴿أَفَأَصۡفَىٰكُمۡ﴾: اختاركم وخَصَّكم."],[41,41,"﴿صَرَّفۡنَا﴾: بيَّنّا، ونَوَّعْنا القولَ في أساليبَ مختلفةٍ."],[42,42,"﴿سَبِيلࣰا﴾: طريقًا إلى المغالَبَةِ."],[43,43,"﴿سُبۡحَـٰنَهُۥ﴾: تنزيهًا لله."],[44,44,"﴿يُسَبِّحُ بِحَمۡدِهِۦ﴾: يُنَزِّهُ اللهَ تنزيهًا مَقْرونًا بالثناءِ والحمدِ له.\n\n﴿لَّا تَفۡقَهُونَ﴾: لا تَفْهَمُون ولا تُدْرِكُون.\n\n﴿حَلِيمًا﴾: لا يُعاجِلُ بالعقوبةِ مَنِ انطمَسَتْ بَصيرتُه فعَصاه."],[45,45,"﴿حِجَابࣰا مَّسۡتُورࣰا﴾: مانِعًا ساتِرًا، يَمْنَعُ عقولَهم عن فَهْمِ القُرآنِ والانتفاعِ به؛ عقوبةً لهم على كُفرِهم."],[46,46,"﴿أَكِنَّةً﴾: أغْطِيَةً.\n\n﴿وَقۡرࣰا﴾: ثِقْلًا وصَمَمًا عن استماعِ القرآنِ وتَدَبُّرِه.\n\n﴿وَحۡدَهُۥ﴾: داعيًا لتوحيدِه، ناهيًا عن الشِّرك بِه.\n\n﴿وَلَّوۡاْ عَلَىٰٓ أَدۡبَـٰرِهِمۡ﴾: أدْبَرُوا راجِعين.\n\n﴿نُفُورࣰا﴾: نافِرين من قولِك؛ تَكَبُّرًا عن الحقّ."],[47,47,"﴿بِمَا يَسۡتَمِعُونَ بِهِۦٓ﴾: بما يستمعون القرآنَ، وقَصْدُهم السخريةُ والتكذيبُ.\n\n﴿وَإِذۡ هُمۡ نَجۡوَىٰٓ﴾: ونَعْلَمُ ما هم مُتَسارُّون بينهم في شأنِكِ.\n\n﴿مَّسۡحُورًا﴾: أصابَه السِّحْرُ فاختلطَ عَقْلُه."],[48,48,"﴿ٱنظُرۡ﴾: تأمَّلْ وتَعَجَّبْ.\n\n﴿ضَرَبُواْ لَكَ ٱلۡأَمۡثَالَ﴾: شَبَّهُوك فقالُوا: ساحِرٌ، وتارةً شاعرٌ، وتارةً مجنونٌ، مع عِلْمِهم بخِلافِه.\n\n﴿فَضَلُّواْ﴾: انحرَفُوا.\n\n﴿سَبِيلࣰا﴾: طريقًا إلى الحقِّ والصوابِ."],[49,49,"﴿وَرُفَـٰتًا﴾: أجزاءً مُتَكَسِّرةً مُتَفتتةً."],[51,51,"﴿يَكۡبُرُ فِي صُدُورِكُمۡ﴾: يَعْظُمُ ويُسْتَبْعَدُ في عقولِكم قَبولُه للحياةِ، كالسمواتِ.\n\n﴿يُعِيدُنَا﴾: يُرْجِعُنا إلى الحياةِ بعدَ موتِنا.\n\n﴿فَطَرَكُمۡ﴾: خَلَقَكم من غيرِ مثالٍ سابقٍ.\n\n﴿فَسَيُنۡغِضُونَ إِلَيۡكَ رُءُوسَهُمۡ﴾: سيُحَرِّكُونها استهزاءً وتعجُّبًا.\n\n﴿مَتَىٰ هُوَ﴾: أي: البعثُ."],[52,52,"﴿يَدۡعُوكُمۡ﴾: يُناديكم خالقُكم على لسانِ المَلَكِ؛ للخروجِ من قبورِكم.\n\n﴿بِحَمۡدِهِۦ﴾: بأمرِ اللهِ، حامدين اللهَ على كمالِ قدرتِه."],[53,53,"﴿يَنزَغُ﴾: يُفْسِدُ ويُوَسْوِسُ.\n\n﴿مُّبِينࣰا﴾: واضحَ العداوةِ."],[54,54,"﴿وَكِيلࣰا﴾: مُفَوَّضًا إليك أمرُهم."],[55,55,"﴿فَضَّلۡنَا بَعۡضَ ٱلنَّبِيِّـۧنَ﴾: بالفضائلِ وإنزالِ الكتبِ.\n\n﴿زَبُورࣰا﴾: الكتابُ المنزَّلُ على داودَ عليه السلام، وكلُّه تحميدٌ وثناءٌ على اللهِ."],[56,56,"﴿كَشۡفَ ٱلضُّرِّ﴾: إزالتَه.\n\n﴿تَحۡوِيلًا﴾: نَقْلَه إلى غيرِكم، أوتبديلَه من حالٍ إلى أخرى."],[57,57,"﴿ٱلَّذِينَ يَدۡعُونَ﴾: اتخذهم المُشْركون آلهةً، كالملائكة والأنبياء.\n\n﴿يَبۡتَغُونَ﴾: يَطْلبون باجتهادٍ.\n\n﴿ٱلۡوَسِيلَةَ﴾: القُرْبةَ بالطاعةِ والدرجةِ العُليا.\n\n﴿أَيُّهُمۡ أَقۡرَبُ﴾: يَطْلُبها الذي هو أقربُ إلى اللهِ، فكيف بمَن دونَه؟\n\n﴿مَحۡذُورࣰا﴾: حقيقًا بأن يَحْذَرَه العِبادُ."],[58,58,"﴿وَإِن مِّن قَرۡيَةٍ﴾: وما مِن قريةٍ كَذَّب أهلُها.\n\n﴿فِي ٱلۡكِتَـٰبِ﴾: في اللَّوحِ المحفوظِ.\n\n﴿مَسۡطُورࣰا﴾: مَكْتوبًا."],[59,59,"﴿بِٱلۡـَٔايَـٰتِ﴾: بالمُعْجزاتِ التي اقترحها المشركون.\n\n﴿مُبۡصِرَةࣰ﴾: معجزةً واضحةً.\n\n﴿فَظَلَمُواْ بِهَا﴾: فكفَرُوا بها فأَهْلَكَهم اللهُ."],[60,60,"﴿أَحَاطَ بِٱلنَّاسِ﴾: عِلْمًا وقُدرةً، فهُم في قَبْضَتِه، ولا يَخْرجُون عن مشيئتِه.\n\n﴿ٱلرُّءۡيَا﴾: ما عاينَه النبيُّ ﷺ ليلةَ الإسراءِ والمعراجِ من عجائبِ مخلوقاتِ اللهِ.\n\n﴿فِتۡنَةࣰ﴾: ابتلاءً وامتحانًا.\n\n﴿وَٱلشَّجَرَةَ ٱلۡمَلۡعُونَةَ﴾: شجرةَ الزَّقُّومِ، جَعَلَها اللهُ ابتلاءً لبعضِ الناس الذين أنكروا خَلْقَ شجرةٍ في النارِ.\n\n﴿وَنُخَوِّفُهُمۡ﴾: نُخَوِّفُ المشركين بأصنافِ الوعيدِ والعذابِ.\n\n﴿طُغۡيَـٰنࣰا﴾: تجاوُزًا للحَدِّ في الكفرِ والضَّلالِ."],[61,61,"﴿ٱسۡجُدُواْ لِـَٔادَمَ﴾: تحيةً وإكرامًا له وإظهارًا لفضلِه، لا عِبادةً."],[62,62,"﴿أَرَءَيۡتَكَ﴾: أخْبِرْني.\n\n﴿لَأَحۡتَنِكَنَّ ذُرِّيَّتَهُۥٓ﴾: لأَسْتَوْلِيَنَّ عليهم بالإغواءِ والإضلالِ.\n\n﴿إِلَّا قَلِيلࣰا﴾: مَن عَصَمَه اللهُ تعالى مِن عبادِه."],[64,64,"﴿وَٱسۡتَفۡزِزۡ﴾: واستَخِفَّ، أو أزْعِجْ.\n\n﴿بِصَوۡتِكَ﴾: بدَعْوَتِك إياهم إلى المعاصي والآثام.\n\n﴿وَأَجۡلِبۡ عَلَيۡهِم﴾: واستحِثَّهم، واجْمَعْ عليهم كلَّ ما تَقْدِرُ عليه مِن جنودِك.\n\n﴿بِخَيۡلِكَ وَرَجِلِكَ﴾: من كلِّ راكبٍ وماشٍ في المعصيةِ والفَسادِ.\n\n﴿وَشَارِكۡهُمۡ فِي ٱلۡأَمۡوَ ٰ⁠لِ﴾: بتحريضِهم على كَسْبِ الأموالِ المحرَّمةِ، وإنفاقِها فيما يُغضبُ اللهَ.\n\n﴿وَٱلۡأَوۡلَـٰدِ﴾: وبتَزْيِينِ إنجابِهم عن طريقِ الزِّنى، أو التخلُّصِ منهم، وتجاوزِ حدودِ الشَّرعِ.\n\n﴿غُرُورًا﴾: وعْدًا باطلًا خادعًا."],[65,65,"﴿سُلۡطَـٰنࣱ﴾: تَسَلُّطٌ وقوةٌ على إغوائِهم.\n\n﴿وَكِيلࣰا﴾: حافِظًا لعبادِه."],[66,66,"﴿يُزۡجِي﴾: يُجْري ويُسَيِّرُ برِفْقٍ.\n\n﴿ٱلۡفُلۡكَ﴾: السُّفُنَ.\n\n﴿لِتَبۡتَغُواْ﴾: لتَطْلُبُوا.\n\n﴿مِن فَضۡلِهِۦٓ﴾: مِن رزقِ اللهِ."],[67,67,"﴿ٱلضُّرُّ﴾: الشِّدَّةُ وخَوْفُ الغَرَقِ.\n\n﴿ضَلَّ﴾: غابَ عن عقولِكم.\n\n﴿مَن تَدۡعُونَ إِلَّآ إِيَّاهُ﴾: الذين تَعْبُدُونهم من الآلهةِ، وتَذَكَّرْتُم اللهَ وحدَه."],[68,68,"﴿يَخۡسِفَ بِكُمۡ جَانِبَ ٱلۡبَرِّ﴾: يُغَوِّرَ بكم الأرضَ، ويُغيِّبَكم فيها.\n\n﴿حَاصِبࣰا﴾: المَطَرَ الذي فيه حِجارةٌ من السماء، أو ريحًا شديدة تَرْمي بالحصى الصِّغارِ.\n\n﴿وَكِيلًا﴾: حَفيظًا وناصِرًا من الله."],[69,69,"﴿فِيهِ﴾: في البحر.\n\n﴿قَاصِفࣰا﴾: شديدةً عاصفةً، تُكَسِّرُ كلَّ ما أتَتْ عليه.\n\n﴿تَبِيعࣰا﴾: مُطالِبًا بما فَعَلْنا، ونصيرًا يأخذُ بالثأرِ لكم."],[70,70,"﴿كَرَّمۡنَا بَنِيٓ ءَادَمَ﴾: بالرسُلِ والرِّسالات، وغيرِها من النِّعَمِ. ومَنحْناهم عقولًا يُدْرِكون بها ويُمَيِّزون."],[71,71,"﴿يَوۡمَ﴾: أي: يومَ القيامةِ.\n\n﴿بِإِمَـٰمِهِمۡ﴾: بمَنِ اقتَدَوْا به في الدُّنيا من كتابٍ، أو نبيّ، أو قائدٍ.\n\n﴿كِتَـٰبَهُۥ﴾: كتابَ أعمالِه.\n\n﴿فَتِيلࣰا﴾: مِقْدارَ الخيطِ الذي في شَقِّ النَّواة."],[72,72,"﴿فِي هَـٰذِهِۦٓ أَعۡمَىٰ﴾: في الدُّنيا أعمى القَلْبِ والبَصيرةِ."],[73,73,"﴿وَإِن كَادُواْ﴾: ولقد قارَبَ المشركون.\n\n﴿لَيَفۡتِنُونَكَ﴾: لَيَصْرِفُونك ويَخْدَعُونك في ظَنِّهم.\n\n﴿لِتَفۡتَرِيَ عَلَيۡنَا﴾: لِتَتَقَوَّلَ علينا مَّما اقترحُوه عليك.\n\n﴿لَّٱتَّخَذُوكَ خَلِيلࣰا﴾: خَصُّوك بالصداقةِ الخاصَّةِ."],[74,74,"﴿تَرۡكَنُ﴾: تميلُ."],[75,75,"﴿ضِعۡفَ ٱلۡحَيَوٰةِ وَضِعۡفَ ٱلۡمَمَاتِ﴾: عذابًا مُضاعَفًا مِثْلَي ما يُعَذَّبُ به غيرُك في الدنيا والآخِرَةِ."],[76,76,"﴿لَيَسۡتَفِزُّونَكَ﴾: لَيُزعِجُونك بعَداوتهم لِيُخْرِجُوك.\n\n﴿مِنَ ٱلۡأَرۡضِ﴾: من مكةَ.\n\n﴿وَإِذࣰا﴾: لو أخرجُوك.\n\n﴿خِلَـٰفَكَ﴾: بَعْدَك."],[77,77,"﴿تَحۡوِيلًا﴾: تَبْديلًا."],[78,78,"﴿لِدُلُوكِ ٱلشَّمۡسِ﴾: وقتِ ميلِها عن وسَطِ السماءِ، وهو الزَّوالُ في الظَّهيرةِ.\n\n﴿غَسَقِ ٱلَّيۡلِ﴾: إقبالِ ظُلْمَتِه وسَوادِه.\n\n﴿وَقُرۡءَانَ ٱلۡفَجۡرِ﴾: وأقمْ صَلاةَ الفجرِ.\n\n﴿مَشۡهُودࣰا﴾: تَحْضُرُها ملائكةُ الليلِ، وملائكةُ النهارِ."],[79,79,"﴿فَتَهَجَّدۡ بِهِۦ﴾: فاقْرأ القرآنَ في صلاةِ الليلِ.\n\n﴿نَافِلَةࣰ لَّكَ﴾: زيادةً لك، وفضيلةً ورَفْعَ دَرَجاتٍ.\n\n﴿مَقَامࣰا مَّحۡمُودࣰا﴾: شافِعًا للناسِ عند فَصْلِ القضاءِ بينَهم، يحْمَدُكَ فيه الأوَّلون والآخِرون."],[80,80,"﴿مُدۡخَلَ صِدۡقࣲ﴾: إدخالًا مَرْضِيًّا لا أرى فيه ما أكْرَهُ.\n\n﴿مُخۡرَجَ صِدۡقࣲ﴾: إخراجًا مَرْضِيًّا مما هوشَرٌّ لي.\n\n﴿سُلۡطَـٰنࣰا﴾: حُجَّةً بيِّنةً ثابتةً، أو قوَّةً وعِزًّا.\n\n﴿نَّصِيرࣰا﴾: ناصرًا ومُعِينًا على مَن خالفني."],[81,81,"﴿ٱلۡحَقُّ﴾: الإسلامُ.\n\n﴿وَزَهَقَ ٱلۡبَـٰطِلُ﴾: ذَهَبَ وبَطَل الشِّرْكُ."],[82,82,"﴿خَسَارࣰا﴾: ضَلالًا وهَلاكًا؛ بسبب كُفْرِهم."],[83,83,"﴿وَنَـَٔا بِجَانِبِهِۦ﴾: تباعَدَ عن شُكْرِ اللهِ وطاعَتِه؛ تَكَبُّرًا.\n\n﴿ٱلشَّرُّ﴾: الشِّدَّةُ والضَّرَرُ.\n\n﴿يَـُٔوسࣰا﴾: شديدَ اليأسِ من رحمةِ الله."],[84,84,"﴿شَاكِلَتِهِۦ﴾: ما يُجانِسُ أخلاقَه التي اعتادَ عليها."],[85,85,"﴿مِنۡ أَمۡرِ رَبِّي﴾: مما استأثرَ اللهُ تعالى بعِلْمِها."],[86,86,"﴿لَنَذۡهَبَنَّ بِٱلَّذِيٓ أَوۡحَيۡنَآ إِلَيۡكَ﴾: لَمَحَوْنا القرآنَ من القلوبِ والمصاحِفِ، حتى لا يَبْقى له أثرٌ.\n\n﴿وَكِيلًا﴾: مَن يَلْتزِمُ باستردادِه بعد الذَّهابِ به."],[87,87,"﴿إِلَّا رَحۡمَةࣰ مِّن رَّبِّكَ﴾: لكن رحمةً من اللهِ أبقَيْنا القرآنَ فلم نُذْهِبْه."],[88,88,"﴿ظَهِيرࣰا﴾: مُعِينًا على تحقيقِ مُرادِهم."],[89,89,"﴿صَرَّفۡنَا﴾: بَيَّنّا ونَوَّعْنا بأساليبَ مختلفةٍ.\n\n﴿كُلِّ مَثَلࣲ﴾: كلِّ معنى يَحْصُلُ الاتعاظُ به.\n\n﴿كُفُورࣰا﴾: جُحودًا للحَقِّ."],[90,90,"﴿يَنۢبُوعًا﴾: عَيْنًا لا يَجِفُّ ماؤُها."],[91,91,"﴿جَنَّةࣱ﴾: حديقةٌ.\n\n﴿فَتُفَجِّرَ ٱلۡأَنۡهَـٰرَ﴾: تُجْرِيها بقُوَّةٍ."],[92,92,"﴿كِسَفًا﴾: قِطَعًا.\n\n﴿قَبِيلًا﴾: مقابَلَةً وعِيانًا."],[93,93,"﴿زُخۡرُفٍ﴾: ذَهَبٍ.\n\n﴿تَرۡقَىٰ﴾: تَصْعَدَ.\n\n﴿سُبۡحَانَ رَبِّي﴾: تَنْزيهًا للهِ عن اقتراحاتهم، وتَعجُّبًا من شِدَّةِ كُفْرِهم."],[95,95,"﴿مُطۡمَئِنِّينَ﴾: ساكنِين فيها."],[97,97,"﴿وَبُكۡمࣰا﴾: لايَنْطِقُون.\n\n﴿وَصُمࣰّا﴾: لا يَسْمَعُون.\n\n﴿مَّأۡوَىٰهُمۡ﴾: مَصيرُهم.\n\n﴿خَبَتۡ﴾: سَكَنَ لَهَبُها.\n\n﴿سَعِيرࣰا﴾: تَوَقُّدًا واشتِعالًا."],[98,98,"﴿ذَ ٰ⁠لِكَ﴾: الموصوفُ من العذابِ.\n\n﴿وَرُفَـٰتًا﴾: أجزاءً من العذابِ."],[99,99,"﴿أَجَلࣰا﴾: وقْتًا مُحَدَّدًا للموتِ والحسابِ.\n\n﴿لَّا رَيۡبَ فِيهِ﴾: لا شَكَّ في وقوعِه.\n\n﴿كُفُورࣰا﴾: جُحودًا للحَقِّ."],[100,100,"﴿رَحۡمَةِ رَبِّيٓ﴾: رِزْقِه وسائرِ نِعَمِه.\n\n﴿قَتُورࣰا﴾: بخيلًا مَنُوعًا."],[101,101,"﴿ءَايَـٰتِۭ بَيِّنَـٰتࣲ﴾: معجزاتٍ واضحاتِ الدَّلالةِ على نُبُوَّتِه.\n\n﴿فَسۡـَٔلۡ﴾: سؤالَ تقريرٍ على صِدْقِك.\n\n﴿مَسۡحُورࣰا﴾: أصابكَ السِّحْرُ فاختلطَ عَقْلُكَ."],[102,102,"﴿هَـٰٓؤُلَآءِ﴾: المعجزاتِ التسعَ.\n\n﴿بَصَآئِرَ﴾: دَلالاتٍ وعِبَرًا يُستَدَلُّ بها على وحدانيةِ اللهِ وقدرتِه.\n\n﴿لَأَظُنُّكَ﴾: لمَوقِنٌ أنك.\n\n﴿مَثۡبُورࣰا﴾: مُهْلَكًا، أو ممنوعًا عن الخير، مطبوعًا على الشَّرِّ."],[103,103,"﴿يَسۡتَفِزَّهُم﴾: يُزْعِجَهم بعَداوتِه ليُخْرِجَهم.\n\n﴿مِّنَ ٱلۡأَرۡضِ﴾: من أرضِ «مصرَ»."],[104,104,"﴿ٱلۡأَرۡضَ﴾: أرضَ «مصرَ والشام».\n\n﴿وَعۡدُ ٱلۡـَٔاخِرَةِ﴾: يومُ القيِامةِ.\n\n﴿لَفِيفࣰا﴾: جميعًا مختلِطِين من كلِّ نوعٍ لا تتعارفُون."],[106,106,"﴿فَرَقۡنَـٰهُ﴾: أوْضَحْناه، وفَرَقْنا فيه بين الحقِّ والباطِل.\n\n﴿عَلَىٰ مُكۡثࣲ﴾: على تَمَهُّلٍ وتَأَنٍّ؛ ليَفْهموه ويَتَيَسَّرَلهم حِفْظُه.\n\n﴿وَنَزَّلۡنَـٰهُ تَنزِيلࣰا﴾: على حَسَبِ الحوادث والمصالحِ والأحوالِ."],[107,107,"﴿مِن قَبۡلِهِۦٓ﴾: من قَبْلِ القرآنِ.\n\n﴿يَخِرُّونَ لِلۡأَذۡقَانِ سُجَّدࣰا﴾: يَسْقُطون بسرعةٍ ساجدين على وجوهِهم؛ تعظيمًا لله وشُكْرًا له."],[108,108,"﴿سُبۡحَـٰنَ رَبِّنَآ﴾: تنزيهًا له على قُدرتِه التامةِ، وأنه لا يُخْلِفُ الميعادَ.\n\n﴿لَمَفۡعُولࣰا﴾: مُنْجَزًا واقعًا."],[109,109,"﴿خُشُوعࣰا﴾: سُكونًا وضَراعةً وخُضوعًا."],[110,110,"﴿بِصَلَاتِكَ﴾: بقراءتِك في الصلاةِ.\n\n﴿وَلَا تُخَافِتۡ﴾: ولا تُسِرَّ.\n\n﴿وَٱبۡتَغِ﴾: اقْصِدْ.\n\n﴿بَيۡنَ ذَ ٰ⁠لِكَ﴾: بينَ الجَهْرِ بقراءتِك والإسرارِ بها.\n\n﴿سَبِيلࣰا﴾: طريقًا وسَطًا."],[111,111,"﴿وَلِيࣱّ مِّنَ ٱلذُّلِّ﴾: ناصرٌ ومُعِينٌ لذُلٍّ يَلْحَقُه، فهو الغَنِيُّ العزيزُ القَوِيُّ.\n\n﴿وَكَبِّرۡهُ تَكۡبِيرَۢا﴾: عَظِّمْه تعظيمًا تامًّا مع كمالِ التنزيهِ."]]);
QTF("gharib",18,[[1,1,"﴿عِوَجَا﴾: اختِلافًا، ولا اختِلالًا فيِ ألفاظِه ولا فيِ معانيه."],[2,2,"﴿قَيِّمࣰا﴾: مستقيمًا معتدلًا، لا إفراطَ فيه ولا تفريطَ.\n\n﴿بَأۡسࣰا شَدِيدࣰا﴾: عقوبةً عاجلةً في الدنيا وآجِلَةً في الآخرةِ.\n\n﴿أَجۡرًا حَسَنࣰا﴾: ثوابًا جزيلًا، هو الجنةُ."],[5,5,"﴿كَبُرَتۡ﴾: عَظُمَتْ في الشَّناعَةِ والقُبْحِ."],[6,6,"﴿بَـٰخِعࣱ نَّفۡسَكَ﴾: مُهْلِكُها ومُجْهِدُها.\n\n﴿عَلَىٰٓ ءَاثَـٰرِهِمۡ﴾: بعدَ تَوَلِّي قومِك عنك.\n\n﴿ٱلۡحَدِيثِ﴾: القرآنِ.\n\n﴿أَسَفًا﴾: حُزْنًا وغَضَبًا؛ لحِرْصِك على إيمانهم."],[7,7,"﴿لِنَبۡلُوَهُمۡ﴾: لِنَخْتَبِرَهم."],[8,8,"﴿صَعِيدࣰا﴾: تُرابًا.\n\n﴿جُرُزًا﴾: لا نباتَ فيه."],[9,9,"﴿ٱلۡكَهۡفِ﴾: النَّقْبِ المتَّسِعِ في الجبل، وهو أكبرُ من المغارة.\n\n﴿وَٱلرَّقِيمِ﴾: اللَّوْحِ الذي كُتِبَتْ فيه أسماءُ أهلِ الكهفِ."],[10,10,"﴿أَوَى ٱلۡفِتۡيَةُ إِلَى ٱلۡكَهۡفِ﴾: لجَؤُوا إليه؛ لعبادةِ اللهِ، وفِرارًا بدِينهم.\n\n﴿وَهَيِّئۡ﴾: يَسِّرْ.\n\n﴿رَشَدࣰا﴾: اهتداءً إلى الحق، وسَدادًا في العمل."],[11,11,"﴿فَضَرَبۡنَا عَلَىٰٓ ءَاذَانِهِمۡ﴾: أنَمْناهم نومًا عميقًا؛ بحيث لا يَسْمعون."],[12,12,"﴿بَعَثۡنَـٰهُمۡ﴾: أيقَظْناهم مِن نومِهم.\n\n﴿ٱلۡحِزۡبَيۡنِ﴾: الفريقَين المختلفَين في مُدَّةِ بقائِهم في الكهفِ.\n\n﴿أَمَدࣰا﴾: غايةً ومُدَّة."],[14,14,"﴿وَرَبَطۡنَا عَلَىٰ قُلُوبِهِمۡ﴾: قَوَّيْناها بالصَّبْرِ والتثبيتِ على الحقِّ.\n\n﴿شَطَطًا﴾: قولًا بعيدًا مجانِبًا للحقِّ."],[15,15,"﴿لَّوۡلَا﴾: هَلّا.\n\n﴿بِسُلۡطَـٰنِۭ بَيِّنࣲ﴾: دليلٍ واضحٍ.\n\n﴿ٱفۡتَرَىٰ﴾: اختَلَقَ.\n\n﴿كَذِبࣰا﴾: بنسبةِ الشريكِ إلى اللهِ تعالى."],[16,16,"﴿ٱعۡتَزَلۡتُمُوهُمۡ﴾: فارَقْتُم قومَكم؛ فِرارًا بدِينِكم.\n\n﴿فَأۡوُۥٓاْ﴾: الجَؤُوا.\n\n﴿يَنشُرۡ﴾: يَبْسُطْ ويُوَسِّعْ.\n\n﴿وَيُهَيِّئۡ﴾: يُيَسِّرْ.\n\n﴿مِّرۡفَقࣰا﴾: ما تنتفعون به من أسبابِ العيشِ."],[17,17,"﴿تَّزَ ٰ⁠وَرُ﴾: تميلُ.\n\n﴿ذَاتَ ٱلۡيَمِينِ﴾: جهةَ يمينِ الكهفِ.\n\n﴿تَّقۡرِضُهُمۡ﴾: تَتْرُكُهم وتتجاوَزُهم.\n\n﴿فَجۡوَةࣲ مِّنۡهُ﴾: مُتَّسَعٍ من الكهفِ وفَضائِه، فلا يتأَذَّون من جَوِّه، أو من حرارةِ الشمس، ويأتيهم الهواءُ النافعُ.\n\n﴿ءَايَـٰتِ ٱللَّهِ﴾: دلائلِ قُدرتِه.\n\n﴿يَهۡدِ ٱللَّهُ﴾: يوفِّقه.\n\n﴿وَلِيࣰّا﴾: مُعِينًا وناصِرًا."],[18,18,"﴿رُقُودࣱ﴾: نِيامٌ.\n\n﴿بِٱلۡوَصِيدِ﴾: بفِناءِ الكَهْفِ، كأنه يَحْرُسُهم.\n\n﴿رُعۡبࣰا﴾: خَوفًا وفَزَعًا."],[19,19,"﴿وَكَذَ ٰ⁠لِكَ﴾: وكما أنَمْناهم وحَفِظْناهم مدةً طويلة.\n\n﴿بَعَثۡنَـٰهُمۡ﴾: أيْقَظْناهم من نومِهم كما كانوا.\n\n﴿بِوَرِقِكُمۡ﴾: بنقُودِكم الفِضِّيَّةِ.\n\n﴿أَيُّهَآ﴾: أيُّ أهلِ المدينةِ.\n\n﴿أَزۡكَىٰ طَعَامࣰا﴾: أحَلُّ وأطيبُ.\n\n﴿وَلۡيَتَلَطَّفۡ﴾: وليتكلَّفِ اللُّطْفَ والرِّفْقَ في المعاملةِ، حتى لا ينكشِفَ أمرُنا."],[20,20,"﴿يَظۡهَرُواْ عَلَيۡكُمۡ﴾: يَطَّلِعُوا على مكانِكم ويَعْلَمُوا به.\n\n﴿يَرۡجُمُوكُمۡ﴾: يَقْتُلوكم بالرَّجْمِ بالحجارةِ.\n\n﴿مِلَّتِهِمۡ﴾: دينِهم الباطلِ."],[21,21,"﴿وَكَذَ ٰ⁠لِكَ﴾: وكما أنَمْناهم السنينَ الطِّوالَ، ثم أيْقَظْناهم بعدَها.\n\n﴿أَعۡثَرۡنَا عَلَيۡهِمۡ﴾: أطْلَعْنا عليهم أهلَ زمانِهم.\n\n﴿وَعۡدَ ٱللَّهِ﴾: بالبعثِ.\n\n﴿أَمۡرَهُمۡ﴾: في أمرِ القِيامةِ، فمِن مُقِرٍّ لها وجاحِدٍ، أو في أمْرِ الفِتْيَةِ المؤمنين وما اطَّلعوا عليه مِن أحوالِهم.\n\n﴿ٱلَّذِينَ غَلَبُواْ عَلَىٰٓ أَمۡرِهِمۡ﴾: أصحابُ الكلمةِ والنفوذِ."],[22,22,"﴿رَجۡمَۢا بِٱلۡغَيۡبِ﴾: قولًا بلا عِلْمٍ ولا اطِّلاعٍ.\n\n﴿بِعِدَّتِهِم﴾: بعَدَدِهم.\n\n﴿فَلَا تُمَارِ فِيهِمۡ﴾: فلا تجادِلْ في شأنِ أصحابِ الكهفِ وعَدَدِهم أحدًا من الخائضين فيه.\n\n﴿إِلَّا مِرَآءࣰ ظَـٰهِرࣰا﴾: إلا جِدالًا واضحًا بذِكْرِ ما قَصَصْنا عليك مِن شأنِهم دونَ زيادةٍ."],[24,24,"﴿وَٱذۡكُر رَّبَّكَ﴾: بقولِ: إنْ شاء الله.\n\n﴿يَهۡدِيَنِ﴾: يُوَفِّقَني.\n\n﴿مِنۡ هَـٰذَا﴾: من قصةِ أصحابِ الكهفِ في الدِّلالةِ على نُبَوَّتي.\n\n﴿رَشَدࣰا﴾: هدايةً ودَلالة للناسِ على ذلك."],[25,25,"﴿وَلَبِثُواْ فِي كَهۡفِهِمۡ﴾: ومَكَثَ الفِتْيانُ فيه نِيامًا."],[26,26,"﴿أَبۡصِرۡ بِهِۦ وَأَسۡمِعۡ﴾: ما أبصَرَ اللهَ وأسمَعَه بكلِّ موجودٍ، فهو لا يَغِيبُ عنه شيء!\n\n﴿مَا لَهُم﴾: ليس للخَلْقِ.\n\n﴿وَلِيࣲّ﴾: مُعينٍ وناصرٍ.\n\n﴿حُكۡمِهِۦٓ﴾: قَضائِه وتشريعِه."],[27,27,"﴿مُلۡتَحَدࣰا﴾: مَلْجَأً ومَلاذًا."],[28,28,"﴿وَٱصۡبِرۡ نَفۡسَكَ﴾: احبِسْها في طاعةِ اللهِ.\n\n﴿بِٱلۡغَدَوٰةِ وَٱلۡعَشِيِّ﴾: أولِ النهار وآخرِه، والمرادُ دوامُ العبادةِ.\n\n﴿وَلَا تَعۡدُ عَيۡنَاكَ عَنۡهُمۡ﴾: لا تَصْرِفْ نَظَرَكَ عنهم إلى غيرِهِم.\n\n﴿أَغۡفَلۡنَا قَلۡبَهُۥ﴾: جَعَلْناه غافلًا.\n\n﴿فُرُطࣰا﴾: ضَياعًا وهَلاكًا ومُتَجاوِزًا فيه الاعتدالَ."],[29,29,"﴿ٱلۡحَقُّ﴾: ما جئتكُم به هو الحقُّ.\n\n﴿فَمَن شَآءَ فَلۡيُؤۡمِن وَمَن شَآءَ فَلۡيَكۡفُرۡ﴾: تهديدٌ ووعيدٌ لمن اختارَ الكفرَ بعد بيانِ الحقِّ ووُضوحِه.\n\n﴿سُرَادِقُهَا﴾: سُورُها المحيطُ بها.\n\n﴿كَٱلۡمُهۡلِ﴾: ماءٌ غليظٌ كالمُنْصَهِر من المعادنِ، أو كعَكَرِ الزيتِ، بَلَغَ منتهى الحَرارةِ.\n\n﴿مُرۡتَفَقًا﴾: منزِلًا ومُقامًا."],[31,31,"﴿جَنَّـٰتُ عَدۡنࣲ﴾: جِنانُ إقامةٍ دائمةٍ.\n\n﴿يُحَلَّوۡنَ﴾: يُزَيَّنُون.\n\n﴿سُندُسࣲ﴾: رقيقِ الحَريرِ.\n\n﴿وَإِسۡتَبۡرَقࣲ﴾: ما غَلُظَ من الحريرِ وثَخُنَ.\n\n﴿ٱلۡأَرَآئِكِ﴾: الأَسِرَّةِ المزيَّنَةِ بفاخِرِ السَّتائرِ."],[32,32,"﴿وَٱضۡرِبۡ لَهُم﴾: واذكُرْ للمؤمنين والكافرين المستكبرِين وأَوْرِدْ لهم.\n\n﴿جَنَّتَيۡنِ﴾: حديقتَين.\n\n﴿وَحَفَفۡنَـٰهُمَا بِنَخۡلࣲ﴾: جَعَلْنا النَّخْلَ محيطًا بكلٍّ منهما."],[33,33,"﴿ءَاتَتۡ أُكُلَهَا﴾: أثمرَتْ ثمرَها الذي يُؤْكَلُ.\n\n﴿وَلَمۡ تَظۡلِم مِّنۡهُ﴾: ولم تَنْقُصْ من إثمارها عَبْرَ السنينَ."],[34,34,"﴿لَهُۥ ثَمَرࣱ﴾: لصاحبِ البستانينِ أنواعٌ من المال سِوى حديقتَيه.\n\n﴿نَفَرࣰا﴾: أولادًا وخَدَمًا وأعوانًا."],[35,35,"﴿ظَالِمࣱ لِّنَفۡسِهِۦ﴾: كافرٌ بالبعثِ، مُعْجَبٌ بمالِه.\n\n﴿تَبِيدَ﴾: تَهْلِكَ وتَفْنى."],[36,36,"﴿قَآئِمَةࣰ﴾: كائنةً وواقعةً.\n\n﴿مُنقَلَبࣰا﴾: مَرْجِعًا وعاقبةً."],[38,38,"﴿لَّـٰكِنَّا۠﴾: لكنْ أنا أقولُ."],[39,39,"﴿وَلَوۡلَآ﴾: وهَلّا."],[40,40,"﴿حُسۡبَانࣰا﴾: جَمْعُ حُسْبانَةٍ، وهو العذابُ كالصَّواعِقِ.\n\n﴿صَعِيدࣰا﴾: أرضًا أو ترابًا.\n\n﴿زَلَقًا﴾: لا نَباتَ فيها، ومَلْساءُ لا تَثْبُتُ عليها قَدَمٌ. والمرادُ أنها عَدِيمةُ النَّفْعِ."],[41,41,"﴿غَوۡرࣰا﴾: غائِرًا ذاهبًا في أسفلِ الأرضِ."],[42,42,"﴿وَأُحِيطَ بِثَمَرِهِۦ﴾: وأُهلِكَتْ أموالُ الكافرِ بما فيها حديقتاه، كما تَوَقَّعَ المؤمنُ.\n\n﴿يُقَلِّبُ كَفَّيۡهِ﴾: دَلالةً على نَدَمِه وأَسَفِه وحَسْرَتِه.\n\n﴿خَاوِيَةٌ عَلَىٰ عُرُوشِهَا﴾: متهدِّمةٌ سَقَطَ بعضُها على بعضٍ، خاليةٌ مما كان فيها."],[43,43,"﴿فِئَةࣱ﴾: جماعةٌ ممَّنِ افتَخَرَ بهم.\n\n﴿وَمَا كَانَ مُنتَصِرًا﴾: ما كان ممتنعًا بنفسِه وقوَّتِه عندَ انتقامِ اللهِ منه."],[44,44,"﴿هُنَالِكَ﴾: في مثلِ هذه الشَّدائدِ، أو يومِ القيامةِ.\n\n﴿ٱلۡوَلَـٰيَةُ لِلَّهِ﴾: النُّصْرَةُ للهِ وحدَه لا يَقْدِرُ عليها غيرُه.\n\n﴿عُقۡبࣰا﴾: عاقبةً لمَن تَوَلّاهم."],[45,45,"﴿وَٱضۡرِبۡ لَهُم﴾: اذكُرْ للناسِ وأَوْرِدْ.\n\n﴿مَّثَلَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا﴾: صِفَتَها في زينتِها، وتَقَلُّبَها وسُرْعَةَ زوالِها.\n\n﴿هَشِيمࣰا﴾: يابسًا مُتَكَسِّرًا، بعد خُضْرَتِه ونَضارَتِه.\n\n﴿تَذۡرُوهُ ٱلرِّيَـٰحُ﴾: تُذْهِبُه وتُفَرِّقُه إلى كلِّ جهةٍ.\n\n﴿مُّقۡتَدِرًا﴾: كاملَ القُدْرةِ على كلِّ شيءٍ."],[46,46,"﴿زِينَةُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا﴾: فيهما جَمالٌ ونَفْعٌ وقوَّةٌ.\n\n﴿وَٱلۡبَـٰقِيَـٰتُ ٱلصَّـٰلِحَـٰتُ﴾: الأعمالُ الصالحةُ بما فيها: التسبيحُ، والتحميدُ، والتكبيرُ، والتهليلُ.\n\n﴿أَمَلࣰا﴾: ما كان يأمُلُه صاحبُها في الدُّنيا عندَ اللهِ في الآخِرة."],[47,47,"﴿نُسَيِّرُ ٱلۡجِبَالَ﴾: نُزيلُها عن أماكنِها، ونُسَيِّرها في الجوِّ كالسَّحابِ.\n\n﴿بَارِزَةࣰ﴾: ظاهرةً للأَعْيُنِ لا يَسْتُرها شيءٌ.\n\n﴿وَحَشَرۡنَـٰهُمۡ﴾: جَمَعْنا الأوَّلِين والآخِرين لموقفِ الحسابِ.\n\n﴿نُغَادِرۡ﴾: نَتْرُكْ."],[48,48,"﴿صَفࣰّا﴾: مُصْطَفِّين جميعًا لا يَغِيبُ أحدٌ منهم.\n\n﴿كَمَا خَلَقۡنَـٰكُمۡ أَوَّلَ مَرَّةِۭ﴾: مِثْلَ خَلْقِنا الأولِ لكم: فُرادى، حُفاةَ الأقدامِ، عُراةَ الأجسامِ، غيرَ مَخْتُونين.\n\n﴿بَلۡ زَعَمۡتُمۡ﴾: يا مُنْكِري البَعْثِ.\n\n﴿مَّوۡعِدࣰا﴾: لبَعْثِكم ومُجازاتِكم على أعمالِكم."],[49,49,"﴿ٱلۡكِتَـٰبُ﴾: صحائفُ أعمالِ العبادِ.\n\n﴿مُشۡفِقِينَ﴾: خائفين.\n\n﴿يَـٰوَيۡلَتَنَا﴾: يا هَلاكَنا، نداءٌ منهم على أنفسِهم بالخُسْرانِ والهَلاكِ.\n\n﴿لَا يُغَادِرُ﴾: لا يَتْرُك.\n\n﴿أَحۡصَىٰهَا﴾: عَدَّها وأثْبتَها."],[50,50,"﴿ٱسۡجُدُواْ لِـَٔادَمَ﴾: تحيةً وإكرامًا له وإظهارًا لفَضْلِه، لا عبادةً.\n\n﴿فَفَسَقَ عَنۡ أَمۡرِ رَبِّهِۦٓ﴾: خَرَجَ عن طاعةِ ربِّه بتَرْكِ السُّجودِ؛ تَكَبُّرًا.\n\n﴿أَوۡلِيَآءَ﴾: أعوانًا."],[51,51,"﴿مَّآ أَشۡهَدتُّهُمۡ﴾: أي: إبليسَ وذريتَه.\n\n﴿عَضُدࣰا﴾: أعوانًا وأنصارًا في شأنٍ من شؤوني."],[52,52,"﴿فَدَعَوۡهُمۡ﴾: استغاثُوا بهم.\n\n﴿مَّوۡبِقࣰا﴾: مَهْلِكًا في جَهَنَّمَ يَهْلِكُون فيه."],[53,53,"﴿فَظَنُّوٓاْ﴾: أيقَنوا.\n\n﴿مُّوَاقِعُوهَا﴾: واقِعُونَ فيها وداخِلُوها.\n\n﴿مَصۡرِفࣰا﴾: مكانًا يَنْصَرِفُون ويَلْجَؤُون إليه."],[54,54,"﴿صَرَّفۡنَا﴾: بَيَّنّا ونوَّعْنا بأساليبَ مختلفةٍ.\n\n﴿كُلِّ مَثَلࣲ﴾: كلِّ معنى يَحْصُلُ الاتِّعاظُ به.\n\n﴿جَدَلࣰا﴾: خُصومةً في الباطل."],[55,55,"﴿سُنَّةُ ٱلۡأَوَّلِينَ﴾: سُنَّةُ اللهِ في إهلاكِ السابقين بالاستئصال.\n\n﴿قُبُلࣰا﴾: صُنوفًا وأنواعًا، أو مَوُاجَهَةً ومقابَلَةً."],[56,56,"﴿لِيُدۡحِضُواْ بِهِ﴾: ليُزِيلُوا بجِدالِهم وباطِلِهم.\n\n﴿هُزُوࣰا﴾: استهزاءً وسُخْريَةً."],[57,57,"﴿أَكِنَّةً﴾: أغطيةً مانعةً.\n\n﴿أَن يَفۡقَهُوهُ﴾: لِئلّا يَفْهَمُوا القرآنَ؛ عُقوبةً لهم.\n\n﴿وَقۡرࣰا﴾: ثِقَلًا في السَّمعِ."],[58,58,"﴿مَّوۡعِدࣱ﴾: أي: مُقَدَّرٌ لعذابهِم."],[59,59,"﴿وَتِلۡكَ ٱلۡقُرَىٰٓ﴾: مِنَ الأممِ السابقةِ.\n\n﴿لِمَهۡلِكِهِم﴾: لهَلاكِهم."],[60,60,"﴿لِفَتَىٰهُ﴾: تلميذِه وخادِمِه يُوشَعَ بنِ نونٍ.\n\n﴿لَآ أَبۡرَحُ﴾: لا أزال أسِيرُ.\n\n﴿مَجۡمَعَ ٱلۡبَحۡرَيۡنِ﴾: مُلتقاهما.\n\n﴿أَمۡضِيَ حُقُبࣰا﴾: أسيرُ زمنًا طويلًا."],[61,61,"﴿فِي ٱلۡبَحۡرِ سَرَبࣰا﴾: طريقًا فيه، كالشَّقِّ في الأرضِ."],[62,62,"﴿جَاوَزَا﴾: فارَقا مكانَهما.\n\n﴿غَدَآءَنَا﴾: طعامَنا أوَّلَ النهارِ.\n\n﴿نَصَبࣰا﴾: تَعَبًا."],[63,63,"﴿أَرَءَيۡتَ﴾: أتَذْكُرُ؟\n\n﴿إِذۡ أَوَيۡنَآ إِلَى ٱلصَّخۡرَةِ﴾: حين لَجَأْنا إليها للراحةِ.\n\n﴿سَبِيلَهُۥ﴾: طريقَه.\n\n﴿عَجَبࣰا﴾: يُتعَجَّبُ منه."],[64,64,"﴿نَبۡغِ﴾: نَطْلبُه، وهو علامةٌ على مكانِ العبدِ الصّالحِ.\n\n﴿فَٱرۡتَدَّا﴾: رَجَعا.\n\n﴿عَلَىٰٓ ءَاثَارِهِمَا﴾: على طريقِهما الذي جاءا منه.\n\n﴿قَصَصࣰا﴾: يَتْبَعان آثارَ مسيرِهما، حتى وصَلا إلى الصَّخْرةِ."],[65,65,"﴿عَبۡدࣰا مِّنۡ عِبَادِنَآ﴾: هو الخَضِرُ، وهو نبيٌّ توفّاه الله.\n\n﴿رَحۡمَةࣰ﴾: نبوَّةً."],[66,66,"﴿رُشۡدࣰا﴾: إصابةً للحقِّ وصَوابًا أسترشِدُ به."],[68,68,"﴿خُبۡرࣰا﴾: عِلْمًا ومعرفةً بحقيقتِه."],[70,70,"﴿عَن شَيۡءٍ﴾: أي: تُنْكِرُه عليَّ في عِلْمِكَ.\n\n﴿أُحۡدِثَ لَكَ مِنۡهُ ذِكۡرࣰا﴾: أبتدِئُكَ ببيانِه وتَوْضيحِ ما خَفِيَ عليك."],[71,71,"﴿فَٱنطَلَقَا﴾: فسار موسى والخَضِرُ يَمْشِيان على الساحلِ.\n\n﴿شَيۡـًٔا إِمۡرࣰا﴾: أمرًا عظيمًا مُنْكَرًا."],[73,73,"﴿وَلَا تُرۡهِقۡنِي﴾: لا تُحَمِّلني وتُكَلِّفني.\n\n﴿مِنۡ أَمۡرِي عُسۡرࣰا﴾: في صُحْبتي إياك وتَعَلُّمي منك مشقَّةً."],[74,74,"﴿زَكِيَّةَۢ﴾: نقيةً طاهرةً لم تبلُغْ حَدَّ التكليفِ.\n\n﴿بِغَيۡرِ نَفۡسࣲ﴾: بغيرِ حَقٍّ من قِصاصٍ عليها.\n\n﴿نُّكۡرࣰا﴾: مُنْكَرًا عظيمًا."],[76,76,"﴿مِن لَّدُنِّي عُذۡرࣰا﴾: إلى الغايةِ التي أعْذُرُكَ في فِراقي بسببِها."],[77,77,"﴿ٱسۡتَطۡعَمَآ أَهۡلَهَا﴾: طَلَبا من أهلِ القريةِ الطعامَ على وجْهِ الضِّيافَةِ.\n\n﴿فَأَبَوۡاْ﴾: امتنعُوا.\n\n﴿يُرِيدُ﴾: يَقْرُبُ ويُوشِكُ.\n\n﴿أَن يَنقَضَّ﴾: أن يسقطَ؛ بسببِ مَيَلانِه.\n\n﴿فَأَقَامَهُۥ﴾: سوّاه الخَضرُ وعَدَّلَ ميلَه."],[78,78,"﴿سَأُنَبِّئُكَ﴾: سأُخْبِرُكَ.\n\n﴿بِتَأۡوِيلِ﴾: بحقيقةِ مَقْصِدي من أفعالي."],[79,79,"﴿لِمَسَـٰكِينَ﴾: محتاجِين لا يملِكُون ما يَكْفيهم ويَسُدُّ حاجتَهم.\n\n﴿أَعِيبَهَا﴾: أُحْدِثَ فيها عَيْبًا بخَرْقِها.\n\n﴿وَرَآءَهُم﴾: أمامَهم.\n\n﴿كُلَّ سَفِينَةٍ﴾: صالحةٍ غيرِ مَعِيبةٍ.\n\n﴿غَصۡبࣰا﴾: قَهْرًا وظُلْمًا."],[80,80,"﴿يُرۡهِقَهُمَا﴾: يَدْفَعَ والدَيه إلى تجاوُزِ حدودِ اللهِ والكفرِ."],[81,81,"﴿زَكَوٰةࣰ﴾: دِينًا وصَلاحًا.\n\n﴿رُحۡمࣰا﴾: رحمةً بوالدَيه وبِرًّا بهما."],[82,82,"﴿كَنزࣱ﴾: مالٌ مَدْفونٌ من الذَّهَبِ والفِضَّةِ.\n\n﴿يَبۡلُغَآ أَشُدَّهُمَا﴾: قوَّتَهما وكمالَ عَقْلِهما.\n\n﴿ذَ ٰ⁠لِكَ تَأۡوِيلُ﴾: الذي بَيَّنْتُ لك أسبابَه هو مآلُ تلك الأمورِ."],[83,83,"﴿وَيَسۡـَٔلُونَكَ﴾: أي: كفارُ قريشٍ بتَلْقينٍ من اليهود.\n\n﴿ذِي ٱلۡقَرۡنَيۡنِ﴾: عبدٌ صالحٌ مَلَّكه اللهُ الأرضَ، وأعطاه العِلْمَ والحكمةَ، حتى بَلَغَ سلطانُه المشرقَ والمغربَ، فسُمِّيَ ذا القَرْنين، فكأنه حاز قَرْنَي الدنيا.\n\n﴿ذِكۡرًا﴾: خَبَرًا تتذكَّرون به."],[84,84,"﴿مَكَّنَّا لَهُۥ﴾: سَهَّلْنا لَه التَّصَرُّفَ كَيفَ شاءَ.\n\n﴿سَبَبࣰا﴾: طَرِيقًا يُوصِلُه إلى مُرادِهِ."],[85,85,"﴿فَأَتۡبَعَ﴾: سَلَك وسارَ.\n\n﴿سَبَبًا﴾: طريقًا نَحْوَ الغَرْبِ."],[86,86,"﴿مَغۡرِبَ ٱلشَّمۡسِ﴾: مَوْضِعَ غُرُوبِها، وهُوَ نِهايةُ الأَرْضِ مِنَ الغَرْبِ.\n\n﴿عَيۡنٍ﴾: نَبْعٍ جارِيةٍ بالماءِ أو غيرِه.\n\n﴿حَمِئَةࣲ﴾: ذاتِ طينٍ أسْودَ.\n\n﴿تُعَذِّبَ﴾: بالقتلِ أو غيرِه إنْ لم يُؤمِنُوا.\n\n﴿حُسۡنࣰا﴾: بِدعوتِهم إلى الهُدى والرَّشادِ."],[87,87,"﴿ظَلَمَ﴾: نفسَه بكُفْرِه بِرَبِّه.\n\n﴿نُّكۡرࣰا﴾: مُنْكَرًا عَظِيمًا في جَهَنَّمَ."],[88,88,"﴿ٱلۡحُسۡنَىٰ﴾: الجنَّةُ.\n\n﴿يُسۡرࣰا﴾: سَهْلًا لا مَشَقَّةَ فِيه."],[89,89,"﴿سَبَبًا﴾: طَرِيقًا نَحْوَ الشَّرْقِ."],[90,90,"﴿مَطۡلِعَ ٱلشَّمۡسِ﴾: مَوْضِعَ طُلُوعِها، وهُوَ نِهايةُ الأرْضِ مِنَ الشَّرْقِ.\n\n﴿سِتۡرࣰا﴾: ساترًا مِنَ البِناء أوْ الأَشْجار."],[91,91,"﴿كَذَ ٰ⁠لِكَ﴾: كما وصَفْنا أمْرَ ذِي القَرنْيَنِ مِن بُلُوغِه المَغْرِبَ والمشْرِقَ.\n\n﴿خُبۡرࣰا﴾: عِلْمًا ومَعْرِفةً."],[93,93,"﴿ٱلسَّدَّيۡنِ﴾: الجَبَلَينِ."],[94,94,"﴿يَأۡجُوجَ وَمَأۡجُوجَ﴾: أُمَّتانِ عظِيمتان مِن بَنِي آدَمَ مَوْجُودتانِ.\n\n﴿خَرۡجًا﴾: نَصِيبًا وأجْرًا مِنَ المالِ.\n\n﴿سَدࣰّا﴾: حاجِزًا."],[95,95,"﴿رَدۡمًا﴾: حاجِزًا قَوِيًّا."],[96,96,"﴿زُبَرَ ٱلۡحَدِيدِ﴾: قِطَعَه الكَبيرةَ.\n\n﴿ٱلصَّدَفَيۡنِ﴾: جانِبَي الجبَلَينِ.\n\n﴿أُفۡرِغۡ﴾: أصُبَّ.\n\n﴿قِطۡرࣰا﴾: نُحاسًا مُذابًا."],[97,97,"﴿يَظۡهَرُوهُ﴾: يَعْلُوه ويَصْعَدُوا إليه.\n\n﴿نَقۡبࣰا﴾: ثَقْبًا؛ لِصَلابَتِه وسَماكَتِه."],[98,98,"﴿وَعۡدُ رَبِّي﴾: وعْدُ رَبِّي بِخُرُوجِ يأجُوجَ ومَأجُوجَ.\n\n﴿دَكَّآءَ﴾: مُنْهَدِمًا مُسْتَويًا بالأَرض."],[99,99,"﴿يَمُوجُ﴾: يضْطَرِبُ ويَخْتَلِطُ بَعْضُهم في بَعْضٍ.\n\n﴿ٱلصُّورِ﴾: القَرْنِ الذي يُنْفَخُ فيه للبعثِ."],[100,100,"﴿وَعَرَضۡنَا﴾: أبْرَزْنا."],[101,101,"﴿غِطَآءٍ﴾: سِتْرٍ وحِجابٍ.\n\n﴿ذِكۡرِي﴾: هُو القرآنُ والآياتُ الكونيةُ.\n\n﴿لَا يَسۡتَطِيعُونَ سَمۡعًا﴾: لا يُطِيقُونَ سَماعَ الحُجَجِ والبَراهِينِ بُغْضًا وعِنادًا."],[102,102,"﴿مِن دُونِيٓ أَوۡلِيَآءَ﴾: مِن غيرِي آلهةً.\n\n﴿أَعۡتَدۡنَا﴾: أعْدَدْنا وأحْضَرْنا.\n\n﴿نُزُلࣰا﴾: مَنزِلًا مُعَدًّا لهم."],[104,104,"﴿ضَلَّ سَعۡيُهُمۡ﴾: ضاعَ عَمَلُهم.\n\n﴿يَحۡسَبُونَ أَنَّهُمۡ يُحۡسِنُونَ صُنۡعًا﴾: يَظُنُّونَ أنّهم مُحْسِنُونَ في أعْمالِهم."],[105,105,"﴿فَحَبِطَتۡ﴾: فبَطَلَتْ.\n\n﴿وَزۡنࣰا﴾: قَدْرًا وثِقَلًا."],[106,106,"﴿هُزُوًا﴾: مُسْتَهْزَأً بِهما."],[107,107,"﴿جَنَّـٰتُ ٱلۡفِرۡدَوۡسِ﴾: أعلى مَناِزلِ الجنِّةِ وأَوْسَطُها، وهي أفْضَلُها.\n\n﴿نُزُلًا﴾: مَنزِلًا مُعدًّا لهم."],[108,108,"﴿لَا يَبۡغُونَ﴾: لا يُرِيدُونَ."],[109,109,"﴿مِدَادࣰا﴾: حِبْرًا للأقْلامِ.\n\n﴿لَنَفِدَ﴾: لَفَنِيَ.\n\n﴿كَلِمَـٰتُ رَبِّي﴾: عِلْمُه وحِكَمُه وما أوْحاه إلى ملائِكَتِه ورُسُلِه.\n\n﴿مَدَدࣰا﴾: زِيادةً."],[110,110,"﴿يَرۡجُواْ﴾: يخافُ عذابَ ربِّه، ويَرْجُو ثَوابَه يومَ لِقائِه."]]);
QTF("gharib",19,[[3,3,"﴿خَفِيࣰّا﴾: سِرًّا."],[4,4,"﴿وَهَنَ﴾: ضَعُفَ.\n\n﴿وَٱشۡتَعَلَ ٱلرَّأۡسُ شَيۡبࣰا﴾: انْتَشَرَ الشَّيبُ في رَأسِي.\n\n﴿شَقِيࣰّا﴾: مَحْرُومًا مِن إجابَةِ الدُّعاءِ."],[5,5,"﴿ٱلۡمَوَ ٰ⁠لِيَ﴾: العَصَبَةَ وأقْرَبَ القَرابَةِ.\n\n﴿عَاقِرࣰا﴾: التي لا تَلِدُ.\n\n﴿وَلِيࣰّا﴾: ولَدًا وارِثًا ومُعِينًا."],[6,6,"﴿يَرِثُنِي﴾: يَرِثُ نُبُوَّتي.\n\n﴿رَضِيࣰّا﴾: مَرْضِيًّا مِنكَ ومِن عِبادِكَ."],[7,7,"﴿سَمِيࣰّا﴾: مُسَمّىً باسْمِه."],[8,8,"﴿أَنَّىٰ﴾: كيفَ؟\n\n﴿عِتِيࣰّا﴾: النِّهايةَ في كِبَر السِّنِّ."],[9,9,"﴿هَيِّنࣱ﴾: سَهْلٌ.\n\n﴿وَلَمۡ تَكُ شَيۡـࣰٔا﴾: ولم تَكُ شيئًا مَذْكُورًا ولا مَوْجُودًا."],[10,10,"﴿ءَايَةࣰ﴾: علامةً.\n\n﴿سَوِيࣰّا﴾: صَحِيحًا مُعافىً."],[11,11,"﴿ٱلۡمِحۡرَابِ﴾: المُصَلّى.\n\n﴿بُكۡرَةࣰ وَعَشِيࣰّا﴾: صَباحًا ومَساءً."],[12,12,"﴿ٱلۡكِتَـٰبَ﴾: أي: التَّوْراةَ.\n\n﴿بِقُوَّةࣲ﴾: بجِدٍّ واجْتِهادٍ.\n\n﴿ٱلۡحُكۡمَ﴾: الحِكْمَةَ وحُسنَ الفَهْمِ.\n\n﴿صَبِيࣰّا﴾: صغيَر السِّنِّ."],[13,13,"﴿حَنَانࣰا﴾: رَحْمَةً ومحبةً.\n\n﴿وَزَكَوٰةࣰ﴾: طَهارةً مِنَ الذُّنُوبِ.\n\n﴿تَقِيࣰّا﴾: خائفًا مِنَ اللهِ، ومُطِيعًا لَه."],[14,14,"﴿بَرَّۢا﴾: بارًّا ومطيعًا.\n\n﴿جَبَّارًا﴾: مُتَكَبِّرًا عَنْ طاعِةِ ربِّه، وطاعةِ والدَيْه.\n\n﴿عَصِيࣰّا﴾: عاصِيًا لِرَبِّه ولِوالِدَيْه."],[16,16,"﴿فِي ٱلۡكِتَـٰبِ﴾: في هَذا القُرْآنِ.\n\n﴿ٱنتَبَذَتۡ﴾: تباعَدَتْ واعْتَزَلَتْ.\n\n﴿شَرۡقِيࣰّا﴾: مَكانًا مِمّا يلِي الشَّرقَ عَنْ أهْلِها."],[17,17,"﴿رُوحَنَا﴾: أي: جِبْرِيلَ عليهِ السَّلامُ.\n\n﴿فَتَمَثَّلَ لَهَا بَشَرࣰا﴾: تصَوَّرَ لَها في صُورَةِ إنْسانٍ.\n\n﴿سَوِيࣰّا﴾: تامَّ الخَلْقِ."],[18,18,"﴿أَعُوذُ بِٱلرَّحۡمَـٰنِ﴾: ألْتَجِئُ وأَسْتَجِيرُ بالرَّحمنِ."],[19,19,"﴿زَكِيࣰّا﴾: طاهِرًا مِنَ الذُّنوبِ."],[20,20,"﴿أَنَّىٰ﴾: كيفَ؟\n\n﴿لَمۡ يَمۡسَسۡنِي بَشَرࣱ﴾: لم يَمَسَّني بَشَرٌ بِنِكاحٍ حَلالٍ.\n\n﴿بَغِيࣰّا﴾: زانيةً."],[21,21,"﴿ءَايَةࣰ﴾: علامةً تَدُلُّ على قُدْرَةِ اللهِ.\n\n﴿رَحۡمَةࣰ مِّنَّا﴾: جَعَلَه اللهُ رحمةً لأمِّه ولِمَن آمَنَ به.\n\n﴿مَّقۡضِيࣰّا﴾: قَضاءً سابِقًا مُقَدَّرًا."],[22,22,"﴿فَٱنتَبَذَتۡ﴾: فتباعَدَتْ."],[23,23,"﴿نَسۡيࣰا مَّنسِيࣰّا﴾: شَيْئًا لا يُعْرَفُ ولا يُذكَرُ."],[24,24,"﴿فَنَادَىٰهَا﴾: أي: جبريلُ أو عِيسى.\n\n﴿سَرِيࣰّا﴾: جَدْوَلَ ماءٍ."],[25,25,"﴿هُزِّيٓ﴾: حَرِّكِي."],[26,26,"﴿وَقَرِّي عَيۡنࣰا﴾: وطِيبِي نَفْسًا بِمَولُودِكِ.\n\n﴿نَذَرۡتُ﴾: أوْجَبْتُ على نَفْسِي.\n\n﴿صَوۡمࣰا﴾: سُكُوتًا.\n\n﴿إِنسِيࣰّا﴾: أحَدًا مِنَ النّاسِ."],[27,27,"﴿شَيۡـࣰٔا فَرِيࣰّا﴾: أمْرًا عَظِيمًا مُفْتَرىً."],[28,28,"﴿يَـٰٓأُخۡتَ هَـٰرُونَ﴾: يا أُخْتَ الرَّجلِ الصّالحِ هارُونَ.\n\n﴿ٱمۡرَأَ سَوۡءࣲ﴾: رَجُلَ سَوْءٍ يأتي الفَواحِشَ.\n\n﴿بَغِيࣰّا﴾: زانيةً."],[29,29,"﴿ٱلۡمَهۡدِ﴾: ما يُهَيَّأ للرَّضِيعِ مِن فِراشٍ ونَحْوِه.\n\n﴿صَبِيࣰّا﴾: طِفْلًا رَضِيعًا."],[30,30,"﴿ٱلۡكِتَـٰبَ﴾: الإنْجِيلَ."],[31,31,"﴿مُبَارَكًا﴾: عَظِيمَ الخيرِ والنَّفْعِ\n\n﴿مَا دُمۡتُ حَيࣰّا﴾: ما بَقِيِتُ حَيًّا."],[32,32,"﴿بَرَّۢا﴾: بارًّا ومُطِيعًا.\n\n﴿جَبَّارࣰا﴾: مُتَكَبِّرًا.\n\n﴿شَقِيࣰّا﴾: عاصِيًا لِربِّي."],[33,33,"﴿وَيَوۡمَ أُبۡعَثُ حَيࣰّا﴾: أي: يَوْمَ القِيامةِ."],[34,34,"﴿فِيهِ يَمۡتَرُونَ﴾: يَشُكُّ فيه اليهودُ والنَّصارى ويُجادِلُونَ."],[35,35,"﴿مَا كَانَ﴾: ما يَنْبَغِي ولا يَلِيقُ.\n\n﴿سُبۡحَـٰنَهُۥٓ﴾: تَقَدَّسَ وتَنَزَّهَ عَن ذَلِكَ.\n\n﴿قَضَىٰٓ﴾: أرادَ.\n\n﴿فَيَكُونُ﴾: أي: كَما أرادَه."],[36,36,"﴿هَـٰذَا صِرَ ٰ⁠طࣱ مُّسۡتَقِيمࣱ﴾: هَذا طريقٌ لا اعْوِجاجَ فِيه."],[37,37,"﴿ٱلۡأَحۡزَابُ﴾: الفِرَقُ مِن أهْلِ الكِتابِ.\n\n﴿فَوَيۡلࣱ﴾: فهَلاكٌ.\n\n﴿مَّشۡهَدِ﴾: شُهُودِ.\n\n﴿يَوۡمٍ عَظِيمٍ﴾: يومِ القِيامَةِ."],[38,38,"﴿أَسۡمِعۡ بِهِمۡ وَأَبۡصِرۡ﴾: ما أقدَرَهم على السَّمعِ والبَصَرِ يوم القيامةِ!\n\n﴿فِي ضَلَـٰلࣲ مُّبِينࣲ﴾: في انْحِرافٍ واضحٍ عَن سَبَيلِ الحقِّ."],[39,39,"﴿يَوۡمَ ٱلۡحَسۡرَةِ﴾: يومَ النَّدامةِ على ما فرَّطُوا في جَنْبِ اللهِ."],[41,41,"﴿صِدِّيقࣰا﴾: عَظِيمَ الصِّدقِ."],[42,42,"﴿وَلَا يُغۡنِي﴾: ولا يَدْفَعُ."],[43,43,"﴿أَهۡدِكَ﴾: أُرْشِدْكَ.\n\n﴿صِرَ ٰ⁠طࣰا سَوِيࣰّا﴾: طريقًا مُسْتَويًا لا اعْوِجاجَ فيه."],[44,44,"﴿لَا تَعۡبُدِ ٱلشَّيۡطَـٰنَ﴾: لا تُطِعِ الشَّيطانَ في عِبادةِ الأصْنام.\n\n﴿عَصِيࣰّا﴾: مُخالِفًا مُسْتكْبِرًا عَن طاعَةِ اللهِ."],[45,45,"﴿لِلشَّيۡطَـٰنِ وَلِيࣰّا﴾: قَرِينًا لَه في اللَّعنةِ، وقريبًا منه في النّار."],[46,46,"﴿أَرَاغِبٌ أَنتَ عَنۡ ءَالِهَتِي﴾: أمُعْرِضٌ أنت عَن عِبادَةِ آلَهتِي.\n\n﴿لَأَرۡجُمَنَّكَ﴾: لَأَقْتُلَنَّك رَمْيًا بِالحِجارَةِ.\n\n﴿مَلِيࣰّا﴾: زَمانًا طَوِيلًا مِنَ الدَّهْرِ."],[47,47,"﴿سَلَـٰمٌ عَلَيۡكَ﴾: تحيةُ تَودِيعٍ ومُتارَكَةٍ، أي: تَسْلَمُ ممّا تَكْرَهُه مِنِّي.\n\n﴿بِي حَفِيࣰّا﴾: كَثيرَ الِبرِّ واللُّطْفِ."],[48,48,"﴿وَأَعۡتَزِلُكُمۡ﴾: وأُفارِقُكُم.\n\n﴿شَقِيࣰّا﴾: مَحْرُومًا مِن إجابَةِ الدُّعاءِ."],[50,50,"﴿لِسَانَ صِدۡقٍ﴾: ثَناءً حَسَنًا.\n\n﴿عَلِيࣰّا﴾: رفيعَ القَدْرِ باقيًا في النّاسِ."],[51,51,"﴿مُخۡلَصࣰا﴾: مُخْتارًا لِرِسالتِه."],[52,52,"﴿ٱلطُّورِ﴾: جَبَلِ طُورِ سَيناءَ.\n\n﴿وَقَرَّبۡنَـٰهُ نَجِيࣰّا﴾: فشَرَّفْناه بِمُناجاتِنا وتَكْلِيمِنا إيّاه سرًّا."],[56,56,"﴿صِدِّيقࣰا﴾: عظيمَ الصِّدقِ في قولِه وعَمَلِه."],[57,57,"﴿وَرَفَعۡنَـٰهُ﴾: أي: ذِكْرَه ومَنزِلَتَه، قيل: إنّه رُفِعَ إلى السَّماءِ الرابعةِ.\n\n﴿عَلِيًّا﴾: رفيعَ القَدْرِ، أو ذا مَكانٍ عالٍ في السَّماءِ."],[58,58,"﴿وَٱجۡتَبَيۡنَآ﴾: واصْطَفَينا للرِّسالةِ والنُّبوَّةِ.\n\n﴿خَرُّواْ﴾: وقَعُوا.\n\n﴿وَبُكِيࣰّا﴾: وباكِينَ مِن خَشْيَتِه سُبْحانَه وتَعالىَ."],[59,59,"﴿خَلَفَ مِنۢ بَعۡدِهِمۡ﴾: فجاءَ بَعْدَهُم.\n\n﴿خَلۡفٌ﴾: أتْباعُ سُوءٍ.\n\n﴿غَيًّا﴾: جَزاءَ الغَيِّ، أو وادِيًا في جَهَنَّمَ."],[61,61,"﴿جَنَّـٰتِ عَدۡنٍ﴾: جناتِ خُلْدٍ وإقامَةٍ دائِمةٍ.\n\n﴿بِٱلۡغَيۡبِ﴾: أي: غائبةً عَنْهم لا يُشاهِدُونها.\n\n﴿مَأۡتِيࣰّا﴾: آتِيًا لا مَحالةَ."],[62,62,"﴿لَغۡوًا﴾: كَلامًا باطِلًا.\n\n﴿بُكۡرَةࣰ وَعَشِيࣰّا﴾: أي: على مِقْدارِ ما يَعرِفُونَ من الغَداءِ والعَشاءِ، وإلّا فليسَ في الجنَّةِ بُكْرَةٌ ولا عَشِيَّةٌ."],[63,63,"﴿نُورِثُ﴾: نُعْطِي."],[64,64,"﴿وَمَا نَتَنَزَّلُ﴾: أي: نَحْنُ الملائكةُ مِنَ السَّماءِ إلى الأرضِ.\n\n﴿لَهُۥ مَا بَيۡنَ أَيۡدِينَا﴾: مما يُسْتَقْبَلُ مِن أُمُورِ الآخِرَةِ.\n\n﴿وَمَا خَلۡفَنَا﴾: مِمّا مَضى مِن أُمُورِ الدُّنْيا.\n\n﴿وَمَا بَيۡنَ ذَ ٰ⁠لِكَ﴾: وما بَيْنَ الدُّنْيا والآخِرةِ.\n\n﴿نَسِيࣰّا﴾: ناسِيًا لشيءٍ مِنَ الأشياءِ."],[65,65,"﴿وَٱصۡطَبِرۡ لِعِبَـٰدَتِهِۦ﴾: واثْبُتْ عَلى طاعةِ الله بِصَبْرٍ ومُواظَبَةٍ.\n\n﴿سَمِيࣰّا﴾: مُماثِلًا في ذاتِه وأَسْمائِه وصِفاتِه وأفعالِه."],[68,68,"﴿لَنَحۡشُرَنَّهُمۡ﴾: لَنَجْمَعَنَّ هَؤلاءِ المُنْكِرِينَ لِلبَعْثِ يومَ القيامةِ.\n\n﴿جِثِيࣰّا﴾: بارِكِينَ على رُكَبِهِم."],[69,69,"﴿ثُمَّ لَنَنزِعَنَّ﴾: ثم لَنَأخُذَنَّ.\n\n﴿شِيعَةٍ﴾: طائِفَةٍ.\n\n﴿عِتِيࣰّا﴾: تَمرُّدًا وعِصْيانًا للهِ تَعالى."],[70,70,"﴿هُمۡ أَوۡلَىٰ بِهَا صِلِيࣰّا﴾: هُم أوْلى بجَهَنَّمَ دُخُولًا."],[71,71,"﴿إِلَّا وَارِدُهَا﴾: إلّا واردٌ النارَ بالمُرُورِ على الصِّراطِ المنْصُوبِ على مَتْنِ جَهَنَّمَ.\n\n﴿حَتۡمࣰا مَّقۡضِيࣰّا﴾: أمْرًا مَحْتُومًا قُضِيَ وحُكِمَ أنّه لابُدَّ مِن وُقُوعِه."],[72,72,"﴿وَّنَذَرُ﴾: ونَتْرُكُ."],[73,73,"﴿خَيۡرࣱ مَّقَامࣰا﴾: أفْضَلُ مَنزِلًا.\n\n﴿وَأَحۡسَنُ نَدِيࣰّا﴾: وأَحْسَنُ مَجْلِسًا."],[74,74,"﴿مِّن قَرۡنٍ﴾: مِن أُمَمٍ.\n\n﴿هُمۡ أَحۡسَنُ أَثَـٰثࣰا وَرِءۡيࣰا﴾: أحْسنُ مَتاعًا مِنهُم، وأَجْمَلُ مَنظَرًا."],[75,75,"﴿فَلۡيَمۡدُدۡ﴾: فَلْيُمْهِلْهُ اسْتِدْراجًا.\n\n﴿هُوَ شَرࣱّ مَّكَانࣰا﴾: شرٌّ مَسْكَنًا ومُسْتَقَرًّا.\n\n﴿وَأَضۡعَفُ جُندࣰا﴾: وأَضْعَفُ قوةً ورِجالًا."],[76,76,"﴿وَٱلۡبَـٰقِيَـٰتُ ٱلصَّـٰلِحَـٰتُ﴾: أعمالُ الخيرِ.\n\n﴿وَخَيۡرࣱ مَّرَدًّا﴾: وخيرٌ مَرْجِعًا وعاقِبَةً."],[77,77,"﴿لَأُوتَيَنَّ﴾: لَأُعْطَينَّ في الآخِرَةِ."],[78,78,"﴿أَطَّلَعَ ٱلۡغَيۡبَ﴾: أعَلِمَ الغَيبَ؟\n\n﴿عَهۡدࣰا﴾: أي: عَهْدًا بِدُخُولِ الجنَّةِ."],[79,79,"﴿وَنَمُدُّ لَهُۥ﴾: ونَزِيدُه في الآخِرَةِ."],[80,80,"﴿وَنَرِثُهُۥ﴾: أي: بَعْدَ هَلاكِه فيَصِيرُ لنا مالُه وولدُه."],[81,81,"﴿عِزࣰّا﴾: شُفَعاءَ وأنْصارًا يَتَعزَّزُونَ بِهِم."],[82,82,"﴿وَيَكُونُونَ عَلَيۡهِمۡ ضِدًّا﴾: وتَكُونُ هَذهَ الآلهةُ مُخالِفةً لهم تُخاصِمُهُم، على عَكْسِ ما كانُوا يَرْجُونَه مِن هَؤلاءِ."],[83,83,"﴿تَؤُزُّهُمۡ﴾: تُهَيِّجُ الكافِرِينَ وتَدْفَعُهُم إلى المَعاصِي."],[84,84,"﴿نَعُدُّ لَهُمۡ﴾: نُحْصِي أعْمالَهم وأَعمارَهُم."],[85,85,"﴿وَفۡدࣰا﴾: قادِمِينَ على اللهِ مُكْرَمِينَ."],[86,86,"﴿وَنَسُوقُ ٱلۡمُجۡرِمِينَ﴾: أي: نَحُثُّهم على السَّيرِ ونَطْرُدُهم كما تُطْرَدُ البَهائِمُ\n\n﴿وِرۡدࣰا﴾: عِطاشًا."],[89,89,"﴿شَيۡـًٔا إِدࣰّا﴾: شَيئًا عَظِيمًا مُنْكَرًا."],[90,90,"﴿يَتَفَطَّرۡنَ مِنۡهُ﴾: يَتَشَقَّقْنَ ويَتَفَتَّتْنَ مِن شَناعَتِه.\n\n﴿تَنشَقُّ﴾: وتَتَصَدَّعُ.\n\n﴿وَتَخِرُّ ٱلۡجِبَالُ﴾: أي: تَسْقُطُ وتَنْهَدِمُ.\n\n﴿هَدًّا﴾: أي: مَهْدُودَةً ومَكْسُورَةً."],[97,97,"﴿لُّدࣰّا﴾: شَدِيدِي الخُصُومَةِ بالباطِل."],[98,98,"﴿مِّن قَرۡنٍ﴾: مِن أُمَمٍ.\n\n﴿رِكۡزَۢا﴾: صَوْتًا خَفِيًّا."]]);
QTF("gharib",20,[[2,2,"﴿لِتَشۡقَىٰٓ﴾: لِتَتْعبَ بفَرْطِ تأسُّفِكَ على كُفْرِهِم."],[3,3,"﴿تَذۡكِرَةࣰ﴾: عِظَةً وعِبْرةً."],[5,5,"﴿ٱلۡعَرۡشِ﴾: هو سَرِيَرُ المُلْكِ الذي اسْتَوى عَلَيه الرحمنُ، وتَحمِلُه الملائِكةُ، وهو أعْظَمُ المخْلُوقاتِ، وهو سَقْفُ الجنَّةِ.\n\n﴿ٱسۡتَوَىٰ﴾: عَلا وارْتَفَعَ، اسْتِواءً يلِيقُ بِجَلالِه وعَظَمَتِه."],[6,6,"﴿وَمَا تَحۡتَ ٱلثَّرَىٰ﴾: باطِنِ الأَرْضِ."],[9,9,"﴿حَدِيثُ مُوسَىٰٓ﴾: خبرُ مُوسى بن عِمْرانَ عليه الصَّلاةُ والسَّلامُ، لمّا رَجَعَ مِن مَدْيَنَ إلى مِصْرَ."],[12,12,"﴿طُوࣰى﴾: اسْمِ الوادِي الُمقَدَّسِ."],[14,14,"﴿لِذِكۡرِيٓ﴾: لِتَذْكُرَني فِيها."],[16,16,"﴿فَلَا يَصُدَّنَّكَ﴾: فلا يَصْرِفَنَّكَ.\n\n﴿فَتَرۡدَىٰ﴾: فَتَهْلَكَ."],[18,18,"﴿أَتَوَكَّؤُاْ عَلَيۡهَا﴾: أعْتَمِدُ عَلَيها في المَشْيِ.\n\n﴿وَأَهُشُّ بِهَا﴾: وأَهُزُّ بِها الشَّجَرَ لِيَسْقُطَ مِنه الوَرَقُ.\n\n﴿مَـَٔارِبُ﴾: حاجاتٌ ومَنافعُ."],[22,22,"﴿إِلَىٰ جَنَاحِكَ﴾: جَنبِك تَحْتَ العَضُدِ.\n\n﴿مِنۡ غَيۡرِ سُوٓءٍ﴾: مِن غَيرِ مَرَضٍ ولا بَرَصٍ."],[24,24,"﴿طَغَىٰ﴾: تَجاوَزَ حَدَّه بالتَّمَرُّدِ على ربِّه."],[27,27,"﴿وَٱحۡلُلۡ عُقۡدَةࣰ مِّن لِّسَانِي﴾: وأَطْلِقْ عَنْ لِساني العُقْدَةَ التي فِيه."],[29,29,"﴿وَزِيرࣰا﴾: مُعِينًا في إبْلاغِ رِسالتِكَ."],[31,31,"﴿ٱشۡدُدۡ بِهِۦٓ أَزۡرِي﴾: قَوِّني به وشُدَّ به ظَهْري."],[32,32,"﴿فِيٓ أَمۡرِي﴾: في النُّبوَّةِ وتَبْلِيغِ الرِّسالةِ."],[36,36,"﴿أُوتِيتَ سُؤۡلَكَ﴾: أُعطِيتَ كلَّ ما سألتَ."],[37,37,"﴿وَلَقَدۡ مَنَنَّا عَلَيۡكَ﴾: ولَقَدْ أنْعَمْنا عَلَيكَ.\n\n﴿مَرَّةً أُخۡرَىٰٓ﴾: نِعْمَةً أُخْرى بإنْجائِكَ مِن بَطْشِ فِرْعَونَ وجُنُودِه حِينَ كُنْتَ رَضِيعًا."],[38,38,"﴿أَوۡحَيۡنَآ﴾: ألْهَمْنا."],[39,39,"﴿ٱقۡذِفِيهِ﴾: ضَعِيه.\n\n﴿ٱلتَّابُوتِ﴾: الصُّنْدُوقِ الخَشَبِيِّ.\n\n﴿فَٱقۡذِفِيهِ فِي ٱلۡيَمِّ﴾: فاطْرَحِيه في النِّيلِ.\n\n﴿وَأَلۡقَيۡتُ عَلَيۡكَ مَحَبَّةࣰ مِّنِّي﴾: أي: أحْبَبْتُك، فَصِرْتَ بِذَلكَ مَحْبُوبًا بَيْنَ العِبادِ.\n\n﴿وَلِتُصۡنَعَ عَلَىٰ عَيۡنِيٓ﴾: ولِتُرَبّى بِمَرأىً مِنِّي."],[40,40,"﴿كَيۡ تَقَرَّ عَيۡنُهَا﴾: كي تُسَرَّ أُمُّ مُوسى بِسَلامةِ ولَدِها ورُجُوعِه إليها.\n\n﴿وَفَتَنَّـٰكَ﴾: وابْتَلَيناك.\n\n﴿عَلَىٰ قَدَرࣲ﴾: عَلى مَوْعِدٍ مُوافِقٍ للوقْتِ الُمقدَّرِ في عِلْمِ اللهِ تَعالى."],[41,41,"﴿وَٱصۡطَنَعۡتُكَ لِنَفۡسِي﴾: هَيَّأْتُكَ لِتَبْلِيغِ الرِّسالةِ عَنِّي."],[42,42,"﴿وَلَا تَنِيَا﴾: ولا تَضْعُفا."],[43,43,"﴿طَغَىٰ﴾: جاوَزَ الحَدَّ في الكُفْرِ والظُّلْمِ."],[45,45,"﴿أَن يَفۡرُطَ عَلَيۡنَآ﴾: أن يُعاجِلَنا ويُبادِرَ بالعُقُوبَةِ.\n\n﴿أَوۡ أَن يَطۡغَىٰ﴾: أو أن يَتَمَرَّدَ على الحقِّ فلا يَقْبَلَه."],[47,47,"﴿وَلَا تُعَذِّبۡهُمۡ﴾: أي: ولا تُعَذِّبْهم بِذَبْحِ أبْنائِهِم واسْتِحْياءِ بَناتِهِم وتَكْلِيفِهِم بِما لا يُطِيقُونَ مِنَ الأَعْمالِ."],[50,50,"﴿خَلۡقَهُۥ﴾: أي: صورتَه اللائِقَةَ بخاصَّتِه ومَنفَعَتِه."],[51,51,"﴿فَمَا بَالُ ٱلۡقُرُونِ ٱلۡأُولَىٰ﴾: فما شأنُ الأممِ السّابِقَةِ؟"],[52,52,"﴿فِي كِتَـٰبࣲ﴾: وهو اللَّوحُ الَمحْفُوظُ.\n\n﴿لَّا يَضِلُّ رَبِّي﴾: أي: لا يُخْطِئُ ربِّي في أفْعالِه وأَحْكامِه.\n\n﴿وَلَا يَنسَى﴾: أيَّ شيءٍ ممّا عَلِمه مِنها."],[53,53,"﴿مَهۡدࣰا﴾: أي: مُيَسَّرةً للانْتِفاعِ بِها، فَصارَتْ كالفِراشِ والِمْهادِ لكلِّ واحدٍ مِنكُم.\n\n﴿وَسَلَكَ لَكُمۡ فِيهَا سُبُلࣰا﴾: وجَعَل لَكُم فِيها طُرُقًا كَثِيرَةً.\n\n﴿أَزۡوَ ٰ⁠جࣰا مِّن نَّبَاتࣲ شَتَّىٰ﴾: أنْواعًا مُخْتَلِفَةً مِنَ النَّباتِ."],[54,54,"﴿لِّأُوْلِي ٱلنُّهَىٰ﴾: لِذَوي العُقُولِ السَّلِيمَةِ."],[56,56,"﴿ءَايَـٰتِنَا﴾: أدلَّتَنا وحُجَجَنا.\n\n﴿وَأَبَىٰ﴾: وامْتَنَعَ عَن قَبُولِ الحَقِّ."],[58,58,"﴿مَكَانࣰا سُوࣰى﴾: في مَكانٍ مُعْتَدِلٍ مُسْتَوٍ بَيْنَنا وبَيْنَكَ."],[59,59,"﴿يَوۡمُ ٱلزِّينَةِ﴾: يومُ العيدِ حِينَ يتزيَّنُ الناسُ.\n\n﴿وَأَن يُحۡشَرَ﴾: وأن يُجْمَعَ."],[61,61,"﴿لَا تَفۡتَرُواْ﴾: لا تَخْتَلِقُوا.\n\n﴿فَيُسۡحِتَكُم﴾:. فَيَسْتَأْصِلَكُم ويُبِيدَكُمْ.\n\n﴿خَابَ﴾: خَسِرَ وهَلَكَ."],[62,62,"﴿وَأَسَرُّواْ ٱلنَّجۡوَىٰ﴾: تَحادَثَ السَّحَرةُ سِرًّا في خَفاءٍ."],[63,63,"﴿بِطَرِيقَتِكُمُ ٱلۡمُثۡلَىٰ﴾: بِطَرِيقةِ السِّحْرِ العظيمةِ التي أنْتُم عَلَيها."],[64,64,"﴿فَأَجۡمِعُواْ كَيۡدَكُمۡ﴾: فأَحْكِمُوا مَكْرَكُم، ولا تَجْعَلُوهُ مُتَفَرِّقًا.\n\n﴿مَنِ ٱسۡتَعۡلَىٰ﴾: مَن عَلا عَلى صاحِبِه فَغَلَبَهُ وقَهَرَهُ."],[67,67,"﴿فَأَوۡجَسَ﴾: فَأَضْمَرَ.\n\n﴿خِيفَةࣰ﴾: خَوْفًا."],[68,68,"﴿أَنتَ ٱلۡأَعۡلَىٰ﴾: أنتَ الغالِبُ على هَؤلاءِ السَّحَرةِ."],[69,69,"﴿تَلۡقَفۡ﴾: تَبْتَلِعْ بِسُرْعَةٍ.\n\n﴿وَلَا يُفۡلِحُ ٱلسَّاحِرُ﴾: ولا يَظْفَرَ السَّحرةُ بِبُغْيتِهِم."],[71,71,"﴿خِلَـٰفࣲ﴾: مُخالِفًا بينها: يدًا مِن جِهَةٍ ورِجْلًا مِنَ الجِهَةِ الأخْرى.\n\n﴿وَلَأُصَلِّبَنَّكُمۡ﴾: ولَأُبالِغَنّ في شَدِّ أطْرافِكَم ورَبْطِ أجْسادِكُم.\n\n﴿فِي جُذُوعِ ٱلنَّخۡلِ﴾: على جُذُوعِ النَّخْلِ.\n\n﴿وَأَبۡقَىٰ﴾: وأَدْوَمُ، لا يَنْقَطِعُ."],[72,72,"﴿لَن نُّؤۡثِرَكَ﴾: لن نُفَضِّلَكَ."],[74,74,"﴿مُجۡرِمࣰا﴾: كافِرًا.\n\n﴿لَا يَمُوتُ فِيهَا وَلَا يَحۡيَىٰ﴾: أي: لا يمُوتُ فيها فَيَسْتَرِيحَ، ولا يحيا حياةً يتلذَّذُ بِها."],[76,76,"﴿جَنَّـٰتُ عَدۡنࣲ﴾: جَنّاتُ إقامَةٍ دائمةٍ.\n\n﴿مَن تَزَكَّىٰ﴾: مَن تَطهَّرَ مِنَ الكُفْرِ والمَعاصِي."],[77,77,"﴿أَنۡ أَسۡرِ﴾: أنِ اخْرُجْ ليلًا بِعِبادِي.\n\n﴿فَٱضۡرِبۡ لَهُمۡ﴾: فاجْعَلْ لهم.\n\n﴿يَبَسࣰا﴾: يابسًا لا ماءٌ فِيها ولا طِينٌ.\n\n﴿لَّا تَخَـٰفُ دَرَكࣰا﴾: لا تخافُ مِن فِرْعَونَ وجُنُودِهِ أن يَلْحَقَ بكُم فيُدْرِكَكُم.\n\n﴿وَلَا تَخۡشَىٰ﴾: ولا تَخْشى مِنَ الغَرَقِ في البَحْرِ."],[78,78,"﴿فَغَشِيَهُم مِّنَ ٱلۡيَمِّ مَا غَشِيَهُمۡ﴾: فَغَمَرَهُم مِن مّاءِ البَحْرِ ما لا يَعْلَمُ كُنهَه إلّا اللهُ."],[80,80,"﴿ٱلۡمَنَّ﴾: شيءٌ يُشْبِهُ الصَّمْغَ، طَعْمُه كالعَسَلِ.\n\n﴿وَٱلسَّلۡوَىٰ﴾: طَيرٌ يُشْبِهُ السُّمانى."],[81,81,"﴿وَلَا تَطۡغَوۡاْ فِيهِ﴾: ولا تَحْمِلنَّكُم العافيةُ والسَّعَةُ في الرِّزقِ على تَجاوُزِ الحدِّ في العِصْيانِ.\n\n﴿فَيَحِلَّ عَلَيۡكُمۡ﴾: فيَنْزِلَ بِكُم.\n\n﴿هَوَىٰ﴾: هَلَكَ وخَسِرَ."],[82,82,"﴿ثُمَّ ٱهۡتَدَىٰ﴾: ثُمَّ التَزَمَ الهِدايةَ واسْتَقامَ عَلَيها."],[84,84,"﴿عَلَىٰٓ أَثَرِي﴾: خَلْفي سَوفَ يَلْحَقُون بِي.\n\n﴿لِتَرۡضَىٰ﴾: لِتَزْدادَ عَنِّي رِضًا."],[85,85,"﴿قَدۡ فَتَنَّا﴾: قد ابتلينا.\n\n﴿وَأَضَلَّهُمُ﴾: دَعاهُم إلى الضَّلالَةِ التي هِيَ عِبادةُ العِجْلِ.\n\n﴿ٱلسَّامِرِيُّ﴾: مَنسُوبٌ إلى «قبيلةِ السّامِرَة» قيل: كان إسْرائِيليًا، وقيل: كانَ قِبْطيًا."],[86,86,"﴿أَسِفࣰا﴾: حَزِينًا كَئِيبًا.\n\n﴿وَعۡدًا حَسَنًا﴾: أي: بإنزالِ التَّوراةِ.\n\n﴿ٱلۡعَهۡدُ﴾: الزَّمانُ.\n\n﴿فَأَخۡلَفۡتُم مَّوۡعِدِي﴾: خالفْتُم ما وعَدْتُّمُونِي مِن عِبادَةِ اللهِ وحْدَه."],[87,87,"﴿بِمَلۡكِنَا﴾: باخْتِيارِنا.\n\n﴿أَوۡزَارࣰا﴾: أثْقالًا.\n\n﴿مِّن زِينَةِ ٱلۡقَوۡمِ﴾: مِن حُلِيِّ قومِ فِرْعَونَ.\n\n﴿فَقَذَفۡنَـٰهَا﴾: فَأَلْقَينا الحُلِيَّ في النّارِ.\n\n﴿فَكَذَ ٰ⁠لِكَ أَلۡقَى ٱلسَّامِرِيُّ﴾: أي: فَكَذَلِك ألْقى السّامِريُّ ما كان مَعَهُ مِن تُرْبَةِ حافِرِ فَرَسِ جِبْريلَ عليه السَّلامُ."],[88,88,"﴿عِجۡلࣰا جَسَدࣰا﴾: مَعْبُودًا مِن ذَهَبِهِم على صُورَةِ العِجْلِ بلا رُوحٍ.\n\n﴿لَّهُۥ خُوَارࣱ﴾: له صَوْتٌ يُشْبِهُ صوتَ البَقَرِ.\n\n﴿فَنَسِيَ﴾: فَغَفَلَ عنه مُوسى نِسْيانًا."],[89,89,"﴿أَلَّا يَرۡجِعُ إِلَيۡهِمۡ قَوۡلࣰا﴾: لا يُكَلِّمُهم ولا يَرُدُّ عَلِيهِم جَوابًا."],[90,90,"﴿فُتِنتُم بِهِۦ﴾: بِهَذا العِجْلِ."],[91,91,"﴿لَن نَّبۡرَحَ عَلَيۡهِ عَـٰكِفِينَ﴾: لَن نَزالَ مُقيمِينَ على عِبادَةِ العِجْل."],[94,94,"﴿وَلَمۡ تَرۡقُبۡ قَوۡلِي﴾: ولَمْ تَعْمَلْ بوَصِيَّتِي لَكَ فِيهِم."],[95,95,"﴿فَمَا خَطۡبُكَ﴾: أي: ما الَّذِي حَمَلَكَ على ما صَنَعْتَ؟"],[96,96,"﴿فَقَبَضۡتُ قَبۡضَةࣰ﴾: فَأَخَذْتُ بِكَفِّي تُرابًا.\n\n﴿مِّنۡ أَثَرِ ٱلرَّسُولِ﴾: مِن أثَرِ حافِرِ فرسِ جِبْرِيلَ عليهِ السلامُ.\n\n﴿فَنَبَذۡتُهَا﴾: فألقيتُ حَفْنَةَ التُّرابِ على الحُليِّ التي صُنِعَ منها العِجلُ.\n\n﴿سَوَّلَتۡ لِي نَفۡسِي﴾: زَيَّنَتْ لي نَفْسِي ما صَنَعْتُ."],[97,97,"﴿لَا مِسَاسَ﴾: أي لا يَمَسَّكَ أحدٌ، ولا تَمَسَّ أحدًا في الدُّنيا، فَتَعِيشَ مَنبُوذًا.\n\n﴿لَكَ مَوۡعِدࣰا﴾: أي: في الآخرةِ لِعِقابِك.\n\n﴿لَّن تُخۡلَفَهُۥ﴾: لَن يُخْلِفَكَ اللهُ إيّاهُ.\n\n﴿ظَلۡتَ عَلَيۡهِ عَاكِفࣰا﴾: أقمتَ مواظِبًا على عبادتِه.\n\n﴿ثُمَّ لَنَنسِفَنَّهُۥ﴾: ثم لنَذْرُوَنَّه حَتّى لا يَبْقى منه أثَرٌ.\n\n﴿ٱلۡيَمِّ﴾: البَحرِ."],[99,99,"﴿ذِكۡرࣰا﴾: القرآنَ؛ لِما فيه مِنَ التَّذْكِيرِ."],[100,100,"﴿وِزۡرًا﴾: إثمًا عَظِيمًا."],[102,102,"﴿ٱلصُّورِ﴾: القَرْنِ الذي يُنفَخُ فيه للبعثِ.\n\n﴿وَنَحۡشُرُ﴾: نَسُوقُ.\n\n﴿زُرۡقࣰا﴾: زُرْقَ العُيونِ والأجْسادِ من هَوْلِ المصيبة."],[103,103,"﴿يَتَخَـٰفَتُونَ بَيۡنَهُمۡ﴾: يَتَسارُّونَ فِيما بَيْنَهم."],[104,104,"﴿أَمۡثَلُهُمۡ طَرِيقَةً﴾: أعْلَمُهم وأَكْمَلُهم رأيًا."],[105,105,"﴿يَنسِفُهَا رَبِّي نَسۡفࣰا﴾: يَقْلعُها رَبي مِن أُصُولِها فَتَتَطايرُ كالصُّوفِ المنفُوشِ."],[106,106,"﴿فَيَذَرُهَا﴾: فَيَتْرُكُ الأرضَ.\n\n﴿قَاعࣰا﴾: أرْضًا لا نَباتٌ فيها ولا بناءٌ.\n\n﴿صَفۡصَفࣰا﴾: مَلْساءَ مُسْتَوِيَةً."],[107,107,"﴿عِوَجࣰا﴾: مَيْلًا.\n\n﴿وَلَآ أَمۡتࣰا﴾: ولا ارْتفِاعًا ولا انْخِفاضًا."],[108,108,"﴿لَا عِوَجَ﴾: لا مَحِيدَ لهم من اتِّباعِ داعِي اللهِ إلى المَحْشَرِ.\n\n﴿هَمۡسࣰا﴾: صَوْتًا خَفِيًّا."],[110,110,"﴿مَا بَيۡنَ أَيۡدِيهِمۡ﴾: أي: مِن أمْرِ القِيامةِ.\n\n﴿وَمَا خَلۡفَهُمۡ﴾: أي: مِن أمْرِ الدُّنْيا."],[111,111,"﴿وَعَنَتِ﴾: ذلَّتْ وخَضَعَتْ.\n\n﴿ٱلۡقَيُّومِ﴾: الدّائِمِ القَيّامِ بِتَدْبِيرِ الخَلْقِ وحِفْظِهِم.\n\n﴿خَابَ﴾: خَسِرَ وهَلَكَ.\n\n﴿ظُلۡمࣰا﴾: شِرْكًا باللهِ."],[112,112,"﴿ظُلۡمࣰا وَلَا هَضۡمࣰا﴾: ظُلْمًا بِزيادةِ سَيِّئاتِه في الآخِرةِ، ولا هَضْمًا بِنَقْصِ حَسَناتِه فيها."],[113,113,"﴿أَوۡ يُحۡدِثُ لَهُمۡ ذِكۡرࣰا﴾: أي: يُحدِثُ فِيهم هذا القرآنُ تَذَكُّرًا واعْتِبارًا."],[114,114,"﴿وَلَا تَعۡجَلۡ بِٱلۡقُرۡءَانِ﴾: لا تُسارِعْ بِقِراءتِه.\n\n﴿مِن قَبۡلِ أَن يُقۡضَىٰٓ إِلَيۡكَ وَحۡيُهُۥ﴾: من قَبْلِ أن يَفرغَ جبريلُ ويُتِمَّ إليك الوحيَ."],[115,115,"﴿عَهِدۡنَآ إِلَىٰٓ ءَادَمَ﴾: وصَّيناهُ، أو أوحينا إليه.\n\n﴿عَزۡمࣰا﴾: قوَّةً في الإرادةِ يَحْفَظُ بها ما أُمِرَ به."],[116,116,"﴿أَبَىٰ﴾: امْتَنَعَ مِنَ السُّجُودِ اسْتِكْبارًا."],[117,117,"﴿فَتَشۡقَىٰٓ﴾: فتعانيَ المتاعِبَ والمشاقَّ في الدُّنيا."],[118,118,"﴿أَلَّا تَجُوعَ فِيهَا﴾: أي: لا يُصِيبَكَ في الجنَّةِ جُوعٌ.\n\n﴿وَلَا تَعۡرَىٰ﴾: أي: لا تَعْرى فيها عن الملابِسِ."],[119,119,"﴿لَا تَظۡمَؤُاْ فِيهَا﴾: لا يُصِيبُكَ في الجنَّةِ عَطَشٌ.\n\n﴿وَلَا تَضۡحَىٰ﴾: ولا يُصيبُك حرُّ شَمْسٍ."],[120,120,"﴿شَجَرَةِ ٱلۡخُلۡدِ﴾: هي الشجرةُ التي مَن أكَلَ مِنها لم يَمُتْ.\n\n﴿لَّا يَبۡلَىٰ﴾: لا يَنْقَطِعُ."],[121,121,"﴿فَبَدَتۡ لَهُمَا سَوۡءَ ٰ⁠ تُهُمَا﴾: فانْكَشَفَتْ لِآدَمَ وحَوّاءَ عَوْراتُهما.\n\n﴿وَطَفِقَا يَخۡصِفَانِ﴾: وجَعلا يَلْصَقان.\n\n﴿فَغَوَىٰ﴾: فَضَلَّ طَريقَ الصَّوابِ."],[122,122,"﴿ٱجۡتَبَـٰهُ﴾: اصْطَفاه."],[123,123,"﴿ٱهۡبِطَا﴾: انْزِلا مِنَ الجَنَّةِ إلى الأرضِ.\n\n﴿فَلَا يَضِلُّ﴾: أي: عَن طَرِيقِ الهِدايةِ.\n\n﴿وَلَا يَشۡقَىٰ﴾: لا يَشْقى في الآخرةِ بعِقابِ اللهِ."],[124,124,"﴿ذِكۡرِي﴾: أي: عَن ذِكْرِي الَّذِي أُذَكِّرهُ بِهِ مِن قُرآنٍ وغَيْرِهِ.\n\n﴿ضَنكࣰا﴾: ضَيِّقةً شاقَّةً في حَياتِه وقَبْرِه."],[126,126,"﴿فَنَسِيتَهَا﴾: أي: بِتَرْكِ الإيمانِ بها.\n\n﴿تُنسَىٰ﴾: تُتْرَكُ في النّارِ."],[127,127,"﴿مَنۡ أَسۡرَفَ﴾: تَجاوَزَ حدودَ ما شَرَعَ اللهُ.\n\n﴿وَأَبۡقَىٰٓ﴾: أدْوَمُ مِن عذابِ الدُّنيا، فلا يَنْقَطِعُ."],[128,128,"﴿يَهۡدِ لَهُمۡ﴾: أي: يَدُلَّهم على طَريقِ الرَّشادِ.\n\n﴿مِّنَ ٱلۡقُرُونِ﴾: مِنَ الأُمَمِ الماضيةِ.\n\n﴿لَـَٔايَـٰتࣲ﴾: لَعِبَرًا وعِظاتٍ.\n\n﴿لِّأُوْلِي ٱلنُّهَىٰ﴾: لأصْحابِ العقولِ السَّلِيمةِ."],[129,129,"﴿لَكَانَ لِزَامࣰا﴾: لَلازَمَهم الهَلاكُ عاجِلًا؛ بسببِ كُفْرِهم."],[130,130,"﴿ءَانَآيِٕ ٱلَّيۡلِ﴾: ساعاتِ الليلِ.\n\n﴿تَرۡضَىٰ﴾: أي: تُثابُ على عَمَلِك بما يُرضِيكَ."],[131,131,"﴿وَلَا تَمُدَّنَّ عَيۡنَيۡكَ﴾: لا تُكَرِّرِ النَّظَرَ إلى المُشْرِكِينَ مُسْتَحْسِنًا.\n\n﴿أَزۡوَ ٰ⁠جࣰا مِّنۡهُمۡ﴾: أصْنافًا مِن الكفّارِ.\n\n﴿زَهۡرَةَ ٱلۡحَيَوٰةِ﴾: زينتَها وبَهْجَتَها التي لا تَدُومُ.\n\n﴿لِنَفۡتِنَهُمۡ﴾: لِنَبْتليَهم."],[132,132,"﴿وَٱصۡطَبِرۡ عَلَيۡهَا﴾: داوِمْ على إقامةِ الصَّلاةِ بِصَبْرٍ."],[133,133,"﴿بِـَٔايَةࣲ﴾: بِمُعْجِزَةٍ.\n\n﴿بَيِّنَةُ مَا فِي ٱلصُّحُفِ ٱلۡأُولَىٰ﴾: أي: هذا القرآنُ مصدِّقٌ لما في الكُتُبِ السّابِقَةِ مِنَ الحقِّ."],[134,134,"﴿مِّن قَبۡلِهِۦ﴾: أي: من قبْلِ أن نُرسِلَ إليهم رَسُولًا.\n\n﴿أَن نَّذِلَّ وَنَخۡزَىٰ﴾: أن يُصيَبنا ذُلٌّ وخِزيٌ بعذابِكَ في الدُّنيا والآخِرةِ."],[135,135,"﴿كُلࣱّ مُّتَرَبِّصࣱ﴾: كلٌّ مِنّا ومِنكُم منتظِرٌ دوائرَ الزمانِ.\n\n﴿فَتَرَبَّصُواْ﴾: فانْتَظِرُوا."]]);
QTF("gharib",21,[[2,2,"﴿مِّن ذِكۡرࣲ﴾: أي: مِن قُرْآنٍ.\n\n﴿مُّحۡدَثٍ﴾: أي: يَتَجَدَّدُ نُزُولُه."],[3,3,"﴿لَاهِيَةࣰ﴾: غافِلةً.\n\n﴿وَأَسَرُّواْ ٱلنَّجۡوَى﴾: اجْتَمَعُوا سِرًّا على أمْرٍ خَفِيٍّ.\n\n﴿ٱلسِّحۡرَ﴾: القرآنَ (على زَعْمِ الكُفّار)."],[5,5,"﴿أَضۡغَـٰثُ أَحۡلَـٰمِۭ﴾: أخْلاطُ أحْلامٍ لا حقيقةَ لها.\n\n﴿بَلِ ٱفۡتَرَىٰهُ﴾: بَلِ اخْتَلَقَه."],[7,7,"﴿إِلَّا رِجَالࣰا﴾: أي: مِنَ البَشَرِ فقط.\n\n﴿أَهۡلَ ٱلذِّكۡرِ﴾: أهْلَ العِلْمِ بالكُتُبِ الُمنَزَّلةِ السّابقَةِ."],[9,9,"﴿ٱلۡمُسۡرِفِينَ﴾: الُمتَجاوِزِينَ الحَدَّ بِكُفْرِهم بِرَبِّهم."],[10,10,"﴿ذِكۡرُكُمۡ﴾: عِزُّكُم وشَرَفُكم إنْ عَمِلْتُم بما جاءَ فيه."],[11,11,"﴿قَصَمۡنَا﴾: أهْلَكْنا واسَتْأصَلْنا.\n\n﴿كَانَتۡ ظَالِمَةࣰ﴾: كانَ أهلُها ظالِميَنَ بِكُفْرِهم باللهِ وبِما جاءتْهم به رُسُلُه.\n\n﴿وَأَنشَأۡنَا﴾: خَلَقْنا وأَوْجَدْنا."],[12,12,"﴿أَحَسُّواْ بَأۡسَنَآ﴾: أي: عَلِمُوا وتيَقَّنُوا بِوُقُوعِ عَذابِنا بِمُشاهَدَةِ بَوادِرِه.\n\n﴿يَرۡكُضُونَ﴾: يَهرُبُون مُسرِعِينَ."],[13,13,"﴿لَا تَرۡكُضُواْ﴾: لا تَهرُبُوا.\n\n﴿أُتۡرِفۡتُمۡ فِيهِ﴾: أُنْعِمْتُم فِيه مِنَ التَّرفِ.\n\n﴿لَعَلَّكُمۡ تُسۡـَٔلُونَ﴾: لَعَلَّكُم تُسْأَلُونَ مِن دُنْياكُم شَيْئًا، قِيلَ لَهُم ذَلك اسْتِهْزاءً بِهِم."],[14,14,"﴿يَـٰوَيۡلَنَآ﴾: يا هَلاكَنا."],[15,15,"﴿تِّلۡكَ دَعۡوَىٰهُمۡ﴾: أي: كلِمتَهم: «يا ويلَنا» يَدْعُونَ بها، ويُرَدِّدُونَها.\n\n﴿حَصِيدًا﴾: مُسْتَأْصَلِينَ كما يُحصَدُ الزَّرْعُ.\n\n﴿خَـٰمِدِينَ﴾: هالِكِينَ، قدِ انْطَفَأَتْ شَرارَةُ حَياتِهمِ."],[16,16,"﴿لَـٰعِبِينَ﴾: عَبَثًا ولَهْوًا وباطِلًا."],[17,17,"﴿لَهۡوࣰا﴾: ما يُتلهّى بِه مِن زَوْجَةٍ ووَلَدٍ.\n\n﴿مِن لَّدُنَّآ﴾: مِن عِنْدِنا مِنَ أهْل السَّماءِ مِنَ الحُورِ العِينِ."],[18,18,"﴿بَلۡ نَقۡذِفُ﴾: بل نَرْمِي.\n\n﴿فَيَدۡمَغُهُۥ﴾: فيَمْحَقُه ويَدْحَضُه.\n\n﴿زَاهِقࣱ﴾: زائِلٌ وذاهِبٌ.\n\n﴿ٱلۡوَيۡلُ﴾: العَذابُ."],[19,19,"﴿لَا يَسۡتَكۡبِرُونَ عَنۡ عِبَادَتِهِۦ﴾: لا يَتَعاظَمُونَ عَن عِبادتِه.\n\n﴿وَلَا يَسۡتَحۡسِرُونَ﴾: لا يُصِيبُهُم إعياءٌ ولا مَلَلٌ مِن عِبادَةِ اللهِ."],[20,20,"﴿لَا يَفۡتُرُونَ﴾: لا يَضْعُفُونَ ولا يَسْأمُونَ."],[21,21,"﴿أَمِ ٱتَّخَذُوٓاْ ءَالِهَةࣰ مِّنَ ٱلۡأَرۡضِ هُمۡ يُنشِرُونَ﴾: هَلِ اتَّخَذَ المُشْرِكُونَ آلهةً مِنَ الأرْضِ قادِرَةً على إحْياءِ المَوتى؟"],[22,22,"﴿لَفَسَدَتَا﴾: لبَطَلَتا، واخْتَلَّ نِظامُهما.\n\n﴿فَسُبۡحَـٰنَ ٱللَّهِ﴾: تَنَزَّهَ اللهُ تعالى.\n\n﴿عَمَّا يَصِفُونَ﴾: عَمّا يَصِفُه الكافِرونَ مِنِ ادِّعاءِ شَريكٍ لَه."],[24,24,"﴿أَمِ ٱتَّخَذُواْ﴾: بَلِ اتَّخَذُوا.\n\n﴿هَاتُواْ بُرۡهَـٰنَكُمۡ﴾: ايتُوا بِحُجَّتِكُم على اتِّخاذِكُم الآلِهَةَ المزْعُومةَ.\n\n﴿ذِكۡرُ مَن مَّعِيَ﴾: القرآنُ الذي جِئْتُ به.\n\n﴿وَذِكۡرُ مَن قَبۡلِي﴾: أي: الكُتُبُ السّابِقَةُ."],[26,26,"﴿ٱتَّخَذَ ٱلرَّحۡمَـٰنُ وَلَدࣰا﴾: أي: بزَعْمِهِم أنّ الملائِكةَ بناتُ اللهِ.\n\n﴿سُبۡحَـٰنَهُۥ﴾: تَنَزَّهَ اللهُ عَنْ ذَلِكَ.\n\n﴿مُّكۡرَمُونَ﴾: أكْرَمَهُم الله بِعِبادَتِه وخَصَّصَهم بالفَضائِلِ."],[27,27,"﴿لَا يَسۡبِقُونَهُۥ بِٱلۡقَوۡلِ﴾: أي: لا يَتَكَلَّمُونَ إلّا بما يْأمُرُهم بِه ربُّهم؛ لِكَمالِ انْقِيادِهم وطاعَتِهم."],[28,28,"﴿يَعۡلَمُ مَا بَيۡنَ أَيۡدِيهِمۡ﴾: يَعلَمُ كلَّ ما عَمِلُوه.\n\n﴿وَمَا خَلۡفَهُمۡ﴾: وما هم عامِلُونَ في الُمسْتَقْبَل.\n\n﴿إِلَّا لِمَنِ ٱرۡتَضَىٰ﴾: أي: إلا لِمَن رَضِيَ اللهُ بشَفاعَتِهم لَهُ.\n\n﴿مُشۡفِقُونَ﴾: حَذِرونَ أن يَعْصُوه."],[30,30,"﴿رَتۡقࣰا﴾: مُلْتَصِقَتَينِ لا فاصِلَ بَيْنَهما.\n\n﴿فَفَتَقۡنَـٰهُمَا﴾: ففَصَلْناهُما بِقُدرَتِنا."],[31,31,"﴿رَوَ ٰ⁠سِيَ﴾: جبالًا ثَوابِتَ.\n\n﴿أَن تَمِيدَ بِهِمۡ﴾: لِئلا تَتَحَرَّكَ الأرضُ وتَضطَرِبَ بِأهْلِها.\n\n﴿فِجَاجࣰا سُبُلࣰا﴾: طُرُقًا واسِعةً."],[32,32,"﴿سَقۡفࣰا﴾: أي: سَقْفًا لِلأَرْضِ.\n\n﴿مَّحۡفُوظࣰا﴾: أي: عَنِ السُّقوطِ، وعَنِ اخْتِراقِ الشَّياطِينِ."],[33,33,"﴿كُلࣱّ﴾: أي: كلٌّ مِنَ الشَّمسِ والقَمَرِ والنُّجُومِ.\n\n﴿فَلَكࣲ﴾: مَدارٍ.\n\n﴿يَسۡبَحُونَ﴾: يدُورُونَ بانْبِساطٍ وسُهُولةٍ."],[34,34,"﴿ٱلۡخُلۡدَ﴾: دَوامَ البقاءِ في الدُّنيا."],[35,35,"﴿وَنَبۡلُوكُم﴾: نَخْتَبِرُكُم ونَبْتَلِيكُم.\n\n﴿فِتۡنَةࣰ﴾: اخْتِبارًا وابْتِلاءً."],[36,36,"﴿هُزُوًا﴾: مُسْتَهْزَأً بِك.\n\n﴿يَذۡكُرُ ءَالِهَتَكُمۡ﴾: يَعِيبُ آلهتَكُم."],[37,37,"﴿خُلِقَ ٱلۡإِنسَـٰنُ مِنۡ عَجَلࣲ﴾: خُلِقَ الإنسانُ عَجُولًا مُتَسَرِّعًا بِفِطْرَتِه.\n\n﴿سَأُوْرِيكُمۡ ءَايَـٰتِي﴾: أي: بنَصْرِ هذا الدِّينِ وهَلاكِ مَن كَفَرَ به وحارَبَه."],[38,38,"﴿ٱلۡوَعۡدُ﴾: أي: الوعدُ بالعذابِ."],[39,39,"﴿لَا يَكُفُّونَ﴾: لا يَقْدِرُونَ أن يَمْنَعُوا."],[40,40,"﴿بَغۡتَةࣰ﴾: فَجْأَةً.\n\n﴿فَتَبۡهَتُهُمۡ﴾: فتُحَيِّرُهم.\n\n﴿وَلَا هُمۡ يُنظَرُونَ﴾: ولا هم يُؤخَّرُونَ، ولا هم يُمهَلُونَ لتوبَةٍ أو اعْتِذارٍ."],[41,41,"﴿فَحَاقَ﴾: نَزَلَ وأَحاطَ.\n\n﴿سَخِرُواْ مِنۡهُم﴾: اسْتَهْزَؤُوا بهم."],[42,42,"﴿يَكۡلَؤُكُم﴾: يَحْفَظُكُم ويَحْرُسُكُم.\n\n﴿مِنَ ٱلرَّحۡمَـٰنِ﴾: أي: مِن عَذابِه وعِقابِه إذا حَلَّ بِكُم.\n\n﴿ذِكۡرِ رَبِّهِم﴾: أي: القرآنِ وما فيه مِن مَّواعِظَ."],[43,43,"﴿وَلَا هُم مِّنَّا يُصۡحَبُونَ﴾: أي: ولا هم يُجارُون مِن عَذابِنا."],[44,44,"﴿بَلۡ مَتَّعۡنَا﴾: بل أمهَلْناهُم؛ لِيَتَمَتَّعُوا.\n\n﴿نَنقُصُهَا مِنۡ أَطۡرَافِهَآ﴾: أي: نَنْقُصُ أرضَ الكفّارِ بالظُّهُورِ والغَلَبَةِ عليها مِن كُلِّ ناحيةٍ وجِهَةٍ، فنَفْتحُها بلَدًا بعد بلَدٍ.\n\n﴿أَفَهُمُ ٱلۡغَـٰلِبُونَ﴾: أي: كيف يكونُون غالِبينَ بعد نَقْصِنا لأَرْضِهم مِن أطْرافِها؟"],[45,45,"﴿أُنذِرُكُم﴾: أُخَوِّفُكُم.\n\n﴿بِٱلۡوَحۡيِ﴾: بالقرآنِ.\n\n﴿ٱلصُّمُّ﴾: جمعُ الأصَمّ، وهو الذي لا يَسْمَعُ، والمرادُ الكافرُ الذي لا يُصْغِي لِلْحَقِّ.\n\n﴿ٱلدُّعَآءَ﴾: النِّداءَ."],[46,46,"﴿مَّسَّتۡهُمۡ﴾: أصابَتْهُم.\n\n﴿نَفۡحَةࣱ﴾: دُفْعَةٌ يسيرةٌ.\n\n﴿يَـٰوَيۡلَنَآ﴾: يا هلاكَنا."],[47,47,"﴿ٱلۡمَوَ ٰ⁠زِينَ ٱلۡقِسۡطَ﴾: المَوازِينَ العادلةَ.\n\n﴿لِيَوۡمِ ٱلۡقِيَـٰمَةِ﴾: لِأهْلِ يومِ القيامةِ.\n\n﴿مِثۡقَالَ حَبَّةࣲ﴾: وزنَ حَبَّة\n\n﴿خَرۡدَلٍ﴾: وهو أصغرُ الحُبوبِ، والمرادُ أصْغرُ شَيءٍ."],[48,48,"﴿ٱلۡفُرۡقَانَ﴾: المُعْجِزاتِ التي يُمَيَّزُ بها الحقُّ عنِ الباطِلِ.\n\n﴿وَضِيَآءࣰ﴾: أي: التَّوْراةَ التي أضاءتْ لهم أمرَ دينِهِم.\n\n﴿وَذِكۡرࣰا﴾: يَتَذَكَّرُونَ بما في التَّوراةِ من المواعظِ."],[49,49,"﴿يَخۡشَوۡنَ رَبَّهُم﴾: يخافُونَ عذابَه.\n\n﴿بِٱلۡغَيۡبِ﴾: في حالِ غيابِهم عَنْ أعْيُنِ النّاسِ.\n\n﴿مُشۡفِقُونَ﴾: خائِفُونَ."],[50,50,"﴿وَهَـٰذَا ذِكۡرࣱ﴾: وهذا القرآنُ موعظَة لِمَن اتَّعَظَ به."],[51,51,"﴿رُشۡدَهُۥ﴾: هُداه اللائقَ به.\n\n﴿مِن قَبۡلُ﴾: مِن قَبْلِ مُوسى وهارُونَ."],[52,52,"﴿ٱلتَّمَاثِيلُ﴾: الأصنامُ التي صَنَعْتُمُوها بِأَيْدِيكُم.\n\n﴿لَهَا عَـٰكِفُونَ﴾: مُقِيمُونَ على عِبادَتِها على الدَّوامِ."],[54,54,"﴿ضَلَـٰلࣲ مُّبِينࣲ﴾: خُسْرانٍ واضِحٍ."],[55,55,"﴿بِٱلۡحَقِّ﴾: أي: أجادٌّ أنت فيما تَقُولُ؟\n\n﴿ٱللَّـٰعِبِينَ﴾: مِن الهازِلِينَ."],[56,56,"﴿فَطَرَهُنَّ﴾: خَلَقَهُنَّ."],[57,57,"﴿لَأَكِيدَنَّ أَصۡنَـٰمَكُم﴾: لَأَمْكُرَنَّ بأصنامِكُم ولَأَكْسِرَنَّها."],[58,58,"﴿جُذَ ٰ⁠ذًا﴾: حُطامًا قِطَعًا مُكسَّرةً."],[60,60,"﴿يَذۡكُرُهُمۡ﴾: يَعِيبُهم."],[61,61,"﴿عَلَىٰٓ أَعۡيُنِ ٱلنَّاسِ﴾: ظاهرًا بِمَرْأىً مِنَ النّاسِ.\n\n﴿يَشۡهَدُونَ﴾: أي: يَشْهَدُونَ عليه أنّه يَذْكُرُهم بِسُوءٍ."],[65,65,"﴿نُكِسُواْ عَلَىٰ رُءُوسِهِمۡ﴾: أي: لمّا غُلِبوا في الحُجَّةِ غَيَّروا رأيَهم."],[67,67,"﴿أُفࣲّ لَّكُمۡ﴾: قُبْحًا لكم."],[70,70,"﴿كَيۡدࣰا﴾: مَكْرًا لهلاكِه."],[71,71,"﴿إِلَى ٱلۡأَرۡضِ﴾: هي أرضُ «الشّام».\n\n﴿بَـٰرَكۡنَا فِيهَا﴾: أي: بِكَثْرَةِ الخيراتِ، وبِكَوْنِها أرْضَ الأنبياءِ عليهمُ الصَّلاةُ والسَّلامُ."],[72,72,"﴿وَيَعۡقُوبَ نَافِلَةࣰ﴾: زِيادةً عمّا طَلَبَ إبراهيمُ عليه الصَّلاةُ والسَّلامُ."],[74,74,"﴿حُكۡمࣰا﴾: نُبُوَّةً وفَصْلَ القَضاءِ بينَ الخُصُومِ.\n\n﴿ٱلۡقَرۡيَةِ﴾: هي قريةُ «سَدُوم».\n\n﴿ٱلۡخَبَـٰٓئِثَ﴾: هي أفعالُهم الُمنْكَرَةُ من إتيانِهم الرِّجالَ، وقَطْعِ السبيلِ وغيرِ ذلك.\n\n﴿قَوۡمَ سَوۡءࣲ﴾: قومًا عُرِفُوا بالأعمالِ القبيحةِ.\n\n﴿فَـٰسِقِينَ﴾: خارجِينَ عَن طاعةِ اللهِ."],[75,75,"﴿فِي رَحۡمَتِنَآ﴾: أي: في أهلِ رحمتِنا، وهم الأنبياءُ عليهمُ الصَّلاةُ والسَّلامُ."],[76,76,"﴿مِن قَبۡلُ﴾: أي: مِن قَبْلِ إبراهيمَ ولوطٍ عليهما الصَّلاةُ والسَّلامُ.\n\n﴿ٱلۡكَرۡبِ﴾: أي: الغَرَقِ بالطُّوفانِ."],[77,77,"﴿بِـَٔايَـٰتِنَآ﴾: بِحُجَجِنا الدالَّةِ على صِدْقِه.\n\n﴿قَوۡمَ سَوۡءࣲ﴾: قَومًا عُرِفُوا بالسُّوءِ والقُبْحِ.\n\n﴿فَأَغۡرَقۡنَـٰهُمۡ﴾: أي: بالطُّوفانِ الذي حَلَّ بهم."],[78,78,"﴿فِي ٱلۡحَرۡثِ﴾: أي: في قَضِيَّةِ الحَرْثِ.\n\n﴿نَفَشَتۡ فِيهِ﴾: انْتَشَرَتْ في الحَرْثِ ليلًا مِن غَيرِ راعٍ."],[79,79,"﴿فَفَهَّمۡنَـٰهَا سُلَيۡمَـٰنَ﴾: ففَهَّمنا سُليمانَ المسْأَلةَ بِمُراعاةِ مَصْلَحَةِ الطرفَينِ بالعَدْلِ.\n\n﴿حُكۡمࣰا وَعِلۡمࣰا﴾: نُبُوَّةً وعِلْمًا بأحْكامِ اللهِ.\n\n﴿وَسَخَّرۡنَا﴾: طَوَّعْنا."],[80,80,"﴿صَنۡعَةَ لَبُوسࣲ﴾: صِناعةَ دُروعٍ تُلبَسُ في الحربِ.\n\n﴿لِتُحۡصِنَكُم﴾: لِتَحْمِيَكم وتحفظَكُم.\n\n﴿مِّنۢ بَأۡسِكُمۡ﴾: مِن حَرْبِكُم."],[81,81,"﴿عَاصِفَةࣰ﴾: شديدةَ الهَبُوب.\n\n﴿إِلَى ٱلۡأَرۡضِ﴾: أي: أرْضِ بيتِ المقْدِسِ بالشّامِ."],[82,82,"﴿يَغُوصُونَ لَهُۥ﴾: يَنْزِلُونَ له في البحرِ لاسْتِخْراجِ ما يُطْلَبُ.\n\n﴿حَـٰفِظِينَ﴾: أي: حفِظَهمُ اللهُ من أنْ يَنْفَلِتُوا عَنْ سُليمانَ ومِن أنْ يُفْسِدُوا أعْمالَهم."],[83,83,"﴿مَسَّنِيَ ٱلضُّرُّ﴾: أصابَنِي الضُّرُّ مِن مَّرَضٍ ونَحْوِه."],[84,84,"﴿فَكَشَفۡنَا مَا بِهِۦ مِن ضُرࣲّ﴾: فَرَفَعْنا عَنْه مَرَضَهُ بِشِفائِنا إيِّاهُ.\n\n﴿وَذِكۡرَىٰ﴾: تَذْكِرَةً."],[87,87,"﴿وَذَا ٱلنُّونِ﴾: أي: واذْكُرْ صاحِبَ الحُوتِ، وذو النُّون لَقَبُ نَبِيِّ اللهِ يُونُسَ عليه الصَّلاةُ والسَّلامُ لابْتِلاعِ الحُوتِ لَه.\n\n﴿مُغَـٰضِبࣰا﴾: غَضْبانَ على قَومِه؛ لِكُفْرِهم.\n\n﴿أَن لَّن نَّقۡدِرَ عَلَيۡهِ﴾: أن لَن نُّضَيِّقَ عليه، ولَن نُّؤاخِذَه بِخُروجِه مِن بَيْنِ قومِه.\n\n﴿ٱلظُّلُمَـٰتِ﴾: هي ظُلْمَةُ الليلِ، وظُلْمَةُ البحرِ، وظُلْمَةُ بَطْنِ الحُوتِ."],[88,88,"﴿وَنَجَّيۡنَـٰهُ مِنَ ٱلۡغَمِّ﴾: وخَلَّصْناه مِن غَمِّهِ بإخْراجِنا له مِن بَطْنِ الحُوتِ."],[89,89,"﴿لَا تَذَرۡنِي فَرۡدࣰا﴾: لا تَتْرُكْنِي وحِيدًا لا عَقِبَ لي."],[90,90,"﴿وَأَصۡلَحۡنَا لَهُۥ زَوۡجَهُۥٓ﴾: أي: جَعَلْناها صالحةً في أخْلاقِها وصالحةً للحَمْلِ والولادةِ.\n\n﴿وَيَدۡعُونَنَا رَغَبࣰا﴾: يَعْبُدُونَنا راغِبينَ فيما عِنْدَنا.\n\n﴿وَرَهَبࣰا﴾: خائِفِينَ من عُقُوبَتِنا.\n\n﴿خَـٰشِعِينَ﴾: مُتَواضِعِينَ مُتَذَلِّلينَ."],[91,91,"﴿أَحۡصَنَتۡ فَرۡجَهَا﴾: حَفِظَتْ فَرْجَها مِنَ الحَلالِ والحَرام ولْم يَمَسَّها بَشَرٌ.\n\n﴿فَنَفَخۡنَا فِيهَا مِن رُّوحِنَا﴾: أي: أمَرْنا جبريلَ حتّى نَفَخَ في جَيْبِ قميصِها، فَخَلقَ اللهُ بذلكَ النَّفْخِ عيسى عليه السلام في بَطْنِها.\n\n﴿ءَايَةࣰ لِّلۡعَـٰلَمِينَ﴾: علامةً للخلْقِ على قُدْرِة اللهِ تعالى."],[92,92,"﴿أُمَّتُكُمۡ﴾: أي: الأنبياءُ عليهمُ الصَّلاةُ والسَّلامُ.\n\n﴿أُمَّةࣰ وَ ٰ⁠حِدَةࣰ﴾: أي: دينُهم واحدٌ، وهو الإسلامُ."],[93,93,"﴿وَتَقَطَّعُوٓاْ أَمۡرَهُم﴾: تَفَرَّقُوا في أمْرِ دِينِهم فِرَقًا."],[94,94,"﴿فَلَا كُفۡرَانَ لِسَعۡيِهِۦ﴾: لا جُحَودَ لِعَمَلِه بل يُشْكَرُ سَعْيُه ويُثابُ عليه."],[95,95,"﴿وَحَرَ ٰ⁠مٌ﴾: واجِبٌ."],[96,96,"﴿فُتِحَتۡ يَأۡجُوجُ وَمَأۡجُوجُ﴾: أي: يُفْتَحُ السَّدُّ عنهما فينطَلِقُونَ.\n\n﴿حَدَبࣲ﴾: مَكانٍ مُرْتَفعٍ مِنَ الأَرْضِ.\n\n﴿يَنسِلُونَ﴾: يَتَفَّرقُونَ في الأَرْضِ مُسْرِعِينَ."],[97,97,"﴿ٱلۡوَعۡدُ ٱلۡحَقُّ﴾: يومُ القيامةِ.\n\n﴿شَـٰخِصَةٌ﴾: مَفْتُوحَةٌ أجْفانُهم لا تَطْرِفُ.\n\n﴿مِّنۡ هَـٰذَا﴾: أي: يومِ البعثِ والحسابِ."],[98,98,"﴿حَصَبُ﴾: حَطَبُ.\n\n﴿وَ ٰ⁠رِدُونَ﴾: داخِلُونَ."],[100,100,"﴿زَفِيرࣱ﴾: أنينُ تَنَفُّسِهم الشَّدِيدُ.\n\n﴿لَا يَسۡمَعُونَ﴾: مِن هَولِ عَذابِهم."],[101,101,"﴿ٱلۡحُسۡنَىٰٓ﴾: السَّعادَةُ بِدُخُولِ الجنَّة.\n\n﴿عَنۡهَا﴾: أي: عَن نّارِ جَهَنَّمَ."],[102,102,"﴿حَسِيسَهَا﴾: أي: صَوْتَ لَهِيبِها."],[103,103,"﴿لَا يَحۡزُنُهُمُ﴾: لا يُخِيفُهم.\n\n﴿ٱلۡفَزَعُ ٱلۡأَكۡبَرُ﴾: الهولُ العظيمُ يومَ القيامةِ.\n\n﴿تَتَلَقَّىٰهُمُ﴾: تَسْتَقْبِلُهم مُهَنِّئين."],[104,104,"﴿نَطۡوِي ٱلسَّمَآءَ﴾: أي: نَطْويها كما يَطْوي الكاتِبُ الوَرَقَةَ التي يَكْتُبُ فيها.\n\n﴿ٱلسِّجِلِّ﴾: الصَّحِيفَةِ، الورقةِ التي يُكتبُ فيها.\n\n﴿لِلۡكُتُبِ﴾: هي ما دُوِّن في الصَّحيفة وكُتِب فيها.\n\n﴿كَمَا بَدَأۡنَآ أَوَّلَ خَلۡقࣲ نُّعِيدُهُۥ﴾: أي: نُعيدُ الخَلْقَ حُفاةً عُراةً غُرْلًا يومَ القيامةِ، كما بَدَأْناهم أوَّلَ مرَّةٍ في بُطُونِ أمَّهاتِهم."],[105,105,"﴿ٱلزَّبُورِ﴾: كِتابِ داودَ عليه الصلاةُ والسلامُ، أو الكُتُبِ المنزَّلَةِ.\n\n﴿مِنۢ بَعۡدِ ٱلذِّكۡرِ﴾: أي: مِن بَعْدِ الكِتابةِ في الذِّكْرِ، وهو التَّوراةُ، أو اللَّوحُ الَمحْفُوظُ."],[106,106,"﴿إِنَّ فِي هَـٰذَا﴾: أي: في هذا المَتْلُوِّ.\n\n﴿لَبَلَـٰغࣰا﴾: وُصُولًا إلى البُغْيةِ."],[108,108,"﴿مُّسۡلِمُونَ﴾: مُسْتَسْلِمُونَ مُنْقادُونَ للهِ تعالى."],[109,109,"﴿فَإِن تَوَلَّوۡاْ﴾: فَإنْ أعْرَضُوا عَنِ الإسْلامِ.\n\n﴿ءَاذَنتُكُمۡ﴾: أعْلَمْتُكُم مِن أنَّ بَعْضَكُم لِبَعْضٍ حَرْبٌ، لا صُلْحَ بَيْنَكُم ولا سِلْمَ.\n\n﴿عَلَىٰ سَوَآءࣲ﴾: فأنا وأنتم مُسْتَوُونَ في العِلْمِ.\n\n﴿وَإِنۡ أَدۡرِيٓ﴾: لا أدْرِي."],[111,111,"﴿لَعَلَّهُۥ فِتۡنَةࣱ لَّكُمۡ﴾: أي: لعلَّ الإمهالَ اختبارٌ لَكُمَ."],[112,112,"﴿قَـٰلَ رَبِّ ٱحۡكُم بِٱلۡحَقِّ﴾: أي: افصِلْ بَيْنِيَ وبْيَنَ قومِي بِما هُو الحقُّ عِنْدَكَ."]]);
QTF("gharib",22,[[1,1,"﴿إِنَّ زَلۡزَلَةَ ٱلسَّاعَةِ﴾: هي حَرَكَةُ الأرضِ مِن أسْفَلِها، واضْطِرابُها الذي يَحدُثُ عِنْدَ قِيامِ السّاعةِ."],[2,2,"﴿تَذۡهَلُ﴾: تَغْفُلُ وتَنْسى.\n\n﴿تَضَعُ﴾: تُسْقِطُ، وتُلْقِي جَنِينَها.\n\n﴿سُكَـٰرَىٰ﴾: أي: كالسُّكارى؛ مِن شِدَّةِ الخوفِ."],[3,3,"﴿يُجَـٰدِلُ﴾: يُخاصِمُ.\n\n﴿مَّرِيدࣲ﴾: مُتَمَرِّدٍ على اللهِ."],[4,4,"﴿كُتِبَ عَلَيۡهِ﴾: قُدِّرَ على الشَّيطانِ.\n\n﴿مَن تَوَلَّاهُ﴾: مَنِ اتَّخَذَه ولِيًّا وتَبِعَه.\n\n﴿وَيَهۡدِيهِ﴾: ويُوصِلُه ويَسُوقُه.\n\n﴿عَذَابِ ٱلسَّعِيرِ﴾: عذابِ جَهَنَّمَ الُموْقَدَةِ."],[5,5,"﴿رَيۡبࣲ﴾: شَكٍّ.\n\n﴿مِن نُّطۡفَةࣲ﴾: هي مَنِيُّ الرَّجُلِ يَقْذِفُه في رَحِم امْرَأتِه.\n\n﴿عَلَقَةࣲ﴾: الدَّم الأحْمَرِ الغَلِيظِ.\n\n﴿مُّضۡغَةࣲ﴾: قِطْعَةِ لَحْمٍ صَغِيرةٍ قَدْرَ ما يُمْضَغُ.\n\n﴿مُّخَلَّقَةࣲ﴾: ما وُلِد تامَّ الخَلْقِ.\n\n﴿غَيۡرِ مُخَلَّقَةࣲ﴾: ما تُسْقِطُه الرَّحِمُ قَبْلَ أن يَتِمَّ خَلْقُه.\n\n﴿وَنُقِرُّ﴾: نُثَبِّتُ ونُبْقِي.\n\n﴿إِلَىٰٓ أَرۡذَلِ ٱلۡعُمُرِ﴾: أخَسِّه، وهو الهَرمُ والخَرَفُ؛ حتى لا يَعْقِلَ.\n\n﴿هَامِدَةࣰ﴾: يابِسةً لا نَباتَ فيها.\n\n﴿ٱهۡتَزَّتۡ﴾: تَحرَّكَتْ بالنَّباتِ تَتَفَتَّحُ عَنْه.\n\n﴿وَرَبَتۡ﴾: زادَتْ وضاعفَتْ النَّباتَ بِنُزُولِ المطرِ.\n\n﴿مِن كُلِّ زَوۡجِۭ بَهِيجࣲ﴾: مِن كُلِّ صِنْفٍ حَسَنٍ ولونٍ مُسْتَحْسَنٍ."],[7,7,"﴿يَبۡعَثُ مَن فِي ٱلۡقُبُورِ﴾: أي: يَبْعَثُهم أحْياءً."],[8,8,"﴿يُجَـٰدِلُ﴾: يُخاصِمُ."],[9,9,"﴿ثَانِيَ عِطۡفِهِۦ﴾: لاويًا عُنُقَه في استكبارٍ عَنِ الحَقِّ.\n\n﴿خِزۡيࣱ﴾: ذُلٌّ وهَوانٌ."],[11,11,"﴿عَلَىٰ حَرۡفࣲ﴾: على ضَعْفٍ وشَكٍّ.\n\n﴿فِتۡنَةٌ﴾: ابْتِلاءٌ وشِدَّةٌ.\n\n﴿ٱنقَلَبَ عَلَىٰ وَجۡهِهِۦ﴾: رَجَعَ عمّا كان عليه مِنَ الاسْتِقامَةِ.\n\n﴿ٱلۡخُسۡرَانُ ٱلۡمُبِينُ﴾: الخَسارةُ العَظِيمَةُ والصَّفْقَةُ الخاسِرةُ."],[13,13,"﴿ٱلۡمَوۡلَىٰ﴾: النَّصِيرُ.\n\n﴿ٱلۡعَشِيرُ﴾: الصّاحِبُ المُعاشِرُ."],[14,14,"﴿مِن تَحۡتِهَا﴾: أي: مِن تَحْتِ قُصُورِها."],[15,15,"﴿فَلۡيَمۡدُدۡ﴾: فليَشْدُدْ.\n\n﴿بِسَبَبٍ﴾: بحَبْلٍ.\n\n﴿إِلَى ٱلسَّمَآءِ﴾: أي: سَماءِ بيتِه، وهو سَقْفُه.\n\n﴿ثُمَّ لۡيَقۡطَعۡ﴾: أي: ذلك الحبلَ، لِيَخْنُقَ بِه نَفْسَه.\n\n﴿كَيۡدُهُۥ﴾: مَكْرُه وحِيلَتُه.\n\n﴿مَا يَغِيظُ﴾: ما يَجِدُ في نَفْسِه مِنَ الغَيظِ والغَضَبِ."],[16,16,"﴿بَيِّنَـٰتࣲ﴾: واضحاتٍ."],[17,17,"﴿ٱلَّذِينَ هَادُواْ﴾: اليهُودَ.\n\n﴿ٱلصَّـٰبِـِٔينَ﴾: هم قَومٌ باقُونَ على فِطْرَتِهم، ولا دِينَ مقرَّرَ لهم يَتَّبِعونه.\n\n﴿وَٱلۡمَجُوسَ﴾: هم عَبَدَةُ النّارِ.\n\n﴿يَفۡصِلُ بَيۡنَهُمۡ﴾: يَقْضِي بَيْنَهم.\n\n﴿شَهِيدٌ﴾: رَقِيبٌ يُحصِي أعمالَ خَلْقِه كلَّها."],[18,18,"﴿أَلَمۡ تَرَ﴾: ألم تَعلَمْ.\n\n﴿يَسۡجُدُ لَهُۥ﴾: يَنْقادُ له ويَخْضَعُ.\n\n﴿حَقَّ عَلَيۡهِ﴾: وجَبَ عليه."],[19,19,"﴿خَصۡمَانِ﴾: فريقانِ: وهم المؤمِنُونَ والكُفّارُ.\n\n﴿ٱخۡتَصَمُواْ﴾: اخْتَلَفُوا.\n\n﴿فِي رَبِّهِمۡ﴾: في دِينِ ربِّهم.\n\n﴿قُطِّعَتۡ لَهُمۡ﴾: جُعِلَتْ لَهم.\n\n﴿ٱلۡحَمِيمُ﴾: الماءُ البالغُ نِهايةَ الحرارةِ."],[20,20,"﴿يُصۡهَرُ بِهِۦ﴾: يُذابُ به."],[21,21,"﴿مَّقَـٰمِعُ﴾: مَطارِقُ."],[22,22,"﴿مِنۡ غَمٍّ﴾: مِنَ أجْلِ ما نالَهُم مِنَ الغَمِّ والكَرْبِ."],[23,23,"﴿يُحَلَّوۡنَ فِيهَا﴾: يُلْبَسُونَ في الجنَّةِ الحُليَّ.\n\n﴿أَسَاوِرَ﴾: مفردُه سِوارٌ: وهو ما يُلبَسُ في اليد للتزيُّنِ، ويُحِيطُ بالمِعْصَمِ."],[24,24,"﴿وَهُدُوٓاْ﴾: هَداهُمُ اللهُ ووَفَّقَهم.\n\n﴿إِلَى ٱلطَّيِّبِ مِنَ ٱلۡقَوۡلِ﴾: إلى كَلِمةِ التَّوحِيدِ أنْ لا إلَهَ إلا اللهُ.\n\n﴿إِلَىٰ صِرَ ٰ⁠طِ ٱلۡحَمِيدِ﴾: الصِّراطِ المحمُودِ وهو الإسْلام."],[25,25,"﴿سَوَآءً﴾: مُسْتَوِيًا.\n\n﴿ٱلۡعَـٰكِفُ فِيهِ﴾: المقيمُ فيه المُلازمُ له.\n\n﴿وَٱلۡبَادِ﴾: القادمُ إليه مِن غَيْرِ أهْلِه.\n\n﴿بِإِلۡحَادِۭ﴾: بِعُدُولٍ عَنِ القَصْدِ."],[26,26,"﴿بَوَّأۡنَا لِإِبۡرَ ٰ⁠هِيمَ﴾: أي: بَيَّنّا له.\n\n﴿وَطَهِّرۡ بَيۡتِيَ﴾: أي: مِنَ الشِّركِ والكُفْرِ وسائِرِ النَّجاساتِ."],[27,27,"﴿وَأَذِّن فِي ٱلنَّاسِ﴾: أي: أعْلِمْهم بإعْلانٍ.\n\n﴿رِجَالࣰا﴾: جَمْعُ راجِلٍ، وهو مَن جاء يَمْشِي على رِجْلَيه.\n\n﴿وَعَلَىٰ كُلِّ ضَامِرࣲ﴾: أي: ورُكبانًا على كلِّ بعيرٍ مَهزولٍ أتْعَبَه طولُ السَّفَرِ.\n\n﴿فَجٍّ عَمِيقࣲ﴾: طَرِيقٍ بَعِيدٍ."],[28,28,"﴿أَيَّامࣲ مَّعۡلُومَـٰتٍ﴾: أيّامٍ مُعَيَّنةٍ هي: عاشرُ ذِي الحِجَّةِ وثلاثةُ أيّامٍ بَعْدَه.\n\n﴿عَلَىٰ مَا رَزَقَهُم مِّنۢ بَهِيمَةِ ٱلۡأَنۡعَـٰمِ﴾: أي: على ذَبْحِ ما رَزَقَهُم مِن بهِيَمَةِ الأنعامِ، وهي: الإبِلُ والَبَقرُ والغَنَمُ.\n\n﴿ٱلۡبَآئِسَ ٱلۡفَقِيرَ﴾: هو الفقيرُ الذي اشْتَدَّ فَقْرُه."],[29,29,"﴿ثُمَّ لۡيَقۡضُواْ تَفَثَهُمۡ﴾: ثم لِيُزِيلُوا وسَخَهم بعد خُرُوجِهِم مِن إحْرامِهِم.\n\n﴿وَلۡيُوفُواْ نُذُورَهُمۡ﴾: ولْيُوَفُّوا بما أوجَبُوه على أنْفُسِهم مِن أعْمالِ البِرِّ في الحجِّ وغيرِه.\n\n﴿بِٱلۡبَيۡتِ ٱلۡعَتِيقِ﴾: وهو الكَعْبةُ، وقد أعْتَقَها اللهُ مِن تَسَلُّطِ الجبّارينَ عَلَيها."],[30,30,"﴿حُرُمَـٰتِ ٱللَّهِ﴾: جَمْعُ حُرْمَةٍ، وهي ما وجَبَ القيامُ به، وحَرُمَ التَّفْرِيطُ فيه.\n\n﴿ٱلرِّجۡسَ مِنَ ٱلۡأَوۡثَـٰنِ﴾: أي: مِن عِبادَةِ الأوثانِ، فإنها رِجْسٌ.\n\n﴿ٱلزُّورِ﴾: الكذِبِ والافْتِراءِ على اللهِ."],[31,31,"﴿حُنَفَآءَ لِلَّهِ﴾: مُسْتَقِيمِينَ على الحقِّ.\n\n﴿خَرَّ﴾: سَقَطَ.\n\n﴿فَتَخۡطَفُهُ﴾: فَتَسْلُبُه وتَذْهبُ بِه.\n\n﴿تَهۡوِي بِهِ﴾: تَقْذِفُه وتَرْمِي بِه.\n\n﴿سَحِيقࣲ﴾: بَعِيدٍ."],[32,32,"﴿شَعَـٰٓئِرَ ٱللَّهِ﴾: هي معالمُ دِينِه، ومِنها شَعِيرةُ الحَجِّ."],[33,33,"﴿إِلَىٰٓ أَجَلࣲ مُّسَمࣰّى﴾: وهو وقتُ ذَبْحِها.\n\n﴿ثُمَّ مَحِلُّهَآ﴾: أي: حيثُ يَحِلُّ ذَبْحُها."],[34,34,"﴿مَنسَكࣰا﴾: ذَبْحًا يَذْبَحُونَه أو عِيدًا أو حَجًّا يَحُجُّونَه.\n\n﴿عَلَىٰ مَا رَزَقَهُم﴾: على ذَبْحِ ما رَزَقَهُم.\n\n﴿ٱلۡمُخۡبِتِينَ﴾: الخاشِعِينَ المخْلصِيِنَ."],[35,35,"﴿وَجِلَتۡ﴾: خافتْ."],[36,36,"﴿وَٱلۡبُدۡنَ﴾: وهي الإبِلُ والبَقَرُ مما يُجْزِئُ ذَبْحُه عَنْ سَبْعةٍ.\n\n﴿صَوَآفَّ﴾: أي: قائِماتٍ، بأن تُقامَ على قَوائِمِها الأرْبَعِ، ثم تُعْقَلَ إحْدى يَدَيها.\n\n﴿وَجَبَتۡ جُنُوبُهَا﴾: سقَطَتْ جُنوبُها على الأرضِ.\n\n﴿ٱلۡقَانِعَ﴾: الفقيرَ المُتَعَفِّفَ عَنِ السُّؤالِ.\n\n﴿وَٱلۡمُعۡتَرَّ﴾: الُمحتاجَ الَّذي يَسْأَلُ."],[37,37,"﴿ٱلتَّقۡوَىٰ مِنكُمۡ﴾: إخْلاصُكم لله وخَشْيَتُكُم مِنه."],[38,38,"﴿يُدَ ٰ⁠فِعُ﴾: يَدْفْعُ ويَرُدُّ.\n\n﴿خَوَّانࣲ﴾: كثيرِ الخِيانَةِ.\n\n﴿كَفُورٍ﴾: جَحُودٍ لِنِعَمِ اللهِ."],[39,39,"﴿أُذِنَ لِلَّذِينَ﴾: أي: شُرِعَ لهم القِتالُ."],[40,40,"﴿صَوَ ٰ⁠مِعُ﴾: مَعابدُ رُهْبانِ النَّصارى.\n\n﴿بِيَعࣱ﴾: كَنائِسُ النَّصارى.\n\n﴿صَلَوَ ٰ⁠تࣱ﴾: كنائِسُ اليهُودِ."],[44,44,"﴿وَأَصۡحَـٰبُ مَدۡيَنَ﴾: قومُ شُعَيبٍ عليه الصَّلاة والسَّلامُ.\n\n﴿فَأَمۡلَيۡتُ﴾: فأَمهَلْتُ.\n\n﴿ثُمَّ أَخَذۡتُهُمۡ﴾: أي: بالعقاب فَأَهْلَكْتُهم.\n\n﴿نَكِيرِ﴾: أي: إنْكارِي عَلَيهم."],[45,45,"﴿فَكَأَيِّن﴾: فَكَثِيرًا.\n\n﴿ظَالِمَةࣱ﴾: أي: أهلُها بالكُفْرِ والشِّركِ.\n\n﴿خَاوِيَةٌ عَلَىٰ عُرُوشِهَا﴾: ساقِطةٌ على سُقُوفِها.\n\n﴿وَبِئۡرࣲ مُّعَطَّلَةࣲ﴾: وبِئْرٍ مَهْجُورَةٍ بِمَوْتِ أهْلِها.\n\n﴿وَقَصۡرࣲ مَّشِيدٍ﴾: وقَصْرٍ مُجَصَّصٍ مَرْفُوعِ البُنْيانِ، خَرِبَ بِمَوتِ أهْلِه."],[47,47,"﴿مِّمَّا تَعُدُّونَ﴾: أي: مما تَحْسُبُونَ من سِنِي الدُّنيا."],[48,48,"﴿أَمۡلَيۡتُ لَهَا﴾: أمْهَلْتُها.\n\n﴿ظَالِمَةࣱ﴾: أي: أهلُها بالكفرِ والشِّركِ.\n\n﴿ثُمَّ أَخَذۡتُهَا﴾: أي: أهْلَكْتُها.\n\n﴿ٱلۡمَصِيرُ﴾: المرْجِعُ."],[50,50,"﴿وَرِزۡقࣱ كَرِيمࣱ﴾: ورِزْقٌ حَسَنٌ لا يَنْقَطِعُ، وهو الجنَّةُ."],[51,51,"﴿وَٱلَّذِينَ سَعَوۡاْ فِيٓ ءَايَـٰتِنَا﴾: والذين اجْتَهَدُوا في مُحارَبةِ القرآنِ وإبْطالِ آياتِه وحُجَجِه.\n\n﴿مُعَـٰجِزِينَ﴾: ظانِّينَ أنّهم يُعْجِزُونَنا ويَغْلِبُوننا.\n\n﴿أَصۡحَـٰبُ ٱلۡجَحِيمِ﴾: أهلُ النارِ الموقَدَةِ."],[52,52,"﴿تَمَنَّىٰٓ﴾: قَرَأَ ما نَزَلَ عَلَيهِ.\n\n﴿أَلۡقَى ٱلشَّيۡطَـٰنُ فِيٓ أُمۡنِيَّتِهِۦ﴾: أي: ألْقى في قِراءتِه الوَساوِسَ والشُّبُهاتِ.\n\n﴿فَيَنسَخُ ٱللَّهُ﴾: أي: فَيُزِيلُه.\n\n﴿مَا يُلۡقِي ٱلشَّيۡطَـٰنُ﴾: أي: ما يُلْقِيهِ مِن وساوِسَ وشُبُهاتٍ.\n\n﴿ثُمَّ يُحۡكِمُ ٱللَّهُ ءَايَـٰتِهِۦ﴾: ثُمَّ يُثَبِّتُ اللهُ آياتِه كما نَزَلَتْ ويَحفْظُها مِنَ التَّبْدِيل."],[53,53,"﴿فِتۡنَةࣰ﴾: ابْتلِاءً واخْتِبارًا.\n\n﴿مَّرَضࣱ﴾: شكٌّ ونِفاقٌ.\n\n﴿وَٱلۡقَاسِيَةِ قُلُوبُهُمۡ﴾: أي: غَلُظَتْ قُلُوبُهم عَن قَبُولِ الحَقِّ.\n\n﴿شِقَاقِۭ بَعِيدࣲ﴾: خِلافٍ بَعِيدٍ عَنِ الصَّوابِ."],[54,54,"﴿أَنَّهُ ٱلۡحَقُّ مِن رَّبِّكَ﴾: أنّ القرآنَ هو الحقُّ النازِلُ مِن عِنْدِ اللهِ عَلَيكَ.\n\n﴿فَتُخۡبِتَ لَهُۥ﴾: فَتَخْشَعَ لَهُ وتَخْضَعَ."],[55,55,"﴿فِي مِرۡيَةࣲ مِّنۡهُ﴾: في شَكٍّ مِن هَذا القُرآنِ.\n\n﴿بَغۡتَةً﴾: فَجْأةً.\n\n﴿يَوۡمٍ عَقِيمٍ﴾: هو يومُ القيامةِ الَّذي لا خيرَ فيه للكفارِ، ولا يومَ بَعْدَه."],[56,56,"﴿ٱلۡمُلۡكُ﴾: السُّلْطانُ القاهِرُ.\n\n﴿يَوۡمَئِذࣲ﴾: أي: يومَ القيامةِ."],[57,57,"﴿مُّهِينࣱ﴾: مُخْزٍ ومُذِلٌّ."],[58,58,"﴿رِزۡقًا حَسَنࣰا﴾: وهو الجنَّةُ."],[59,59,"﴿مُّدۡخَلࣰا﴾: مكانَ دخولٍ، وهو الجنَّةُ."],[60,60,"﴿ثُمَّ بُغِيَ عَلَيۡهِ﴾: ثُمَّ اعْتُدِيَ عليه بالظُّلْمِ."],[61,61,"﴿يُولِجُ﴾: يُدخِلُ."],[62,62,"﴿مَا يَدۡعُونَ مِن دُونِهِۦ﴾: ما يَعْبُدُه الُمشْرِكُون مِن دُونِ اللهِ مِنَ الأصْنامِ وغَيرِها.\n\n﴿ٱلۡعَلِيُّ﴾: أي: على خَلْقِه ذاتًا وقدْرًا وقَهْرًا."],[63,63,"﴿مَآءࣰ﴾: مَطَرًا."],[64,64,"﴿ٱلۡحَمِيدُ﴾: المحمودُ المُسْتَحِقُّ لِلْحمْدِ في كُلِّ حالٍ."],[65,65,"﴿سَخَّرَ﴾: ذَلَّلَ.\n\n﴿ٱلۡفُلۡكَ﴾: السُّفُنَ.\n\n﴿يُمۡسِكُ ٱلسَّمَآءَ﴾: يَحْفظُ السَّماءَ."],[66,66,"﴿لَكَفُورࣱ﴾: لَجَحُودٌ."],[67,67,"﴿مَنسَكًا﴾: شَرِيعةً خاصَّةً.\n\n﴿هُمۡ نَاسِكُوهُ﴾: هم عامِلُونَ به.\n\n﴿فَلَا يُنَـٰزِعُنَّكَ فِي ٱلۡأَمۡرِ﴾: فلا يَحِقُّ لَهُم أنْ يخاصِمُوكَ في شَرِيعَتِكَ.\n\n﴿هُدࣰى مُّسۡتَقِيمࣲ﴾: دِينٍ قَوِيمٍ لا اعْوِجاجَ فِيه."],[70,70,"﴿فِي كِتَـٰبٍ﴾: أي: في اللَّوحِ المحْفُوظِ."],[71,71,"﴿سُلۡطَـٰنࣰا﴾: حُجَّةً وبُرْهانًا.\n\n﴿لِلظَّـٰلِمِينَ﴾: للمُشْرِكِينَ."],[72,72,"﴿ٱلۡمُنكَرَ﴾: الأمرَ الذي يُنْكَرُ مِنَ العُبُوسِ والغَضَبِ والكَراهَةِ.\n\n﴿يَسۡطُونَ﴾: يَبْطِشُونَ.\n\n﴿بِشَرࣲّ مِّن ذَ ٰ⁠لِكُمُ﴾: بِشَرٍّ مِن غَيظِكُم على مَن يَتْلُو عليكُم آياتِ اللهِ.\n\n﴿وَبِئۡسَ ٱلۡمَصِيرُ﴾: ساءَ وقَبُحَ المكانُ الذي يَرجِعُونَ إليه."],[73,73,"﴿فَٱسۡتَمِعُواْ لَهُۥٓ﴾: أي: سَماعَ تَدَبُّرٍ.\n\n﴿تَدۡعُونَ﴾: تَعْبُدُونَ.\n\n﴿ذُبَابࣰا﴾: ذُبابةً واحِدةً مَعَ صِغَرِها.\n\n﴿وَإِن يَسۡلُبۡهُمُ﴾: أي: وإن يَأْخُذِ الذُّبابُ شيئًا مِن هَذهِ المعْبُوداتِ.\n\n﴿لَّا يَسۡتَنقِذُوهُ مِنۡهُ﴾: أي: لا يَقْدِرُوا -لِعَجْزِهِم- على اسْتِرْدادِ ما أُخِذَ مِنهم.\n\n﴿ٱلطَّالِبُ﴾: هو المَعبُودُ مِن دُونِ اللهِ.\n\n﴿ٱلۡمَطۡلُوبُ﴾: هو الذُّبابُ."],[74,74,"﴿مَا قَدَرُواْ ٱللَّهَ حَقَّ قَدۡرِهِۦٓ﴾: ما عَظَّمَ المشْرِكُونَ اللهَ تَعالى حقَّ تَعْظِيمِهِ."],[75,75,"﴿يَصۡطَفِي﴾: يَخْتارُ."],[76,76,"﴿مَا بَيۡنَ أَيۡدِيهِمۡ﴾: أي: أعْمالَهم التي عَمِلُوها.\n\n﴿مَا خَلۡفَهُمۡ﴾: أي: أعْمالَهم التي سَيَعْمَلُونَها."],[78,78,"﴿وَجَـٰهِدُواْ فِي ٱللَّهِ﴾: أي: في سَبِيِلهِ لإعْلاءِ كَلِمَتِهِ.\n\n﴿هُوَ ٱجۡتَبَىٰكُمۡ﴾: اصْطَفاكُم اللهُ لِحَمْلِ دِينِه.\n\n﴿مِنۡ حَرَجࣲ﴾: مِن ضِيقٍ ومَشَقَّةٍ بتكْلِيفٍ يَشُقُّ عَلَيكُم.\n\n﴿مِن قَبۡلُ﴾: أي: في الكُتُبِ المُنَزَّلةِ السّابِقَةِ.\n\n﴿فِي هَـٰذَا﴾: أي: في هَذا القرآنِ.\n\n﴿شُهَدَآءَ عَلَى ٱلنَّاسِ﴾: أي: على الأممِ السّابَقَةِ أنّ رُسُلَهم قد بَلَّغَتْهم رِسالاتِ ربِّهم.\n\n﴿وَٱعۡتَصِمُواْ بِٱللَّهِ﴾: أي: اجْعَلُوه عِصْمةً لكم مما تَحْذَرُونَ، والتَجِئُوا إليه في جميعِ أُمُورِكُم.\n\n﴿هُوَ مَوۡلَىٰكُمۡ﴾: هو ناصِرُكُم، ومُتَوَلِّي أمورِكُم."]]);
QTF("gharib",23,[[1,1,"﴿أَفۡلَحَ﴾: فازَ بِالنَّجاةِ مِنَ النّارِ."],[2,2,"﴿خَـٰشِعُونَ﴾: خاضِعُونَ بِقُلوبِهِم وجَوارِحِهِم."],[3,3,"﴿عَنِ ٱللَّغۡوِ مُعۡرِضُونَ﴾: أي: تارِكُونَ لِكُلِّ ما لا خَيرَ فِيه مِنَ العَبَثِ."],[5,5,"﴿حَـٰفِظُونَ﴾: أي: ممّا حَرَّم الله مِنَ الزِّنى وسائرِ الفواحِشِ."],[7,7,"﴿ٱبۡتَغَىٰ وَرَآءَ ذَ ٰ⁠لِكَ﴾: طَلَبَ التَّمَتُّعَ بِغَيرِ ما أحَلَّه اللهُ.\n\n﴿ٱلۡعَادُونَ﴾: المُجاوِزُونَ حُدَودَ اللهِ."],[8,8,"﴿رَ ٰ⁠عُونَ﴾: حافِظُونَ."],[11,11,"﴿ٱلۡفِرۡدَوۡسَ﴾: أعْلى مَنازِلِ الجنَّةِ وأَوسَطَها، وهو أفْضَلُها."],[12,12,"﴿ٱلۡإِنسَـٰنَ﴾: آدَمَ.\n\n﴿مِن سُلَـٰلَةࣲ مِّن طِينࣲ﴾: أي: مِن طِينٍ مأخُوذٍ مِن جَمِيعِ الأرضِ."],[13,13,"﴿نُطۡفَةࣰ﴾: هي مَنِيُّ الرَّجُلِ يَقْذِفُه في رَحِمِ امْرَأَتِه.\n\n﴿قَرَارࣲ مَّكِينࣲ﴾: مُسْتَقِرٍّ مُتمَكِّنٍ، وهو رَحِمُ المرْأَةِ."],[14,14,"﴿عَلَقَةࣰ﴾: دَمًا أحْمرَ غَلِيظًا.\n\n﴿مُضۡغَةࣰ﴾: قِطْعَةَ لَحْمِ قَدْرَ ما يُمَضَغُ.\n\n﴿فَكَسَوۡنَا ٱلۡعِظَـٰمَ لَحۡمࣰا﴾: أي: أنْبَتْنا على كُلِّ عَظْمٍ لَحْمًا مُناسِبًا.\n\n﴿خَلۡقًا ءَاخَرَ﴾: مُباينًا لِلْأَوَّلِ، وذلِكَ بِنَفْخِ الرُّوحِ فيه بَعْدَ أنْ كانَ جمادًا."],[16,16,"﴿تُبۡعَثُونَ﴾: تُحْيَوْن مِن قُبُورِكُم؛ لَلْحِسابِ."],[17,17,"﴿سَبۡعَ طَرَآئِقَ﴾: سَبْعَ سَمَواتٍ جُعِلَ بعضُها فَوْقَ بَعْضٍ."],[18,18,"﴿بِقَدَرࣲ﴾: أي: بِمِقْدارِ الحاجَةِ.\n\n﴿فَأَسۡكَنَّـٰهُ فِي ٱلۡأَرۡضِ﴾: أي: جَعَلْناه مُسْتَقِرًّا فِيها.\n\n﴿عَلَىٰ ذَهَابِۭ بِهِۦ﴾: أي: على إذْهابِ هذا الماءِ."],[19,19,"﴿جَنَّـٰتࣲ﴾: بساتِينَ."],[20,20,"﴿وَشَجَرَةࣰ﴾: هي شَجَرَةُ الزَّيتُونِ.\n\n﴿طُورِ﴾: هو جَبَلٌ ب «سَيْناءَ».\n\n﴿بِٱلدُّهۡنِ﴾: أي: مُلْتَبِسًا ثَمَرُها بالزَّيتِ.\n\n﴿وَصِبۡغࣲ﴾: إدامٍ يُغْمَسُ فيه الخُبْزُ."],[21,21,"﴿لَعِبۡرَةࣰ﴾: لَعِظَةً وآيةً على القُدْرَةِ والرَّحْمَةِ."],[22,22,"﴿وَعَلَيۡهَا﴾: أي: وعلى الإبِلِ من الأنعامِ.\n\n﴿ٱلۡفُلۡكِ﴾: السُّفُنِ."],[24,24,"﴿ٱلۡمَلَؤُاْ﴾: أشرافُ القومِ وسادَتُهم.\n\n﴿أَن يَتَفَضَّلَ﴾: أن يتَرَأَّسَ ويَشْرُفَ عليكم."],[25,25,"﴿جِنَّةࣱ﴾: أي: جُنُونٌ أو مَسٌّ من الجِنِّ.\n\n﴿فَتَرَبَّصُواْ﴾: فانْتَظِرُوا.\n\n﴿حِينࣲ﴾: أي: وقتٍ مّا."],[27,27,"﴿بِأَعۡيُنِنَا﴾: بِمَرْأىً مِنّا.\n\n﴿أَمۡرُنَا﴾: أي: بِعَذابِهم بالطُّوفانِ.\n\n﴿وَفَارَ﴾: نَبَعَ الماءُ وخَرَجَ بِقُوَّةٍ.\n\n﴿ٱلتَّنُّورُ﴾: هو المكانُ الذي يُخْبزُ فِيه.\n\n﴿فَٱسۡلُكۡ﴾: أدْخِلْ.\n\n﴿مِن كُلࣲّ﴾: أي: من كُلِّ الأَحْياءِ.\n\n﴿زَوۡجَيۡنِ﴾: ذَكَرًا وأنْثى.\n\n﴿سَبَقَ عَلَيۡهِ ٱلۡقَوۡلُ﴾: أي: سَبَق القضاءُ بِهلاكِه؛ لِكُفْرِه كزَوْجَتِكَ وابْنِكَ."],[28,28,"﴿ٱسۡتَوَيۡتَ﴾: اعْتَدَلَتْ، أي: بَعْدَ رُكُوبِكَ في السَّفِينةِ.\n\n﴿ٱلۡفُلۡكِ﴾: السَّفِينةِ."],[29,29,"﴿مُنزَلࣰا﴾: إنْزِالًا أومَكانَ إنْزالٍ."],[30,30,"﴿لَـَٔايَـٰتࣲ﴾: عِبَرًا وحُجَجًا يُسْتَدَلُّ بها على سُنَنِ اللهِ في أمْثالِ هؤلاءِ مِنَ الكَفَرةِ والمُشْرِكِينَ.\n\n﴿وَإِن كُنَّا﴾: وإننا كُنّا.\n\n﴿لَمُبۡتَلِينَ﴾: لمُخْتَبِريِنَ الناسَ بهذه الآياتِ."],[31,31,"﴿ثُمَّ أَنشَأۡنَا﴾: أحْدَثْنا وخَلَقْنا.\n\n﴿قَرۡنًا ءَاخَرِينَ﴾: جِيلًا آخَرَ: هم قَومُ عادٍ أو قومُ ثمُودَ."],[32,32,"﴿رَسُولࣰا مِّنۡهُمۡ﴾: هو هودٌ أو صالحٌ عليهما الصَّلاةُ والسَّلامُ."],[33,33,"﴿ٱلۡمَلَأُ﴾: الأشْرافُ.\n\n﴿بِلِقَآءِ ٱلۡـَٔاخِرَةِ﴾: أي: بِلقاءِ اللهِ يومَ القِيامةِ.\n\n﴿وَأَتۡرَفۡنَـٰهُمۡ﴾: جَعَلْناهُم في تَرَفٍ وسَعَةٍ حتّى بَطِرُوا."],[34,34,"﴿لَّخَـٰسِرُونَ﴾: أي: بِتَرْكِكُم آلِهَتَكم واتِّباعِكُم الرسولَ عليه السلام."],[35,35,"﴿مُّخۡرَجُونَ﴾: أي: من قُبُورِكُم أحياءً."],[36,36,"﴿هَيۡهَاتَ﴾: بَعُدَ، أي: ما تُوعدُونَ به أيُّها القومُ.\n\n﴿لِمَا تُوعَدُونَ﴾: هو البعثُ بَعْدَ الموتِ."],[37,37,"﴿وَمَا نَحۡنُ بِمَبۡعُوثِينَ﴾: أي: بَعْدَ المماتِ."],[38,38,"﴿إِنۡ هُوَ إِلَّا رَجُلٌ﴾: هو هُودٌ أو صالحٌ عليهما الصَّلاةُ والسَّلامُ.\n\n﴿ٱفۡتَرَىٰ﴾: اختَلَقَ.\n\n﴿بِمُؤۡمِنِينَ﴾: بِمُصَدِّقِينَ."],[40,40,"﴿عَمَّا قَلِيلࣲ﴾: أي: بَعْدَ زَمَنٍ قَريبٍ."],[41,41,"﴿ٱلصَّيۡحَةُ﴾: صَوْتٌ شَدِيدٌ مُهْلِكٌ.\n\n﴿بِٱلۡحَقِّ﴾: أي: يَسْتَحِقُّونَ ذَلك العذابَ؛ لِكُفْرِهم وطُغْيانِهم.\n\n﴿فَجَعَلۡنَـٰهُمۡ غُثَآءࣰ﴾: أي: أمْواتًا كَغُثاءِ السَّيلِ الذي يَطْفُو على الماءِ.\n\n﴿فَبُعۡدࣰا﴾: أي: عَن رَّحْمَةِ اللهِ."],[42,42,"﴿أَنشَأۡنَا﴾: خلَقْنا وأوْجَدْنا.\n\n﴿قُرُونًا ءَاخَرِينَ﴾: أقْوامًا آخَرِينَ مِثْلَ قَوْمِ لُوطٍ وشُعَيبٍ وأيُّوبَ ويونسَ عليهمُ الصَّلاةُ والسَّلامُ."],[43,43,"﴿مَا تَسۡبِقُ﴾: ما تَتَقَدَّمُ.\n\n﴿أَجَلَهَا﴾: الوَقْتَ المَحْدُودَ لهلاكِها.\n\n﴿وَمَا يَسۡتَـٔۡخِرُونَ﴾: ولا يتأخَّرُونَ."],[44,44,"﴿تَتۡرَا﴾: يَتْبَعُ بعضُهم بَعْضًا.\n\n﴿أَحَادِيثَ﴾: أخْبارًا يَتَحَدَّثُ الناسُ بها للعِبْرَةِ وغيرِها.\n\n﴿فَبُعۡدࣰا﴾: أي: بُعْدًا عَن رَّحْمَةِ اللهِ."],[45,45,"﴿بِـَٔايَـٰتِنَا﴾: أي: بالمُعْجِزاتِ التِّسْعِ، وهي: العَصا واليدُ البيضاءُ والسِّنونَ المُجْدِبةُ ونَقْصُ الثَّمَراتِ، والطُّوفانُ والجَرادُ والقُمَّلُ والضَّفادِعُ والدَّمُ\n\n﴿وَسُلۡطَـٰنࣲ مُّبِينٍ﴾: بُرْهانٍ مُظْهِرٍ لِلْحَقِّ."],[46,46,"﴿وَمَلَإِيْهِۦ﴾: وأشْرافِ قَومِه.\n\n﴿عَالِينَ﴾: مُسْتَعْلِينَ على النّاسِ بالبَغْيِ والظُّلْمِ."],[47,47,"﴿لَنَا عَـٰبِدُونَ﴾: أي: مُنْقادُون اْنِقيادَ العَبِيدِ."],[50,50,"﴿ءَايَةࣰ﴾: علامةً على عَظِيمِ قُدْرَتِنا.\n\n﴿وَءَاوَيۡنَـٰهُمَآ﴾: وجَعَلْنا لَهُما مأْوىً ومْنزِلًا.\n\n﴿رَبۡوَةࣲ﴾: بُقْعَةٍ مُرْتَفِعَةٍ.\n\n﴿ذَاتِ قَرَارࣲ﴾: أي: فيها أسْبابُ الاسْتِقْرارِ من الزَّرِعِ والثِّمارِ.\n\n﴿وَمَعِينࣲ﴾: وماءٍ جارٍ تَسْتَمْتِعُ بِرُؤيَتِه العُيونُ."],[51,51,"﴿مِنَ ٱلطَّيِّبَـٰتِ﴾: مايُسْتَطابُ مِنَ الحَلالِ."],[52,52,"﴿أُمَّتُكُمۡ أُمَّةࣰ﴾: دِينُكُم دِينٌ واحِدٌ وهو دَعْوةُ جَمِيعِ الأنْبِياءِ إلى عِبادَةِ اللهِ وحْدَه لا شَرِيكَ لَه."],[53,53,"﴿فَتَقَطَّعُوٓاْ أَمۡرَهُم بَيۡنَهُمۡ﴾: تَفرَّقَ الأتْباعُ في أمْرِ دِينِهِم.\n\n﴿زُبُرࣰا﴾: قِطَعًا وفِرَقًا.\n\n﴿فَرِحُونَ﴾: مَسْرُورُونَ."],[54,54,"﴿فَذَرۡهُمۡ﴾: فاتْرُكْهُم.\n\n﴿فِي غَمۡرَتِهِمۡ﴾: في غَفْلَتِهِم التي غَمَرَتْهُم وغَطَّتْهم مِن كُلِّ الجِهاتِ.\n\n﴿حَتَّىٰ حِينٍ﴾: إلى وقْتِ نُزُولِ العَذاب بِهِم."],[55,55,"﴿أَيَحۡسَبُونَ﴾: أيظُنُّونَ.\n\n﴿نُمِدُّهُم﴾: نُعْطِيهِم اسْتِدْراجًا"],[57,57,"﴿مُّشۡفِقُونَ﴾: وجِلُونَ وحَذِرُونَ."],[60,60,"﴿يُؤۡتُونَ مَآ ءَاتَواْ﴾: يُعْطُونَ ما أعْطَوا مِنَ الصَّدقاتِ.\n\n﴿وَجِلَةٌ﴾: خائِفَةٌ."],[63,63,"﴿فِي غَمۡرَةࣲ﴾: في غَفْلَةٍ.\n\n﴿مِّن دُونِ ذَ ٰ⁠لِكَ﴾: مِن دُونِ الشِّركِ."],[64,64,"﴿مُتۡرَفِيهِم﴾: مُنَعَّمِيهِم الذين أبْطَرَتْهُم النِّعَمُ.\n\n﴿يَجۡـَٔرُونَ﴾: يَصْرُخُونَ مُسْتَغِيثِينَ."],[65,65,"﴿لَا تَجۡـَٔرُواْ﴾: لا تَصْرُخُوا."],[66,66,"﴿تَنكِصُونَ﴾: تَرْجِعُونَ وراءَكُم مُعْرِضِينَ عَنْ سَماعِ الآياتِ."],[67,67,"﴿بِهِۦ سَـٰمِرࣰا﴾: أي: مُتَسامِرِينَ باللَّيلِ حَولَ الكَعْبَةِ.\n\n﴿تَهۡجُرُونَ﴾: تَتَكَلَّمُونَ بِساقِطِ القولِ."],[68,68,"﴿أَفَلَمۡ يَدَّبَّرُواْ ٱلۡقَوۡلَ﴾: أفلم يَتَفَكَّرُوا في القرآنِ."],[70,70,"﴿جِنَّةُۢ﴾: جُنُونٌ."],[71,71,"﴿بِذِكۡرِهِمۡ﴾: بالقرآنِ الذي فِيهِ عِزُّهُم وشَرفُهُم."],[72,72,"﴿خَرۡجࣰا﴾: أجْرًا مِنَ المالِ.\n\n﴿فَخَرَاجُ رَبِّكَ﴾: ثوابُ اللهِ وعَطاؤُه."],[73,73,"﴿صِرَ ٰ⁠طࣲ مُّسۡتَقِيمࣲ﴾: دِينٍ قَوِيمٍ وهو الإسْلامُ."],[74,74,"﴿لَنَـٰكِبُونَ﴾: لمائِلُونَ ومُنْحَرِفُونَ عَنْه."],[75,75,"﴿مِّن ضُرࣲّ﴾: مِن جَدْبٍ وجُوعٍ.\n\n﴿لَّلَجُّواْ﴾: لَتَمادَوا واسْتَمَرُّوا.\n\n﴿فِي طُغۡيَـٰنِهِمۡ﴾: في كُفْرِهِم وعِنادِهِم.\n\n﴿يَعۡمَهُونَ﴾: يَتَرَدَّدُونَ."],[76,76,"﴿فَمَا ٱسۡتَكَانُواْ﴾: فما خَضَعُوا وما أظْهَرُوا المَسْكَنَةَ.\n\n﴿وَمَا يَتَضَرَّعُونَ﴾: وما يَتَذَلَّلُونَ للهِ تعالى بالدُّعاءِ."],[77,77,"﴿مُبۡلِسُونَ﴾: آيِسُونَ مِن كُلِّ خَيرٍ، مُتَحَيِّرُونَ."],[79,79,"﴿ذَرَأَكُمۡ﴾: خَلَقَكُم وبَثَّكُم."],[80,80,"﴿ٱخۡتِلَـٰفُ ٱلَّيۡلِ وَٱلنَّهَارِ﴾: تَعاقُبُهُما وتَفاوُتُهُما."],[81,81,"﴿ٱلۡأَوَّلُونَ﴾: آباؤهُم وأَسْلافُهُم المُتَقَدِّمون."],[82,82,"﴿لَمَبۡعُوثُونَ﴾: أي: من قُبُورِنا أحْياءً."],[83,83,"﴿أَسَـٰطِيرُ ٱلۡأَوَّلِينَ﴾: الأكاذِيبُ الَّتي كَتَبَها المُتَقَدِّمُونَ."],[85,85,"﴿أَفَلَا تَذَكَّرُونَ﴾: أنَّ اللهَ قادِرٌ على البَعْثِ والنُّشُورِ."],[87,87,"﴿أَفَلَا تَتَّقُونَ﴾: أفلا تَخافُونَ عِقابَ اللهِ على كُفْرِكُم وشِرْكِكُم؟"],[88,88,"﴿مَلَكُوتُ كُلِّ شَيۡءࣲ﴾: مالِكُ كُلِّ شَيءٍ والمُتَصَرِّفُ فِيه.\n\n﴿يُجِيرُ﴾: يُغِيثُ ويَحْمِي غيرَه.\n\n﴿وَلَا يُجَارُ عَلَيۡهِ﴾: ولا يُغِيثُ ولا يَحْمِي أحَدٌ منه أحَدًا."],[89,89,"﴿فَأَنَّىٰ تُسۡحَرُونَ﴾: فَكَيفَ تُصْرَفَونَ عَنِ الحقِّ؟"],[90,90,"﴿لَكَـٰذِبُونَ﴾: أي: في شِرْكِهِم وإنْكارِهِم البَعْثَ."],[91,91,"﴿لَّذَهَبَ كُلُّ إِلَـٰهِۭ بِمَا خَلَقَ﴾: أي: لانْفَردَ كُلُّ مَعْبُودٍ بِمَخْلُوقاتِه.\n\n﴿وَلَعَلَا﴾: ولَغَلَبَ.\n\n﴿سُبۡحَـٰنَ ٱللَّهِ﴾: تَنَزَّه وتَقَدَّسَ.\n\n﴿عَمَّا يَصِفُونَ﴾: أي: من كَذِبِهِم وبُهْتانِهِم بِأَنَّ له شَرِيكًا أوْ ولَدًَا."],[92,92,"﴿وَٱلشَّهَـٰدَةِ﴾: وما يُشاهَدُ."],[93,93,"﴿مَا يُوعَدُونَ﴾: أي: مِنَ العَذابِ."],[97,97,"﴿هَمَزَ ٰ⁠تِ﴾: نَزَغاتٍ ووَساوِسَ."],[98,98,"﴿أَن يَحۡضُرُونِ﴾: أي: مِن حُضُورِ الشَّياطِينِ في أُمُورِي."],[99,99,"﴿ٱرۡجِعُونِ﴾: رُدُّوني إلى الدُّنيا."],[100,100,"﴿هُوَ قَآئِلُهَا﴾: يَقُولُها باللِّسانِ ولا يَعْمَلُ بِمُقْتَضاها.\n\n﴿بَرۡزَخٌ﴾: هو الحاجِزُ الَّذي بين الموتِ والبَعْثِ."],[101,101,"﴿ٱلصُّورِ﴾: القَرْنِ الذي يُنفَخُ فيه للَبعْثِ.\n\n﴿فَلَآ أَنسَابَ بَيۡنَهُمۡ﴾: أي: فلا تَنْفَعُهم أنْسابُهم، ولا يَتَفاخَرُونَ بها مِن هَوْلِ الموْقِفِ.\n\n﴿وَلَا يَتَسَآءَلُونَ﴾: أي: لا يَسْأَلُ أحَدٌ أحَدًا."],[102,102,"﴿ثَقُلَتۡ مَوَ ٰ⁠زِينُهُۥ﴾: أي: بِكَثْرةِ حسناتِهِ.\n\n﴿ٱلۡمُفۡلِحُونَ﴾: الفائِزُونَ بالجنَّةِ والنَّجاةِ مِنَ النّارِ."],[103,103,"﴿خَفَّتۡ مَوَ ٰ⁠زِينُهُۥ﴾: أي: قَلَّتْ أعْمالُه الصّالِحَةُ.\n\n﴿خَسِرُوٓاْ أَنفُسَهُمۡ﴾: أي: ضَيَّعُوها."],[104,104,"﴿تَلۡفَحُ﴾: تَحْرِقُ.\n\n﴿كَـٰلِحُونَ﴾: عابِسُونَ تَقَلَّصَتْ شِفاهُهُم عن أسْنانِهِم؛ مِن إحْراقِ النّارِ وُجُوهَهُم."],[105,105,"﴿ءَايَـٰتِي﴾: أي: آياتُ القُرآن."],[106,106,"﴿شِقۡوَتُنَا﴾: هي المَلَذّاتُ والشَّهَواتُ التي كُتِبَتْ عَلَينا في سابِقِ عِلْمِكَ وساقَتْنا إلى الشِّقاءِ."],[107,107,"﴿فَإِنۡ عُدۡنَا﴾: فَإن رَّجَعْنا إلى الضَّلالِ."],[108,108,"﴿ٱخۡسَـُٔواْ فِيهَا﴾: امْكُثُوا في النّارِ أذِلّاءَ صاغِرِينَ."],[110,110,"﴿سِخۡرِيًّا﴾: مَهْزُوءًا بهم."],[113,113,"﴿ٱلۡعَآدِّينَ﴾: أي: المُتَمَكِّنِينَ مِن مَّعْرِفَةِ العَدَدِ مِنَ الملائِكَةِ أو مِنَ النّاسِ."],[115,115,"﴿عَبَثࣰا﴾: لَعِبًا مِن غَيرِ فائِدةٍ ولاحِكْمَةٍ."],[116,116,"﴿ٱلۡمَلِكُ﴾: الَّذي يَحِقُّ لَهُ المُلْكُ على الإطْلاقِ\n\n﴿ٱلۡحَقُّ﴾: الثّابِتُ الَّذي لا يَزُولُ.\n\n﴿ٱلۡعَرۡشِ﴾: هو سَرِيرُ المُلْكِ الَّذي اسْتَوى عليه الرَّحمنُ، وتَحْمِلُه الملائِكةُ، وهو أعْظَمُ المَخْلُوقاتِ، وهو سَقْفُ الجنَّةِ."]]);
QTF("gharib",24,[[1,1,"﴿وَفَرَضۡنَـٰهَا﴾: أوْجَبْنا أحْكامَ هذه السُّورةِ عَلَيكُم.\n\n﴿ءَايَـٰتِۭ بَيِّنَـٰتࣲ﴾: دَلالاتٍ واضِحاتٍ."],[2,2,"﴿فَٱجۡلِدُواْ﴾: فاضربُوا بالسَّوطِ.\n\n﴿رَأۡفَةࣱ﴾: رَحْمَةٌ ورِقَّةٌ.\n\n﴿وَلۡيَشۡهَدۡ﴾: ولْيَحْضُرْ."],[3,3,"﴿وَحُرِّمَ ذَ ٰ⁠لِكَ﴾: أي: نكاحُ الزِّانِيةِ حتى تَتَوْبَ أوْ حُرِّم الزِّنى نَفْسُه."],[4,4,"﴿يَرۡمُونَ﴾: يَقْذِفُونَ بالزِّنى.\n\n﴿ٱلۡمُحۡصَنَـٰتِ﴾: النِّساءَ الحرائِرَ العَفِيفاتِ، وكذلك الرِّجالُ.\n\n﴿ٱلۡفَـٰسِقُونَ﴾: الخارِجُونَ عَن طاعَةِ اللهِ."],[6,6,"﴿يَرۡمُونَ أَزۡوَ ٰ⁠جَهُمۡ﴾: يَقْذِفُونَ زَوْجاتِهم بالزِّنى.\n\n﴿لَمِنَ ٱلصَّـٰدِقِينَ﴾: أي: في قَذْفِه زَوْجَتَه بالزِّنى."],[7,7,"﴿وَٱلۡخَـٰمِسَةُ﴾: أي: الشَّهادَةُ الخامِسَةُ.\n\n﴿مِنَ ٱلۡكَـٰذِبِينَ﴾: أي: في قَذْفِه زَوْجتَه بالزِّنى."],[8,8,"﴿وَيَدۡرَؤُاْ عَنۡهَا﴾: ويَدْفَعُ عَنِ الزَّوجَةِ المَقْذُوفَةِ."],[10,10,"﴿تَوَّابٌ﴾: كثِيرُ القَبُولِ لِتَوْبَةِ مَن تابَ إليهِ مِن عِبادِهِ.\n\n﴿حَكِيمٌ﴾: أي: في شَرائِعِه وأَحْكامِه، فلم يُنْزِلْ بالكاذِبِ مِن المتَلاعِنَينِ ما دَعا به على نَفْسِه."],[11,11,"﴿بِٱلۡإِفۡكِ﴾: أقْبحِ الكَذِبِ وأفْحَشِه، وهو اتِّهامُ أمِّ المؤمنينَ عائِشَةَ رضي اللهُ عَنَها بالفاحِشةِ.\n\n﴿عُصۡبَةࣱ مِّنكُمۡ﴾: جَماعةٌ مُنْتَسِبُونَ إليكُم.\n\n﴿مَّا ٱكۡتَسَبَ﴾: جَزاءُ ما ارْتَكَبَ.\n\n﴿تَوَلَّىٰ كِبۡرَهُۥ﴾: تَحَمَّلَ مُعْظَمَ الإفْكِ، وهو عبدُ اللهِ بنُ أُبيِّ بنِ سَلُولٍ كبيرُ المنافِقِيِنَ."],[12,12,"﴿لَّوۡلَآ﴾: هَلّا.\n\n﴿إِفۡكࣱ مُّبِينࣱ﴾: بُهْتانٌ واضِحٌ."],[14,14,"﴿لَمَسَّكُمۡ﴾: لَأصابَكُم.\n\n﴿فِي مَآ أَفَضۡتُمۡ فِيهِ﴾: بِسَبَبِ ماخُضْتُم فيه مِن حَدِيثِ الإفْكِ."],[15,15,"﴿إِذۡ تَلَقَّوۡنَهُۥ﴾: حِينَ تَتَلَقَّفُونَ حَدِيثَ الإفْكِ وتَتَناقَلُونَه.\n\n﴿وَتَحۡسَبُونَهُۥ هَيِّنࣰا﴾: وتَظُنُّونَ تَلَقِّيَ الإفْكِ شَيئًا سَهْلًا لا يَلْحَقُكُم فيه إثْمٌ."],[16,16,"﴿مَّا يَكُونُ لَنَآ﴾: ما يَحِلُّ لَنا ولا يَنْبَغِي.\n\n﴿سُبۡحَـٰنَكَ﴾: تَنْزِيهًا لكَ يا رَبِّ.\n\n﴿بُهۡتَـٰنٌ﴾: افْتِراءٌ وكَذِبٌ."],[18,18,"﴿ٱلۡـَٔايَـٰتِ﴾: آياتِ القرآنِ المشْتَمِلَةَ على الأحْكامِ والمَواعِظِ."],[19,19,"﴿تَشِيعَ﴾: تَنْتَشِرَ.\n\n﴿ٱلۡفَـٰحِشَةُ﴾: الزِّنى وكلُّ قولٍ سيِّئٍ."],[20,20,"﴿وَلَوۡلَا فَضۡلُ ٱللَّهِ﴾: أي: لولا فَضْلُ اللهِ لَعاجَلَ مَن خالَفَ أمْرَه بالعُقُوبَةِ.\n\n﴿رَءُوفࣱ﴾: كَثِيرُ الرَّأْفَةِ والمَحَبَّةِ لِعِبادِه.\n\n﴿رَّحِيمࣱ﴾: بِعِبادِه فَيَتَقَدَّمُ إلَيِهم بِمِثْلِ هذا الإعْذارِ والإنْذارِ."],[21,21,"﴿خُطُوَ ٰ⁠تِ ٱلشَّيۡطَـٰنِ﴾: طُرُقَه وآثارَه.\n\n﴿بِٱلۡفَحۡشَآءِ﴾: ما عَظُمَ قُبْحُه مِنَ الذُّنوب.\n\n﴿وَٱلۡمُنكَرِ﴾: ما يُنْكِرُه الشَّرعُ أو يَكرَهُه.\n\n﴿مَا زَكَىٰ﴾: ما طَهُرَ، ولا تَطَهَّرَ مِن دَنَسِ الذُّنُوبِ\n\n﴿يُزَكِّي﴾: يُطَهِّرُ."],[22,22,"﴿وَلَا يَأۡتَلِ﴾: ولا يَحْلِفْ.\n\n﴿أُوْلُواْ ٱلۡفَضۡلِ﴾: أصْحابُ الفَضَلِ في الدِّينِ.\n\n﴿وَٱلسَّعَةِ﴾: الغِنى في المالِ.\n\n﴿أَن يُؤۡتُوٓاْ﴾: أي: يَحْلِفُونَ على ألّا يُعْطُوا.\n\n﴿أُوْلِي ٱلۡقُرۡبَىٰ﴾: أصْحابَ القَرابَةِ.\n\n﴿وَلۡيَعۡفُواْ﴾: أي: ولْيَتَجاوزُوا عَن ذَنْبِهِم وإساءَتِهِم.\n\n﴿وَلۡيَصۡفَحُوٓاْ﴾: أي: بالإعْراضِ عَن مُّؤاخَذَتِهِم."],[23,23,"﴿يَرۡمُونَ﴾: يَقْذِفُون بالزِّنى.\n\n﴿ٱلۡمُحۡصَنَـٰتِ﴾: العفِيفاتِ.\n\n﴿ٱلۡغَـٰفِلَـٰتِ﴾: اللّاتي لا تَخْطُرُ بِبالِهنَّ الفاحِشَةُ."],[25,25,"﴿دِينَهُمُ ٱلۡحَقَّ﴾: جَزاءَهم الثّابِتَ لهم بالعَدْلِ."],[26,26,"﴿مِمَّا يَقُولُونَ﴾: أي: مِنِ اتِّهامِهِم."],[27,27,"﴿حَتَّىٰ تَسۡتَأۡنِسُواْ﴾: حتى تَسْتأذِنُوا."],[28,28,"﴿هُوَ أَزۡكَىٰ لَكُمۡ﴾: الرُّجُوعُ أْطَهرُ لكُم."],[29,29,"﴿جُنَاحٌ﴾: حَرَجٌ.\n\n﴿غَيۡرَ مَسۡكُونَةࣲ﴾: ليسَتْ مُخَصَّصَةً لِسَكَنِ أُناسٍ مُعَيَّنِينَ كالفَنادِقِ والمساجِدِ.\n\n﴿مَتَـٰعࣱ لَّكُمۡ﴾: مَنفَعَةٌ ومَصْلَحَةٌ لكُم."],[30,30,"﴿يَغُضُّواْ مِنۡ أَبۡصَـٰرِهِمۡ﴾: يَخْفِضُوا نَظَرَهُم إلى المُحَرَّماتِ.\n\n﴿أَزۡكَىٰ﴾: أطَهرُ."],[31,31,"﴿وَلَا يُبۡدِينَ﴾: ولا يُظْهِرْنَ.\n\n﴿زِينَتَهُنَّ﴾: مواضِعَ زينَتِهنَّ مِنَ الجَسَدِ.\n\n﴿إِلَّا مَا ظَهَرَ مِنۡهَا﴾: مِنَ الثِّيابِ الظّاهِرَةِ التي جَرَتِ العادَةُ بِلُبسِها.\n\n﴿عَلَىٰ جُيُوبِهِنَّ﴾: أي: على فَتَحات ثِيابِهِنَّ مِن جِهَةِ صُدُورِهِنَّ.\n\n﴿لِبُعُولَتِهِنَّ﴾: لأزْواجِهِنَّ.\n\n﴿أَوۡ نِسَآئِهِنَّ﴾: مِنَ المسْلِماتِ المخْتَصّاتِ بهِنَّ بالصُّحْبَةِ أو الخِدْمَةِ.\n\n﴿مَا مَلَكَتۡ أَيۡمَـٰنُهُنَّ﴾: أي: مِنَ العَبِيدِ والإماءِ.\n\n﴿غَيۡرِ أُوْلِي ٱلۡإِرۡبَةِ﴾: الَّذينَ لا حاجةَ لهم في النِّساءِ.\n\n﴿أَوِ ٱلطِّفۡلِ﴾: أي: الأطْفالِ.\n\n﴿لَمۡ يَظۡهَرُواْ﴾: لم يَطَّلِعُوا ولم يَبْلُغُوا حَدَّ الشَّهْوةِ."],[32,32,"﴿ٱلۡأَيَـٰمَىٰ﴾: الَّذينَ لا أزْواجَ لَهُم مِنَ الأحْرارِ والحرائِر."],[33,33,"﴿وَلۡيَسۡتَعۡفِفِ﴾: ولْيطْلُب العِفَّةَ عَنِ الزِّنى والحَرامِ.\n\n﴿لَا يَجِدُونَ نِكَاحًا﴾: أي: لا يَجِدُونَ قُدْرَةً مالِيَّةً على النِّكاحِ.\n\n﴿ٱلۡكِتَـٰبَ﴾: أي: المُكاتَبَةَ، وهي أن يكاتِبَ الرَّجلُ عبدَه على مالٍ يُؤَدِّيهِ مُنَجَّمًا، فإذا أدّاه فهو حُرٌّ.\n\n﴿مِمَّا مَلَكَتۡ أَيۡمَـٰنُكُمۡ﴾: مِن عَبيدِكُم وإمائِكُم.\n\n﴿فَكَاتِبُوهُمۡ﴾: أي: فاكْتُبُوا مَعَهُم عَقْدَ مُكاتَبَةٍ.\n\n﴿فَتَيَـٰتِكُمۡ﴾: إماءَكُم وجَوارِيَكُم.\n\n﴿ٱلۡبِغَآءِ﴾: الزِّنى.\n\n﴿تَحَصُّنࣰا﴾: تَعَفُّفًا.\n\n﴿غَفُورࣱ رَّحِيمࣱ﴾: أي: لمن أُكرِهَتْ على الزِّنى، وبَقِيَ الإثْمُ على مَن أكْرَهَها."],[34,34,"﴿ءَايَـٰتࣲ مُّبَيِّنَـٰتࣲ﴾: آياتِ القرآنِ المفصَّلاتِ.\n\n﴿خَلَوۡاْ﴾: مَضَوا."],[35,35,"﴿كَمِشۡكَوٰةࣲ﴾: الِمشْكاةُ: الكَوَّة في الحائِطِ غيرُ النّافِذَةِ.\n\n﴿مِصۡبَاحٌ﴾: سِراجٌ.\n\n﴿زُجَاجَةٍ﴾: قِنْدِيلٍ مِنَ الزُّجاجِ صافٍ أزْهَرَ.\n\n﴿كَوۡكَبࣱ دُرِّيࣱّ﴾: نَجْمٌ مُضِيءٌ كالدُّرِّ في صَفائِه وإشْراقِه.\n\n﴿لَّا شَرۡقِيَّةࣲ وَلَا غَرۡبِيَّةࣲ﴾: أي: بَلْ هِيَ في موقِعٍ مُتَوَسِّطٍ بينَ الشَّرقِ والغَرْبِ، فَتَتَعَرَّضُ للشَّمسِ طوالَ النَّهارِ."],[36,36,"﴿بُيُوتٍ﴾: مَساجِدَ.\n\n﴿أَذِنَ﴾: أمَرَ وقَضى.\n\n﴿تُرۡفَعَ﴾: تُبْنىَ وتُعَظَّمَ.\n\n﴿بِٱلۡغُدُوِّ وَٱلۡـَٔاصَالِ﴾: أوَّلِ النَّهار وآخِرِه."],[37,37,"﴿لَّا تُلۡهِيهِمۡ﴾: لا تشْغَلُهُم.\n\n﴿تَتَقَلَّبُ﴾: تَضْطَربُ وتَتَحَوَّلُ."],[39,39,"﴿كَسَرَابِۭ﴾: السَّرابُ: ما يُرى ظُهرًا في المفاوِزِ من لَمَعانِ الشَّمْسِ عِنْدَ اشْتِدادِ الحرِّ، يَظُنُّه العَطْشانُ ماءً.\n\n﴿بِقِيعَةࣲ﴾: جَمْعِ «قاعٍ» وهو المستَوي مِنَ الأرضِ."],[40,40,"﴿لُّجِّيࣲّ﴾: عَمِيقٍ كَثِيرِ الماءِ.\n\n﴿يَغۡشَىٰهُ﴾: يَعْلوُ ويُغَطِّي.\n\n﴿يَدَهُۥ لَمۡ يَكَدۡ يَرَىٰهَا﴾: لم يُقارِبْ رُؤيتَها مِن شِدَّةِ الظُّلُماتِ."],[41,41,"﴿صَـٰٓفَّـٰتࣲ﴾: باسِطاتٍ أجْنِحَتَها في الهَواءِ.\n\n﴿صَلَاتَهُۥ﴾: أي: المُصَلِّي مِنهُم عَلِم صَلاتَه.\n\n﴿وَتَسۡبِيحَهُۥ﴾: أي: المُسَبِّحُ مِنهم عَلِمَ تَسْبِيحَهُ."],[42,42,"﴿ٱلۡمَصِيرُ﴾: المَرْجِعُ بعد الموتِ."],[43,43,"﴿يُزۡجِي﴾: يَسُوقُ بِرِفْقٍ.\n\n﴿يُؤَلِّفُ﴾: يَجْمَعُ.\n\n﴿رُكَامࣰا﴾: مُجْتَمِعًا ومُتَراكِمًا بَعْضُهَ فَوْقَ بَعْضٍ.\n\n﴿ٱلۡوَدۡقَ﴾: المَطَرَ.\n\n﴿مِنۡ خِلَـٰلِهِۦ﴾: مِن مَّخارِجِ السَّحابِ.\n\n﴿مِن جِبَالࣲ﴾: أي: مِثلِ جبالٍ في عَظَمَتِه.\n\n﴿سَنَا بَرۡقِهِۦ﴾: ضَوءُ بَرْقِه ولمَعانُه."],[44,44,"﴿لِّأُوْلِي ٱلۡأَبۡصَـٰرِ﴾: لأصْحابِ العُقُولِ السَّلِيمةِ."],[45,45,"﴿عَلَىٰ بَطۡنِهِۦ﴾: كالحيّاتِ ونحوِها.\n\n﴿عَلَىٰ رِجۡلَيۡنِ﴾: كالإنْسانِ.\n\n﴿عَلَىٰٓ أَرۡبَعࣲ﴾: كالبهائِمِ ونحوِها."],[47,47,"﴿يَتَوَلَّىٰ﴾: يُعرِضُ."],[49,49,"﴿لَّهُمُ ٱلۡحَقُّ﴾: أي: في قَضاءِ النَّبيِّ ﷺ وحُكْمِهِ.\n\n﴿مُذۡعِنِينَ﴾: مُسْرِعِينَ مُنْقادِينَ."],[50,50,"﴿مَّرَضٌ﴾: أي: مِنَ النِّفاقِ.\n\n﴿ٱرۡتَابُوٓاْ﴾: شَكُّوا.\n\n﴿أَن يَحِيفَ﴾: أن يَجُورَ."],[53,53,"﴿جَهۡدَ أَيۡمَـٰنِهِمۡ﴾: أي: بأَيمانٍ مُغَلَّظَةٍ.\n\n﴿لَيَخۡرُجُنَّ﴾: أي: لِلْجِهادِ."],[54,54,"﴿فَإِن تَوَلَّوۡاْ﴾: فَإن تُعْرِضُوا.\n\n﴿مَا حُمِّلَ﴾: ما أُمِرَ به مِن تَبْلِيغِ الرِّسالَةِ.\n\n﴿مَّا حُمِّلۡتُمۡ﴾: ما أُمِرْتُم بِه مِنَ الطّاعةِ والانْقِيادِ.\n\n﴿ٱلۡبَلَـٰغُ ٱلۡمُبِينُ﴾: التَّبْلِيغُ الواضِحُ."],[55,55,"﴿لَيَسۡتَخۡلِفَنَّهُمۡ﴾: أي: لَيَجْعَلَنَّهم خُلَفاءَ.\n\n﴿وَلَيُمَكِّنَنَّ لَهُمۡ﴾: ولَيُثَبِّتَنَّ لَهُم.\n\n﴿دِينَهُمُ﴾: وهو دينُ الإسلامِ.\n\n﴿ٱلۡفَـٰسِقُونَ﴾: الخارِجُونَ عَن طاعَةِ اللهِ."],[57,57,"﴿مُعۡجِزِينَ﴾: فائتِينَ مِن عَذابِ اللهِ.\n\n﴿وَمَأۡوَىٰهُمُ﴾: ومَرْجِعُهُم.\n\n﴿وَلَبِئۡسَ﴾: وقَبُحَ.\n\n﴿ٱلۡمَصِيرُ﴾: المرجِعُ."],[58,58,"﴿ٱلَّذِينَ مَلَكَتۡ أَيۡمَـٰنُكُمۡ﴾: هُمُ العبيدُ والإماءُ.\n\n﴿ٱلۡحُلُمَ﴾: أي: سِنَّ الاحْتِلامِ.\n\n﴿ثَلَـٰثُ عَوۡرَ ٰ⁠تࣲ لَّكُمۡ﴾: أي: ثلاثةُ أوقاتٍ يَخْتَلُّ فيها السِّتْرُ ويَقِلُّ.\n\n﴿جُنَاحُۢ﴾: حَرَجٌ.\n\n﴿طَوَّ ٰ⁠فُونَ﴾: أي: كَثِيرُو التَّطْوافِ والتَّردُّدِ عَلَيكُم لِلْخِدْمَةِ وقَضاءِ المصالِحِ.\n\n﴿يُبَيِّنُ﴾: يُوضِّحُ.\n\n﴿ٱلۡـَٔايَـٰتِ﴾: أي: آياتِ القُرآنِ الدّالَّةَ على الأحْكامِ."],[59,59,"﴿ٱلۡحُلُمَ﴾: سِنَّ الاحْتِلامِ والبُلُوغِ."],[60,60,"﴿وَٱلۡقَوَ ٰ⁠عِدُ مِنَ ٱلنِّسَآءِ﴾: العَجائِزُ اللّاتي قَعَدْنَ عَنِ الحَيضِ والاسْتِمْتاعِ لِكِبَرِهِنَّ.\n\n﴿لَا يَرۡجُونَ نِكَاحࣰا﴾: لا يَطْمَعْنَ فيه.\n\n﴿مُتَبَرِّجَـٰتِۭ﴾: مُظْهِراتٍ.\n\n﴿وَأَن يَسۡتَعۡفِفۡنَ﴾: وأن يَتْرُكْنَ وضْعَ الثِّيابِ لِطَلَبِ العِفَّةِ."],[61,61,"﴿حَرَجࣱ﴾: إثْمٌ.\n\n﴿أَوۡ مَا مَلَكۡتُم مَّفَاتِحَهُۥٓ﴾: أي: البُيوتِ الَّتي تَمْلِكُونَ التَّصرُّفَ فِيها بإذِنِ أرْبابِها.\n\n﴿أَشۡتَاتࣰا﴾: مُتَفَرِّقِينَ.\n\n﴿ٱلۡـَٔايَـٰتِ﴾: أي: آياتِ القرآنِ الدّالَّةَ على الأحْكامِ."],[62,62,"﴿أَمۡرࣲ جَامِعࣲ﴾: أمرٍ مُهِمٍّ يَجِبُ اجْتِماعُهُم لَهُ.\n\n﴿لِبَعۡضِ شَأۡنِهِمۡ﴾: أي: لِبَعْضِ أُمُورِهِم."],[63,63,"﴿دُعَآءَ ٱلرَّسُولِ﴾: دَعْوتَهُ لَكُم لِلاجْتِماعِ، أو نِداءَكُم لَهُ ﷺ.\n\n﴿يَتَسَلَّلُونَ﴾: يَخْرُجُونَ خِفْيةً مِن غِيرِ إذْنٍ.\n\n﴿لِوَاذࣰا﴾: أي: مُسْتَترِينَ بعضُهم بِبَعْضٍ عنْدَ الخُروجِ.\n\n﴿فِتۡنَةٌ﴾: بَلاءٌ ومِحْنَةٌ في الدُّنْيا."]]);
QTF("gharib",25,[[1,1,"﴿تَبَارَكَ﴾: تَكاثَرَ خَيْرُه وعَظُمَتْ بَرَكاتُه.\n\n﴿ٱلۡفُرۡقَانَ﴾: القُرآنَ، الفارقَ بَيْنَ الحقِّ والَباطِلِ.\n\n﴿نَذِيرًا﴾: مُخَوِّفًا."],[2,2,"﴿فَقَدَّرَهُۥ﴾: أي: فَهَيَّأَه لِما يَصْلُحُ لَهُ ويلِيقُ بِهِ."],[3,3,"﴿نُشُورࣰا﴾: بَعْثًا بَعْدَ الموتِ."],[4,4,"﴿هَـٰذَآ﴾: أي: القرآنُ.\n\n﴿إِفۡكٌ﴾: كَذِبٌ وبُهْتانٌ.\n\n﴿ٱفۡتَرَىٰهُ﴾: اختَلَقَه وتَقَوَّلَه.\n\n﴿قَوۡمٌ ءَاخَرُونَ﴾: أي: من الَّذينَ أسْلَمُوا مِن أهْلِ الكِتابِ.\n\n﴿وَزُورࣰا﴾: كَذِبًا عظِيمًا."],[5,5,"﴿أَسَـٰطِيرُ ٱلۡأَوَّلِينَ﴾: الأكاذيبُ الَّتي كَتَبها المتقدِّمُونَ.\n\n﴿ٱكۡتَتَبَهَا﴾: طَلَبَ كِتابَتَها.\n\n﴿تُمۡلَىٰ عَلَيۡهِ﴾: تُقْرَأُ عَلَيهِ لِيِحْفَظَها."],[6,6,"﴿ٱلسِّرَّ﴾: هو كلُّ ما يَغِيبُ ويَخْفى."],[8,8,"﴿جَنَّةࣱ﴾: أي: بُسْتانٌ مُثْمِرٌ.\n\n﴿مَّسۡحُورًا﴾: مَجْنُونًا، غَلَبَ السِّحرُ على عَقْلِه."],[10,10,"﴿جَنَّـٰتࣲ﴾: بَساتِينَ وحَدائقَ.\n\n﴿قُصُورَۢا﴾: بُيُوتًا مُشَيَّدةً."],[11,11,"﴿وَأَعۡتَدۡنَا﴾: وجَعَلْناه مُعَدًّا لهم.\n\n﴿سَعِيرًا﴾: أي: نارًا مُشْتَعِلةً تُسَعَّر بهم."],[12,12,"﴿تَغَيُّظࣰا﴾: صَوْتَ غَلَيانٍ وفَوَرانٍ.\n\n﴿وَزَفِيرࣰا﴾: النَّفَسَ الخارِجَ مِنَ الجَوفِ بِشِدَّةٍ."],[13,13,"﴿مِنۡهَا﴾: أي: مِن جَهَنَّمَ.\n\n﴿مُّقَرَّنِينَ﴾: مُقَيَّدةً أيدِيهِم إلى أعْناقِهِم.\n\n﴿ثُبُورࣰا﴾: هَلاكًا."],[15,15,"﴿وَمَصِيرࣰا﴾: ومَرْجِعًا."],[16,16,"﴿مَّسۡـُٔولࣰا﴾: أي: يَسْأَلُ اللهَ عِبادُه المتَّقُونَ"],[18,18,"﴿سُبۡحَـٰنَكَ﴾: تَنْزِيهًا لَكَ يا رَبَّنا.\n\n﴿مَا كَانَ يَنۢبَغِي لَنَآ﴾: ما كان يَحِقُّ ولا يَصِحُّ لَنا.\n\n﴿أَوۡلِيَآءَ﴾: المُرادُ به: آلهةٌ نَعْبُدُهُم.\n\n﴿نَسُواْ ٱلذِّكۡرَ﴾: غَفَلُوا عَن دَلائِلِ الوَحْدانيَّةِ.\n\n﴿بُورࣰا﴾: هالِكِينَ أو فاسِدِين."],[19,19,"﴿صَرۡفࣰا﴾: دَفْعًا.\n\n﴿يَظۡلِم﴾: أي: يُشْرِكْ بِاللهِ."],[20,20,"﴿فِتۡنَةً﴾: ابْتِلاءً واخْتِبارًا."],[21,21,"﴿لَا يَرۡجُونَ﴾: لا يخافُونَ.\n\n﴿أَوۡ نَرَىٰ﴾: أي: عِيانًا.\n\n﴿ٱسۡتَكۡبَرُواْ فِيٓ أَنفُسِهِمۡ﴾: أضْمَرُوا الاسْتِكْبارَ عَنِ الحَقِّ في قُلُوبِهِم.\n\n﴿وَعَتَوۡ﴾: تَجاوَزُوا الحدَّ في الطُّغيانِ."],[22,22,"﴿حِجۡرࣰا مَّحۡجُورࣰا﴾: حَرامًا محرَّمًا عَلَيكُمُ الجنَّةُ."],[23,23,"﴿هَبَآءࣰ﴾: أي: كالهباءِ وهو ما يُرى في ضَوءِ الشَّمسِ مِن دقِيقِ الغُبارِ.\n\n﴿مَّنثُورًا﴾: مُفَرَّقًا."],[24,24,"﴿مَقِيلࣰا﴾: مَكانًا للرّاحَةِ وقتَ القَيْلُولَةِ."],[25,25,"﴿تَشَقَّقُ ٱلسَّمَآءُ﴾: تَتَفَتَّحُ السَّمَواتُ.\n\n﴿بِٱلۡغَمَـٰمِ﴾: بالسَّحابِ الأبيضِ الرَّقِيقِ."],[26,26,"﴿عَسِيرࣰا﴾: صَعْبًا شَدِيدًا."],[27,27,"﴿يَعَضُّ ٱلظَّالِمُ عَلَىٰ يَدَيۡهِ﴾: أي: تَحَسُّرًا."],[28,28,"﴿خَلِيلࣰا﴾: صَدِيقًا."],[29,29,"﴿ٱلذِّكۡرِ﴾: أي: القرآنِ والإيمانِ به.\n\n﴿خَذُولࣰا﴾: كثيرَ الخِذْلانِ لِمَن يُوالِيهِ، والخِذْلانُ: التَّخَلِّي عَنِ النُّصْرَةِ."],[30,30,"﴿مَهۡجُورࣰا﴾: مَتْرُوكًا، تُرِكَ الإيمانُ به والعَمَلُ بِما فِيه."],[31,31,"﴿ٱلۡمُجۡرِمِينَ﴾: أي: الكافِرِينَ والمُشْرِكِينَ."],[32,32,"﴿لَوۡلَا﴾: هَلّا.\n\n﴿جُمۡلَةࣰ وَ ٰ⁠حِدَةࣰ﴾: أي: دُفْعةً واحِدَةً.\n\n﴿لِنُثَبِّتَ بِهِۦ فُؤَادَكَ﴾: لنُقَوِّيَ به قَلْبَكَ.\n\n﴿وَرَتَّلۡنَـٰهُ تَرۡتِيلࣰا﴾: أي: أنْزَلْناه وفرَّقْناه آيةً بعْدَ آيةٍ."],[33,33,"﴿بِمَثَلٍ﴾: بِحُجَّةٍ أو شُبْهَةٍ."],[35,35,"﴿وَزِيرࣰا﴾: مُعِينًا لِتَبْلِيغِ الرِّسالةِ."],[36,36,"﴿فَدَمَّرۡنَـٰهُمۡ﴾: فَأَهْلَكْناهُم."],[37,37,"﴿ءَايَةࣰ﴾: عِبْرةً.\n\n﴿وَأَعۡتَدۡنَا﴾: هَيَّأنا."],[38,38,"﴿وَأَصۡحَـٰبَ ٱلرَّسِّ﴾: أصْحابَ البِئْرِ.\n\n﴿وَقُرُونَۢا﴾: وأُمَمًا."],[39,39,"﴿ضَرَبۡنَا لَهُ ٱلۡأَمۡثَـٰلَ﴾: بَيَّنّا لجَمِيعِ الأمَمِ الحُجَجَ، وأَزَلْنا عَنْهم الشَّبُهاتِ.\n\n﴿تَبَّرۡنَا﴾: أهْلَكْنا."],[40,40,"﴿ٱلۡقَرۡيَةِ﴾: هي «سَدُومُ» قَرْيَةُ قَومِ لُوطٍ.\n\n﴿مَطَرَ ٱلسَّوۡءِ﴾: أي: بالحِجارةِ مِنَ السَّماءِ.\n\n﴿لَا يَرۡجُونَ نُشُورࣰا﴾: لا يتَوَقَّعُونَ بَعْثًا بَعْدَ الموتِ."],[41,41,"﴿هُزُوًا﴾: مُسْتَهْزَأً بِه."],[42,42,"﴿إِن كَادَ﴾: إنّه قارَبَ."],[43,43,"﴿وَكِيلًا﴾: حَفِيظًا يَحْفَظُه مِنِ اتِّباعِ هَواهُ."],[44,44,"﴿كَٱلۡأَنۡعَـٰمِ﴾: كالبَهائِمِ لا يَفْهَمُونَ."],[45,45,"﴿مَدَّ ٱلظِّلَّ﴾: بَسَطَه مِن طُلُوعِ الفَجْرِ إلى طُلُوعِ الشَّمسِ.\n\n﴿سَاكِنࣰا﴾: ثابِتًا، لا تُزِيلُهُ الشَّمْسُ.\n\n﴿دَلِيلࣰا﴾: أي: يُسْتَدَلُّ بأحْوالِ الشَّمسِ على أحْوالِ الظِّلِّ."],[46,46,"﴿قَبۡضࣰا يَسِيرࣰا﴾: أي: يَتَقَلَّصُ الظِّلُّ تَدْرِيجيًّا بِقَدْرِ ارْتِفاعِ الشَّمسِ."],[47,47,"﴿لِبَاسࣰا﴾: ساتِرًا بِظَلامِهِ.\n\n﴿سُبَاتࣰا﴾: راحَةً لَكُم.\n\n﴿نُشُورࣰا﴾: تَنْتَشِرُونَ فِيهِ لمَعاشِكُم."],[49,49,"﴿أَنۡعَـٰمࣰا﴾: بَهائِمَ.\n\n﴿وَأَنَاسِيَّ﴾: أُناسًا."],[50,50,"﴿صَرَّفۡنَـٰهُ بَيۡنَهُمۡ﴾: أنْزَلْنا المَطَرَ على أنْحاءٍ مُخْتَلِفَةٍ.\n\n﴿كُفُورࣰا﴾: جُحُودًا بالنِّعمَةِ."],[52,52,"﴿وَجَـٰهِدۡهُم بِهِۦ﴾: وجاهِدِ الكُفّارَ بالقُرآنِ والبُرْهانِ."],[53,53,"﴿مَرَجَ﴾: خَلَطَ وأرْسَلَ.\n\n﴿عَذۡبࣱ فُرَاتࣱ﴾: حُلْوٌ شَدِيدُ الحَلاوَةِ.\n\n﴿أُجَاجࣱ﴾: شَدِيدُ المُلُوحَةِ.\n\n﴿بَيۡنَهُمَا بَرۡزَخࣰا﴾: حاجِزًا بين البَحْرَينِ يَمْنَعُ اخْتِلاطَ أحَدِهِما بالآخَر.\n\n﴿وَحِجۡرࣰا مَّحۡجُورࣰا﴾: أي: مانِعًا حَصِينًا."],[54,54,"﴿ٱلۡمَآءِ﴾: هو مَنِيُّ الرَّجلِ والمرْأةِ.\n\n﴿وَصِهۡرࣰا﴾: القَرابَةَ النّاشِئَةَ مِنَ الزَّواجِ بَيْنَ الزَّوْجِ وأهْلِ زَوْجتِهِ."],[55,55,"﴿عَلَىٰ رَبِّهِۦ ظَهِيرࣰا﴾: مُعِينًا للشَّيطانِ على رَبِّه."],[59,59,"﴿ثُمَّ ٱسۡتَوَىٰ﴾: أي: عَلا وارْتَفَعَ كَما يَلِيقُ بِجَلالِهِ.\n\n﴿ٱلۡعَرۡشِ﴾: هو سريرُ المُلْكِ الَّذِي اسْتَوى عليه الرَّحْمَنُ وتَحْمِلُهُ الملائِكةُ، وهو أعْظَمُ المخْلُوقاتِ، وهو سَقْفُ الجنَّةِ."],[60,60,"﴿نُفُورࣰا﴾: تَباعُدًا عَنِ الإيمانِ."],[61,61,"﴿تَبَارَكَ﴾: تَكاثَرَ خَيْرُه وعَظُمَتْ بَرَكاتُه.\n\n﴿بُرُوجࣰا﴾: مَنازِلَ للكَواكِبِ والنُّجُومِ.\n\n﴿سِرَ ٰ⁠جࣰا﴾: شَمْسًا تُضِيءُ."],[62,62,"﴿خِلۡفَةࣰ﴾: يَخْلُفُ أحدُهما الآخَرَ فَيَتَعاقَبانِ.\n\n﴿أَن يَذَّكَّرَ﴾: أن يَعْتَبرَ."],[63,63,"﴿هَوۡنࣰا﴾: أي: بسَكِينَةٍ وتَواضُعٍ.\n\n﴿قَالُواْ سَلَـٰمࣰا﴾: أي: قالُوا قَوْلًا سَدِيدًا يَسْلَمُونَ بهِ مِنَ الأذى."],[64,64,"﴿يَبِيتُونَ﴾: يَقْضُونَ لَيالِيَهُم."],[65,65,"﴿ٱصۡرِفۡ﴾: ادْفَعْ.\n\n﴿غَرَامًا﴾: لِزامًا، يُلازِمُ صاحِبَهُ."],[67,67,"﴿لَمۡ يُسۡرِفُواْ﴾: لم يَتَجاوَزُوا حَدَّ الاعْتِدالِ.\n\n﴿وَلَمۡ يَقۡتُرُواْ﴾: ولم يُضَيِّقوا في الإنْفِاقِ.\n\n﴿قَوَامࣰا﴾: وسَطًا بَيْنَ التَّبذِيرِ والتَّضْيِيقِ."],[68,68,"﴿لَا يَدۡعُونَ﴾: لا يَعْبُدُونَ.\n\n﴿أَثَامࣰا﴾: عِقابًا."],[69,69,"﴿وَيَخۡلُدۡ فِيهِۦ﴾: ويَبْقى فيه على الدَّوامِ.\n\n﴿مُهَانًا﴾: ذلِيلًا حَقِيرًا."],[71,71,"﴿مَتَابࣰا﴾: توبةً."],[72,72,"﴿ٱلزُّورَ﴾: شَهادَةً كاذِبَةً.\n\n﴿بِٱللَّغۡوِ﴾: بِكُلِّ ساقِطٍ مِن قَوْلٍ أو فِعْلٍ.\n\n﴿مَرُّواْ كِرَامࣰا﴾: مُكْرِمِينَ أنْفُسَهُم بالإعْراضِ عَنْهُ."],[73,73,"﴿لَمۡ يَخِرُّواْ﴾: لم يَسْقُطُوا ولَمْ يَقَعُوا.\n\n﴿صُمࣰّا وَعُمۡيَانࣰا﴾: أي: لا يَسْمَعُونَ ولا يُبْصِرُونَ، والمعنى إنّما يَخِرُّونَ عَلَيها سامِعِينَ مُبْصِرِينَ مُنْتَفِعِينَ."],[74,74,"﴿قُرَّةَ أَعۡيُنࣲ﴾: مَوْضِعَ سُرورٍ وفَرَحٍ."],[75,75,"﴿ٱلۡغُرۡفَةَ﴾: المرادُ منها أعلى مَنازِلِ الجنَّةِ وأَفْضَلُها."],[77,77,"﴿مَا يَعۡبَؤُاْ بِكُمۡ﴾: لا يُبالي بكُم.\n\n﴿لِزَامَۢا﴾: أي: عَذابًا داِئمًا مُلازِمًا لَكُم."]]);
QTF("gharib",26,[[2,2,"﴿ٱلۡكِتَـٰبِ﴾: القرآنِ."],[3,3,"﴿بَـٰخِعࣱ نَّفۡسَكَ﴾: مُهْلِكُها غَمًّا وحُزْنًا."],[4,4,"﴿ءَايَةࣰ﴾: مُعْجِزَةً.\n\n﴿خَـٰضِعِينَ﴾: مُنْقادِينَ بالكُرْهِ مِنهُم."],[5,5,"﴿مُحۡدَثٍ﴾: أي: مُجَدَّدٍ إنْزالُه."],[7,7,"﴿أَوَ لَمۡ يَرَوۡاْ﴾: أوَلَم يَنْظُرُوا.\n\n﴿زَوۡجࣲ كَرِيمٍ﴾: صِنْفٍ حَسَنٍ كَثِيرِ النَّفْعِ."],[8,8,"﴿لَـَٔايَةࣰ﴾: لَدَلالةً واضِحَةً."],[11,11,"﴿أَلَا يَتَّقُونَ﴾: ألا يَخافُونَ عِقابَ اللهِ تعالى؟"],[14,14,"﴿ذَنۢبࣱ﴾: وهو قَتْلُ القِبْطِيِّ."],[15,15,"﴿بِـَٔايَـٰتِنَآ﴾: بِمُعْجزاتِنا وحُجَجِنا.\n\n﴿إِنَّا مَعَكُم﴾: أي: بالعِلْمِ والحِفْظِ والنُّصْرَةِ."],[18,18,"﴿أَلَمۡ نُرَبِّكَ﴾: ألم نَرْعَكَ.\n\n﴿وَلِيدࣰا﴾: صَغِيرًا."],[19,19,"﴿فَعۡلَتَكَ﴾: أي: قَتْلَ القِبْطِيِّ.\n\n﴿مِنَ ٱلۡكَـٰفِرِينَ﴾: أي: من الجاحِدِينَ لِنِعْمَتِي."],[20,20,"﴿مِنَ ٱلضَّآلِّينَ﴾: مِنَ المُخْطِئِينَ لا المتعَمِّدِينَ."],[21,21,"﴿حُكۡمࣰا﴾: أي: نُبُوَّةً وحِكْمَةً."],[22,22,"﴿تَمُنُّهَا عَلَيَّ﴾: تَعُدُّها نِعْمَةً مِنكَ عليّ.\n\n﴿عَبَّدتَّ﴾: جَعَلْتَهُم عَبِيدًا تَذْبَحُ مَن تَشاءُ وتَتْرُكُ مَن تَشاءُ مِن أبْنائِهِم وتَسْتَبْقِي نِساءَهُم لِلْخِدْمَةِ والامْتِهانِ."],[30,30,"﴿بِشَيۡءࣲ مُّبِينࣲ﴾: أي: بِبُرْهانٍ قاطِعٍ."],[33,33,"﴿بَيۡضَآءُ﴾: أي: مِن غَيرِ مَرَضٍ ولا بَرَصٍ."],[34,34,"﴿لِلۡمَلَإِ﴾: لأشْرافِ قَوْمِهِ.\n\n﴿لَسَـٰحِرٌ عَلِيمࣱ﴾: أي: ساحِرٌ ماهِرٌ."],[36,36,"﴿أَرۡجِهۡ﴾: أخِّرْهُ.\n\n﴿ٱلۡمَدَآئِنِ﴾: المُدُنِ.\n\n﴿حَـٰشِرِينَ﴾: جامِعِينَ للسَّحَرةِ."],[45,45,"﴿تَلۡقَفُ﴾: تَبْتَلِعُ بِسُرْعَةٍ.\n\n﴿مَا يَأۡفِكُونَ﴾: ما يَكْذِبُونَهُ ويُمَوِّهُونَهُ."],[49,49,"﴿مِّنۡ خِلَـٰفࣲ﴾: أي: بِقَطْعِ اليَدِ اليُمْنى والرِّجْلِ اليُسْرى أو عَكْسِ ذَلِك.\n\n﴿وَلَأُصَلِّبَنَّكُمۡ﴾: ولَأُبالِغَنَّ في شَدِّ أطْرافِكُم ورَبْطِ أجْسادِكُم على جُذُوعِ النَّخْلِ."],[50,50,"﴿لَا ضَيۡرَ﴾: لا ضَرَرَ عَلَينا فِيما يُصِيبُنا.\n\n﴿مُنقَلِبُونَ﴾: راجِعُونَ."],[51,51,"﴿أَوَّلَ ٱلۡمُؤۡمِنِينَ﴾: أي: مِن قَومِ فِرْعَونَ."],[52,52,"﴿أَنۡ أَسۡرِ بِعِبَادِيٓ﴾: أي: اخْرُجْ بِهِم لَيْلًا.\n\n﴿مُّتَّبَعُونَ﴾: يَتَّبِعُكُم فِرْعَونُ وجُنُودُه."],[53,53,"﴿ٱلۡمَدَآئِنِ﴾: المُدُنِ.\n\n﴿حَـٰشِرِينَ﴾: جامِعِينَ لِلْجَيشِ."],[54,54,"﴿لَشِرۡذِمَةࣱ﴾: لَطائِفَةٌ حَقِيرَةٌ قَلِيلةُ العَدَدِ."],[55,55,"﴿لَنَا لَغَآئِظُونَ﴾: لَمُغْضِبُونا بِخُرُوجِهِم مِن غَيْرِ إذْنٍ مِنّا."],[56,56,"﴿حَـٰذِرُونَ﴾: مُتَيَقِّظُونَ."],[57,57,"﴿جَنَّـٰتࣲ﴾: بَساتِينَ."],[60,60,"﴿مُّشۡرِقِينَ﴾: وقْتَ شُرُوقِ الشَّمْسِ."],[61,61,"﴿ٱلۡجَمۡعَانِ﴾: جَمْعُ مُوسى وهُم بنُو إسْرائيلَ، وجَمْعُ فِرْعَونَ وهم القِبْطُ.\n\n﴿لَمُدۡرَكُونَ﴾: لَمُلحَقُون من قِبَلِ فِرْعَونَ وجُنُودِهِ."],[63,63,"﴿فَٱنفَلَقَ﴾: أي: انْشَقَّ البَحْرُ إلى اثْنَي عَشْرَ طَرِيقًا.\n\n﴿فِرۡقࣲ﴾: قِطْعةٍ من البحْرِ مُرْتَفِعَةٍ.\n\n﴿كَٱلطَّوۡدِ﴾: كالجَبَلِ المُتَطاوِلِ في السَّماءِ."],[64,64,"﴿وَأَزۡلَفۡنَا﴾: وقَرَّبْنا.\n\n﴿ثَمَّ﴾: هُناك.\n\n﴿ٱلۡـَٔاخَرِينَ﴾: وهم فِرْعَونُ وقَوْمُه."],[67,67,"﴿لَـَٔايَةࣰ﴾: لَعِبرةً عَجِيبةً."],[71,71,"﴿لَهَا عَـٰكِفِينَ﴾: على عِبادتِها مُقِيمِينَ على الدَّوامِ."],[75,75,"﴿أَفَرَءَيۡتُم﴾: هَل تأمَّلْتُم ما أنْتُم عَلَيه؟"],[82,82,"﴿يَوۡمَ ٱلدِّينِ﴾: يومَ الجَزاءِ."],[83,83,"﴿حُكۡمࣰا﴾: عِلْمًا وفَهْمًا."],[84,84,"﴿لِسَانَ صِدۡقࣲ﴾: ثَناءً حَسَنًا.\n\n﴿فِي ٱلۡـَٔاخِرِينَ﴾: أي: في الَّذينَ يأتُونَ بَعْدِي إلى يومِ القِيامَةِ."],[87,87,"﴿وَلَا تُخۡزِنِي﴾: ولا تَفْضَحْنِي."],[89,89,"﴿بِقَلۡبࣲ سَلِيمࣲ﴾: أي: مِنَ النِّفاقِ والكُفْرِ."],[90,90,"﴿وَأُزۡلِفَتِ﴾: قُرِّبَتْ."],[91,91,"﴿وَبُرِّزَتِ﴾: أُظْهِرَتْ.\n\n﴿لِلۡغَاوِينَ﴾: للضّالِينَ عَن طَرِيقِ الهِدايةِ."],[94,94,"﴿فَكُبۡكِبُواْ فِيهَا﴾: أُلْقُوا في جَهَنَّمَ على وُجُوهِهِم مرَّةً بَعْدَ مَرَّةٍ إلى أنِ اسْتَقرُّوا في قَعْرِها."],[96,96,"﴿يَخۡتَصِمُونَ﴾: يَتَنازَعُون."],[97,97,"﴿إِن كُنَّا﴾: إنَّنا كُنّا."],[98,98,"﴿نُسَوِّيكُم بِرَبِّ ٱلۡعَـٰلَمِينَ﴾: نَجْعَلُكُم مِثْلَ رَبِّ العالَمِينَ."],[100,100,"﴿شَـٰفِعِينَ﴾: فَيُخَلِّصُونا مِنَ العَذابِ."],[101,101,"﴿حَمِيمࣲ﴾: قَرِيبٍ ومُشْفِقٍ."],[102,102,"﴿كَرَّةࣰ﴾: رَجْعَةً إلى الدُّنيا."],[111,111,"﴿ٱلۡأَرۡذَلُونَ﴾: أي: أسافلُ النّاسِ وأَراذِلُهم."],[116,116,"﴿ٱلۡمَرۡجُومِينَ﴾: مِنَ المقْتُولِينَ رَمْيًا بالحِجارَةِ."],[118,118,"﴿فَٱفۡتَحۡ﴾: فاحْكُمْ."],[119,119,"﴿ٱلۡمَشۡحُونِ﴾: المَمْلُوءِ بالنّاسِ والدَّوابِّ والمتاعِ."],[128,128,"﴿رِيعٍ﴾: مكانٍ مُرْتَفِعٍ.\n\n﴿ءَايَةࣰ﴾: بِناءً شامِخًا."],[129,129,"﴿مَصَانِعَ﴾: حُصُونًا أو قُصُورًا.\n\n﴿تَخۡلُدُونَ﴾: أي: تَبْقَونَ في الدُّنيا ولا تَمُوتُونَ."],[130,130,"﴿بَطَشۡتُم﴾: أخَذْتُم بِعُنْفٍ.\n\n﴿جَبَّارِينَ﴾: قاهِرِينَ ظالِمِين."],[132,132,"﴿أَمَدَّكُم﴾: أنْعَمَ عليكُم وأَعْطاكُم."],[133,133,"﴿بِأَنۡعَـٰمࣲ﴾: مِنَ الإبِلِ والبَقَرِ والغَنَمِ."],[134,134,"﴿وَجَنَّـٰتࣲ﴾: حَدائِقَ وبَساتِينَ."],[137,137,"﴿إِنۡ هَـٰذَآ﴾: ما هَذا.\n\n﴿خُلُقُ ٱلۡأَوَّلِينَ﴾: دِينُ الأوَّلِينَ وعاداتُهُم."],[146,146,"﴿مَا هَـٰهُنَآ﴾: أي: في الدُّنيا."],[148,148,"﴿طَلۡعُهَا﴾: ثَمَرُها.\n\n﴿هَضِيمࣱ﴾: مُنْكَسِرٌ مِن لِينِهِ ورُطُوبَتِه."],[149,149,"﴿فَـٰرِهِينَ﴾: ماهِرِين بنَحْتِها."],[153,153,"﴿مِنَ ٱلۡمُسَحَّرِينَ﴾: مِنَ المغْلُوبِ على عُقُولِهِم بِكَثْرَةِ السِّحرِ."],[154,154,"﴿بِـَٔايَةٍ﴾: بِحُجَّةٍ واضِحَةٍ."],[155,155,"﴿لَّهَا شِرۡبࣱ﴾: لها نَصِيبٌ مِنَ الماءِ."],[157,157,"﴿فَعَقَرُوهَا﴾: فَنَحَرُوها."],[165,165,"﴿أَتَأۡتُونَ ٱلذُّكۡرَانَ﴾: أتَنْكِحُونَ الرِّجالَ؟"],[166,166,"﴿وَتَذَرُونَ﴾: وتَتْرُكُونَ.\n\n﴿عَادُونَ﴾: مُتَجاوِزُونَ ما أباحَهُ اللهُ لَكُم مِنَ الحَلالِ إلى الحَرامِ."],[168,168,"﴿مِّنَ ٱلۡقَالِينَ﴾: مِنَ المُبْغِضِينَ أشَدَّ البُغْضِ."],[171,171,"﴿فِي ٱلۡغَـٰبِرِينَ﴾: في الباقِينَ في العذابِ والهلاكِ."],[172,172,"﴿دَمَّرۡنَا﴾: أهْلَكْنا."],[176,176,"﴿أَصۡحَـٰبُ لۡـَٔيۡكَةِ﴾: أصْحابُ الشَّجَرِ المُلْتَفِّ."],[181,181,"﴿مِنَ ٱلۡمُخۡسِرِينَ﴾: مِنَ النّاقِصِينَ للحُقُوقِ بالتَّطفِيفِ."],[182,182,"﴿بِٱلۡقِسۡطَاسِ﴾: بالميزانِ."],[183,183,"﴿وَلَا تَبۡخَسُواْ﴾: ولا تَنْقُصُوا.\n\n﴿وَلَا تَعۡثَوۡاْ﴾: ولا تُفْسِدُوا أشَدَّ الإفْسادِ."],[184,184,"﴿وَٱلۡجِبِلَّةَ ٱلۡأَوَّلِينَ﴾: والخَلائِقَ من الأُمَمِ المتقدِّمةِ."],[185,185,"﴿مِنَ ٱلۡمُسَحَّرِينَ﴾: مِنَ المغلُوبِ على عُقُولِهِم بِكَثْرَةِ السِّحْرِ."],[187,187,"﴿كِسَفࣰا﴾: قِطَعَ عَذابٍ."],[189,189,"﴿يَوۡمِ ٱلظُّلَّةِ﴾: أي: أظَلَّتْهُم سَحابَةٌ، ثُمَّ أمْطَرَتْهُم نارًَا."],[193,193,"﴿ٱلرُّوحُ ٱلۡأَمِينُ﴾: جِبْرِيلُ عَلَيهِ السَّلامُ."],[196,196,"﴿وَإِنَّهُۥ﴾: وإنَّ ذِكْرَ هَذا القُرآنِ.\n\n﴿زُبُرِ ٱلۡأَوَّلِينَ﴾: كُتُبِ الرُّسُلِ السّابِقِينَ."],[198,198,"﴿ٱلۡأَعۡجَمِينَ﴾: الَّذِينَ لا يتكَلَّمُونَ باللغةِ العَربيةِ."],[200,200,"﴿سَلَكۡنَـٰهُ﴾: أدْخَلْناه."],[202,202,"﴿بَغۡتَةࣰ﴾: فَجْأَةً."],[203,203,"﴿مُنظَرُونَ﴾: مُمْهَلُون لِنُؤمِنَ."],[205,205,"﴿مَّتَّعۡنَـٰهُمۡ سِنِينَ﴾: أي: طَوَّلْنا لَهُم أعْمارَهُم."],[207,207,"﴿مَآ أَغۡنَىٰ عَنۡهُم﴾: أي: لم يَنْفَعْهُم."],[209,209,"﴿ذِكۡرَىٰ﴾: أي: تَذْكِيرٌ وتَنْبِيهٌ."],[211,211,"﴿وَمَا يَنۢبَغِي لَهُمۡ﴾: ولا يَصِحُّ مِنهُم."],[212,212,"﴿لَمَعۡزُولُونَ﴾: لمحْجُوُبونَ."],[214,214,"﴿عَشِيرَتَكَ﴾: قَبِيلَتَكَ."],[215,215,"﴿وَٱخۡفِضۡ جَنَاحَكَ﴾: ألِنْ جانِبَكَ وتَواضَعْ."],[219,219,"﴿وَتَقَلُّبَكَ﴾: وتَصرُّفَكَ أو تَقَلُّبَكَ في الرُّكُوعِ والسُّجُودِ والقِيامِ."],[222,222,"﴿أَفَّاكٍ﴾: كَذّابٍ.\n\n﴿أَثِيمࣲ﴾: كَثِيرِ الآثامِ."],[223,223,"﴿يُلۡقُونَ ٱلسَّمۡعَ﴾: يُلْقُونَ ما سَمِعُوه مِنَ السَّماءِ إلى الكُهّانِ."],[224,224,"﴿ٱلۡغَاوُۥنَ﴾: الضّالُّونَ عَنِ الحقِّ."],[225,225,"﴿كُلِّ وَادࣲ﴾: كلِّ فَنٍّ مِن فُنُونِ الكَذِبِ.\n\n﴿يَهِيمُونَ﴾: يخُوضُونَ."],[227,227,"﴿يَنقَلِبُونَ﴾: يَرْجِعُونَ إليهِ."]]);
QTF("gharib",27,[[1,1,"﴿طسٓ﴾: تَقَدَّمَ الكلامُ على مِثْلِه أوَّلَ سُورَةِ البقرةِ."],[4,4,"﴿يَعۡمَهُونَ﴾: يَتَرَدَّدُونَ ويَتَحَيَّرُونَ."],[7,7,"﴿ءَانَسۡتُ﴾: أبْصَرْتُ ما يُؤْنِسُ.\n\n﴿بِشِهَابࣲ قَبَسࣲ﴾: بِشُعْلَةِ نارٍ مَقْبُوسَةٍ، أي: مأخُوذَةٍ.\n\n﴿تَصۡطَلُونَ﴾: تَسْتَدْفِئُونَ بِها."],[8,8,"﴿بُورِكَ مَن فِي ٱلنَّارِ﴾: أي: إنّ اللهَ باركَ مَن فِي النّارِ ومَن حَولَها مِنَ الملائِكَةِ."],[10,10,"﴿تَهۡتَزُّ﴾: تَتَحَرَّكُ بخِفَّةٍ.\n\n﴿جَآنࣱّ﴾: حَيَّةٌ خَفِيفَةٌ في سُرْعَةِ حَرَكَتِها.\n\n﴿وَلَّىٰ﴾: هرَبَ.\n\n﴿وَلَمۡ يُعَقِّبۡ﴾: لم يَرْجِعْ."],[12,12,"﴿فِي جَيۡبِكَ﴾: في فَتْحَةِ قَمِيصِكَ الَّتي يُدْخَلُ منها الرَّأسُ.\n\n﴿مِنۡ غَيۡرِ سُوٓءࣲ﴾: مِن غَيرِ بَرَصٍ ولا مَرَضٍ.\n\n﴿فِي تِسۡعِ ءَايَـٰتٍ﴾: وهي: اليدُ، والعَصا، والسِّنونَ، ونَقْصُ الثَّمراتِ، والطُّوفانُ، والجَرادُ، والقُمَّلُ، والضَّفادِعُ، والدَّمُ."],[13,13,"﴿مُبۡصِرَةࣰ﴾: واضِحَةً هادِيةً."],[14,14,"﴿وَجَحَدُواْ بِهَا﴾: أنْكَرُوها بألْسِنَتِهِم.\n\n﴿وَعُلُوࣰّا﴾: تَرَفُّعًا واسْتِكْبارًا عَنِ الإيمانِ بِها."],[16,16,"﴿وَوَرِثَ سُلَيۡمَـٰنُ دَاوُۥدَ﴾: أي: نُبوَّتَه وعِلْمَه ومُلْكَه.\n\n﴿مَنطِقَ ٱلطَّيۡرِ﴾: فَهْمَ أغْراضِه كلِّها مِن أصْواتِه.\n\n﴿وَأُوتِينَا﴾: وأُعْطِينا."],[17,17,"﴿وَحُشِرَ﴾: وجُمِعَ.\n\n﴿فَهُمۡ يُوزَعُونَ﴾: فهم يُكَفُّونَ عَنِ التَّفرُّقِ، فكان على كُلِّ جِنْسٍ مَن يَرُدُّ أوَّلَهم على آخِرِهم كي يقِفُوا ويسِيرُوا مُنْتَظِمِينَ."],[18,18,"﴿لَا يَحۡطِمَنَّكُمۡ﴾: أي: لا تُمَكِّنوهُم مِن قَتْلِكُم وإهْلاكِكُم."],[19,19,"﴿أَوۡزِعۡنِيٓ﴾: ألْهِمْنِي ووَفِّقْنِي."],[21,21,"﴿بِسُلۡطَـٰنࣲ مُّبِينࣲ﴾: بِحُجَّةٍ تُبيِّنُ عُذْرَه في غِيابِه."],[22,22,"﴿أَحَطتُ﴾: عَلِمْتُ الأمرَ مِن جَميعِ جِهاتِهِ.\n\n﴿وَجِئۡتُكَ﴾: بَلَدٍ باليمنِ سُمِّي باسْمِ «سَبأِ بنِ يَشْجُبَ»،ويقَعُ شَرْقَ صَنْعاء ويُسَمّى الآنَ «مَأْرِبًا»."],[23,23,"﴿وَلَهَا عَرۡشٌ﴾: أي: سَرِيرُ المُلْكِ، تَجْلِسُ عليه لإدارةِ مُلْكِها."],[24,24,"﴿فَصَدَّهُمۡ﴾: فَصَرَفَهُم."],[25,25,"﴿ٱلۡخَبۡءَ﴾: المخْبوُءَ المسْتُورَ."],[27,27,"﴿سَنَنظُرُ﴾: أي: سَنَتَأَمَّلُ."],[28,28,"﴿تَوَلَّ عَنۡهُمۡ﴾: تَنَحَّ عَنْهُم."],[31,31,"﴿أَلَّا تَعۡلُواْ﴾: ألّا تَتَكَبَّرُوا عليَّ."],[32,32,"﴿يَـٰٓأَيُّهَا ٱلۡمَلَؤُاْ﴾: يا أيُّها الأشْرافُ.\n\n﴿أَفۡتُونِي﴾: أشِيرُوا عَليَّ.\n\n﴿قَاطِعَةً أَمۡرًا﴾: مُبْرِمَةً أمْرًا.\n\n﴿تَشۡهَدُونِ﴾: تَحْضُرُونِ."],[33,33,"﴿وَأُوْلُواْ بَأۡسࣲ﴾: أصْحابُ نَجْدةٍ وبَلاءٍ في الحرْبِ."],[35,35,"﴿فَنَاظِرَةُۢ﴾: فمُنتَظِرةٌ."],[37,37,"﴿لَّا قِبَلَ لَهُم بِهَا﴾: لا طاقَةَ لَهُم بِمُقاوَمَتِها.\n\n﴿صَـٰغِرُونَ﴾: ذَلِيلُونَ مُهانُونَ."],[39,39,"﴿عِفۡرِيتࣱ﴾: مارِدٌ قويٌّ شَدِيدٌ."],[40,40,"﴿أَن يَرۡتَدَّ﴾: أن يَرْجِعَ.\n\n﴿طَرۡفُكَ﴾: نَظَرُكَ.\n\n﴿لِيَبۡلُوَنِيٓ﴾: لِيَخْتَبِرَنِي.\n\n﴿أَمۡ أَكۡفُرُ﴾: أي: بِتَرْكِ شُكْرِ النِّعْمةِ."],[41,41,"﴿نَكِّرُواْ﴾: غيِّرُوا."],[42,42,"﴿وَأُوتِينَا ٱلۡعِلۡمَ﴾: وأُعْطِينا العِلْمَ بِاللهِ وبِقُدْرَتِه."],[44,44,"﴿ٱلصَّرۡحَ﴾: القَصْرَ.\n\n﴿حَسِبَتۡهُ لُجَّةࣰ﴾: ظنَّتْهُ ماءً تتردَّدُ أمْواجُه.\n\n﴿مُّمَرَّدࣱ﴾: أمْلَسُ.\n\n﴿مِّن قَوَارِيرَ﴾: مِن زُجاجٍ صافٍ شَفّافٍ."],[45,45,"﴿يَخۡتَصِمُونَ﴾: يَتَنازَعُونَ."],[46,46,"﴿بِٱلسَّيِّئَةِ قَبۡلَ ٱلۡحَسَنَةِ﴾: أي: بالكُفْرِ قَبْلَ الإيمانِ."],[47,47,"﴿ٱطَّيَّرۡنَا بِكَ﴾: تَشاءَمْنا بِكَ، لأنّنا أُصِبْنا بالشَّدائِدِ.\n\n﴿طَـٰٓئِرُكُمۡ﴾: شُؤْمُكُم.\n\n﴿عِندَ ٱللَّهِ﴾: أي: قَدَّرَهُ اللهُ عَلَيكُم.\n\n﴿تُفۡتَنُونَ﴾: تُمتَحَنُونَ وتُخْتَبرُونَ."],[48,48,"﴿رَهۡطࣲ﴾: رِجالٍ مِن أبْناءِ الأشْرافِ."],[49,49,"﴿تَقَاسَمُواْ بِٱللَّهِ﴾: تحالَفُوا باللهِ.\n\n﴿لَنُبَيِّتَنَّهُۥ﴾: لَنَأْتِيَنَّهُ بَغْتَةً في الليلِ، فَنْقتُلَهُ.\n\n﴿مَا شَهِدۡنَا﴾: ما حَضَرْنا."],[50,50,"﴿وَمَكَرُواْ﴾: دبَّرُوا الشَّرَّ بِحِيلَةٍ."],[51,51,"﴿دَمَّرۡنَـٰهُمۡ﴾: أهْلكْناهُم."],[52,52,"﴿خَاوِيَةَۢ﴾: خالِيةً خَرِبةً."],[56,56,"﴿يَتَطَهَّرُونَ﴾: يَتَنَزَّهُونَ مِن إتْيانِ الرِّجالِ."],[57,57,"﴿مِنَ ٱلۡغَـٰبِرِينَ﴾: مِنَ الباقِينَ في العَذابِ والهَلاكِ."],[59,59,"﴿ٱصۡطَفَىٰٓ﴾: اخْتارَ."],[60,60,"﴿حَدَآئِقَ ذَاتَ بَهۡجَةࣲ﴾: بَساتِينَ ذاتَ مَنظَرٍ حَسَنٍ.\n\n﴿يَعۡدِلُونَ﴾: يَنْحَرِفُونَ عَن طَرِيقِ الحقِّ إلى طَرِيقِ الباطِلِ وهو الشِّركُ."],[61,61,"﴿قَرَارࣰا﴾: مُسْتَقَرًّا.\n\n﴿خِلَـٰلَهَآ﴾: وسَطَها.\n\n﴿رَوَ ٰ⁠سِيَ﴾: جِبالًا ثَوابِتَ.\n\n﴿ٱلۡبَحۡرَيۡنِ﴾: العَذْبِ والمِلْحِ.\n\n﴿حَاجِزًا﴾: فاصِلًا يَمْنَعُ اخْتِلاطَهُما."],[62,62,"﴿ٱلۡمُضۡطَرَّ﴾: الَّذي أصابَه بَلاءٌ وشِدَّةٌ.\n\n﴿خُلَفَآءَ﴾: أي: تَخْلُفُونَ مَن سَبَقَكُم في الأرضِ."],[63,63,"﴿بُشۡرَۢا﴾: تُبَشِّرُ بالمَطَرِ."],[64,64,"﴿يَبۡدَؤُاْ ٱلۡخَلۡقَ﴾: يُنْشِئُه.\n\n﴿بُرۡهَـٰنَكُمۡ﴾: حُجَّتَكُم."],[65,65,"﴿أَيَّانَ يُبۡعَثُونَ﴾: مَتى يُبْعثُونَ مِن قُبُورِهِم."],[66,66,"﴿بَلِ ٱدَّ ٰ⁠رَكَ عِلۡمُهُمۡ فِي ٱلۡـَٔاخِرَةِ﴾: بَلْ تَكامَلَ علمُهُم بِها عِنْدَما بُعِثُوا يومَ القيامةِ.\n\n﴿فِي شَكࣲّ مِّنۡهَا﴾: أي: مِنَ الآخِرةِ في الدُّنيا.\n\n﴿عَمُونَ﴾: أي: غافِلُونَ، فَقُلُوبُهُم عَمْياءُ."],[67,67,"﴿لَمُخۡرَجُونَ﴾: لمَبْعُوثُونَ مِن قُبُورِنا."],[68,68,"﴿أَسَـٰطِيرُ ٱلۡأَوَّلِينَ﴾: الأكاذيبُ الَّتي كَتَبها المتقدِّمُونَ."],[70,70,"﴿ضَيۡقࣲ﴾: حَرَجٍ وضِيقِ صَدْرٍ."],[72,72,"﴿رَدِفَ لَكُم﴾: لَحِقَكُم، أو اقْتَرَبَ لَكُم."],[74,74,"﴿مَا تُكِنُّ﴾: ما تُخْفِي.\n\n﴿وَمَا يُعۡلِنُونَ﴾: وما يُظْهِرُونَ."],[75,75,"﴿غَآئِبَةࣲ﴾: هو ما يَغيبُ ويَخْفى عَلى الخَلْقِ.\n\n﴿مُّبِينٍ﴾: واضِحٍ."],[80,80,"﴿مُدۡبِرِينَ﴾: مُعْرِضِينَ."],[82,82,"﴿وَقَعَ ٱلۡقَوۡلُ﴾: أي: وجَبَ العَذابُ.\n\n﴿دَآبَّةࣰ﴾: هي مِن أشْراطِ السّاعةِ الكُبْرى.\n\n﴿تُكَلِّمُهُمۡ﴾: تُحدِّثُهُم.\n\n﴿لَا يُوقِنُونَ﴾: لا يُصَدِّقُونَ."],[83,83,"﴿نَحۡشُرُ﴾: نَجْمَعُ.\n\n﴿فَهُمۡ يُوزَعُونَ﴾: فهم يُكَفُّونَ عَنِ التَّفَرُّقِ، فكان على كُلِّ جِنْسٍ مَن يَرُدُّ أوَّلَهم على آخِرِهِم ثُمَّ يُساقُون جميعًا."],[87,87,"﴿ٱلصُّورِ﴾: القَرْنِ الَّذي يُنفَخُ فيهِ للبَعْثِ.\n\n﴿فَفَزِعَ﴾: خافَ خَوْفًا شَدِيدًا مِن هَوْلِ النَّفخَةِ.\n\n﴿دَ ٰ⁠خِرِينَ﴾: صاغِرِينَ مُطِيعِينَ."],[88,88,"﴿تَحۡسَبُهَا جَامِدَةࣰ﴾: تَظُنُّها ثابِتةً في أماكِنِها.\n\n﴿مَرَّ ٱلسَّحَابِ﴾: مِثْلَ السَّحابِ الَّذي تُسَيِّرُه الرِّياحُ."],[90,90,"﴿فَكُبَّتۡ وُجُوهُهُمۡ فِي ٱلنَّارِ﴾: أي: أُلقُوا على وُجُوهِهِم فِيها."],[91,91,"﴿حَرَّمَهَا﴾: جَعَلها حَرَمًا آمِنًا لا يُسْفَكُ فيها دَمٌ."]]);
QTF("gharib",28,[[3,3,"﴿نَّبَإِ مُوسَىٰ﴾: خَبَرِ مُوسى.\n\n﴿بِٱلۡحَقِّ﴾: بالصِّدْقِ."],[4,4,"﴿عَلَا﴾: تَجَبَّرَ وتكَبَّرَ.\n\n﴿شِيَعࣰا﴾: طَوائِفَ مُتَفَرِّقةً.\n\n﴿وَيَسۡتَحۡيِۦ نِسَآءَهُمۡ﴾: أي: يَسْتَبْقِيهِنَّ للخِدْمَةِ والامْتِهانِ."],[5,5,"﴿أَن نَّمُنَّ﴾: أن نَتَفَضَّلَ.\n\n﴿أَئِمَّةࣰ﴾: قادَةً في الخيرِ.\n\n﴿ٱلۡوَ ٰ⁠رِثِينَ﴾: أي: ورِثُوا أرضَ مِصْرَ بَعْدَ هَلاكِ فِرْعَونَ وقَومِهِ."],[6,6,"﴿وَنُمَكِّنَ﴾: ونُثَبِّتَ لهم.\n\n﴿يَحۡذَرُونَ﴾: يَخافُونَ."],[7,7,"﴿وَأَوۡحَيۡنَآ﴾: وألْهَمْنا.\n\n﴿فِي ٱلۡيَمِّ﴾: في نَهْرِ النِّيلِ."],[8,8,"﴿فَٱلۡتَقَطَهُۥٓ﴾: فأخَذَهُ.\n\n﴿لِيَكُونَ﴾: أي: في المآلِ والعاقِبَةِ."],[9,9,"﴿قُرَّتُ عَيۡنࣲ﴾: مَصْدرُ سُرورٍ وسَعادةٍ تَقَرُّ العَينُ بِهِ."],[10,10,"﴿فُؤَادُ﴾: قَلْبُ.\n\n﴿فَـٰرِغًا﴾: خالِيًا مِن كلِّ شَيءٍ، ليمْلَأَه هَمُّ مُوسى وذِكْرُه.\n\n﴿لَتُبۡدِي بِهِۦ﴾: لَتُظْهِرُ أنَّ مُوسى ابْنُها.\n\n﴿أَن رَّبَطۡنَا﴾: أن ثبَّتناها بالصَّبرِ والثَّباتِ."],[11,11,"﴿قُصِّيهِ﴾: اتَّبعِي أثَرَ مُوسى وتَعَرَّفي خَبَرَه.\n\n﴿عَن جُنُبࣲ﴾: عن بُعدٍ."],[12,12,"﴿وَحَرَّمۡنَا عَلَيۡهِ﴾: أي: مَنَعْناهُ مِن قَبُولِ الرَّضاعَةِ.\n\n﴿يَكۡفُلُونَهُۥ﴾: يقُومُونَ بإرْضاعِه وتَرْبِيَتِهِ.\n\n﴿نَـٰصِحُونَ﴾: مُشْفِقُونَ."],[13,13,"﴿كَيۡ تَقَرَّ عَيۡنُهَا﴾: كَي تُسَرَّ أمُّ مُوسى بِسَلامَةِ ولَدِها ورُجُوعِهِ إليها."],[14,14,"﴿أَشُدَّهُۥ وَٱسۡتَوَىٰٓ﴾: أي: مُنْتَهى قُوَّتِه، وتكامَلَ عَقْلُه.\n\n﴿ءَاتَيۡنَـٰهُ حُكۡمࣰا وَعِلۡمࣰا﴾: أعْطَيناه حِكْمَةً وفَهْمًا ومَعْرِفَةً بالدِّينِ."],[15,15,"﴿عَلَىٰ حِينِ غَفۡلَةࣲ﴾: وقْتِ غَفْلَةِ أهْلِها.\n\n﴿فَٱسۡتَغَـٰثَهُ﴾: فَطَلَبَ الغَوثَ والنَّصْرَ مِن مُوسى عَلَيهِ الصَّلاةُ والسَّلامُ.\n\n﴿مِن شِيعَتِهِۦ﴾: أي: مِن بَنِي إسْرائِيلَ قَومِ مُوسى عَلَيهِ الصَّلاةُ والسَّلامُ.\n\n﴿ٱلَّذِي مِنۡ عَدُوِّهِۦ﴾: أي: القِبْطِيِّ الَّذي كان مِن قَومِ فِرْعَونَ.\n\n﴿فَوَكَزَهُۥ﴾: ضَرَبَه مُوسى بجُمْعِ كَفِّه.\n\n﴿فَقَضَىٰ عَلَيۡهِ﴾: قَتَلَه."],[17,17,"﴿ظَهِيرࣰا﴾: مُعِينًا."],[18,18,"﴿يَتَرَقَّبُ﴾: يَتَوَقَّعُ المكْرُوهَ ويُراقِبُ ما يَحْدُثُ.\n\n﴿يَسۡتَصۡرِخُهُۥ﴾: يَطْلُبُ مِنهُ النَّصْرَ.\n\n﴿لَغَوِيࣱّ﴾: لَشَدِيدُ الضَّلالِ وسُوءِ النَّظرِ."],[19,19,"﴿أَن يَبۡطِشَ﴾: أن يَأْخُذَ بقوَّةٍ وعُنْفٍ."],[20,20,"﴿أَقۡصَا ٱلۡمَدِينَةِ﴾: آخِرِ المدينةِ.\n\n﴿ٱلۡمَلَأَ﴾: أشْرافَ القَومِ.\n\n﴿يَأۡتَمِرُونَ﴾: يَتَشاورُونَ في شَأْنِكَ.\n\n﴿ٱلنَّـٰصِحِينَ﴾: المُشْفِقِينَ."],[22,22,"﴿تِلۡقَآءَ مَدۡيَنَ﴾: جِهَةَ مَدْيَنَ.\n\n﴿سَوَآءَ ٱلسَّبِيلِ﴾: أي: الطَّرِيقَ المُسْتَويَ إلى مَدْيَنَ."],[23,23,"﴿وَرَدَ﴾: بَلَغَ.\n\n﴿أُمَّةࣰ﴾: جَماعةً.\n\n﴿تَذُودَانِ﴾: تَحبِسانِ غَنَمَهُما عَنِ الماءِ.\n\n﴿مَا خَطۡبُكُمَا﴾: ما شَأْنُكما؟\n\n﴿يُصۡدِرَ ٱلرِّعَآءُ﴾: يَنْصَرِفَ الرُّعاةُ بِمَواشِيهِم عَنِ الماءِ."],[24,24,"﴿تَوَلَّىٰٓ إِلَى ٱلظِّلِّ﴾: رَجَعَ إليه."],[27,27,"﴿تَأۡجُرَنِي﴾: تَكُونَ لي أجِيرًا في رَعْيِ الغَنَمِ.\n\n﴿حِجَجࣲ﴾: سِنِينَ."],[28,28,"﴿أَيَّمَا ٱلۡأَجَلَيۡنِ﴾: أيَّ المُدَّتَينِ.\n\n﴿قَضَيۡتُ﴾: وفَّيتُ به وأتْمَمْتُه.\n\n﴿فَلَا عُدۡوَ ٰ⁠نَعَلَيَّ﴾: لا اعْتِداءَ ولا ظُلْمَ عليّ بالمطالَبَةِ بأكْثَرَ مِنه.\n\n﴿وَكِيلࣱ﴾: شاهِدٌ وحَفِيظٌ."],[29,29,"﴿ٱلۡأَجَلَ﴾: المُدَّةَ المُتَّفَقَ عَلَيها وهي عَشْرُ سِنِينَ.\n\n﴿ءَانَسَ﴾: أبصَرَ ما يُؤْنِسُ.\n\n﴿جَذۡوَةࣲ﴾: جَمْرَةٍ وشُعْلَةٍ.\n\n﴿تَصۡطَلُونَ﴾: تَسْتَدْفِئُونَ بِها."],[30,30,"﴿شَـٰطِيِٕ﴾: جانِبِ.\n\n﴿ٱلۡبُقۡعَةِ﴾: القِطْعَةِ مِنَ الأرْضِ."],[31,31,"﴿تَهۡتَزُّ﴾: تتحرَّكُ بخِفَّةٍ.\n\n﴿جَآنࣱّ﴾: حَيَّةٌ خَفِيفَةٌ في سُرْعَةِ حرَكَتِها.\n\n﴿وَلَّىٰ﴾: هَرَبَ.\n\n﴿وَلَمۡ يُعَقِّبۡ﴾: لم يَرْجِعْ.\n\n﴿أَقۡبِلۡ﴾: تَقَدَّمْ."],[32,32,"﴿ٱسۡلُكۡ﴾: أدْخِلْ.\n\n﴿فِي جَيۡبِكَ﴾: في فَتْحَةِ قَمِيصِكَ الَّتِي يُدْخَلُ مِنها الرَّأسُ.\n\n﴿مِنۡ غَيۡرِ سُوٓءࣲ﴾: مِن غَيرِ مَرَضٍ ولا بَرَصٍ.\n\n﴿جَنَاحَكَ﴾: يَدَكَ.\n\n﴿مِنَ ٱلرَّهۡبِ﴾: لِتَأْمَنَ مِنَ الخَوْفِ.\n\n﴿وَمَلَإِيْهِۦٓ﴾: أشْرافِ قومهِ."],[34,34,"﴿رِدۡءࣰا﴾: مُعِينًا."],[35,35,"﴿سَنَشُدُّ عَضُدَكَ﴾: سَنُقَوِّيكَ ونُعِينُكَ.\n\n﴿سُلۡطَـٰنࣰا﴾: حُجَّةً أو مَهابَةً في قُلُوبِ الأعْداءِ."],[37,37,"﴿عَـٰقِبَةُ ٱلدَّارِ﴾: العاقِبةُ المحْمُودَةُ في الدّارِ الآخِرَةِ."],[38,38,"﴿ٱلۡمَلَأُ﴾: الأشْرافُ مِن قَومِه.\n\n﴿فَأَوۡقِدۡ﴾: فَأَشْعِلْ.\n\n﴿صَرۡحࣰا﴾: قَصْرًا.\n\n﴿أَطَّلِعُ﴾: أنظُرُ."],[40,40,"﴿فَنَبَذۡنَـٰهُمۡ فِي ٱلۡيَمِّ﴾: فَطَرَحْناهُمْ في البَحْرِ، فَأَغْرَقَنْاهُم."],[42,42,"﴿مِّنَ ٱلۡمَقۡبُوحِينَ﴾: مِنَ المذْمُومِينَ والمُبْعَدِينَ مِن كُلِّ خَيْرٍ."],[43,43,"﴿ٱلۡقُرُونَ ٱلۡأُولَىٰ﴾: الأُمَمَ الماضِيَةَ."],[44,44,"﴿قَضَيۡنَآ إِلَىٰ مُوسَى﴾: عَهِدْنا إليهِ وكَلَّفْناهُ.\n\n﴿ٱلۡأَمۡرَ﴾: أي: أمْرَ الرِّسالَةِ.\n\n﴿مِنَ ٱلشَّـٰهِدِينَ﴾: مِنَ الحاضِرِينَ في ذلك الوقتِ."],[45,45,"﴿أَنشَأۡنَا﴾: خَلَقْنا.\n\n﴿قُرُونࣰا﴾: أُمَمًا.\n\n﴿فَتَطَاوَلَ عَلَيۡهِمُ ٱلۡعُمُرُ﴾: امْتَدَّ عَلَيهِمُ الزَّمانُ.\n\n﴿ثَاوِيࣰا﴾: مُقِيمًا."],[46,46,"﴿ٱلطُّورِ﴾: جَبَلِ طُورِ سَيناءَ."],[47,47,"﴿بِمَا قَدَّمَتۡ أَيۡدِيهِمۡ﴾: أي: بِسَبَبِ أعْمالِهِم السَّيِّئَةِ."],[48,48,"﴿أُوتِيَ﴾: أُعْطِيَ.\n\n﴿سِحۡرَانِ﴾: أي: التَّوراةُ والقرآنُ حَسَبَ زَعْمِهِم، أو هُما ذَوا سِحْرٍ، أي: مُوسى ومُحَمَّدٌ عليهما الصَّلاةُ والسَّلامُ حَسَبَ زَعْمِهِم."],[51,51,"﴿وَصَّلۡنَا لَهُمُ ٱلۡقَوۡلَ﴾: أي: نَزَّلْنا عَلَيهِم القرآنَ يَتْبَعُ بَعْضُهُ بَعْضًا."],[53,53,"﴿مُسۡلِمِينَ﴾: أي: مُخْلِصِينَ للهِ بالتوحيدِ."],[54,54,"﴿وَيَدۡرَءُونَ﴾: يَدْفَعُونَ."],[55,55,"﴿ٱللَّغۡوَ﴾: السّاقِطَ مِنَ القَوْلِ.\n\n﴿لَا نَبۡتَغِي﴾: لا نُرِيدُ ولا نُحِبُّ."],[56,56,"﴿لَا تَهۡدِي﴾: أي: هِدايةَ توفِيقٍ."],[57,57,"﴿نُتَخَطَّفۡ﴾: نُخْتلَسْ ونُسْتَلَبْ قَتْلًا وأسْرًا.\n\n﴿أَوَ لَمۡ نُمَكِّن لَّهُمۡ حَرَمًا ءَامِنࣰا﴾: أولم نَجْعَلْهُم يَنْعَمُونَ بالأمْنِ والتَّمكِينِ في البلدِ الحرامِ.\n\n﴿يُجۡبَىٰٓ إِلَيۡهِ﴾: يُجْلَبُ إليه."],[58,58,"﴿وَكَمۡ﴾: كَثِيرًا.\n\n﴿بَطِرَتۡ مَعِيشَتَهَا﴾: طَغَتْ وكَفَرتْ نِعْمَةَ العَيشِ بالرَّغَدِ.\n\n﴿ٱلۡوَ ٰ⁠رِثِينَ﴾: أي: للعِباد بَعْدَ إهْلاكِهم."],[59,59,"﴿فِيٓ أُمِّهَا﴾: وهي مَكَّة المكَرَّمةُ، وتُعْرَفُ بأمِّ القُرى."],[60,60,"﴿وَمَآ أُوتِيتُم﴾: وما أُعْطِيتُم."],[61,61,"﴿وَعۡدًا حَسَنࣰا﴾: أي: بِدُخُولِ الجنَّةِ.\n\n﴿مِنَ ٱلۡمُحۡضَرِينَ﴾: أي: مِمَّن أُحْضِرُوا لِلْحِسابِ والعَذابِ."],[63,63,"﴿حَقَّ عَلَيۡهِمُ ٱلۡقَوۡلُ﴾: وجَبَ لهم العَذابُ.\n\n﴿أَغۡوَيۡنَآ﴾: أضْلَلْنا.\n\n﴿تَبَرَّأۡنَآ﴾: أي: مِن عِبادتِهم إيّانا."],[66,66,"﴿فَعَمِيَتۡ عَلَيۡهِمُ ٱلۡأَنۢبَآءُ﴾: فَخَفِيَتْ عَلَيهِمُ الأَخْبارُ الَّتي كانُوا يَحْتَجُّونَ بِها."],[68,68,"﴿ٱلۡخِيَرَةُ﴾: الاخْتِيارُ."],[69,69,"﴿مَا تُكِنُّ﴾: ما تُخْفِي."],[70,70,"﴿ٱلۡأُولَىٰ﴾: الحَياةِ الأُولى هي الدُّنيا.\n\n﴿وَٱلۡـَٔاخِرَةِ﴾: الدّارِ الآخرةِ."],[71,71,"﴿أَرَءَيۡتُمۡ﴾: أي: أخْبِرُونِي.\n\n﴿سَرۡمَدًا﴾: دائِمًا مُسْتَمِرًّا.\n\n﴿بِضِيَآءٍ﴾: بنُورٍ."],[72,72,"﴿تَسۡكُنُونَ فِيهِ﴾: تَسْتَقِرُّونَ فِيه مِنَ التَّعَبِ."],[73,73,"﴿لِتَسۡكُنُواْ فِيهِ﴾: لِتَسْتَقِرُّوا في اللَّيلِ وتَرْتاحَ أبْدانُكُم.\n\n﴿لِتَبۡتَغُواْ مِن فَضۡلِهِۦ﴾: لِتطْلُبُوا وتَلْتَمِسُوا مِن رِزْقِهِ."],[75,75,"﴿وَنَزَعۡنَا﴾: وأَخْرَجْنا.\n\n﴿شَهِيدࣰا﴾: وهو نَبِيُّ كُلِّ أُمَّةٍ.\n\n﴿هَاتُواْ بُرۡهَـٰنَكُمۡ﴾: أحْضِرُوا حُجَّتَكُم.\n\n﴿يَفۡتَرُونَ﴾: يَخْتَلِقُونَ."],[76,76,"﴿فَبَغَىٰ عَلَيۡهِمۡ﴾: تَكَبَّرَ عَلَيهِم.\n\n﴿وَءَاتَيۡنَـٰهُ﴾: وأعْطَيناهُ.\n\n﴿ٱلۡكُنُوزِ﴾: الأمْوالِ المدَّخَرَةِ في الخَزائِنِ.\n\n﴿لَتَنُوٓأُ بِٱلۡعُصۡبَةِ﴾: لَتُثْقِلُ الجَماعَةَ الكَثِيرَةَ.\n\n﴿أُوْلِي ٱلۡقُوَّةِ﴾: أصْحابِ القُوَّةِ، الأقْوِياءِ.\n\n﴿لَا تَفۡرَحۡ﴾: لا تَبْطَرْ فَرَحًا بِكَثْرَةِ المالِ."],[77,77,"﴿وَٱبۡتَغِ﴾: والتَمِسْ.\n\n﴿ءَاتَىٰكَ﴾: أعْطاكَ.\n\n﴿وَلَا تَنسَ نَصِيبَكَ﴾: ولا تَترُكْ حَظَّكَ مِنَ الدُّنيا.\n\n﴿وَلَا تَبۡغِ﴾: ولا تَلْتمِسْ."],[78,78,"﴿أُوتِيتُهُۥ﴾: أُعْطِيتُ هَذا المالَ.\n\n﴿مِنَ ٱلۡقُرُونِ﴾: مِنَ الأُمَمِ."],[79,79,"﴿أُوتِيَ﴾: أُعطِيَ.\n\n﴿لَذُو حَظٍّ﴾: لَصاحِبُ نَصِيبٍ."],[80,80,"﴿أُوتُواْ﴾: أُعطُوا.\n\n﴿وَيۡلَكُمۡ﴾: زَجْرٌ لهم عَنْ هَذا التَّمَنِّي.\n\n﴿وَلَا يُلَقَّىٰهَآ﴾: أي: لا يُعطى تِلْكَ الخَصْلَةَ أوِ الجنَّةَ."],[81,81,"﴿فَخَسَفۡنَا بِهِۦ﴾: أي: فَجَعَلْنا الأرضَ تَبْتَلِعُهُ وهو حَيٌّ.\n\n﴿فِئَةࣲ﴾: جَماعَةٍ."],[82,82,"﴿وَيۡكَأَنَّ﴾: كَلِمَةُ تَندُّمٍ وتَفَجُّعٍ، أي: ألمْ تَعْلَمْ.\n\n﴿يَبۡسُطُ﴾: يُوسِّعُ.\n\n﴿وَيَقۡدِرُ﴾: يُضَيِّقُ.\n\n﴿مَّنَّ﴾: أنْعَمَ.\n\n﴿وَيۡكَأَنَّهُۥ﴾: ألَمْ تَعْلَمْ."],[83,83,"﴿عُلُوࣰّا﴾: تَكَبُّرًا.\n\n﴿وَٱلۡعَـٰقِبَةُ﴾: أي: العاقِبةُ المحْمُودَةُ، وهي الجنَّةُ."],[85,85,"﴿فَرَضَ﴾: أي: أنْزَلَ وأَوْجَبَ عَلَيكَ العَمَلَ بِمُقْتَضاه.\n\n﴿لَرَآدُّكَ﴾: لَمُرْجِعُكَ.\n\n﴿إِلَىٰ مَعَادࣲ﴾: المرادُ بِهِ هُنا «مَكَّةُ».\n\n﴿ضَلَـٰلࣲ مُّبِينࣲ﴾: انحِرافٍ واضِحٍ."],[86,86,"﴿تَرۡجُوٓاْ﴾: تَتَوَقَّعُ وتَنْتَظِرُ.\n\n﴿أَن يُلۡقَىٰٓ﴾: أي: أن يُنزَّلَ.\n\n﴿ظَهِيرࣰا﴾: مُعِينًا."],[87,87,"﴿وَلَا يَصُدُّنَّكَ﴾: ولا يَصْرِفُنَّكَ."],[88,88,"﴿إِلَّا وَجۡهَهُۥ﴾: إلّا إيّاهُ، أو إلّا ما أُرِيدَ به وجْهُه.\n\n﴿ٱلۡحُكۡمُ﴾: القَضاءُ النّافِذُ، يَقْضِي بما شاءَ."]]);
QTF("gharib",29,[[1,1,"﴿الٓمٓ﴾: سَبَقَ الكَلامُ على مِثْلِه في أوَّلِ سورةِ البَقَرةِ."],[2,2,"﴿لَا يُفۡتَنُونَ﴾: لا يُبتَلَونَ."],[4,4,"﴿أَن يَسۡبِقُونَا﴾: أن يُعْجِزُونا ويَفُوتُونا.\n\n﴿سَآءَ﴾: بِئْسَ."],[5,5,"﴿يَرۡجُواْ﴾: يَتَوَقَّعُ ويَطْمَعُ.\n\n﴿أَجَلَ ٱللَّهِ﴾: الوَقْتَ المُعَيَّنَ للبَعْثِ والجَزاءِ."],[6,6,"﴿جَـٰهَدَ﴾: أي: الكُفّارَ ونَفْسَه الأَمّارةَ بالسُّوءِ."],[7,7,"﴿لَنُكَفِّرَنَّ﴾: لَنَمْحُوَنَّ.\n\n﴿وَلَنَجۡزِيَنَّهُمۡ﴾: لَنُثِيبَنَّهم."],[8,8,"﴿وَوَصَّيۡنَا﴾: أي: أمَرْنا.\n\n﴿حُسۡنࣰا﴾: أي: بَرًّا بِهِما وعَطْفًا عَلَيهِما.\n\n﴿جَـٰهَدَاكَ﴾: ألْزَماكَ."],[10,10,"﴿فِتۡنَةَ ٱلنَّاسِ﴾: ابتلاءَهم وتَعْذِيبَهُم"],[12,12,"﴿وَلۡنَحۡمِلۡ﴾: ولْنَتَحَمَّلْ."],[13,13,"﴿أَثۡقَالَهُمۡ﴾: أي: أثْقالَ ذُنُوبِهِم العَظِيمَةَ.\n\n﴿يَفۡتَرُونَ﴾: يَخْتَلِقُونَ."],[14,14,"﴿فَلَبِثَ﴾: مَكَثَ.\n\n﴿ٱلطُّوفَانُ﴾: الماءُ الكَثِيرُ الذي غَمَرهُم مِن جَمِيعِ الجِهاتِ."],[15,15,"﴿ءَايَةࣰ﴾: عِبْرةً عَظِيمةً."],[17,17,"﴿أَوۡثَـٰنࣰا﴾: أصْنامًا.\n\n﴿تَخۡلُقُونَ إِفۡكًا﴾: تَفْتَرُونَ كَذِبًا.\n\n﴿فَٱبۡتَغُواْ﴾: فالتَمِسُوا."],[19,19,"﴿أَوَ لَمۡ يَرَوۡاْ﴾: أوَلم يَعْلَمُوا.\n\n﴿يُبۡدِئُ﴾: يُنشِئُ ابتداءً.\n\n﴿يُعِيدُهُۥٓ﴾: يُعِيدُ الخَلْقَ مِن بَعْدِ فَنائِهِ."],[20,20,"﴿يُنشِئُ﴾: يَخلُقُ.\n\n﴿ٱلنَّشۡأَةَ ٱلۡـَٔاخِرَةَ﴾: أي: نَشْأَةً ثانيةً عِنْدَ البعْثِ."],[21,21,"﴿تُقۡلَبُونَ﴾: تُرجَعُونَ."],[22,22,"﴿بِمُعۡجِزِينَ﴾: بِسابِقِينَ اللهَ."],[23,23,"﴿بِـَٔايَـٰتِ ٱللَّهِ﴾: أي: بالقرآنِ.\n\n﴿وَلِقَآئِهِۦٓ﴾: أي: بالبعثِ بَعْدَ الموتِ."],[24,24,"﴿لَـَٔايَـٰتࣲ﴾: لَأَدِلَّةً واضِحَةً."],[25,25,"﴿أَوۡثَـٰنࣰا﴾: أصْنامًا، أي: اتَّخذتُموها آلِهَةً.\n\n﴿مَّوَدَّةَ بَيۡنِكُمۡ﴾: أي: للتَّوادِّ والتَّواصُل بَيْنَكُم لاجْتِماعِكُم على عِبادَتِها.\n\n﴿يَكۡفُرُ بَعۡضُكُم بِبَعۡضࣲ﴾: أي: يتبرَّأُ بعضُكُم مِن بَعْضٍ.\n\n﴿مَأۡوَىٰكُمُ﴾: مَنزِلُكُم الذي تَأْوُونَ وتَرْجِعُونَ إليهِ."],[26,26,"﴿فَـَٔامَنَ﴾: أي: صَدَّقَ إبراهيمَ عَلَيهِ الصَّلاةُ والسَّلامُ."],[27,27,"﴿وَٱلۡكِتَـٰبَ﴾: أي: الكُتُبَ المنزَّلةَ، مِنَ التَّوراةِ والإنْجِيلِ والزَّبُورِ والقرآنِ.\n\n﴿أَجۡرَهُۥ﴾: أي: ثَوابَه."],[28,28,"﴿ٱلۡفَـٰحِشَةَ﴾: هي إتْيانُهم الرِّجالَ في أدْبارِهِم."],[29,29,"﴿ٱلسَّبِيلَ﴾: أي: الطَّريقَ على المارَّةِ والمسافِرِينَ، بأخْذِ أمْوالِهِم، أو قَتْلِهِم، أو إكْراهِهِم على الفاحِشَةِ.\n\n﴿فِي نَادِيكُمُ﴾: في مَجْلِسِكُم.\n\n﴿ٱلۡمُنكَرَ﴾: وهو كلُّ فِعْلٍ يُنكِره الشَّرْعُ أو العقْلُ كالسُّخْرِيَةِ مِنَ النّاسِ وحَذْفِ المارّةِ."],[31,31,"﴿رُسُلُنَآ﴾: أي: مِنَ الَملائِكَةِ.\n\n﴿هَـٰذِهِ ٱلۡقَرۡيَةِ﴾: هي «سَدُومُ» قَرْيَةُ قَوْمِ لُوطٍ."],[32,32,"﴿مِنَ ٱلۡغَـٰبِرِينَ﴾: مِنَ الباقِينَ في العَذابِ والهَلاكِ."],[33,33,"﴿سِيٓءَ بِهِمۡ﴾: اعْتَراهُ الغَمُّ بِمَجِيئِهِم خَوْفًا عَليهِم مِن قَومِهِ.\n\n﴿وَضَاقَ بِهِمۡذَرۡعࣰا﴾: أي: عَجَزَ عَن تَدْبِيرِ خَلاصِهِم."],[34,34,"﴿رِجۡزࣰا﴾: عَذابًا شَدِيدًا."],[35,35,"﴿مِنۡهَآ﴾: أي: مِن دِيارِ قَومِ لُوطٍ.\n\n﴿ءَايَةَۢ بَيِّنَةࣰ﴾: أي: آثارًا واضِحةً."],[36,36,"﴿وَٱرۡجُواْ﴾: تَوَقّعُوا، أوِ اخْشَوا.\n\n﴿وَلَا تَعۡثَوۡاْ﴾: لا تُفْسدُوا أشدَّ الفَسادِ."],[37,37,"﴿ٱلرَّجۡفَةُ﴾: الزَّلْزَلةُ الشَّدِيدَةُ.\n\n﴿جَـٰثِمِينَ﴾: مَيِّتِينَ بارِكِينَ على رُكَبِهِم."],[38,38,"﴿فَصَدَّهُمۡ﴾: فصَرفَهُم.\n\n﴿ٱلسَّبِيلِ﴾: أي: سَبِيلِ اللهِ المُسْتَقِيمِ.\n\n﴿مُسۡتَبۡصِرِينَ﴾: أي: عُقَلاءَ ذَوِي بَصائِرَ مُتَمَكِّنِينَ مِن مَّعْرِفَةِ الحقِّ."],[39,39,"﴿بِٱلۡبَيِّنَـٰتِ﴾: بالأدِلَّةِ الواضِحةِ.\n\n﴿سَـٰبِقِينَ﴾: فائِتِينَ مِن عَذابِ اللهِ."],[40,40,"﴿حَاصِبࣰا﴾: ريحًا عاصِفًا ترمِيهِم بالحَصْباءِ.\n\n﴿ٱلصَّيۡحَةُ﴾: صَوْتٌ مِنَ السَّماءِ مُهلِكٌ مُرْجِفٌ.\n\n﴿خَسَفۡنَا بِهِ﴾: جَعَلْنا الأرْضَ تبتَلِعُه وهو حَيٌّ."],[41,41,"﴿أَوۡهَنَ ٱلۡبُيُوتِ﴾: أضْعَفَها."],[43,43,"﴿نَضۡرِبُهَا﴾: أي: نُبَيِّنُها.\n\n﴿وَمَا يَعۡقِلُهَآ﴾: وما يَفْهَمُها."],[44,44,"﴿لَـَٔايَةࣰ﴾: لدَلالَةً عَظِيمةً."],[45,45,"﴿ٱلۡفَحۡشَآءِ﴾: أي: كُلِّ عَمَلٍ قَبِيحٍ.\n\n﴿وَٱلۡمُنكَرِ﴾: وهو كلُّ فِعْلٍ يُنكِرُه الشَّرعُ أو العَقْلُ."],[46,46,"﴿أَهۡلَ ٱلۡكِتَـٰبِ﴾: وهُمُ اليَهُودُ والنَّصارى."],[47,47,"﴿وَمَا يَجۡحَدُ﴾: وما يُنكِرُ.\n\n﴿بِـَٔايَـٰتِنَآ﴾: أي: بالقرآنِ وما فيه مِن دَلائِلَ وبَراهِينَ.\n\n﴿ٱلۡكَـٰفِرُونَ﴾: أي: المُكابِرُونَ في كُفْرِهِم."],[48,48,"﴿لَّٱرۡتَابَ﴾: لَشَكَّ.\n\n﴿ٱلۡمُبۡطِلُونَ﴾: هُمْ أهلُ الباطِلِ."],[49,49,"﴿هُوَ ءَايَـٰتُۢ﴾: أي: القرآنُ آياتٌ تُتْلى.\n\n﴿بَيِّنَـٰتࣱ﴾: واضِحاتٌ.\n\n﴿أُوتُواْ﴾: أُعْطُوا.\n\n﴿ٱلظَّـٰلِمُونَ﴾: أي: المُعانِدُونَ الَّذينَ يَعْلَمُونَ الحقَّ ولا يَتَّبعُونَه."],[50,50,"﴿ءَايَـٰتࣱ﴾: أي: مُعْجِزاتٌ حِسِّيَّةٌ تُثْبِتُ صِدْقَهُ.\n\n﴿عِندَ ٱللَّهِ﴾: أي: إنْ شاءَ أنْزَلَها، وإنْ شاءَ مَنَعَها."],[53,53,"﴿أَجَلࣱ مُّسَمࣰّى﴾: وقْتٌ مُعَيَّنٌ لا يَتَقَدَّمُ ولا يَتَأَخَّرُ.\n\n﴿بَغۡتَةࣰ﴾: فُجاءَةً."],[54,54,"﴿لَمُحِيطَةُۢ﴾: أي: سَتُحِيطُ بِهِم في الآخِرَةِ."],[58,58,"﴿لَنُبَوِّئَنَّهُم﴾: لَنُنَزِّلَنَّهُم.\n\n﴿غُرَفࣰا﴾: مَنازِلَ عالِيةً."],[60,60,"﴿وَكَأَيِّن مِّن دَآبَّةࣲ﴾: أي: كَثِيرٌ مِنَ الدَّوابِّ.\n\n﴿لَّا تَحۡمِلُ رِزۡقَهَا﴾: أي: لا تُطِيقُ حَمْلَهُ ولا ادِّخارَهُ."],[61,61,"﴿فَأَنَّىٰ يُؤۡفَكُونَ﴾: فَكَيفَ يُصرَفُونَ عَن تَوحِيدِهِ؟"],[62,62,"﴿يَبۡسُطُ﴾: يُوَسِّعُ.\n\n﴿وَيَقۡدِرُ﴾: يُضَيِّقُ."],[63,63,"﴿مِنۢ بَعۡدِ مَوۡتِهَا﴾: مِن بَعْدِ قَحْطِ الأرْضِ وجَفافِها."],[64,64,"﴿لَهِيَ ٱلۡحَيَوَانُ﴾: لَهِيَ الحَياةُ الدّائِمَةُ الَّتي لا يُنَغِّصُها شَيءٌ."],[65,65,"﴿فِي ٱلۡفُلۡكِ﴾: في السُّفُن"],[67,67,"﴿وَيُتَخَطَّفُ ٱلنَّاسُ﴾: أي: يُسْتَلَبُونَ قَتْلًا وأسْرًا.\n\n﴿أَفَبِٱلۡبَـٰطِلِ﴾: أي: بالشِّركِ."],[68,68,"﴿ٱفۡتَرَىٰ﴾: اخْتَلَقَ.\n\n﴿مَثۡوࣰى﴾: مَسْكَنٌ."],[69,69,"﴿جَـٰهَدُواْ فِينَا﴾: أي: الكُفّارَ والنَّفْسَ والشَّيطانَ.\n\n﴿لَنَهۡدِيَنَّهُمۡ سُبُلَنَا﴾: لَنُرْشِدَنَّهُم طُرُقَنا."]]);
QTF("gharib",30,[[3,3,"﴿أَدۡنَى ٱلۡأَرۡضِ﴾: أقْرَبِ أرْضِ الشّامِ إلى فارِس.\n\n﴿غَلَبِهِمۡ﴾: أي: كَوْنِهِم مَغْلُوبِينَ."],[4,4,"﴿بِضۡعِ سِنِينَ﴾: أي: ما بينَ الثَّلاثَةِ إلى العَشْرَةِ"],[7,7,"﴿ظَـٰهِرࣰا مِّنَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا﴾: فَيَنْظُرُونَ إلى الأسْبابِ الظّاهِرَةِ ولا يَنْظُرُونَ إلى مُسَبِّبِها المتَصَرِّفِ فِيها الَّذي هُوَ اللهُ تَعالى."],[8,8,"﴿أَوَ لَمۡ يَتَفَكَّرُواْ﴾: أوَلَمْ يَتَأَمَّلُوا ويَتَدَبَّرُوا.\n\n﴿أَجَلࣲ مُّسَمࣰّى﴾: وقْتٍ مُقَدَّرٍ هُوَ يومُ القِيامَةِ.\n\n﴿بِلِقَآيِٕ رَبِّهِمۡ﴾: المُرادُ به البَعْثُ بَعْدَ الموتِ."],[9,9,"﴿عَـٰقِبَةُ ٱلَّذِينَ مِن قَبۡلِهِمۡ﴾: أي: مَصِيرُهُم الَّذي انْتهَوا إليهِ.\n\n﴿وَأَثَارُواْ ٱلۡأَرۡضَ﴾: حَرَثُوها للزِّراعَةِ.\n\n﴿وَعَمَرُوهَآ﴾: أي: بالبُنْيانِ والزِّراعَةِ.\n\n﴿بِٱلۡبَيِّنَـٰتِ﴾: بالبَراهِينِ الواضِحةِ، ومنها المُعْجِزاتُ الحِسِّيةُ."],[10,10,"﴿ٱلسُّوٓأَىٰٓ﴾: تَأْنِيثُ «الأسْوأ»، ومعناها: العُقُوبَةُ المتناهِيةُ في السُّوءِ، وهي نارُ جَهَنَّم."],[11,11,"﴿يَبۡدَؤُاْ﴾: يُنْشِئُ ابتِداءً.\n\n﴿يُعِيدُهُۥ﴾: يُعِيدُ الخَلْقَ مِن بَعْدِ فَنائِهِ."],[12,12,"﴿يُبۡلِسُ ٱلۡمُجۡرِمُونَ﴾: يَيْئَسُونَ بانْقِطاعِ حُجَّتِهِم."],[13,13,"﴿مِّن شُرَكَآئِهِمۡ﴾: أي: مِن آلهَتِهِم الَّتي كانُوا يَعْبُدُونَها مِن دُونِ اللهِ."],[14,14,"﴿يَتَفَرَّقُونَ﴾: أي: فَرِيقٌ في الجنَّة، وفَرِيقٌ في السَّعِيرِ."],[15,15,"﴿رَوۡضَةࣲ﴾: المرادُ بِها هُنا «الجنَّةُ».\n\n﴿يُحۡبَرُونَ﴾: يُكَرَّمُونَ ويُنَعَّمُونَ."],[16,16,"﴿وَلِقَآيِٕ ٱلۡـَٔاخِرَةِ﴾: أي: البَعْثِ بَعْدَ الموتِ.\n\n﴿فِي ٱلۡعَذَابِ مُحۡضَرُونَ﴾: مُقيمُونَ فِيهِ."],[17,17,"﴿فَسُبۡحَـٰنَ ٱللَّهِ﴾: أي: فنزِّهُوهُ عمّا لا يَلِيقُ بِه.\n\n﴿حِينَ تُمۡسُونَ﴾: أي: وقْتَ دُخُولِكُم في المساءِ.\n\n﴿وَحِينَ تُصۡبِحُونَ﴾: أي: وقْتَ دُخُولِكَمُ في الصَّباحِ."],[18,18,"﴿وَعَشِيࣰّا﴾: وقْتَ العَشِيِّ، أي: بَعْدَ زَوالِ الشَّمسِ.\n\n﴿وَحِينَ تُظۡهِرُونَ﴾: أي: وقْتَ الظَّهِيَرةِ."],[19,19,"﴿بَعۡدَ مَوۡتِهَا﴾: أي: قَحْطِها وجَفافِها.\n\n﴿تُخۡرَجُونَ﴾: أي: تُبعثُونَ مِن قُبُورِكُم."],[20,20,"﴿تَنتَشِرُونَ﴾: تَتَفَرَّقُونَ."],[21,21,"﴿مِّنۡ أَنفُسِكُمۡ﴾: مِن جِنْسِكُم.\n\n﴿لِّتَسۡكُنُوٓاْ إِلَيۡهَا﴾: لِتألَفُوها وتَطْمئنُّوا إلَيها.\n\n﴿مَّوَدَّةࣰ وَرَحۡمَةً﴾: مَحَبَّةً وشَفَقَةً.\n\n﴿يَتَفَكَّرُونَ﴾: يَتَدَبَّرُونَ."],[22,22,"﴿أَلۡسِنَتِكُمۡ﴾: لُغاتِكُم."],[23,23,"﴿ٱبۡتِغَآؤُكُم﴾: طَلَبُكُم والتِماسُكُم.\n\n﴿مِّن فَضۡلِهِۦٓ﴾: مِن رِزْقِه."],[24,24,"﴿خَوۡفࣰا وَطَمَعࣰا﴾: أي: خَوْفًا مِنَ الصَّواعِقِ وطَمعًا في الغَيثِ.\n\n﴿بَعۡدَ مَوۡتِهَآ﴾: بَعْدَ قَحْطِها وجَفافِها."],[25,25,"﴿بِأَمۡرِهِۦ﴾: بِإرادَتِه وقُدْرَتِهِ.\n\n﴿تَخۡرُجُونَ﴾: أي: مِن قُبُورِكُم أحْياءً."],[26,26,"﴿لَّهُۥ قَـٰنِتُونَ﴾: مُنْقادُونَ لإرادَتِه."],[27,27,"﴿يَبۡدَؤُاْ﴾: يُنْشِئُ.\n\n﴿أَهۡوَنُ﴾: هيِّنٌ ويَسِيرُ.\n\n﴿ٱلۡمَثَلُ ٱلۡأَعۡلَىٰ﴾: الوصْفُ الأَعْلى."],[28,28,"﴿مَلَكَتۡ أَيۡمَـٰنُكُم﴾: أي: العبِيدُ والإماءُ.\n\n﴿كَخِيفَتِكُمۡ أَنفُسَكُمۡ﴾: أي: كَما تَخافُونَ الأحْرارَ المُشابِهِينَ لَكُم في الحرِّيَّةِ وتَمَلُّكِ الأمْوالِ."],[30,30,"﴿فَأَقِمۡ وَجۡهَكَ لِلدِّينِ﴾: أي: اسْتَقِمْ واسْتَمِر عَلى دِينِ الإسْلامِ.\n\n﴿حَنِيفࣰا﴾: مائِلًا إليه مُسْتَقِيمًا عَلِيهِ، غَيْرَ مُلْتَفِتٍ إلى غَيْرِه مِنَ الأدْيانِ الباطِلَةِ.\n\n﴿فِطۡرَتَ ٱللَّهِ﴾: أي: الزَمُوا فِطْرَةَ اللهِ، وهِيَ الإسْلامُ.\n\n﴿فَطَرَ ٱلنَّاسَ عَلَيۡهَا﴾: أي: خَلَقَهُم عَلَيها."],[31,31,"﴿مُنِيبِينَ إِلَيۡهِ﴾: راجِعِينَ إليهِ بالتَّوبَةِ والإخْلاصِ."],[32,32,"﴿فَرَّقُواْ دِينَهُمۡ﴾: أي: آمَنُوا بِبَعْضٍ وكَفَرُوا بِبَعْضٍ.\n\n﴿شِيَعࣰا﴾: فِرَقًا وأحْزابًا مُخْتلِفَةً.\n\n﴿كُلُّ حِزۡبِۭ﴾: كلُّ فَرِيقٍ.\n\n﴿فَرِحُونَ﴾: مَسْرُورُونَ."],[33,33,"﴿ضُرࣱّ﴾: قَحْطٌ وشِدَّةٌ.\n\n﴿مُّنِيبِينَ إِلَيۡهِ﴾: مُلْتَجِئِينَ إليهِ بالتَّوبَةِ والإخْلاصِ.\n\n﴿أَذَاقَهُم مِّنۡهُ رَحۡمَةً﴾: أي: كَشَفَ عَنْهُم ضُرَّهُم."],[35,35,"﴿سُلۡطَـٰنࣰا﴾: بُرْهانًا أو كِتابًا."],[36,36,"﴿فَرِحُواْ بِهَا﴾: فرِحُوا بِها فَرَحَ بَطَرٍ لا فَرَحَ شُكْرٍ.\n\n﴿بِمَا قَدَّمَتۡ أَيۡدِيهِمۡ﴾: أي: بِسَبَبِ أعْمالِهِم السَّيِّئةِ.\n\n﴿يَقۡنَطُونَ﴾: يَيْئَسُونَ."],[37,37,"﴿أَوَ لَمۡ يَرَوۡاْ﴾: أي: أوَلَمْ يَعْلَمُوا.\n\n﴿وَيَقۡدِرُ﴾: يُضَيِّقُ."],[38,38,"﴿فَـَٔاتِ﴾: فأعْطِ.\n\n﴿ٱلۡمِسۡكِينَ﴾: الفَقِيرَ الَّذِي لا يَمْلِكُ ما يَكْفِيهِ ويَسُدُّ حاجَتَه.\n\n﴿ٱبۡنَ ٱلسَّبِيلِ﴾: المُسافِرَ المُحْتاجَ."],[39,39,"﴿وَمَآ ءَاتَيۡتُم﴾: وما أعطَيتُم.\n\n﴿رِّبࣰا﴾: قَرْضًا أو هَدِيَّةً بِقَصْدِ الرِّبا والزِّيادَةِ.\n\n﴿لِّيَرۡبُوَاْ﴾: لِيَزِيِدَ ويَنْمُوَ.\n\n﴿فَلَا يَرۡبُواْ﴾: فَلا يَزِيدُ.\n\n﴿ٱلۡمُضۡعِفُونَ﴾: أي: هُمْ أصْحابُ الأجْرِ المُضاعَفِ."],[40,40,"﴿مِن شُرَكَآئِكُم﴾: مِنَ آلَهتِكُم الَّتي تَعْبُدُونَها مِن دُونِ اللهِ.\n\n﴿سُبۡحَـٰنَهُۥ وَتَعَـٰلَىٰ﴾: تَنَزَّهَ اللهُ وتَقَدَّسَ."],[41,41,"﴿بِمَا كَسَبَتۡ أَيۡدِي ٱلنَّاسِ﴾: أي: بِسَبَبِ أعْمالِهِم السَّيِّئةِ.\n\n﴿بَعۡضَ ٱلَّذِي﴾: أي: عُقُوبَةَ بَعْضِ الَّذي.\n\n﴿يَرۡجِعُونَ﴾: أي: يَتُوبُونَ إلى اللهِ."],[43,43,"﴿لِلدِّينِ ٱلۡقَيِّمِ﴾: أي: نَحْوَ الدِّينِ المسْتَقِيم، وهو الإسْلامُ.\n\n﴿لَّا مَرَدَّ لَهُۥ﴾: أي: لا يقْدِرُ أحدٌ على ردِّهِ.\n\n﴿يَصَّدَّعُونَ﴾: يَتَفَرَّقُونَ، فَرِيقٌ في الجنَّةِ وفَرِيقٌ في السَّعيرِ."],[44,44,"﴿يَمۡهَدُونَ﴾: يُوَطِّئُونَ ويُهَيِّئُونَ الطَّريقَ إلى مَنازِلَ في الجنَّةِ."],[46,46,"﴿مُبَشِّرَ ٰ⁠تࣲ﴾: أي: بِنُزُولِ المَطَرِ.\n\n﴿مِّن رَّحۡمَتِهِۦ﴾: والمرادُ بها هُنا: المَطرُ.\n\n﴿ٱلۡفُلۡكُ﴾: السُّفُنُ.\n\n﴿لِتَبۡتَغُواْ﴾: لِتَطْلُبُوا."],[47,47,"﴿بِٱلۡبَيِّنَـٰتِ﴾: بالمُعْجِزاتِ والبراهِينِ الواضِحةِ.\n\n﴿ٱلَّذِينَ أَجۡرَمُواْ﴾: الَّذينَ فَعَلُوا الإجْرامَ واكْتَسَبُوا السَّيِّئاتِ."],[48,48,"﴿فَتُثِيرُ﴾: فتُحَرِّكُ وتَنْشُرُ.\n\n﴿فَيَبۡسُطُهُۥ﴾: فَيَنْشُرُه.\n\n﴿كِسَفࣰا﴾: قِطَعًا متفرِّقةً.\n\n﴿ٱلۡوَدۡقَ﴾: المطَرَ.\n\n﴿مِنۡ خِلَـٰلِهِۦ﴾: مِن فُرَجِ السَّحابِ ووَسَطِه.\n\n﴿يَسۡتَبۡشِرُونَ﴾: يَفْرَحُونَ."],[49,49,"﴿لَمُبۡلِسِينَ﴾: لَآيسِينَ مِن نُّزُولِ المطَرِ.\n\n﴿بَعۡدَ مَوۡتِهَآ﴾: بَعْدَ جَدْبِها وجَفافِها."],[51,51,"﴿رِيحࣰا﴾: أي: رِيحًا مُفْسِدَةً لِنَباتِهم.\n\n﴿فَرَأَوۡهُ مُصۡفَرࣰّا﴾: فَرَأَوُا النَّباتَ مُصْفَرًّا بَعْدَ الخُضْرَةِ.\n\n﴿لَّظَلُّواْ﴾: لَصارُوا.\n\n﴿يَكۡفُرُونَ﴾: يَجْحَدُونَ باللهِ وبنِعَمِه."],[52,52,"﴿وَلَّوۡاْ﴾: انصَرَفُوا."],[53,53,"﴿بِهَـٰدِ ٱلۡعُمۡيِ﴾: بمُرْشِدِ مَن أعْماهُ اللهُ عَنِ الحقِّ.\n\n﴿مُّسۡلِمُونَ﴾: خاضِعُونَ مُنْقادُونَ."],[54,54,"﴿مِّن ضَعۡفࣲ﴾: أي: مِن نُّطْفَةٍ ضَعِيفَةٍ.\n\n﴿مِنۢ بَعۡدِ ضَعۡفࣲ﴾: أي: مِن بَعْدِ ضَعْفِ الطُّفولَةِ والصِّغَرِ.\n\n﴿قُوَّةࣲ﴾: أي: قُوَّةِ الشَّبابِ.\n\n﴿ضَعۡفࣰا﴾: أي: ضَعْفَ الكِبَرِ والهرَمِ.\n\n﴿وَشَيۡبَةࣰ﴾: أي: بياضًا في الشَّعْرِ وضَعْفًا في قُوى الجسِمِ."],[55,55,"﴿غَيۡرَ سَاعَةࣲ﴾: غيرَ فَتْرَةِ قَصِيرةٍ مِنَ الزَّمَنِ.\n\n﴿يُؤۡفَكُونَ﴾: يُصْرَفُونَ عَنِ الحقِّ والصِّدقِ."],[57,57,"﴿مَعۡذِرَتُهُمۡ﴾: اعْتِذارُهُم.\n\n﴿وَلَا هُمۡ يُسۡتَعۡتَبُونَ﴾: لا يُطْلَبُ مِنهُم إرْضاءُ اللهِ تَعالى بالتَّوبَةِ والطّاعَةِ."],[58,58,"﴿بِـَٔايَةࣲ﴾: أي: بِأيِّ حُجَّةٍ.\n\n﴿مُبۡطِلُونَ﴾: أي: أصْحابُ أباطِيلَ."],[59,59,"﴿يَطۡبَعُ﴾: يَخْتِمُ، فلا تَعِي شيئًا مِنَ الحَقِّ."],[60,60,"﴿وَلَا يَسۡتَخِفَّنَّكَ﴾: لا يَحْمِلَنَّكَ على الخِفَّةِ وتَرْكِ الصَّبْرِ."]]);
QTF("gharib",31,[[4,4,"﴿يُؤۡتُونَ﴾: يُعْطُونَ.\n\n﴿يُوقِنُونَ﴾: يُؤْمِنُونَ."],[5,5,"﴿ٱلۡمُفۡلِحُونَ﴾: الفائِزُونَ."],[6,6,"﴿لَهۡوَ ٱلۡحَدِيثِ﴾: هُوَ كلُّ ما يُلْهِي عَن طاعةِ اللهِ.\n\n﴿بِغَيۡرِ عِلۡمࣲ﴾: جَهْلًا بِعاقِبَةِ ذَلِكَ.\n\n﴿وَيَتَّخِذَهَا﴾: ويَتَّخِذَ سَبيلَ اللهِ وآياتِ كِتابِه.\n\n﴿هُزُوًا﴾: مُسْتهْزَأً بهِا."],[7,7,"﴿وَلَّىٰ﴾: أعْرَضَ وأَدْبَرَ.\n\n﴿مُسۡتَكۡبِرࣰا﴾: مُتَكبِّرًا.\n\n﴿وَقۡرࣰا﴾: ثِقَلًا أو صَمَمًا فلا يَنْتَفِعُ بِما يَسْمَعُ."],[9,9,"﴿حَقࣰّا﴾: أي: وعْدًا حَقًّا ثابِتًا."],[10,10,"﴿عَمَدࣲ﴾: دَعائِمَ، مُفْرَدُه عِمادٌ.\n\n﴿رَوَ ٰ⁠سِيَ﴾: أي: جِبالًا ثَوابِتَ.\n\n﴿أَن تَمِيدَ بِكُمۡ﴾: أي: لِئلا تَتَحَرَّكَ الأرْضُ وتَضْطَرِبَ بِكم.\n\n﴿بَثَّ﴾: نَشَر وفَرَّقَ.\n\n﴿زَوۡجࣲ كَرِيمٍ﴾: صِنْفٍ حَسَنٍ كَثِيرِ المَنفَعَةِ."],[11,11,"﴿ضَلَـٰلࣲ مُّبِينࣲ﴾: عُدُولٍ واضِحٍ عَنِ الطَّرِيقِ المُسْتَقِيمِ."],[12,12,"﴿لُقۡمَـٰنَ﴾: هو رَجُلٌ صالِحٌ كانَ مِن حُكَماءِ بني إسرْائِيلَ.\n\n﴿ٱلۡحِكۡمَةَ﴾: العقلَ والفهمَ وإصابةَ القولِ.\n\n﴿كَفَرَ﴾: أي: جَحَدَ نِعَمَ اللهِ بِعَدَمِ شُكْرِها."],[14,14,"﴿وَصَّيۡنَا﴾: أمَرْنا.\n\n﴿وَهۡنًا﴾: ضَعْفًا.\n\n﴿وَفِصَـٰلُهُۥ﴾: فِطامُه عَنِ الرَّضاعَةِ.\n\n﴿ٱلۡمَصِيرُ﴾: المَرْجِعُ."],[15,15,"﴿جَـٰهَدَاكَ﴾: بَذَلا الجُهْدَ وحاوَلا أن يُجْبِراكَ.\n\n﴿وَصَاحِبۡهُمَا﴾: عاشِرْهُما.\n\n﴿أَنَابَ إِلَيَّ﴾: رَجَع إليّ بالإخْلاصِ والتَّوبة.\n\n﴿مَرۡجِعُكُمۡ﴾: مَصِيرُكُم.\n\n﴿فَأُنَبِّئُكُم﴾: فَأُخْبِرُكُم."],[16,16,"﴿إِنَّهَآ﴾: أي: السَّيِّئةَ أو الحَسَنَةَ.\n\n﴿مِثۡقَالَ حَبَّةࣲ﴾: وزْنَ حَبَّةٍ.\n\n﴿خَرۡدَلࣲ﴾: وهْوَ أصْغَرُ الحُبُوبِ، والمرادُ أصغرُ شيءٍ.\n\n﴿فِي صَخۡرَةٍ﴾: في باطِنِ جَبَلٍ."],[17,17,"﴿بِٱلۡمَعۡرُوفِ﴾: المعْرُوفُ كُلُّ فِعْلٍ يُعْرَفُ حُسْنُه بالشَّرْعِ أو العَقْلِ.\n\n﴿ٱلۡمُنكَرِ﴾: وهْوَ كُلُّ فِعْلٍ يُنكِرُه الشَّرعُ أوِ العَقْلُ.\n\n﴿مِنۡ عَزۡمِ ٱلۡأُمُورِ﴾: أي: مِنَ الأمُورِ الَّتي يَنْبَغِي العَزْمُ والحِرْصُ عليها."],[18,18,"﴿وَلَا تُصَعِّرۡ خَدَّكَ﴾: أي: لا تُمِلْه عُجْبًا واسْتِكْبارًا.\n\n﴿مَرَحًا﴾: فَرَحًا وبَطَرًا.\n\n﴿مُخۡتَالࣲ﴾: مُتَكَبِّرٍ.\n\n﴿فَخُورࣲ﴾: مُتَباهٍ بنفسه."],[19,19,"﴿وَٱقۡصِدۡ فِي مَشۡيِكَ﴾: أي: تَوَسَّطْ فِيه مَعَ تَواضُعٍ وسَكِينَةٍ.\n\n﴿وَٱغۡضُضۡ﴾: واخْفِضْ.\n\n﴿أَنكَرَ ٱلۡأَصۡوَ ٰ⁠تِ﴾: أي: أقبَحَها."],[20,20,"﴿سَخَّرَ لَكُم﴾: ذَلَّلَ لَكُم.\n\n﴿وَأَسۡبَغَ﴾: عَمَّ وأَتَمَّ.\n\n﴿يُجَـٰدِلُ﴾: يُخاصِمُ.\n\n﴿فِي ٱللَّهِ﴾: أي: في تَوحِيدِه وإخْلاصِ العِبادَةِ لَهُ."],[21,21,"﴿عَذَابِ ٱلسَّعِيرِ﴾: عَذابِ جَهَنَّمَ المُسْتَعِرَةِ."],[22,22,"﴿يُسۡلِمۡ وَجۡهَهُۥٓ إِلَى ٱللَّهِ﴾: يُفوِّضْ إلِيهِ أمْرَهُ ويُخلِصْ لَهُ عِبادَتَه.\n\n﴿مُحۡسِنࣱ﴾: مُطِيعٌ للهِ في أمْرِهِ ونَهْيِهِ.\n\n﴿ٱسۡتَمۡسَكَ﴾: تمسَّكَ واعْتَصَمَ.\n\n﴿بِٱلۡعُرۡوَةِ ٱلۡوُثۡقَىٰ﴾: العَهْدِ الأوْثَقِ والسَّبَبِ الأقْوى.\n\n﴿عَـٰقِبَةُ ٱلۡأُمُورِ﴾: مَرْجِعُها."],[23,23,"﴿فَنُنَبِّئُهُم﴾: فَنُخْبِرُهُم."],[24,24,"﴿نَضۡطَرُّهُمۡ﴾: نُلْجِئُهُم ونَسُوقُهُم.\n\n﴿عَذَابٍ غَلِيظࣲ﴾: أي: فَظِيعٍ وثَقِيلٍ، وهُوَ عَذابُ جَهَنَّمَ."],[27,27,"﴿يَمُدُّهُۥ﴾: أي: يَزِيدُه، فَيَصِيرُ ما في البِحارِ كلِّها مِدادًا.\n\n﴿مَّا نَفِدَتۡ﴾: ما فَنِيَتْ."],[28,28,"﴿كَنَفۡسࣲ وَ ٰ⁠حِدَةٍ﴾: أي: كَخَلْقِ نَفْسٍ واحِدَةٍ وبَعْثِها."],[29,29,"﴿يُولِجُ﴾: يُدخِلُ.\n\n﴿سَخَّرَ﴾: ذلَّلَ.\n\n﴿مُّسَمࣰّى﴾: مَعْلُومٍ مُحدَّدٍ."],[31,31,"﴿ٱلۡفُلۡكَ﴾: السُّفُنَ.\n\n﴿لِيُرِيَكُم﴾: ليُظْهِرَ لَكُم.\n\n﴿مِّنۡ ءَايَـٰتِهِۦٓ﴾: أي: مِن آياتِه الدّالَّةِ عَلى قُدْرَتِه.\n\n﴿لَـَٔايَـٰتࣲ﴾: لدَلالاتٍ.\n\n﴿صَبَّارࣲ شَكُورࣲ﴾: أي: صَبّارٍ عَلى الضَّرّاءِ، وشَكُورٍ عَلى السَّرّاءِ."],[32,32,"﴿غَشِيَهُم﴾: عَلاهُم وغَطّاهُم.\n\n﴿كَٱلظُّلَلِ﴾: أي: كَشَيءٍ يكُونُ ظِلًّا مِثْلِ الِجبالِ والسَّحابِ.\n\n﴿مُّقۡتَصِدࣱ﴾: مُتَوَسِّطٌ في عَمَلِهِ وعِبادَتِه.\n\n﴿يَجۡحَدُ﴾: يُنكِرُ.\n\n﴿بِـَٔايَـٰتِنَآ﴾: بحُجَجِنا.\n\n﴿خَتَّارࣲ﴾: غَدّارٍ ناقِضٍ لِلْعهَدِ.\n\n﴿كَفُورࣲ﴾: جَحُودٍ للنِّعَمِ لا يَشْكُرُها."],[33,33,"﴿وَٱخۡشَوۡاْ يَوۡمࣰا﴾: أي: خافُوه واسْتَعِدُّوا لَهُ.\n\n﴿لَّا يَجۡزِي﴾: لا يُغْنِي.\n\n﴿فَلَا تَغُرَّنَّكُمُ﴾: فلا تَخْدَعَنَّكُم.\n\n﴿ٱلۡغَرُورُ﴾: ما يَغُرُّ ويَخْدَعُ مِن شَيطانٍ وغَيرِهِ."],[34,34,"﴿ٱلۡغَيۡثَ﴾: المَطَرَ.\n\n﴿تَدۡرِي﴾: تَعْلَمُ."]]);
QTF("gharib",32,[[1,1,"﴿الٓمٓ﴾: سَبَقَ الكَلامُ عَلى مِثْلهِ في أوَّلِ سُورةِ البقرةِ."],[2,2,"﴿لَا رَيۡبَ فِيهِ﴾: لاشَكَّ فِيه."],[3,3,"﴿أَمۡ يَقُولُونَ﴾: بل أيقُولُ المشرِكُونَ.\n\n﴿ٱفۡتَرَىٰهُ﴾: اختَلَقَ محمدٌ ﷺ القرآنَ مِن تِلْقاءِ نَفْسِهِ.\n\n﴿نَّذِيرࣲ﴾: أي: رَسُولٍ مُنْذِرٍ."],[4,4,"﴿ٱسۡتَوَىٰ عَلَى ٱلۡعَرۡشِ﴾: عَلا وارْتَفَعَ سُبْحانَه وتَعالى عَلى عَرْشِهِ كَما يَليقُ بِجَلالِهِ.\n\n﴿ٱلۡعَرۡشِ﴾: هُوَ سَريرُ المُلْكِ الَّذي اسْتَوى عَلَيهِ الرَّحْمَنُ، وتَحْمِلُهُ الملائِكَةُ، وهْوَ أعْظَمُ المْخلُوقاتِ، وهو سَقْفُ الجنَّةِ.\n\n﴿وَلِيࣲّ﴾: ناصِرٍ يَنْصُرُكُم.\n\n﴿تَتَذَكَّرُونَ﴾: تَتَّعِظُونَ."],[5,5,"﴿يُدَبِّرُ ٱلۡأَمۡرَ﴾: يَقْضِي القَضاءَ.\n\n﴿يَعۡرُجُ﴾: يَصْعَدُ."],[7,7,"﴿أَحۡسَنَ كُلَّ شَيۡءٍ﴾: أحْكَمَهُ وأَتْقَنَهُ.\n\n﴿طِينࣲ﴾: تُرابٍ."],[8,8,"﴿نَسۡلَهُۥ﴾: ذُرِّيَّتَه.\n\n﴿سُلَـٰلَةࣲ﴾: نُطْفَةٍ مَسْلُولَةٍ.\n\n﴿مَّهِينࣲ﴾: ذَلِيلٍ."],[9,9,"﴿سَوَّىٰهُ﴾: أتمَّ خَلْقَهُ.\n\n﴿وَٱلۡأَفۡـِٔدَةَ﴾: القُلُوبَ."],[10,10,"﴿ضَلَلۡنَا فِي ٱلۡأَرۡضِ﴾: ضِعْنا فِيها وصِرْنا تُرابًا.\n\n﴿كَـٰفِرُونَ﴾: مُنْكِرُونَ."],[11,11,"﴿يَتَوَفَّىٰكُم﴾: يَقبِضُ أرْواحَكُم.\n\n﴿وُكِّلَ بِكُمۡ﴾: وُكِّلَ بِقَبْضِ أرْواحِكِم."],[12,12,"﴿نَاكِسُواْ رُءُوسِهِمۡ﴾: أي: مُطْرِقُوها خِزْيًا ونَدامَةً.\n\n﴿مُوقِنُونَ﴾: مُصَدِّقُونَ."],[13,13,"﴿هُدَىٰهَا﴾: رُشْدَها، وتَوفِيقَها لِلْإيمانِ.\n\n﴿حَقَّ﴾: وجَبَ وثَبَتَ."],[14,14,"﴿ٱلۡخُلۡدِ﴾: الدّائِمِ."],[15,15,"﴿يُؤۡمِنُ﴾: يُصَدِّقُ.\n\n﴿ذُكِّرُواْ بِهَا﴾: وُعِظِوُا بِها.\n\n﴿خَرُّواْ﴾: سَقَطوُا."],[16,16,"﴿تَتَجَافَىٰ﴾: تَرْتَفِعُ وتَتَنَحّى.\n\n﴿عَنِ ٱلۡمَضَاجِعِ﴾: عَنِ الفُرُشِ الَّتِي يُضْطَجَعُ عَلَيها."],[17,17,"﴿مِّن قُرَّةِ أَعۡيُنࣲ﴾: مِن موجِباتِ المسَرَّةِ والفَرَحِ."],[19,19,"﴿نُزُلَۢا﴾: ما يُهيَّأُ للنَّزيلِ ضِيافَةً وإكْرامًا."],[20,20,"﴿فَمَأۡوَىٰهُمُ﴾: المكانُ الَّذي يَأْوُونَ إليه."],[21,21,"﴿ٱلۡعَذَابِ ٱلۡأَدۡنَىٰ﴾: وهو ما يُصِيبُهُم في الدُّنيا مِنَ البَلاءِ والِمحَنَ.\n\n﴿ٱلۡعَذَابِ ٱلۡأَكۡبَرِ﴾: وهو ما يُصِيبُهُم يومَ القِيامةِ مِن عَذابِ جَهَنَّمَ."],[22,22,"﴿ذُكِّرَ﴾: وُعِظَ."],[23,23,"﴿فِي مِرۡيَةࣲ﴾: في شَكٍّ.\n\n﴿مِّن لِّقَآئِهِۦ﴾: أي: مِن لِقاءِ مُوسى عَلَيهِ الصَّلاةُ والسَّلامُ."],[25,25,"﴿يَفۡصِلُ﴾: يَقْضِي."],[26,26,"﴿أَوَ لَمۡ يَهۡدِ لَهُمۡ﴾: أوَلم يُبَيِّنْ لَهُم.\n\n﴿مِّنَ ٱلۡقُرُونِ﴾: مِنَ الأُمَمِ السّابقِةِ.\n\n﴿لَـَٔايَـٰتٍ﴾: لَعِبَرًا وعِظاتٍ."],[27,27,"﴿ٱلۡجُرُزِ﴾: الأرْضِ اليابِسةِ الغَلِيظَةِ الجرْداءِ الَّتي لا نَباتَ فِيها."],[28,28,"﴿هَـٰذَا ٱلۡفَتۡحُ﴾: هذا القضاءُ بين العِبادِ."],[29,29,"﴿يُنظَرُونَ﴾: يُمْهَلُونَ لِيؤْمِنُوا."],[30,30,"﴿وَٱنتَظِرۡ﴾: أي: انْتَظِرْ ما اللهُ صانِعٌ بِهِم."]]);
QTF("gharib",33,[[1,1,"﴿ٱتَّقِ ٱللَّهَ﴾: أي: داوِمْ على تَقْواه عزَّ وجلّ."],[3,3,"﴿وَكِيلࣰا﴾: حافِظًا مُفَوَّضًا إليه كُلُّ أمْرٍ."],[4,4,"﴿فِي جَوۡفِهِۦ﴾: أي: في صَدْرِه.\n\n﴿تُظَـٰهِرُونَ﴾: مِنَ الظِّهارِ، وهو أن يقُولَ الرَّجُلُ لامْرَأَتِه: أنتِ عليَّ كَظَهْرِ أُمِّي.\n\n﴿أَدۡعِيَآءَكُمۡ﴾: أولادَكُم المتَبَنَّينَ.\n\n﴿يَهۡدِي﴾: يُرْشِدُ."],[5,5,"﴿ٱدۡعُوهُمۡ لِـَٔابَآئِهِمۡ﴾: انْسُبُوهُم إليهِم.\n\n﴿أَقۡسَطُ﴾: أعْدَلُ وأَقْوَمُ.\n\n﴿وَمَوَ ٰ⁠لِيكُمۡ﴾: أي: هُم أولياؤُكُم في الدِّينِ.\n\n﴿جُنَاحࣱ﴾: إثمٌ.\n\n﴿تَعَمَّدَتۡ﴾: قَصَدَتْ وعَزَمَتْ."],[6,6,"﴿ٱلنَّبِيُّ أَوۡلَىٰ بِٱلۡمُؤۡمِنِينَ﴾: أي: أحَقُّ، فَلَهُ أن يَحْكُمَ فِيهِم بِما يشاءُ.\n\n﴿وَأُوْلُواْ ٱلۡأَرۡحَامِ﴾: ذَوُو القَراباتِ.\n\n﴿أَوۡلَىٰ بِبَعۡضࣲ﴾: أي: أحَقُّ.\n\n﴿مِنَ ٱلۡمُؤۡمِنِينَ وَٱلۡمُهَـٰجِرِينَ﴾: أي: مِن أنْ يُورَثُوا بالإيمانِ والهجرةِ. (كان ذلك في أوَّلِ الإسلامِ، ثم نُسِخ بآيةِ المواريثِ).\n\n﴿إِلَّآ أَن تَفۡعَلُوٓاْ إِلَىٰٓ أَوۡلِيَآئِكُم مَّعۡرُوفࣰا﴾: أي: مِن صَدَقَةٍ أو وصَيَّةٍ للأقارِبِ غَيرِ الورثةِ.\n\n﴿فِي ٱلۡكِتَـٰبِ﴾: أي: في اللَّوحِ المحفوظِ.\n\n﴿مَسۡطُورࣰا﴾: مَكْتُوبًا."],[7,7,"﴿مِيثَـٰقَهُمۡ﴾: عَهْدَهُم المُؤَكَّدَ."],[9,9,"﴿جُنُودࣱ﴾: وهم الأحْزابُ يومَ الخنْدَقِ سَنَةَ خَمْسٍ للهجرةِ.\n\n﴿رِيحࣰا﴾: أي: ريحًا شدِيدةً اقتلَعَتْ خيامَهُم وقَلَبَتْ قُدورَهم.\n\n﴿وَجُنُودࣰا لَّمۡ تَرَوۡهَا﴾: أي: جُنُودًا مِنَ الملائِكةِ."],[10,10,"﴿مِّن فَوۡقِكُمۡ﴾: مِن أعْلى الوادِي مِن جِهةِ المشْرقِ، وهم كانُوا مِن غَطَفانَ وهَوازِنَ وأهْلِ نَجْدٍ.\n\n﴿وَمِنۡ أَسۡفَلَ مِنكُمۡ﴾: مِن بَطْنِ الوادِي مِن جِهَةِ المغْرِبِ، وهم كانُوا مِن مُّشْرِكي مَكَّةَ ومَن كان معهم.\n\n﴿زَاغَتِ ٱلۡأَبۡصَـٰرُ﴾: مالَتِ الأَبصْارُ وشَخَصَتْ مِن شِدَّةِ الفزَعِ والهَوْلِ.\n\n﴿وَبَلَغَتِ ٱلۡقُلُوبُ ٱلۡحَنَاجِرَ﴾: أي: ارْتَفَعَتْ عَن مَّكانِها مِنَ الفَزَعِ والخَوْفِ ووَصَلَتْ إلى الحناجِرِ، مُفْرَدُها حَنْجَرَةٌ وهيَ جَوْفُ الحُلْقُومِ.\n\n﴿ٱلظُّنُونَا۠﴾: أي: الظُّنُونَ السَّيِّئةَ بِأنّ اللهِ لا يَنْصُرُ دِينَه."],[11,11,"﴿ٱبۡتُلِيَ﴾: اخْتُبِر.\n\n﴿زِلۡزَالࣰا﴾: واضْطَرَبُوا."],[12,12,"﴿فِي قُلُوبِهِم مَّرَضࣱ﴾: شَكٌّ، وهم ضُعَفاءُ الإيمانِ.\n\n﴿غُرُورࣰا﴾: باطِلًا."],[13,13,"﴿يَثۡرِبَ﴾: وهو الاسْمُ القديمُ للمدينةِ النَّبَوِيَّةِ.\n\n﴿لَا مُقَامَ لَكُمۡ﴾: لا إقامَةَ لَكُم هاهُنا.\n\n﴿عَوۡرَةࣱ﴾: أي: غيرُ حَصِينةٍ يُخْشى عَلَيها مِنَ الأعْداءِ.\n\n﴿فِرَارࣰا﴾: أي: مِن مَّيدانِ القِتالِ."],[14,14,"﴿دُخِلَتۡ عَلَيۡهِم مِّنۡ أَقۡطَارِهَا﴾: أي: ولو دَخَلَ جيشُ الأحزابِ «المدينةَ» مِن جَوانِبِها.\n\n﴿ٱلۡفِتۡنَةَ﴾: هي الشِّركُ باللهِ، والرُّجُوعُ عَنِ الإسْلامِ.\n\n﴿لَـَٔاتَوۡهَا﴾: لَأعْطَوها، ولأَجابُوا إلى ما طُلِبَ إليهم.\n\n﴿وَمَا تَلَبَّثُواْ بِهَآ﴾: وما أبْطَؤُوا عَن فِتْنةِ الشِّركِ."],[15,15,"﴿لَا يُوَلُّونَ ٱلۡأَدۡبَـٰرَ﴾: لا يَفِرُّونَ مِن مَّيدانِ القِتالِ.\n\n﴿مَسۡـُٔولࣰا﴾: أي: يُسْأَلُ عنه ويُحاسَبُ عَلَيهِ."],[17,17,"﴿يَعۡصِمُكُم﴾: يَمْنَعُكُم."],[18,18,"﴿ٱلۡمُعَوِّقِينَ﴾: المُثَبِّطِينَ عَنِ الجِهادِ مَعَ الرَّسولِ ﷺ.\n\n﴿هَلُمَّ إِلَيۡنَا﴾: تَعالَوا وانْضَمُّوا إلينا.\n\n﴿ٱلۡبَأۡسَ﴾: القتالَ."],[19,19,"﴿أَشِحَّةً عَلَيۡكُمۡ﴾: بُخَلاءَ عَلَيكُم بكلِّ ما يَنْفَعُكُم.\n\n﴿تَدُورُ أَعۡيُنُهُمۡ﴾: يمِينًا وشِمالًا مِن شِدَّةِ الخوفِ.\n\n﴿يُغۡشَىٰ عَلَيۡهِ﴾: يُغمى عَلَيهِ مِن سَكَراتِ الموتِ.\n\n﴿سَلَقُوكُم﴾: آذَوْكُم ورَمَوْكُم.\n\n﴿حِدَادٍ﴾: قاطِعةٍ كالحديدِ.\n\n﴿أَشِحَّةً عَلَى ٱلۡخَيۡرِ﴾: بُخَلاءَ حَرِيصِينَ على المالِ والغَنِيمَةِ.\n\n﴿فَأَحۡبَطَ﴾: فَأبْطَلَ."],[20,20,"﴿يَوَدُّواْ﴾: يَتَمَنَّوا.\n\n﴿بَادُونَ فِي ٱلۡأَعۡرَابِ﴾: كانُوا مَعَهُم في الباديةِ بعيدِينَ عَن مَّيدانِ الحربِ."],[21,21,"﴿أُسۡوَةٌ حَسَنَةࣱ﴾: قُدْوَةٌ صالِحَةٌ في كُلِّ الأُمُورِ.\n\n﴿يَرۡجُواْ﴾: يَخافُ."],[22,22,"﴿ٱلۡأَحۡزَابَ﴾: الجيوشَ التي تَحَزَّبَتْ حَوْلَ المدينةِ."],[23,23,"﴿قَضَىٰ نَحۡبَهُۥ﴾: وفّى بِنَذْرِهِ ونالَ الشَّهادَةَ.\n\n﴿وَمَا بَدَّلُواْ تَبۡدِيلࣰا﴾: وما غَيَّرُوا عَهْدَ اللهِ، بل ثَبَتُوا عَلَيهِ."],[25,25,"﴿بِغَيۡظِهِمۡ﴾: أي: مُتَلَبِّسين بِغَيظِهِم وغَضَبِهِم."],[26,26,"﴿ظَـٰهَرُوهُم﴾: أعانُوهُم.\n\n﴿مِن صَيَاصِيهِمۡ﴾: مِن حُصُونِهِم ومَعاقِلِهِم.\n\n﴿وَقَذَفَ﴾: وألْقى.\n\n﴿ٱلرُّعۡبَ﴾: الخوفَ الشَّدِيدَ.\n\n﴿فَرِيقࣰا تَقۡتُلُونَ﴾: وهم الرِّجالُ.\n\n﴿وَتَأۡسِرُونَ فَرِيقࣰا﴾: وهم النِّساءُ والذُّرِّيَّةُ."],[27,27,"﴿لَّمۡ تَطَـُٔوهَا﴾: لم تَدْخُلُوها."],[28,28,"﴿أُمَتِّعۡكُنَّ﴾: أُعْطِكُنَّ المُتْعَةَ بِشيءٍ مِنَ الدُّنيا.\n\n﴿وَأُسَرِّحۡكُنَّ﴾: أفارِقْكُنَّ بالطَّلاقِ."],[29,29,"﴿أَعَدَّ﴾: هَيَّأَ.\n\n﴿أَجۡرًا﴾: ثوابًا."],[30,30,"﴿بِفَـٰحِشَةࣲ مُّبَيِّنَةࣲ﴾: بمَعْصِيةٍ ظاهِرةِ القُبْحِ.\n\n﴿يَسِيرࣰا﴾: هَيِّنًا."],[31,31,"﴿يَقۡنُتۡ﴾: يَخْضَعْ ويُطِعْ.\n\n﴿أَعۡتَدۡنَا﴾: أعْدَدْنا وهَيَّأنا.\n\n﴿رِزۡقࣰا كَرِيمࣰا﴾: وهو الجنَّةُ."],[32,32,"﴿فَلَا تَخۡضَعۡنَ بِٱلۡقَوۡلِ﴾: فلا تُلِنَّ القولَ والحديثَ للرِّجال.\n\n﴿مَرَضࣱ﴾: فُجُورٌ ومَيْلٌ إلى المعْصِيَةِ.\n\n﴿مَّعۡرُوفࣰا﴾: مُعْتَدِلًا بعِيدًا عَنِ الرِّيبةِ والشَّكِّ."],[33,33,"﴿وَقَرۡنَ﴾: والزَمْنَ.\n\n﴿وَلَا تَبَرَّجۡنَ﴾: ولا تُظْهِرْنَ محاسِنَكُنَّ.\n\n﴿ٱلۡجَـٰهِلِيَّةِ ٱلۡأُولَىٰ﴾: أي: التي كانتْ قَبْلَ الإسْلامِ.\n\n﴿ٱلرِّجۡسَ﴾: الأذىَ والسُّوءَ والخُبْثَ."],[34,34,"﴿وَٱلۡحِكۡمَةِ﴾: السُّنَّةِ النَّبَويَّةِ."],[35,35,"﴿ٱلۡقَـٰنِتِينَ﴾: المطِيعِينَ الخاضِعِينَ للهِ.\n\n﴿وَٱلۡحَـٰفِظِينَ فُرُوجَهُمۡ﴾: أي: عَنِ الزِّنى ومُقَدِّماتِه.\n\n﴿أَعَدَّ﴾: هيَّأ.\n\n﴿أَجۡرًا عَظِيمࣰا﴾: ثوابًا عَظِيمًا، وهو الجنّةُ."],[36,36,"﴿ٱلۡخِيَرَةُ﴾: الاخْتِيارُ.\n\n﴿ضَلَّ﴾: بَعُدَ عَنِ الصِّراطِ المُسْتَقِيمِ."],[37,37,"﴿لِلَّذِيٓ أَنۡعَمَ ٱللَّهُ عَلَيۡهِ﴾: أي: بالإسْلامِ، وهو زَيدُ بْنُ حارِثَة الَّذي تَبَنّاهُ النَّبيُّ ﷺ قَبْلَ أن يُبْطِلَ القرآنُ هذا التَّبَنِّي\n\n﴿وَأَنۡعَمۡتَ عَلَيۡهِ﴾: بأن أعتَقْتَه مِنَ الرِّقِّ.\n\n﴿وَتُخۡفِي فِي نَفۡسِكَ﴾: وهو ما أوْحى اللهُ إلى نبِيِّه مِن طَلاقِ زَيدٍ لِزَوْجِهِ ثُمَّ زَواجِه ﷺ مِنها.\n\n﴿وَطَرࣰا﴾: حاجَةً مُهِمَّةً وهي نِكاحُها.\n\n﴿حَرَجࣱ﴾: إثْمٌ.\n\n﴿أَزۡوَ ٰ⁠جِ أَدۡعِيَآئِهِمۡ﴾: أي: في نِكاحِ زَوْجاتِ أولادِهِم المُتَبنَّينَ، الذي كان حَرامًا على عادَةِ أهْلِ الجاهِليَّةِ، فأبْطَلَها الإسْلامُ."],[38,38,"﴿فَرَضَ ٱللَّهُ لَهُۥ﴾: أي: أحَلَّ اللهُ له.\n\n﴿سُنَّةَ ٱللَّهِ﴾: عادَةَ اللهِ وطَرِيقَتَهُ.\n\n﴿خَلَوۡاْ﴾: مضَوا.\n\n﴿قَدَرࣰا مَّقۡدُورًا﴾: أي: قَضاءً مَقْضِيًّا لابُدَّ مِن وُقُوعِهِ."],[39,39,"﴿حَسِيبࣰا﴾: عَلِيمًا بالأعْمالِ ومُحاسِبًا عَلَيها."],[40,40,"﴿وَخَاتَمَ ٱلنَّبِيِّـۧنَ﴾: أي: آخِرَهُم، فلا نُبُوَّةَ بَعْدَه إلى يومِ القيامةِ."],[42,42,"﴿بُكۡرَةࣰ وَأَصِيلًا﴾: أوَّلَ النهارِ وآخِرَه."],[43,43,"﴿يُصَلِّي عَلَيۡكُمۡ﴾: يُنَزِّلُ رَحْمَتَهُ عَلَيكُم.\n\n﴿مِّنَ ٱلظُّلُمَـٰتِ إِلَى ٱلنُّورِ﴾: مِن ظُلُماتِ الضَّلالةِ إلى نُورِ الهِدايةِ."],[45,45,"﴿شَـٰهِدࣰا﴾: أي: على أُمَّتِكَ."],[46,46,"﴿وَسِرَاجࣰا مُّنِيرࣰا﴾: أي: يُسْتَضاءُ بِهَدْيِهِ في ظُلُماتِ الضَّلالةِ."],[48,48,"﴿وَكِيلࣰا﴾: حافِظًا مُفَوَّضًا إليهِ كُلُّ أمْرٍ."],[49,49,"﴿أَن تَمَسُّوهُنَّ﴾: أن تُجامِعُوهُنَّ.\n\n﴿تَعۡتَدُّونَهَا﴾: تُحْصُونَها عَلَيهِنّ.\n\n﴿فَمَتِّعُوهُنَّ﴾: أعْطُوهُنّ مُتْعَةً يَتَمَتَّعْنَ بِها.\n\n﴿وَسَرِّحُوهُنَّ﴾: خَلُّوا سَبِيلَهُنَّ."],[50,50,"﴿أُجُورَهُنَّ﴾: مُهُورَهُنَّ.\n\n﴿مَلَكَتۡ يَمِينُكَ﴾: أي: مِنَ الإماءِ.\n\n﴿مِمَّآ أَفَآءَ ٱللَّهُ عَلَيۡكَ﴾: مِمّا رَدَّهُ اللهُ عَلَيكَ بالغَنِيمَةِ.\n\n﴿مَا فَرَضۡنَا عَلَيۡهِمۡ﴾: ما أوْجَبْنا عَلَيهِم مِن شُرُوطِ العَقْدِ وحُقُوقِهِ.\n\n﴿حَرَجࣱ﴾: ضِيقٌ وإثْمٌ."],[51,51,"﴿تُرۡجِي﴾: تُؤَخِّرُ في المبيتِ.\n\n﴿تُـٔۡوِيٓ﴾: تَضُمُّ إليكَ في المبيتِ.\n\n﴿وَمَنِ ٱبۡتَغَيۡتَ﴾: ومَن طَلَبْتَ.\n\n﴿مِمَّنۡ عَزَلۡتَ﴾: مِمَّنْ أخَّرْتَ المبيتَ معها.\n\n﴿جُنَاحَ﴾: حَرَجَ.\n\n﴿أَدۡنَىٰٓ﴾: أقْرَبُ.\n\n﴿أَن تَقَرَّ أَعۡيُنُهُنَّ﴾: أي: لِعِلْمِهِنَّ أنَّه مِن عِنْدِ اللهِ."],[52,52,"﴿مِنۢ بَعۡدُ﴾: أي: مِن بَعْدِ أزواجِكَ اللاتِي مَعَكَ.\n\n﴿وَلَآ أَن تَبَدَّلَ بِهِنَّ مِنۡ أَزۡوَ ٰ⁠جࣲ﴾: ولا أنْ تَتَزَوَّجَ بَدَلَهُنَّ غَيْرَهُنَّ.\n\n﴿إِلَّا مَا مَلَكَتۡ يَمِينُكَ﴾: أي: مِنَ الإماءِ فهُنَّ حَلالٌ لَكَ.\n\n﴿رَّقِيبࣰا﴾: حَفِيظًا مُطَّلِعًا."],[53,53,"﴿غَيۡرَ نَـٰظِرِينَ إِنَىٰهُ﴾: غَيرَ مُنْتَظِرِينَ نُضْجَه واسْتِواءَه.\n\n﴿طَعِمۡتُمۡ﴾: أكَلْتُم.\n\n﴿فَٱنتَشِرُواْ﴾: فانصَرِفُوا وتَفَرَّقُوا.\n\n﴿وَلَا مُسۡتَـٔۡنِسِينَ لِحَدِيثٍ﴾: أي: لا تُطِيلُوا المكْثَ عِنْدَه لاسْتِئْناسِ الحديثِ فيما بَيْنَكُم.\n\n﴿مِنَ ٱلۡحَقِّ﴾: أي: مِن بَيانِه.\n\n﴿مَتَـٰعࣰا﴾: حاجَةً مِنَ الماعُونِ وغيرِه.\n\n﴿حِجَابࣲ﴾: سِتْرٍ بَيْنَكُم وبَيْنَهُنَّ."],[54,54,"﴿تُبۡدُواْ﴾: تُظْهِرُوا."],[55,55,"﴿لَّا جُنَاحَ﴾: لا إثْمَ.\n\n﴿وَلَا مَا مَلَكَتۡ أَيۡمَـٰنُهُنَّ﴾: أي: مِنَ الإماءِ والعبيدِ لِشِدَّةِ الحاجَةِ إليهِم في الخِدْمَةِ."],[56,56,"﴿يُصَلُّونَ عَلَى ٱلنَّبِيِّ﴾: يُثْنُونَ على النَّبيِّ ﷺ بإظْهارِ شَرَفِهِ وتَعْظِيمِ شَأْنِه."],[57,57,"﴿يُؤۡذُونَ﴾: أي: بالشِّركِ والمعاصِي.\n\n﴿لَعَنَهُمُ ٱللَّهُ﴾: طَرَدَهُم مِن رَحْمَتِهِ.\n\n﴿مُّهِينࣰا﴾: مُذِلًّا."],[58,58,"﴿بِغَيۡرِ مَا ٱكۡتَسَبُواْ﴾: بِغَيرِ ذَنْبٍ ارْتَكَبُوه.\n\n﴿ٱحۡتَمَلُواْ﴾: حَمَلُوا وهم لا يُطِيقُونَه.\n\n﴿بُهۡتَـٰنࣰا﴾: كَذِبًا شَنِيعًا.\n\n﴿مُّبِينࣰا﴾: ظاهرَ القُبْحِ."],[59,59,"﴿يُدۡنِينَ عَلَيۡهِنَّ﴾: يُرْخِينَ ويُسْدِلْنَ على أجْسادِهِنَّ.\n\n﴿مِن جَلَـٰبِيبِهِنَّ﴾: مِن أرْدِيتِهِنَّ ومَلاحِفِهِنّ.\n\n﴿أَدۡنَىٰٓ﴾: أقْرَبُ.\n\n﴿أَن يُعۡرَفۡنَ﴾: بالحِشْمَةِ والسِّتْرِ.\n\n﴿فَلَا يُؤۡذَيۡنَ﴾: فلا يُتعرَّضُ لَهُنّ بِمَكْرُوهٍ أوْ أذى."],[60,60,"﴿مَّرَضࣱ﴾: شَكٌّ ورِيبَةٌ.\n\n﴿ٱلۡمُرۡجِفُونَ﴾: المُشِيعُونَ للأَخْبارِ الكاذِبَةِ.\n\n﴿لَنُغۡرِيَنَّكَ بِهِمۡ﴾: لنُسَلِّطنَّكَ عَلَيهِم."],[61,61,"﴿مَّلۡعُونِينَ﴾: مَطْرُودِينَ مَنَ رَحْمَةِ اللهِ.\n\n﴿ثُقِفُوٓاْ﴾: وُجِدُوا."],[62,62,"﴿سُنَّةَ ٱللَّهِ﴾: طَرِيَقةَ اللهِ وعادَتَهُ.\n\n﴿خَلَوۡاْ﴾: مَضَوا."],[63,63,"﴿عَنِ ٱلسَّاعَةِ﴾: أي: عَن وقْتِ يومِ القِيامةِ."],[64,64,"﴿لَعَنَ ٱلۡكَـٰفِرِينَ﴾: طَرَدَهُم مِن رَحْمَتِهِ.\n\n﴿وَأَعَدَّ﴾: جَهَّزَ.\n\n﴿سَعِيرًا﴾: نارًا مُسْتَعِرةً شَدِيدَةَ الحرارةِ."],[66,66,"﴿تُقَلَّبُ وُجُوهُهُمۡ﴾: تُحَوَّلُ مِن نّاحيةٍ إلى أُخْرى لِيزْدادَ عَذابُهُم."],[67,67,"﴿ٱلسَّبِيلَا۠﴾: الطَّريقَ المستقيمَ."],[68,68,"﴿ضِعۡفَيۡنِ﴾: مِثلَينِ.\n\n﴿وَٱلۡعَنۡهُمۡ﴾: اطرُدْهُم مِن رَحْمَتِكَ.\n\n﴿كَبِيرࣰا﴾: شَدِيدًا ثَقِيلَ الموقِعِ."],[69,69,"﴿وَجِيهࣰا﴾: عظيمَ القَدْرِ والجاهِ."],[70,70,"﴿سَدِيدࣰا﴾: صَوابًا."],[72,72,"﴿ٱلۡأَمَانَةَ﴾: التَّكالِيفَ الشَّرْعِيةَ مِن الأوامِرِ والنَّواهِي.\n\n﴿فَأَبَيۡنَ﴾: امْتَنَعْنَ.\n\n﴿وَأَشۡفَقۡنَ مِنۡهَا﴾: خِفْنَ مِنَ الخِيانَة فِيها.\n\n﴿ظَلُومࣰا جَهُولࣰا﴾: شَدِيدَ الظُّلمِ والجَهْلِ لِنَفْسِهِ."]]);
QTF("gharib",34,[[2,2,"﴿يَلِجُ﴾: يَدْخُلُ.\n\n﴿يَخۡرُجُ مِنۡهَا﴾: أي: مِنَ النَّباتِ والمعادِن والِمياهِ.\n\n﴿وَمَا يَنزِلُ مِنَ ٱلسَّمَآءِ﴾: مِنَ الأمْطارِ والملائِكةِ والكُتُبِ.\n\n﴿وَمَا يَعۡرُجُ فِيهَا﴾: وما صَعَدُ إلَيها مِنَ الملائِكَةِ وأعْمالِ الخلْقِ."],[3,3,"﴿ٱلسَّاعَةُ﴾: القِيامةُ.\n\n﴿لَا يَعۡزُبُ عَنۡهُ﴾: لا يَغِيبُ عَنْهُ ولا يَخْفى عَلَيهِ.\n\n﴿مِثۡقَالُ ذَرَّةࣲ﴾: مِقْدارُ أصْغرِ نَمْلَةٍ.\n\n﴿كِتَـٰبࣲ مُّبِينࣲ﴾: كِتابٍ واضِحٍ، وهو اللَّوحُ المَحْفُوظُ."],[4,4,"﴿وَرِزۡقࣱ كَرِيمࣱ﴾: وهو الجنَّةُ."],[5,5,"﴿مُعَـٰجِزِينَ﴾: ظانِّينَ أنّهم يُعْجِزُونَنا ويَغْلِبُونَنا.\n\n﴿مِّن رِّجۡزٍ﴾: أسْوَأِ العَذابِ وأشَدِّهِ."],[6,6,"﴿وَيَرَى﴾: يَعْلمُ.\n\n﴿وَيَهۡدِيٓ﴾: يُرْشِدُ."],[7,7,"﴿يُنَبِّئُكُمۡ﴾: يُخْبِرُكُم بِنَبَأٍ غَرِيبٍ.\n\n﴿مُزِّقۡتُمۡ﴾: قُطِّعْتُم، وتَفَرَّقَتْ أجْسادُكُم إلى أجْزاءٍ."],[8,8,"﴿أَفۡتَرَىٰ﴾: هَلِ اخْتَلَقَ؟\n\n﴿جِنَّةُۢ﴾: جُنُونٌ."],[9,9,"﴿مَا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُم مِّنَ ٱلسَّمَآءِ وَٱلۡأَرۡضِ﴾: أي: كُلٌّ مِنَ السَّماءِ والأرضِ يُحِيطُ بِهِم مِن أمامِهِم وخَلْفِهِم.\n\n﴿نَخۡسِفۡ بِهِمُ ٱلۡأَرۡضَ﴾: نَجْعَلِ الأرْضَ تَبْتَلِعُهُم وهُمْ أحْياءٌ.\n\n﴿كِسَفࣰا مِّنَ ٱلسَّمَآءِ﴾: قِطَعًا مِنها.\n\n﴿مُّنِيبࣲ﴾: راجِعٍ إلى رَبِّهِ بالتَّوبَةِ والطّاعَةِ."],[10,10,"﴿أَوِّبِي﴾: سَبِّحِي.\n\n﴿وَأَلَنَّا لَهُ ٱلۡحَدِيدَ﴾: جَعَلْنا الحديدَ في يدِهِ لَيِّنًا، يَصْنَعُ بِهِ ما يَشاءُ."],[11,11,"﴿سَـٰبِغَـٰتࣲ﴾: أي: دُرُوعًا واسِعاتٍ تُغَطِّي الِجسْمَ كلَّه.\n\n﴿قَدِّرۡ فِي ٱلسَّرۡدِ﴾: أي: قَدِّرْ في نَسْجِ الدُّرُوعِ وإحْكامِها تَقْدِيرًا مُناسِبًا يَجْمَعُ ما بَينَ الخِفَّةِ والحَصانَةِ."],[12,12,"﴿غُدُوُّهَا شَهۡرࣱ﴾: أي: تَجْرِي الرِّيحُ مِن أوَّلِ النَّهارِ إلى انْتِصافِه مَسِيرَةَ شَهْرٍ بالسَّيرِ المُعْتادِ.\n\n﴿وَرَوَاحُهَا شَهۡرࣱ﴾: أي: تَجْرِي الرِّيحُ مِن مُّنْتَصَفِ النَّهارِ إلى اللَّيلِ مَسِيرَةَ شَهْرٍ.\n\n﴿وَأَسَلۡنَا لَهُۥ عَيۡنَ ٱلۡقِطۡرِ﴾: وأَسَلْنا لَهُ عَينَ النُّحاسِ كما يَسِيلُ الماءُ.\n\n﴿مَن يَزِغۡ﴾: مَن يَمِلْ ويَعدِلْ.\n\n﴿ٱلسَّعِيرِ﴾: النّارِ المسْتَعِرةِ."],[13,13,"﴿مَّحَـٰرِيبَ﴾: قُصُورٍ أو مساجِدَ.\n\n﴿وَتَمَـٰثِيلَ﴾: صُوَرٍ مُجَسَّمَةٍ من نُّحاسٍ وزُجاجٍ وغيرِهِما (وحُرِّمَ ذلك في الإسْلامِ).\n\n﴿وَجِفَانࣲ﴾: جَمْعُ «جَفْنَةٍ»، وهي القَصْعةُ الكَبِيرةُ.\n\n﴿كَٱلۡجَوَابِ﴾: جَمْعِ «جابِيَةٍ»، وهي الحوضُ الكبيرُ الذي يُجْمعُ فيه الماءُ.\n\n﴿رَّاسِيَـٰتٍ﴾: ثابتاتٍ على المواقِد، لا تَتَحَرَّكُ لِعِظَمِها."],[14,14,"﴿قَضَيۡنَا﴾: حَكَمْنا.\n\n﴿دَآبَّةُ ٱلۡأَرۡضِ﴾: الأَرَضَةُ الَّتي تَأْكُلُ الخَشَبَ.\n\n﴿مِنسَأَتَهُۥ﴾: عَصاهُ.\n\n﴿خَرَّ﴾: سَقَطَ ووَقَعَ.\n\n﴿تَبَيَّنَتِ﴾: عَلِمَتْ.\n\n﴿مَا لَبِثُواْ﴾: ما أقامُوا.\n\n﴿ٱلۡمُهِينِ﴾: المُذِلِّ."],[15,15,"﴿لِسَبَإࣲ﴾: «سبأ» بَلَدٌ باليمنِ سُمِّيَ باسم «سبأ بن يَشْجُب»، ويقعُ شرقَ صنعاء، ويُسَمّى الآنَ «مأرِبًا».\n\n﴿ءَايَةࣱ﴾: دَلالةٌ على قُدْرَتِنا.\n\n﴿جَنَّتَانِ عَن يَمِينࣲ وَشِمَالࣲ﴾: مَجْمُوعَتانِ كَبِيرَتانِ مِنَ البساتِينِ الكثيرةِ عَن يَمِينِ الوادِي وشِمالِه.\n\n﴿طَيِّبَةࣱ﴾: كريمةُ التُّربةِ حَسَنةُ الهواءِ."],[16,16,"﴿سَيۡلَ ٱلۡعَرِمِ﴾: السَّيلَ الجارِفَ الشَّدِيدَ.\n\n﴿خَمۡطࣲ﴾: هو الثَّمرُ المُرُّ الكريهُ الطَّعْمِ والرائِحَةِ.\n\n﴿أَثۡلࣲ﴾: هو شَجَرٌ شَبِيهٌ بالطَّرْفاءِ لا ثَمَرَ لَهُ.\n\n﴿سِدۡرࣲ﴾: هو شجرُ النَّبْقِ كثِيرُ الشَّوكِ."],[17,17,"﴿نُجَـٰزِيٓ﴾: نُعاقِبُ.\n\n﴿ٱلۡكَفُورَ﴾: الجَحودَ المبالِغَ في الكُفْرِ بِنِعَمِ اللهِ ورُسُلِه."],[18,18,"﴿بَيۡنَهُمۡ﴾: أي: بينَ أهلِ «سبأٍ» الَّذينَ كانُوا باليمنِ.\n\n﴿ٱلۡقُرَى ٱلَّتِي بَـٰرَكۡنَا فِيهَا﴾: هي بلادُ «الشّامِ».\n\n﴿قُرࣰى ظَـٰهِرَةࣰ﴾: قُرىً مُتَواصِلةً مُتَقارِبة يُرى بَعْضُها مِن بَعْضٍ (على امْتِداد الطَّرِيقِ مِنَ اليمنِ إلى الشّامِ).\n\n﴿قَدَّرۡنَا فِيهَا ٱلسَّيۡرَ﴾: أي: جَعَلْنا مَسافَةَ السَّيرِ بَيْنَ القُرى مَسافَةً متقارِبةً نَحْوًا مِن نِّصفِ يومٍ ليكونَ المَقِيلُ في قَرْيَةٍ والمبيتُ في أُخْرى.\n\n﴿ءَامِنِينَ﴾: لا تخافُونَ عَدُوًّا ولا جُوعًا ولا عَطَشًا."],[19,19,"﴿بَـٰعِدۡ بَيۡنَ أَسۡفَارِنَا﴾: أي: اجْعَلْ هذه القُرى المُتَقارِبةَ مُتَباعِدةً لِيَبْعُدَ سَفَرُنا بَينَها.\n\n﴿أَحَادِيثَ﴾: أي: ذوي أخبارٍ يتحدّثُ الناسُ بها في مجالِسِهِم للتَّعَجُّبِ والاعْتِبارِ.\n\n﴿وَمَزَّقۡنَـٰهُمۡ﴾: فَرَّقْناهُم في البلادِ.\n\n﴿لَـَٔايَـٰتࣲ﴾: لَعِبرًا وعِظاتٍ."],[20,20,"﴿صَدَّقَ عَلَيۡهِمۡ﴾: حقَّقَ عَلَيهِم.\n\n﴿ظَنَّهُۥ﴾: بأنّهم يَتَّبِعُونَه."],[21,21,"﴿سُلۡطَـٰنٍ﴾: تَسَلُّطٍ واسْتِيلاءٍ بالوسْوَسَةِ والإغْواءِ."],[22,22,"﴿زَعَمۡتُم مِّن دُونِ ٱللَّهِ﴾: أي: زَعَمْتُمُوهُم شركاءَ للهِ.\n\n﴿مِثۡقَالَ ذَرَّةࣲ﴾: مِقْدارَ أصْغَرِ نَمْلَةٍ.\n\n﴿شِرۡكࣲ﴾: مُشارَكَةٍ.\n\n﴿ظَهِيرࣲ﴾: مُعِينٍ على الخَلْقِ والتَّدبيرِ."],[23,23,"﴿فُزِّعَ عَن قُلُوبِهِمۡ﴾: أُزيِلَ الفَزَعُ والخوفُ عَن قُلُوبِهِم."],[25,25,"﴿أَجۡرَمۡنَا﴾: اكْتَسَبْنا مِنَ الذُّنُوبِ."],[26,26,"﴿يَفۡتَحُ بَيۡنَنَا﴾: يَقْضِي ويَحْكُمُ بَيْنَنا.\n\n﴿ٱلۡفَتَّاحُ﴾: الحاكِمُ بَينَ خَلْقِهِ."],[27,27,"﴿أَرُونِيَ﴾: أي: بالحُجَّةِ والدَّليلِ."],[28,28,"﴿كَآفَّةࣰ لِّلنَّاسِ﴾: للنّاسِ أجْمَعِينَ."],[30,30,"﴿مِّيعَادُ يَوۡمࣲ﴾: هو يومُ القيامةِ.\n\n﴿لَّا تَسۡتَـٔۡخِرُونَ عَنۡهُ﴾: لا تتأخَّرُونَ عَنْهُ.\n\n﴿لَا تَسۡتَقۡدِمُونَ﴾: لا تَتَقَدَّمُونَ عَلَيه."],[31,31,"﴿وَلَا بِٱلَّذِي بَيۡنَ يَدَيۡهِ﴾: ولا بالَّذي تَقَدَّمَهُ مِنَ الكُتُبِ السَّماوِيَّةِ كالتَّوراةِ والإنْجِيلِ والزَّبُورِ.\n\n﴿مَوۡقُوفُونَ﴾: محبوسُونَ في مَوْقِفِ الحِسابِ.\n\n﴿يَرۡجِعُ بَعۡضُهُمۡ إِلَىٰ بَعۡضٍ ٱلۡقَوۡلَ﴾: يتراجعُون الكلام باللَّومِ والعِتابِ فيما بَينَهُم."],[32,32,"﴿ٱلَّذِينَ ٱسۡتَكۡبَرُواْ﴾: هم القادَةُ والرُّؤساءُ الضّالُّون المُضِلُّونَ.\n\n﴿صَدَدۡنَـٰكُمۡ﴾: مَنَعْناكُم.\n\n﴿بَلۡ كُنتُم مُّجۡرِمِينَ﴾: بَلْ كُنْتُم اخْتَرْتُم سَبِيلَ الإجْرامِ لِمَحْضِ إرادَتِكُم."],[33,33,"﴿بَلۡ مَكۡرُ ٱلَّيۡلِ وَٱلنَّهَارِ﴾: بَلْ صَدَّنا مَكْرُكُم بِنا وتَدْبِيرُكُم الشَّرَّ لَنا في اللَّيلِ والنَّهارِ.\n\n﴿أَندَادࣰا﴾: أمْثالًا وشُرَكاءَ مِن مَّخْلُوقاتِه.\n\n﴿أَسَرُّواْ ٱلنَّدَامَةَ﴾: أي: أضْمَرَ وأَخْفى الفَرِيقانِ الحسْرةَ والنَّدامةَ.\n\n﴿ٱلۡأَغۡلَـٰلَ﴾: الأطْواقَ.\n\n﴿يُجۡزَوۡنَ﴾: يُعاقَبونَ."],[34,34,"﴿مِّن نَّذِيرٍ﴾: مِن رَّسولٍ.\n\n﴿مُتۡرَفُوهَآ﴾: مُتَنَعِّمُوها.\n\n﴿كَـٰفِرُونَ﴾: جاحِدُون، مُنْكِرُونَ."],[35,35,"﴿بِمُعَذَّبِينَ﴾: أي: في الدُّنيا ولا في الآخرةِ."],[36,36,"﴿يَبۡسُطُ﴾: يُوَسِّعُ.\n\n﴿يَقۡدِرُ﴾: يُضَيِّقُ."],[37,37,"﴿زُلۡفَىٰٓ﴾: قُرْبى.\n\n﴿لَهُمۡ جَزَآءُ ٱلضِّعۡفِ﴾: لهم الثَّوابُ المُضاعَفُ.\n\n﴿ٱلۡغُرُفَـٰتِ﴾: المنازلِ العالِيةِ في الجنّةِ.\n\n﴿ءَامِنُونَ﴾: أي: مِن جَمِيعِ ما يكْرَهُونَ كالعذابِ والموتِ والأحْزانِ."],[38,38,"﴿مُعَـٰجِزِينَ﴾: ظانّينَ أنّهُم يُعْجِزُونَنا ويَغلِبُونَنا.\n\n﴿فِي ٱلۡعَذَابِ مُحۡضَرُونَ﴾: مُقيمُونَ فيه تُحضِرُهم الزَّبانيةُ، فَلا يَسْتَطِيعُونَ الخُرُوجَ منه."],[39,39,"﴿يَبۡسُطُ﴾: يُوَسِّعُ.\n\n﴿يَقۡدِرُ﴾: يُضَيِّقُ.\n\n﴿يُخۡلِفُهُۥ﴾: يُعَوِّضُه لكم في الدُّنيا وفي الآخِرةِ."],[40,40,"﴿يَحۡشُرُهُمۡ﴾: يَجْمَعُهُم."],[41,41,"﴿سُبۡحَـٰنَكَ﴾: نُنَزِّهُكَ يا اللهُ.\n\n﴿أَنتَ وَلِيُّنَا﴾: أنتَ الَّذي نُوالِيهِ ونَعْبُدُهُ.\n\n﴿ٱلۡجِنَّ﴾: أي: الشَّياطِينَ."],[43,43,"﴿أَن يَصُدَّكُمۡ﴾: أن يَمْنَعَكُم.\n\n﴿إِفۡكࣱ مُّفۡتَرࣰى﴾: كَذِبٌ مُخْتَلَقٌ.\n\n﴿مُّبِينࣱ﴾: واضِحٌ."],[44,44,"﴿يَدۡرُسُونَهَا﴾: يَقْرَؤُونَها ويَفْهَمُونَها.\n\n﴿مِن نَّذِيرࣲ﴾: مِن رَّسولٍ."],[45,45,"﴿وَكَذَّبَ ٱلَّذِينَ مِن قَبۡلِهِمۡ﴾: أي: مِنَ الأُمَمِ الماضيةِ كَعادٍ وثمُودَ.\n\n﴿وَمَا بَلَغُواْ﴾: وما بلَغَ أهلُ مَكَّةَ.\n\n﴿مِعۡشَارَ مَآ ءَاتَيۡنَـٰهُمۡ﴾: عُشْرَ ما أعْطَيناهُم مِنَ النِّعَمِ.\n\n﴿نَكِيرِ﴾: إنْكارِي عليهم بالعِقابِ والعَذابِ."],[46,46,"﴿أَعِظُكُم بِوَ ٰ⁠حِدَةٍ﴾: أنْصَحُكُم وأُوصِيكُم بِخَصْلَةٍ واحِدَةٍ.\n\n﴿أَن تَقُومُواْ لِلَّهِ﴾: أن تَجْتَهِدُوا بالقِيامِ لهذا الأَمْرِ، مُخْلِصِينَ للهِ مِن غَيرِ هَوىً ولا عَصَبِيَّةٍ.\n\n﴿مِّن جِنَّةٍ﴾: مِن جُنُونٍ."],[48,48,"﴿يَقۡذِفُ بِٱلۡحَقِّ﴾: يَرْمِي الباطِلَ بالحقِّ فيَدْمَغُه."],[49,49,"﴿ٱلۡحَقُّ﴾: القرآنُ.\n\n﴿وَمَا يُبۡدِئُ ٱلۡبَـٰطِلُ وَمَا يُعِيدُ﴾: أي: ذَهَبَ واضْمَحَلَّ، ولم يَبْقَ مِنهُ إقْبالٌ ولا إدْبارٌ."],[50,50,"﴿ضَلَلۡتُ﴾: أي: عَنِ الصِّراطِ المُسْتَقِيمِ."],[51,51,"﴿إِذۡ فَزِعُواْ﴾: خافُوا عِنْدَ مُعايَنَتِهِم العَذابَ.\n\n﴿فَلَا فَوۡتَ﴾: أي: لا يفُوتُنِي أحَدٌ مِنهُم فَيَهْرُبَ.\n\n﴿مَّكَانࣲ قَرِيبࣲ﴾: مَوْضِعٍ قَرِيبٍ، فهُم لا يَبْعُدُونَ عَنِ اللهِ حيثُ كانُوا."],[52,52,"﴿وَأَنَّىٰ لَهُمُ ٱلتَّنَاوُشُ مِن مَّكَانِۭ بَعِيدࣲ﴾: وكَيْفَ لَهُمْ أن يَتَناوَلُوا الإيمانَ في الآخِرةِ وقَدْ تَرَكُوه في الدُّنيا؟"],[53,53,"﴿وَيَقۡذِفُونَ بِٱلۡغَيۡبِ مِن مَّكَانِۭ بَعِيدࣲ﴾: يَرْمُونَ مِن مَّكانٍ بَعِيدٍ وهُمْ لا يَرَوْنَ."],[54,54,"﴿وَحِيلَ﴾: وحُجِزَ ومُنِعَ.\n\n﴿مَا يَشۡتَهُونَ﴾: أي: مِنَ التَّوبَةِ والعوْدَةِ إلى الدُّنيا.\n\n﴿بِأَشۡيَاعِهِم﴾: بأمثالِهِم مِنَ الكُفّارِ.\n\n﴿مُّرِيبِۭ﴾: مُوقِعٍ في الرِّيبةِ."]]);
QTF("gharib",35,[[1,1,"﴿فَاطِرِ﴾: مُبْدِعٍ عَلى غَيرِ مِثالٍ سَبَقَ.\n\n﴿أُوْلِيٓ أَجۡنِحَةࣲ﴾: أصْحابَ أجْنِحَةٍ."],[2,2,"﴿مَّا يَفۡتَحِ﴾: أي: ما يُرسِلْ ويُعْطِ.\n\n﴿رَّحۡمَةࣲ﴾: نِعْمَةٍ.\n\n﴿مُمۡسِكَ﴾: مانِعَ.\n\n﴿مُرۡسِلَ﴾: مُعْطِيَ."],[3,3,"﴿فَأَنَّىٰ تُؤۡفَكُونَ﴾: فَكَيفَ تُصْرَفُونَ عَن تَوحِيدِهِ؟."],[5,5,"﴿وَعۡدَ ٱللَّهِ﴾: أي: بالبعْثِ والثَّوابِ والعِقابِ.\n\n﴿حَقࣱّ﴾: ثابِتٌ وكائِنٌ لا محالةَ.\n\n﴿فَلَا تَغُرَّنَّكُمُ﴾: فَلا تَخْدَعَنَّكُم.\n\n﴿ٱلۡغَرُورُ﴾: الشَّيطانُ."],[6,6,"﴿حِزۡبَهُۥ﴾: أي: أتْباعَهُ.\n\n﴿ٱلسَّعِيرِ﴾: النّارِ الموقَدَةِ."],[7,7,"﴿أَجۡرࣱ كَبِيرٌ﴾: وهو الجنَّةُ."],[8,8,"﴿زُيِّنَ لَهُۥ﴾: أي: حَسَّنَ له الشَّيطانُ.\n\n﴿سُوٓءُ عَمَلِهِۦ﴾: عَمَلُه السَّيِّئُ والقبيحُ.\n\n﴿فَلَا تَذۡهَبۡ نَفۡسُكَ عَلَيۡهِمۡ حَسَرَ ٰ⁠تٍ﴾: فلا تُهِلكْ نفسَك حُزْنًا على كُفْرِهِم."],[9,9,"﴿فَتُثِيرُ﴾: فَتُحَرِّكُ.\n\n﴿مَّيِّتࣲ﴾: جَدْب.\n\n﴿بَعۡدَ مَوۡتِهَا﴾: بَعْدَ يُبْسِها وجَفافِها.\n\n﴿ٱلنُّشُورُ﴾: بَعْثُ الموتى مِن قُبُورِهِم للجزاءِ."],[10,10,"﴿يَصۡعَدُ﴾: يَرْتَقِي.\n\n﴿ٱلۡكَلِمُ ٱلطَّيِّبُ﴾: الكلامُ الطَّيِّبُ مِن ذِكْرٍ ودُعاءٍ وتِلاوَةٍ.\n\n﴿يَرۡفَعُهُۥ﴾: أي: يَرفَعُه اللهُ إلَيهِ ويَقْبَلُه.\n\n﴿يَمۡكُرُونَ ٱلسَّيِّـَٔاتِ﴾: أي: يَمْكُرُونَ المكَراتِ السَّيِّئاتِ، وهي مَذْكُورةٌ في قوله تعالى:\n\n﴿وَإِذۡ يَمۡكُرُ بِكَ ٱلَّذِينَ كَفَرُواْ لِيُثۡبِتُوكَ أَوۡ يَقۡتُلُوكَ أَوۡ يُخۡرِجُوكَ﴾: [الأنفال: ٣٠].\n\n﴿يَبُورُ﴾: يَفسُدُ ويَبْطُلُ."],[11,11,"﴿مِن نُّطۡفَةࣲ﴾: هي مَنِيُّ الرجلِ يَقْذِفُه في رَحِمِ امْرَأَتِه.\n\n﴿أَزۡوَ ٰ⁠جࣰا﴾: ذُكُورًا وإناثًا تَزَوَّجَ بعضُهم بَعْضًا.\n\n﴿لَا تَضَعُ﴾: لاتَلِدُ.\n\n﴿مُّعَمَّرࣲ﴾: طَوِيلِ العُمُرِ."],[12,12,"﴿فُرَاتࣱ﴾: حُلْوٌ شَدِيدُ الحَلاوَةِ.\n\n﴿سَآئِغࣱ شَرَابُهُۥ﴾: سَهْلٌ مُرُورُهُ في الحَلْقِ.\n\n﴿أُجَاجࣱ﴾: شَدِيدُ المُلوحَةِ.\n\n﴿لَحۡمࣰا طَرِيࣰّا﴾: هو السَّمَكُ.\n\n﴿حِلۡيَةࣰ﴾: هي اللُّؤلُؤُ والمَرْجانُ.\n\n﴿ٱلۡفُلۡكَ﴾: السُّفُنَ.\n\n﴿مَوَاخِرَ﴾: جوارِيَ تَشُقُّ الماءَ شَقًّا.\n\n﴿لِتَبۡتَغُواْ﴾: لِتَطْلُبُوا."],[13,13,"﴿يُولِجُ﴾: يُدخِلُ.\n\n﴿لِأَجَلࣲ مُّسَمࣰّى﴾: لِوقْتٍ مَعْلُومٍ.\n\n﴿قِطۡمِيرٍ﴾: القِشْرَةِ الرَّقيقَةِ على نَواةِ التَّمْرَةِ."],[14,14,"﴿وَلَا يُنَبِّئُكَ﴾: ولا يُخْبِرُكَ."],[15,15,"﴿ٱلۡفُقَرَآءُ﴾: المحْتاجُونَ."],[17,17,"﴿بِعَزِيزࣲ﴾: بمُمْتَنِعٍ."],[18,18,"﴿وَلَا تَزِرُ﴾: لا تَحْمِلُ.\n\n﴿وَازِرَةࣱ﴾: أي: نفسٌ مُذْنِبَةٌ.\n\n﴿مُثۡقَلَةٌ﴾: أي: نَفْسٌ أثْقَلَتْها الذُّنوبُ.\n\n﴿حِمۡلِهَا﴾: ذُنُوبِها التي أثْقَلَتْها.\n\n﴿يَخۡشَوۡنَ﴾: يخافُونَ.\n\n﴿تَزَكَّىٰ﴾: تَطَهَّرَ مِنَ الشِّرْكِ والمعاصِي.\n\n﴿ٱلۡمَصِيرُ﴾: المرْجِعُ."],[19,19,"﴿ٱلۡأَعۡمَىٰ﴾: مَن فَقَدَ بَصَرَه، والمُرادُ بِه هُنا الكافِرُ لأنّهُ عَمِيَ عَن دِينِ الحقِّ."],[21,21,"﴿ٱلۡحَرُورُ﴾: الرِّيحُ الحارَّةُ."],[23,23,"﴿نَذِيرٌ﴾: رَسُولٌ مُنْذِرٌ مِن عَذابِ اللهِ."],[24,24,"﴿بَشِيرࣰا وَنَذِيرࣰا﴾: بَشِيرًا لِأَهْلِ الطّاعةِ ونَذَيرًا لِأَهْلِ المعْصِيةِ.\n\n﴿نَذِيرࣱ﴾: نَبِيٌّ مُنْذِرٌ مِن عَذابِ اللهِ."],[25,25,"﴿بِٱلۡبَيِّنَـٰتِ﴾: بالمعْجِزاتِ الواضِحةِ.\n\n﴿وَبِٱلزُّبُرِ﴾: بالكُتُبِ التي فيها مَواعِظُ.\n\n﴿وَبِٱلۡكِتَـٰبِ ٱلۡمُنِيرِ﴾: الكُتُبِ الَّتي أنارَتْ طَرِيقَ الشَّرْعِ والهِدايَةِ، ومْنِها القرآنُ الكريمُ."],[27,27,"﴿جُدَدُۢ﴾: جَمْعُ جُدَّةٍ، وهي الطَّرِيقَةُ والخِطَّةُ في الشَّيءِ تكونُ واضِحةً فِيهِ.\n\n﴿وَغَرَابِيبُ﴾: جمع غِرْبِيبٍ، وهو شَديدُ السَّوادِ يُشْبِهُ لَونُه لَونَ الغُرابِ."],[29,29,"﴿لَّن تَبُورَ﴾: لَن تَكْسُدَ، ولَن تَهْلِكَ."],[32,32,"﴿ٱلَّذِينَ ٱصۡطَفَيۡنَا﴾: الَّذِيِنَ اخْتَرْناهُم.\n\n﴿ظَالِمࣱ لِّنَفۡسِهِۦ﴾: أي: بِأن وقَعَ في بَعْضِ المعاصِي.\n\n﴿مُّقۡتَصِدࣱ﴾: أي: بِأَداءِ الواجِباتِ واجْتِنابِ المُحَرَّماتِ.\n\n﴿سَابِقُۢ بِٱلۡخَيۡرَ ٰ⁠تِ﴾: أي: مُسارعٌ مُجْتَهِدٌ في الأعْمالِ الصّالحةِ فَرْضِها ونَفْلِها."],[33,33,"﴿يُحَلَّوۡنَ﴾: يُزيَّنُونَ بالحِلْيةَ.\n\n﴿أَسَاوِرَ﴾: مُفْرَدُه سِوارٌ: وهو ما يُلْبَسُ في اليدِ مِنَ الحُلِيِّ ويُحِيطُ بالمِعْصَمِ.\n\n﴿حَرِيرࣱ﴾: ثِيابٌ رَقِيقَةٌ."],[34,34,"﴿ٱلۡحَزَنَ﴾: أي: كُلَّ ما يُحْزِنُ ويُغِمُّ."],[35,35,"﴿أَحَلَّنَا﴾: أنزَلنا.\n\n﴿دَارَ ٱلۡمُقَامَةِ﴾: دارَ الإقامةِ الدّائمةِ، وهي الجنَّةُ.\n\n﴿نَصَبࣱ﴾: تَعَبٌ ومَشَقَّةٌ.\n\n﴿لُغُوبࣱ﴾: إعياءٌ مِنَ التَّعَبِ وفُتُورٌ."],[36,36,"﴿لَا يُقۡضَىٰ عَلَيۡهِمۡ﴾: أي: بالموتِ.\n\n﴿كَفُورࣲ﴾: مُتَمادٍ في الكُفْرِ مُصِرٍّ عليه."],[37,37,"﴿يَصۡطَرِخُونَ﴾: يَصْرُخُونَ بِشِدَّةٍ مُسْتَغِيثِينَ.\n\n﴿مَّا يَتَذَكَّرُ فِيهِ مَن تَذَكَّرَ﴾: أي: مِثْلُه كافٍ للاتِّعاظِ لِمنْ أرادَ أن يَتَّعِظَ فِيهِ.\n\n﴿ٱلنَّذِيرُ﴾: وهو الرَّسولُ ﷺ."],[39,39,"﴿خَلَـٰٓئِفَ﴾: يَخْلُفُ بَعْضُكُم بَعْضًا.\n\n﴿مَقۡتࣰا﴾: بُغْضًا وغَضَبًا.\n\n﴿خَسَارࣰا﴾: هَلاكًا وخُسْرانًا."],[40,40,"﴿أَرَءَيۡتُمۡ شُرَكَآءَكُمُ﴾: أخْبرُونِي عَن شُركائِكُم.\n\n﴿ءَاتَيۡنَـٰهُمۡ﴾: أعْطَيناهُم.\n\n﴿غُرُورًا﴾: خِداعًا."],[42,42,"﴿جَهۡدَ أَيۡمَـٰنِهِمۡ﴾: مُجْتَهِدِينَ فِيها بالحَلِفِ بأغْلَظِها.\n\n﴿نُفُورًا﴾: بُعْدًا عَنِ الحقِّ وفِرارًا مِنه."],[43,43,"﴿لَا يَحِيقُ﴾: لا يُحِيطُ ولا يَنْزِلُ.\n\n﴿ٱلۡمَكۡرُ ٱلسَّيِّئُ﴾: أي: وبالُ مَكْرِهِم السَّيِّئِ.\n\n﴿سُنَّتَ ٱلۡأَوَّلِينَ﴾: طَرِيقَةَ اللهِ فِيهِم وعادَتَهُ بِتَعْذِيبِهِم لِتكْذِيبِهِم."],[44,44,"﴿لِيُعۡجِزَهُۥ﴾: لِيَفُوتَه."],[45,45,"﴿يُؤَاخِذُ﴾: يُعاقِبُ.\n\n﴿يُؤَخِّرُهُمۡ﴾: يُمْهِلُهُم."]]);
QTF("gharib",36,[[1,1,"﴿يسٓ﴾: سَبَقَ الكلامُ على الحروفِ المُقَطَّعَةِ في أوَّلِ سُورةِ البقرةِ."],[4,4,"﴿صِرَ ٰ⁠طࣲ مُّسۡتَقِيمࣲ﴾: طَرِيقٍ مُعْتَدِلٍ وهو الإسْلامُ."],[7,7,"﴿حَقَّ ٱلۡقَوۡلُ﴾: وجَبَ القولُ أي: العذابُ."],[8,8,"﴿أَغۡلَـٰلࣰا﴾: قُيُودًا تَشُدُّ أيدِيَهُم إلى أعناقِهِم تَحتَ أذقانِهم.\n\n﴿مُّقۡمَحُونَ﴾: رافِعُونَ رؤوسَهم غاضُّونَ أبْصارَهُم."],[9,9,"﴿سَدࣰّا﴾: حاجِزًا ومانِعًا.\n\n﴿فَأَغۡشَيۡنَـٰهُمۡ﴾: غَطَّينا أبْصارَهُم."],[11,11,"﴿أَجۡرࣲ كَرِيمٍ﴾: أجْرٍ حَسَنٍ، وهو دخولُ الجنّةِ."],[12,12,"﴿نُحۡيِ ٱلۡمَوۡتَىٰ﴾: نَبْعَثُهُم بَعْدَ الموتِ.\n\n﴿وَءَاثَـٰرَهُمۡ﴾: أي: ما أبْقَوهُ مِنَ الحسَناتِ الَّتي لايَنْقَطِعُ نَفْعُها بَعْدَ الموتِ.\n\n﴿إِمَامࣲ مُّبِينࣲ﴾: كِتابٍ واضِحٍ، وهو اللَّوحُ المحفُوظُ."],[13,13,"﴿أَصۡحَـٰبَ ٱلۡقَرۡيَةِ﴾: أهْلَ القَرْيَةِ، وهي «أنْطاكِيَةُ»."],[14,14,"﴿فَعَزَّزۡنَا بِثَالِثࣲ﴾: أي: قوَّيناهُما بِرَسُولٍ ثالِثٍ."],[18,18,"﴿تَطَيَّرۡنَا بِكُمۡ﴾: تَشاءَمْنا بِكُم.\n\n﴿لَنَرۡجُمَنَّكُمۡ﴾: لَنَقْتُلَنَّكُم رَمْيًا بالِحجارَةِ."],[19,19,"﴿طَـٰٓئِرُكُم مَّعَكُمۡ﴾: شُؤْمُكُم مَعَكُم، الذي هو كُفْرُكُم وشِرْكُكُم."],[20,20,"﴿أَقۡصَا ٱلۡمَدِينَةِ﴾: مِن مَّكانٍ بَعِيدٍ فِيها."],[22,22,"﴿فَطَرَنِي﴾: خَلَقَنِي."],[23,23,"﴿وَلَا يُنقِذُونِ﴾: لا يُنَجُّونَنِي مِمّا أنافِيه."],[24,24,"﴿ضَلَـٰلࣲ مُّبِينٍ﴾: خَطَأٍ ظاهِرٍ."],[28,28,"﴿جُندࣲ﴾: جَيشٍ."],[29,29,"﴿صَيۡحَةࣰ﴾: صَوْتًا مُهلِكًا مِنَ السَّماءِ.\n\n﴿خَـٰمِدُونَ﴾: مَيِّتُونَ لا حَراكَ فِيهِم."],[30,30,"﴿يَسۡتَهۡزِءُونَ﴾: يَسْخَرُونَ."],[31,31,"﴿مِّنَ ٱلۡقُرُونِ﴾: مِنَ الأُمَمِ الخالِيةِ."],[32,32,"﴿مُحۡضَرُونَ﴾: نُحْضِرُهُم للحسابِ والجزاءِ."],[33,33,"﴿وَءَايَةࣱ لَّهُمُ﴾: دَلالةٌ لَهُم.\n\n﴿ٱلۡأَرۡضُ ٱلۡمَيۡتَةُ﴾: هي الَّتي لا نَباتَ فِيها.\n\n﴿أَحۡيَيۡنَـٰهَا﴾: أي: بإنْزالِ المطرِ عَلَيها وإخراجِ النَّباتِ منها."],[34,34,"﴿جَنَّـٰتࣲ﴾: بَساتِينَ.\n\n﴿فَجَّرۡنَا﴾: شَقَقْنا."],[36,36,"﴿ٱلۡأَزۡوَ ٰ⁠جَ﴾: الأَصْنافَ والأَنْواعَ."],[37,37,"﴿ءَايَةࣱ لَّهُمُ﴾: علامةٌ لَهُم.\n\n﴿نَسۡلَخُ مِنۡهُ﴾: نَنْزِعُ مِنهُ."],[38,38,"﴿لِمُسۡتَقَرࣲّ لَّهَا﴾: مُسْتَقَرُّها تَحْتَ العَرْشِ، كما جاء في الحديثِ المتَّفقِ عَلَيه."],[39,39,"﴿مَنَازِلَ﴾: مسافات، وهي ثمانيةٌ وعِشْرُونَ مَنزِلًا.\n\n﴿كَٱلۡعُرۡجُونِ ٱلۡقَدِيمِ﴾: كالعِذْقِ اليابسِ المتَقَوِّسِ."],[40,40,"﴿أَن تُدۡرِكَ﴾: أن تَلْحَقَ.\n\n﴿فَلَكࣲ﴾: مَدارٍ.\n\n﴿يَسۡبَحُونَ﴾: يَدُورُونَ في فَلَكِ السَّماءِ بانْبِساطٍ وسُهُولَةٍ."],[41,41,"﴿ءَايَةࣱ لَّهُمۡ﴾: دليلٌ لَهُم.\n\n﴿ٱلۡمَشۡحُونِ﴾: الممْلُوءِ."],[43,43,"﴿صَرِيخَ لَهُمۡ﴾: مُغِيثَ لَهُم.\n\n﴿يُنقَذُونَ﴾: يُخَلَّصُونَ مِنَ الغَرَقِ."],[45,45,"﴿مَا بَيۡنَ أَيۡدِيكُمۡ﴾: مِنَ الآخرةِ وأهْوالِها.\n\n﴿وَمَا خَلۡفَكُمۡ﴾: مِن أحْوالِ الدُّنيا وعِقابِها."],[49,49,"﴿يَنظُرُونَ﴾: ينتظِرُونَ.\n\n﴿صَيۡحَةࣰ وَ ٰ⁠حِدَةࣰ﴾: هي نَفْخَةُ الفَزَعِ عِنْدَ قِيامِ السّاعةِ.\n\n﴿يَخِصِّمُونَ﴾: يَخْتَصِمُونَ في شُؤونِ حياتِهم غافِلينَ عَن يَوْمِ القيامةِ."],[50,50,"﴿تَوۡصِيَةࣰ﴾: وصِيَّةً."],[51,51,"﴿ٱلصُّورِ﴾: «القَرْنِ» الذي يُنفَخُ فيه للبعث.\n\n﴿ٱلۡأَجۡدَاثِ﴾: القُبُورِ.\n\n﴿يَنسِلُونَ﴾: يُسْرِعُونَ في الخُرُوجِ."],[52,52,"﴿يَـٰوَيۡلَنَا﴾: يا هَلاكَنا.\n\n﴿مَنۢ بَعَثَنَا﴾: مَن أحْيانا؟\n\n﴿مِن مَّرۡقَدِنَاۜ﴾: مِن قُبُورِنا."],[53,53,"﴿صَيۡحَةࣰ وَ ٰ⁠حِدَةࣰ﴾: نَفْخَةً واحِدَةً.\n\n﴿مُحۡضَرُونَ﴾: نُحْضِرُهم للحِسابِ والجَزاءِ."],[55,55,"﴿فِي شُغُلࣲ﴾: في نَعِيمٍ عَظِيمٍ يُلْهِيهِم عمّا سِواه.\n\n﴿فَـٰكِهُونَ﴾: مُتَلَذِّذُونَ."],[56,56,"﴿ٱلۡأَرَآئِكِ﴾: الأَسِرَّةِ المزَيَّنةِ."],[57,57,"﴿مَّا يَدَّعُونَ﴾: ما يَشْتَهُونَ."],[59,59,"﴿وَٱمۡتَـٰزُواْ﴾: تميَّزُوا، وانفرِدُوا عَنِ المؤمِنِينَ."],[60,60,"﴿أَعۡهَدۡ إِلَيۡكُمۡ﴾: أُوصِكُم وأُبَلِّغْكُم."],[62,62,"﴿جِبِلࣰّا﴾: خَلْقًا."],[64,64,"﴿ٱصۡلَوۡهَا﴾: ادخُلُوا جَهَنَّمَ وقاسُوا حَرَّها."],[65,65,"﴿نَخۡتِمُ﴾: نَطْبَعُ."],[66,66,"﴿لَطَمَسۡنَا عَلَىٰٓ أَعۡيُنِهِمۡ﴾: لصَيرَّناها مَمْسُوحَةً لا يُرى لها شِقٌّ ولا جَفْنٌ.\n\n﴿فَٱسۡتَبَقُواْ ٱلصِّرَ ٰ⁠طَ﴾: بادَرُوا إليه.\n\n﴿فَأَنَّىٰ يُبۡصِرُونَ﴾: فكيفَ يُبْصِرُونَ وقد طُمِسَتْ أبْصارُهُم؟"],[67,67,"﴿لَمَسَخۡنَـٰهُمۡ عَلَىٰ مَكَانَتِهِمۡ﴾: لَغَيَّرْنا خَلْقَهم في المكانِ الَّذي هم فيهِ.\n\n﴿مُضِيࣰّا﴾: أي: ذَهابًا إلى الأمامِ."],[68,68,"﴿نُّعَمِّرۡهُ﴾: نُطِلْ عُمُرَه.\n\n﴿نُنَكِّسۡهُ فِي ٱلۡخَلۡقِ﴾: نَرُدَّه إلى أرْذَلِ العُمُرِ وأَضْعَفِه."],[70,70,"﴿وَيَحِقَّ ٱلۡقَوۡلُ﴾: أي: تَجِبَ كلمةُ العذابِ."],[71,71,"﴿مِّمَّا عَمِلَتۡ أَيۡدِينَآ﴾: أي: مما أبْدَعْناهُ وعَمِلْناهُ.\n\n﴿لَهَا مَـٰلِكُونَ﴾: مالِكُونَ أمْرَها، يَتَصَرَّفُونَ بِها كيفَ شاؤُوا."],[72,72,"﴿ذَلَّلۡنَـٰهَا﴾: سَخَّرْناها لَهُم.\n\n﴿رَكُوبُهُمۡ﴾: مَرْكُوبُهم الّذي يَرْكَبُونَه."],[75,75,"﴿وَهُمۡ لَهُمۡ جُندࣱ مُّحۡضَرُونَ﴾: والحالُ أنَّ هذه الآلهةَ قَدْ أُحْضِرَتْ مُجْتَمِعَةً لِتُعايِنَ عذابَ عابِديِها، وهي لا تَسْتَطِيعُ نَصْرَهُم."],[77,77,"﴿مِن نُّطۡفَةࣲ﴾: هي مَنِيُّ الرَّجُلِ يقْذِفُه في رَحمِ امْرَأتِه.\n\n﴿خَصِيمࣱ﴾: كثيرُ الخُصُومَةِ بالباطلِ."],[78,78,"﴿رَمِيمࣱ﴾: باليةٌ مُتفَتِّتةٌ."],[79,79,"﴿أَنشَأَهَآ﴾: خَلَقَها."],[80,80,"﴿مِّنۡهُ تُوقِدُونَ﴾: تَقْدَحُونَ منه."],[83,83,"﴿مَلَكُوتُ﴾: هو المُلْكُ التّامُّ للأشياءِ كلِّها."]]);
QTF("gharib",37,[[1,1,"﴿وَٱلصَّـٰٓفَّـٰتِ﴾: هي الملائِكَةُ التي تَصْطَفُّ في عِبادَتِها."],[2,2,"﴿فَٱلزَّ ٰ⁠جِرَ ٰ⁠تِ﴾: هي الملائكةُ التي تَزْجُرُ السَّحابَ وتَسُوقُه."],[3,3,"﴿ذِكۡرًا﴾: هو القرآنُ."],[6,6,"﴿ٱلۡكَوَاكِبِ﴾: النُّجُومِ."],[7,7,"﴿مَّارِدࣲ﴾: مُتَمَرِّدٍ خارجٍ عَنِ الطّاعةِ."],[8,8,"﴿وَيُقۡذَفُونَ﴾: ويُرجَمُونَ (بالشُّهُبِ)."],[9,9,"﴿دُحُورࣰا﴾: إبْعادًا وطَرْدًا.\n\n﴿وَاصِبٌ﴾: دائمٌ لا يَنْقَطِعُ."],[10,10,"﴿خَطِفَ ٱلۡخَطۡفَةَ﴾: أي: اسْتَرَقَ السَّمْعَ خِلْسةً.\n\n﴿فَأَتۡبَعَهُۥ﴾: تَبِعَه ولحِقَه.\n\n﴿شِهَابࣱ ثَاقِبࣱ﴾: نَجْمٌ مُضِيءٌ."],[11,11,"﴿لَّازِبِۭ﴾: مُلْتَزِقٍ بَعْضُه ببَعْضٍ."],[12,12,"﴿وَيَسۡخَرُونَ﴾: يَسْتَهْزِئُونَ بِكَ."],[14,14,"﴿ءَايَةࣰ﴾: مُعْجِزَةً مِن مُّعْجِزاتِكَ.\n\n﴿يَسۡتَسۡخِرُونَ﴾: يبالِغُونَ في سُخْرِيَّتِهِم."],[18,18,"﴿دَ ٰ⁠خِرُونَ﴾: أذِلّاءُ صاغِرُونَ."],[19,19,"﴿زَجۡرَةࣱ وَ ٰ⁠حِدَةࣱ﴾: نَفْخَةٌ واحِدَةٌ."],[20,20,"﴿يَـٰوَيۡلَنَا﴾: يا هَلاكَنا."],[21,21,"﴿يَوۡمُ ٱلۡفَصۡلِ﴾: يومُ القضاءِ بَيْنَ الخَلْقِ."],[22,22,"﴿ٱحۡشُرُواْ﴾: اجْمَعُوا.\n\n﴿وَأَزۡوَ ٰ⁠جَهُمۡ﴾: قُرَناءَهُم ونُظراءَهُم."],[23,23,"﴿فَٱهۡدُوهُمۡ إِلَىٰ صِرَ ٰ⁠طِ ٱلۡجَحِيمِ﴾: دُلُّوهُم إلى طَرِيقِ النّارِ، وسُوقُوهُم إليها."],[24,24,"﴿وَقِفُوهُمۡ﴾: احْبِسُوهُم في مَوْقِفِ الحِسابِ."],[26,26,"﴿مُسۡتَسۡلِمُونَ﴾: مُنْقادُونَ أذلّاءُ لِعَجِزِهِم عَنِ الحِيلَةِ."],[28,28,"﴿عَنِ ٱلۡيَمِينِ﴾: أي: عَنِ النّاحيةِ الَّتي كان مِنها الحقُّ، فَتَصْرِفُونَنا عَنْها."],[30,30,"﴿طَـٰغِينَ﴾: متجاوِزِينَ الحَدَّ في الكُفْرِ والضَّلالِ."],[31,31,"﴿فَحَقَّ﴾: ثَبَتَ ووَجَبَ."],[32,32,"﴿فَأَغۡوَيۡنَـٰكُمۡ﴾: فأَضْلَلْناكُم.\n\n﴿غَـٰوِينَ﴾: ضالِّيِنَ."],[45,45,"﴿يُطَافُ﴾: يُدارُ.\n\n﴿بِكَأۡسࣲ﴾: بِكأسٍ مِن خمْرٍ.\n\n﴿مَّعِينِۭ﴾: نابِعٍ مِنَ العُيوَنِ."],[47,47,"﴿لَا فِيهَا غَوۡلࣱ﴾: لا أذىً فيها ولا مَكْروهٌ على شاربيها.\n\n﴿وَلَا هُمۡ عَنۡهَا يُنزَفُونَ﴾: ولا هم عَن شُرْبِها تَذْهَبُ عُقُولُهم، أي: لا تُنزَفُ عُقُولُهم كما يُنْزَفَ دَمُ الجَرِيحِ."],[48,48,"﴿قَـٰصِرَ ٰ⁠تُ ٱلطَّرۡفِ﴾: حُورٌ قَصَرْنَ نَظَرَهُنَّ على أزْواجِهِنَّ.\n\n﴿عِينࣱ﴾: جَمْعُ «عَيناءَ»: واسعةُ العَينِ حَسَنَتُها."],[49,49,"﴿مَّكۡنُونࣱ﴾: مَصُونٌ لم يَمْسَسْهُ أحَدٌ."],[51,51,"﴿قَرِينࣱ﴾: صاحِبٌ مُلازِمٌ."],[53,53,"﴿لَمَدِينُونَ﴾: لَمَجْزِيُّونَ ومُحاسَبُونَ."],[55,55,"﴿سَوَآءِ ٱلۡجَحِيمِ﴾: وسَطِها."],[56,56,"﴿تَٱللَّهِ﴾: واللهِ.\n\n﴿كِدتَّ﴾: قارَبْتَ.\n\n﴿لَتُرۡدِينِ﴾: لَتُهْلِكُنِي."],[57,57,"﴿ٱلۡمُحۡضَرِينَ﴾: أي: في العذابِ مِثلَك."],[62,62,"﴿نُّزُلًا﴾: ما يُهَيَّأُ للنَّزيلِ إكْرامًا لهُ.\n\n﴿شَجَرَةُ ٱلزَّقُّومِ﴾: الشَّجَرَةُ الخَبيَثةُ الملعُونةُ ذاتُ الثَّمرِ المُرِّ الكرِيهِ الرّائِحَةِ."],[63,63,"﴿فِتۡنَةࣰ لِّلظَّـٰلِمِينَ﴾: مِحْنَةً لَهُم لِكَوْنِهِم يُعَذَّبُونَ بِها في الآخِرةِ."],[64,64,"﴿تَخۡرُجُ﴾: تَنْبُتُ.\n\n﴿أَصۡلِ ٱلۡجَحِيمِ﴾: قَعْرِ جَهَنَّمَ."],[65,65,"﴿طَلۡعُهَا﴾: ثَمَرُها.\n\n﴿كَأَنَّهُۥ رُءُوسُ ٱلشَّيَـٰطِينِ﴾: تشبيهٌ للمَحْسُوسِ بالمتَخَيَّلِ؛ لِتناهِيهِ في البَشاعَةِ والقُبْحِ."],[67,67,"﴿لَشَوۡبࣰا﴾: لخَلْطًا ومِزاجًا.\n\n﴿مِّنۡ حَمِيمࣲ﴾: الماءِ الحارِّ الشَّديدِ الحرارةِ."],[68,68,"﴿مَرۡجِعَهُمۡ﴾: مَرَدَّهُم.\n\n﴿ٱلۡجَحِيمِ﴾: جَهَنَّمَ."],[69,69,"﴿أَلۡفَوۡاْ﴾: وجَدُوا."],[70,70,"﴿يُهۡرَعُونَ﴾: يُسْرِعُونَ إلى متابعةِ آبائِهِم الضّالِّينَ."],[72,72,"﴿مُّنذِرِينَ﴾: مُرسَلِينَ."],[76,76,"﴿ٱلۡكَرۡبِ ٱلۡعَظِيمِ﴾: الغَرَقِ بالطُّوفانِ العظيمِ."],[78,78,"﴿ٱلۡـَٔاخِرِينَ﴾: الَّذينَ جاؤُوا بَعْدَه."],[82,82,"﴿ٱلۡـَٔاخَرِينَ﴾: الباقِينَ الَّذين كذَّبوُا نوحًا عليه الصَّلاةُ والسَّلامُ."],[83,83,"﴿شِيعَتِهِۦ﴾: أي: جَماعَتِهِ الَّذينَ هُمُ الأنبِياءُ والمرْسَلُونَ عليهم الصَّلاةُ والسَّلامُ."],[86,86,"﴿أَئِفۡكًا﴾: أكَذِبًا وباطِلًا."],[88,88,"﴿فَنَظَرَ﴾: تَأَمَّلَ."],[89,89,"﴿سَقِيمࣱ﴾: مَرِيضٌ."],[90,90,"﴿فَتَوَلَّوۡاْ عَنۡهُ مُدۡبِرِينَ﴾: فانصَرَفُوا عنه مُعْرِضِين."],[91,91,"﴿فَرَاغَ إِلَىٰٓ﴾: ذَهَبَ خُفْيَةً."],[93,93,"﴿فَرَاغَ عَلَيۡهِمۡ﴾: مالَ وأَقْبَل عَلَيهِم.\n\n﴿بِٱلۡيَمِينِ﴾: أي: بيَدِه اليُمْنى."],[94,94,"﴿يَزِفُّونَ﴾: يُسْرِعُونَ في مَشْيِهِم."],[95,95,"﴿تَنۡحِتُونَ﴾: تَبْرُونَ وتَقْشِرُونَ بِأَيْدِيكُم."],[97,97,"﴿ٱلۡجَحِيمِ﴾: النّارِ الشَّديدةِ الاتِّقادِ."],[98,98,"﴿ٱلۡأَسۡفَلِينَ﴾: المقْهُورِينَ المغْلُوبِينَ."],[101,101,"﴿حَلِيمࣲ﴾: أي: عِنْدَما يَكْبَر."],[103,103,"﴿أَسۡلَمَا﴾: اسْتَسْلَما لأمْرِ اللهِ وانْقادا لَه.\n\n﴿وَتَلَّهُۥ لِلۡجَبِينِ﴾: أي: أضْجَعَه على جَبينِه على الأرضِ."],[106,106,"﴿ٱلۡبَلَـٰٓؤُاْ ٱلۡمُبِينُ﴾: الاخْتِبارُ الواضِحُ."],[107,107,"﴿بِذِبۡحٍ عَظِيمࣲ﴾: بكَبْشٍ مَذْبُوحٍ عَظِيمِ القَدْرِ."],[108,108,"﴿عَلَيۡهِ﴾: أي: على ذِكْرِه الحَسَنِ.\n\n﴿فِي ٱلۡـَٔاخِرِينَ﴾: في الأُمَمِ التي جاءتْ بَعْدَه."],[115,115,"﴿مِنَ ٱلۡكَرۡبِ ٱلۡعَظِيمِ﴾: أي: مِنَ الغَرَقِ وتَسَلُّطِ فِرْعَونَ."],[119,119,"﴿عَلَيۡهِمَا﴾: أي: على ذِكْرِهِما الحَسَنِ.\n\n﴿فِي ٱلۡـَٔاخِرِينَ﴾: في الأمَمِ الَّتي جاءَتْ بَعْدَهُما."],[125,125,"﴿بَعۡلࣰا﴾: وهو اسْمٌ لِصَنَمٍ كانُوا يَعْبُدُونَهُ.\n\n﴿وَتَذَرُونَ﴾: تَتْرُكُونَ."],[127,127,"﴿لَمُحۡضَرُونَ﴾: أي: لِلْحِسابِ والعِقابِ."],[129,129,"﴿عَلَيۡهِ﴾: أي: على ذِكْرِه الحَسَنِ.\n\n﴿فِي ٱلۡـَٔاخِرِينَ﴾: في الأُمَمِ الَّتي جاءَتْ بَعْدَهُ."],[135,135,"﴿فِي ٱلۡغَـٰبِرِينَ﴾: الباقِينَ في العذابِ."],[136,136,"﴿دَمَّرۡنَا﴾: أهْلَكْنا.\n\n﴿ٱلۡـَٔاخَرِينَ﴾: الباقِينَ مِن قَومِ لُوطٍ عَلَيهِ السَّلامُ الَّذينَ لم يُؤْمِنُوا بِهِ."],[137,137,"﴿مُّصۡبِحِينَ﴾: داخِلِينَ وقْتَ الصَّباحِ."],[140,140,"﴿أَبَقَ﴾: هَرَبَ.\n\n﴿ٱلۡمَشۡحُونِ﴾: المَمْلُوءِ."],[141,141,"﴿فَسَاهَمَ﴾: اقْتَرَعَ وقَبِلَ القُرْعَةَ.\n\n﴿ٱلۡمُدۡحَضِينَ﴾: المَغْلُوبِينَ بالقُرْعَةِ."],[142,142,"﴿فَٱلۡتَقَمَهُ﴾: فابْتَلَعَه.\n\n﴿مُلِيمࣱ﴾: آتٍ بما يُلامُ عَلَيهِ."],[143,143,"﴿ٱلۡمُسَبِّحِينَ﴾: بِذِكْرِ اللهِ وكَثْرةِ العِبادةِ."],[144,144,"﴿لَلَبِثَ﴾: لمَكَثَ."],[145,145,"﴿فَنَبَذۡنَـٰهُ﴾: طَرَحْناه.\n\n﴿بِٱلۡعَرَآءِ﴾: بِأرْضٍ خاليةٍ عاريةٍ من الشَّجرِ والبناءِ.\n\n﴿سَقِيمࣱ﴾: ضَعِيفُ البَدَنِ بسَبِبِ حَبْسِهِ في بَطْنِ الحُوتِ."],[146,146,"﴿يَقۡطِينࣲ﴾: القَرْعِ."],[151,151,"﴿إِفۡكِهِمۡ﴾: من كَذِبِهِم وافْتِرائِهِم."],[153,153,"﴿أَصۡطَفَى﴾: هل اخْتارَ؟"],[156,156,"﴿سُلۡطَـٰنࣱ مُّبِينࣱ﴾: حُجَّةٌ واضِحةٌ."],[158,158,"﴿وَبَيۡنَ ٱلۡجِنَّةِ﴾: بَيْنَ الملائِكَةِ.\n\n﴿لَمُحۡضَرُونَ﴾: أي: لِلْعَذابِ."],[162,162,"﴿بِفَـٰتِنِينَ﴾: بمُضِلِّينَ ومُفْسِدِينَ أحَدًا."],[163,163,"﴿صَالِ ٱلۡجَحِيمِ﴾: يَدْخُلُ النارَ، ويُقاسي حَرَّها."],[165,165,"﴿ٱلصَّآفُّونَ﴾: الواقِفُونَ صُفُوفًا."],[166,166,"﴿ٱلۡمُسَبِّحُونَ﴾: المُنَزِّهُونَ للهِ والمُقَدِّسُونَ له عَن كُلِّ ما لا يَلِيقُ بِه."],[168,168,"﴿ذِكۡرࣰا مِّنَ ٱلۡأَوَّلِينَ﴾: أي: كِتابًا مِن كُتُبِ الأوَّلِينَ كالتَّوراةِ والإنْجِيلِ."],[170,170,"﴿فَكَفَرُواْ بِهِۦ﴾: أي: فَجاءَهُم الرَّسُولُ بالقرآنِ فَكَفَرُوا بِهِ."],[177,177,"﴿بِسَاحَتِهِمۡ﴾: بِفِنائِهِم، والمرادُ: القَومُ."]]);
QTF("gharib",38,[[2,2,"﴿عِزَّةࣲ﴾: تكبُّرٍ عَنِ الحقِّ.\n\n﴿وَشِقَاقࣲ﴾: مُشاقَّةٍ ومُخالَفةٍ للهِ ولِرَسُولِهِ."],[3,3,"﴿كَمۡ أَهۡلَكۡنَا﴾: كَثِيرًا أهْلَكْنا.\n\n﴿مِّن قَرۡنࣲ﴾: مِن أُمَّةٍ.\n\n﴿فَنَادَواْ﴾: فاسْتَغاثُوا حِينَ عايَنُوا العَذابَ.\n\n﴿وَّلَاتَ﴾: ولَيسَ.\n\n﴿حِينَ مَنَاصࣲ﴾: وقتَ فِرارٍ."],[4,4,"﴿مُّنذِرࣱ مِّنۡهُمۡ﴾: رَسُولٌ مِنهُم."],[5,5,"﴿عُجَابࣱ﴾: عَجِيبٌ."],[6,6,"﴿ٱلۡمَلَأُ﴾: أشْرافُ القوم ورُؤساؤُهُم.\n\n﴿أَنِ ٱمۡشُواْ﴾: أنِ امْضُوا على ما كُنتُم عَلَيهِ ولا تَدْخُلُوا في دِينِه.\n\n﴿وَٱصۡبِرُواْ عَلَىٰٓ ءَالِهَتِكُمۡ﴾: أي: اثبُتُوا على عِبادَتِها.\n\n﴿لَشَيۡءࣱ يُرَادُ﴾: أي: شَيءٌ مُدَبَّرٌ يُريدُهُ محمدٌ بِنا وبآلَهتِنا؛ لِيَتَحَكَّمَ فِينا بِما يُرِيدُ."],[7,7,"﴿ٱلۡمِلَّةِ ٱلۡـَٔاخِرَةِ﴾: هي النَّصْرانِيَّةُ، أو دِينُ قُرَيشٍ.\n\n﴿إِلَّا ٱخۡتِلَـٰقٌ﴾: إلا كَذِبٌ اختَلَقَهُ محمدٌ وافْتَراهُ."],[10,10,"﴿فَلۡيَرۡتَقُواْ﴾: فَلْيَصْعَدُوا.\n\n﴿ٱلۡأَسۡبَـٰبِ﴾: المعارِجِ إلى السَّماءِ."],[11,11,"﴿جُندࣱ مَّا هُنَالِكَ﴾: أي: هَؤُلاءِ الجُنْدُ المكذِّبُونَ الَّذينَ هُم في عِزَّةٍ وشِقاقٍ.\n\n﴿مَهۡزُومࣱ مِّنَ ٱلۡأَحۡزَابِ﴾: سَيُهْزَمُ هَذا الجُنْدُ ويُغلَبُ، كما هُزِمَ الَّذينَ مِن قَبْلِهِم مِنَ الأحْزابِ المكَذِّبِينَ."],[12,12,"﴿ٱلۡأَوۡتَادِ﴾: صاحِبُ القُوَّةِ العظِيمةِ مِنَ الجُنُودِ والمبانِي الشّاهِقَةِ."],[13,13,"﴿وَأَصۡحَـٰبُ لۡـَٔيۡكَةِ﴾: أصْحابُ الأشْجارِ والبَساتِينِ."],[14,14,"﴿فَحَقَّ عِقَابِ﴾: فحَلَّ بهم عِقابِي وعَذابي."],[15,15,"﴿يَنظُرُ﴾: يَنْتَظِرُ.\n\n﴿صَيۡحَةࣰ وَ ٰ⁠حِدَةࣰ﴾: نَفْخَةً واحِدةً في الصُّورِ.\n\n﴿مَّا لَهَا مِن فَوَاقࣲ﴾: مالها مِن تَوقُّفٍ مِقْدارَ فَواقِ ناقَةٍ: وهو مابيَن حَلْبَتَيها مِنَ المدَّةِ القلِيلَةِ."],[16,16,"﴿قِطَّنَا﴾: نصيبَنا مِنَ العذابِ."],[17,17,"﴿ذَا ٱلۡأَيۡدِ﴾: صاحِبَ القُوَّةِ.\n\n﴿أَوَّابٌ﴾: كَثِيرُ الرُّجُوعِ إلى اللهِ وطاعَتِهِ عَن كُلِّ ما يَكْرَهُهُ."],[18,18,"﴿بِٱلۡعَشِيِّ﴾: بآخِرِ النَّهارِ.\n\n﴿وَٱلۡإِشۡرَاقِ﴾: أوَّلِ النَّهارِ."],[19,19,"﴿وَٱلطَّيۡرَ مَحۡشُورَةࣰ﴾: أي: سَخَّرْنا الطَّيرَ مَجْمُوعَةً إليهِ تُسَبِّحُ اللهَ مَعَهُ."],[20,20,"﴿وَشَدَدۡنَا مُلۡكَهُۥ﴾: أي: قَوَّيْناهُ بأسْبابِ القُوَّةِ كُلِّها.\n\n﴿ٱلۡحِكۡمَةَ﴾: النُّبوَّةَ.\n\n﴿وَفَصۡلَ ٱلۡخِطَابِ﴾: أي: الفَصْلَ في الكَلامِ والخُصُوماتِ."],[21,21,"﴿نَبَؤُاْ ٱلۡخَصۡمِ﴾: خبرُ المتخاصِمَينِ.\n\n﴿تَسَوَّرُواْ ٱلۡمِحۡرَابَ﴾: تَسَلَّقُوا مَكانَ عِبادَتِهِ وأتَوهُ مِن أعلى سُورِهِ."],[22,22,"﴿فَفَزِعَ﴾: فَخافَ.\n\n﴿بَغَىٰ﴾: ظَلَمَ وتَعدّى.\n\n﴿بِٱلۡحَقِّ﴾: بالعَدْلِ.\n\n﴿وَلَا تُشۡطِطۡ﴾: لا تَجُرْ في حُكْمِكَ.\n\n﴿وَٱهۡدِنَآ﴾: أرْشِدْنا.\n\n﴿سَوَآءِ ٱلصِّرَ ٰ⁠طِ﴾: وسَطِ الطَّرِيقِ وهو الطَّرِيقُ الحقُّ."],[23,23,"﴿أَكۡفِلۡنِيهَا﴾: أعْطِنيها حتّى أكْفَلَها.\n\n﴿وَعَزَّنِي﴾: غَلَبَني.\n\n﴿فِي ٱلۡخِطَابِ﴾: في المُحاجَّةِ الكَلامِيَّةِ."],[24,24,"﴿ٱلۡخُلَطَآءِ﴾: الشُّركاءِ.\n\n﴿لَيَبۡغِي﴾: لَيَظْلِمُ ويَتَعَدّى.\n\n﴿وَظَنَّ﴾: أيْقَنَ.\n\n﴿فَتَنَّـٰهُ﴾: ابْتَلَيناهُ وامْتَحَنّاه.\n\n﴿وَخَرَّ رَاكِعࣰا﴾: سَقَطَ ساجِدًا للهِ.\n\n﴿وَأَنَابَ﴾: رَجَعَ إلى اللهِ بالتَّوبَةِ."],[25,25,"﴿لَزُلۡفَىٰ﴾: لقُرْبةً ومَكانَةً.\n\n﴿وَحُسۡنَ مَـَٔابࣲ﴾: حُسْنَ مَرْجِعٍ في الآخِرَةِ، وهو الجنَّةُ."],[26,26,"﴿بِٱلۡحَقِّ﴾: بالعَدْلِ والإنْصافِ.\n\n﴿ٱلۡهَوَىٰ﴾: أي: هَوى النَّفْسِ المُخالِفَ لِلْحَقِّ.\n\n﴿بِمَا نَسُواْ يَوۡمَ ٱلۡحِسَابِ﴾: أي: بِسَبَبِ تَرْكِهِم العَمَلَ لِيومِ الحِسابِ."],[27,27,"﴿بَـٰطِلࣰا﴾: لَعِبًا وعَبَثًا.\n\n﴿فَوَيۡلࣱ﴾: فَهَلاكٌ."],[29,29,"﴿لِّيَدَّبَّرُوٓاْ﴾: لِيَتَفكَّرُوا.\n\n﴿وَلِيَتَذَكَّرَ﴾: ليتَّعِظَ.\n\n﴿أُوْلُواْ ٱلۡأَلۡبَـٰبِ﴾: أصْحابُ العُقُولِ السَّلِيمَةِ."],[30,30,"﴿أَوَّابٌ﴾: توّابٌ كثيرُ الرُّجُوعِ إلى اللهِ."],[31,31,"﴿بِٱلۡعَشِيِّ﴾: بآخِرِ النَّهارِ (مِن بَعْدِ الزَّوالِ إلى الغُرُوبِ).\n\n﴿ٱلصَّـٰفِنَـٰتُ﴾: الخُيُولُ الأصِيلةُ الواقِفَةُ على ثَلاثِ قَوائِمَ وطرفِ حافِرِ الرّابِعَةِ.\n\n﴿ٱلۡجِيَادُ﴾: السَّريعَةُ في الجَرْي."],[32,32,"﴿أَحۡبَبۡتُ حُبَّ ٱلۡخَيۡرِ﴾: آثَرْتُ حُبَّ الخيلِ.\n\n﴿تَوَارَتۡ بِٱلۡحِجَابِ﴾: غَرَبَتِ الشَّمسُ."],[33,33,"﴿فَطَفِقَ مَسۡحَۢا بِٱلسُّوقِ وَٱلۡأَعۡنَاقِ﴾: فَشَرَعَ يَقْطَعُ سُوقَها وأعْناقَها بالسَّيفِ."],[34,34,"﴿فَتَنَّا﴾: ابتَلَينا.\n\n﴿جَسَدࣰا﴾: شِقَّ ولَدٍ وُلِد لَهُ.\n\n﴿أَنَابَ﴾: رَجَعَ إلى اللهِ بالتَّوبَةِ."],[36,36,"﴿فَسَخَّرۡنَا لَهُ﴾: فَذَلَّلْنا لَه.\n\n﴿رُخَآءً﴾: لَيِّنةً طَيِّعةً.\n\n﴿حَيۡثُ أَصَابَ﴾: حيثُ أرادَ."],[37,37,"﴿بَنَّآءࣲ﴾: يَبْنِي لَهُ ما يشاءُ.\n\n﴿وَغَوَّاصࣲ﴾: يَغُوصُ في البحْرِ لاسْتِخْراجِ نَفائِسِه."],[38,38,"﴿مُقَرَّنِينَ فِي ٱلۡأَصۡفَادِ﴾: مُقَيَّدين في الأغْلالِ والسَّلاسِلِ."],[39,39,"﴿فَٱمۡنُنۡ أَوۡ أَمۡسِكۡ﴾: فأعْطِ مَن شِئْتَ، وامنَعْ مَن شِئْتَ."],[40,40,"﴿لَزُلۡفَىٰ﴾: لَقُرْبةً وكَرامةً.\n\n﴿وَحُسۡنَ مَـَٔابࣲ﴾: حُسْنَ مَرْجِعٍ في الآخِرَةِ، وهو الجَنّةُ."],[41,41,"﴿بِنُصۡبࣲ﴾: بِتَعَبٍ ومَشَقَّةٍ.\n\n﴿وَعَذَابٍ﴾: ألَمٍ وضُرٍّ."],[42,42,"﴿ٱرۡكُضۡ بِرِجۡلِكَ﴾: اضْرِبْ بِها الأرْضَ."],[43,43,"﴿أَهۡلَهُۥ﴾: زَوْجَهُ ووَلَدَهُ.\n\n﴿وَمِثۡلَهُم مَّعَهُمۡ﴾: وزِدْناهُ مِثْلَهُم بَنِينَ وحَفَدَةً.\n\n﴿لِأُوْلِي ٱلۡأَلۡبَـٰبِ﴾: لأصْحابِ العُقُولِ السَّلِيمَةِ."],[44,44,"﴿ضِغۡثࣰا﴾: حُزْمَةً مِنَ الحَشِيشِ ونَحْوِهِ.\n\n﴿وَلَا تَحۡنَثۡ﴾: لا تَتْرُكِ الوفاءَ بِيَمِينِكَ.\n\n﴿أَوَّابࣱ﴾: رَجّاعٌ إلى طاعَةِ اللهِ."],[45,45,"﴿أُوْلِي ٱلۡأَيۡدِي﴾: أصْحابَ القُوى في طاعةِ اللهِ.\n\n﴿وَٱلۡأَبۡصَـٰرِ﴾: البصائرِ في الدِّينِ."],[46,46,"﴿أَخۡلَصۡنَـٰهُم بِخَالِصَةࣲ﴾: خَصَصْناهُم واصْطَفَيناهُم بِخاصَّةٍ عَظِيمَةٍ.\n\n﴿ذِكۡرَى ٱلدَّارِ﴾: ذِكْرِ الدّارِ الآخرةِ في قُلُوبِهِم."],[47,47,"﴿ٱلۡمُصۡطَفَيۡنَ﴾: الَّذينَ اخْتَرْناهُم لِرِسالَتِنا وطاعَتِنا.\n\n﴿ٱلۡأَخۡيَارِ﴾: الُمخْتارِينَ الفضلاءِ المُخْتَصِّينَ بالخيرِ."],[49,49,"﴿ذِكۡرࣱ﴾: عِظَةٌ وشَرَفٌ لك أيُّها الرسولُ ولِقَومِكَ.\n\n﴿مَـَٔابࣲ﴾: مَصِيرٍ."],[50,50,"﴿جَنَّـٰتِ عَدۡنࣲ﴾: جَنّاتِ إقامَةٍ."],[51,51,"﴿مُتَّكِـِٔينَ﴾: جالِسِينَ مُتَمَكِّنِينَ على السُّرُرِ.\n\n﴿يَدۡعُونَ﴾: يَطْلُبُونَ."],[52,52,"﴿قَـٰصِرَ ٰ⁠تُ ٱلطَّرۡفِ﴾: لا يَمْدُدْنَ أبْصارَهُنَّ إلى غَيْرِ أزْواجِهِنَّ.\n\n﴿أَتۡرَابٌ﴾: مُتَساوِياتٌ في السِّنِّ."],[54,54,"﴿نَّفَادٍ﴾: فَناءٍ وانْقِطاعِ."],[55,55,"﴿لِلطَّـٰغِينَ﴾: الُمتَجاوِزِينَ الحَدَّ في الكُفْرِ والمعاصِي.\n\n﴿مَـَٔابࣲ﴾: مَرْجِعٍ ومَصِيرٍ."],[56,56,"﴿يَصۡلَوۡنَهَا﴾: يُعذَّبُونَ فِيها، تَغْمُرُهُم مِن جَمِيعِ جَوانِبِهِم.\n\n﴿ٱلۡمِهَادُ﴾: الفِراشُ."],[57,57,"﴿حَمِيمࣱ﴾: ماءٌ شَدِيدُ الحَرارَةِ.\n\n﴿وَغَسَّاقࣱ﴾: صَدِيدٌ سائِلٌ مِن أجْسادِ أهْلِ النّارِ."],[58,58,"﴿وَءَاخَرُ﴾: عَذابٌ آخَرُ.\n\n﴿شَكۡلِهِۦٓ﴾: مِثْلِه.\n\n﴿أَزۡوَ ٰ⁠جٌ﴾: أصْنافٌ وألْوانٌ."],[59,59,"﴿فَوۡجࣱ﴾: جَماعَةٌ عَظِيمةٌ.\n\n﴿مُّقۡتَحِمࣱ﴾: داخِلٌ.\n\n﴿صَالُواْ ٱلنَّارِ﴾: مُقاسُونَ حَرَّها."],[60,60,"﴿قَدَّمۡتُمُوهُ لَنَا﴾: بَدَأْتُم بالكُفْرِ قَبْلنا وسَنَنْتُمُوهُ لَنا.\n\n﴿ٱلۡقَرَارُ﴾: دارُ الاسْتِقْرارِ، وهي جَهَنَّمُ."],[61,61,"﴿ضِعۡفࣰا﴾: مُضاعَفًا."],[63,63,"﴿أَتَّخَذۡنَـٰهُمۡ سِخۡرِيًّا﴾: هَلْ أخْطأنا في تَحْقِيرِنا لَهُم، واسْتِهْزائِنا بِهِم؟\n\n﴿زَاغَتۡ﴾: لم تَقَعْ عَلَيهِم."],[64,64,"﴿ذَ ٰ⁠لِكَ﴾: جِدالَ أهْلِ النّارِ وخِصامَهُم."],[65,65,"﴿ٱلۡقَهَّارُ﴾: الَّذي قَهَرَ كُلَّ شَيءٍ وغَلَبَهُ."],[67,67,"﴿نَبَؤٌاْ عَظِيمٌ﴾: خَبَرٌ عظِيمُ النَّفْعِ."],[69,69,"﴿بِٱلۡمَلَإِ ٱلۡأَعۡلَىٰٓ﴾: مَلائِكَةِ السَّماءِ."],[72,72,"﴿رُّوحِي﴾: رُوحِ الحَياةِ الَّتي يَخْلُقُها اللهُ.\n\n﴿فَقَعُواْ لَهُۥ سَـٰجِدِينَ﴾: فاسْجُدُوا لَهُ سُجُودَ تَحِيَّةٍ وإكْرامٍ، لا سُجُودَ عِبادَةٍ وتَعْظِيمٍ."],[75,75,"﴿أَسۡتَكۡبَرۡتَ﴾: أتَعَظَّمْتَ وتَكَبَّرْتَ الآنَ عَنِ السُّجُودِ لآدَمَ؟\n\n﴿أَمۡ كُنتَ مِنَ ٱلۡعَالِينَ﴾: أم كُنْتَ مِنَ الُمتَكَبِّرِينَ عَلى رَبِكَ مِن قَبْلُ."],[77,77,"﴿رَجِيمࣱ﴾: مَطْرُودٌ."],[78,78,"﴿لَعۡنَتِيٓ﴾: طَرْدِي وإبْعادِي.\n\n﴿ٱلدِّينِ﴾: الجَزاءِ."],[79,79,"﴿فَأَنظِرۡنِيٓ﴾: فأخِّرْ أجَلِي، ولا تُهْلِكْنِي."],[80,80,"﴿ٱلۡمُنظَرِينَ﴾: المُؤَخَّرِينَ."],[81,81,"﴿إِلَىٰ يَوۡمِ ٱلۡوَقۡتِ ٱلۡمَعۡلُومِ﴾: إلى يومِ النَّفْخَةِ الأُولى الَّتي يَمُوتُ مِنها مَن بَقِيَ مِنَ الخلائِقِ."],[83,83,"﴿ٱلۡمُخۡلَصِينَ﴾: الَّذينَ أخْلَصْتَهُم لِعِبادَتِكَ وعَصَمْتَهم من إضْلالِ الشَّيطانِ."],[86,86,"﴿ٱلۡمُتَكَلِّفِينَ﴾: الُمتَقَوِّلينَ للقُرآنِ مِن تِلْقاءِ نَفْسِي."],[87,87,"﴿ذِكۡرࣱ﴾: تَذْكِيرٌ."],[88,88,"﴿نَبَأَهُۥ﴾: خَبَرَ صِدْقِ القُرآنِ.\n\n﴿بَعۡدَ حِينِۭ﴾: حِينَ يَغْلِبُ الإسْلامُ، وحيِنَ يَقَعُ عَلَيكُم العَذابُ."]]);
QTF("gharib",39,[[3,3,"﴿ٱلدِّينُ ٱلۡخَالِصُ﴾: الطّاعَةُ التّامَّةُ السّالِمَةُ مِنَ الشِّرْكِ.\n\n﴿زُلۡفَىٰٓ﴾: قُرْبى."],[4,4,"﴿لَّٱصۡطَفَىٰ﴾: لاخْتارَ.\n\n﴿ٱلۡقَهَّارُ﴾: الَّذي قَهَرَ خَلْقَه بِقُدْرَتِهِ، فَكُلُّ شَيءٍ لَهُ مُتَذَلِّلٌ خاضِعٌ."],[5,5,"﴿يُكَوِّرُ ٱلَّيۡلَ عَلَى ٱلنَّهَارِ﴾: يُدْخِلُ الليلَ على النَّهارِ.\n\n﴿وَيُكَوِّرُ ٱلنَّهَارَ عَلَى ٱلَّيۡلِ﴾: يُدْخِلُ النَّهارَ على الليلِ.\n\n﴿وَسَخَّرَ﴾: ذَلَّل.\n\n﴿لِأَجَلࣲ مُّسَمًّى﴾: إلى حِينِ قِيامِ السّاعةِ."],[6,6,"﴿نَّفۡسࣲ وَ ٰ⁠حِدَةࣲ﴾: آدَمَ عَلَيهِ السَّلامُ.\n\n﴿وَأَنزَلَ﴾: خَلَقَ.\n\n﴿مِّنَ ٱلۡأَنۡعَـٰمِ ثَمَـٰنِيَةَ أَزۡوَ ٰ⁠جࣲ﴾: ثمانيةَ أنْواعٍ ذَكَرًا وأُنْثى مِنَ الإبِلِ والبَقَرِ والضَّأنِ والَمعْزِ.\n\n﴿خَلۡقࣰا مِّنۢ بَعۡدِ خَلۡقࣲ﴾: طَوْرًا بَعْدَ طَورِ مِنَ الخَلْقِ.\n\n﴿ظُلُمَـٰتࣲ ثَلَـٰثࣲ﴾: ظُلُماتِ البَطْنِ والرَّحِمِ والَمشِيمَةِ.\n\n﴿فَأَنَّىٰ تُصۡرَفُونَ﴾: فَكَيفَ تَعْدِلُونَ عَنْ عِبادَةِ رَبِّكُم إلى عِبادَةِ غَيْرِه؟"],[7,7,"﴿وَلَا تَزِرُ وَازِرَةࣱ وِزۡرَ أُخۡرَىٰ﴾: ولا تُؤْخَذُ نَفْسٌ بإثْمِ غَيْرِها.\n\n﴿بِذَاتِ ٱلصُّدُورِ﴾: بأسْرارِ النُّفُوسِ وما تُخْفِيهِ."],[8,8,"﴿مُنِيبًا﴾: تائِبًا إليِهِ.\n\n﴿خَوَّلَهُۥ﴾: مَنَحَه.\n\n﴿أَندَادࣰا﴾: شُرَكاءَ.\n\n﴿تَمَتَّعۡ بِكُفۡرِكَ قَلِيلًا﴾: تَمَتَّعْ بالسَّلامَةِ مِنَ العَذابِ زَمَنًا قَلِيلًا."],[9,9,"﴿قَـٰنِتٌ﴾: عابدٌ لِرَبِّهِ، طائِعٌ لَهُ.\n\n﴿ءَانَآءَ﴾: ساعاتِ.\n\n﴿أُوْلُواْ ٱلۡأَلۡبَـٰبِ﴾: أصْحابُ العُقُولِ السَّلِيمَةِ."],[10,10,"﴿حَسَنَةࣱ﴾: في الدُّنيا بالعافِيةِ، وفي الآخِرةِ بالجنَّةِ.\n\n﴿بِغَيۡرِ حِسَابࣲ﴾: مِن غَيْرِ حَدٍّ ولا مِقْدارٍ."],[12,12,"﴿أَوَّلَ ٱلۡمُسۡلِمِينَ﴾: أوَّلَ مَن أسْلَمَ مِن أُمَّتِي."],[15,15,"﴿فَٱعۡبُدُواْ مَا شِئۡتُم﴾: صِيغَةُ أمْرٍ على جِهَةِ التَّهْدِيدِ."],[16,16,"﴿ظُلَلࣱ﴾: جَمْعُ ظُلَّةٍ قِطَعُ عَذابٍ كالسَّحابِ العظِيمِ.\n\n﴿عِبَادَهُۥ﴾: كُلَّ عَبْدٍ مِنَ النّاسِ مِن مُّؤْمِنٍ وكافِرٍ."],[17,17,"﴿ٱلطَّـٰغُوتَ﴾: كُلَّ ما عُبِدَ مِن دُونِ اللهِ مِن شَيطانٍ وغَيرِهِ.\n\n﴿وَأَنَابُوٓاْ﴾: وتابُوا."],[18,18,"﴿أَحۡسَنَهُۥٓ﴾: أرْشَدَهُ، وأَحْسَنُ الكَلامِ كَلامُ اللهِ ثُمَّ كَلامُ رَسُولِهِ.\n\n﴿أُوْلُواْ ٱلۡأَلۡبَـٰبِ﴾: أصْحابُ العُقُولِ السَّليمَةِ."],[19,19,"﴿حَقَّ﴾: وجَبَ."],[20,20,"﴿غُرَفࣱ﴾: منازِلُ عالِيةٌ في الجنُّةِ."],[21,21,"﴿ٱلسَّمَآءِ﴾: السَّحابِ.\n\n﴿مَآءࣰ﴾: مَطَرًا.\n\n﴿فَسَلَكَهُۥ﴾: فأدْخَلَه.\n\n﴿يَنَـٰبِيعَ﴾: جَمْعُ يَنْبُوعٍ وهو العينُ الكَثِيرةُ النَّبعِ التي لا يَنضُبُ ماؤُها.\n\n﴿يَهِيجُ﴾: يَيْبَسُ بَعْدَ خُضْرتِهِ ونَضارَتِهِ.\n\n﴿حُطَـٰمًا﴾: مُتَكَسِّرًا مُتَفَتِّتًا.\n\n﴿لِأُوْلِي ٱلۡأَلۡبَـٰبِ﴾: لِأَصْحابِ العُقُول السَّلِيمَةِ."],[22,22,"﴿شَرَحَ ٱللَّهُ صَدۡرَهُۥ لِلۡإِسۡلَـٰمِ﴾: وسَّعَ اللهُ صدْرَهُ بالإيمانِ بِهِ والإسْلامِ.\n\n﴿فَوَيۡلࣱ﴾: فَهَلاكٌ.\n\n﴿لِّلۡقَـٰسِيَةِ قُلُوبُهُم مِّن ذِكۡرِ ٱللَّهِ﴾: الَّذينَ غَلُظَتْ قُلُوبُهُم وأَعْرَضَتْ عَن ذِكْرِ اللهِ."],[23,23,"﴿أَحۡسَنَ ٱلۡحَدِيثِ﴾: القرآنَ العَظِيمَ.\n\n﴿مُّتَشَـٰبِهࣰا﴾: يُشْبِهُ بَعْضُه بَعْضًا في الحُسْنِ والإحْكامِ وعَدَمِ الاخْتِلافِ.\n\n﴿مَّثَانِيَ﴾: تُثَنّى فيه وتُكَرَّرُ القِصَصُ والأَحْكامُ والحُجَجُ والبَيِّناتُ.\n\n﴿تَقۡشَعِرُّ﴾: تَتَقَبَّضُ وتَتَغَيَّرُ بِسَبَبِ الخوفِ.\n\n﴿تَلِينُ﴾: تَطْمئِنُّ وتَسْكُنُ."],[24,24,"﴿أَفَمَن يَتَّقِي بِوَجۡهِهِۦ سُوٓءَ ٱلۡعَذَابِ﴾: أفمن يُلْقى في النّارِ مكْتُوفًا فلا يَقْدِرُ أن يَتَّقِيَ النّارَ إلا بِوجْهِهِ كَمَن هُو مُنَعَّمٌ في الجنَّةِ؟"],[25,25,"﴿مِنۡ حَيۡثُ لَا يَشۡعُرُونَ﴾: مِنَ الموضِعِ الَّذي لا يعلَمُونَ بِمَجِيءِ العَذابِ مِنهُ."],[26,26,"﴿ٱلۡخِزۡيَ﴾: العَذابَ والهَوانَ."],[27,27,"﴿ضَرَبۡنَا﴾: ذَكَرْنا ووَصَفْنا.\n\n﴿مَثَلࣲ﴾: نَبَأٍ عَظِيمٍ يَدْعُو إلى الاعْتِبارِ ويَسْتَوجِبُ الإيمانَ."],[28,28,"﴿غَيۡرَ ذِي عِوَجࣲ﴾: لا لَبْسَ فِيهِ ولا اخْتِلافَ."],[29,29,"﴿رَّجُلࣰا فِيهِ شُرَكَآءُ﴾: عَبْدًا مَمْلُوكًا لِشُرَكاءَ.\n\n﴿مُتَشَـٰكِسُونَ﴾: متنازِعُونَ، سَيِّئةٌ أخْلاقُهُم.\n\n﴿سَلَمࣰا لِّرَجُلٍ﴾: خالِصًا لِرَجُلٍ واحِدٍ.\n\n﴿مَثَلًا﴾: حالًَا."],[32,32,"﴿فَمَنۡ أَظۡلَمُ﴾: لا أحَدَ أظْلَمُ.\n\n﴿بِٱلصِّدۡقِ﴾: بالقرآنِ.\n\n﴿مَثۡوࣰى﴾: مأوىً ومَسْكَنٌ."],[33,33,"﴿بِٱلصِّدۡقِ﴾: لا إلَهَ إلّا اللهُ.\n\n﴿وَصَدَّقَ بِهِۦٓ﴾: مَن آمَنَ بالقُرْآنِ مِن نَّبِيِّ اللهِ وأَتْباعِهِ."],[36,36,"﴿بِكَافٍ عَبۡدَهُۥ﴾: حامِي رَسُولِهِ مُحَمَّدٍ ﷺ.\n\n﴿مِن دُونِهِۦ﴾: بالَّذِينَ يَعْبُدُونَ مِن دُونِهِ وهُمُ الأَصْنامُ.\n\n﴿مِن دُونِهِۦ﴾: آلهَتِهِم الَّذين يَزْعُمُون أنها سَتُؤْذِيكَ."],[37,37,"﴿وَمَن يَهۡدِ ٱللَّهُ﴾: ومَن يُوفِّقْه اللهُ للإيمانِ بهِ والعملِ بِكِتابِهِ."],[38,38,"﴿مُمۡسِكَـٰتُ رَحۡمَتِهِۦ﴾: حابِساتُ رَحْمَتِهَ.\n\n﴿حَسۡبِيَ ٱللَّهُ﴾: كافيَّ اللهُ.\n\n﴿يَتَوَكَّلُ﴾: يَعْتَمِدُ ويُفَوِّضُ أمْرَهُ."],[39,39,"﴿ٱعۡمَلُواْ عَلَىٰ مَكَانَتِكُمۡ﴾: اعْمَلُوا على حالَتِكُم الَّتِي رَضَيتُمُوها لِأَنْفُسِكُم."],[40,40,"﴿يُخۡزِيهِ﴾: يُهينُهُ.\n\n﴿مُّقِيمٌ﴾: دائِمٌ."],[41,41,"﴿فَلِنَفۡسِهِۦ﴾: فَنَفْعُ هِدايتِهِ لِنَفْسِهِ.\n\n﴿يَضِلُّ عَلَيۡهَا﴾: يَعُودُ ضَرَرُ ضَلالِهِ عَلى نَفْسِهِ.\n\n﴿بِوَكِيلٍ﴾: بِحَفِيظٍ ومَسْؤُولٍ عَنْ أعْمالِهِم."],[43,43,"﴿شُفَعَآءَ﴾: جَمْعُ شَفِيعٍ وهو الَّذِي يَطْلُبُ مِن غَيْرِه قَضاءَ حاجةِ شَخْصٍ آخَرَ، والمرادُ، واللهُ أعلمُ، ما يعبُدُونَه مِن دُونِ اللهِ."],[44,44,"﴿قُل لِّلَّهِ ٱلشَّفَـٰعَةُ﴾: لِأَنَّ شَفاعةَ غَيرِهِ مَوقُوفَةٌ على إذْنِهِ سُبحانَه للشّافِعِ ورِضاهُ عَنِ المشْفُوعِ لَهُ، فلا تُطْلَبُ مِن هؤلاءِ الآلِهَةِ."],[45,45,"﴿ٱشۡمَأَزَّتۡ﴾: نَفَرَتْ.\n\n﴿مِن دُونِهِۦٓ﴾: وهُمُ الأَصْنامُ والأَوْثانُ والأَوْلِياءُ."],[46,46,"﴿فَاطِرَ﴾: هُوَ الخالِقُ والُمبْدِعُ عَلى غَيرِ مِثالٍ.\n\n﴿تَحۡكُمُ﴾: تَفْصِلُ وتَقْضِي."],[47,47,"﴿وَبَدَا﴾: وظَهَرَ.\n\n﴿يَحۡتَسِبُونَ﴾: يَظُنُونَ أنَّهُ واقِعٌ بِهِم."],[48,48,"﴿وَحَاقَ بِهِم﴾: ونَزَلَ وأَحاطَ بِهِم."],[49,49,"﴿خَوَّلۡنَـٰهُ﴾: أعْطَيناهُ تَفَضُّلًا مِنّا.\n\n﴿عَلَىٰ عِلۡمِۭ﴾: عَلى خَيرٍ عِنْدِي.\n\n﴿فِتۡنَةࣱ﴾: بَلْوى يَبْتَلِي اللهُ بِها عِبادَهُ لِيَنْظُرَ مَن يَشْكُرُهُ مِمَّنْ يَكْفُرُهُ."],[50,50,"﴿فَمَآ أَغۡنَىٰ عَنۡهُم﴾: ما دَفَعَ عَنْهُمُ العَذابَ."],[51,51,"﴿سَيِّـَٔاتُ مَا كَسَبُواْ﴾: جَزاءُ سَيِّئاتِهِم وهو العَذابُ.\n\n﴿وَمَا هُم بِمُعۡجِزِينَ﴾: وماهُمْ بِفائِتِينَ اللهَ ولا سابِقِيهِ."],[52,52,"﴿وَيَقۡدِرُ﴾: ويُضَيِّقُ."],[53,53,"﴿أَسۡرَفُواْ عَلَىٰٓ أَنفُسِهِمۡ﴾: تَمادَوا في المَعاصِي والكَبائِر.\n\n﴿لَا تَقۡنَطُواْ﴾: لا تَيْئَسُوا."],[54,54,"﴿وَأَنِيبُوٓاْ﴾: ارْجِعُوا إلى رَبِّكُم بالتَّوبَةِ والطّاعةِ.\n\n﴿وَأَسۡلِمُواْ لَهُۥ﴾: واخْضَعُوا لَهُ بالطّاعةِ والإقْرارِ بَتَوْحِيدِهِ وإخْلاصِ العِبادةِ لَهُ.\n\n﴿لَا تُنصَرُونَ﴾: لا تُمنَعُونَ."],[55,55,"﴿أَحۡسَنَ مَآ أُنزِلَ إِلَيۡكُم مِّن رَّبِّكُم﴾: هو القُرآنُ العظِيمُ، وفِيهِ الخبرُ والأمْرُ بالحَسَنِ والأَحْسَنِ، ومُقْتَضاهُ فِيهِ حَسَنٌ وأَحْسَنُ، وإن كانَ في نَفْسِه أحْسَنَ الحَدِيثِ.\n\n﴿بَغۡتَةࣰ﴾: فَجْأةً."],[56,56,"﴿أَن تَقُولَ﴾: لِئَلّا تَقُولَ.\n\n﴿يَـٰحَسۡرَتَى﴾: يا نَدَمِي؛ اغْتِمامًا عَلى ما فاتَ.\n\n﴿مَا فَرَّطتُ﴾: ما ضَيَّعْتُ في الدُّنيا مِنَ العَمَلِ بِما أمَرَنِي اللهُ بِه.\n\n﴿فِي جَنۢبِ ٱللَّهِ﴾: في طاعَتِهِ.\n\n﴿ٱلسَّـٰخِرِينَ﴾: المُسْتَهْزِئِينَ بِأمْرِ اللهِ وكِتابِهِ ورَسُولِهِ والمؤُمِنِينَ."],[58,58,"﴿كَرَّةࣰ﴾: رَجْعَةً إلى الحياةِ الدُّنيا."],[60,60,"﴿مَثۡوࣰى﴾: مأوىً ومَسْكَنٌ."],[61,61,"﴿بِمَفَازَتِهِمۡ﴾: بِسَبِبِ فَوْزِهِم بالأَعْمالِ الصّالِحَةِ.\n\n﴿ٱلسُّوٓءُ﴾: أذى جَهَنَّمَ."],[62,62,"﴿وَكِيلࣱ﴾: حَفِيظٌ يُدَبِّرُ جَمِيعَ شَؤُونِ خَلْقِهِ."],[63,63,"﴿مَقَالِيدُ﴾: مَفاتِيحُ خَزائِن."],[65,65,"﴿لَيَحۡبَطَنَّ﴾: لَيَبْطُلَنَّ."],[67,67,"﴿وَمَا قَدَرُواْ ٱللَّهَ حَقَّ قَدۡرِهِۦ﴾: ما عَظَّمُوا اللهَ حَقَّ تعظِيمِهِ إذْ عَبَدُوا مَعَهُ غَيرَهُ.\n\n﴿قَبۡضَتُهُۥ﴾: في قَبْضَتِه عَلى ما يَلِيقُ بِه."],[68,68,"﴿ٱلصُّورِ﴾: الَقْرنِ الَّذِي يُنْفخُ فِيهِ.\n\n﴿فَصَعِقَ﴾: فَماتَ مِنَ الفَزَعِ وشِدَّةِ الصَّوْتِ.\n\n﴿أُخۡرَىٰ﴾: هي نَفْخَةُ البَعْثِ.\n\n﴿يَنظُرُونَ﴾: يُبْصِرُونَ، لِكَمالِ حياتِهِم."],[69,69,"﴿وَأَشۡرَقَتِ﴾: أضاءَتْ.\n\n﴿ٱلۡأَرۡضُ﴾: أرْضُ القِيامَةِ.\n\n﴿وَوُضِعَ ٱلۡكِتَـٰبُ﴾: ونَشَرَتِ الملائِكةُ صَحِيفَةَ كُلِّ فَرْدٍ.\n\n﴿وَٱلشُّهَدَآءِ﴾: هُمُ الَّذِينَ يَشْهَدُونَ على النّاسِ بأعْمالِهِم."],[71,71,"﴿وَسِيقَ﴾: وحُثَّ الكافِرُونَ على السَّيرِ بِعْنْفٍ.\n\n﴿زُمَرًا﴾: جماعاتٍ مُتَفَرِّقةً، بَعْضُهُم عَلى إثْرِ بَعْضٍ.\n\n﴿حَقَّتۡ﴾: وجَبَتْ.\n\n﴿كَلِمَةُ ٱلۡعَذَابِ﴾: قَضاءُ اللهِ بالعَذابِ."],[72,72,"﴿فَبِئۡسَ﴾: فَقَبُحَ.\n\n﴿مَثۡوَى﴾: مَصِيرُ."],[73,73,"﴿وَسِيقَ﴾: وحُثَّ المتَّقُونَ عَلى السَّيرِ مُكَرَّمِينَ.\n\n﴿زُمَرًا﴾: جماعاتٍ مُتَفَرِّقةً، بعضُهم على إثْرِ بَعْضٍ.\n\n﴿طِبۡتُمۡ﴾: طابَتْ أحْوالُكُم."],[74,74,"﴿ٱلۡأَرۡضَ﴾: أرْضَ الجنَّةِ.\n\n﴿نَتَبَوَّأُ﴾: نَنْزِلُ."],[75,75,"﴿حَآفِّينَ﴾: مُحِيطِينَ بجَوانِبِ العَرْشِ.\n\n﴿ٱلۡعَرۡشِ﴾: هو سَرِيرُ الُملْكِ الَّذي اسْتَوى عَلَيهِ الَّرحمنُ، وتَحْمِلُهُ الملائِكَةُ، وهو أعْظَمُ المَخْلُوقاتِ، وهو سَقْفُ الجنَّةِ.\n\n﴿يُسَبِّحُونَ﴾: يُنَزِّهُونَ."]]);
QTF("gharib",40,[[1,1,"﴿حمٓ﴾: انْظُرْ أوَّلَ سورة البقرةِ."],[3,3,"﴿ٱلتَّوۡبِ﴾: التَّوبَةِ.\n\n﴿ذِي ٱلطَّوۡلِ﴾: صاحِبِ الإنْعامِ والتفضُّلِ على عبادِهِ الطّائِعِينَ.\n\n﴿إِلَيۡهِ ٱلۡمَصِيرُ﴾: إلى اللهِ مَرْجِعُكُم أيُّها الخَلْقُ."],[4,4,"﴿فَلَا يَغۡرُرۡكَ﴾: فلا يَخْدَعْكَ.\n\n﴿تَقَلُّبُهُمۡ فِي ٱلۡبِلَـٰدِ﴾: تَرَدُّدُهُم وتَصَرُّفُهُم في البِلادِ بأنْواعِ التِّجاراتِ والمكاسِبِ."],[5,5,"﴿وَٱلۡأَحۡزَابُ﴾: الأُمَمُ الَّتي اجْتَمَعتْ عَلى تَكْذِيبِ رُسُلِها كَعادٍ وثَمُودَ.\n\n﴿لِيَأۡخُذُوهُ﴾: لِيقْتُلُوهُ.\n\n﴿لِيُدۡحِضُواْ بِهِ﴾: لِيُبْطِلُوا بِجِدالِهِم.\n\n﴿فَأَخَذۡتُهُمۡ﴾: فَعاقَبْتُهُمْ."],[6,6,"﴿حَقَّتۡ﴾: وجَبَتْ وثَبَتَتْ.\n\n﴿كَلِمَتُ رَبِّكَ﴾: كَلِمَةُ العذابِ وهي قولُه تَعالى: (لَأَمۡلَأَنَّ جَهَنَّمَ مِنكَ ومِمَّن تَبِعَكَ مِنۡهُمۡ أجۡمَعِينَ)."],[7,7,"﴿ٱلۡعَرۡشَ﴾: هو سَرِيرُ المُلْكِ الَّذيِ اسْتَوى عَلَيهِ الَّرحْمنُ، وتَحْمِلُهُ الملائِكَةُ، وهُوَ أعْظَمُ المَخْلُوقاتِ، وهو سَقْفُ الجنَّةِ.\n\n﴿وَمَنۡ حَوۡلَهُۥ﴾: أي: الملائِكةُ الذين يَحُفُّونَ بالعرْشِ.\n\n﴿يُسَبِّحُونَ﴾: يُنَزِّهُونَ.\n\n﴿وَقِهِمۡ﴾: وجَنِّبْهُم.\n\n﴿عَذَابَ ٱلۡجَحِيمِ﴾: عذابَ النّارِ."],[8,8,"﴿جَنَّـٰتِ عَدۡنٍ﴾: بساتين إقامَةٍ دائِمَةٍ."],[9,9,"﴿وَقِهِمُ ٱلسَّيِّـَٔاتِ﴾: واصْرِفْ عَنْهُم سُوءَ عاقِبَةِ سيِّئاتِهِم."],[10,10,"﴿لَمَقۡتُ ٱللَّهِ﴾: بُغْضُ اللهِ لَكُم.\n\n﴿مَّقۡتِكُمۡ أَنفُسَكُمۡ﴾: بُغْضِكُم لِأَنْفُسِكُم الآنَ بَعْدَ أنْ أدْرَكْتُم أنّكُم تَسْتَحِقُّونَ سَخَطَ اللهِ وعَذابَهُ."],[11,11,"﴿أَمَتَّنَا ٱثۡنَتَيۡنِ﴾: أمَتَّنا مَرَّتَينِ: حِينَ كُنّا نُطَفًا في بُطُونِ أمَّهاتِنا قَبْلَ نَفْخِ الرُّوحِ وحِينَ انْقَضى أجَلُنا في الحياةِ الدُّنيا.\n\n﴿وَأَحۡيَيۡتَنَا ٱثۡنَتَيۡنِ﴾: وأَحْيَيْتَنا مَرَّتَينِ: في دارِ الدُّنيا، يَوْمَ وُلِدْنا، ويَوْمَ بُعِثْنا مِن قُبُورِنا.\n\n﴿خُرُوجࣲ﴾: أي: مِنَ النّارِ."],[12,12,"﴿ٱلۡعَلِيِّ﴾: العاِلي عَلى خَلْقِهِ ذاتًا وقُدْرَةً وقَهْرًا."],[13,13,"﴿ءَايَـٰتِهِۦ﴾: دَلائِلَ عَظَمَتِه الَّتي تَظْهَرُ في هَذا العالَمِ.\n\n﴿رِزۡقࣰا﴾: مَطَرًا هُوَ سَبَبُ رِزْقِكُم.\n\n﴿يُنِيبُ﴾: يَرْجِعُ إلى طاعَةِ اللهِ."],[14,14,"﴿ٱلدِّينَ﴾: العِبادَةَ والدُّعاءَ."],[15,15,"﴿رَفِيعُ ٱلدَّرَجَـٰتِ﴾: ارْتَفَعَتْ دَرَجاتُه ارْتِفاعًا بايَنَ بِهِ مَخْلُوقاتِهِ.\n\n﴿ٱلرُّوحَ﴾: الوَحْيَ الَّذِي يَحْيَوْنَ بِهِ.\n\n﴿يَوۡمَ ٱلتَّلَاقِ﴾: يومَ القِيامةِ الَّذِي يَلْتَقِي فِيهِ الأولُونَ والآخِرُونَ."],[16,16,"﴿بَـٰرِزُونَ﴾: يَظْهَرُونَ أمامَ رَبِّهِم.\n\n﴿ٱلۡقَهَّارِ﴾: الَّذِي قَهَرَ جَميعَ الخَلائِقِ، فَكُلُّها تَحْتَ تَصَرُّفِهِ وتَدْبِيرِهِ فَلا تَتَحَرَّكُ ولا تَسْكُنُ إلّا بِإْذِنِهِ."],[18,18,"﴿يَوۡمَ ٱلۡـَٔازِفَةِ﴾: يَوْمَ القِيامَةِ القريبَ وإنِ اسْتَبْعَدُوهُ.\n\n﴿ٱلۡحَنَاجِرِ﴾: جَمْعِ حَنْجَرةٍ، وهي الحُلْقُومُ.\n\n﴿كَـٰظِمِينَ﴾: مُمْتلِئِين غمًّا وحُزْنًا.\n\n﴿حَمِيمࣲ﴾: قَرِيبٍ وصاحِبٍ.\n\n﴿شَفِيعࣲ﴾: يَشْفَعُ لَهُم عنْدَ رَبِّهِمِ.\n\n﴿يُطَاعُ﴾: يُسْتَجابُ لَهُ."],[19,19,"﴿خَآئِنَةَ ٱلۡأَعۡيُنِ﴾: ما تَخْتَلِسُهُ العُيُونُ مِن نَّظَراتٍ."],[20,20,"﴿يَقۡضِي بِٱلۡحَقِّ﴾: يَحْكُمُ بالعَدْلِ.\n\n﴿لَا يَقۡضُونَ بِشَيۡءٍ﴾: لا يَحْكُمُونَ بِشَيءٍ؛ لأنّ هذه الآلهةَ لا تَعْلَمُ شَيئًا ولا تَقْدِرُ عَلى شَيءٍ."],[21,21,"﴿عَـٰقِبَةُ ٱلَّذِينَ كَانُواْ مِن قَبۡلِهِمۡ﴾: خاتِمةُ ومَصِيرُ الأُمَمِ السّابِقةِ قَبْلَهُم.\n\n﴿وَءَاثَارࣰا فِي ٱلۡأَرۡضِ﴾: وأبْقى آثارًَا مِنهُم في الأَرْضِ يُسْتَدَلُّ بِها عَلى قُوَّتِهِم.\n\n﴿فَأَخَذَهُمُ﴾: فَأَهْلَكَهُم.\n\n﴿وَاقࣲ﴾: دافعٍ يَدْفَعُ عَنْهُم عَذابَ اللهِ."],[23,23,"﴿وَسُلۡطَـٰنࣲ﴾: حُجَّةٍ."],[25,25,"﴿وَٱسۡتَحۡيُواْ نِسَآءَهُمۡ﴾: اسْتَبْقُوا نِساءَهم لِلْخِدْمَةِ والاسْتِرْقاقِ.\n\n﴿وَمَا كَيۡدُ ٱلۡكَـٰفِرِينَ إِلَّا فِي ضَلَـٰلࣲ﴾: وما تَدْبِيرُ الكافِرِينَ إلا في ذَهابٍ وهَلاكٍ."],[26,26,"﴿ذَرُونِيٓ﴾: اتْرُكُونِي.\n\n﴿ٱلۡأَرۡضِ﴾: أرْضِ مِصْرَ."],[27,27,"﴿عُذۡتُ﴾: لَجَأْتُ واسْتَجَرْتُ."],[28,28,"﴿يُصِبۡكُم﴾: يَلْحَقْكُم.\n\n﴿يَعِدُكُمۡ﴾: يَتَوَعَّدُكُم بهِ مِنَ العُقُوبَةِ.\n\n﴿مُسۡرِفࣱ﴾: مُتَجاوِزٌ لِلْحَدِّ بالشِّرْكِ والقَتْلِ بِغَيْرِ حَقٍّ."],[29,29,"﴿ظَـٰهِرِينَ﴾: غالِبينَ.\n\n﴿ٱلۡأَرۡضِ﴾: أرْضِ مِصْرَ.\n\n﴿فَمَن يَنصُرُنَا﴾: فَمَن يَدْفَعُ عَنّا.\n\n﴿بَأۡسِ ٱللَّهِ﴾: عَذابِ اللهِ.\n\n﴿مَآ أُرِيكُمۡ إِلَّا مَآ أَرَىٰ﴾: ما أُرِيكُم مِّنَ الرّأيِ والنَّصِيحَةِ إلّا ما أرى لِنَفْسِي ولَكُم صَلاحًا وصَوابًا.\n\n﴿سَبِيلَ ٱلرَّشَادِ﴾: طَرِيقَ الحقِّ والصَّوابِ."],[30,30,"﴿يَوۡمِ ٱلۡأَحۡزَابِ﴾: يَوْمِ عَذابِ الَّذينَ تَجَمَّعُوا على أنبيائِهِم فَأَهْلكَهُم اللهُ."],[31,31,"﴿دَأۡبِ﴾: عادَةِ."],[32,32,"﴿يَوۡمَ ٱلتَّنَادِ﴾: يَومَ يُنادِي فِيه بعضُ النّاسِ بَعْضًا مِن هَوْلِ الموقِفِ."],[33,33,"﴿تُوَلُّونَ﴾: تَذْهَبُونَ وتَنْصَرِفُونَ.\n\n﴿مُدۡبِرِينَ﴾: ذاهِبِينَ هارِبِينَ.\n\n﴿عَاصِمࣲ﴾: مانِعٍ يَمْنَعُكُم."],[34,34,"﴿بِٱلۡبَيِّنَـٰتِ﴾: الدَّلائِلِ الُمظْهِرَةِ أنّهُ رَسُول مِنَ اللهِ.\n\n﴿هَلَكَ﴾: ماتَ.\n\n﴿مُسۡرِفࣱ﴾: مُتَجاوِزٌ لِلْحَقِّ.\n\n﴿مُّرۡتَابٌ﴾: شاكٌّ في وحْدانِيَّةِ اللهِ."],[35,35,"﴿سُلۡطَـٰنٍ﴾: حُجَّةٍ مَقْبُولةٍ.\n\n﴿يَطۡبَعُ ٱللَّهُ﴾: يَخْتِمُ اللهُ.\n\n﴿جَبَّارࣲ﴾: الَّذِي يُكْرِهُ الناسَ عَلى ما لا يُحِبُّونَ عَمَلَه لِظُلْمِهِ."],[36,36,"﴿صَرۡحࣰا﴾: بِناءً عَظِيمًا.\n\n﴿ٱلۡأَسۡبَـٰبَ﴾: أبْوابَ السَّمَواتِ وما يُوصِلُنِي إلَيها."],[37,37,"﴿كَيۡدُ﴾: احْتِيالُ.\n\n﴿تَبَابࣲ﴾: خَسارٍ وبَوارٍ."],[39,39,"﴿مَتَـٰعࣱ﴾: تَمَتُّعٌ في مُدَّةٍ قَلِيلَةٍ.\n\n﴿ٱلۡقَرَارِ﴾: الدَّوامِ في المكانِ."],[40,40,"﴿بِغَيۡرِ حِسَابࣲ﴾: بَغَيرِ تَقْتِيرٍ."],[43,43,"﴿لَا جَرَمَ﴾: حَقًّا.\n\n﴿لَيۡسَ لَهُۥ دَعۡوَةࣱ﴾: لا يَمْلِكُ إجابَةَ دَعْوَةِ الدّاعِينَ.\n\n﴿مَرَدَّنَآ﴾: مَصِيرَنا.\n\n﴿ٱلۡمُسۡرِفِينَ﴾: المتَعَدِّينَ حُدُودَهُ بالشِّرْكِ باللهِ."],[44,44,"﴿وَأُفَوِّضُ أَمۡرِيٓ إِلَى ٱللَّهِ﴾: وأَتَوَكَّلُ عَلى اللهِ وأَلْجَأُ إلَيهِ وأَعْتَصِمُ بِهِ."],[45,45,"﴿سَيِّـَٔاتِ مَا مَكَرُواْ﴾: عُقُوباتِ مَكْرِ فِرْعَونَ وآلِهِ.\n\n﴿وَحَاقَ﴾: وحَلَّ."],[46,46,"﴿يُعۡرَضُونَ عَلَيۡهَا﴾: يُشاهِدُونَ مَقاعِدَهُم في النّارِ.\n\n﴿غُدُوࣰّا﴾: أوَّلَ النَّهارِ.\n\n﴿وَعَشِيࣰّا﴾: آخِرَ النَّهارِ."],[47,47,"﴿يَتَحَآجُّونَ﴾: يتخاصَمُونَ.\n\n﴿نَصِيبࣰا﴾: قِسْطًا."],[50,50,"﴿بِٱلۡبَيِّنَـٰتِ﴾: بالحُجَجِ الواضِحَةِ.\n\n﴿إِلَّا فِي ضَلَـٰلٍ﴾: إلّا في ضَياعٍ."],[51,51,"﴿وَيَوۡمَ يَقُومُ ٱلۡأَشۡهَـٰدُ﴾: يَوْمَ القِيامةِ، فَيُشْهَدُ للرُّسُلِ بالتَّبْلِيغِ، وعَلى الكُفّارِ بالتَّكْذِيبِ."],[52,52,"﴿وَلَهُمُ ٱللَّعۡنَةُ﴾: ولَهُم الطَّرْدُ مِن رحْمَةِ اللهِ.\n\n﴿سُوٓءُ ٱلدَّارِ﴾: الدّارُ السَّيِّئَةُ في الآخِرَةِ وهي النّارُ."],[53,53,"﴿ٱلۡكِتَـٰبَ﴾: التَّوراةَ."],[54,54,"﴿لِأُوْلِي ٱلۡأَلۡبَـٰبِ﴾: لِأصْحابِ العُقُولِ السَّلِيمةِ."],[55,55,"﴿بِٱلۡعَشِيِّ﴾: آخِرِ النَّهارِ.\n\n﴿وَٱلۡإِبۡكَـٰرِ﴾: أوَّلِ النَّهارِ."],[56,56,"﴿سُلۡطَـٰنٍ﴾: بُرْهانٍ وحُجَّةٍ."],[58,58,"﴿ٱلۡمُسِيٓءُ﴾: مَن كَفَرَ بِاللهِ وخالفَ أمْرَهُ."],[60,60,"﴿ٱدۡعُونِيٓ﴾: خُصُّونِي بِدُعاءِ العِبادةِ ودُعاءِ المسْأَلةِ.\n\n﴿يَسۡتَكۡبِرُونَ عَنۡ عِبَادَتِي﴾: يَتَكَبَّرُونَ عَنْ إفْرادِي بالعِبادَةِ.\n\n﴿دَاخِرِينَ﴾: صاغِرِينَ ذَلِيلِينَ."],[61,61,"﴿لِتَسۡكُنُواْ﴾: لِتَهْدَؤُوا فِيهِ مِنَ الحرَكَةِ والتَّعَبِ.\n\n﴿مُبۡصِرًا﴾: مُضِيئًا يُبْصِرُ فِيهِ النّاسُ."],[62,62,"﴿فَأَنَّىٰ تُؤۡفَكُونَ﴾: فَكَيفَ تُصْرَفُونَ عَنِ الحقِّ والصَّوابِ فَتَعْدِلُونَ عَنِ الإيمانِ باللهِ، وتَعْبُدُونَ غَيرَه؟"],[63,63,"﴿يُؤۡفَكُ﴾: يُصْرَفُ عَنِ الحقِّ.\n\n﴿بِـَٔايَـٰتِ ٱللَّهِ﴾: مُعْجِزاتِهِ.\n\n﴿يَجۡحَدُونَ﴾: يُكَذِّبُونَ."],[64,64,"﴿قَرَارࣰا﴾: مَكانَ اسْتِقْرارٍ، ويَسَّرَ لَكُم الإقامَةَ عَلَيها.\n\n﴿بِنَآءࣰ﴾: سَقْفًا للأَرْضِ.\n\n﴿وَصَوَّرَكُمۡ فَأَحۡسَنَ صُوَرَكُمۡ﴾: وخَلَقَكُم في أكْمَلِ هَيْئَةٍ، وأحْسَنِ تَقْويمٍ.\n\n﴿فَتَبَارَكَ ٱللَّهُ﴾: فَتَكاثَر خَيْرُهُ وفَضْلُهُ وبَرَكتُهُ."],[65,65,"﴿ٱلۡحَيُّ﴾: الموصُوفُ بالحياةِ الحقِيقِيَّةِ الكامِلةِ.\n\n﴿ٱلدِّينَ﴾: الطّاعَةَ."],[66,66,"﴿ٱلۡبَيِّنَـٰتُ﴾: دَلائلُ التَّوحِيدِ.\n\n﴿أُسۡلِمَ﴾: أخْضَعَ وأنقادَ بالطّاعةِ التامَّةِ."],[67,67,"﴿نُّطۡفَةࣲ﴾: مَنِيٍّ.\n\n﴿عَلَقَةࣲ﴾: دَمٍ غَلِيظٍ أحْمَرَ.\n\n﴿لِتَبۡلُغُوٓاْ أَشُدَّكُمۡ﴾: ليَتِمّ خَلْقُكُم، وتَتَكامَلَ قُواكُم ويَتَناهى شَبابُكُم.\n\n﴿شُيُوخࣰا﴾: جَمْعُ شَيخ، وهو مَن بَلَغَ سِنّ الخمْسِينَ إلى آخِرِ عُمُرِهِ."],[70,70,"﴿بِٱلۡكِتَـٰبِ﴾: بالقرآنِ."],[71,71,"﴿ٱلۡأَغۡلَـٰلُ﴾: جَمْعُ غُلٍّ، وهو القَيْدُ يُقَيَّدُ بِه، فَتُجْعَلُ العُنُقُ في وسطِه.\n\n﴿وَٱلسَّلَـٰسِلُ﴾: جَمْعُ سِلْسِلةٍ، وهي مَجْمُوعُ حِلَقٍ غَلِيظَةٍ مِن حَدِيدٍ مُتَّصِلٍ بَعْضُها بِبَعْضٍ.\n\n﴿يُسۡحَبُونَ﴾: يُجَرُّونَ."],[72,72,"﴿ٱلۡحَمِيمِ﴾: الماءِ الحارِّ الَّذِي اشْتَدَّ غَلَيانُه وحَرّهُ.\n\n﴿يُسۡجَرُونَ﴾: يُوقَدُ بِهِم."],[74,74,"﴿ضَلُّواْ عَنَّا﴾: غابُوا عَنْ عُيُونِنا."],[75,75,"﴿تَفۡرَحُونَ﴾: تَفْرَحُونَ بِما تَقْتَرِفُونَهُ مِنَ المعاصِي والآثامِ.\n\n﴿تَمۡرَحُونَ﴾: تَبْطَرُونَ وتَبغُونَ على عِبادِ اللهِ."],[76,76,"﴿مَثۡوَى ٱلۡمُتَكَبِّرِينَ﴾: مَنزِلُهُم."],[78,78,"﴿بِـَٔايَةٍ﴾: بِمُعْجِزَةٍ.\n\n﴿أَمۡرُ ٱللَّهِ﴾: بِنُزُولِ العَذابِ على الكُفّارِ.\n\n﴿ٱلۡمُبۡطِلُونَ﴾: الَّذين يَتَّبِعُونَ الباطِلَ."],[80,80,"﴿وَلِتَبۡلُغُواْ عَلَيۡهَا حَاجَةࣰ فِي صُدُورِكُمۡ﴾: ولِتَبْلُغُوا بالحَمُولَةِ على بَعْضِها، وهي الإبِلُ، حاجَةً في صُدُورِكُم مِنَ الوصُولِ إلى الأقْطارِ البعِيدةِ. والحاجةُ: النِّيَّةُ والعَزِيمَةُ.\n\n﴿ٱلۡفُلۡكِ﴾: السُّفُنِ."],[82,82,"﴿وَءَاثَارࣰا فِي ٱلۡأَرۡضِ﴾: وأَبْقى آثارًا في الأرضِ مِنَ الأَبْنِيَةِ والمصانِع والغِراسِ.\n\n﴿فَمَآ أَغۡنَىٰ﴾: فَما أجْزَأَ وكَفى."],[83,83,"﴿بِٱلۡبَيِّنَـٰتِ﴾: بالُمعْجِزاتِ الظّاهِراتِ.\n\n﴿فَرِحُواْ بِمَا عِندَهُم مِّنَ ٱلۡعِلۡمِ﴾: الُمناقِضِ لما جاءتْ به الرُّسُلُ، وقالُوا: نَحْنُ أعْلمُ مِنَ الرُّسُلِ ولَن نُّعَذِّبَ.\n\n﴿وَحَاقَ بِهِم﴾: ونَزَلَ وأَحاطَ بِهم.\n\n﴿مَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ﴾: ما كانُوا يَسْتَعْجِلُونَ بِهِ رسُلَهُم عَلى سَبِيلِ السُّخْرِيَةِ والاسْتِهْزاءِ، وهُوَ عَذابُ الاسْتِئْصالِ."],[84,84,"﴿بَأۡسَنَا﴾: عَذابَنا."],[85,85,"﴿سُنَّتَ ٱللَّهِ ٱلَّتِي قَدۡ خَلَتۡ فِي عِبَادِهِۦ﴾: طَرِيقَتَهُ الَّتِي سَنَّها في الأُمَم كلِّها ألّا ينفَعَها الإيمانُ إذا رَأَوا العَذابَ.\n\n﴿وَخَسِرَ هُنَالِكَ ٱلۡكَـٰفِرُونَ﴾: وهَلَكَ عِنْدَ مَجِيءِ بأْسِ اللهِ الكافِرُونَ بِرَبِّهِم."]]);
QTF("gharib",41,[[1,1,"﴿حمٓ﴾: سَبَقَ الكَلامُ عَلى الحرُوفِ المقطَّعةِ في أوَّلِ سُورةِ البقرةِ."],[3,3,"﴿فُصِّلَتۡ﴾: بُيِّنتْ، أو نُوِّعَتْ."],[4,4,"﴿لَا يَسۡمَعُونَ﴾: لَهُ سَماعَ قَبُولٍ وإجابَةٍ."],[5,5,"﴿أَكِنَّةࣲ﴾: أغْطية تَمْنَعُنا من فَهْم ما تَدْعُوننا إليه.\n\n﴿وَقۡرࣱ﴾: ثِقَلٌ وصَمَمٌ، يمْنَعُنا مِنَ السَّمْعِ.\n\n﴿حِجَابࣱ﴾: ساتِرٌ يَحْجُبُنا عَنْ إجابَةِ دَعْوَتِكَ."],[6,6,"﴿فَٱسۡتَقِيمُوٓاْ إِلَيۡهِ﴾: فاسْلُكُوا الطَّريقَ الُموصِلَ إلَيهِ.\n\n﴿وَوَيۡلࣱ﴾: هَلاكٌ وعَذابٌ."],[7,7,"﴿لَا يُؤۡتُونَ ٱلزَّكَوٰةَ﴾: لا يُؤَدُّونَ الصَّدَقةَ إلى مُسْتَحِقِّيها."],[8,8,"﴿غَيۡرُ مَمۡنُونࣲ﴾: غَيرُ مَنقُوصٍ ولا مَحْسُوبٍ ليُمَنَّ بِهِ، بَلْ هُوَ خالٍ مِنَ المَنِّ والأَذى."],[9,9,"﴿أَندَادࣰا﴾: شُرَكاءَ."],[10,10,"﴿رَوَ ٰ⁠سِيَ﴾: جِبالًا ثَوابِتَ.\n\n﴿وَبَـٰرَكَ فِيهَا﴾: أدامَ خَيرَها، وأَنْبَتَ شَجَرَها.\n\n﴿وَقَدَّرَ﴾: وقَسَّمَ.\n\n﴿أَقۡوَ ٰ⁠تَهَا﴾: أرْزاقَ أهْلِها، وما يُصْلِحُهُم مِنَ المعاشِ.\n\n﴿فِيٓ أَرۡبَعَةِ أَيَّامࣲ﴾: أي: في تَتمَّةِ الأيامِ الأرْبَعَةِ.\n\n﴿سَوَآءࣰ﴾: مُسْتَوِيَةً مُهَيَّأةً.\n\n﴿لِّلسَّآئِلِينَ﴾: لِلْمُحْتاجِينَ إليها مِنَ البَشَرِ، أو لِمن يَطْلُبُ مَعْرِفَةَ ذَلكَ."],[11,11,"﴿ٱسۡتَوَىٰٓ﴾: ارْتَفَعَ.\n\n﴿دُخَانࣱ﴾: بُخارٌ مُرْتَفِعٌ.\n\n﴿ٱئۡتِيَا﴾: انْقادا لِأَمْرِي.\n\n﴿طَوۡعًا أَوۡ كَرۡهࣰا﴾: مُخْتارَتَينِ أو مُجْبَرتَين.\n\n﴿طَآئِعِينَ﴾: مُذْعِنِينَ لَكَ، ليسَ لَنا إرادَةٌ تُخالِفُ إرادتَكَ."],[12,12,"﴿فَقَضَىٰهُنَّ﴾: فأَوْجَدَهُنَّ وفَرَغَ من خَلْقِهنَّ.\n\n﴿وَأَوۡحَىٰ فِي كُلِّ سَمَآءٍ أَمۡرَهَا﴾: وألقى في كل سماءٍ من السمواتِ السبعِ ما أراد من الأمورِ التي بها قِوامُها وصَلاحُها.\n\n﴿بِمَصَـٰبِيحَ﴾: بالنجومِ المضيئةِ.\n\n﴿وَحِفۡظࣰا﴾: وزَيَّنّاها حِفْظًا لها من الشياطينِ الذين يَسْتَرِقون السَّمْعَ."],[13,13,"﴿أَنذَرۡتُكُمۡ﴾: خَوَّفْتُكُمْ.\n\n﴿صَـٰعِقَةࣰ﴾: وقْعَةَ عذابٍ يَسْتأصِلُكم."],[14,14,"﴿مِنۢ بَيۡنِ أَيۡدِيهِمۡ وَمِنۡ خَلۡفِهِمۡ﴾: يَتْبَعُ بعضُهم بعضًا واتصلَتْ نِذارتُهم."],[15,15,"﴿بِـَٔايَـٰتِنَا﴾: الُمعْجزات."],[16,16,"﴿صَرۡصَرࣰا﴾: شديدةَ البُرودةِ والصوتِ.\n\n﴿نَّحِسَاتࣲ﴾: مَشْؤوماتٍ عليهم.\n\n﴿ٱلۡخِزۡيِ﴾: الهَوانِ والهلاكِ."],[17,17,"﴿فَهَدَيۡنَـٰهُمۡ﴾: بيَّنّا لهم طُرُقَ الخيرِ والشرِّ.\n\n﴿ٱلۡعَمَىٰ﴾: الكفرَ.\n\n﴿فَأَخَذَتۡهُمۡ﴾: فأهلكَتْهُم.\n\n﴿صَـٰعِقَةُ﴾: مُهْلِكَةُ.\n\n﴿ٱلۡعَذَابِ ٱلۡهُونِ﴾: الذي معه هَوانٌ وإذلالٌ."],[19,19,"﴿يُحۡشَرُ﴾: يُجْمَعُ.\n\n﴿يُوزَعُونَ﴾: تَرُدُّ زبانيةُ العذابِ أوَّلَهم على آخِرِهم؛ ليجتمِعُوا جميعًا."],[21,21,"﴿أَوَّلَ مَرَّةࣲ﴾: الخَلْقَ الأَوَّلَ ولَمْ تَكُونُوا شيئًا."],[22,22,"﴿تَسۡتَتِرُونَ﴾: تَسْتَخْفُونَ عِنْدَ ارْتِكابِكُم المعاصِيَ في الدُّنيا.\n\n﴿أَن يَشۡهَدَ﴾: مَخافَةَ أن يَشْهَدَ."],[23,23,"﴿أَرۡدَىٰكُمۡ﴾: أهْلَكَكُم، فَأَوْرَدَكُم النّارَ.\n\n﴿ٱلۡخَـٰسِرِينَ﴾: الهالِكِينَ."],[24,24,"﴿مَثۡوࣰى﴾: مَأْوىً.\n\n﴿يَسۡتَعۡتِبُواْ﴾: يَسْأَلُوا العُتْبى وهي الرَّجْعَةُ لَهُم إلى الَّذِي يُحِبُّونَ بِتَخْفِيفِ العَذابِ عَنْهُم.\n\n﴿ٱلۡمُعۡتَبِينَ﴾: الَّذِينَ يُقْبَلُ عُذْرُهُم ويُجابُونَ إلى ما طَلَبُوا."],[25,25,"﴿وَقَيَّضۡنَا﴾: هَيَّأنا وأَعْدَدْنا.\n\n﴿قُرَنَآءَ﴾: نُظَراءَ مُلازِمِينَ مِن شَياطِينِ الإنْسِ والجِنِّ.\n\n﴿فَزَيَّنُواْ﴾: فَحَسّنُوا.\n\n﴿مَّا بَيۡنَ أَيۡدِيهِمۡ﴾: مِن أمْرِ الدُّنيا حتّى آثَرُوها على الآخِرةِ.\n\n﴿وَمَا خَلۡفَهُمۡ﴾: ما بَعْدَ مَماتِهم وذَلكَ بالتَّكْذِيبِ بالَمعادِ.\n\n﴿وَحَقَّ عَلَيۡهِمُ ٱلۡقَوۡلُ﴾: وجَبَ لَهُم العَذابُ.\n\n﴿فِيٓ أُمَمࣲ﴾: في جُمْلةِ أُمَمٍ كافِرةٍ.\n\n﴿قَدۡ خَلَتۡ﴾: مَضَتْ."],[26,26,"﴿وَٱلۡغَوۡاْ﴾: وأْتُوا فِيهِ بالتَّخْلِيطِ والصَّفِيرِ عِنْدَ قِراءتِهِ."],[28,28,"﴿دَارُ ٱلۡخُلۡدِ﴾: دارُ الإقامةِ الدّائِمَةِ.\n\n﴿يَجۡحَدُونَ﴾: يَكْفُرُونَ."],[29,29,"﴿ٱلۡأَسۡفَلِينَ﴾: أشَدَّ عَذابًا مِنّا."],[30,30,"﴿ٱسۡتَقَـٰمُواْ﴾: سَلَكُوا الطَّريقَ القَوِيمَ، وأَدَّوا فَرائِضَ اللهِ.\n\n﴿تَتَنَزَّلُ عَلَيۡهِمُ ٱلۡمَلَـٰٓئِكَةُ﴾: أي: عِنْدَ نُزُولِ الموتِ بِهِم مُطَمْئِنَةً.\n\n﴿أَلَّا تَخَافُواْ﴾: تَقُولُ لَهُم: لا تخافُوا مِنَ الموتِ وما بَعْدَهُ.\n\n﴿وَلَا تَحۡزَنُواْ﴾: عَلى ما تُخَلِّفُونَه وراءَكُم مِن أُمَورِ الدُّنيا.\n\n﴿وَأَبۡشِرُواْ﴾: وسُرُّوا."],[31,31,"﴿أَوۡلِيَآؤُكُمۡ﴾: أنْصارُكُم وأَحِبّاؤُكُم.\n\n﴿تَدَّعُونَ﴾: تَتَمَنَّونَ."],[32,32,"﴿نُزُلࣰا﴾: ضِيافَةً وتَكْرِمَةً."],[33,33,"﴿وَمَنۡ أَحۡسَنُ قَوۡلࣰا﴾: لا أحَدَ أحْسَنُ قَولًا.\n\n﴿دَعَآ إِلَى ٱللَّهِ﴾: دَعا إلى تَوْحِيدِ اللهِ وعِبادَتِه وحْدَهُ."],[34,34,"﴿ٱلۡحَسَنَةُ﴾: الصَّبرُ والحِلْمُ والعَفْوُ.\n\n﴿ٱلسَّيِّئَةُ﴾: الغَضَبُ والجَهْلُ والإساءَةُ.\n\n﴿ٱدۡفَعۡ بِٱلَّتِي هِيَ أَحۡسَنُ﴾: ادْفَعْ -أيُّها الرَّسُولُ- بِعَفْوِكَ وحِلْمِكَ وإحْسانِكَ مَن أساءَ إليكَ.\n\n﴿وَلِيٌّ﴾: مُحِبٌّ مُناصِرٌ.\n\n﴿حَمِيمࣱ﴾: قَرِيبٌ مُشْفِقٌ."],[35,35,"﴿وَمَا يُلَقَّىٰهَآ﴾: وما يُعْطى ويُوفَّقُ لهذهِ الَمنْزِلَةِ الحمِيدَةِ.\n\n﴿حَظٍّ﴾: نَصِيبٍ."],[36,36,"﴿وَإِمَّا يَنزَغَنَّكَ مِنَ ٱلشَّيۡطَـٰنِ نَزۡغࣱ﴾: وإمّا يُلْقِيَنَّ الشَّيطانُ في نَفْسِكَ وسْوَسَةً مِن حدِيثِ النَّفْسِ تَحْمِلُكَ عَلى مُجازاةِ الُمسِيءِ بالإساءَةِ.\n\n﴿فَٱسۡتَعِذۡ بِٱللَّهِ﴾: فاسْتَجِرْ بِاللهِ واعْتَصِمْ بِهِ."],[37,37,"﴿وَمِنۡ ءَايَـٰتِهِ﴾: ومِن حُجَجِ اللهِ عَلى خَلقِهِ، ودَلائِلِهِ عَلى وحْدانِيَّتهِ وكَمالِ قُدْرَتِهِ."],[38,38,"﴿فَٱلَّذِينَ عِندَ رَبِّكَ﴾: هُمُ الملائِكَةُ.\n\n﴿لَا يَسۡـَٔمُونَ﴾: لا يَفْتُرُونَ ولا يَمَلُّونَ."],[39,39,"﴿خَـٰشِعَةࣰ﴾: يابِسَةً مُسْتَكِينَةً لا نَباتَ فِيها.\n\n﴿ٱهۡتَزَّتۡ﴾: تَحَرَّكَتْ وتَشَقَّقَتْ بالنَّباتِ.\n\n﴿وَرَبَتۡ﴾: وانْتَفَخَتْ وعَلَتْ."],[40,40,"﴿يُلۡحِدُونَ﴾: يَمِيلُونَ عَنِ الحَقِّ إنْكارًا لَهُ.\n\n﴿ٱعۡمَلُواْ مَا شِئۡتُمۡ﴾: وعِيدٌ في صِيغَةِ الأمْر."],[41,41,"﴿بِٱلذِّكۡرِ﴾: بالقرآنِ."],[42,42,"﴿ٱلۡبَـٰطِلُ﴾: الشَّيطانُ وأيُّ أمْرٍ يُبْطِلُ شَيئًا مِنهُ.\n\n﴿مِنۢ بَيۡنِ يَدَيۡهِ وَلَا مِنۡ خَلۡفِهِۦ﴾: مِن أيِّ جِهَةٍ مِن جِهاتِهِ، فهو مَحْفُوظٌ بِحِفْظِ اللهِ.\n\n﴿حَكِيمٍ﴾: ذِي حِكْمَةٍ.\n\n﴿حَمِيدࣲ﴾: مَحْمُودٍ عَلى نِعَمِهِ عَلى الخَلْقِ وعَلى ما لَهُ مِن صِفاتِ الكَمالِ."],[43,43,"﴿مَّا يُقَالُ لَكَ﴾: لا يقُولُ لَكَ المشرِكُونَ."],[44,44,"﴿أَعۡجَمِيࣰّا﴾: عَلى غَيرِ لُغَةِ العَرَبِ.\n\n﴿لَوۡلَا﴾: هَلّا.\n\n﴿فُصِّلَتۡ ءَايَـٰتُهُۥٓ﴾: بُيِّنتْ آياتُه فَنَفْقَهَهُ ونَعْلَمَهُ.\n\n﴿ءَا۬عۡجَمِيࣱّ وَعَرَبِيࣱّ﴾: أأَعْجَمِيٌّ هَذا القُرآنُ، ولِسانُ الَّذِي أُنْزِل عَليهِ عَرَبيٌّ؟\n\n﴿هُدࣰى﴾: بَيانٌ لِلْحَقِّ.\n\n﴿وَشِفَآءࣱ﴾: مِنَ الجَهْلِ والأمْراضِ.\n\n﴿وَقۡرࣱ﴾: ثِقَلٌ وصَمَمٌ.\n\n﴿وَهُوَ عَلَيۡهِمۡ عَمًى﴾: عَمِيَتْ قُلُوبُهُم عَنِ القُرآنِ فَلا يَهْتَدُونَ بِهِ.\n\n﴿أُوْلَـٰٓئِكَ يُنَادَوۡنَ مِن مَّكَانِۭ بَعِيدࣲ﴾: كَأنّ أُولئِكَ المشرِكِينَ يَسْمَعُونَ صَوْتًا مِن بَعِيدٍ، ولا يَفْهَمُونَ مَعانِيَهُ."],[45,45,"﴿ٱلۡكِتَـٰبَ﴾: التَّوراةَ.\n\n﴿وَلَوۡلَا كَلِمَةࣱ سَبَقَتۡ مِن رَّبِّكَ﴾: بِتَأْجِيلِ العَذابِ عَن قَومِكَ.\n\n﴿لَقُضِيَ بَيۡنَهُمۡ﴾: لَفُصِلَ بينهم بإهْلاكِ الكافِرينَ في الحالِ.\n\n﴿وَإِنَّهُمۡ لَفِي شَكࣲّ مِّنۡهُ﴾: وإنّ الفريقَ المُبْطِلَ مِنهُم لَفِي شَكٍّ مما قالُوا في التَّوراةِ.\n\n﴿مُرِيبࣲ﴾: مُوقِعٍ في قَلَقِ النَّفْسِ وعَدَمِ طُمَأنِينتِها؛ لأنّهُم قالُوهُ ظنًّا بِغَيرِ حُجَّةٍ."],[46,46,"﴿فَعَلَيۡهَا﴾: فَعَلى نَفْسِهِ جَنى.\n\n﴿بِظَلَّـٰمࣲ﴾: بِذِي ظُلْمٍ."],[47,47,"﴿إِلَيۡهِ يُرَدُّ﴾: إلى اللهِ وحْدَهُ يُرجَعُ.\n\n﴿مِّنۡ أَكۡمَامِهَا﴾: مِن أوْعِيَتِها. مُفْرَدُها: كِمٌّ.\n\n﴿ءَاذَنَّـٰكَ﴾: أعْلَمناكَ.\n\n﴿مَا مِنَّا مِن شَهِيدࣲ﴾: يَشْهَدُ أنّ لَكَ شَريكًا."],[48,48,"﴿وَضَلَّ عَنۡهُم﴾: وذَهَبَ عَنِ المشْرِكِينَ.\n\n﴿وَظَنُّواْ﴾: أيقَنُوا.\n\n﴿مَّحِيصࣲ﴾: مَلْجَأٍ مِن عَذابِ اللهِ."],[49,49,"﴿لَّا يَسۡـَٔمُ﴾: لا يَمَلُّ.\n\n﴿ٱلۡإِنسَـٰنُ﴾: المُرادُ هُنا الكافرُ بِاللهِ.\n\n﴿مِن دُعَآءِ ٱلۡخَيۡرِ﴾: مِن سُؤالِهِ رَبَّهُ أن يَمُدَّهُ بالمالِ والصِّحَّةِ.\n\n﴿وَإِن مَّسَّهُ﴾: وإنْ أصابَه.\n\n﴿ٱلشَّرُّ﴾: فَقْرٌ ومَرَضٌ.\n\n﴿فَيَـُٔوسࣱ﴾: مُبالِغٌ في اعْتِقادِ عَدَمِ حُصُولِ الخيرِ لَهُ.\n\n﴿قَنُوطࣱ﴾: شَدِيد اليأسِ."],[50,50,"﴿ضَرَّآءَ﴾: شدَّةٍ وبَلاءٍ.\n\n﴿هَـٰذَا لِي﴾: أسْتَحِقُّه على اللهِ لأنّه راضٍ عَنِّي.\n\n﴿لَلۡحُسۡنَىٰ﴾: الجنَّةِ.\n\n﴿غَلِيظࣲ﴾: شَدِيدٍ، وهو خُلُودُهُم في النّارِ."],[51,51,"﴿وَنَـَٔابِجَانِبِهِۦ﴾: تَباعَدَ عَن شُكْرِ نِعْمَةِ اللهِ وطاعَتِهِ.\n\n﴿عَرِيضࣲ﴾: كَثِيرٍ."],[52,52,"﴿أَرَءَيۡتُمۡ﴾: أخْبِرُونِي.\n\n﴿مَنۡ أَضَلُّ﴾: لا أحَد أشَدُّ ذَهابًا عَن قَصْدِ السَّبيلِ.\n\n﴿فِي شِقَاقِۭ﴾: في خِلافٍ وفِراقٍ لأمر الله.\n\n﴿بَعِيدࣲ﴾: واسِع المسافَةِ مِنَ الرَّشادِ."],[53,53,"﴿ءَايَـٰتِنَا﴾: مِنَ الفُتُوحاتِ وظُهُورِ الإسْلامِ عَلى الأقاليمِ وسائِرِ الأدْيانِ.\n\n﴿ٱلۡـَٔافَاقِ﴾: أقْطارِ السَّمَواتِ والأرْضِ.\n\n﴿وَفِيٓ أَنفُسِهِمۡ﴾: مِن لطِيفِ الصَّنْعَةِ وبدِيعِ الحِكْمةِ.\n\n﴿أَوَ لَمۡ يَكۡفِ بِرَبِّكَ﴾: أو لم يَكْفِ ربُّكَ شاهِدًا عَلى صِدْقِكَ وصِدْقِ ما أُنزِلَ إليكَ."],[54,54,"﴿مِرۡيَةࣲ مِّن لِّقَآءِ رَبِّهِمۡ﴾: شَكٍّ عَظِيمٍ مِنَ البعثِ بَعْدَ المماتِ.\n\n﴿مُّحِيطُۢ﴾: أحاطَ بِكُلِّ شَيءٍ عِلْمًا."]]);
QTF("gharib",42,[[1,2,"﴿حمٓ عٓسٓقٓ﴾: سَبَقَ الكَلامُ عَلى الحروفِ المقطَّعةِ في أوَّلِ سُورةِ البقرةِ."],[3,3,"﴿ٱلۡعَزِيزُ﴾: القويُّ الَّذِي لا يُعْجِزُهُ شَيءٌ أرادَهُ.\n\n﴿ٱلۡحَكِيمُ﴾: الَّذِي لا يَدْخُلُ تَدْبِيرَهُ خَلَلٌ ولا زَلَلٌ."],[4,4,"﴿ٱلۡعَلِيُّ﴾: العالي بِذاتِهِ وقُدْرَتِهِ وقَهْرِهِ."],[5,5,"﴿يَتَفَطَّرۡنَ﴾: يَتَشَقَّقْنَ.\n\n﴿مِن فَوۡقِهِنَّ﴾: مِن أعْلاهُنَّ مِن عَظَمِةِ اللهِ وجَلالِهِ.\n\n﴿يُسَبِّحُونَ﴾: يُنَزِّهُونَ اللهَ عَمّا لا يَلِيقُ بِهِ قائِلِينَ: سُبَحانَ اللهِ.\n\n﴿وَيَسۡتَغۡفِرُونَ لِمَن فِي ٱلۡأَرۡضِ﴾: ويَطْلُبُونَ مِن رَبِّهِم أن يَسْتُرَ ذُنُوبَ أهْلِ الأَرْضِ مِنَ المُؤمِنِين."],[6,6,"﴿مِن دُونِهِۦٓ﴾: غَيرَ اللهِ.\n\n﴿أَوۡلِيَآءَ﴾: مَعْبُودِينَ يَتَوَلَّونَهُم بالمحبَّةِ والتَّعظِيمِ.\n\n﴿ٱللَّهُ حَفِيظٌ عَلَيۡهِمۡ﴾: يُحْصِي عَلَيهِم أعْمالَهُم فَيُجازِيهِم بِها يَومَ القِيامةِ.\n\n﴿وَمَآ أَنتَ عَلَيۡهِم بِوَكِيلࣲ﴾: ولَسْتَ مُوَكَّلًا بِحِفْظِ أعمالِهِم وإنّما أنتَ مُنْذِرٌ."],[7,7,"﴿وَكَذَ ٰ⁠لِكَ﴾: مِثْلَ ذَلِكَ الإيجادِ.\n\n﴿لِّتُنذِرَ أُمَّ ٱلۡقُرَىٰ﴾: لتُخَوِّفَ أهْلَ مَكَّةَ العَذابَ.\n\n﴿وَمَنۡ حَوۡلَهَا﴾: وتُنْذِرَ مَن حَولَ مَكَّةَ مِن سائِر الناسِ العَذابَ.\n\n﴿يَوۡمَ ٱلۡجَمۡعِ﴾: يومَ القِيامةِ، وسُمِّيَ بيومِ الجمْعِ لاجْتِماعِ الخلائقِ فِيهِ.\n\n﴿لَا رَيۡبَ فِيهِ﴾: لا شَكَّ فِيه.\n\n﴿ٱلسَّعِيرِ﴾: النّارِ الموقَدةِ على أهْلِها."],[8,8,"﴿أُمَّةࣰ وَ ٰ⁠حِدَةࣰ﴾: أهْلَ دِينٍ واحِدٍ.\n\n﴿وَٱلظَّـٰلِمُونَ﴾: والكافِرُونَ بِاللهِ.\n\n﴿وَلِيࣲّ﴾: قَرِيبٍ مُحِبٍّ يَتَوَلّاهُم بِنَفْعِهِ.\n\n﴿نَصِيرٍ﴾: ناصِرٍ يَمْنَعُهم مِن عِقابِ اللهِ حِينَ يُعاقِبُهُم."],[9,9,"﴿أَمِ ٱتَّخَذُواْ﴾: بَل اتَّخَذُوا.\n\n﴿أَوۡلِيَآءَ﴾: مَعْبودِينَ يَتَوَلَّونَهُم بالمحَبَّةِ والتَّعْظِيمِ ويَطْلُبُونَ مِنهُم النَّفْعَ والنُّصْرَةَ.\n\n﴿ٱلۡوَلِيُّ﴾: النّاصِرُ المُعِينُ الَّذِي تَنْفَعُ وِلايتُهُ، يَتَوَلّاهُ عَبْدُهُ بالعِبادَةِ والطّاعَةِ، ويَتَوَلّى عِبادَهُ المؤمِنِينَ بِهدايَتِهِم وإعانَتِهِم، ويَتَولّى عُمُومَ خَلْقِهِ بَتَدْبِيرِهِ ونُفُوذِ القَدَرِ فِيهِم."],[10,10,"﴿عَلَيۡهِ تَوَكَّلۡتُ﴾: اعتمدت على الله بقلبي في جَلْبِ المنافِعِ ودَفْعِ المضارِّ.\n\n﴿وَإِلَيۡهِ أُنِيبُ﴾: أرْجِعُ إلى اللهِ في جَمِيعِ أُمُوريِ."],[11,11,"﴿فَاطِرُ﴾: خالِقُ ومُبْدِعُ.\n\n﴿وَمِنَ ٱلۡأَنۡعَـٰمِ أَزۡوَ ٰ⁠جࣰا﴾: وجَعَلَ مِنَ الأنْعامِ أزْواجًا ذُكُورًا وإناثًا.\n\n﴿يَذۡرَؤُكُمۡ فِيهِ﴾: يُكَثِّرُكُم بسَبِبِ هَذا التَّزاوُجِ بِالتَّوالُدِ نَسْلًا بَعْدَ نسْلٍ.\n\n﴿لَيۡسَ كَمِثۡلِهِۦ شَيۡءࣱ﴾: لا يُماثِلُهُ شَيءٌ مِن مَّخلُوقاتِهِ لا في ذاتِهِ ولا في صِفاتِهِ ولا في أسْمائِهِ ولا في أفْعالِهِ، لانْفِرادِهِ وتَوَحُّدِهِ بِالكَمالِ مِن كُلِّ وجْهٍ.\n\n﴿وَهُوَ ٱلسَّمِيعُ﴾: لجَمِيعِ الأصْواتِ.\n\n﴿ٱلۡبَصِيرُ﴾:: لِأَعْمالِ الخلْقِ لا يَخْفى عَلَيهِ شَيءٌ مِنها."],[12,12,"﴿مَقَالِيدُ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ﴾: مَفاتِيحُ خَزائِنِ السَّمواتِ والأرْضِ.\n\n﴿يَبۡسُطُ﴾: يُوسِّعُ.\n\n﴿وَيَقۡدِرُ﴾: ويُضَيِّقُ."],[13,13,"﴿شَرَعَ﴾: بَيَّنَ ووَضِّحَ.\n\n﴿أَنۡ أَقِيمُواْ ٱلدِّينَ﴾: التَّوحِيدَ.\n\n﴿كَبُرَ﴾: عَظُمَ.\n\n﴿يَجۡتَبِيٓ إِلَيۡهِ﴾: يَصْطَفِي إلى التَّوحِيدِ.\n\n﴿وَيَهۡدِيٓ﴾: ويُوَفِّقُ للعَمَلِ بِطاعَتِهِ.\n\n﴿يُنِيبُ﴾: يَرْجِعُ عَنِ الكُفْرِ ويَحْرِصُ على الخيرِ."],[14,14,"﴿بَغۡيَۢا بَيۡنَهُمۡ﴾: تجاوُزًا للحَدِّ واعْتِداءً مِن بَعْضِهم علىِ بَعْضٍ.\n\n﴿كَلِمَةࣱ سَبَقَتۡ مِن رَّبِّكَ﴾: بتأخِيرِ العذابِ عَنْهُم.\n\n﴿أَجَلࣲ مُّسَمࣰّى﴾: يَومِ القِيامَةِ.\n\n﴿لَّقُضِيَ بَيۡنَهُمۡ﴾: لفُصِلَ بينَهُم بِتَعْجِيلِ عَذابِ الكافِريِنَ مِنهُم في الدُّنيا.\n\n﴿مُرِيبࣲ﴾: مُوقِعٍ في الرِّيَبةِ والاخْتِلافِ المَذْمُومِ."],[15,15,"﴿فَلِذَ ٰ⁠لِكَ﴾: فإلى ذَلِك الدِّينِ القيِّمِ.\n\n﴿مِن كِتَـٰبࣲ﴾: مِنَ الكُتُب.\n\n﴿لَا حُجَّةَ﴾: لا خُصُومةَ ولا جِدالَ بَعْدَ تَبَيُّنِ الحقِّ.\n\n﴿ٱلۡمَصِيرُ﴾: المرجِعُ."],[16,16,"﴿يُحَآجُّونَ﴾: يُجادِلُونَ في دِينِ اللهِ بالإبْطالِ وفِتْنَةِ النّاسِ عَنْهُ.\n\n﴿مِنۢ بَعۡدِ مَا ٱسۡتُجِيبَ لَهُۥ﴾: مِن بَعْدِ ما اسْتَجابَ النّاسُ لمحمَّدٍ ﷺ وأَسْلَمُوا.\n\n﴿حُجَّتُهُمۡ دَاحِضَةٌ﴾: مُجادَلَتُهُم باطِلةٌ."],[17,17,"﴿بِٱلۡحَقِّ﴾: بالصِّدقِ.\n\n﴿وَٱلۡمِيزَانَ﴾: العَدْلَ.\n\n﴿وَمَا يُدۡرِيكَ﴾: وأيَّ شَيءٍ يُعْلِمُكَ؟"],[18,18,"﴿مُشۡفِقُونَ مِنۡهَا﴾: خائِفُونَ مِن قِيامِها.\n\n﴿يُمَارُونَ﴾: يُخاصِمُونَ ويُجادِلُونَ."],[19,19,"﴿لَطِيفُۢ بِعِبَادِهِۦ﴾: رَفِيقٌ بالِغُ الرَّأْفةِ بِعبادِهِ المؤْمِنِينَ."],[20,20,"﴿حَرۡثَ ٱلۡـَٔاخِرَةِ﴾: عَمَلًا لِأَجْلِ الآخِرةِ.\n\n﴿حَرۡثِهِۦ﴾: عَمَلِهِ الحَسَنِ.\n\n﴿وَمَن كَانَ يُرِيدُ حَرۡثَ ٱلدُّنۡيَا﴾: ومَن كانَ يُريدُ بِعَمَلِهِ الدُّنيا، لا يَسْعى إلا لَها، وهُوَ الكافرُ بالآخِرةِ.\n\n﴿نُؤۡتِهِۦ مِنۡهَا﴾: نُعْطِه مِنَ الدُّنيا ما قَسَمْناهُ له مِن مُّدَةِ حياةٍ وعافِيةٍ ورزْقٍ."],[21,21,"﴿شَرَعُواْ لَهُم﴾: ابْتَدَعُوا لَهُم.\n\n﴿كَلِمَةُ ٱلۡفَصۡلِ﴾: القَضاءُ السّابقُ بأنّ الجَزاءَ يومَ القِيامَةِ.\n\n﴿لَقُضِيَ بَيۡنَهُمۡ﴾: لفُرِغَ مِنَ الحُكْمِ بَينَكُم وبَينَهُم بِتَعْجِيلِ العَذابِ لَهُم في الدُّنيا.\n\n﴿وَإِنَّ ٱلظَّـٰلِمِينَ﴾: وإنَّ الكافِرِينَ باللهِ.\n\n﴿أَلِيمࣱ﴾: مُوجِعٌ."],[22,22,"﴿ٱلظَّـٰلِمِينَ﴾: الكافِرينَ.\n\n﴿مُشۡفِقِينَ﴾: خائِفِينَ.\n\n﴿وَهُوَ وَاقِعُۢ بِهِمۡ﴾: والعَذابُ نازلٌ بِهِم.\n\n﴿رَوۡضَاتِ ٱلۡجَنَّاتِ﴾: بَساتِينِ الجَّناتِ، وأنْزَهِها."],[23,23,"﴿لَّآ أَسۡـَٔلُكُمۡ عَلَيۡهِ أَجۡرًا﴾: لا أسْأَلُكُم عَلى ما أدْعُوكُم إلَيهِ مِنَ الحقِّ عِوَضًا مِن أمْوالِكُم.\n\n﴿إِلَّا ٱلۡمَوَدَّةَ فِي ٱلۡقُرۡبَىٰ﴾: إلّا أن تَوَدُّوني في قَرابتِي مِنكُم، وتَصِلُوا الرَّحِمَ التِّي بينِي وبَينَكُم.\n\n﴿وَمَن يَقۡتَرِفۡ﴾: ومَن يَكْتَسِبْ.\n\n﴿نَّزِدۡ لَهُۥ فِيهَا حُسۡنًا﴾: نُضاعِفْ لَهُ تِلْكَ الحَسَنَةَ.\n\n﴿غَفُورࣱ﴾: ساتِرٌ عُيُوبَ عِبادِهِ.\n\n﴿شَكُورٌ﴾: كَثِيرُ الشُّكْرِ للمُطِيعِينَ."],[24,24,"﴿أَمۡ﴾: بَلْ.\n\n﴿ٱفۡتَرَىٰ﴾: اخْتَلَقَ.\n\n﴿يَخۡتِمۡ﴾: يَطْبَعْ.\n\n﴿وَيَمۡحُ﴾: ويُزِيلُ.\n\n﴿بِكَلِمَـٰتِهِۦٓ﴾: الَّتي لا تَتَبَدَّلُ ولا تَتَغَيَّرُ، وبِوعْدِهِ الصّادِقِ الَّذِي لا يَتَخَلَّفُ.\n\n﴿بِذَاتِ ٱلصُّدُورِ﴾: بِما في قُلُوبِ العبادِ."],[27,27,"﴿بَسَطَ﴾: وسَّعَ.\n\n﴿لَبَغَوۡاْ﴾: لَطَغى بَعْضُهُم عَلى بَعْضٍ.\n\n﴿بِقَدَرࣲ﴾: بمِقْدار."],[28,28,"﴿ٱلۡغَيۡثَ﴾: المطرَ.\n\n﴿قَنَطُواْ﴾: يَئِسُوا مِن نُّزُولِهِ.\n\n﴿رَحۡمَتَهُۥ﴾: المطرَ.\n\n﴿ٱلۡوَلِيُّ﴾: الَّذِي يَتَولى عِبادَهُ بإحْسانِهِ وفَضْلِهِ.\n\n﴿ٱلۡحَمِيدُ﴾: المحْمُودُ."],[29,29,"﴿بَثَّ﴾: نَشَرَ وفَرَّقَ.\n\n﴿دَآبَّةࣲ﴾: اسْم لِكُلِّ ذِي رُوحٍ لا يطِيرُ بِجَناحَيْهِ، لِدَبِيبِهِ عَلى الأرْضِ."],[31,31,"﴿بِمُعۡجِزِينَ﴾: بَفائِتِينَ اللهَ.\n\n﴿وَلِيࣲّ﴾: يَتَوَلىَّ أُمُورَكُم، فَيُوصِلُ لَكُم المنافِعَ.\n\n﴿نَصِيرࣲ﴾: يَدْفَعُ عَنْكُمُ المضارِّ."],[32,32,"﴿ٱلۡجَوَارِ﴾: السُّفُنُ العَظِيمَةُ الَّتي تَجِري في البَحْرِ.\n\n﴿كَٱلۡأَعۡلَـٰمِ﴾: كالجبالِ."],[33,33,"﴿رَوَاكِدَ﴾: سَواكِنَ لا تَجْرِي."],[34,34,"﴿يُوبِقۡهُنَّ﴾: يُغْرِقْهُنَّ."],[35,35,"﴿مَّحِيصࣲ﴾: مَلْجأٍ."],[36,36,"﴿فَمَتَـٰعُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا﴾: فهو مَتاعٌ لَكُم، سرْعانَ ما يَزُولُ."],[37,37,"﴿وَٱلۡفَوَ ٰ⁠حِشَ﴾: ما فَحُشَ وقَبُحَ مِن أنْواعِ المعاصِي.\n\n﴿يَغۡفِرُونَ﴾: يَصْفَحُونَ عن عُقُوبِة المُسِيءِ إلَيهِم."],[38,38,"﴿ٱسۡتَجَابُواْ لِرَبِّهِمۡ﴾: آمنُوا باللهِ وقَبِلُوا شَرْعَه.\n\n﴿وَأَمۡرُهُمۡ شُورَىٰ بَيۡنَهُمۡ﴾: ويتَشاوَرُونَ في جَمِيعِ أُمُورِهِم ولا يَعْجَلونَ."],[39,39,"﴿ٱلۡبَغۡيُ﴾: الظُّلْمُ.\n\n﴿يَنتَصِرُونَ﴾: يَنْتقِمُونَ مِمَّن ظَلَمَهُم بِمِثْلِ ظُلْمِهِ."],[40,40,"﴿وَجَزَ ٰ⁠ٓؤُاْ سَيِّئَةࣲ سَيِّئَةࣱ مِّثۡلُهَا﴾: وجَزاءُ سيئةِ المُسِيءِ عُقُوبَتُهُ بِسَيِّئَةٍ مِثْلِها مِن غَيرِ زِيادةٍ."],[41,41,"﴿سَبِيلٍ﴾: مُؤاخَذَةٍ."],[42,42,"﴿وَيَبۡغُونَ﴾: ويَتَجاوَزُونَ الحدَّ الَّذي أُبيحَ لهُم إلى ما لم يُؤذَنْ لَهُم فِيهِ.\n\n﴿أَلِيمࣱ﴾: مُوجِعٌ."],[43,43,"﴿وَغَفَرَ﴾: قابَلَ الإساءَةَ بالعَفْوِ.\n\n﴿ذَ ٰ⁠لِكَ﴾: الصَّبْرَ والمغْفِرَةَ.\n\n﴿عَزۡمِ ٱلۡأُمُورِ﴾: مُحْكَمِها ومُتْقَنِها الَّذِي تُحْمَدُ عاقِبَتُهُ."],[44,44,"﴿وَلِيࣲّ﴾: ناصرٍ يَهْديِهِ سَبِيلَ الرَّشادِ.\n\n﴿ٱلظَّـٰلِمِينَ﴾: الكافِرِينَ باللهِ.\n\n﴿مَرَدࣲّ﴾: رُجُوعٍ إلى الدُّنيا؛ لِنَسْتَدِركَ الإيمانَ والعَمَلَ الصّالِحَ."],[45,45,"﴿خَـٰشِعِينَ مِنَ ٱلذُّلِّ﴾: خاضِعِينَ بِسَبَبِ الذُّلِّ.\n\n﴿طَرۡفٍ خَفِيࣲّ﴾: عَيْنٍ ذَلِيلةٍ مِنَ الخَوْفِ والهَوانِ.\n\n﴿مُّقِيمࣲ﴾: دائِمٍ."],[46,46,"﴿أَوۡلِيَآءَ﴾: أعْوانٍ ونُصَراءَ.\n\n﴿يَنصُرُونَهُم﴾: يَمْنَعُونَهُم مِن عَذابِ اللهِ.\n\n﴿وَمَن يُضۡلِلِ ٱللَّهُ﴾: ومَن يَخْذُلْه اللهُ عَن طَرِيقِ الحقِّ.\n\n﴿سَبِيلٍ﴾: طَرِيقٍ يَصِل بِهِ إلى الحقِّ والنَّجاةِ."],[47,47,"﴿ٱسۡتَجِيبُواْ لِرَبِّكُم﴾: أجِيبُوا داعيَ اللهِ وآمِنُوا بِه.\n\n﴿لَّا مَرَدَّ لَهُۥ﴾: لا شَيءَ يَرُدُّ مَجِيئَهُ إذا جاء اللهُ بِهِ.\n\n﴿مَّلۡجَإࣲ﴾: مَعْقِل تَحْتَرِزُونَ فِيهِ مِن عَذابِ اللهِ.\n\n﴿نَّكِيرࣲ﴾: إنْكارٍ وتَغْيِيرٍ."],[48,48,"﴿رَحۡمَةࣰ﴾: غِنىً وسَعةً وغَيرَ ذَلِكَ.\n\n﴿سَيِّئَةُۢ﴾: مُصِيَبةٌ تَسُوءُهُم في أجْسادِهِم أوْ نُفُوسِهِم.\n\n﴿بِمَا قَدَّمَتۡ أَيۡدِيهِمۡ﴾: بما أسْلفَتْ مِنَ المعاصِي.\n\n﴿كَفُورࣱ﴾: جَحُودٌ نِعَمَ رَبِّه لا يَذْكُرُ إلا المصائِبَ."],[49,49,"﴿يَهَبُ﴾: يُعْطِي."],[50,50,"﴿يُزَوِّجُهُمۡ﴾: يُنَوِّعُهُم.\n\n﴿عَقِيمًا﴾: لا يُولَدُ له."],[51,51,"﴿عَلِيٌّ﴾: عالٍ بِذاتِه وأسْمائِهِ وصِفاتِه وأفعالِه."],[52,52,"﴿رُوحࣰا﴾: قُرآنًا.\n\n﴿ٱلۡكِتَـٰبُ﴾: الكُتُبُ السّابِقَةُ.\n\n﴿لَتَهۡدِيٓ﴾: لَتَدُلُّ وتُرْشِدُ.\n\n﴿صِرَ ٰ⁠طࣲ مُّسۡتَقِيمࣲ﴾: هُوَ الإسْلامُ."],[53,53,"﴿تَصِيرُ﴾: تَرْجِعُ."]]);
QTF("gharib",43,[[1,1,"﴿حمٓ﴾: سَبَقَ الكَلامُ على الحُرُوفِ المُقَطَّعةِ في أوَّلِ سُورَةِ البَقَرةِ."],[2,2,"﴿وَٱلۡكِتَـٰبِ﴾: القُرآنِ.\n\n﴿ٱلۡمُبِينِ﴾: الواضِح لَفْظًا ومَعْنىً."],[4,4,"﴿أُمِّ ٱلۡكِتَـٰبِ﴾: اللَّوحِ المحْفُوظِ.\n\n﴿لَعَلِيٌّ﴾: رَفِيعٌ.\n\n﴿حَكِيمٌ﴾: مُحْكَمٌ لا اخْتِلافَ فِيهِ ولا تَناقُضَ."],[5,5,"﴿أَفَنَضۡرِبُ عَنكُمُ ٱلذِّكۡرَ﴾: أفَنُعْرِضُ عَنْكُم ونَتْرُكُ إنْزالَ القُرآنِ إلَيكُم.\n\n﴿صَفۡحًا﴾: أي: إعْراضًا.\n\n﴿مُّسۡرِفِينَ﴾: مُتَجاوِزِينَ الحدَّ في الإعْراضِ عَنِ القُرآنِ."],[6,6,"﴿وَكَمۡ﴾: كَثِيرًا.\n\n﴿ٱلۡأَوَّلِينَ﴾: القُرُونِ الَّتي مَضَتْ."],[8,8,"﴿بَطۡشࣰا﴾: قُوَّةً وبأسًا.\n\n﴿مَثَلُ﴾: عُقُوبةُ."],[10,10,"﴿مَهۡدࣰا﴾: فِراشًا وبِساطًا.\n\n﴿سُبُلࣰا﴾: طُرُقًا لِمَعاشِكُم ومَتاجِرِكُم."],[11,11,"﴿مَآءَۢ﴾: مَطَرًا.\n\n﴿بِقَدَرࣲ﴾: بِمِقْدارِ الحاجَةِ.\n\n﴿فَأَنشَرۡنَا﴾: فَأَحْيَيْنا.\n\n﴿بَلۡدَةࣰ﴾: قِطْعَةً واسِعَةً مِنَ الأرْضِ.\n\n﴿مَّيۡتࣰا﴾: مُقْفِرًا مِنَ النَّباتِ والزَّرْعِ.\n\n﴿تُخۡرَجُونَ﴾: تُبْعَثُونَ يومَ القيامةِ."],[12,12,"﴿ٱلۡأَزۡوَ ٰ⁠جَ﴾: الأصْنافَ مِن حَيوانٍ ونَباتٍ ذُكُورًا وإناثًا.\n\n﴿ٱلۡفُلۡكِ﴾: السُّفُنِ.\n\n﴿وَٱلۡأَنۡعَـٰمِ﴾: البَهائِمِ كالإبِلِ والخيلِ والبِغالِ والحمِيرِ."],[13,13,"﴿سَخَّرَ﴾: ذَلَّلَ وطَوَّعَ.\n\n﴿مُقۡرِنِينَ﴾: مُطِيقِينَ."],[14,14,"﴿لَمُنقَلِبُونَ﴾: راجِعُونَ."],[15,15,"﴿جُزۡءًا﴾: نَصِيبًا."],[16,16,"﴿أَمِ﴾: بَلِ.\n\n﴿ٱتَّخَذَ﴾: أتَزْعُمُونَ أنَّ الله اتَّخَذَ.\n\n﴿وَأَصۡفَىٰكُم﴾: وأَخْلَصَكُم."],[17,17,"﴿ضَرَبَ﴾: جَعَلَ.\n\n﴿مَثَلࣰا﴾: شبيهًا.\n\n﴿ظَلَّ﴾: صارَ.\n\n﴿كَظِيمٌ﴾: حَزِينٌ مملُوءٌ بالهَمِّ والكَرْبِ."],[18,18,"﴿يُنَشَّؤُاْ﴾: يُرَبّى.\n\n﴿ٱلۡحِلۡيَةِ﴾: الزِّينةِ.\n\n﴿ٱلۡخِصَامِ﴾: الِجدالِ."],[19,19,"﴿أَشَهِدُواْ خَلۡقَهُمۡ﴾: أحَضَرُوا حِينَ خَلْقِهِم؟"],[20,20,"﴿يَخۡرُصُونَ﴾: يَكْذِبُونَ."],[21,21,"﴿مُسۡتَمۡسِكُونَ﴾: يَعْمَلُونَ به ويَدِينُونَ بما فِيهِ."],[22,22,"﴿أُمَّةࣲ﴾: طَرِيقةٍ ودِينٍ.\n\n﴿عَلَىٰٓ ءَاثَـٰرِهِم﴾: وراءَهُم.\n\n﴿مُّهۡتَدُونَ﴾: مُتَّبِعُونَ."],[23,23,"﴿مُتۡرَفُوهَآ﴾: الرُّؤَساءُ الَّذيِنَ أطْغَتْهُم النِّعْمَةُ."],[25,25,"﴿فَٱنتَقَمۡنَا مِنۡهُمۡ﴾: عاقَبْناهُم على ذُنُوبِهِم.\n\n﴿عَـٰقِبَةُ﴾: آخِرُ أمْرٍ."],[26,26,"﴿بَرَآءࣱ﴾: بَرِيءٌ."],[27,27,"﴿فَطَرَنِي﴾: خَلَقَنِي.\n\n﴿سَيَهۡدِينِ﴾: سَيُوَفِّقُنِي لاتِّباعِ سَبِيلِ الرُّشْدِ."],[28,28,"﴿وَجَعَلَهَا كَلِمَةَۢ بَاقِيَةࣰ﴾: وجَعَلَ إبْراهِيمُ كَلِمةَ التَّوحِيدِ قَوْلًا باقِيًا على مَرِّ الزَّمانِ.\n\n﴿عَقِبِهِۦ﴾: ولَدِهِ مِن بَعْدِهِ."],[29,29,"﴿مَتَّعۡتُ﴾: أجْزَلْتُ النِّعمَةَ ولَمْ أُعاجِلْ بالعُقُوبَةِ.\n\n﴿ٱلۡحَقُّ﴾: القُرَآنُ.\n\n﴿مُّبِينࣱ﴾: يُبَيِّنُ لَهُم مّا يَحْتاجُونَ إلَيهِ مِن أُمُورِ دِينِهِم."],[31,31,"﴿لَوۡلَا﴾: هَلّا.\n\n﴿ٱلۡقَرۡيَتَيۡنِ﴾: مَكَّةَ والطّائِفِ."],[32,32,"﴿رَحۡمَتَ رَبِّكَ﴾: النُّبُوَّةُ.\n\n﴿سُخۡرِيࣰّا﴾: مُذَلَّلًا في شُؤُونِ المعاشِ.\n\n﴿وَرَحۡمَتُ رَبِّكَ﴾: النُّبُوَّةُ.\n\n﴿مِّمَّا يَجۡمَعُونَ﴾: مِنَ الأمْوالِ."],[33,33,"﴿أُمَّةࣰ وَ ٰ⁠حِدَةࣰ﴾: جماعَةً واحِدَةً، كُلُّهُم كُفّارٌ.\n\n﴿وَمَعَارِجَ﴾: وسَلالِمَ.\n\n﴿يَظۡهَرُونَ﴾: يَصْعَدُونَ."],[34,34,"﴿وَسُرُرًا﴾: جَمْعُ سَرِيرٍ، وهو ككرْسِيٍّ واسِعٍ يُمْكِنُ الاضْطِجاعُ عَلَيهِ.\n\n﴿يَتَّكِـُٔونَ﴾: يَجْلِسُونَ عَلَيها مُعْتَمِدِينَ على مَرافِقِهِم."],[35,35,"﴿وَزُخۡرُفࣰا﴾: وجَعَلْنا لهم ذَهَبًا."],[36,36,"﴿يَعۡشُ﴾: يُعرِضْ.\n\n﴿ذِكۡرِ ٱلرَّحۡمَـٰنِ﴾: القرآن.\n\n﴿نُقَيِّضۡ﴾: نَجْعَلْ.\n\n﴿قَرِينࣱ﴾: مُلازِمٌ ومُصاحِبٌ."],[37,37,"﴿ٱلسَّبِيلِ﴾: طَرِيقِ الحقِّ"],[38,38,"﴿يَـٰلَيۡتَ﴾: ودِدْتُّ وتمنَّيتُ.\n\n﴿بُعۡدَ ٱلۡمَشۡرِقَيۡنِ﴾: بُعْدَ ما بَينَ المشْرِقِ والمغْرِبِ."],[44,44,"﴿لَذِكۡرࣱ﴾: لَشَرَفٌ."],[45,45,"﴿مَنۡ أَرۡسَلۡنَا﴾: أتْباعَ مَن أرْسَلْنا، وهُم مُّؤمِنُو أهْلِ الكِتابِ."],[46,46,"﴿بِـَٔايَـٰتِنَآ﴾: بِحُجَجِنا.\n\n﴿وَمَلَإِيْهِۦ﴾: عُظَماءِ قَومِهِ."],[48,48,"﴿مِنۡ أُخۡتِهَا﴾: مِنَ الَّتِي قَبْلَها."],[49,49,"﴿ٱلسَّاحِرُ﴾: العالِمُ، ولَمْ يَكُنِ السِّحْرُ صِفَةَ ذَمٍّ عِنْدَ فِرْعَونَ ومَلَئِهِ."],[50,50,"﴿يَنكُثُونَ﴾: يغْدِرُونَ ويَنْقُضُونَ ما عاهَدُوا عليهِ أنْفُسَهُم."],[51,51,"﴿مِن تَحۡتِيٓ﴾: مِن تَحْتِ قُصُورِي."],[52,52,"﴿أَمۡ﴾: بَلْ.\n\n﴿مَهِينࣱ﴾: ضَعِيفٌ حَقِيرٌ.\n\n﴿يُبِينُ﴾: أي: يُبِين الكَلامَ."],[53,53,"﴿فَلَوۡلَآ﴾: فَهَلّا.\n\n﴿مُقۡتَرِنِينَ﴾: مُتَتابِعِينَ."],[54,54,"﴿فَٱسۡتَخَفَّ قَوۡمَهُۥ﴾: حَمَلَ قَومَه عَلى خفَّةِ العَقْل."],[55,55,"﴿ءَاسَفُونَا﴾: أغْضَبُونا.\n\n﴿ٱنتَقَمۡنَا مِنۡهُمۡ﴾: عاقَبْناهُم عَلى ذُنُوبِهم."],[56,56,"﴿سَلَفࣰا﴾: قَوْمًا تَقَدَّمُوا لِيتَّعِظَ بِهِمُ الآخَرُونَ.\n\n﴿وَمَثَلࣰا﴾: عِبْرةً وعِظَةً."],[57,57,"﴿ضُرِبَ ٱبۡنُ مَرۡيَمَ مَثَلًا﴾: ضَرَبَ المشركُونَ نَبِيَّ اللهِ عِيسى مَثَلًا لِآلِهَتِهِم وشَبَّهُوهُ بِها في دُخُولِ النّارِ.\n\n﴿يَصِدُّونَ﴾: يَصِيحُونَ فَرَحًا وسُرُورًا."],[58,58,"﴿خَصِمُونَ﴾: شِدِيدُو التَّمَسُكِ بالخُصُومَةِ مَعَ ظُهُورِ الحقِّ عِنْدَهُم."],[59,59,"﴿مَثَلࣰا لِّبَنِيٓ إِسۡرَ ٰ⁠ٓءِيلَ﴾: عِبْرةً لَهُم يَعْرِفُونَ بِهِ قُدْرَةَ اللهِ عَلى ما يُرِيدُ؛ إذْ خَلَقَهُ مِن غَيرِ أبٍ."],[60,60,"﴿مِنكُم﴾: بَدَلًا مِنكُم.\n\n﴿يَخۡلُفُونَ﴾: يَخْلُفُ بَعْضُهُم بَعْضًا بَدَلًا مِن بنِي آدمَ."],[61,61,"﴿وَإِنَّهُۥ﴾: وإنّ نُزولَ عِيسى عَلَيهِ السَّلامُ في آخِرِ الزَّمانِ.\n\n﴿لَعِلۡمࣱ﴾: لَدَلِيلٌ وعَلامةٌ.\n\n﴿فَلَا تَمۡتَرُنَّ﴾: فَلا تَشُكُّوا أنّها واقِعةٌ."],[62,62,"﴿مُّبِينࣱ﴾: بَيِّنُ العَداوَةِ."],[63,63,"﴿بِٱلۡبَيِّنَـٰتِ﴾: بالأدِلَّةِ الواضِحاتِ.\n\n﴿بِٱلۡحِكۡمَةِ﴾: بالنُّبُوَّةِ."],[65,65,"﴿ٱلۡأَحۡزَابُ﴾: الفِرَقُ مِنَ النَّصارى.\n\n﴿فَوَيۡلࣱ﴾: فَهَلاكٌ وعَذابٌ ألِيمٌ."],[66,66,"﴿يَنظُرُونَ﴾: يَنْتَظِرُونَ.\n\n﴿بَغۡتَةࣰ﴾: فَجْأةً."],[67,67,"﴿ٱلۡأَخِلَّآءُ﴾: الأصْدِقاءُ."],[70,70,"﴿وَأَزۡوَ ٰ⁠جُكُمۡ﴾: وقُرَناؤُكُم المؤمِنُونَ.\n\n﴿تُحۡبَرُونَ﴾: تُنَعَّمُونَ وتُسَرُّونَ."],[71,71,"﴿بِصِحَافࣲ﴾: بآنِيةٍ يُؤْكَلُ فِيها.\n\n﴿وَأَكۡوَابࣲ﴾: آنِيَةٍ للشُّرْبِ.\n\n﴿وَتَلَذُّ﴾: وتَجِدُ فِيها ما يَسُرُّها."],[74,74,"﴿ٱلۡمُجۡرِمِينَ﴾: الكافِرينَ."],[75,75,"﴿لَا يُفَتَّرُ﴾: لا يُخَفَّفُ.\n\n﴿مُبۡلِسُونَ﴾: آيِسُونَ مِن رَّحْمَةِ اللهِ."],[77,77,"﴿يَـٰمَـٰلِكُ﴾: هو اسْمُ خازِنِ جَهَنَّمَ.\n\n﴿لِيَقۡضِ عَلَيۡنَا رَبُّكَ﴾: لِيُمِتْنا ربُّكَ.\n\n﴿مَّـٰكِثُونَ﴾: مُقِيمُونَ في العذابِ."],[79,79,"﴿أَمۡ﴾: بَلْ.\n\n﴿أَبۡرَمُوٓاْ﴾: أحْكَمُوا.\n\n﴿مُبۡرِمُونَ﴾: مُحْكِمُونَ أمْرًا في مُجازاتِهم بِالنَّكالِ والعَذابِ."],[80,80,"﴿سِرَّهُمۡ﴾: ما يُخْفُونَه مِن غَيرِهِم.\n\n﴿وَنَجۡوَىٰهُم﴾: الحدِيثَ الَّذِي يَتَسارُّونَ بِهِ فِيما بَينَهُم.\n\n﴿وَرُسُلُنَا﴾: الملائِكَةُ الحَفَظَةُ."],[81,81,"﴿فَأَنَا۠ أَوَّلُ ٱلۡعَـٰبِدِينَ﴾: أوَّلُ عابِدِيهِ بِذلكَ مِنكُم، ولَكِنَّهُ لا ولَدَ لَهُ، فأَنا أعْبُدُهُ بِأنّه لا ولَدَ لَهُ."],[82,82,"﴿سُبۡحَـٰنَ﴾: تنْزِيهًا وتَقْدِيسًا.\n\n﴿يَصِفُونَ﴾: يَكْذِبُونَ."],[83,83,"﴿يَخُوضُواْ﴾: يَتَحَدَّثُوا بالباطِل على غيرِ هُدىً."],[84,84,"﴿فِي ٱلسَّمَآءِ إِلَـٰهࣱ وَفِي ٱلۡأَرۡضِ إِلَـٰهࣱ﴾: مَعْبُودٌ في السَّماءِ وفي الأَرْضِ."],[85,85,"﴿وَتَبَارَكَ﴾: كَثُرَ خَيْرُهُ.\n\n﴿تُرۡجَعُونَ﴾: تُرَدُّونَ بَعْدَ مَماتِكُم."],[86,86,"﴿ٱلشَّفَـٰعَةَ﴾: طَلَبَ قَضاءِ حاجَةِ المشْفُوعِ لَهُ عِنْدَ المشْفُوعِ عِنْدَهُ مِنَ التَّجاوُزِ عَنِ السَّيئاتِ والزَّلّاتِ وغَيرِها."],[87,87,"﴿فَأَنَّىٰ يُؤۡفَكُونَ﴾: كَيْفَ يُصْرَفُونَ عَنْ عِبادَةِ الله؟"],[88,88,"﴿وَقِيلِهِۦ﴾: وعِنْدَ اللهِ عِلْمُ قولِ الرَّسُولِ ﷺ."],[89,89,"﴿فَٱصۡفَحۡ﴾: فَأَعْرِضْ.\n\n﴿سَلَـٰمࣱ﴾: سَلامُ مُتارَكَةٍ ومُفارَقَةٍ لِلْجاهِلِينَ."]]);
QTF("gharib",44,[[1,1,"﴿حمٓ﴾: سَبَقَ الكلامُ عَلى الحُرُوفِ المقَطَّعةِ أوَّلَ سُورَةِ البقرةِ."],[2,2,"﴿ٱلۡمُبِينِ﴾: الواضِحِ لَفْظًا ومَعْنىً."],[3,3,"﴿مُّبَـٰرَكَةٍ﴾: كَثِيرَةِ الخَيراتِ، وهي لَيلةُ القَدْرِ."],[4,4,"﴿يُفۡرَقُ﴾: يُقضى ويُفَصَّلُ مِنَ اللوحِ المحْفُوظِ إلى الكَتَبةِ مِنَ الملائِكَةِ.\n\n﴿حَكِيمٍ﴾: مُحْكَمٍ."],[10,10,"﴿فَٱرۡتَقِبۡ﴾: فانْتَظِرْ.\n\n﴿بِدُخَانࣲ﴾: ظُلْمَةٍ كَهَيئَةِ الدُّخانِ بِسَبِبِ الجَدْبِ.\n\n﴿مُّبِينࣲ﴾: واضِحٍ."],[11,11,"﴿يَغۡشَى﴾: يَعُمُّ."],[13,13,"﴿أَنَّىٰ﴾: كَيفَ.\n\n﴿ٱلذِّكۡرَىٰ﴾: التَّذَكُّرُ والاتِّعاظُ."],[14,14,"﴿تَوَلَّوۡاْ عَنۡهُ﴾: أعْرَضُوا عَنْه.\n\n﴿مُعَلَّمࣱ﴾: عَلَّمَه بَشَرٌ أو الكَهَنَةُ أو الشَّياطِينُ."],[16,16,"﴿نَبۡطِشُ﴾: نُعَذِّبُ، والبَطْشُ أخْذٌ بِشِدَّةٍ."],[17,17,"﴿فَتَنَّا﴾: ابْتَلينا واخْتَبَرْنا."],[18,18,"﴿أَدُّوٓاْ﴾: سَلِّمُوا وأرْسِلُوا مَعِي.\n\n﴿عِبَادَ ٱللَّهِ﴾: بَنِي إسْرائِيلَ."],[19,19,"﴿وَأَن لَّا تَعۡلُواْ عَلَى ٱللَّهِ﴾: لا تَتَكَبَّرُوا على اللهِ بِتَكْذِيبِ رُسُلِه.\n\n﴿بِسُلۡطَـٰنࣲ﴾: بِبُرْهانٍ."],[20,20,"﴿عُذۡتُ بِرَبِّي﴾: استَجَرْتُ بِاللهِ.\n\n﴿تَرۡجُمُونِ﴾: تَقْتُلُوني رَجْمًا بالحِجارَةِ."],[21,21,"﴿فَٱعۡتَزِلُونِ﴾: كُفُّوا عَنْ أذايَ."],[22,22,"﴿مُّجۡرِمُونَ﴾: مُشْرِكُونَ بِاللهِ كافِرُونَ."],[23,23,"﴿فَأَسۡرِ﴾: اجْعَلْهُم يَسِيُرونَ لَيلًا."],[24,24,"﴿رَهۡوًا﴾: ساكِنًا مُسْتَقِرًّا عَلى حالِه مُنْفَرِجًا."],[26,26,"﴿وَمَقَامࣲ كَرِيمࣲ﴾: ومَنازِلَ جَمِيلَةٍ."],[27,27,"﴿وَنَعۡمَةࣲ﴾: عَيْشٍ لَيِّنٍ رَغْدٍ.\n\n﴿فَـٰكِهِينَ﴾: مُتَنَعِّمِينَ، مُتْرَفِينَ."],[28,28,"﴿كَذَ ٰ⁠لِكَ﴾: مِثْلَ ذَلِكَ العِقابِ يُعاقِبُ اللهُ مَن كَذَّبَ، وبَدّلَ نِعْمةَ اللهِ كُفْرًا.\n\n﴿وَأَوۡرَثۡنَـٰهَا﴾: ومَلَّكْناها."],[29,29,"﴿مُنظَرِينَ﴾: مُؤَخَّرِينَ عَنِ العُقُوبَةِ."],[30,30,"﴿ٱلۡمُهِينِ﴾: المُذِلِّ."],[31,31,"﴿عَالِيࣰا﴾: جَبّارًا.\n\n﴿مِّنَ ٱلۡمُسۡرِفِينَ﴾: مُتَجاوِزًا للحَدِّ في العُلوِّ والتَّكَبُّرِ عَلى عبادِ اللهِ."],[32,32,"﴿ٱلۡعَـٰلَمِينَ﴾: عالَمِي زَمانِهِم."],[33,33,"﴿ٱلۡـَٔايَـٰتِ﴾: الُمعْجِزاتِ.\n\n﴿بَلَـٰٓؤࣱاْ﴾: اخْتِبارٌ بالرَّخاءِ والشِّدَةِ."],[35,35,"﴿بِمُنشَرِينَ﴾: بِمَبْعُوثِينَ."],[37,37,"﴿تُبَّعࣲ﴾: أحَدِ مُلُوكِ اليمنِ الحِمْيَرِيِّينَ مِمَّن جَمَعَ مُلْكَ مَناطِقِ اليمنِ كُلِّها."],[40,40,"﴿يَوۡمَ ٱلۡفَصۡلِ﴾: يومَ القَضاءِ بَينَ الخَلْقِ.\n\n﴿مِيقَـٰتُهُمۡ﴾: مَوعِدُ جزائِهِم"],[41,41,"﴿يُغۡنِي﴾: يَدْفَعُ.\n\n﴿مَّوۡلࣰى﴾: صاحِبٌ."],[43,43,"﴿شَجَرَتَ ٱلزَّقُّومِ﴾: شَجَرةً كَرِيهةَ الرّائِحَةِ صَغِيرةَ الوَرَقِ مَسْمُومةً خَلَقَها اللهُ في جَهَنَّمَ."],[44,44,"﴿ٱلۡأَثِيمِ﴾: الكَثِيرِ الآثامِ، والمرادُ بِه المشْرِكُ."],[45,45,"﴿كَٱلۡمُهۡلِ﴾: كالمَعْدَنِ المُذابِ."],[46,46,"﴿ٱلۡحَمِيمِ﴾: الماءِ الَّذِي بَلَغَ الغايَةَ فِي الحرارةِ."],[47,47,"﴿فَٱعۡتِلُوهُ﴾: ادْفَعُوهُ وقُودُوهُ بِعُنْفٍ.\n\n﴿سَوَآءِ﴾: وسَطِ."],[48,48,"﴿صُبُّواْ﴾: أفْرِغُوا."],[49,49,"﴿ذُقۡ﴾: قُولُوا لَهُ عَلى وجْهِ الإهانَةِ: أحْسِسْ.\n\n﴿أَنتَ ٱلۡعَزِيزُ ٱلۡكَرِيمُ﴾: أي: الذَّلِيلُ المُهانُ، عُكِسَ المَدْلُولُ للتَّهَكُّمِ بِهِ."],[50,50,"﴿تَمۡتَرُونَ﴾: تَشُكُّونَ."],[51,51,"﴿مَقَامٍ﴾: مَسْكَنٍ.\n\n﴿أَمِينࣲ﴾: آمِنٍ صاحِبُه مِنَ الآفاتِ."],[53,53,"﴿سُندُسࣲ﴾: الرقِيقِ مِنَ الحرِيرِ الخالِصِ.\n\n﴿وَإِسۡتَبۡرَقࣲ﴾: الغليظِ مِنَ الحريرِ الخالصِ.\n\n﴿مُّتَقَـٰبِلِينَ﴾: أي: في مَجالِسِهِم ومُحادَثاتِهِم."],[54,54,"﴿وَزَوَّجۡنَـٰهُم﴾: قَرنّاهُم.\n\n﴿بِحُورٍ﴾: جَمْعُ حَوْراءَ وهي البيضاءُ.\n\n﴿عِينࣲ﴾: واسِعاتِ الأَعْيُنِ."],[55,55,"﴿يَدۡعُونَ﴾: يَطْلُبُونَ."],[56,56,"﴿ٱلۡمَوۡتَةَ ٱلۡأُولَىٰ﴾: الَّتِي سَلَفَتْ لَهُم في الُّدنيا."],[58,58,"﴿يَسَّرۡنَـٰهُ﴾: سَهَّلْنا لَفْظَ القرآنِ ومَعْناهُ."],[59,59,"﴿فَٱرۡتَقِبۡ﴾: فانْتَظِر ما وعَدْتُكَ.\n\n﴿مُّرۡتَقِبُونَ﴾: مُنْتَظِرُونَ موتَكَ وقَهْرَكَ."]]);
QTF("gharib",45,[[1,1,"﴿حمٓ﴾: سَبقَ الكلامُ على الحروف المقطَّعة أولَ سورة البقرة."],[4,4,"﴿وَمَا يَبُثُّ﴾: وما يَنْشُرُ ويُفَرِّقُ.\n\n﴿دَآبَّةٍ﴾: ما يَدِبُّ عَلى الأرضِ غَيرَ الإنْسانِ.\n\n﴿يُوقِنُونَ﴾: يَعْلَمُونَ حَقائِقَ الأَشْياءِ، فيُقِرُّونَ بِها."],[5,5,"﴿وَٱخۡتِلَـٰفِ ٱلَّيۡلِ وَٱلنَّهَارِ﴾: تَعاقُبِهِما، أو تَفاوَتِهِما بالطُّولِ والقِصَرِ والظُّلْمَةِ والضِّياءِ.\n\n﴿رِّزۡقࣲ﴾: مَطَرٍ يَكُونُ مِنهُ القُوتُ.\n\n﴿وَتَصۡرِيفِ ٱلرِّيَـٰحِ﴾: تَبْدِيلِ اللهِ سبحانه وتعالى للرِّياحِ صُعُودًا ونُزُولًا، واخْتلِافِ جِهاتِ هُبُوبِها."],[7,7,"﴿وَيۡلࣱ﴾: هَلاكٌ شَدِيدٌ.\n\n﴿أَفَّاكٍ﴾: كَذّابٍ.\n\n﴿أَثِيمࣲ﴾: كَثِيرِ الآثامِ."],[9,9,"﴿هُزُوًا﴾: مَوْضِعَ سُخْرِيةٍ واسْتِخْفافٍ."],[10,10,"﴿مِّن وَرَآئِهِمۡ﴾: من أمامِهم.\n\n﴿وَلَا يُغۡنِي عَنۡهُم﴾: ولا يَنْفَعُهُم.\n\n﴿أَوۡلِيَآءَ﴾: نُصَراءَ."],[11,11,"﴿رِّجۡزٍ﴾: أسْوأِ العَذابِ."],[12,12,"﴿ٱلۡفُلۡكُ﴾: السُّفُنُ."],[14,14,"﴿يَغۡفِرُواْ﴾: يَعْفُوا ويَتجاوَزُوا.\n\n﴿لَا يَرۡجُونَ﴾: لا يَخافُونَ.\n\n﴿أَيَّامَ ٱللَّهِ﴾: بأسَهُ ووَقائِعَه ونِقَمَهُ."],[15,15,"﴿فَعَلَيۡهَا﴾: فَعَلى نَفْسِهِ جَنى."],[16,16,"﴿ٱلۡكِتَـٰبَ﴾: التَّوْراةَ والإنْجِيلَ.\n\n﴿وَٱلۡحُكۡمَ﴾: الفَهْمَ للكِتابِ والعِلْمَ بِالسُّنَنِ الَّتي لم تَنْزِلْ في الكِتابِ.\n\n﴿ٱلۡعَـٰلَمِينَ﴾: عالمَي أهلِ زَمانِهِم."],[17,17,"﴿بَيِّنَـٰتࣲ﴾: دَلالاتٍ تُبَيِّنُ الحقَّ مِنَ الباطِلِ.\n\n﴿ٱلۡعِلۡمُ﴾: الكتابُ والنُّبُوَّةُ والدَّلائِلُ الواضِحَةُ الَّتِي تُفَرِّقُ بين الحقِّ والباطِلِ.\n\n﴿بَغۡيَۢا﴾: ظُلْمًا وحَسَدًا."],[18,18,"﴿شَرِيعَةࣲ﴾: مِنهاجٍ واضِحٍ.\n\n﴿مِّنَ ٱلۡأَمۡرِ﴾: مِن أمْرِ الدِّينِ.\n\n﴿أَهۡوَآءَ﴾: ما تَمِيلُ نُفُوسُهُم إلَيهِ مِمّا يُخالِفُ شَرْعَ اللهِ."],[19,19,"﴿يُغۡنُواْ﴾: يَدْفَعُوا."],[20,20,"﴿بَصَـٰٓئِرُ﴾: جَمْعُ بصِيرةِ، وهي الحُجَّةُ فِيما يحتاجُونَ إليهِ مِنَ الأحْكامِ."],[21,21,"﴿ٱجۡتَرَحُواْ﴾: اكْتَسَبُوا.\n\n﴿سَوَآءࣰ مَّحۡيَاهُمۡ وَمَمَاتُهُمۡ﴾: مُسْتَويةً حالةُ حياتِهِم وحالاتُ موتِهِم."],[23,23,"﴿وَخَتَمَ عَلَىٰ سَمۡعِهِۦ﴾: وطَبَع عَلى سَمْعِهَ، فَلا يَسْمَعُ مَواعِظَ اللهِ.\n\n﴿غِشَـٰوَةࣰ﴾: غِطاءً فَلا يَنْتَفِعُ بِبَصَرِهِ."],[24,24,"﴿ٱلدَّهۡرُ﴾: مُرورُ السِّنينَ والأَيّامِ.\n\n﴿عِلۡمٍ﴾: يَقِينٍ بَلْ يَقُولُونَ ذَلكَ تَخَرُّصًا."],[27,27,"﴿ٱلۡمُبۡطِلُونَ﴾: الَّذِينَ أبْطَلُوا في دَعْواهُم للهِ شَرِيكًا."],[28,28,"﴿جَاثِيَةࣰ﴾: بارِكَةً عَلى الرُّكَبِ مُسْتَوفِزَةً.\n\n﴿كِتَـٰبِهَا﴾: كِتابِ أعْمالِها."],[29,29,"﴿كِتَـٰبُنَا﴾: كِتابُ أعْمالِكُم الَّذِي دوَّنَتْهُ ملائِكَتِي.\n\n﴿نَسۡتَنسِخُ﴾: نَأمُرُ الحَفَظَةَ أن تَكْتُبَ."],[32,32,"﴿بِمُسۡتَيۡقِنِينَ﴾: بِمُتَحَقِّقِينَ."],[33,33,"﴿وَبَدَا﴾: وظَهَرَ.\n\n﴿وَحَاقَ﴾: ونَزَلَ وأَحاطَ."],[34,34,"﴿نَنسَىٰكُمۡ﴾: نَتْرُكُكُم في عَذابِ جَهَنَّمَ.\n\n﴿وَمَأۡوَىٰكُمُ﴾: ومَسْكَنُكُم."],[35,35,"﴿هُزُوࣰا﴾: مُسْتَهْزَأً بِها.\n\n﴿وَغَرَّتۡكُمُ﴾: وخَدَعَتْكُم.\n\n﴿لَا يُخۡرَجُونَ مِنۡهَا﴾: أي مِنَ النّارِ.\n\n﴿يُسۡتَعۡتَبُونَ﴾: يُرْضِيهِم أحَدٌ بِتَمْكِينِهِم مِنَ التَّوبَةِ."],[37,37,"﴿ٱلۡكِبۡرِيَآءُ﴾: السُّلطانُ والعَظَمَةُ."]]);
QTF("gharib",46,[[1,1,"﴿حمٓ﴾: سبق شَرْحُ الحروفِ المقطَّعةِ أوَّلَ سُورةِ البَقَرَةِ."],[3,3,"﴿وَأَجَلࣲ مُّسَمࣰّى﴾: وتَعْيِينِ ساعَةٍ مُحَدَّدَةٍ لِبَقائِهِما."],[4,4,"﴿شِرۡكࣱ﴾: شِرْكَةٌ ونَصِيبٌ.\n\n﴿مِّن قَبۡلِ هَـٰذَآ﴾: مِن قَبْل هذا القرآنِ.\n\n﴿أَثَـٰرَةࣲ﴾: بَقِيَّةٍ تُؤْثَرُ عَنِ الأوَّلِينَ."],[6,6,"﴿كَانُواْ لَهُمۡ﴾: كانَتِ الأصْنامُ للعابِدِينَ."],[8,8,"﴿فَلَا تَمۡلِكُونَ لِي﴾: فَلا تَقْدِرُونَ على أن تَرُدُّوا عَنِّي.\n\n﴿تُفِيضُونَ﴾: وتُكْثِرُونَ القَوْلَ فِيهِ، وتَخُوضُونَ وتتوسَّعُونَ."],[9,9,"﴿بِدۡعࣰا﴾: أوَّلَ مَبْعُوثٍ، فَقَدْ كانَ قَبْلِي رُسُلٌ."],[10,10,"﴿أَرَءَيۡتُمۡ﴾: أخْبِرُونِي.\n\n﴿شَاهِدࣱ﴾: هُوَ عَبْدُاللهِ بْنُ سَلامٍ.\n\n﴿عَلَىٰ مِثۡلِهِۦ﴾: أي القُرآنِ، مِنَ المعانِي الموجُودَةِ في التَّوراةِ."],[11,11,"﴿مَّا سَبَقُونَآ إِلَيۡهِ﴾: ما سَبَقَنا فُقَراءُ المسِلمِينَ إلى الإيمانِ.\n\n﴿إِفۡكࣱ﴾: كَذِبٌ."],[12,12,"﴿إِمَامࣰا﴾: يُقْتَدى بِهِ في الدِّينِ.\n\n﴿مُّصَدِّقࣱ﴾: لِكِتاب مُوسى وغيرِه من كُتُب اللهِ."],[15,15,"﴿كُرۡهࣰا﴾: مَشَقَّةً.\n\n﴿وَفِصَـٰلُهُۥ﴾: وفِطامُهُ.\n\n﴿أَشُدَّهُۥ﴾: نِهايةَ قُوَّتِهِ البَدَنِيَّةِ والعقْلِيَّةِ.\n\n﴿أَوۡزِعۡنِيٓ﴾: ألْهِمْنِي."],[16,16,"﴿فِيٓ أَصۡحَـٰبِ ٱلۡجَنَّةِ﴾: في جُمْلة أصْحابِ الجنَّة."],[17,17,"﴿أُفࣲّ﴾: اسْمُ فِعْلٍ مَعْناه: أتَضَجَّرُ.\n\n﴿أُخۡرَجَ﴾: أُبْعَثَ بَعْدَ الموتِ.\n\n﴿خَلَتِ﴾: مَضَتِ.\n\n﴿ٱلۡقُرُونُ﴾: جَمْعُ قَرْنٍ وهو الأُمَّةُ الَّتي تَقارَبَ زَمانُ حياتِها أي: فماتُوا ولم يُبْعَثْ مِنهُم أحَدٌ؟\n\n﴿يَسۡتَغِيثَانِ ٱللَّهَ﴾: يَطْلُبانِ عَوْنَهُ.\n\n﴿وَيۡلَكَ﴾: هَلاكًا لَكَ.\n\n﴿أَسَـٰطِيرُ﴾: القِصَصُ الباطِلةُ."],[18,18,"﴿حَقَّ عَلَيۡهِمُ ٱلۡقَوۡلُ﴾: وجَبَ عَلَيهِمُ القَوْلُ بالعَذابِ."],[20,20,"﴿أَذۡهَبۡتُمۡ﴾: يقُولُ اللهُ لَهُم ذَلِكَ.\n\n﴿ٱلۡهُونِ﴾: الهَوانِ والذُّلِّ.\n\n﴿تَفۡسُقُونَ﴾: تَخْرُجُونَ عَن طاعَةِ اللهِ بالشِّرْكِ."],[21,21,"﴿بِٱلۡأَحۡقَافِ﴾: الرِّمالِ الكثِيرَةِ الَّتي لَمْ تَبْلُغْ أن تَكُونَ جَبَلًا، وتَقَعُ في جَنُوبِ الجزِيرَةِ العَرَبِيَّةِ، وهي مَنازلُ عادٍ قَومِ هُودٍ.\n\n﴿ٱلنُّذُرُ﴾: جَمْعُ النَّذِيرِ وهو الرَّسُولُ."],[22,22,"﴿لِتَأۡفِكَنَا﴾: لِتَصْرِفَنا."],[24,24,"﴿رَأَوۡهُ﴾: أي العذابَ.\n\n﴿عَارِضࣰا﴾: كالسَّحابِ الَّذي يَعْتَرِضُ جَوَّ السَّماءِ.\n\n﴿أَوۡدِيَتِهِمۡ﴾: منازِلِهم في السُّهُولِ."],[25,25,"﴿كُلَّ شَيۡءِۭ﴾: ما مِن شَأنِه أن تُدَمِّرَهُ مِنَ الإنْسانِ والحيوانِ والدِّيارِ.\n\n﴿مَسَـٰكِنُهُمۡ﴾: أي آثارُ المساكِنِ وبقاياها."],[26,26,"﴿فِيمَآ إِن مَّكَّنَّـٰكُمۡ فِيهِ﴾: في الَّذِي لَم نَجْعَل لَّكُم القُدْرَةَ عَلَيهِ.\n\n﴿وَأَفۡـِٔدَةࣰ﴾: عُقُولًا.\n\n﴿أَغۡنَىٰ﴾: نَفَعَ.\n\n﴿يَجۡحَدُونَ﴾: يُنْكِرُونَ.\n\n﴿وَحَاقَ بِهِم﴾: ونَزَلَ وأَحاطَ بِهِم.\n\n﴿مَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ﴾: العَذابُ الَّذِي كانُوا يَسْخَرُونَ مِنهُ."],[27,27,"﴿وَصَرَّفۡنَا ٱلۡـَٔايَـٰتِ﴾: بيَّنّا لَهُم أنْواعَ الأَدِلَّةِ."],[28,28,"﴿فَلَوۡلَا﴾: فَهَلّا.\n\n﴿قُرۡبَانًا﴾: لِأَجْلِ التَّقَرُّبِ بِهِم إلى اللهِ، وهو مُعْتَرِضٌ بَيْنَ (ٱتَّخَذُواْ) ومَفْعُولِهِ: (ءالِهَةَۢ).\n\n﴿ضَلُّواْ عَنۡهُمۡ﴾: غابُوا عَنْهُم.\n\n﴿إِفۡكُهُمۡ﴾: كَذِبُهُم في زَعمِهِم أنَّ الأصْنامَ شُرَكاءُ لله.\n\n﴿يَفۡتَرُونَ﴾: يَخْتَلِقُونَه مِن كَونِ الأصْنامِ تُقَرِّبُهُم إلى اللهِ."],[29,29,"﴿صَرَفۡنَآ إِلَيۡكَ﴾: أمَلْناهُم إلَيكَ وأَقْبَلْنا بِهِم نَحْوَك.\n\n﴿نَفَرࣰا﴾: جَماعَةً.\n\n﴿أَنصِتُواْ﴾: وجِّهُوا أسْماعَكُم إلى الكَلامِ.\n\n﴿قُضِيَ﴾: فُرِغَ مِن قِراءتِه.\n\n﴿وَلَّوۡاْ﴾: انْصَرفُوا.\n\n﴿مُّنذِرِينَ﴾: المُنْذِرُ: المُخْبِرُ بِخَبرِ مُخِيفٍ."],[30,30,"﴿مُصَدِّقࣰا لِّمَا بَيۡنَ يَدَيۡهِ﴾: مُصَدِّقًا لما سَبَقَه مِن كُتُبِ اللهِ الَّتِي أنْزَلَها على رُسُلِه."],[31,31,"﴿دَاعِيَ ٱللَّهِ﴾: رَسُولَ اللهِ محمَّدًا ﷺ.\n\n﴿وَيُجِرۡكُم﴾: ويَمْنَعْكُم."],[32,32,"﴿فَلَيۡسَ بِمُعۡجِزࣲ فِي ٱلۡأَرۡضِ﴾: فَلا يَفُوتُ عِقابَ الله.\n\n﴿أَوۡلِيَآءُ﴾: نُصَراءُ."],[33,33,"﴿وَلَمۡ يَعۡيَ بِخَلۡقِهِنَّ﴾: ولَمْ يَعْجَزْ عَنْ خَلْقِهِنَّ."],[35,35,"﴿أُوْلُواْ ٱلۡعَزۡمِ مِنَ ٱلرُّسُلِ﴾: هُمْ: نُوحٌ وإبراهيمُ وموسى وعِيسى ومُحَمَّدٌ عَلَيهِمُ الصَّلاةُ والسَّلامُ.\n\n﴿وَلَا تَسۡتَعۡجِل﴾: الَهلاكَ.\n\n﴿لَمۡ يَلۡبَثُوٓاْ﴾: لم يَمْكُثُوا.\n\n﴿بَلَـٰغࣱ﴾: هَذا بَلاغٌ للنّاسِ.\n\n﴿ٱلۡفَـٰسِقُونَ﴾: الخارِجُونَ عَنِ الإيمانِ بالإشْراكِ."]]);
QTF("gharib",47,[[1,1,"﴿أَضَلَّ﴾: أبْطلَ."],[2,2,"﴿كَفَّرَ﴾: سَتَرَ.\n\n﴿بَالَهُمۡ﴾: شَأْنَهُم."],[3,3,"﴿يَضۡرِبُ﴾: يُبَيِّنُ.\n\n﴿أَمۡثَـٰلَهُمۡ﴾: أحُوالَهُم الَّتي تُميِّزُهُم."],[4,4,"﴿لَقِيتُمُ﴾: قاتَلْتُم.\n\n﴿فَضَرۡبَ ٱلرِّقَابِ﴾: فاضْرِبُوا مِنهُم الأَعْناقَ.\n\n﴿أَثۡخَنتُمُوهُمۡ﴾: أضْعَفْتُمُوهُم بِكَثْرةِ القَتْلِ وبالَغْتُم في قَتْلِهِم.\n\n﴿فَشُدُّواْ﴾: فأحْكِمُوا.\n\n﴿ٱلۡوَثَاقَ﴾: قَيْدَ الأسْرىَ.\n\n﴿مَنَّۢا﴾: إطْلاقًا مِنَ الأَسْرِ.\n\n﴿فِدَآءً﴾: مُبادَلةً بالمالِ أو بأسْرى مُسْلِمِينَ.\n\n﴿حَتَّىٰ تَضَعَ ٱلۡحَرۡبُ أَوۡزَارَهَا﴾: حَتّى يَنْتَهِيَ الُمحارِبُونَ عَنْ قِتالِكُم."],[6,6,"﴿عَرَّفَهَا﴾: بَيَّنها."],[8,8,"﴿فَتَعۡسࣰا﴾: فَخِزْيًا لَهُم وشَقاءً وبَلاءً."],[9,9,"﴿فَأَحۡبَطَ﴾: فَأَبْطَلَ."],[10,10,"﴿أَمۡثَـٰلُهَا﴾: أمْثالُ عاقِبةِ تَكْذِيبِ الأُمَمِ السّابِقةِ مِنَ التَّدْمِيرِ والهَلاكِ."],[11,11,"﴿مَوۡلَىٰ﴾: ولِيٌّ وناصِرٌ."],[12,12,"﴿مَثۡوࣰى﴾: مَنزِلٌ."],[13,13,"﴿وَكَأَيِّن مِّن قَرۡيَةٍ﴾: وكَثِيرٍ مِن أهْلِ قَرْيَةٍ.\n\n﴿مِّن قَرۡيَتِكَ﴾: مِن أهْلِ قَرْيَتِكَ."],[15,15,"﴿مَّثَلُ﴾: صِفَةُ.\n\n﴿ءَاسِنࣲ﴾: مُتَغَيِّرٍ.\n\n﴿لَّذَّةࣲ﴾: ذاتِ لَذّةٍ.\n\n﴿حَمِيمࣰا﴾: تَناهى في شِدَّةِ حَرِّهِ."],[16,16,"﴿ءَانِفًا﴾: الآنَ، أي أوَّلَ وقْتٍ يَقْرُبُ مِنّا.\n\n﴿طَبَعَ﴾: خَتَمَ."],[18,18,"﴿فَهَلۡ يَنظُرُونَ﴾: فَما يَنْتَظِرُونَ.\n\n﴿بَغۡتَةࣰ﴾: فَجْأَةً.\n\n﴿أَشۡرَاطُهَا﴾: عَلاماتُها.\n\n﴿ذِكۡرَىٰهُمۡ﴾: تَذَكُّرُهُم ما ضَيَّعُوا مِن طاعَةِ اللهِ."],[19,19,"﴿مُتَقَلَّبَكُمۡ﴾: تَصَرُّفَكُم في يَقَظَتِكُم نَهارًا.\n\n﴿وَمَثۡوَىٰكُمۡ﴾: ومُسْتَقَرَّكُم في نَوْمِكُم لَيلًا."],[20,20,"﴿لَوۡلَا﴾: هَلّا.\n\n﴿مُّحۡكَمَةࣱ﴾: لا نَسْخَ فِيها.\n\n﴿مَّرَضࣱ﴾: شَكٌّ في دينِ اللهِ ونِفاقٌ.\n\n﴿ٱلۡمَغۡشِيِّ عَلَيۡهِ﴾: المُحْتضَرِ الذَّي في سَكْرةِ الموتِ لا يَطْرِفُ بَصَرُه.\n\n﴿مِنَ ٱلۡمَوۡتِ﴾: خَوْفَ الموتِ.\n\n﴿فَأَوۡلَىٰ لَهُمۡ﴾: ولِيَهُم شرٌّ فَلْيَحْذَرُوا."],[21,21,"﴿عَزَمَ ٱلۡأَمۡرُ﴾: جَدَّ وعُزِمَ عَلَيهِ."],[22,22,"﴿فَهَلۡ عَسَيۡتُمۡ﴾: فَلَعَلَّكُم.\n\n﴿تَوَلَّيۡتُمۡ﴾: أعْرَضْتُم."],[23,23,"﴿لَعَنَهُمُ﴾: أبْعَدَهُم."],[24,24,"﴿يَتَدَبَّرُونَ﴾: يتأمَّلُونَ.\n\n﴿أَمۡ﴾: بَلْ.\n\n﴿عَلَىٰ قُلُوبٍ أَقۡفَالُهَآ﴾: قُلُوبُهم مُقْفَلَةٌ فلا يَصِلُ إلَيها ذِكْرُ اللهِ."],[25,25,"﴿سَوَّلَ﴾: زَيَّنَ.\n\n﴿وَأَمۡلَىٰ لَهُمۡ﴾: أطالَ لَهُم أمَلَهُم."],[27,27,"﴿فَكَيۡفَ﴾: فَكَيفَ حالُهُم؟\n\n﴿تَوَفَّتۡهُمُ﴾: قَبَضَتْ أرْواحَهُم."],[29,29,"﴿أَمۡ حَسِبَ﴾: بَلْ أظَنَّ؟\n\n﴿أَضۡغَـٰنَهُمۡ﴾: أحْقادَهُم وعَداوَتَهُم."],[30,30,"﴿بِسِيمَـٰهُمۡ﴾: بِعَلاماتٍ ظاهِرَةٍ فِيهِم.\n\n﴿لَحۡنِ ٱلۡقَوۡلِ﴾: فَحْوى الكلامِ ومَعْناهُ."],[31,31,"﴿وَلَنَبۡلُوَنَّكُمۡ﴾: ولَنَخْتَبِرَنَّكُم."],[32,32,"﴿وَشَآقُّواْ﴾: وخالَفُوا.\n\n﴿وَسَيُحۡبِطُ﴾: وسَيُبْطِلُ."],[35,35,"﴿ٱلسَّلۡمِ﴾: الصُّلْحِ.\n\n﴿يَتِرَكُمۡ﴾: يَنْقُصَكُم."],[37,37,"﴿فَيُحۡفِكُمۡ﴾: فيُلِحَّ عليكُم، ويُبالِغْ في طَلَبِها."]]);
QTF("gharib",48,[[1,1,"﴿فَتَحۡنَا لَكَ﴾: قَضَينا لَكَ.\n\n﴿مُّبِينࣰا﴾: عَظِيما."],[2,2,"﴿صِرَ ٰ⁠طࣰا﴾: طَرِيقًا."],[4,4,"﴿ٱلسَّكِينَةَ﴾: الطُّمأنِينَةَ."],[6,6,"﴿ظَنَّ ٱلسَّوۡءِ﴾: الظَّنَّ السَّيِّئَ.\n\n﴿دَآئِرَةُ ٱلسَّوۡءِ﴾: الشِّدَّةُ المُحِيطَةُ الَّتِي تسُوءُهُم.\n\n﴿وَلَعَنَهُمۡ﴾: وطَردَهُمْ مِن رحْمَتِهِ."],[9,9,"﴿وَتُعَزِّرُوهُ﴾: وتَنْصُروا الله بِنصْرِ دِينِهِ.\n\n﴿وَتُوَقِّرُوهُ﴾: وتُعَظِّمُوا اللهَ.\n\n﴿بُكۡرَةࣰ﴾: أوَّلَ النَّهارِ.\n\n﴿وَأَصِيلًا﴾: آخِرَ النَّهارِ."],[10,10,"﴿يُبَايِعُونَكَ﴾: يُعاهِدُونَكَ على الطّاعةِ.\n\n﴿نَّكَثَ﴾: نَقَضَ بَيْعَتَهُ.\n\n﴿يَنكُثُ عَلَىٰ نَفۡسِهِۦ﴾: يَعُودُ وبالُ ذلِكَ عَلى نَفْسِهِ."],[11,11,"﴿ٱلۡمُخَلَّفُونَ﴾: الَّذِينَ تَخَلَّفُوا عَنِ الخُروجِ مَعَكَ إلى مكَّةَ."],[12,12,"﴿يَنقَلِبَ﴾: يَرْجِعَ.\n\n﴿بُورࣰا﴾: هَلْكى."],[13,13,"﴿أَعۡتَدۡنَا﴾: أعْدَدْنا.\n\n﴿سَعِيرࣰا﴾: نارًا مُؤَجَّجَةً."],[15,15,"﴿مَغَانِمَ﴾: غَنائِمِ خَيبَرَ.\n\n﴿ذَرُونَا﴾: اتْرُكُونا.\n\n﴿كَلَـٰمَ ٱللَّهِ﴾: وعْدَهُ لَكُم بِغنائِمِ خَيبَرَ، واخْتِصاصِها بِمَن شَهِدَ الحُدَيبِيَةَ."],[16,16,"﴿أُوْلِي بَأۡسࣲ﴾: أصْحابِ قُوَّةٍ.\n\n﴿وَإِن تَتَوَلَّوۡاْ﴾: تُعْرِضُوا."],[17,17,"﴿حَرَجࣱ﴾: إثْمٌ في تَخَلُّفِهِ عَنِ الجِهادِ."],[18,18,"﴿يُبَايِعُونَكَ﴾: يُعاهِدُونَكَ عَلى الطّاعِة والنُّصْرَةِ.\n\n﴿ٱلسَّكِينَةَ﴾: الطُّمأنِينةَ.\n\n﴿وَأَثَـٰبَهُمۡ﴾: جازاهُم.\n\n﴿فَتۡحࣰا قَرِيبࣰا﴾: هو فَتْحُ «خَيْبَرَ»."],[20,20,"﴿هَـٰذِهِۦ﴾: غَنائِمَ خَيبرَ.\n\n﴿وَكَفَّ﴾: ومَنَعَ."],[21,21,"﴿وَأُخۡرَىٰ﴾: وعَدَكُم رَبُّكُم فَتْحَ بَلْدَةٍ أُخْرى وهي مكَّةُ."],[23,23,"﴿سُنَّةَ ٱللَّهِ﴾: سَنَّ اللهُ ذَلِكَ سُنَّةً أي: جَعَلَهُ عادَةً لَهُ يَنْصُرُ المؤمِنينَ إذا نَصَرَوا دِينَهُ."],[24,24,"﴿بِبَطۡنِ مَكَّةَ﴾: الحُدَيبِيَةِ.\n\n﴿أَظۡفَرَكُمۡ عَلَيۡهِمۡ﴾: أيَّدكُم عَلَيهِم، ومَكَّنَكُم مِن رِّقابِهِم."],[25,25,"﴿وَٱلۡهَدۡيَ﴾: ما يُهْدى إلى الكَعْبَةِ مِنَ الأنْعامِ، أي: حَبَسُوا الهَدْيَ.\n\n﴿مَعۡكُوفًا﴾: مَحْبُوسًا.\n\n﴿مَحِلَّهُۥ﴾: مَكانَ حِلِّ نَحْرِه، وهو الحَرَمُ.\n\n﴿تَطَـُٔوهُمۡ﴾: تُهْلِكُوهُم.\n\n﴿مَّعَرَّةُۢ﴾: إثْمٌ وعَيبٌ وغَرامَةُ دِيَةٍ.\n\n﴿لَوۡ تَزَيَّلُواْ﴾: لو تَمَيَّزُوا وفارَقُوا."],[26,26,"﴿جَعَلَ﴾: وضَعَ.\n\n﴿ٱلۡحَمِيَّةَ﴾: الأَنفَةَ الَّتِي لا مُوجِبَ لَها.\n\n﴿حَمِيَّةَ ٱلۡجَـٰهِلِيَّةِ﴾: الحَمِيّةَ المنْسُوبةَ إلى الجاهِليَّةِ لحَقارَتِها وشَناعَتِها.\n\n﴿سَكِينَتَهُۥ﴾: الثَّباتَ والطُّمأنِينَةَ.\n\n﴿وَأَلۡزَمَهُمۡ﴾: جَعَلَها لازِمةً لَهُم لا يُفارِقُونَها.\n\n﴿كَلِمَةَ ٱلتَّقۡوَىٰ﴾: قولَ: لا إلَه إلّا اللهُ."],[27,27,"﴿صَدَقَ ٱللَّهُ رَسُولَهُ ٱلرُّءۡيَا﴾: صَدَّقَ اللهُ رَسُولَهُ في الرُّؤيا.\n\n﴿فَتۡحࣰا قَرِيبًا﴾: هو فَتْحُ خَيبرَ."],[28,28,"﴿بِٱلۡهُدَىٰ﴾: بِالبَيانِ الواضِحِ.\n\n﴿وَدِينِ ٱلۡحَقِّ﴾: دِينِ الإسْلامِ.\n\n﴿لِيُظۡهِرَهُۥ﴾: ليُعْلِيَهُ ويُشَرِّفَهُ.\n\n﴿شَهِيدࣰا﴾: شاهِدا."],[29,29,"﴿سِيمَاهُمۡ﴾: عَلامةُ طاعَتِهِم للهِ.\n\n﴿مِّنۡ أَثَرِ ٱلسُّجُودِ﴾: نُورٍ وسَمْتٍ حَسَنٍ.\n\n﴿مَثَلُهُمۡ﴾: صِفَتُهُم وحالَتُهُم العجِيبَةُ.\n\n﴿شَطۡـَٔهُۥ﴾: فُرُوعَهُ وفِراخَهُ.\n\n﴿فَـَٔازَرَهُۥ﴾: فَقَوّى الفَرْعُ أصْلَهُ.\n\n﴿فَٱسۡتَغۡلَظَ﴾: غَلُظَ غِلَظًا شَدِيدًا في نَوعِهِ.\n\n﴿سُوقِهِۦ﴾: جَمعُ ساقٍ، وهو الأصْلُ الَّذِي تَخرُجُ فِيهِ السَّنابلُ والأغْصانُ."]]);
QTF("gharib",49,[[1,1,"﴿لَا تُقَدِّمُواْ﴾: لا تَقْطَعُوا أمرًْا دُونَ اللهِ ورَسُولِهِ."],[2,2,"﴿أَن تَحۡبَطَ﴾: خَشْيَة أن تَبْطُلَ.\n\n﴿لَا تَشۡعُرُونَ﴾: لا تُحِسُّونَ."],[3,3,"﴿يَغُضُّونَ﴾: يَخْفِضُونَ.\n\n﴿ٱمۡتَحَنَ﴾: اخْتَبَرَ."],[4,4,"﴿ٱلۡحُجُرَ ٰ⁠تِ﴾: غُرَفِ النَّبِيِّ ﷺ."],[6,6,"﴿فَاسِقُۢ﴾: خارِجٌ عَن طاعَة اللهِ ورَسُولِهِ بارْتِكابِ الكبائِرِ.\n\n﴿بِنَبَإࣲ﴾: بأيِّ خَبَرٍ.\n\n﴿فَتَبَيَّنُوٓاْ﴾: فَتَبَيَّنُوا الحقَّ مِن غَيرِ جِهَةِ الفاسِقِ.\n\n﴿أَن تُصِيبُواْ﴾: خَشْيةَ أن تُصِيبُوا بضُرٍّ.\n\n﴿بِجَهَـٰلَةࣲ﴾: مُتَلَبّسِينَ بِعَدَمِ العِلمِ.\n\n﴿فَتُصۡبِحُواْ﴾: فتَصِيرُوا."],[7,7,"﴿لَعَنِتُّمۡ﴾: لَوَقَعْتُم في مَشَقَّةٍ وضَرَرٍ وإثْمٍ.\n\n﴿ٱلرَّ ٰ⁠شِدُونَ﴾: المُسْتَقِيمُونَ عَلى طَرِيقِ الحقِّ."],[9,9,"﴿بَغَتۡ﴾: اعْتَدَتْ، ولم تَقْبَلِ الصُّلْحَ.\n\n﴿تَفِيٓءَ﴾: تَرْجِعَ.\n\n﴿وَأَقۡسِطُوٓاْ﴾: واعْدِلُوا.\n\n﴿ٱلۡمُقۡسِطِينَ﴾: العادِلِينَ."],[11,11,"﴿يَسۡخَرۡ﴾: يَهْزَأْ.\n\n﴿وَلَا تَلۡمِزُوٓاْ أَنفُسَكُمۡ﴾: ولا يِعِبْ بَّعْضُكُم بَعْضا.\n\n﴿وَلَا تَنَابَزُواْ﴾: ولا يَدْعُ بعضُكُم بَعْضًا.\n\n﴿بِٱلۡأَلۡقَـٰبِ﴾: بِما يَكْرَهُ مِنَ الألقابِ.\n\n﴿ٱلِٱسۡمُ﴾: الذِّكْرُ والتَّسمِيَةُ.\n\n﴿ٱلۡفُسُوقُ﴾: ما ذُكِرَ مِنَ السُّخْرِيَةِ واللَّمْزِ والتنابُزِ بالألقابِ."],[12,12,"﴿وَلَا تَجَسَّسُواْ﴾: ولا تُفَتِّشُوا عَنْ عَوْراتِ المُسْلِمِينَ، وتَبْحَثُوا عَنْ أخْبارِهِم.\n\n﴿وَلَا يَغۡتَب بَّعۡضُكُم بَعۡضًا﴾: ولا يَذْكُرْ بَعْضُكُم بَعْضًا بِما يَكْرَهُ في غَيبَتِهِ."],[13,13,"﴿شُعُوبࣰا﴾: نَسَبًا بِعِيدًا، وهي أكْثَرُ مِنَ القبائِل.\n\n﴿وَقَبَآئِلَ﴾: نَسَبًا قَرِيبا، وهي تَدْخُل تَحْتَ الشُّعوبِ.\n\n﴿لِتَعَارَفُوٓاْ﴾: لِيَعْرِفَ بَعْضُكُم بَعْضًا.\n\n﴿أَكۡرَمَكُمۡ﴾: أشْرَفَكُم."],[14,14,"﴿ٱلۡأَعۡرَابُ﴾: هُمْ في الأَصْلِ سُكّانُ البادِيةِ مِنَ العَرَبِ، والمرادُ هُنا أعْرابُ بَنِي أسَدِ بن خُزَيْمَةَ.\n\n﴿لَا يَلِتۡكُم﴾: لا يَنْقُصْكُمُ."],[15,15,"﴿لَمۡ يَرۡتَابُواْ﴾: لَمْ يَشُكُّوا."],[16,16,"﴿أَتُعَلِّمُونَ ٱللَّهَ بِدِينِكُمۡ﴾: أتُخْبِرُونَهُ بِطاعَتِكُم؟"],[17,17,"﴿لَّا تَمُنُّواْ﴾: لا تَذْكُرُوا إنْعامَكُم."]]);
QTF("gharib",50,[[1,1,"﴿قٓ﴾: سَبَقَ الكلامُ على الحُروفِ المُقَطَّعةِ في أوَّلِ سُورَةِ البقرةِ.\n\n﴿ٱلۡمَجِيدِ﴾: ذي المجْدِ والشَّرَفِ."],[2,2,"﴿عَجِيبٌ﴾: مُسْتَغْرَبٌ يُتَعَجَّبُ مِنهُ."],[3,3,"﴿رَجۡعُۢ﴾: بَعْثٌ."],[4,4,"﴿تَنقُصُ ٱلۡأَرۡضُ﴾: تُفْنِي مِن أجْسامِهِم.\n\n﴿حَفِيظُۢ﴾: مَحفُوظٌ."],[5,5,"﴿مَّرِيجٍ﴾: مُخْتَلِطٍ مُضْطَرِبٍ."],[6,6,"﴿فُرُوجࣲ﴾: شُقُوقٍ وُصُدُوعٍ."],[7,7,"﴿مَدَدۡنَـٰهَا﴾: بَسَطْناها.\n\n﴿رَوَ ٰ⁠سِيَ﴾: جِبالًا ثَوابِتَ.\n\n﴿زَوۡجِۭ﴾: نَوْعٍ وجِنْسٍ.\n\n﴿بَهِيجࣲ﴾: حَسَنِ المنْظَر."],[8,8,"﴿تَبۡصِرَةࣰ﴾: تَجْعَلُ المرءَ مُبْصِرًا.\n\n﴿وَذِكۡرَىٰ﴾: تُذَكِّرُ النّاسِي.\n\n﴿مُّنِيبࣲ﴾: رَجّاعٍ إلى اللهِ."],[9,9,"﴿مُّبَـٰرَكࣰا﴾: كَثِيرَ الخيَرِ والمنافِعِ.\n\n﴿وَحَبَّ ٱلۡحَصِيدِ﴾: وحَبَّ الزَّرْعِ المحْصُودِ."],[10,10,"﴿بَاسِقَـٰتࣲ﴾: مُرْتَفِعاتٍ.\n\n﴿طَلۡعࣱ﴾: هُو أوَّلُ ما يَظْهَرُ مِن ثَمَرِ التَّمْرِ وهُو غِلافُ العُنْقُودِ.\n\n﴿نَّضِيدࣱ﴾: مَنضُودٌ، مُصَفَّفٌ بعْضُهُ فَوْقَ بَعْضٍ."],[11,11,"﴿مَّيۡتࣰا﴾: أجْدَبَتْ وقَحَطَتْ.\n\n﴿كَذَ ٰ⁠لِكَ﴾: كَما أحْيا اللهُ هَذِه الأَرْضَ الميتَةَ.\n\n﴿ٱلۡخُرُوجُ﴾: خَرُوجُ النّاسِ يَومَ البعْثِ."],[12,12,"﴿ٱلرَّسِّ﴾: البِئْرِ."],[14,14,"﴿وَأَصۡحَـٰبُ ٱلۡأَيۡكَةِ﴾: أصْحابُ الشَّجَرِ المُلْتَفِّ وهم قُوُم شُعَيبٍ عَلَيهِ السَّلامُ.\n\n﴿وَقَوۡمُ تُبَّعࣲ﴾: هُم سَبأٌ، وتُبَّعٌ هُوَ أحَدُ مُلُوكِ اليمَنِ.\n\n﴿فَحَقَّ﴾: صَدَقَ وتَحَقَّقَ.\n\n﴿وَعِيدِ﴾: إنذارِي بالعُقُوبةِ."],[15,15,"﴿أَفَعَيِينَا﴾: أفَعَجَزْنا.\n\n﴿لَبۡسࣲ﴾: اشْتِباهٍ وشَكٍّ.\n\n﴿خَلۡقࣲ جَدِيدࣲ﴾: قِيامِ الخَلْقِ في البَعْثِ."],[16,16,"﴿مَا تُوَسۡوِسُ بِهِۦ﴾: تُحَدِّث بِه.\n\n﴿حَبۡلِ ٱلۡوَرِيدِ﴾: عِرْقِ العُنُقِ المُتَّصِلِ بالقلبِ."],[17,17,"﴿يَتَلَقَّى﴾: يُسَجِّلُ.\n\n﴿ٱلۡمُتَلَقِّيَانِ﴾: المَلَكانِ المُوكَّلانِ بِكِتابَةِ أعْمالِ النّاسِ وأَقْوالِهِم.\n\n﴿عَنِ ٱلۡيَمِينِ﴾: عَن يَمِينِ الإنْسانِ.\n\n﴿قَعِيدࣱ﴾: مُقاعِدٌ، مِثْلُ جَلِيسٍ للمُجالِسِ."],[18,18,"﴿رَقِيبٌ﴾: مَلَكٌ يَرْقُبُ قَوْلَهُ ويَكْتُبُهُ.\n\n﴿عَتِيدࣱ﴾: حاضِرٌ مُعَدٌّ لِذَلِكَ."],[19,19,"﴿سَكۡرَةُ ٱلۡمَوۡتِ﴾: شِدَّةُ غَمَراتِ الموتِ.\n\n﴿تَحِيدُ﴾: تَفِرُّ وتَهْرُبُ."],[20,20,"﴿ٱلصُّورِ﴾: القَرْنِ الَّذِي يَنْفُخُ فِيهِ إسْرافِيلُ.\n\n﴿يَوۡمُ ٱلۡوَعِيدِ﴾: أي الَّذِي تَوَعَّدَ اللهُ بِه الكُفّارَ."],[21,21,"﴿سَآئِقࣱ﴾: مَلَكٌ يَسُوقُ الإنْسانَ إلى المَحْشَرِ.\n\n﴿وَشَهِيدࣱ﴾: مَلَكٌ يَشْهَدُ عَلى النَّفْسِ بِما عَمِلَتْ."],[22,22,"﴿حَدِيدࣱ﴾: قَوِيُّ الَّنفاذِ في المرئِي."],[23,23,"﴿قَرِينُهُۥ﴾: المَلَكُ الكاتِبُ الشَّهِيدُ عَلَيهِ.\n\n﴿عَتِيدٌ﴾: مُهَيَّأٌ محفُوظٌ."],[24,24,"﴿عَنِيدࣲ﴾: مُعانِدٍ لِلْحَقِّ."],[25,25,"﴿مُعۡتَدࣲ﴾: ظالِمٍ مُتَجاوِزٍ لْلِحَقِّ.\n\n﴿مُّرِيبٍ﴾: شاكٍّ."],[27,27,"﴿قَرِينُهُۥ﴾: شَيْطانُه الَّذِي كانَ مُوَكَّلًا بِهِ في الدُّنيا.\n\n﴿مَآ أَطۡغَيۡتُهُۥ﴾: ما أضْلَلْتُهُ.\n\n﴿ضَلَـٰلِۭ﴾: طَرِيقٍ بَعِيدٍ عن سَبِيلِ الهُدى."],[28,28,"﴿قَدَّمۡتُ إِلَيۡكُم بِٱلۡوَعِيدِ﴾: أعْلَمْتُكُم ما يَنْتَظِرُ العاصِيَ مِن العُقُوبَةِ."],[30,30,"﴿مَّزِيدࣲ﴾: زِيادةٍ في وارِدِيها."],[31,31,"﴿وَأُزۡلِفَتِ﴾: وقُرِّبَتْ.\n\n﴿غَيۡرَ بَعِيدٍ﴾: مَكانًا غَيرَ بَعِيدٍ مِنَ المُتَّقِينَ."],[32,32,"﴿أَوَّابٍ﴾: كَثِيرِ الرُّجُوعِ مِن ذُنُوبِهِ.\n\n﴿حَفِيظࣲ﴾: حافظٍ لِكُلِّ عَمَلٍ صالِحٍ قَرَّبَهُ إلى ربِّهِ."],[33,33,"﴿بِٱلۡغَيۡبِ﴾: في حالِ غِيابهِ عَنْ أعْيُنِ النّاسِ.\n\n﴿مُّنِيبٍ﴾: تائبٍ مِن ذُنُوبِهِ."],[34,34,"﴿بِسَلَـٰمࣲ﴾: وأَنْتُم سالِمُونَ.\n\n﴿يَوۡمُ ٱلۡخُلُودِ﴾: هُوَ الَّذِي لا زَوالَ لَهُ ولا مَوْتَ."],[35,35,"﴿مَزِيدࣱ﴾: النَّظَرُ إلى وجْهِ اللهِ الكريمِ."],[36,36,"﴿مِّن قَرۡنٍ﴾: مِن أُمَّةٍ.\n\n﴿بَطۡشࣰا﴾: قُوَّةً وسَطْوَةً.\n\n﴿فَنَقَّبُواْ﴾: فَطَوَّفُوا.\n\n﴿مَّحِيصٍ﴾: مَهْرَبٍ مِن عَذابِ اللهِ."],[37,37,"﴿قَلۡبٌ﴾: عَقْلٌ.\n\n﴿أَلۡقَى ٱلسَّمۡعَ﴾: أصْغى السَّمْعَ، واسْتَمَعَ بِأُذُنَيْهِ.\n\n﴿شَهِيدࣱ﴾: حاضِرٌ بِقَلْبِهِ."],[38,38,"﴿وَمَا مَسَّنَا﴾: وما أصابَنا.\n\n﴿لُّغُوبࣲ﴾: تَعَبٍ."],[40,40,"﴿وَأَدۡبَـٰرَ ٱلسُّجُودِ﴾: عَقِبَ الصَّلَواتِ."],[41,41,"﴿وَٱسۡتَمِعۡ﴾: أيُّها النَّبِيُّ لِما أُخْبِرُكَ بِهِ مِن أهْوالِ يَوْمِ القِيامَةِ.\n\n﴿ٱلۡمُنَادِ﴾: هُوَ المَلَكُ المُوَكَّلُ بِنَفْخِ الصُّورِ.\n\n﴿مَّكَانࣲ قَرِيبࣲ﴾: صَخْرَةِ بَيتِ المَقْدِسِ."],[42,42,"﴿بِٱلۡحَقِّ﴾: بِالصِّدْقِ.\n\n﴿يَوۡمُ ٱلۡخُرُوجِ﴾: يومُ البَعْثِ مِنَ القُبُورِ."],[44,44,"﴿تَشَقَّقُ﴾: تَتَصَدَّعُ.\n\n﴿سِرَاعࣰا﴾: مُسْرِعِينَ."],[45,45,"﴿بِجَبَّارࣲ﴾: بِمُسَلَّطٍ عَلَيهِم تُجْبِرُهُم عَلى الإيمانِ."]]);
QTF("gharib",51,[[1,1,"﴿وَٱلذَّ ٰ⁠رِيَـٰتِ﴾: الرِّياحِ المُثِيراتِ للتُّرابِ."],[2,2,"﴿فَٱلۡحَـٰمِلَـٰتِ﴾: فالسُّحُبِ الحامِلاتِ.\n\n﴿وِقۡرࣰا﴾: ثِقَلًا عَظِيمًا مِنَ الماءِ."],[3,3,"﴿فَٱلۡجَـٰرِيَـٰتِ﴾: فالسُّفُنِ الجارِياتِ في البِحارِ.\n\n﴿يُسۡرࣰا﴾: جَرْيًا ذا يُسْرٍ وسُهُولةٍ."],[4,4,"﴿فَٱلۡمُقَسِّمَـٰتِ﴾: فالملائِكةِ المُقَسِّماتِ.\n\n﴿أَمۡرًا﴾: أمْرَ اللهِ في خَلْقِهِ."],[5,5,"﴿لَصَادِقࣱ﴾: لَكائِنٌ حقٌّ يَقِينٌ."],[6,6,"﴿ٱلدِّينَ﴾: الحِسابَ.\n\n﴿لَوَ ٰ⁠قِعࣱ﴾: لَكائِنٌ لا مَحالةَ."],[7,7,"﴿ذَاتِ ٱلۡحُبُكِ﴾: ذاتِ الخَلْقِ الحَسَنِ."],[8,8,"﴿مُّخۡتَلِفࣲ﴾: مُضْطَرِبٍ."],[9,9,"﴿يُؤۡفَكُ﴾: يُصْرَفُ."],[10,10,"﴿قُتِلَ﴾: لُعِنَ.\n\n﴿ٱلۡخَرَّ ٰ⁠صُونَ﴾: الكَذّابُونَ الظّانُّونَ غيرَ الحقِّ."],[11,11,"﴿غَمۡرَةࣲ﴾: لُجَّةِ مِنَ الكُفْرِ.\n\n﴿سَاهُونَ﴾: غافِلُونَ."],[12,12,"﴿أَيَّانَ﴾: مَتى.\n\n﴿يَوۡمُ ٱلدِّينِ﴾: يومُ الجَزاءِ."],[13,13,"﴿يُفۡتَنُونَ﴾: يُعَذَّبُونَ بالإحْرِاقِ بالنّارِ."],[14,14,"﴿فِتۡنَتَكُمۡ﴾: عَذابَكُم."],[16,16,"﴿ءَاخِذِينَ﴾: قابِلينَ على وجْهِ الرِّضا.\n\n﴿ءَاتَىٰهُمۡ﴾: أعْطاهُم.\n\n﴿مُحۡسِنِينَ﴾: فاعِلِينَ الحَسَناتِ والطّاعاتِ."],[17,17,"﴿يَهۡجَعُونَ﴾: يَنامُونَ."],[18,18,"﴿وَبِٱلۡأَسۡحَارِ﴾: جَمْعُ سَحَر، وهُو آخِرُ الليلِ."],[19,19,"﴿حَقࣱّ﴾: واجِبٌ ثابِتٌ.\n\n﴿لِّلسَّآئِلِ﴾: الَّذِي يُظْهِرُ فَقْرَهُ فَيسْأَلُ النّاسَ.\n\n﴿وَٱلۡمَحۡرُومِ﴾: الفَقِيرِ الُمتَعَفِّفِ."],[20,20,"﴿لِّلۡمُوقِنِينَ﴾: لِأَهْلِ اليقِينِ بِأنّ اللهَ ورَسُولَه حَقٌّ."],[21,21,"﴿وَفِيٓ أَنفُسِكُمۡ﴾: وفي خَلْقِ أنْفُسِكُم دَلائِلُ وعِبَرٌ."],[22,22,"﴿رِزۡقُكُمۡ﴾: مادَّةُ رِزْقِكُم مِنَ الأمْطارِ وما قَدَّرَهُ اللهُ.\n\n﴿وَمَا تُوعَدُونَ﴾: مِنَ الجَزاءِ في الدُّنيا والآخِرةِ."],[23,23,"﴿مِّثۡلَ مَآ أَنَّكُمۡ تَنطِقُونَ﴾: فَتَحَقَّقَ الوعِيدُ مِثْلَ نُطْقِكُم الَّذِي لا تَشُكُّونَ فِيهِ."],[24,24,"﴿ضَيۡفِ إِبۡرَ ٰ⁠هِيمَ﴾: هُم مِن الملائِكةِ."],[25,25,"﴿سَلَـٰمࣰا﴾: سَلَّمنا سَلاما.\n\n﴿سَلَـٰمࣱ﴾: أمْرِي سَلامٌ لَكُم.\n\n﴿مُّنكَرُونَ﴾: لا أعْرِفُهُم."],[26,26,"﴿فَرَاغَ﴾: فَمال خِفْيَةً."],[28,28,"﴿فَأَوۡجَسَ﴾: أحَسَّ في نَفْسِهِ.\n\n﴿بِغُلَـٰمٍ عَلِيمࣲ﴾: هو إسْحاقُ عَلَيهِ السَّلامُ."],[29,29,"﴿صَرَّةࣲ﴾: صَيْحَةٍ.\n\n﴿فَصَكَّتۡ﴾: فَلَطَمَتْ.\n\n﴿عَقِيمࣱ﴾: لا تَحْمِلُ."],[31,31,"﴿فَمَا خَطۡبُكُمۡ﴾: فَما شَأنُكُم؟"],[32,32,"﴿قَوۡمࣲ مُّجۡرِمِينَ﴾: هُم قَومُ لُوطٍ عَلَيهِ السَّلامُ."],[34,34,"﴿مُّسَوَّمَةً﴾: عَلَيها عَلامةٌ، وكَلُّ حَجَرٍ عَلَيهِ اسْمُ صاحِبِهِ.\n\n﴿لِلۡمُسۡرِفِينَ﴾: للمُفَرِّطِينَ بِكُفْرِهِم وشِيُوعِ الفاحِشَةِ فِيهِم."],[36,36,"﴿بَيۡتࣲ﴾: بيتِ لُوطٍ عَلَيهِ السَّلامُ."],[37,37,"﴿تَرَكۡنَا﴾: أبْقينا.\n\n﴿ءَايَةࣰ﴾: أثَرًا مِن العَذابِ والخَرابِ يُتَّعظُ بِها."],[38,38,"﴿بِسُلۡطَـٰنࣲ﴾: بِحُجَّةٍ."],[39,39,"﴿فَتَوَلَّىٰ﴾: فَأَعْرَضَ.\n\n﴿بِرُكۡنِهِۦ﴾: بِقُوَّتِهِ وجانِبِهِ."],[40,40,"﴿فَأَخَذۡنَـٰهُ﴾: فَأَهْلَكْناهُ.\n\n﴿فَنَبَذۡنَـٰهُمۡ﴾: فَطَرحْناهُم.\n\n﴿ٱلۡيَمِّ﴾: البَحْرِ.\n\n﴿مُلِيمࣱ﴾: مُسْتَوْجِبٌ العِقابَ، آتٍ بِما يَلُومُهُ اللهُ عَلَيهِ."],[41,41,"﴿ٱلۡعَقِيمَ﴾: التي لا بَرَكَةَ فِيها ولا تَأْتِي بِخَيرٍ."],[42,42,"﴿مَا تَذَرُ﴾: ما تَدَعُ.\n\n﴿كَٱلرَّمِيمِ﴾: العَظْمِ الَّذِي بَلِي فَتَفَتَّتَ."],[43,43,"﴿تَمَتَّعُواْ﴾: مُباحٌ لكُم أن تَتَمَتَّعُوا بِنِعَمِ الدُّنيا الزّائِلةِ.\n\n﴿حَتَّىٰ حِينࣲ﴾: إلى آجالِكُم."],[44,44,"﴿فَعَتَوۡاْ﴾: تَكَبَّرُوا فَأَعْرَضُوا.\n\n﴿فَأَخَذَتۡهُمُ﴾: فَأَصابَتْهُم.\n\n﴿ٱلصَّـٰعِقَةُ﴾: الصَّيحَةُ العَظِيمَةُ الُمهْلِكَةُ.\n\n﴿يَنظُرُونَ﴾: إلى عُقُوبَتِهِم بأَعْيُنِهِم فَيَكُونُ أشَدَّ للعُقُوبَةِ."],[45,45,"﴿قِيَامࣲ﴾: نُهُوضٍ ودِفاعٍ."],[47,47,"﴿بَنَيۡنَـٰهَا﴾: خَلَقْناها وجَعَلْناها سَقْفًا لِلأَرْضِ.\n\n﴿بِأَيۡيْدࣲ﴾: بِقُوِّةٍ.\n\n﴿لَمُوسِعُونَ﴾: لَمُقْتَدِرُونَ، مِن أوْسَعَ إذا كانَ ذا وُسْعٍ وهي القُدْرَةُ."],[48,48,"﴿فَرَشۡنَـٰهَا﴾: جَعَلْناها فِراشًا لاسْتِقْرارِ الخَلْقِ عَلَيها.\n\n﴿ٱلۡمَـٰهِدُونَ﴾: المُوطِّئُونَ الَمُهَيِّئُونَ."],[49,49,"﴿زَوۡجَيۡنِ﴾: صِنْفَينِ ذَكَرًا وأُنْثى."],[50,50,"﴿فَفِرُّوٓاْ﴾: فارِقُوا الشِّرْكَ المُسَبِّبَ لِعَذابِكُم."],[53,53,"﴿أَتَوَاصَوۡاْ﴾: هَلْ أوصْىَ بَعْضُهُم بَعْضًا؟\n\n﴿طَاغُونَ﴾: مُتَعَدُّونَ، طُغاةٌ عَنْ أمْرِ رَبِّهِم."],[54,54,"﴿فَتَوَلَّ عَنۡهُمۡ﴾: فأَعْرِضْ عَنْهُم.\n\n﴿فَمَآ أَنتَ بِمَلُومࣲ﴾: فَلَيسَ عَلَيكَ لَوْمٌ في ذَنْبِهِم."],[55,55,"﴿ٱلذِّكۡرَىٰ﴾: التَّذْكِيرَ والمَوعِظَةَ."],[56,56,"﴿لِيَعۡبُدُونِ﴾: إرادَةَ أن يَعْبُدُونِي إرادَةً شَرْعِيَّةً دِينِيَّةً، وقَدْ تَقَعُ العِبادة وقَدْ لا تَقَعُ."],[58,58,"﴿ٱلۡمَتِينُ﴾: الشَّدِيدُ الكامِلُ في قُوَّتِهِ."],[59,59,"﴿ذَنُوبࣰا﴾: حَظًّا ونَصِيبًا."],[60,60,"﴿فَوَيۡلࣱ﴾: عَذابٌ وهَلاكٌ."]]);
QTF("gharib",52,[[1,1,"﴿وَٱلطُّورِ﴾: هُوَ الجَبَلُ الَّذِي كَلَّمَ اللهُ عَلَيهِ مُوسى عَلَيهِ السَّلامُ."],[2,2,"﴿مَّسۡطُورࣲ﴾: مَكْتُوبٍ، وهُو القُرآنُ."],[3,3,"﴿فِي رَقࣲّ مَّنشُورࣲ﴾: مَكْتُوبٍ في صَحِيفةٍ مَبْسُوطَةٍ."],[4,4,"﴿وَٱلۡبَيۡتِ ٱلۡمَعۡمُورِ﴾: هو فَوْقَ السَّماءِ السّابِعةِ تَطُوفُ بِه الملائِكةُ دائِمًا."],[5,5,"﴿وَٱلسَّقۡفِ ٱلۡمَرۡفُوعِ﴾: هو السَّماءُ الدُّنيا، جَعَلَها اللهُ سَقْفًا للأرْضِ."],[6,6,"﴿ٱلۡمَسۡجُورِ﴾: الممْلُوءِ بالمياهِ."],[8,8,"﴿دَافِعࣲ﴾: مانِعٍ يَمْنَعُه حِينَ وقُوعِهِ."],[9,9,"﴿تَمُورُ﴾: تَتَحرَّكُ وتَضْطَرِبُ."],[10,10,"﴿وَتَسِيرُ﴾: تَزُولُ عَنْ أماكِنِها وتَسيرُ كَسَيرِ السَّحابِ."],[11,11,"﴿فَوَيۡلࣱ﴾: فَهَلاكٌ."],[12,12,"﴿فِي خَوۡضࣲ﴾: في انْدِفاعٍ في الكَلامِ الباطِلِ.\n\n﴿يَلۡعَبُونَ﴾: يَسْتَهْزِئُونَ."],[13,13,"﴿يُدَعُّونَ﴾: يُدْفَعُونَ.\n\n﴿دَعًّا﴾: دَفْعًا بِعُنْفٍ ومهانَةٍ."],[16,16,"﴿ٱصۡلَوۡهَا﴾: ادْخُلُوها واحْتَرِقُوا بِنارِها."],[18,18,"﴿فَـٰكِهِينَ﴾: طَيِّبَةً أنْفُسُكُم مُتَمَتِّعِينَ عَلى وجْهِ السُّرِورِ."],[19,19,"﴿هَنِيٓـَٔۢا﴾: أكْلًا وشُرْبًا هَنِيئًا أي سائِغًا."],[20,20,"﴿مُتَّكِـِٔينَ﴾: جالِسِين عَلى وجْهِ التَّمَكُّن والرّاحةِ.\n\n﴿سُرُرࣲ﴾: جَمْعُ سَرِيرٍ وهو ما يُضْطَجَعُ عَلَيهِ، وهو مَجْلِسُ المنَعَّمِينَ.\n\n﴿مَّصۡفُوفَةࣲ﴾: مُتَقابِلَةٍ.\n\n﴿وَزَوَّجۡنَـٰهُم﴾: قَرَنّاهُم.\n\n﴿بِحُورٍ﴾: بِنِساءٍ شَدِيداتِ بَياضِ العَينِ وسَوادها.\n\n﴿عِينࣲ﴾: واسِعاتِ العُيونِ حِسانِهِنَّ."],[21,21,"﴿وَمَآ أَلَتۡنَـٰهُم﴾: وما نَقَصْناهُم.\n\n﴿رَهِينࣱ﴾: مَحْبُوسٌ مقْرُونٌ."],[22,22,"﴿وَأَمۡدَدۡنَـٰهُم﴾: وزِدْناهُم."],[23,23,"﴿يَتَنَـٰزَعُونَ﴾: يَتَعاطَونَ، ويُناوِلُ بعضُهم بَعْضًا.\n\n﴿كَأۡسࣰا﴾: إناءً مَمْلُوءًا مِنَ الخَمْرِ.\n\n﴿لَغۡوࣱ﴾: كَلامٌ لا فائِدةَ فِيهِ.\n\n﴿تَأۡثِيمࣱ﴾: إثْمٌ ومَعْصِيَةٌ."],[24,24,"﴿مَّكۡنُونࣱ﴾: مَصُونٌ في أصْدافِهِ."],[26,26,"﴿مُشۡفِقِينَ﴾: خائِفِينَ مِن عَذابِ رَبِنا."],[27,27,"﴿ٱلسَّمُومِ﴾: نارِ جَهَنَّمَ وحَرارَتِها."],[28,28,"﴿ٱلۡبَرُّ﴾: المُحْسِنُ."],[29,29,"﴿بِنِعۡمَتِ رَبِّكَ﴾: بمَنِّهِ ولُطْفِهِ.\n\n﴿بِكَاهِنࣲ﴾: يُخْبِرُ بالغَيبِ دُونَ عِلْمٍ."],[30,30,"﴿نَّتَرَبَّصُ﴾: نَنْتَظِرُ.\n\n﴿رَيۡبَ ٱلۡمَنُونِ﴾: حوادِثَ الدَّهرِ فَيَمُوتُ."],[32,32,"﴿أَحۡلَـٰمُهُم﴾: عُقُولُهم.\n\n﴿طَاغُونَ﴾: مُتَجاوِزُونَ الحدَّ."],[33,33,"﴿تَقَوَّلَهُۥ﴾: اخْتَلَقَهُ."],[37,37,"﴿ٱلۡمُصَۜيۡطِرُونَ﴾: المُتَسَلِّطُونَ."],[38,38,"﴿سُلَّمࣱ﴾: دَرَجٌ ومَصْعَدٌ إلى السَّماءِ.\n\n﴿يَسۡتَمِعُونَ﴾: الكَلامَ الَّذِي يَجْرِي في السَّماءِ ويَسْتَرِقُونَهُ.\n\n﴿بِسُلۡطَـٰنࣲ﴾: بِحُجَّةٍ."],[40,40,"﴿مَّغۡرَمࣲ﴾: غَرامةٍ مَطْلُوبَةٍ مِنهُم."],[42,42,"﴿كَيۡدࣰا﴾: مَكْرًا.\n\n﴿ٱلۡمَكِيدُونَ﴾: يَعُودُ ضَرَرُ مَكْرِهِم عَلَيهِم."],[44,44,"﴿كِسۡفࣰا﴾: قِطَعًا كِبارًا مِنَ العَذابِ.\n\n﴿مَّرۡكُومࣱ﴾: مُتَراكِمٌ بَعْضُهُ فَوْقَ بَعْضٍ."],[45,45,"﴿فَذَرۡهُمۡ﴾: فَدَعْهُم.\n\n﴿يُصۡعَقُونَ﴾: يُهلَكُونَ، وهو يومُ القِيامَةِ."],[46,46,"﴿لَا يُغۡنِي﴾: لا يَدْفَعُ."],[47,47,"﴿عَذَابࣰا دُونَ ذَ ٰ⁠لِكَ﴾: مِنَ القَتْلِ والسَّبْيِ وعَذابِ القَبْرِ."],[48,48,"﴿بِأَعۡيُنِنَا﴾: بِمَرْأىً مِنّا وحِفْظٍ واعْتِناءٍ.\n\n﴿حِينَ تَقُومُ﴾: إلى الصَّلاةِ، وحِينَ تَقُومُ مِنَ النَّومِ."],[49,49,"﴿وَإِدۡبَـٰرَ ٱلنُّجُومِ﴾: عِنْدَ صَلاةِ الصُّبْحِ حِينَ يُغَطِّي ضَوءُ الصُّبْحِ النُّجُومَ."]]);
QTF("gharib",53,[[1,1,"﴿هَوَىٰ﴾: غابَ."],[2,2,"﴿غَوَىٰ﴾: خَرَجَ عنِ الرَّشادِ."],[3,3,"﴿ٱلۡهَوَىٰٓ﴾: ما تَمِيلُ إلَيهِ النَّفْسُ مِن غَيرِ دَلِيلٍ."],[5,5,"﴿شَدِيدُ ٱلۡقُوَىٰ﴾: مَلَكٌ شَدِيدُ القُوَّةِ."],[6,6,"﴿مِرَّةࣲ﴾: مَنظَرٍ حَسَنٍ.\n\n﴿فَٱسۡتَوَىٰ﴾: عَلى صُورَتِهِ الحقِيقِيَّةِ للرَّسولِ ﷺ."],[7,7,"﴿بِٱلۡأُفُقِ ٱلۡأَعۡلَىٰ﴾: أُفُقِ الشَّمسِ عِنْدَ مَطْلَعِها."],[8,8,"﴿فَتَدَلَّىٰ﴾: فَزادَ في القُرْبِ."],[9,9,"﴿قَابَ قَوۡسَيۡنِ﴾: مِقْدارَ قَوسَينِ."],[11,11,"﴿ٱلۡفُؤَادُ﴾: قَلْبُه."],[12,12,"﴿أَفَتُمَـٰرُونَهُۥ﴾: أتُكَذِّبُونَ مُحَمَّدًا ﷺ فَتُجادِلُونَه عَلى ما يَراهُ مِن آياتِ رَبِّهِ؟"],[13,13,"﴿رَءَاهُ﴾: رَأى مُحَمّدٌ ﷺ جِبْرِيلَ.\n\n﴿نَزۡلَةً﴾: مَرَّةً."],[14,14,"﴿سِدۡرَةِ ٱلۡمُنتَهَىٰ﴾: شَجَرةِ نَبْقٍ في السَّماءِ السّابِعةِ، يَنْتَهي إلَيها ما يُعْرَجُ بِهِ مِنَ الأَرْضِ، وما يُهْبَطُ بِه مِن فَوْقِها."],[16,16,"﴿يَغۡشَى ٱلسِّدۡرَةَ﴾: يُغَطِّيها ويَسْتُرُها."],[17,17,"﴿زَاغَ﴾: مالَ.\n\n﴿طَغَىٰ﴾: جاوَزَ ما أُمِرَ برُؤْيَتِهِ."],[18,18,"﴿ءَايَـٰتِ﴾: دَلائلِ عَظَمةِ اللهِ."],[19,20,"﴿ٱللَّـٰتَ وَٱلۡعُزَّىٰ ۞ وَمَنَوٰةَ﴾: هي أصْنامٌ اتَّخَذَها العَربُ آلِهَةً.\n\n﴿ٱلثَّالِثَةَ ٱلۡأُخۡرَىٰٓ﴾: صِفَتا تأكيدٍ لمناةٍ."],[22,22,"﴿ضِيزَىٰٓ﴾: جائِرةٌ."],[23,23,"﴿سُلۡطَـٰنٍ﴾: حُجَّةٍ.\n\n﴿تَهۡوَى﴾: تَشْتَهِيهِ وتَمِيلُ إلَيهِ."],[24,24,"﴿تَمَنَّىٰ﴾: اشْتَهى."],[26,26,"﴿وَكَم مِّن مَّلَكࣲ﴾: وكَثِيرٍ مِنَ الملائِكَةِ."],[27,27,"﴿تَسۡمِيَةَ ٱلۡأُنثَىٰ﴾: صِفَةَ الأُنْثى، وهي أن يُقالَ لَها: بِنْتٌ."],[28,28,"﴿ٱلظَّنَّ﴾: التَّوهُّمَ الباطِلَ.\n\n﴿لَا يُغۡنِي﴾: لا يُجدِي ولا يَقُومُ مَقامَ الحَقِّ."],[30,30,"﴿مَبۡلَغُهُم مِّنَ ٱلۡعِلۡمِ﴾: مُنْتَهى عِلْمِهِم، لا عِلْمَ لَهُم فَوْقَهُ؛ والمرادُ ظَنُّهُم الفاسِدُ."],[31,31,"﴿بِٱلۡحُسۡنَى﴾: بالجنَّةِ."],[32,32,"﴿ٱللَّمَمَ﴾: الذُّنُوبَ الصِّغارَ الَّتِي لا يُصِرُّ صاحِبُها عَلَيها، أو يُلِمُّ بِها على وجْهِ النُّدْرَةِ.\n\n﴿أَنشَأَكُم مِّنَ ٱلۡأَرۡضِ﴾: خَلَقَ أباكُم آدمَ مِن تُرابٍ.\n\n﴿فَلَا تُزَكُّوٓاْ أَنفُسَكُمۡ﴾: فَتَمْدَحُوها بالتَّقْوى."],[33,33,"﴿تَوَلَّىٰ﴾: أعْرَضَ عَن طاعَةِ اللهِ."],[34,34,"﴿وَأَكۡدَىٰٓ﴾: تَوَقَّفَ عَنِ العَطاءِ."],[36,36,"﴿صُحُفِ مُوسَىٰ﴾: هي أسْفارُ التَّوراةِ."],[37,37,"﴿وَإِبۡرَ ٰ⁠هِيمَ﴾: وصُحُفِ إبراهِيمَ التي سُجِّل فيها ما أوْحى اللهُ إليهِ.\n\n﴿وَفَّىٰٓ﴾: بَلَّغَ ما أُرْسِلَ بِه."],[38,38,"﴿أَلَّا تَزِرُ﴾: أي لا تَحْمِلُ ولا تُؤاخَذُ.\n\n﴿وَازِرَةࣱ﴾: حاملةُ إثْمٍ."],[39,39,"﴿لَّيۡسَ لِلۡإِنسَـٰنِ إِلَّا مَا سَعَىٰ﴾: لا يَحْصُلُ للإنسانِ مِنَ الأجْرِ إلّا ما كَسَبَ هُوَ لِنَفْسِهِ بِسَعْيِهِ."],[40,40,"﴿سَعۡيَهُۥ﴾: عَمَلَه واكْتِسابَه.\n\n﴿يُرَىٰ﴾: يُشاهَدُ عِنْدَ الحسابِ."],[41,41,"﴿يُجۡزَىٰهُ﴾: يُجزى الإنسانُ عَلى سَعْيِهِ.\n\n﴿ٱلۡأَوۡفَىٰ﴾: التامَّ الكامِلَ."],[42,42,"﴿ٱلۡمُنتَهَىٰ﴾: انْتِهاءَ جَمِيعِ خَلْقِهِ ورُجُوعَهُم إلى حُكْمِهِ في الآخِرةِ."],[43,43,"﴿أَضۡحَكَ وَأَبۡكَىٰ﴾: خَلَقَ في الإنْسانِ قُوَّتَي الضَّحِكِ والبُكاءِ وأَسْبابَهُما مِن سُرورٍ وحُزْنٍ."],[44,44,"﴿أَمَاتَ وَأَحۡيَا﴾: انْفَرَدَ بالإماتَةِ والإحْياءِ."],[46,46,"﴿نُّطۡفَةٍ﴾: ماءٍ قَلِيلٍ.\n\n﴿تُمۡنَىٰ﴾: تُصَبُّ في الرَّحِمِ وتُقْذَفُ."],[47,47,"﴿ٱلنَّشۡأَةَ﴾: الخَلقَ.\n\n﴿ٱلۡأُخۡرَىٰ﴾: الأخِيَرةَ الَّتِي لا نَشْأَةَ بَعْدَها."],[48,48,"﴿وَأَقۡنَىٰ﴾: أرضى الَّذِي أغْناهُ."],[49,49,"﴿ٱلشِّعۡرَىٰ﴾: نَجْمٍ مُضِيءٍ كانَ يَعْبُدُهُ بَعْضُ أهْل الجاهِلِيَّةِ."],[50,50,"﴿عَادًا ٱلۡأُولَىٰ﴾: قَوْمَ نَبِيِّ اللهِ هُودٍ عَلَيهِ السَّلامُ، وهي أوَّلُ العرَبِ البائِدةِ."],[51,51,"﴿وَثَمُودَاْ﴾: قَوْمَ نَبِيِّ اللهِ صالِحٍ عَلَيهِ السَّلامُ.\n\n﴿فَمَآ أَبۡقَىٰ﴾: فَما تَرَكَها بَلْ أهْلَكَها."],[52,52,"﴿وَأَطۡغَىٰ﴾: أشَدَّ طَغْيانًا وتَمَرُّدًا على اللهِ."],[53,53,"﴿وَٱلۡمُؤۡتَفِكَةَ﴾: هي القُرى المَخْسُوفُ بِها، المقلوبُ أعلاها أسفلها، وهي قُرى قَوْمِ لُوطٍ عَلَيهِ السَّلامُ.\n\n﴿أَهۡوَىٰ﴾: أسْقَطَ، فَجَعَلَها هاوِيَةً."],[54,54,"﴿فَغَشَّىٰهَا مَا غَشَّىٰ﴾: فَأَلْبَسَها ما ألْبَسَها مِنَ الحِجارَةِ المُتَتابِعَةِ النّازِلَةِ عَلَيهِم."],[55,55,"﴿ءَالَآءِ﴾: نِعَمِ، جَمْعُ إلىً.\n\n﴿تَتَمَارَىٰ﴾: تَتَشَكَّكُ."],[56,56,"﴿هَـٰذَا﴾: الَّذِي أنْذَرْتُكُم بِهِ مِنَ الوقائِعِ.\n\n﴿نَذِيرࣱ﴾: إنْذارٌ.\n\n﴿مِّنَ ٱلنُّذُرِ ٱلۡأُولَىٰٓ﴾: الَّتي أنْذَرْتُها الأُمَمَ الَّتي قَبْلَكُم."],[57,57,"﴿أَزِفَتِ﴾: قَرُبَتْ.\n\n﴿ٱلۡـَٔازِفَةُ﴾: القِيامَةُ."],[58,58,"﴿لَيۡسَ لَهَا مِن دُونِ ٱللَّهِ كَاشِفَةٌ﴾: لا يَعْلَمُ بوَقْتِ وُقُوعِها إلّا اللهُ."],[59,59,"﴿هَـٰذَا ٱلۡحَدِيثِ﴾: القرآنِ.\n\n﴿تَعۡجَبُونَ﴾: مِن أن يَكُونَ صَحِيحًا."],[60,60,"﴿وَتَضۡحَكُونَ﴾: مِنهُ سُخْرِيَةً واسْتِهْزاءً.\n\n﴿وَلَا تَبۡكُونَ﴾: خَوْفًا مِن وعِيدِهِ."],[61,61,"﴿سَـٰمِدُونَ﴾: لاهُونَ مُعْرِضُونَ عَنْهُ."]]);
QTF("gharib",54,[[1,1,"﴿ٱلسَّاعَةُ﴾: القِيامَةُ.\n\n﴿وَٱنشَقَّ﴾: انْفَلَقَ فِلْقَتَينِ."],[2,2,"﴿ءَايَةࣰ﴾: بُرْهانًا عَلى صِدْقِ الرَّسُولِ مُحَمَّدٍ ﷺ.\n\n﴿مُّسۡتَمِرࣱّ﴾: ذاهِبٌ مُضْمَحِلٌّ لا دَوامَ لَهُ."],[3,3,"﴿أَهۡوَآءَهُمۡ﴾: ما تُحِبُّهُ أنفُسُهُم مِنَ الضَّلالِ والتَّكْذِيبِ.\n\n﴿أَمۡرࣲ﴾: مِن خَيرٍ أوْ شَرٍّ.\n\n﴿مُّسۡتَقِرࣱّ﴾: واقِعٌ بأَهْلِهِ يَوْمَ القِيامَةِ."],[4,4,"﴿مُزۡدَجَرٌ﴾: كِفايَةٌ لِرَدْعِهم."],[5,5,"﴿حِكۡمَةُۢ﴾: هَذا القُرْآنُ فِيهِ حِكْمَةٌ عَظِيمةٌ.\n\n﴿بَـٰلِغَةࣱ﴾: بالِغَةٌ غايَتَها.\n\n﴿فَمَا﴾: فأيُّ شَيءٍ.\n\n﴿تُغۡنِ﴾: تَدْفَعُ أوْ تَنْفَعُ.\n\n﴿ٱلنُّذُرُ﴾: الإنْذاراتُ."],[6,6,"﴿فَتَوَلَّ﴾: فَأَعْرِضْ.\n\n﴿ٱلدَّاعِ﴾: المَلَكُ بنَفْخِهِ في «القَرْنِ».\n\n﴿نُّكُرٍ﴾: فَظِيعٍ مُنْكَرٍ وهو موقِفُ الحِسابِ."],[7,7,"﴿خُشَّعًا﴾: ذَلِيلَةً.\n\n﴿ٱلۡأَجۡدَاثِ﴾: القُبُورِ.\n\n﴿مُّنتَشِرࣱ﴾: مُنْبَثٌّ عَلى وجْهِ الأرْضِ."],[8,8,"﴿مُّهۡطِعِينَ﴾: مُسْرِعِينَ مادِّينَ أعْناقَهُم.\n\n﴿ٱلدَّاعِ﴾: صوتِ المَلَكِ.\n\n﴿عَسِرࣱ﴾: شَدِيدُ الهَوْلِ."],[9,9,"﴿وَٱزۡدُجِرَ﴾: وانْتَهَرُوهُ مُتَوَعِّدِينَ إيّاهُ بأنْواعِ الأَذى."],[10,10,"﴿مَغۡلُوبࣱ﴾: ضَعِيفٌ عَن مُقاوَمةِ هَؤُلاءِ.\n\n﴿فَٱنتَصِرۡ﴾: لِي بِعِقابٍ مِن عِنْدِكَ."],[11,11,"﴿مُّنۡهَمِرࣲ﴾: كَثِيرٍ مُتَدَفِّقٍ."],[12,12,"﴿وَفَجَّرۡنَا﴾: وشَقَقْنا.\n\n﴿عُيُونࣰا﴾: مِن عُيُونٍ مُتَفَجِّرَةٍ بالماءِ.\n\n﴿فَٱلۡتَقَى ٱلۡمَآءُ﴾: فالتَقى ماءُ السَّماءِ وماءُ الأرْضِ.\n\n﴿عَلَىٰٓ أَمۡرࣲ قَدۡ قُدِرَ﴾: عَلى إهْلاكِهِم الَّذِي قَدَّرَهُ اللهُ لَهُم."],[13,13,"﴿ذَاتِ أَلۡوَ ٰ⁠حࣲ﴾: سَفِيَنةٍ ذاتِ ألْواحٍ.\n\n﴿وَدُسُرࣲ﴾: ومَسامِيرَ شُدَّتْ بِها."],[14,14,"﴿بِأَعۡيُنِنَا﴾: بِمَرْأىً مِنّا وحِفْظٍ."],[15,15,"﴿وَلَقَد تَّرَكۡنَـٰهَآ﴾: ولَقَدْ أبْقَينا قِصَّةَ نُوحٍ.\n\n﴿ءَايَةࣰ﴾: عِبْرةً.\n\n﴿مُّدَّكِرࣲ﴾: مُتَّعِظٍ."],[17,17,"﴿يَسَّرۡنَا﴾: سَهَّلْنا.\n\n﴿لِلذِّكۡرِ﴾: لِلتِّلاوَةِ والحِفْظِ والفَهْمِ والتَّدَبُّرِ."],[19,19,"﴿صَرۡصَرࣰا﴾: شَدِيدَةَ البَرْدِ والصَّوتِ.\n\n﴿نَحۡسࣲ﴾: شُؤْمٍ.\n\n﴿مُّسۡتَمِرࣲّ﴾: اسْتَمَرَّ بِهِمُ العَذابُ إلى أن وافى بِهِمْ جَهَنَّمَ."],[20,20,"﴿تَنزِعُ ٱلنَّاسَ﴾: تَقَلَعُ النّاسَ مِنَ الأرْضِ، فتَصْرَعُهم عَلى رُؤوسِهِم، فَتَنْدَقُّ رِقابُهُم وتَنْفَصِلُ عَنْ أجْسامِهِم.\n\n﴿أَعۡجَازُ﴾: أُصُولُ.\n\n﴿مُّنقَعِرࣲ﴾: مُنْقَلِعٍ."],[23,23,"﴿بِٱلنُّذُرِ﴾: بالآياتِ الَّتِي أُنْذِرُوا بِها."],[24,24,"﴿ضَلَـٰلࣲ﴾: بُعْدٍ عَنِ الصَّوابِ.\n\n﴿وَسُعُرٍ﴾: جُنُونٍ."],[25,25,"﴿أَءُلۡقِيَ﴾: أأُنْزِلَ.\n\n﴿ٱلذِّكۡرُ﴾: الوَحْيُ والقُرآنُ.\n\n﴿أَشِرࣱ﴾: صاحِبُ بَطَرٍ وتَكَبُّرٍ."],[27,27,"﴿مُرۡسِلُواْ﴾: مُخْرِجُو.\n\n﴿فَٱرۡتَقِبۡهُمۡ﴾: اخْتِبارًا.\n\n﴿فَٱرۡتَقِبۡهُمۡ﴾: فانْتَظِرْ ما يَحُلُّ عَلَيهِم مِنَ العَذابِ.\n\n﴿وَٱصۡطَبِر﴾: واصْبِرْ عَلى الأَذى الَّذِي يُصِيبُكَ مِنَ المدْعُوِّينَ."],[28,28,"﴿وَنَبِّئۡهُمۡ﴾: وأَخْبِرْهُم.\n\n﴿قِسۡمَةُۢ﴾: مَقْسُومٌ.\n\n﴿بَيۡنَهُمۡ﴾: بَيْنَ ثَمُودَ والنّاقَةِ.\n\n﴿كُلُّ شِرۡبࣲ﴾: كُلُّ نَصِيبٍ مِن الشَّرابِ.\n\n﴿مُّحۡتَضَرࣱ﴾: يَحْضُرُهُ صاحِبُهُ ويَسْتَحِقُّهُ."],[29,29,"﴿فَتَعَاطَىٰ﴾: فَتَناوَلَ النّاقَةَ بِيَدِهِ لِيَعْقِرَها.\n\n﴿فَعَقَرَ﴾: فَقَتَلَ."],[31,31,"﴿كَهَشِيمِ﴾: كالشَّجَرِ اليابِسِ الَّذِي يَسْقُطُ ويَتَناثَرُ.\n\n﴿ٱلۡمُحۡتَظِرِ﴾: الَّذِي يُرِيدُ أن يَعْمَلَ سِياجًا لِحِفْظِ المواشِي فَيَحْتَطِبَ لِذَلِكَ."],[34,34,"﴿حَاصِبًا﴾: رِيحًا شَدِيدَةً تَرْمِيهِم بِحِجارَةٍ.\n\n﴿بِسَحَرࣲ﴾: في آخِرِ الليلِ."],[35,35,"﴿نَجۡزِي﴾: نُثِيبُ.\n\n﴿مَن شَكَرَ﴾: مَن آمَنَ بِاللهِ ووَحّدَهُ."],[36,36,"﴿وَلَقَدۡ أَنذَرَهُم﴾: خَوَّفَهُم.\n\n﴿بَطۡشَتَنَا﴾: بَأْسَنا وعَذابَنا.\n\n﴿فَتَمَارَوۡاْ﴾: فَشَكُّوا.\n\n﴿بِٱلنُّذُرِ﴾: بالإنْذارِ."],[38,38,"﴿صَبَّحَهُم بُكۡرَةً﴾: جاءَهُم وقْتَ الصَّباحِ.\n\n﴿مُّسۡتَقِرࣱّ﴾: نازلٌ بِهم."],[41,41,"﴿ءَالَ فِرۡعَوۡنَ﴾: أتْباعَ فِرْعَونَ.\n\n﴿ٱلنُّذُرُ﴾: الإنْذارُ تِلْو الإنْذارِ مِن مُوسى عَلَيهِ السَّلامُ بالعُقُوبةِ عَلى كُفْرِهِم."],[42,42,"﴿بِـَٔايَـٰتِنَا﴾: بِأَدلَّتِنا الدّالّةِ عَلى وحْدانِيَّتِنا ونُبُوَّةِ أنْبِيائِنا.\n\n﴿فَأَخَذۡنَـٰهُمۡ﴾: فَعاقَبْناهُم.\n\n﴿عَزِيزࣲ﴾: لا يُغالَبُ.\n\n﴿مُّقۡتَدِرٍ﴾: قادِرٍ عَلى هَلاكِكُم."],[43,43,"﴿أَكُفَّارُكُمۡ﴾: يا مَعْشَرَ العَرَبِ.\n\n﴿بَرَآءَةࣱ﴾: مِنَ العذابِ ألّا يُصِيبَكُم ما أصابَهُم.\n\n﴿ٱلزُّبُرِ﴾: الكُتُبِ المنَزَّلةِ عَلى الأنبياءِ المُتقَدِّمِينَ."],[44,44,"﴿جَمِيعࣱ﴾: نَحْنَ يَدٌ واحِدَةٌ عَلى مَن خالَفَنا.\n\n﴿مُّنتَصِرࣱ﴾: نَغْلِبُ غَيرَنا."],[45,45,"﴿ٱلۡجَمۡعُ﴾: جَمْعُ كُفّارِ مَكَّةَ أمامَ المُؤمِنِينَ."],[46,46,"﴿أَدۡهَىٰ﴾: أفْظَعُ وأَعْظَمُ.\n\n﴿وَأَمَرُّ﴾: أشدُّ مَرارَةً مِنَ القَتْلِ والأَسْرِ."],[47,47,"﴿ضَلَـٰلࣲ﴾: تِيهٍ عَنِ الحقِّ.\n\n﴿وَسُعُرࣲ﴾: جُنُونٍ أو نارٍ تَسْتَعِرُ عَلَيهِم."],[48,48,"﴿يُسۡحَبُونَ﴾: يُجَرُّونَ.\n\n﴿مَسَّ سَقَرَ﴾: شِدَّةَ عَذابِ جَهَنَّمَ."],[49,49,"﴿بِقَدَرࣲ﴾: بمِقَدارٍ قَدَّرْناهُ، وسَبَق عِلْمُنا بِهِ، وكِتابَتُنا لَهُ في اللَّوحِ المَحْفُوظِ."],[50,50,"﴿وَ ٰ⁠حِدَةࣱ﴾: قَوْلَةٌ واحِدَةٌ، وهي «كُنْ».\n\n﴿كَلَمۡحِۭ بِٱلۡبَصَرِ﴾: فَيُوجَدُ في أقْصَرِ وقْتٍ."],[51,51,"﴿أَشۡيَاعَكُمۡ﴾: أشْباهَكُم في الكُفْرِ مِنَ الأُمَمِ السّابِقَةِ.\n\n﴿مُّدَّكِرࣲ﴾: مُتَّعِظٍ."],[52,52,"﴿ٱلزُّبُرِ﴾: الكُتَبِ الَّتِي كَتَبَتْها الحَفَظَةُ."],[53,53,"﴿مُّسۡتَطَرٌ﴾: مُسَطَّرٌ في صَحائِفِهم."],[55,55,"﴿مَقۡعَدِ صِدۡقٍ﴾: مَجْلِسِ حَقٍّ.\n\n﴿مَلِيكࣲ﴾: اللهِ الملِكِ العَظِيمِ.\n\n﴿مُّقۡتَدِرِۭ﴾: عَظِيمِ القُدْرَةِ."]]);
QTF("gharib",55,[[4,4,"﴿ٱلۡبَيَانَ﴾: النُّطْقَ والتَّعْبِيرَ عَمّا في الضَّمائِرِ."],[5,5,"﴿بِحُسۡبَانࣲ﴾: يَجْرِيانِ بِحِسابٍ مُتْقَنٍ."],[7,7,"﴿ٱلۡمِيزَانَ﴾: العَدْلَ الَّذِي شَرَعَهُ لِعِبادِهِ."],[8,8,"﴿أَلَّا تَطۡغَوۡاْ﴾: لِئَلّا تَعْتَدُوا."],[9,9,"﴿بِٱلۡقِسۡطِ﴾: بالعَدْلِ.\n\n﴿وَلَا تُخۡسِرُواْ﴾: ولا تُنْقِصُوا."],[10,10,"﴿وَضَعَهَا﴾: مَهَّدَها.\n\n﴿لِلۡأَنَامِ﴾: لِلْخَلْقِ."],[11,11,"﴿ٱلۡأَكۡمَامِ﴾: جَمْعُ كِمٍّ وهو وِعاءُ الثَّمرَةِ."],[12,12,"﴿ذُو ٱلۡعَصۡفِ﴾: ذُو القِشْرِ.\n\n﴿وَٱلرَّيۡحَانُ﴾: كُلُّ نَبْتٍ طَيِّبِ الرّائِحةِ."],[13,13,"﴿ءَالَآءِ﴾: نِعَمِ."],[14,14,"﴿ٱلۡإِنسَـٰنَ﴾: أي أباه، وهو آدَمُ.\n\n﴿مِن صَلۡصَـٰلࣲ﴾: مِن طِينٍ يابِسٍ.\n\n﴿كَٱلۡفَخَّارِ﴾: الطينِ الَّذِي طُبِخَ بالنّارِ."],[15,15,"﴿ٱلۡجَآنَّ﴾: إبْلِيسَ.\n\n﴿مَّارِجࣲ﴾: لَهَبِ الَّنارِ المُخْتَلِطِ بَعْضُهُ بِبَعْضٍ."],[17,17,"﴿ٱلۡمَشۡرِقَيۡنِ﴾: مَشْرِقَي الشَّمْسِ في الشِّتاءِ والصَّيفِ.\n\n﴿ٱلۡمَغۡرِبَيۡنِ﴾: مَغْرِبَيِ الشَّمسِ في الشِّتاءِ والصَّيفِ."],[19,19,"﴿مَرَجَ﴾: خَلَطَ.\n\n﴿ٱلۡبَحۡرَيۡنِ﴾: الماءَ العَذْبَ والمِلْحَ.\n\n﴿يَلۡتَقِيَانِ﴾: في مَرْأى العَينِ."],[20,20,"﴿بَرۡزَخࣱ﴾: حاجِزٌ.\n\n﴿لَّا يَبۡغِيَانِ﴾: لا يطْغى أحَدُهُما عَلى الآخَرِ."],[22,22,"﴿ٱللُّؤۡلُؤُ﴾: الدُّرُّ.\n\n﴿وَٱلۡمَرۡجَانُ﴾: صِغارُ اللُّؤلُؤ."],[24,24,"﴿ٱلۡجَوَارِ﴾: السُّفُنُ الضَّخْمَةُ الَّتِي تَجْرِي في البَحْرِ.\n\n﴿ٱلۡمُنشَـَٔاتُ﴾: المَرْفُوعاتُ الشِّراعِ.\n\n﴿كَٱلۡأَعۡلَـٰمِ﴾: كالجِبالِ."],[26,26,"﴿عَلَيۡهَا﴾: عَلى وجْهِ الأرْضِ.\n\n﴿فَانࣲ﴾: هالِكٌ."],[27,27,"﴿ٱلۡجَلَـٰلِ﴾: ذُو العَظَمَةِ والكِبْرِياءِ.\n\n﴿وَٱلۡإِكۡرَامِ﴾: والفَضْلِ والجُودِ."],[31,31,"﴿سَنَفۡرُغُ﴾: سنفرغ لحسابكم ومجازاتكم بأعْمالِكُم.\n\n﴿أَيُّهَ ٱلثَّقَلَانِ﴾: أيُّها الإنْسُ والجِنُّ."],[33,33,"﴿تَنفُذُواْ﴾: تَخْرُجُوا.\n\n﴿أَقۡطَارِ﴾: أطْرافِ.\n\n﴿بِسُلۡطَـٰنࣲ﴾: بِقُوَّةٍ وحُجَّةٍ."],[35,35,"﴿شُوَاظࣱ﴾: لَهَبٌ.\n\n﴿وَنُحَاسࣱ﴾: مُذابٌ يُصَبُّ على رُؤُوسِكُم.\n\n﴿فَلَا تَنتَصِرَانِ﴾: فَلا يَنْصُرُ بَعْضُكُم بَعْضًا."],[37,37,"﴿ٱنشَقَّتِ﴾: تَفَطَّرَتْ يَوْمَ القِيامَةِ.\n\n﴿وَرۡدَةࣰ﴾: حَمْراءَ كَلَونِ الوَرْدِ.\n\n﴿كَٱلدِّهَانِ﴾: كالزَّيتِ الَمغْلِيِّ والرَّصاصِ المُذابِ."],[41,41,"﴿بِسِيمَـٰهُمۡ﴾: بعَلاماتِهِم.\n\n﴿بِٱلنَّوَ ٰ⁠صِي﴾: بمُقَدِّمَةِ رُؤُوسِهِم."],[44,44,"﴿حَمِيمٍ﴾: الماءِ الشَّدِيدِ الحَرارَةِ.\n\n﴿ءَانࣲ﴾: بالغٍ مُنْتَهاهُ في الحرارةِ."],[46,46,"﴿مَقَامَ رَبِّهِۦ﴾: وقْتَ قِيامِهِ بين يَدَي رَبِّهِ."],[48,48,"﴿أَفۡنَانࣲ﴾: أغْصانٍ نَضِرَةٍ مِنَ الفَواكِهِ والثِّمارِ."],[52,52,"﴿زَوۡجَانِ﴾: صِنْفانِ."],[54,54,"﴿بَطَآئِنُهَا﴾: جَمْعُ بِطانَةٍ وهي: ما يَلِي الأرْضَ مِنَ الفِراشِ.\n\n﴿إِسۡتَبۡرَقࣲ﴾: غَلِيظِ الحرِيرِ الخالِصِ.\n\n﴿وَجَنَى﴾: وثَمَرُ.\n\n﴿دَانࣲ﴾: قَرِيبٌ إليهِم."],[56,56,"﴿فِيهِنَّ﴾: في هَذِه الفُرُشِ.\n\n﴿قَـٰصِرَ ٰ⁠تُ ٱلطَّرۡفِ﴾: لا يَصْرِفْنَ أبْصارَهُنَّ إلى غَيرِ أزْواجِهِنَّ.\n\n﴿لَمۡ يَطۡمِثۡهُنَّ﴾: لم يَطَأْهُنَّ."],[58,58,"﴿ٱلۡيَاقُوتُ﴾: حَجَرٌ مِنَ الأحْجارِ الكَرِيمَةِ، ذُو ألْوانٍ.\n\n﴿وَٱلۡمَرۡجَانُ﴾: صِغارُ اللُّؤلُؤِ."],[62,62,"﴿وَمِن دُونِهِمَا﴾: ومِن دُونِ الجنَّتَينِ السّابِقَتَينِ في الدَّرَجِ."],[64,64,"﴿مُدۡهَآمَّتَانِ﴾: خَضْراوانِ، وقَدِ اشْتَدَّتْ خُضْرَتُهُما حَتّى مالَتْ إلى السَّوادِ."],[66,66,"﴿نَضَّاخَتَانِ﴾: فَوّارتانِ بالماءِ لا تَنْقَطِعانِ."],[70,70,"﴿فِيهِنَّ﴾: في هَذِه الجنّاتِ الأرْبَعِ.\n\n﴿خَيۡرَ ٰ⁠تٌ﴾: زَوْجاتٌ طيِّباتُ الأخْلاقِ.\n\n﴿حِسَانࣱ﴾: حِسانُ الوُجُوهِ."],[72,72,"﴿حُورࣱ﴾: نِساءٌ ذَواتُ حَوَرٍ، وهو شِدَّةُ بَياضِ العَينِ وشِدَّةُ سَوادِها.\n\n﴿مَّقۡصُورَ ٰ⁠تࣱ﴾: مَسْتُوراتٌ مَصُوناتٌ.\n\n﴿ٱلۡخِيَامِ﴾: البُيوتِ."],[76,76,"﴿رَفۡرَفٍ﴾: وسائِدَ ذَواتِ أغْطِيَةٍ.\n\n﴿وَعَبۡقَرِيٍّ﴾: وفُرُشٍ بَدِيعَةٍ."],[78,78,"﴿تَبَـٰرَكَ﴾: كَثُرَ خَيرُهُ.\n\n﴿ٱلۡجَلَـٰلِ﴾: العَظَمَةِ والمَجْدِ.\n\n﴿وَٱلۡإِكۡرَامِ﴾: لِأَوْلِيائِهِ."]]);
QTF("gharib",56,[[1,1,"﴿ٱلۡوَاقِعَةُ﴾: القِيامَةُ."],[2,2,"﴿كَاذِبَةٌ﴾: لا يَكُونُ عِنْدَ وُقُوعِها تَكْذِيبٌ."],[3,3,"﴿خَافِضَةࣱ رَّافِعَةٌ﴾: هي خافِضَةٌ يَحْصُلُ عِنْدَها خَفْضُ أقْوامٍ كانُوا مُرْتَفِعِينَ ورَفْعُ أقْوامٍ كانُوا مُنْخَفِضِينَ، وخافِضَةُ جِهاتٍ كانَتْ مُرْتَفِعَةً كالجِبالِ والصَّوامِعِ، رافِعَةٌ ما كانَ مُنْخَفِضًا بِسَبَبِ ما يَحْدُثُ في الكَونِ."],[4,4,"﴿رُجَّتِ﴾: اضْطَرَبَتْ، بِسَبَبِ الزَّلازِلِ والخَسْفِ ونَحْوِ ذَلِكَ."],[5,5,"﴿وَبُسَّتِ﴾: فُتِّتَتِ الجبالُ ونُسِفَتْ."],[6,6,"﴿هَبَآءࣰ﴾: ما يَلُوحُ في خُيُوطِ شُعاعِ الشَّمسِ مِن دَقِيقِ الغُبارِ.\n\n﴿مُّنۢبَثࣰّا﴾: مُتَفَرِّقًا."],[7,7,"﴿أَزۡوَ ٰ⁠جࣰا﴾: أصْنافًا."],[8,8,"﴿أَصۡحَـٰبُ ٱلۡمَيۡمَنَةِ﴾: هُمُ الَّذِينَ يُجْعَلُونَ في الجِهَةِ اليُمْنى فِي الجَنَّةِ أوْ فِي الَمحْشَرِ."],[9,9,"﴿أَصۡحَـٰبُ ٱلۡمَشۡـَٔمَةِ﴾: أصْحابُ الشَّقاوَةِ الَّذِينَ يُؤْخَذُ بِهِم ذاتَ الشِّمال إلى النّارِ."],[10,10,"﴿وَٱلسَّـٰبِقُونَ﴾: إلى الخَيْراتِ.\n\n﴿ٱلسَّـٰبِقُونَ﴾: إلى مُنْتَهى الفَضْلِ والرِّفْعَةِ."],[13,13,"﴿ثُلَّةࣱ﴾: جَماعةٌ."],[15,15,"﴿سُرُرࣲ﴾: جَمْعُ سَرِيرٍ، وهو مَجِلِسُ العُظَماءِ والمُلُوكِ أيْضًا.\n\n﴿مَّوۡضُونَةࣲ﴾: مَسْبُوكٍ بَعْضُها بِبَعْضٍ."],[16,16,"﴿مُتَقَـٰبِلِينَ﴾: يَجْلِسُ بَعْضُهُم مُقابِلَ بَعْضٍ، وذَلِكَ مِن تَمامِ النَّعِيمِ لمِا فِيهِ مِنَ الأُنْسِ بِمُشاهَدَةِ الأَصْحابِ والحَدِيثِ مَعَهُم."],[17,17,"﴿يَطُوفُ﴾: يَدُورُ عَلى نَحْوٍ دائِمٍ.\n\n﴿مُّخَلَّدُونَ﴾: أي دائِمُونَ عَلى الطَّوافِ عَلَيهِم ومُناوَلَتِهِم."],[18,18,"﴿بِأَكۡوَابࣲ﴾: جَمْعُ كُوبٍ، وهو إناءُ الخمْرِ.\n\n﴿وَأَبَارِيقَ﴾: جَمْعِ إبْريقٍ، وهو إناءٌ تُحْمَلُ فِيهِ الخمْرُ فتُصَبُّ في الأكْوابِ.\n\n﴿وَكَأۡسࣲ﴾: هو إناءٌ للخَمْرِ كاْلكُوبِ.\n\n﴿مَّعِينࣲ﴾: هو الجارِي، والمُرادُ بِهِ الخَمْرُ الَّتِي لِكَثْرَتِها تَجْرِي ولَيسَتْ عَزِيَزةً كَما هِي في الدُّنيا."],[19,19,"﴿لَّا يُصَدَّعُونَ﴾: لا يُصِيبُهُم صُداعُ الرَّأْسِ.\n\n﴿وَلَا يُنزِفُونَ﴾: أي لا يَعْتَرِيهِم اخْتِلاطُ العَقْلِ."],[20,20,"﴿يَتَخَيَّرُونَ﴾: يَخْتارُونَهُ ويَشْتَهُونَهُ."],[22,22,"﴿وَحُورٌ﴾: نِساءٌ ذَواتُ حَوَرٍ أي: نِساءٌ شَدِيداتُ بياضِ العَينِ وسَوادِها.\n\n﴿عِينࣱ﴾: واسِعاتُ العُيُونِ."],[23,23,"﴿كَأَمۡثَـٰلِ﴾: كأشْباهِ.\n\n﴿ٱللُّؤۡلُوِٕ﴾: الدُّرِّ.\n\n﴿ٱلۡمَكۡنُونِ﴾: المَخْزُونِ المُخَبَّأِ لِنَفاسَتِهِ."],[25,25,"﴿لَغۡوࣰا﴾: هُوَ الكَلامُ الَّذِي لا يُعْتَدُّ بِهِ.\n\n﴿تَأۡثِيمًا﴾: هُوَ اللَّومُ والإنْكارُ."],[26,26,"﴿سَلَـٰمࣰا سَلَـٰمࣰا﴾: سَلَّمْنا سَلامًا إثْرَ سَلامٍ."],[28,28,"﴿سِدۡرࣲ﴾: شَجَرٍ مِن شَجَرِ العِضاه، ذِي ورَقٍ عَرِيضٍ مُدَوَّرٍ.\n\n﴿مَّخۡضُودࣲ﴾: أُزِيلَ شَوْكُهُ."],[29,29,"﴿وَطَلۡحࣲ﴾: شَجَرٍ مِن شَجَرِ العِضاه، واحدُه طَلْحةٌ، كَثِيرَةُ الظِّلِّ مِن التِفافِ أغْصانِها.\n\n﴿مَّنضُودࣲ﴾: مُتَراصٍّ مُتَراكِبٍ بالأغْصانِ."],[30,30,"﴿وَظِلࣲّ مَّمۡدُودࣲ﴾: لا يَتَقَلَّصُ كَظِلِّ الدُّنيا."],[31,31,"﴿وَمَآءࣲ مَّسۡكُوبࣲ﴾: مَصبُوبٍ."],[33,33,"﴿لَّا مَقۡطُوعَةࣲ وَلَا مَمۡنُوعَةࣲ﴾: دائِمَةٍ مَبْذُولَةٍ لَهُم."],[34,34,"﴿وَفُرُشࣲ﴾: جَمْعُ فِراشٍ، وهو ما يُفْرَشُ.\n\n﴿مَّرۡفُوعَةٍ﴾: عَلى الأَسِرَّةِ."],[42,42,"﴿سَمُومࣲ﴾: هي الرِّيحُ الشَّدِيدَةُ الحَرارةِ.\n\n﴿وَحَمِيمࣲ﴾: هو الماءُ الشَّديدُ الحَرارةِ."],[43,43,"﴿يَحۡمُومࣲ﴾: الدُّخانِ الأَسْوَدِ."],[45,45,"﴿مُتۡرَفِينَ﴾: ذوي نِعْمَةٍ واسِعةٍ."],[46,46,"﴿يُصِرُّونَ﴾: يَثْبُتُونَ عَلَيهِ.\n\n﴿ٱلۡحِنثِ﴾: الذَّنبِ والمَعْصِيَةِ.\n\n﴿ٱلۡعَظِيمِ﴾: القَوِيِّ في نَوْعِهِ، وهو الشِّركُ."],[50,50,"﴿لَمَجۡمُوعُونَ﴾: يُبْعَثُونَ ويُحْشَرُونَ جَمِيعًا."],[52,52,"﴿شَجَرࣲ مِّن زَقُّومࣲ﴾: شَجَرَةٍ كَرِيهَةِ الرّائِحَةِ يُنبتُها اللهُ في جَهَنَّمَ."],[54,54,"﴿ٱلۡحَمِيمِ﴾: هُوَ الماءُ الشَّدِيدُ الغَلَيانِ."],[55,55,"﴿ٱلۡهِيمِ﴾: جَمْعُ أهْيَمَ، وهُوَ البَعِيرُ الَّذِي أصابَهُ الهُيامُ، وهو داءُ يُصُيِبُ الإبِلَ فلا تَزالُ تَشْرَبُ ولا تَرْوى."],[56,56,"﴿نُزُلُهُمۡ﴾: النُّزُلُ هو ما يُقَدَّمُ للضَّيفِ مِن طَعامٍ."],[58,58,"﴿تُمۡنُونَ﴾: ما يَكُونُ مِنكُم مِن الَمنِيِّ."],[60,60,"﴿قَدَّرۡنَا بَيۡنَكُمُ ٱلۡمَوۡتَ﴾: قَضَيْنا عَلَيكُم بِالمَوْتِ أوْ سَوَّينا بَينَكُم في الموتِ.\n\n﴿بِمَسۡبُوقِينَ﴾: بِمَغْلُوبِينَ."],[61,61,"﴿نُّبَدِّلَ أَمۡثَـٰلَكُمۡ﴾: نُغَيِّرَ خَلْقَكُم.\n\n﴿فِي مَا لَا تَعۡلَمُونَ﴾: مِنَ الصِّفاتِ والأحْوال."],[62,62,"﴿ٱلنَّشۡأَةَ ٱلۡأُولَىٰ﴾: خَلْقَ اللهِ إياكُم ولَمْ تكُونُوا شَيئًا مَذْكُورًا."],[64,64,"﴿تَزۡرَعُونَهُۥٓ﴾: تُنْبِتُونَهُ."],[65,65,"﴿حُطَـٰمࣰا﴾: يابِسًا هَشِيمًا لا يُنْتَفعُ بِهِ.\n\n﴿فَظَلۡتُمۡ﴾: فصِرْتُمْ.\n\n﴿تَفَكَّهُونَ﴾: تَعْجَبُونَ مِن يُبْسِهِ بَعْدَ خُضْرَتِهِ."],[66,66,"﴿إِنَّا لَمُغۡرَمُونَ﴾: لَمُلْزَمُونَ غَرامَةَ ما أنْفَقْنا."],[67,67,"﴿مَحۡرُومُونَ﴾: من الرِّزقِ."],[69,69,"﴿ٱلۡمُزۡنِ﴾: السَّحابِ."],[70,70,"﴿أُجَاجࣰا﴾: شَدِيدَ المُلُوحَةِ."],[71,71,"﴿تُورُونَ﴾: تُوقِدُونَ."],[72,72,"﴿شَجَرَتَهَآ﴾: الَّتِي تُقْدَحُ مِنها النّارُ.\n\n﴿ٱلۡمُنشِـُٔونَ﴾: الخالِقُونَ."],[73,73,"﴿تَذۡكِرَةࣰ﴾: تَذْكِيرًا لَكُم بِنارِ جَهَنَّمَ.\n\n﴿وَمَتَـٰعࣰا﴾: ومَنفَعَةً.\n\n﴿لِّلۡمُقۡوِينَ﴾: لِلْمُسافِريِنَ."],[74,74,"﴿فَسَبِّحۡ﴾: فنَزِّهْ."],[75,75,"﴿بِمَوَ ٰ⁠قِعِ ٱلنُّجُومِ﴾: بِمَساقِطِ النُّجُومِ في مَغارِبِها في السَّماءِ."],[78,78,"﴿مَّكۡنُونࣲ﴾: مَصُونٍ مَسْتُورٍ، وهو الكِتابُ الَّذِي بأيدِي الملائِكةِ."],[79,79,"﴿ٱلۡمُطَهَّرُونَ﴾: هُمُ المَلائِكةُ الَّذِينَ طَهَّرَهُم اللهُ مِنَ الآفاتِ والذُّنُوبِ."],[81,81,"﴿ٱلۡحَدِيثِ﴾: القرآنِ.\n\n﴿مُّدۡهِنُونَ﴾: مُكَذِّبُونَ."],[82,82,"﴿رِزۡقَكُمۡ﴾: شُكْرَكُم لِنِعَمِ اللهِ عَلَيكُم."],[83,83,"﴿فَلَوۡلَآ﴾: فَهَلّا.\n\n﴿بَلَغَتِ﴾: أي النَّفْسُ.\n\n﴿ٱلۡحُلۡقُومَ﴾: الحَلْقَ."],[85,85,"﴿وَنَحۡنُ أَقۡرَبُ إِلَيۡهِ مِنكُمۡ﴾: بِمَلائِكَتِنا ولَكِنَّكُم لا تَرَونَهُم."],[86,86,"﴿فَلَوۡلَآ﴾: فَهَلّا.\n\n﴿غَيۡرَ مَدِينِينَ﴾: غَيرَ مُحاسَبِينَ ولا مَجْزِيِّينَ بِأَعْمالِكُم."],[87,87,"﴿تَرۡجِعُونَهَآ﴾: تَرُدُّونَ النَّفْسَ."],[89,89,"﴿فَرَوۡحࣱ﴾: فَلَهُ رَحْمَةٌ وفَرَحٌ عِنْدَ مَوتِهِ.\n\n﴿وَرَيۡحَانࣱ﴾: مُسْتَراحٌ."],[91,91,"﴿فَسَلَـٰمࣱ لَّكَ﴾: فسَلامةٌ لَكَ وأَمْنٌ."],[92,92,"﴿فَنُزُلࣱ﴾: فَضِيافَةٌ.\n\n﴿حَمِيمࣲ﴾: شَرابِ جَهَنَّمَ المَغْلِيِّ."],[94,94,"﴿وَتَصۡلِيَةُ﴾: وإدْخالٌ لِيُقاسِيَ الحرَّ."],[95,95,"﴿حَقُّ ٱلۡيَقِينِ﴾: اليَقِينُ حقًا."],[96,96,"﴿فَسَبِّحۡ﴾: فَنَزِّهْ."]]);
QTF("gharib",57,[[1,1,"﴿سَبَّحَ لِلَّهِ﴾: نَزَّهَهُ عِنِ السُّوءِ ومَجَّدَهُ.\n\n﴿ٱلۡعَزِيزُ﴾: الَّذِي لا يُغْلَبُ.\n\n﴿ٱلۡحَكِيمُ﴾: الَّذِي يَضَعُ الأَفْعالَ حِيثُ يَلِيقُ بِها."],[3,3,"﴿ٱلۡأَوَّلُ﴾: الَّذِي ليسَ قَبْلَهُ شَيءٌ.\n\n﴿ٱلۡـَٔاخِرُ﴾: الَّذِي لَيسَ بَعْدَه شَيءٌ.\n\n﴿ٱلظَّـٰهِرُ﴾: الَّذِي لَيسَ فَوْقَه شَيءٌ.\n\n﴿ٱلۡبَاطِنُ﴾: الَّذِي لَيسَ دُونَهُ شَيءٌ."],[4,4,"﴿ٱسۡتَوَىٰ﴾: عَلا وارْتَفَعَ.\n\n﴿ٱلۡعَرۡشِ﴾: سَرير المُلْكِ الَّذِي تَحْمِلُه الملائِكَةُ، واسْتَوىَ عَليهِ الرَّحمنُ، وهو أعْظَمُ المخلُوقاتِ، وهو سَقْفُ جَنَّةِ الفِرْدَوسِ.\n\n﴿يَلِجُ فِي ٱلۡأَرۡضِ﴾: يَدْخُلُ مِن حَبٍّ ومَطَرٍ وغَيرِ ذَلِكَ.\n\n﴿يَعۡرُجُ فِيهَا﴾: يَصْعَدُ مِنَ الملائِكةِ والأرْواحِ والأَدْعِيَةِ والأَعْمالِ.\n\n﴿مَعَكُمۡ﴾: بِعِلْمِهِ."],[6,6,"﴿يُولِجُ ٱلَّيۡلَ فِي ٱلنَّهَارِ﴾: يُدْخِلُ ما نَقَصَ مِن ساعاتِ الليل في النَّهارِ فَيَزِيدُ النَّهارَ.\n\n﴿وَيُولِجُ ٱلنَّهَارَ فِي ٱلَّيۡلِ﴾: ويُدْخِلُ ما نَقَصَ من ساعاتِ النَّهارِ في الليلِ فَيَزيدُ الليلَ.\n\n﴿بِذَاتِ ٱلصُّدُورِ﴾: بما فِي صُدُورِ خَلْقِهِ."],[7,7,"﴿جَعَلَكُم مُّسۡتَخۡلَفِينَ﴾: جَعَلَها في أيْدِيكُم، واسْتَخْلَفَكُم عَلَيها."],[8,8,"﴿مِيثَـٰقَكُمۡ﴾: عَهْدَكُم المؤَكَّدَ."],[9,9,"﴿ٱلظُّلُمَـٰتِ﴾: ظُلُماتِ الكُفْرِ.\n\n﴿ٱلنُّورِ﴾: نُور الإيمانِ.\n\n﴿لَرَءُوفࣱ﴾: لَرَحِيمٌ بِهِم أشَدَّ رَحْمةٍ."],[10,10,"﴿وَمَا لَكُمۡ أَلَّا تُنفِقُواْ﴾: أيُّ شَيءٍ يَمْنَعُكُم مِنَ الإنْفاقِ؟\n\n﴿مِيرَ ٰ⁠ثُ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ﴾: مُلْكُ السَّمَواتِ والأرْضِ، وسَيَنْتَقِلُ إلى مالِكِه الحقِيقِي.\n\n﴿ٱلۡفَتۡحِ﴾: فَتْحِ مَكَّةَ.\n\n﴿ٱلۡحُسۡنَىٰ﴾: الجنَّةَ."],[11,11,"﴿يُقۡرِضُ ٱللَّهَ﴾: يُنْفِقُ مُخْلِصًا عَمَلَهُ للهِ."],[12,12,"﴿يَسۡعَىٰ نُورُهُم﴾: يُضِيءُ لَهُم نُورُ عَمَلِهِم عَلى الصِّراطِ عَلى قَدْرِ أعْمالِهِم."],[13,13,"﴿ٱنظُرُونَا﴾: انْتَظِرُونا، وتَريَّثُوا في سَيرِكُم حتى نَلْحَقَ بِكُم.\n\n﴿نَقۡتَبِسۡ﴾: نَأْخُذْ.\n\n﴿قِيلَ﴾: القائِلُ: المؤمِنُونَ.\n\n﴿ٱرۡجِعُواْ وَرَآءَكُمۡ﴾: ارْجِعُوا إلى المكانِ الَّذِي قَبَسْتُم فِيهِ النُّورَ.\n\n﴿فَٱلۡتَمِسُواْ﴾: فاطْلُبُوا.\n\n﴿فَضُرِبَ بَيۡنَهُم﴾: فَوُضِعَ بَيْنَ المؤمِنينَ والمنافِقِينَ.\n\n﴿بِسُورࣲ﴾: بِجِدارٍ مُحِيطٍ مُرْتَفِعٍ.\n\n﴿بَاطِنُهُۥ﴾: داخِلُهُ.\n\n﴿وَظَـٰهِرُهُۥ﴾: خارِجُهُ.\n\n﴿مِن قِبَلِهِ﴾: في جِهَتِهِ المقابِلَةِ الَّتِي فِيها المنافِقُونَ."],[14,14,"﴿فَتَنتُمۡ أَنفُسَكُمۡ﴾: آثمْتُمُوها، وأَهْلَكْتُمُوها بالنِّفاقِ.\n\n﴿وَتَرَبَّصۡتُمۡ﴾: وانْتَظَرْتُم بالنَّبِي الموتَ وبِالمؤمِنِينَ الدَّوائِرَ.\n\n﴿وَٱرۡتَبۡتُمۡ﴾: شَكَكْتُم في التَّوحِيدِ ونُبُوَّةِ محمَّدٍ ﷺ.\n\n﴿وَغَرَّتۡكُمُ﴾: خَدَعَتْكُم.\n\n﴿ٱلۡأَمَانِيُّ﴾: ما تُمَنُّونَ بِهِ أنْفُسَكُم مِنَ الأباطِيلِ.\n\n﴿أَمۡرُ ٱللَّهِ﴾: الموتُ.\n\n﴿ٱلۡغَرُورُ﴾: الشَّيطانُ."],[15,15,"﴿فِدۡيَةࣱ﴾: عِوَضٌ تَتَخَلّصُونَ بِهِ مِنَ العذابِ.\n\n﴿مَأۡوَىٰكُمُ﴾: مَصِيرُكُم الَّذِي تَخْلُدُونَ فِيهِ.\n\n﴿وَبِئۡسَ ٱلۡمَصِيرُ﴾: وساءَ مَرْجِعُ مَن صارَ إلى النّارِ."],[16,16,"﴿أَلَمۡ يَأۡنِ﴾: ألَمْ يَأْتِ الوَقْتُ؟\n\n﴿تَخۡشَعَ﴾: تَرِقَّ وتَلِينَ.\n\n﴿ٱلۡأَمَدُ﴾: الزَّمانُ أو الغايَةُ، وبُعْدُ عَهْدِهِم بالأنبياءِ والصّالِحِينَ."],[17,17,"﴿ٱلۡأَرۡضَ﴾: الميْتَةَ الَّتِي لا تُنْبِتُ شَيئًا.\n\n﴿بَعۡدَ مَوۡتِهَا﴾: بَعْدَ يُبْسِها لاحْتِباسِ الماءِ عَنْها.\n\n﴿ٱلۡـَٔايَـٰتِ﴾: الدَّلائِلَ والحُجَجَ.\n\n﴿لَعَلَّكُمۡ تَعۡقِلُونَ﴾: رَجاءَ أن تَعْقِلُوا."],[18,18,"﴿ٱلۡمُصَّدِّقِينَ﴾: المتَصَدِّقِينَ مِن أمْوالِهِم.\n\n﴿وَأَقۡرَضُواْ ٱللَّهَ قَرۡضًا﴾: أنْفَقُوا في سَبِيلِ اللهِ نَفَقاتٍ طَيِّبةً بِها نُفُوسُهُم."],[19,19,"﴿ٱلصِّدِّيقُونَ﴾: الَّذِينَ كَمُلَ تَصْدِيقُهُم بِما جاءَتْ بِهِ الرُّسُلُ، اعتِقادًا وقَوْلًا وعَمَلًا.\n\n﴿وَٱلشُّهَدَآءُ﴾: هُمُ القَتْلى في سَبِيلِ اللهِ، والَّذِينَ يَشْهَدُونَ عَلى الأُمَمِ السّابِقَةِ."],[20,20,"﴿كَمَثَلِ غَيۡثٍ﴾: كَحالِ القَطْرِ.\n\n﴿ٱلۡكُفَّارَ﴾: الزُّرّاعَ، لِأنّ الزّارِعَ يَسْتُرُ ما يَزْرَعُهُ بِتُرابِ الأرْضِ.\n\n﴿يَهِيجُ﴾: يَيْبَسُ.\n\n﴿مُصۡفَرࣰّا﴾: تَحَوَّلَ لونُه إلى الصُّفْرةِ.\n\n﴿حُطَـٰمࣰا﴾: مُتَهَشِّمًا مُتَكَسِّرًا.\n\n﴿مَتَـٰعُ ٱلۡغُرُورِ﴾: تَمتُّعٌ يَنْخَدِعُ بِهِ أهْلُهُ."],[21,21,"﴿مَغۡفِرَةࣲ﴾: أسبابِ المغفِرَةِ مِنَ التَّوبَةِ والابْتِعادِ عَنِ المعاصِي."],[22,22,"﴿كِتَـٰبࣲ﴾: اللوحِ المحفُوظِ.\n\n﴿نَّبۡرَأَهَآ﴾: نَخْلُقَ الخَلِيقَةَ."],[23,23,"﴿تَأۡسَوۡاْ﴾: تَحْزَنُوا.\n\n﴿تَفۡرَحُواْ﴾: فَرَحَ بَطَرٍ وأَشَرٍ.\n\n﴿مُخۡتَالࣲ﴾: مُتَكَبِّرٍ."],[24,24,"﴿يَبۡخَلُونَ﴾: بأمْوالِهمِ.\n\n﴿يَتَوَلَّ﴾: يُعْرِضْ عَن طاعَةِ اللهِ.\n\n﴿ٱلۡغَنِيُّ﴾: عَنْ خَلْقِهِ.\n\n﴿ٱلۡحَمِيدُ﴾: المحمُودُ على أوصافِهِ الكامِلةِ."],[25,25,"﴿بِٱلۡبَيِّنَـٰتِ﴾: بالحُجَجِ الواضِحاتِ.\n\n﴿لِيَقُومَ ٱلنَّاسُ بِٱلۡقِسۡطِ﴾: لِيَتَعامَلَ النّاسُ بَيْنَهُم بالعَدلِ.\n\n﴿بَأۡسࣱ﴾: قُوَّةٌ.\n\n﴿عَزِيزࣱ﴾: لا يُغْلَبُ."],[27,27,"﴿قَفَّيۡنَا﴾: أتْبَعْنا.\n\n﴿رَأۡفَةࣰ﴾: لِينًا.\n\n﴿وَرَهۡبَانِيَّةً﴾: وابْتَدَعُوا رَهْبانِيَّةً بالغُلُوِّ في العِبادةِ.\n\n﴿مَا كَتَبۡنَـٰهَا﴾: ما فَرَضْناها.\n\n﴿إِلَّا ٱبۡتِغَآءَ رِضۡوَ ٰ⁠نِ ٱللَّهِ﴾: التَزَمُوا بالرَّهْبانِيَّةِ المُبْتدَعَةِ يَطْلُبُونَ بِذَلِكَ رِضا اللهِ.\n\n﴿فَمَا رَعَوۡهَا حَقَّ رِعَايَتِهَا﴾: فما قامُوا بِها حَقَّ القيامِ."],[28,28,"﴿كِفۡلَيۡنِ﴾: ضعْفَينِ.\n\n﴿تَمۡشُونَ بِهِۦ﴾: تَهْتَدُونَ بِهِ."],[29,29,"﴿لِّئَلَّا يَعۡلَمَ﴾: لِيعلَمَ.\n\n﴿ٱلۡفَضۡلِ ٱلۡعَظِيمِ﴾: الإحْسانِ والعَطاءِ الكَثِيرِ الواسِعِ."]]);
QTF("gharib",58,[[1,1,"﴿تُجَـٰدِلُكَ﴾: تُراجِعُكَ الكَلامَ في زَوْجِها وهي خَوْلَةُ بِنْتُ ثَعْلَبةَ وزَوْجُها أوسُ بنُ الصّامتِ.\n\n﴿تَحَاوُرَكُمَآ﴾: تَخاطُبَكُما ومُراجَعَتَكُما الكَلامَ."],[2,2,"﴿يُظَـٰهِرُونَ﴾: يَقُولُ الرَّجُلُ مِنهُم لِزوجَتِهِ: «أنْتِ عَليَّ كَظَهْرِ أُمِّي» أي في حُرْمَةِ النِّكاحِ."],[3,3,"﴿ۡ ثُمَّ يَعُودُونَ لِمَا قَالُواْ﴾: ثُمَّ يَرْجِعُونَ عَن قَوْلِهِم ويَعْزِمُونَ على وطْءِ نِسائِهِم.\n\n﴿يَتَمَآسَّا﴾: يَمَسَّ أحَدُهُما الآخَرَ، وهي كِنايةٌ عَنِ الِجماعِ."],[4,4,"﴿مِسۡكِينࣰا﴾: هو الَّذِي لا يَمْلِكُ ما يَكْفِيهِ ويَسُدُّ حاجَتَهُ."],[5,5,"﴿يُحَآدُّونَ﴾: يُشاقُّونَ ويُخالِفُونَ.\n\n﴿كُبِتُواْ﴾: خُذِلُوا وأُهِينُوا.\n\n﴿مُّهِينࣱ﴾: مُذِلٌّ."],[6,6,"﴿أَحۡصَىٰهُ ٱللَّهُ﴾: كَتَبهُ في اللَّوح المحْفُوظِ، وحَفِظَهُ عَلَيهم في صحائفِ أعْمالِهِم.\n\n﴿شَهِيدٌ﴾: شاهِدٌ يَعْلَمُهُ ويُحِيطُ بِهِ، فلا يعْزُبُ عنه شَيءٌ مِنهُ."],[7,7,"﴿نَّجۡوَىٰ﴾: مُناجاةٍ ومُسارَّةٍ وما يَكْتُمُهُ النّاسُ مِن أحادِيثِهِم.\n\n﴿هُوَ رَابِعُهُمۡ﴾: مُشاهِدُهُم بِعِلْمِهِ، وهو عَلى عَرْشِهِ.\n\n﴿وَلَآ أَدۡنَىٰ مِن ذَ ٰ⁠لِكَ﴾: ولا أقَلَّ مِن ذَلِكَ.\n\n﴿هُوَ مَعَهُمۡ﴾: بِعِلْمِه وهُوَ فَوْقَ العَرْشِ."],[8,8,"﴿ٱلنَّجۡوَىٰ﴾: حَدِيثِ السِّرِّ الَّذِي يُثيرُ الشَّكَ في نُفُوسِ المؤمِنينَ.\n\n﴿وَيَتَنَـٰجَوۡنَ﴾: يَتَحَدَّثُونَ سِرًّا.\n\n﴿حَيَّوۡكَ﴾: سَلَّمُوا عَلَيكَ.\n\n﴿حَسۡبُهُمۡ﴾: كافِيهِم مِنَ العَذابِ.\n\n﴿يَصۡلَوۡنَهَا﴾: يَدْخُلُونَها ويُقاسُونَ حَرَّها.\n\n﴿فَبِئۡسَ ٱلۡمَصِيرُ﴾: فَساءَ المنْقَلَبُ والمرْجِعُ."],[11,11,"﴿تَفَسَّحُواْ﴾: لِيُوسِّعْ بَعْضُكُم لِبَعْضٍ المَجالِسَ.\n\n﴿يَفۡسَحِ ٱللَّهُ لَكُمۡ﴾: يُوَسِّعِ اللهُ عَلَيكُم في الدُّنيا والآخِرةِ.\n\n﴿ٱنشُزُواْ﴾: قُومُوا من مجالِسِكُم.\n\n﴿يَرۡفَعِ﴾: يَرْفَعْ مَكانَةً.\n\n﴿دَرَجَـٰتࣲ﴾: مَراتِبَ رَفِيَعةً في دِينِهِم."],[12,12,"﴿نَـٰجَيۡتُمُ ٱلرَّسُولَ﴾: أرَدْتُم أن تُكَلِّمُوا رَسُولَ اللهِ ﷺ سرًّا.\n\n﴿وَأَطۡهَرُ﴾: وأَزْكى لِقُلُوبِكُم مِنَ المأثَمِ."],[13,13,"﴿ءَأَشۡفَقۡتُمۡ﴾: أخَشِيتُم الفَقْرَ عَقِبَ تَقْدِيمِ الصَّدَقةِ؟"],[14,14,"﴿تَوَلَّوۡاْ قَوۡمًا﴾: اتخذوهم أصدقاءَ يُحِبُّونهم وينصرونهم."],[16,16,"﴿جُنَّةࣰ﴾: وِقايِةً وسِتْرَةً.\n\n﴿مُّهِينࣱ﴾: مُذِلٌّ في النّارِ."],[17,17,"﴿لَّن تُغۡنِيَ﴾: لَن تَدْفَعَ."],[19,19,"﴿ٱسۡتَحۡوَذَ﴾: غَلَبَ واسْتَولى.\n\n﴿فَأَنسَىٰهُمۡ﴾: جَعَلَهُم يَتْرُكُونَ.\n\n﴿ذِكۡرَ ٱللَّهِ﴾: تَوْحِيدَ اللهِ، والعَمَلَ بِطاعَتِهِ."],[20,20,"﴿يُحَآدُّونَ﴾: يُخالِفُونَ.\n\n﴿ٱلۡأَذَلِّينَ﴾: مِن جُمْلةِ الأذِلّاءِ المغلوبِينَ المهانِينَ."],[21,21,"﴿كَتَبَ﴾: قَضى وكَتَبَ في اللَّوحِ المحْفُوظِ.\n\n﴿لَأَغۡلِبَنَّ﴾: لَتَكونَنَّ الغَلَبةُ بِالقُوَّةِ للهِ ولِرُسُلِهِ.\n\n﴿عَزِيزࣱ﴾: مانِعٌ حِزْبَهُ مِن أن يُذَلَّ."],[22,22,"﴿يُوَآدُّونَ﴾: يُحِبُّونَ ويُوالُونَ.\n\n﴿حَآدَّ﴾: عادى.\n\n﴿عَشِيرَتَهُمۡ﴾: أقْرِباءَهُم.\n\n﴿كَتَبَ﴾: ثَبَّتَ.\n\n﴿وَأَيَّدَهُم﴾: قَوّاهُم.\n\n﴿بِرُوحࣲ﴾: بِنَصْرٍ وتأْيِيدٍ.\n\n﴿حِزۡبَ ٱللَّهِ﴾: أولياؤُهُ.\n\n﴿ٱلۡمُفۡلِحُونَ﴾: الفائِزُونَ بِسَعادةِ الدُّنيا والآخِرَةِ."]]);
QTF("gharib",59,[[1,1,"﴿سَبَّحَ﴾: نَزَّهَ."],[2,2,"﴿ٱلَّذِينَ كَفَرُواْ﴾: هُم بنُو النَّضِيرِ مِنَ اليهُودِ.\n\n﴿دِيَـٰرِهِمۡ﴾: مَساكِنِهِم الَّتِي جاوَرُوا بِها المسْلِمِينَ حَوْلَ «المدينةِ».\n\n﴿لِأَوَّلِ ٱلۡحَشۡرِ﴾: عِنْدَ أوَّلِ جَمْعِهِم لِلْخُرُوجِ مِن جَزِيرةِ العَرَبِ.\n\n﴿مَّانِعَتُهُمۡ﴾: تَدْفَعُ عَنْهُم.\n\n﴿فَأَتَىٰهُمُ ٱللَّهُ﴾: فَجاءَهُم أمْرُ اللهِ.\n\n﴿مِنۡ حَيۡثُ لَمۡ يَحۡتَسِبُواْ﴾: مِن مَكانٍ لم يَظُنُّوهُ.\n\n﴿وَقَذَفَ﴾: وجَعَل.\n\n﴿ٱلرُّعۡبَ﴾: الخَوْفَ والفَزَعَ الشَّدِيدَ.\n\n﴿فَٱعۡتَبِرُواْ﴾: فاتَّعِظُوا.\n\n﴿يَـٰٓأُوْلِي ٱلۡأَبۡصَـٰرِ﴾: أصْحابَ البَصائِر السَّلِيمَةِ، والعُقُولِ الرّاجِحَةِ."],[3,3,"﴿ٱلۡجَلَآءَ﴾: الخُرُوجَ مِنَ الوطنِ بِنِيَّةِ عَدَمِ العَوْدِ."],[4,4,"﴿شَآقُّواْ﴾: خالفُوا."],[5,5,"﴿لِّينَةٍ﴾: نَخْلَةٍ ذاتِ ثَمَرٍ طَيِّبٍ.\n\n﴿أُصُولِهَا﴾: قَواعِدِها، والمرادُ: سُوقُ النَّخْلِ.\n\n﴿وَلِيُخۡزِيَ﴾: ولِيُهِينَ.\n\n﴿ٱلۡفَـٰسِقِينَ﴾: الكافِرِينَ، وهُمْ يَهُودُ بَنِي النَّضِيرِ."],[6,6,"﴿وَمَآ أَفَآءَ ٱللَّهُ عَلَىٰ رَسُولِهِۦ﴾: وما أعطاهُ اللهُ لِرَسُولِه مما يَظْفَرُ بِهِ الجيشُ مِن عَدُوِّهِم.\n\n﴿فَمَآ أَوۡجَفۡتُمۡ﴾: فَما أرْكَضْتُم للإغارَةِ، وأَوْجَفَهُ: حَمَلَهُ عَلى السَّيرِ السَّرِيعِ.\n\n﴿رِكَابࣲ﴾: الإبِلِ الَّتِي تُرْكَبُ."],[7,7,"﴿ٱلۡقُرَىٰ﴾: قُرىً فُتِحَتْ في عَهْدِ الرَّسُولِ ﷺ.\n\n﴿فَلِلَّهِ وَلِلرَّسُولِ﴾: أي يُصْرَفُ في مصالِحِ المسْلِمِينَ.\n\n﴿وَلِذِي ٱلۡقُرۡبَىٰ﴾: ولِذِي قَرابَةِ رَسُولِ اللهِ ﷺ، وهم بنُو هاشِم، وبنُو المطَّلِبِ.\n\n﴿وَٱلۡيَتَـٰمَىٰ﴾: الأَطْفالِ الَّذِين ماتَ آباؤُهم، وهم دُونَ سِنِّ البُلُوغِ.\n\n﴿وَٱلۡمَسَـٰكِينِ﴾: هم أهلُ الحاجةِ الَّذِينَ لا يَمْلِكُونَ ما يَسُدُّ حاجَتَهَم.\n\n﴿وَٱبۡنِ ٱلسَّبِيلِ﴾: هو الغريبُ المسافِر الَّذِي نَفِدَتْ نَفَقَتُهُ.\n\n﴿دُولَةَۢ بَيۡنَ ٱلۡأَغۡنِيَآءِ﴾: مُداوَلَةً يَتَداولُه الأَغْنِياءُ ويتعاقَبُونَ في التَّصَرُّفِ فِيهِ."],[9,9,"﴿تَبَوَّءُو﴾: اسْتَوطَنُوا وتَمَكَّنُوا.\n\n﴿ٱلدَّارَ﴾: المدِينَةَ، وهي دارُ الهِجْرَةِ.\n\n﴿حَاجَةࣰ﴾: حَسَدًا.\n\n﴿مِّمَّآ أُوتُواْ﴾: مِمّا أُعْطِي المهاجِرُونَ من فَيْءِ بَنِي النَّضِيرِ.\n\n﴿وَيُؤۡثِرُونَ عَلَىٰٓ أَنفُسِهِمۡ﴾: ويُقَدِّمُونَ غيرَهُم مِنَ المهاجِرِينَ وذَوِي الحاجةِ عَلى أنْفُسِهِم.\n\n﴿خَصَاصَةࣱ﴾: شِدَّةُ احْتِياجٍ.\n\n﴿وَمَن يُوقَ﴾: ومَن سَلَّمَهُ اللهُ فمُنِعَ.\n\n﴿شُحَّ نَفۡسِهِۦ﴾: بُخْلَها مَعَ حِرْصِها.\n\n﴿ٱلۡمُفۡلِحُونَ﴾: الفائِزُونَ بِمَطْلُوبِهِم."],[10,10,"﴿غِلࣰّا﴾: حَسَدًا وحِقْدًَا."],[11,11,"﴿ٱلَّذِينَ كَفَرُواْ مِنۡ أَهۡلِ ٱلۡكِتَـٰبِ﴾: هم بَنُو النَّضِيرِ.\n\n﴿وَلَا نُطِيعُ فِيكُمۡ﴾: أي في ضُرِّكُم."],[12,12,"﴿وَلَئِن نَّصَرُوهُمۡ﴾: ولئِنْ أرادُوا نُصْرَتَهُم.\n\n﴿ثُمَّ لَا يُنصَرُونَ﴾: أي لا يَغْلِبُونَ."],[13,13,"﴿رَهۡبَةࣰ﴾: خَوْفًا."],[14,14,"﴿مُّحَصَّنَةٍ﴾: ممنُوعَةٍ بأسْوارٍ أو خَنادِقَ مِمَّن يُرِيدُ أخْذَها.\n\n﴿جُدُرِۭ﴾: حِيطانٍ.\n\n﴿بَأۡسُهُم﴾: قوَّتُهُم.\n\n﴿شَتَّىٰ﴾: مُتَفَرِّقَةٌ"],[15,15,"﴿وَبَالَ أَمۡرِهِمۡ﴾: سُوءَ عاقِبَةِ كُفْرِهِم وعَداوَتِهِم لِلرَّسُولِ ﷺ."],[18,18,"﴿مَّا قَدَّمَتۡ﴾: أي: مِنَ الأعْمالِ.\n\n﴿لِغَدࣲ﴾: يومِ القِيامةِ."],[19,19,"﴿نَسُواْ ٱللَّهَ﴾: تَرَكُوا أداءَ حَقِّ اللهِ الَّذِي أوْجَبَهُ عَلَيهِم.\n\n﴿فَأَنسَىٰهُمۡ أَنفُسَهُمۡ﴾: مِمّا يُنَجِّيهِم مِنَ عَذابِ يَوْمِ القِيامةِ.\n\n﴿ٱلۡفَـٰسِقُونَ﴾: الخارجُونَ عَن طاعَةِ اللهِ ورَسُولِهِ."],[21,21,"﴿خَـٰشِعࣰا﴾: خاضِعًا مُتَذَلِّلًا.\n\n﴿مُّتَصَدِّعࣰا﴾: مُتَشَقِّقًا.\n\n﴿نَضۡرِبُهَا﴾: نُوَضِّحُها."],[22,22,"﴿عَـٰلِمُ ٱلۡغَيۡبِ وَٱلشَّهَـٰدَةِ﴾: يَعْلَمُ ما غابَ وما حَضَرَ."],[23,23,"﴿ٱلۡمَلِكُ﴾: المالِكُ لجمِيعِ الأشْياءِ، المتَصَرِّفُ فِيها بِلا مُمانَعَةٍ ولا مُدافَعَةٍ.\n\n﴿ٱلۡقُدُّوسُ﴾: المُنَزَّهُ عَن كُلِّ نَقْصٍ.\n\n﴿ٱلسَّلَـٰمُ﴾: الَّذِي سَلِمَ مِن كُلِّ عيبٍ.\n\n﴿ٱلۡمُؤۡمِنُ﴾: المصَدِّقُ رُسُلَه وأنبياءَه بِما أرْسَلَهُم بِهِ.\n\n﴿ٱلۡمُهَيۡمِنُ﴾: الرَّقِيبُ على خَلْقِهِ في أعمالِهِم.\n\n﴿ٱلۡعَزِيزُ﴾: الَّذِي لا يُغالَبُ.\n\n﴿ٱلۡجَبَّارُ﴾: الَّذِي قَهَرَ جَميعَ العِبادِ، وأَذْعَنُوا لَهُ.\n\n﴿ٱلۡمُتَكَبِّرُ﴾: الَّذِي له الكبرياءُ والعَظَمَةُ.\n\n﴿سُبۡحَـٰنَ ٱللَّهِ﴾: تنَزَّهَ اللهُ."],[24,24,"﴿ٱلۡخَـٰلِقُ﴾: المقَدِّرُ لِلْخَلْقِ.\n\n﴿ٱلۡبَارِئُ﴾: المنْشِئُ لِلْخَلْقِ.\n\n﴿ٱلۡمُصَوِّرُ﴾: صَوَّر خَلْقَهُ كَيفَ يَشاءُ.\n\n﴿ٱلۡعَزِيزُ﴾: الشَّدِيدُ الانتِقامِ مِن أعدائِهِ.\n\n﴿ٱلۡحَكِيمُ﴾: في تَدْبِيرِه أُمُورَ خَلْقِه."]]);
QTF("gharib",60,[[1,1,"﴿أَوۡلِيَآءَ﴾: خُلَصاءَ وأحبّاءَ.\n\n﴿تُلۡقُونَ إِلَيۡهِم بِٱلۡمَوَدَّةِ﴾: أي: فتُخْبِرُونَهُم بِأَخْبارِ الرَّسُولِ ﷺ وسَرائِر المسْلِمِينَ.\n\n﴿وَٱبۡتِغَآءَ﴾: طَلَبَ.\n\n﴿تُسِرُّونَ﴾: تَنْقُلُونَ إلَيهِمُ الأخْبارَ سِرًّا.\n\n﴿سَوَآءَ ٱلسَّبِيلِ﴾: طَرِيقَ الحقِّ والصَّوابِ."],[2,2,"﴿إِن يَثۡقَفُوكُمۡ﴾: إن يَظْفَرْ بِكُم هَؤلاءِ الَّذِينَ تُسِرُّونَ إليهِم بالمودّةِ.\n\n﴿وَيَبۡسُطُوٓاْ إِلَيۡكُمۡ﴾: ويَمُدُّوا إلَيكُم.\n\n﴿بِٱلسُّوٓءِ﴾: بالقَتْلِ، والسَّبْيِ، والشَّتْمِ."],[3,3,"﴿أَرۡحَامُكُمۡ﴾: قراباتُكُم.\n\n﴿يَفۡصِلُ بَيۡنَكُمۡ﴾: يَفْرُقُ اللهُ بَيْنَكُم، فيُدْخِلُ أهلَ طاعَتهِ الجَّنَةَ، وأهلَ مَعْصِيتِه النّارَ."],[4,4,"﴿أُسۡوَةٌ﴾: قُدْوَةٌ\n\n﴿كَفَرۡنَا بِكُمۡ﴾: أنْكَرْنا ما أنتُم عَلَيهِ مِنَ الكُفْرِ.\n\n﴿وَبَدَا﴾: وظَهَر.\n\n﴿تَوَكَّلۡنَا﴾: اعْتَمَدْنا.\n\n﴿أَنَبۡنَا﴾: رَجَعْنا بالتَّوبَةِ\n\n﴿ٱلۡمَصِيرُ﴾: المرْجِعُ يومَ القِيامَةِ."],[5,5,"﴿فِتۡنَةࣰ﴾: مَفْتُونِينَ بِتَسْلِيطِ الكُفّارِ عَلَينا.\n\n﴿ٱلۡعَزِيزُ﴾: الَّذِي لا يُغالَبُ.\n\n﴿ٱلۡحَكِيمُ﴾: في أفْعالِهِ وأَقْوالِهِ."],[6,6,"﴿أُسۡوَةٌ﴾: قُدْوَةٌ.\n\n﴿يَرۡجُواْ ٱللَّهَ﴾: يَطْمَعُ في الخيرِ مِنَ اللهِ.\n\n﴿وَمَن يَتَوَلَّ﴾: ومَن يُعْرضْ عَمّا أمَرهُ اللهُ بِهِ.\n\n﴿ٱلۡغَنِيُّ﴾: عَنْ عِبادِهِ.\n\n﴿ٱلۡحَمِيدُ﴾: في ذاتِه وصِفاتِه، المحْمُودُ عَلى كُلِّ حالٍ."],[7,7,"﴿عَسَى ٱللَّهُ﴾: وعَدَ اللهُ."],[8,8,"﴿تَبَرُّوهُمۡ﴾: تُحْسِنُوا مُعامَلَتَهُم.\n\n﴿وَتُقۡسِطُوٓاْ إِلَيۡهِمۡ﴾: وتَعْدِلُوا فِيهِم."],[9,9,"﴿فِي ٱلدِّينِ﴾: بِسَببِ الدِّينِ.\n\n﴿وَظَـٰهَرُواْ﴾: وعاوَنُوا الكُفّارَ.\n\n﴿أَن تَوَلَّوۡهُمۡ﴾: بالنُّصْرَةِ والمحبَّةِ.\n\n﴿وَمَن يَتَوَلَّهُمۡ﴾: ومَنَ يَتَّخِذْهُم أنْصارًا عَلى المؤمِنِينَ."],[10,10,"﴿مُهَـٰجِرَ ٰ⁠تࣲ﴾: مِن دارِ الكُفْرِ إلى دارِ الإسْلامِ.\n\n﴿فَٱمۡتَحِنُوهُنَّ﴾: فاخْتَبرُوا إيمانَهُنَّ.\n\n﴿وَءَاتُوهُم﴾: وأعْطُوا أزواجَ اللاتِي أسْلَمْنَ.\n\n﴿مَّآ أَنفَقُواْ﴾: مِثْلَ ما أعْطَوهُنَّ مِنَ المهُورِ.\n\n﴿أُجُورَهُنَّ﴾: مُهُورَهُنَّ.\n\n﴿بِعِصَمِ﴾: بِنِكاحِ، وأصْلُه جَمْعُ عِصْمَةٍ وهي: ما اعتُصِمَ بِهِ من العَقْدِ والسَّبَبِ.\n\n﴿ٱلۡكَوَافِرِ﴾: الزَّوجاتِ الكافِراتِ."],[11,11,"﴿فَاتَكُمۡ﴾: فَرَرْنَ ولَحِقْنَ.\n\n﴿فَعَاقَبۡتُمۡ﴾: كانَتِ العُقْبى لَكُم، وهي الغِنيمَةُ."],[12,12,"﴿يُبَايِعۡنَكَ﴾: يُعاهِدْنَكَ.\n\n﴿أَن لَّا يُشۡرِكۡنَ بِٱللَّهِ شَيۡـࣰٔا﴾: ألّا يَجْعَلْنَ مَعَ اللهِ شَرِيكًا في عِبادَتِهِ.\n\n﴿وَلَا يَأۡتِينَ بِبُهۡتَـٰنࣲ يَفۡتَرِينَهُۥ﴾: ولا يأتِينَ بِكَذِبٍ في مَولُودٍ مِن غَيرِ أزْواجِهِنَّ فيُلْحِقْنَهُ بِهِم.\n\n﴿فَبَايِعۡهُنَّ﴾: فعاهِدْهُنَّ."],[13,13,"﴿لَا تَتَوَلَّوۡاْ قَوۡمًا﴾: لا تَتَّخِذُوهُم أخِلّاءَ.\n\n﴿مِنَ ٱلۡـَٔاخِرَةِ﴾: مِن ثَوابِ اللهِ في الآخِرَةِ، أوْ كَما يَئِسَ الكُفّارُ مِن بَعْثِ مَوْتاهُم."]]);
QTF("gharib",61,[[2,2,"﴿مَا لَا تَفۡعَلُونَ﴾: ما لا تَقُومُونَ بالوفاءِ بهِ."],[3,3,"﴿مَقۡتًا﴾: بُغْضًا."],[4,4,"﴿صَفࣰّا﴾: أي مَصْفُوفِينَ.\n\n﴿مَّرۡصُوصࣱ﴾: مُتَراصٌّ مُحْكَمٌ."],[5,5,"﴿زَاغُوٓاْ﴾: مالُوا عَنِ الحقِّ مع عِلْمِهِم به.\n\n﴿أَزَاغَ ٱللَّهُ قُلُوبَهُمۡ﴾: صَرَفَها عَن قَبُولِ الهِدايَةِ.\n\n﴿ٱلۡفَـٰسِقِينَ﴾: الخارِجِيِنَ عَنِ الطّاعةِ."],[6,6,"﴿لِّمَا بَيۡنَ يَدَيَّ﴾: لِما جاءَ قَبْلي.\n\n﴿وَمُبَشِّرَۢا﴾: ومُخْبِرًا بِمَجِيءِ الرَّسُولِ ﷺ.\n\n﴿بِٱلۡبَيِّنَـٰتِ﴾: بالدَّلائِلِ الواضِحاتِ الدّالّةِ عَلى نُبُوَّتِهِ."],[7,7,"﴿وَمَنۡ أَظۡلَمُ﴾: لا أحَدَ أظْلَمُ.\n\n﴿ٱفۡتَرَىٰ﴾: اختَلَقَ."],[8,8,"﴿لِيُطۡفِـُٔواْ نُورَ ٱللَّهِ﴾: لِيَقْضُوا عَلى دِينِ اللهِ.\n\n﴿مُتِمُّ نُورِهِۦ﴾: سيُتِمُّ هَذا الإسلامَ حَتّى يَنْتَشِرَ."],[9,9,"﴿بِٱلۡهُدَىٰ﴾: بالقُرآنِ.\n\n﴿وَدِينِ ٱلۡحَقِّ﴾: ودِينِ الإسْلامِ.\n\n﴿لِيُظۡهِرَهُۥ﴾: ليُعْلِيَهُ."],[12,12,"﴿مِن تَحۡتِهَا﴾: مِن تَحْتِ قُصُورِها وأَشْجارِها.\n\n﴿عَدۡنࣲ﴾: إقامَةٍ دائِمَةٍ."],[13,13,"﴿وَأُخۡرَىٰ﴾: ونِعْمَةٌ أُخْرى.\n\n﴿قَرِيبࣱ﴾: عاجِلٌ."],[14,14,"﴿لِلۡحَوَارِيِّـۧنَ﴾: هُمْ أصْفِياءُ عِيسى –عَلَيهِ السَّلامُ- وخُلَّصُ أصحابِهِ.\n\n﴿ظَـٰهِرِينَ﴾: غالِبِينَ: إما بالحُجَّةِ أو بِبِعْثَةِ مُحَمَّدٍ ﷺ."]]);
QTF("gharib",62,[[1,1,"﴿يُسَبِّحُ﴾: يُنَزِّهُ.\n\n﴿ٱلۡمَلِكِ﴾: المالِكِ لِكُلِّ شَيءٍ المتَصَرِّفِ فِيهِ بِلا مُنازِعٍ.\n\n﴿ٱلۡقُدُّوسِ﴾: المنَزَّهِ عَن كُلِّ نَقْصٍ.\n\n﴿ٱلۡعَزِيزِ﴾: الَّذِي لا يُغالَبُ\n\n﴿ٱلۡحَكِيمِ﴾: المحْكِم فِي تَدْبِيرِهِ وصُنْعِهِ."],[2,2,"﴿ٱلۡأُمِّيِّـۧنَ﴾: العربِ الَّذِينَ لا يَقْرَؤُونَ ولا يَكْتُبُونَ.\n\n﴿ءَايَـٰتِهِۦ﴾: القُرْآنَ.\n\n﴿وَيُزَكِّيهِمۡ﴾: ويُطَهِّرهم مِنَ العقائِدِ الفاسِدَةِ والأخْلاقِ السَّيِّئةِ.\n\n﴿ٱلۡكِتَـٰبَ﴾: القُرْآنَ.\n\n﴿وَٱلۡحِكۡمَةَ﴾: والسُّنَّةَ."],[3,3,"﴿وَءَاخَرِينَ﴾: وأَرْسَلَهُ إلى آخَرِينَ.\n\n﴿مِنۡهُمۡ﴾: مِنَ العَرَبِ ومِن غَيْرِهِم.\n\n﴿لَمَّا يَلۡحَقُواْ بِهِمۡ﴾: لَمْ يَجِيئُوا بَعْدُ، وسَيَجِيئُونَ."],[4,4,"﴿فَضۡلُ ٱللَّهِ﴾: مِمّا تَفَضَّلَ اللهُ بِهِ عَلى هَؤلاءِ دُونَ غَيرِهِم.\n\n﴿ٱلۡفَضۡلِ ٱلۡعَظِيمِ﴾: الإحْسانِ والعَطاءِ الجَزِيلِ."],[5,5,"﴿مَثَلُ﴾: شَبَهُ.\n\n﴿حُمِّلُواْ ٱلتَّوۡرَىٰةَ﴾: كُلِّفُوا العَمَلَ بِها.\n\n﴿لَمۡ يَحۡمِلُوهَا﴾: لم يَعْمَلُوا بِها.\n\n﴿أَسۡفَارَۢا﴾: كُتُبًا لا يَدْرِي ما فِيها.\n\n﴿بِئۡسَ﴾: قَبُحَ.\n\n﴿لَا يَهۡدِي﴾: لا يُوفِّقُ."],[6,6,"﴿هَادُوٓاْ﴾: تَمَسَّكُوا بالِملَّةِ اليهُودِيَّةِ.\n\n﴿أَوۡلِيَآءُ لِلَّهِ﴾: أحِبّاءُ للهِ."],[7,7,"﴿بِمَا قَدَّمَتۡ أَيۡدِيهِمۡ﴾: بِسببِ ما اكْتَسَبُوا في هذه الدُّنيا مِنَ الآثامِ."],[8,8,"﴿فَإِنَّهُۥ مُلَـٰقِيكُمۡ﴾: آتٍ إلَيكُم وقْتَ مَجِيءِ آجالِكُم.\n\n﴿ثُمَّ تُرَدُّونَ﴾: ثم تُرْجَعُونَ يَومَ القِيامةِ.\n\n﴿ٱلۡغَيۡبِ﴾: ما غابَ.\n\n﴿ٱلشَّهَـٰدَةِ﴾: ما حَضَرَ."],[9,9,"﴿نُودِيَ﴾: نادى المؤَذِّنُ.\n\n﴿فَٱسۡعَوۡاْ﴾: فامْضُوا وأَقْبِلُوا إلَيها.\n\n﴿ذِكۡرِ ٱللَّهِ﴾: الموعظةِ في خُطْبَةِ الإمامِ.\n\n﴿وَذَرُواْ﴾: واتْرُكُوا."],[10,10,"﴿وَٱبۡتَغُواْ مِن فَضۡلِ ٱللَّهِ﴾: واطْلُبُوا مِن رِزْقِ اللهِ.\n\n﴿تُفۡلِحُونَ﴾: تَفُوزُونَ بِخَيرَيِ الدُّنيا والآخِرَةِ."],[11,11,"﴿لَهۡوًا﴾: صارِفًا عَنِ الصَّلاةِ.\n\n﴿ٱنفَضُّوٓاْ﴾: تَفَرَّقُوا.\n\n﴿قَآئِمࣰا﴾: أي: عَلى الِمنْبَرِ."]]);
QTF("gharib",63,[[1,1,"﴿ٱلۡمُنَـٰفِقُونَ﴾: جَمْعُ مُنافِقٍ، وهو الَّذِي يُظْهِرُ الإيمانَ ويُسِرُّ الكُفْرَ."],[2,2,"﴿جُنَّةࣰ﴾: وِقايةً لَهُم مِنَ العَذابِ.\n\n﴿فَصَدُّواْ﴾: مَنَعُوا أنْفُسَهُم ومَنَعُوا النّاسَ.\n\n﴿سَآءَ﴾: بِئْسَ."],[3,3,"﴿فَطُبِعَ﴾: فَخُتِم.\n\n﴿لَا يَفۡقَهُونَ﴾: لا يَفْهَمُونَ ولا يُدْرِكُونَ حُجَجَ الإيمانِ."],[4,4,"﴿رَأَيۡتَهُمۡ﴾: نَظَرْتَ إلَيهِم.\n\n﴿تُعۡجِبُكَ أَجۡسَامُهُمۡ﴾: تُعْجِبُكَ هَيْئاتُهُم.\n\n﴿تَسۡمَعۡ﴾: تُصْغِ.\n\n﴿خُشُبࣱ مُّسَنَّدَةࣱ﴾: الأَخْشابُ المُلْقاةُ على الحائِطِ، فلا نَفْعَ فِيها لِأَحَدٍ.\n\n﴿صَيۡحَةٍ﴾: صَوْتٍ عالٍ.\n\n﴿عَلَيۡهِمۡ﴾: واقِعًا عَلَيهِم، وضارًّا بِهِم.\n\n﴿قَـٰتَلَهُمُ ٱللَّهُ﴾: طَرَدَهُم مِن رَّحْمتِهِ.\n\n﴿أَنَّىٰ﴾: كَيفَ.\n\n﴿يُؤۡفَكُونَ﴾: يُصْرَفُونَ عَنِ الحقِّ إلى الباطِلِ؟"],[5,5,"﴿لَوَّوۡاْ رُءُوسَهُمۡ﴾: أمالُوها وحَرَّكُوها إعْراضًا عَن كَلامِ المتَكَلِّم.\n\n﴿يَصُدُّونَ﴾: يُعْرِضُونَ."],[7,7,"﴿حَتَّىٰ﴾: لِأَجْلِ.\n\n﴿يَنفَضُّواْ﴾: يَتَفَرَّقُوا ويَبْتَعِدُوا.\n\n﴿خَزَآئِنُ ٱلسَّمَـٰوَ ٰ⁠تِ﴾: مقارُّ أسبابِ حُصُول الأرزاق منَ الأَمْطارِ والرِّياحِ الصّالِحَةِ وأَشِعَّةِ الشَّمسِ."],[8,8,"﴿ٱلۡمَدِينَةِ﴾: المدِينةِ النَّبَوِيَّةِ.\n\n﴿ٱلۡأَعَزُّ﴾: القويُّ العِزَّةِ، وهو الَّذِي لا يُقْهَرُ ولا يُغْلَبُ.\n\n﴿ٱلۡعِزَّةُ﴾: القُوَّةُ الحقُّ المطْلَقَةُ، وعِزَّةُ غَيرِ اللهِ ناقِصةٌ."],[9,9,"﴿لَا تُلۡهِكُمۡ﴾: لا تَشْغَلْكُم.\n\n﴿ذِكۡرِ ٱللَّهِ﴾: عِبادتِهِ وطاعَتِهِ."],[11,11,"﴿أَجَلُهَا﴾: وقْتُ موتِها."]]);
QTF("gharib",64,[[1,1,"﴿يُسَبِّحُ﴾: يُنَزِّهُ.\n\n﴿ٱلۡحَمۡدُ﴾: الثَّناءُ الحسنُ الجميلُ."],[3,3,"﴿وَصَوَّرَكُمۡ﴾: خَلَقَكُم.\n\n﴿ٱلۡمَصِيرُ﴾: المَرْجِعُ يَومَ القِيامَةِ."],[4,4,"﴿تُسِرُّونَ﴾: تُخْفُونَ.\n\n﴿تُعۡلِنُونَ﴾: تُظْهِرُونَهُ.\n\n﴿بِذَاتِ ٱلصُّدُورِ﴾: بما تُخْفِيهِ النَّفُوسُ."],[5,5,"﴿فَذَاقُواْ﴾: حَلَّ بِهِم.\n\n﴿وَبَالَ﴾: سُوءَ عاقِبَةِ."],[6,6,"﴿بِٱلۡبَيِّنَـٰتِ﴾: الآياتِ الواضِحاتِ والمُعْجِزاتِ الظّاهراتِ.\n\n﴿وَتَوَلَّواْ﴾: أعْرَضُوا عَنِ الحَقِّ.\n\n﴿وَّٱسۡتَغۡنَى ٱللَّهُ﴾: عَنْ عِبادَتِهِم وإيمانِهِم.\n\n﴿حَمِيدࣱ﴾: مَحْمُودٌ في أقوالِهِ وأفعالِهِ وصِفاتِهِ."],[7,7,"﴿يُبۡعَثُواْ﴾: يُخْرَجُوا مِن قُبُورِهِم.\n\n﴿يَسِيرࣱ﴾: هِيِّنٌ."],[8,8,"﴿وَٱلنُّورِ﴾: واهْتَدُوا بالقرآنِ."],[9,9,"﴿لِيَوۡمِ ٱلۡجَمۡعِ﴾: لِيومِ الحَشْرِ.\n\n﴿ٱلتَّغَابُنِ﴾: الغَبْنُ والتَّفاوُتُ بَينَ الخَلْقِ.\n\n﴿يُكَفِّرۡ﴾: يَمْحُ.\n\n﴿تَحۡتِهَا﴾: تَحْتِ قُصُورِها وأَشْجارِها."],[10,10,"﴿وَبِئۡسَ ٱلۡمَصِيرُ﴾: وساءَ المَرْجِعُ الَّذِي صارُوا إلَيهِ، وهو جَهَنَّمُ."],[11,11,"﴿مُّصِيبَةٍ﴾: مَكْرُوهٍ.\n\n﴿بِإِذۡنِ ٱللَّهِ﴾: بمشيئته.\n\n﴿يَهۡدِ﴾: يُوَفِقْهُ اللهُ إلى مَرْضاتِهِ."],[12,12,"﴿تَوَلَّيۡتُمۡ﴾: أعْرَضْتُم عَن طاعَةِ اللهِ."],[13,13,"﴿ٱللَّهُ لَآ إِلَـٰهَ إِلَّا هُوَ﴾: لا مَعْبُودَ بِحَقٍّ سِواهُ.\n\n﴿فَلۡيَتَوَكَّلِ﴾: فَلْيَعْتَمِدوا في كُلِّ الأُمُورِ."],[14,14,"﴿عَدُوࣰّا لَّكُمۡ﴾: أي: يَمْنَعُونَكُم مِنَ الإسْلامِ أو الهِجْرَةِ أو يكُونونَ سَبَبًا لِلْمَعاصِي.\n\n﴿وَإِن تَعۡفُواْ﴾: تَتَجاوَزُوا عَن سَيِّئاتِهِم.\n\n﴿وَتَغۡفِرُواْ﴾: وتَسْتُرُوها عَلَيهِم."],[15,15,"﴿فِتۡنَةࣱ﴾: اخِتبارٌ لَكُم وشُغْلٌ عَنِ الآخِرَةِ.\n\n﴿أَجۡرٌ﴾: ثَوابٌ."],[16,16,"﴿مَا ٱسۡتَطَعۡتُمۡ﴾: أطَقْتُم.\n\n﴿خَيۡرࣰا﴾: يَكُنْ خَيرًا.\n\n﴿وَمَن يُوقَ شُحَّ نَفۡسِهِۦ﴾: ومَن سَلِمَ مِنَ البُخْلِ والحِرْصِ.\n\n﴿ٱلۡمُفۡلِحُونَ﴾: الظّافِرُونَ بِكُلِّ خَيرٍ."],[17,17,"﴿تُقۡرِضُواْ ٱللَّهَ﴾: تُنْفِقُوا أمْوالَكُم في سَبِيلِ اللهِ بِإخْلاصٍ وطِيبِ نَفْسٍ.\n\n﴿شَكُورٌ﴾: مُجازٍ على الطّاعةِ.\n\n﴿حَلِيمٌ﴾: لا يَعْجَلُ بالعُقُوبَةِ عَلى مَن عَصاهُ."],[18,18,"﴿ٱلۡغَيۡبِ﴾: ما غابَ.\n\n﴿ٱلشَّهَـٰدَةِ﴾: ما لم يَغِبْ عَنِ الأَبْصارِ."]]);
QTF("gharib",65,[[1,1,"﴿إِذَا طَلَّقۡتُمُ﴾: إذا أرَدْتُم أن تُطَلِّقُوا.\n\n﴿لِعِدَّتِهِنَّ﴾: مُسْتَقْبِلاتٍ لِعِدَّتِهِنَّ، أي: في طُهْرٍ لم يَقَعْ فِيه جِماعٌ، أو في حَمْلٍ ظاهِرٍ.\n\n﴿وَأَحۡصُواْ﴾: واحْفَظُوا.\n\n﴿بِفَـٰحِشَةࣲ﴾: بِفعْلَةٍ مُنْكَرَةٍ ظاهِرَةٍ كالزِّنى.\n\n﴿يَتَعَدَّ﴾: يَتجاوَزْه.\n\n﴿يُحۡدِثُ بَعۡدَ ذَ ٰ⁠لِكَ أَمۡرࣰا﴾: يُوقِعُ في قَلْبِ الزَّوجِ الَمحَبَّةَ لِرَجْعَتِها بَعْدَ الطَّلْقةِ والطَّلْقَتيَنِ."],[2,2,"﴿بَلَغۡنَ أَجَلَهُنَّ﴾: قارَبْنَ نِهايةَ عِدَّتِهِنَّ.\n\n﴿فَأَمۡسِكُوهُنَّ﴾: فَراجِعُوهُنَّ.\n\n﴿بِمَعۡرُوفٍ﴾: بحُسْنِ مُعاشَرَةٍ وإنْفاقٍ عَلَيهِنَّ.\n\n﴿فَارِقُوهُنَّ﴾: اتْرُكُوهُنَّ حتّى تَنْقَضِيَ عِدَّتُهُنَّ.\n\n﴿بِمَعۡرُوفٍ﴾: مَعَ إعْطائِهنَّ حُقُوقَهُنَّ مِن غَيرِ مُضارَّةٍ بِهِنَّ.\n\n﴿وَأَقِيمُواْ ٱلشَّهَـٰدَةَ لِلَّهِ﴾: أدُّوا الشَّهادةَ خالصةً للهِ.\n\n﴿مَخۡرَجࣰا﴾: مِن كُلِّ ضِيقٍ."],[3,3,"﴿لَا يَحۡتَسِبُ﴾: لا يَخْطُرُ على بالِهِ ولا يَكُونُ في حِسابِهِ.\n\n﴿حَسۡبُهُۥٓ﴾: كافِيهِ في جَمِيعِ أُمُورِهِ.\n\n﴿بَـٰلِغُ أَمۡرِهِۦ﴾: يَقْضِي ما يُرِيدُ.\n\n﴿قَدۡرࣰا﴾: أجَلًا يَنْتَهِي إلَيهِ."],[4,4,"﴿إِنِ ٱرۡتَبۡتُمۡ﴾: شَكَكْتُم فَلَمْ تَدْرُوا ما عِدّتُهُنَّ؟\n\n﴿وَأُوْلَـٰتُ ٱلۡأَحۡمَالِ﴾: ذواتُ الحمْلِ مِنَ النِّساءِ.\n\n﴿أَجَلُهُنَّ﴾: عِدَّتُهُنَّ."],[5,5,"﴿يُكَفِّرۡ عَنۡهُ سَيِّـَٔاتِهِۦ﴾: يَمْحُ عَنْهُ ذُنُوبَهُ.\n\n﴿وَيُعۡظِمۡ لَهُۥٓ أَجۡرًا﴾: ويُجْزِلْ لَهُ الثَّوابَ."],[6,6,"﴿مِّن وُجۡدِكُمۡ﴾: على قَدْرِ سَعَتِكُم وطاقَتِكُم.\n\n﴿وَلَا تُضَآرُّوهُنَّ﴾: ولا تُلْحِقُوا بِهِنَّ ضَرَرًا.\n\n﴿أُوْلَـٰتِ حَمۡلࣲ﴾: ذَواتِ حَمْلٍ.\n\n﴿وَأۡتَمِرُواْ بَيۡنَكُم﴾: ولْتتَشاوَرُوا.\n\n﴿بِمَعۡرُوفࣲ﴾: ما عُرِف مِن سَماحِةٍ وطِيبِ نَفْسٍ.\n\n﴿وَإِن تَعَاسَرۡتُمۡ﴾: وإن لَم تَتَّفِقُوا على إرضاعِ الأُمِّ."],[7,7,"﴿ذُو سَعَةࣲ﴾: ذُو غِنىً.\n\n﴿وَمَن قُدِرَ عَلَيۡهِ﴾: ضُيِّقَ عَلَيهِ.\n\n﴿إِلَّا مَآ ءَاتَىٰهَا﴾: إلّا عَلى قَدْرِ ما أعْطاها مِنَ المالِ."],[8,8,"﴿وَكَأَيِّن﴾: وكَثيرٍ.\n\n﴿عَتَتۡ﴾: عَصى أهْلُها وتَجاوَزُوا الحدَّ في مَعْصِيَةِ اللهِ.\n\n﴿نُّكۡرࣰا﴾: عَظِيمًا مُنْكَرًا."],[9,9,"﴿فَذَاقَتۡ وَبَالَ أَمۡرِهَا﴾: فَتَجَرَّعُوا سُوءَ عاقِبَةِ عِصْيانِهِم.\n\n﴿عَـٰقِبَةُ أَمۡرِهَا﴾: آخِرُ أمْرِها."],[10,10,"﴿يَـٰٓأُوْلِي ٱلۡأَلۡبَـٰبِ﴾: أصْحابَ العُقُولِ.\n\n﴿ذِكۡرࣰا﴾: قُرآنًا."],[11,11,"﴿مُبَيِّنَـٰتࣲ﴾: مُوَضِّحاتٍ لَكُم الحقَّ.\n\n﴿ٱلظُّلُمَـٰتِ﴾: ظُلُماتِ الكُفْرِ.\n\n﴿ٱلنُّورِ﴾: نُورِ الإيمانِ.\n\n﴿رِزۡقًا﴾: في الجنَّةِ."],[12,12,"﴿وَمِنَ ٱلۡأَرۡضِ﴾: وخَلَقَ سَبْعًا مِنَ الأَرَضِينَ.\n\n﴿ٱلۡأَمۡرُ﴾: مَّما أوْحاهُ اللهُ إلى رُسُلِهِ وما يُدَبِّرُ بِهِ خَلْقَهُ.\n\n﴿بَيۡنَهُنَّ﴾: بَينَ السَّمواتِ والأَرْضِ."]]);
QTF("gharib",66,[[2,2,"﴿تَحِلَّةَ أَيۡمَـٰنِكُمۡ﴾: تَحْلِيلَ قَسَمِكُم بأَداءِ الكَفّارَةِ عَنْها، وهي إطْعامُ عَشْرَةِ مَساكِينَ أوْ كِسْوتُهُم أو تَحْرِيرُ رَقَبَةٍ، فَمَن لَمْ يَجِدْ فَصِيامُ ثَلاثَةِ أيّامٍ.\n\n﴿مَوۡلَىٰكُمۡ﴾: ناصِرُكُم ومُتَوَلّي أُمُورِكُم."],[3,3,"﴿وَأَظۡهَرَهُ ٱللَّهُ﴾: وأَطْلَعَهُ اللهُ عَلى إفْشائِها سِرَّهُ.\n\n﴿عَرَّفَ بَعۡضَهُۥ﴾: أعْلَمَ حَفْصَةَ بَعْضَ ما أخْبرَتْ بِهِ."],[4,4,"﴿صَغَتۡ﴾: مالَتْ.\n\n﴿وَإِن تَظَـٰهَرَا عَلَيۡهِ﴾: وإن تَعاوَنا عَلَيهِ بِما يَسُوءُهُ.\n\n﴿مَوۡلَىٰهُ﴾: وليُّهُ وناصِرُهُ.\n\n﴿ظَهِيرٌ﴾: أعْوانٌ لَهُ عَلى مَن يُعادُونَهُ."],[5,5,"﴿مُسۡلِمَـٰتࣲ﴾: خاضِعاتٍ للهِ بالطّاعةِ.\n\n﴿قَـٰنِتَـٰتࣲ﴾: مُطِيعاتٍ للهِ.\n\n﴿سَـٰٓئِحَـٰتࣲ﴾: صائِماتٍ."],[6,6,"﴿قُوٓاْ﴾: احْفَظُوا.\n\n﴿لَّا يَعۡصُونَ﴾: لا يخالِفُونَ."],[7,7,"﴿لَا تَعۡتَذِرُواْ﴾: لا تْلتَمِسُوا الأَعْذارَ."],[8,8,"﴿تُوبُوٓاْ﴾: ارْجِعُوا عَن ذُنُوبِكُم.\n\n﴿تَوۡبَةࣰ نَّصُوحًا﴾: رُجُوعًا لا مَعْصِيَةَ بَعْدَهُ.\n\n﴿عَسَىٰ رَبُّكُمۡ﴾: يَتَحَقَّقُ رَجاؤُكُم بِوَعْدِ ربِّكُم.\n\n﴿يُكَفِّرَ﴾: يَمْحُوَ.\n\n﴿مِن تَحۡتِهَا﴾: من تَحْتِ قُصُورِها وأَشْجارِها.\n\n﴿مِن تَحۡتِهَا﴾: لا يَلْحِقُ بِهِم هَوانًا وذُلًّا بِسَبَبِ العَذابِ، بَلْ يُعْلي شَأْنَهُم.\n\n﴿يَسۡعَىٰ﴾: يسِيرُ.\n\n﴿بَيۡنَ أَيۡدِيهِمۡ﴾: أمامَهُم.\n\n﴿أَتۡمِمۡ﴾: أدِمْ، أو زِدْ."],[9,9,"﴿وَٱغۡلُظۡ عَلَيۡهِمۡ﴾: واسْتَعْمِلْ مَعَهُم الشِّدَّةَ في جِهادِهِم.\n\n﴿وَمَأۡوَىٰهُمۡ﴾: ومَسْكَنُهُم الَّذِي يصيرُونَ إلَيهِ في الآخِرَةِ.\n\n﴿وَبِئۡسَ ٱلۡمَصِيرُ﴾: وقَبُحَ ذَلِكَ المَرْجِعُ الَّذِي يَرْجِعُونَ إلَيهِ."],[10,10,"﴿فَخَانَتَاهُمَا﴾: أي في الدِّين بالكُفْرِ.\n\n﴿فَلَمۡ يُغۡنِيَا﴾: فَلَمْ يَدْفَعا."],[12,12,"﴿أَحۡصَنَتۡ﴾: حَفِظَتْ.\n\n﴿فَنَفَخۡنَا﴾: أمَرْنا جِبْرِيلَ أن يَنْفُخَ في جَيْبِ قَمِيصِها.\n\n﴿ٱلۡقَـٰنِتِينَ﴾: المُطِيعِينَ للهِ."]]);
QTF("gharib",67,[[1,1,"﴿تَبَـٰرَكَ ٱلَّذِي﴾: تَكاثَرَ خَيرُ اللهِ وبِرُّهُ عَلى جَمِيعِ خَلْقِهِ.\n\n﴿بِيَدِهِ ٱلۡمُلۡكُ﴾: التَّصَرُّفُ في مُلْكِ الدُّنيا والآخِرَةِ."],[2,2,"﴿لِيَبۡلُوَكُمۡ﴾: لِيَخْتَبِرَكُم."],[3,3,"﴿طِبَاقࣰا﴾: مُتَناسِقَةً.\n\n﴿تَفَـٰوُتࣲ﴾: اخْتِلافٍ وتَبايُنٍ.\n\n﴿فَٱرۡجِعِ ٱلۡبَصَرَ﴾: فَأَعِدِ النَّظَرَ.\n\n﴿فُطُورࣲ﴾: شُقُوقٍ أو صُدُوعٍ."],[4,4,"﴿كَرَّتَيۡنِ﴾: مَرَّةً بَعْدَ مَرَّةٍ.\n\n﴿يَنقَلِبۡ﴾: يَرْجِعْ.\n\n﴿خَاسِئࣰا﴾: ذَلِيلًا صاغِرًا.\n\n﴿حَسِيرࣱ﴾: مُتْعَبٌ كَلِيلٌ."],[5,5,"﴿ٱلدُّنۡيَا﴾: القَرِيبةَ.\n\n﴿بِمَصَـٰبِيحَ﴾: بِنُجُومٍ عَظِيمَةٍ مُضِيئةٍ.\n\n﴿رُجُومࣰا﴾: شُهُبًا مُحْرِقَةً.\n\n﴿لِّلشَّيَـٰطِينِ﴾: لِمُسْتَرِقِي السَّمْعِ مِنَ الشَّياطِينِ.\n\n﴿ٱلسَّعِيرِ﴾: النّارِ المُوقَدَةِ."],[6,6,"﴿وَبِئۡسَ ٱلۡمَصِيرُ﴾: وساءَ المَرْجِعُ لهم جَهَنَّمُ."],[7,7,"﴿أُلۡقُواْ﴾: طُرِحُوا.\n\n﴿شَهِيقࣰا﴾: صَوْتًا شَدِيدًا مُنْكَرًا.\n\n﴿تَفُورُ﴾: تَغْلِي غَلَيانًا شَدِيدًا."],[8,8,"﴿تَمَيَّزُ﴾: تَتَمَزَّقُ.\n\n﴿مِنَ ٱلۡغَيۡظِ﴾: مِن شِدَّةِ غَضَبِها عَلى الكُفّارِ.\n\n﴿أُلۡقِيَ﴾: طُرِحِ.\n\n﴿فَوۡجࣱ﴾: جَماعةٌ مِنَ النّاسِ.\n\n﴿خَزَنَتُهَآ﴾: الملائِكةُ المُوكَّلُونَ بأَمْرِها.\n\n﴿نَذِيرࣱ﴾: رَسُولٌ يُحَذِّرُكُم مِن هَذا العَذابِ."],[10,10,"﴿نَسۡمَعُ﴾: سَماعَ مَن يَطْلُبُ الحقَّ.\n\n﴿نَعۡقِلُ﴾: نُفَكِّرُ فِيما نُدْعى إلَيهِ.\n\n﴿ٱلسَّعِيرِ﴾: النّارِ المُوقَدَةِ."],[11,11,"﴿فَسُحۡقࣰا﴾: فَبُعْدًا عَن رَّحَمَةِ اللهِ."],[12,12,"﴿بِٱلۡغَيۡبِ﴾: وهُمْ غائِبُونَ عَنْ أعْيُنِ النّاسِ، وقَبْلَ مُعايَنَةِ العَذابِ.\n\n﴿وَأَجۡرࣱ﴾: ثَوابٌ."],[13,13,"﴿أَسِرُّواْ﴾: وأَخْفُوا.\n\n﴿أَوِ ٱجۡهَرُواْ بِهِۦٓ﴾: أعْلِنُوهُ.\n\n﴿بِذَاتِ ٱلصُّدُورِ﴾: بِما يَتَرَدَّدُ في النَّفْسِ مِنَ الخواطِرِ والنِّياتِ."],[14,14,"﴿يَعۡلَمُ﴾: اللهُ.\n\n﴿مَنۡ خَلَقَ﴾: المخلُوقِينَ.\n\n﴿ٱللَّطِيفُ﴾: العالِمُ خَبايا الأُمُورِ والمُدَبِّرُ لَها بِرِفْقٍ وحِكْمَةٍ.\n\n﴿ٱلۡخَبِيرُ﴾: العَلِيمُ بِباطِنِ أمرِهِم."],[15,15,"﴿ذَلُولࣰا﴾: سَهْلةً مُمَهَّدَةً تَسْتَقِرُّونَ عَلَيها.\n\n﴿مَنَاكِبِهَا﴾: نواحِيها وجَوانِبِها.\n\n﴿ٱلنُّشُورُ﴾: البَعْثُ مِن قُبُورِكُم لِلْحِسابِ."],[16,16,"﴿ءَأَمِنتُم﴾: هَلْ أمِنتُم؟\n\n﴿مَّن فِي ٱلسَّمَآءِ﴾: الَّذِي فَوقَ السَّماءِ.\n\n﴿يَخۡسِفَ بِكُمُ ٱلۡأَرۡضَ﴾: يَقْلِبَ ظاهِرَ الأرضِ باطِنًا، وباطِنَها ظاهِرًا مُصاحِبةً لِذَواتِكم.\n\n﴿تَمُورُ﴾: تَضْطَرِبُ بِكُم حَتّى تَهْلِكُوا."],[17,17,"﴿حَاصِبࣰا﴾: رِيحًا تَرْجُمُكُم بالحِجارةِ الصَّغِيرةِ.\n\n﴿نَذِيرِ﴾: تَحْذِيرِي لَكُم."],[18,18,"﴿نَكِيرِ﴾: إنْكارِي عَلَيهِم بإنْزِالِ العَذابِ بِهِم."],[19,19,"﴿صَـٰٓفَّـٰتࣲ﴾: باسِطاتٍ أجْنِحَتَها عِنْدَ طَيَرانِها في الهواءِ.\n\n﴿وَيَقۡبِضۡنَ﴾: ويَضْمُمْنَ أجْنِحَتَها."],[20,20,"﴿أَمَّنۡ هَـٰذَا﴾: بَلْ مَن هَذا.\n\n﴿جُندࣱ لَّكُمۡ﴾: حِزْبٌ لَكُم.\n\n﴿مِّن دُونِ ٱلرَّحۡمَـٰنِ﴾: مِن غَيْرِ الرَّحمنِ.\n\n﴿إِنِ﴾: ما.\n\n﴿غُرُورٍ﴾: خِداعٍ وضَلالٍ مِنَ الشَّيطانِ."],[21,21,"﴿لَّجُّواْ﴾: اسْتَمَرُّوا في طُغْيانِهِم وكُفْرِهِم.\n\n﴿عُتُوࣲّ﴾: مُعانَدَةٍ واسْتِكْبارٍ\n\n﴿وَنُفُورٍ﴾: فِرارٍ مِنَ الحقِّ."],[22,22,"﴿مُكِبًّا﴾: ساقِطًا عَلى وجْهِهِ.\n\n﴿أَهۡدَىٰٓ﴾: أشَدُّ اسْتِقامةً عَلى الطَّرِيقةِ.\n\n﴿سَوِيًّا﴾: مُسْتَوِيًا."],[23,23,"﴿أَنشَأَكُمۡ﴾: أوْجَدَكُم مِن العَدَمِ.\n\n﴿وَٱلۡأَفۡـِٔدَةَ﴾: القُلُوبَ."],[24,24,"﴿ذَرَأَكُمۡ﴾: خَلَقَكُم ونَشَرَكُم.\n\n﴿تُحۡشَرُونَ﴾: تُجْمَعُونَ لِلْحِسابِ والجَزاءِ."],[26,26,"﴿نَذِيرࣱ﴾: مُخَوِّفٌ.\n\n﴿مُّبِينࣱ﴾: أُبَيِّنُ لَكُمُ الشَّرائِعَ."],[27,27,"﴿زُلۡفَةࣰ﴾: قَرِيبًا مِنهُم.\n\n﴿سِيٓـَٔتۡ﴾: ظَهَرَتْ الذِّلَّةُ والكآبةُ.\n\n﴿بِهِۦ تَدَّعُونَ﴾: تَطْلُبُونَ تَعْجِيلَه في الدُّنيا."],[28,28,"﴿أَرَءَيۡتُمۡ﴾: أخْبِرُوني.\n\n﴿أَهۡلَكَنِيَ﴾: أماتَنِي.\n\n﴿يُجِيرُ﴾: يَحْمِي ويَمْنَعُ."],[29,29,"﴿ءَامَنَّا بِهِۦ﴾: صَدَّقْنا بِهِ وعَمِلْنا بِشَرْعِهِ.\n\n﴿تَوَكَّلۡنَا﴾: اعْتَمَدْنا في كُلِّ أُمُورِنا.\n\n﴿ضَلَـٰلࣲ﴾: بُعْدٍ عَن صِراطِ اللهِ المُسْتَقِيمِ."],[30,30,"﴿أَرَءَيۡتُمۡ﴾: أخْبِرُونِي.\n\n﴿أَصۡبَحَ﴾: صارَ.\n\n﴿غَوۡرࣰا﴾: ذاهِبًا في الأرضِ لا تصِلُونَ إلَيهِ.\n\n﴿مَّعِينِۭ﴾: جارٍ على وجْهِ الأَرْضِ تَراهُ العُيُونُ."]]);
QTF("gharib",68,[[1,1,"﴿نٓ﴾: سَبَقَ الكَلامُ عَلى الحروفِ المُقَطَّعةِ في أوَّلِ سُورَةِ البَقَرَةِ.\n\n﴿وَٱلۡقَلَمِ﴾: أقْسَمَ اللهُ بالقلمِ الَّذِي يَكْتُبُ بهِ الملائِكةُ والنّاسُ.\n\n﴿وَمَا يَسۡطُرُونَ﴾: أقْسَمَ اللهُ بِما يَكْتُبُونَ مِنَ الخَيرِ والنَّفْعِ والعُلُومِ."],[3,3,"﴿لَأَجۡرًا﴾: لَثَوابًا عَظِيمًا.\n\n﴿غَيۡرَ مَمۡنُونࣲ﴾: غيرَ مَنقُوصٍ ولا مَقْطُوعٍ."],[6,6,"﴿بِأَييِّكُمُ﴾: في أيٍّ مِنكُم.\n\n﴿ٱلۡمَفۡتُونُ﴾: الفِتْنَةُ و الجنُونُ."],[9,9,"﴿وَدُّواْ﴾: تَمَنَّوا وأحَبُّوا.\n\n﴿لَوۡ تُدۡهِنُ﴾: لو تُلايِنُهُم وتُصانِعُهُم عَلى بَعْضِ ما هُم عَلَيهِ.\n\n﴿فَيُدۡهِنُونَ﴾: فَيَلِينُونَ لَكَ."],[10,10,"﴿حَلَّافࣲ﴾: كَثِيرِ الحَلْفِ.\n\n﴿مَّهِينٍ﴾: حَقِيرٍ."],[11,11,"﴿هَمَّازࣲ﴾: مُغْتابٍ للنّاسِ.\n\n﴿مَّشَّآءِۭ بِنَمِيمࣲ﴾: يَمْشِي بَينَ النّاسِ ويَنْقُلُ حَدِيثَ بَعْضِهِم إلى بَعْضٍ عَلى وجْهِ الإفْسادِ بَيْنَهُم."],[12,12,"﴿مَّنَّاعࣲ﴾: شَدِيدِ المنْعِ لِلخَيْرِ.\n\n﴿مُعۡتَدٍ﴾: مُتَجاوِزٍ حَدَّه في العُدْوانِ عَلى النّاسِ وتَناوُلِ الُمحَرَّماتِ.\n\n﴿أَثِيمٍ﴾: كَثِيرِ الآثامِ."],[13,13,"﴿عُتُلِّۭ﴾: شَدَيدٍ في كُفْرِهِ، فاحِشٍ لَئِيمٍ.\n\n﴿زَنِيمٍ﴾: مَنسُوبٍ إلى غَيرِ أبِيهِ."],[14,14,"﴿أَن كَانَ ذَا مَالࣲ وَبَنِينَ﴾: طَغى وتَكَبَّرَ لِأَجْلِ أن رَّزَقَهُ اللهُ مالًا وبَنِينَ فَلَمْ يَشْكُرِ النِّعْمَةَ."],[15,15,"﴿أَسَـٰطِيرُ ٱلۡأَوَّلِينَ﴾: أباطِيلُ الأوَّلِينَ وخُرافاتُهُم."],[16,16,"﴿سَنَسِمُهُۥ﴾: سَنَجْعلُ عَلامةً لازِمةً لا تُفارِقُهُ.\n\n﴿عَلَى ٱلۡخُرۡطُومِ﴾: عَلى أنْفِهِ عُقُوبةً لَهُ."],[17,17,"﴿بَلَوۡنَـٰهُمۡ﴾: اخْتَبَرْنا أهْلَ مَكَّةَ بالجُوعِ والقَحْطِ.\n\n﴿ٱلۡجَنَّةِ﴾: الحَدِيقَةِ.\n\n﴿لَيَصۡرِمُنَّهَا﴾: لَيَقْطَعُنَّ ثِمارَها.\n\n﴿مُصۡبِحِينَ﴾: مُبَكِّرِينَ في الصَّباحِ."],[18,18,"﴿وَلَا يَسۡتَثۡنُونَ﴾: ولَمْ يَقُولُوا: إن شاءَ اللهُ."],[19,19,"﴿فَطَافَ عَلَيۡهَا طَآئِفࣱ مِّن رَّبِّكَ﴾: فَأَنْزَلَ اللهُ عَلَيها نارًا أحْرَقَتْها لَيلًا."],[20,20,"﴿كَٱلصَّرِيمِ﴾: مُحْتَرِقَةً سَوْداءَ كالليلِ المُظْلمِ."],[21,21,"﴿فَتَنَادَوۡاْ﴾: فَنادى بَعْضُهُم بَعْضا.\n\n﴿مُصۡبِحِينَ﴾: وقْتَ الصَّباحِ."],[22,22,"﴿ٱغۡدُواْ﴾: اذْهَبُوا مُبَكِّرِينَ.\n\n﴿حَرۡثِكُمۡ﴾: زَرْعِكُم.\n\n﴿صَـٰرِمِينَ﴾: قاطِعِينَ ثِمارَكُم."],[23,23,"﴿يَتَخَـٰفَتُونَ﴾: يُسِرُّ بَعْضُهُم إلى بَعْضٍ في الكَلامِ."],[25,25,"﴿وَغَدَوۡاْ﴾: سارُوا في أوَّلِ النَّهارِ.\n\n﴿عَلَىٰ حَرۡدࣲ﴾: على أمْرٍ مُجْمَعٍ عَلَيهِ."],[26,26,"﴿فَلَمَّا رَأَوۡهَا﴾: أي مُحْتَرِقَةً.\n\n﴿لَضَآلُّونَ﴾: أخْطأنا الطَّريقَ إلى حَدِيقَتِنا."],[27,27,"﴿مَحۡرُومُونَ﴾: حُرِمْنا خيرَها بِسَبَبِ مَنعِنا الَمساكِينَ."],[28,28,"﴿أَوۡسَطُهُمۡ﴾: أعْدَلُهُم وأَفْضَلُهُم.\n\n﴿لَوۡلَا﴾: هَلّا.\n\n﴿تُسَبِّحُونَ﴾: تَقُولُونَ: إن شاء اللهُ."],[29,29,"﴿سُبۡحَـٰنَ رَبِّنَآ﴾: نُنَزِّهُ رَبَّنا عَنِ الظُّلْمِ فِيما أصابَنا."],[30,30,"﴿يَتَلَـٰوَمُونَ﴾: يَلُومُ بَعْضُهم بَعْضًا."],[31,31,"﴿يَـٰوَيۡلَنَآ﴾: نادَوا عَلى أنْفُسِهِم بِالشَّرِّ والعَذابِ.\n\n﴿طَـٰغِينَ﴾: مُتَجاوِزِينَ الحدَّ في مَنعِنا الفُقَراءَ."],[32,32,"﴿رَ ٰ⁠غِبُونَ﴾: طالِبُونَ الخيرَ والعفوَ عَن سيِّئاتِنا."],[33,33,"﴿كَذَ ٰ⁠لِكَ ٱلۡعَذَابُ﴾: نَفْعَلُ بِمن تَعَدّى حُدُودَنا مِثلَ ما فَعَلْنا بِهَؤُلاءِ."],[36,36,"﴿كَيۡفَ تَحۡكُمُونَ﴾: كَيفَ تَقْضُونَ بِهذا الحُكْمِ الظّالِمِ؟"],[37,37,"﴿كِتَـٰبࣱ﴾: أُنْزِلَ مِن عِنْدِ اللهِ.\n\n﴿تَدۡرُسُونَ﴾: تَقْرَؤونَ فِيهِ هَذا الحُكْمَ الجائِرَ."],[38,38,"﴿لَمَا تَخَيَّرُونَ﴾: ما تَشْتَهُونَ وتَخْتارُونَ، ليسَ لَكُم ذَلِكَ."],[39,39,"﴿أَيۡمَـٰنٌ عَلَيۡنَا﴾: عُهُودٌ ومَواثِيقُ عَلَينا.\n\n﴿بَـٰلِغَةٌ﴾: مُؤَكَّدةٌ."],[40,40,"﴿زَعِيمٌ﴾: كَفِيلٌ وضامِنٌ."],[41,41,"﴿أَمۡ لَهُمۡ شُرَكَآءُ﴾: ألَهُم أرْبابٌ يَفْعَلُونَ بِهِم ما زَعَمُوا مِنَ الكَرامةِ؟"],[42,42,"﴿سَاقࣲ﴾: يَكْشِفُ رَبُّنا عَن ساقِهِ يَوْمَ القِيامَةِ فَيَسْجُدُ لَهُ كُلُّ مُؤْمِنٍ ومُؤْمِنَةٍ، ولا يَتَمكَّنُ المنافِقُونَ مِنَ السُّجُودِ."],[43,43,"﴿خَـٰشِعَةً أَبۡصَـٰرُهُمۡ﴾: مُنْكَسِرَةً لا يَرْفَعُونَها.\n\n﴿تَرۡهَقُهُمۡ﴾: تَغْشاهُم."],[44,44,"﴿فَذَرۡنِي وَمَن يُكَذِّبُ﴾: خَلِّ بينِي وبَينَ مَنُ يُكذِّبُ.\n\n﴿سَنَسۡتَدۡرِجُهُم﴾: سَنَمُدُّهُم بالأمْوالِ والأَولادِ والنِّعَمِ اسْتِدْراجًا لَهُم."],[45,45,"﴿وَأُمۡلِي لَهُمۡ﴾: وأُمْهِلُهُم وأُطِيلُ أعْمارَهُم لِيَزْدادُوا إثْما.\n\n﴿كَيۡدِي﴾: مَكْرِي بِالكُفّارِ.\n\n﴿مَتِينٌ﴾: قَوِيٌّ شدِيدٌ."],[46,46,"﴿مِّن مَّغۡرَمࣲ﴾: مِن غَرامَةِ ذَلِكَ الأَجْرِ.\n\n﴿مُّثۡقَلُونَ﴾: يَثْقُلُ عَلَيهِم حِمْلُهُ."],[47,47,"﴿أَمۡ عِندَهُمُ ٱلۡغَيۡبُ﴾: بَلْ أعِنْدَهُم عِلْمُ الغَيبِ؟"],[48,48,"﴿كَصَاحِبِ ٱلۡحُوتِ﴾: هُو يُونُسُ -عَلَيهِ السَّلامُ-.\n\n﴿مَكۡظُومࣱ﴾: مَمْلُوءٌ غَمًّا وكَرْبًا."],[49,49,"﴿نِعۡمَةࣱ مِّن رَّبِّهِۦ﴾: التَّوبَةُ وقَبُولُها مِنهُ.\n\n﴿لَنُبِذَ﴾: لَطُرِحَ.\n\n﴿بِٱلۡعَرَآءِ﴾: بالأرْضِ الفَضاءِ المهْلِكَةِ.\n\n﴿مَذۡمُومࣱ﴾: آتٍ بِما يُلامُ عَلَيهِ."],[50,50,"﴿فَٱجۡتَبَـٰهُ﴾: فاخْتارَهُ لِرِسالتِهِ."],[51,51,"﴿لَيُزۡلِقُونَكَ﴾: لَيُصِيبُونَكَ بالعَينِ لِبُغْضِهِم إيّاكَ.\n\n﴿ٱلذِّكۡرَ﴾: القُرَآنَ."]]);
QTF("gharib",69,[[1,1,"﴿ٱلۡحَآقَّةُ﴾: القِيامة الواقِعةُ حَقًّا الَّتِي يَتَحَقَّقُ فِيها الوعْدُ والوَعِيدُ."],[3,3,"﴿وَمَآ أَدۡرَىٰكَ﴾: وأيُّ شَيءٍ عَرَّفَكَ حَقيقَةَ القيامَةِ؟"],[4,4,"﴿بِٱلۡقَارِعَةِ﴾: بالقِيامَةِ الَّتِي تَقْرَعُ القُلُوبَ بِأهْوالِها."],[5,5,"﴿بِٱلطَّاغِيَةِ﴾: بالصَّيحَةِ العَظِيمَةِ الَّتِي جاوزَتِ الحدَّ في شِدَّتِها."],[6,6,"﴿صَرۡصَرٍ﴾: بارِدَةٍ.\n\n﴿عَاتِيَةࣲ﴾: شَدِيدَةٍ الهُبُوبِ."],[7,7,"﴿سَخَّرَهَا عَلَيۡهِمۡ﴾: سَلَّطَها اللهُ عَلَيهِم.\n\n﴿حُسُومࣰا﴾: مُتَتابِعَةً.\n\n﴿صَرۡعَىٰ﴾: مَوْتى.\n\n﴿أَعۡجَازُ نَخۡلٍ﴾: أُصُولُ نَخْلٍ.\n\n﴿خَاوِيَةࣲ﴾: خَرِبَةٍ مُتآكِلَةِ الأَجْوافِ."],[8,8,"﴿بَاقِيَةࣲ﴾: نَفْسٍ باقِيةٍ دُونَ هَلاكٍ."],[9,9,"﴿وَٱلۡمُؤۡتَفِكَـٰتُ﴾: وأَهلُ قُرى قَوْمِ لُوطٍ الَّذِينَ انْقَلَبَتْ بِهم دِيارُهُم.\n\n﴿بِٱلۡخَاطِئَةِ﴾: بِسَبَبِ الفَعْلَةِ المنكرَةِ مِنَ الكُفْرِ والفواحِشِ."],[10,10,"﴿فَأَخَذَهُمۡ﴾: فَأَهْلَكَهُم.\n\n﴿رَّابِيَةً﴾: بالِغةً في الشِّدَّةِ."],[11,11,"﴿طَغَا ٱلۡمَآءُ﴾: جاوَزَ حَدَّهُ حتّى عَلا وارْتَفَعَ فَوْقَ كُلِّ شَيءٍ.\n\n﴿حَمَلۡنَـٰكُمۡ﴾: حَمَلْناكُم وأنتُم في أصْلابِ آبائِكُم وأُمَّهاتِكُم.\n\n﴿ٱلۡجَارِيَةِ﴾: السَّفِينَةِ الَّتِي تَجْرِي في الماءِ."],[12,12,"﴿لِنَجۡعَلَهَا﴾: لِنَجْعَلَ الواقِعةَ الَّتِي نَجا فِيها المُؤمِنُونَ، وأُغْرِقَ فِيها الكافِرُونَ.\n\n﴿تَذۡكِرَةࣰ﴾: عِبْرةً وعِظَةً.\n\n﴿وَتَعِيَهَآ﴾: وتَحْفَظَها."],[13,13,"﴿ٱلصُّورِ﴾: القَرْنِ الَّذِي يَنْفُخُ فيه المَلَكُ عِنْدَ قِيامِ السّاعةِ."],[14,14,"﴿وَحُمِلَتِ ٱلۡأَرۡضُ وَٱلۡجِبَالُ﴾: رُفِعَت عن أماكِنِها.\n\n﴿فَدُكَّتَا دَكَّةࣰ وَ ٰ⁠حِدَةࣰ﴾: دُقَّتا دَقَّةً واحِدَةً."],[15,15,"﴿وَقَعَتِ ٱلۡوَاقِعَةُ﴾: قامَتِ القِيامةِ."],[16,16,"﴿وَٱنشَقَّتِ﴾: انْصَدَعَتْ مُتَشَقِّقَةً.\n\n﴿وَاهِيَةࣱ﴾: ضَعِيفَةٌ لا تَماسُكَ فِيها."],[17,17,"﴿وَٱلۡمَلَكُ عَلَىٰٓ أَرۡجَآئِهَا﴾: والملائِكَةُ على أطْرافِها.\n\n﴿عَرۡشَ رَبِّكَ﴾: وهو سَرِيرُ الملْكِ الَّذِي تَحْمِلُه الملائِكةُ، واسْتَوى عَلَيهِ الرحمنُ، وهو أعْظَمُ المَخْلُوقاتِ، وهو سَقْفُ جَنَّةِ الفِرْدَوسِ.\n\n﴿ثَمَـٰنِيَةࣱ﴾: أي من الملائِكةِ العِظامِ."],[18,18,"﴿تُعۡرَضُونَ﴾: أي: عَلى اللهِ.\n\n﴿لَا تَخۡفَىٰ مِنكُمۡ خَافِيَةࣱ﴾: لا تَخْفى عَلى اللهِ نَفْسٌ خافِيةٌ مِنكُم."],[19,19,"﴿هَآؤُمُ﴾: تعالَوا."],[20,20,"﴿ظَنَنتُ﴾: أيْقَنْتُ.\n\n﴿حِسَابِيَهۡ﴾: جَزائِي يومَ القيامةِ."],[21,21,"﴿رَّاضِيَةࣲ﴾: مَرْضِيَّةٍ."],[22,22,"﴿عَالِيَةࣲ﴾: مُرْتَفِعَةِ المكانِ والدَّرجاتِ."],[23,23,"﴿قُطُوفُهَا﴾: ثِمارُها.\n\n﴿دَانِيَةࣱ﴾: قَرِيبَةُ التَّناوُلِ."],[24,24,"﴿هَنِيٓـَٔۢا﴾: أكْلًا وشُرْبًا يَهْنأُ بِهما صاحِبُهُما.\n\n﴿أَسۡلَفۡتُمۡ﴾: قدَّمْتُم.\n\n﴿ٱلۡأَيَّامِ ٱلۡخَالِيَةِ﴾: أيّامِ الدُّنيا الماضِيةِ."],[26,26,"﴿حِسَابِيَهۡ﴾: جَزائِي."],[27,27,"﴿يَـٰلَيۡتَهَا﴾: ياليتَ الموتَةَ الَّتِي مِتُّها في الدُّنيا.\n\n﴿ٱلۡقَاضِيَةَ﴾: القاطِعةَ لِأَمْرِي فلا أُبْعَثُ."],[28,28,"﴿مَآ أَغۡنَىٰ﴾: ما نَفَعَ."],[29,29,"﴿هَلَكَ﴾: غابَ.\n\n﴿سُلۡطَـٰنِيَهۡ﴾: مُلْكِي."],[30,30,"﴿فَغُلُّوهُ﴾: اجْعَلُوا القَيْدَ في عُنُقِه."],[31,31,"﴿صَلُّوهُ﴾: أدْخِلُوهُ."],[32,32,"﴿سِلۡسِلَةࣲ﴾: مَجْمُوعِ حَلَقٍ مِن حَدِيدٍ داخِلٍ بَعْضُها فِي بَعْضٍ.\n\n﴿ذَرۡعُهَا﴾: مِقْدارُ طُولِها بالذِّراعِ.\n\n﴿فَٱسۡلُكُوهُ﴾: فَأَدْخِلُوه في السِّلْسِلَةِ."],[34,34,"﴿وَلَا يَحُضُّ﴾: ولا يَحُثُّ."],[35,35,"﴿هَـٰهُنَا﴾: يَومَ القِيامةِ.\n\n﴿حَمِيمࣱ﴾: قَرِيبٌ يدفعُ عنَه العذابَ."],[36,36,"﴿غِسۡلِينࣲ﴾: صَدِيدِ أهْلِ النّارِ وما يَسِيلُ مِن أجْسادِهِم."],[37,37,"﴿ٱلۡخَـٰطِـُٔونَ﴾: المذْنِبُونَ أشَدَّ الذَّنبِ وهو الإشْراكُ."],[38,38,"﴿بِمَا تُبۡصِرُونَ﴾: مِنَ الأرضِ والجِبالِ والبِحارِ والبَشَرِ والسَّمواتِ ونحوِها."],[39,39,"﴿وَمَا لَا تُبۡصِرُونَ﴾: مِنَ الأرواحِ والملائِكةِ وأُمُورِ الآخِرَةِ."],[40,40,"﴿لَقَوۡلُ رَسُولࣲ كَرِيمࣲ﴾: يَنْطِقُ بِهِ مُحَمَّدٌ ﷺ، والكَلامُ كَلامُ المُرسِلِ سُبْحانَهُ وتَعالى."],[41,41,"﴿قَلِيلࣰا مَّا تُؤۡمِنُونَ﴾: تُؤْمِنُونَ إيمانا قَلِيلا لا يُنْجِيكُم مِن الخُلُود في النّارِ."],[42,42,"﴿قَلِيلࣰا مَّا تَذَكَّرُونَ﴾: تَتَذَكَّرُونَ تَذَكُّرًا قَلِيلًا."],[44,44,"﴿وَلَوۡ تَقَوَّلَ عَلَيۡنَا بَعۡضَ ٱلۡأَقَاوِيلِ﴾: ولَو كَذَبَ عَلَينا بأنّا قُلْنا قَوْلًا لم نَقُلْه."],[45,45,"﴿لَأَخَذۡنَا مِنۡهُ بِٱلۡيَمِينِ﴾: لَأَخَذْناهُ بِقُوَّةٍ وقُدْرَةٍ."],[46,46,"﴿ٱلۡوَتِينَ﴾: هو عِرْقٌ عُلِّقَ به القلبُ ويَسْقِي الجسدَ بالدَّمِ، فإذا قُطِعَ مات صاحِبُه."],[47,47,"﴿عَنۡهُ حَـٰجِزِينَ﴾: يَمنعُونَ مِنهُ عِقابَنا."],[48,48,"﴿لَتَذۡكِرَةࣱ﴾: لَعِظَةٌ."],[50,50,"﴿وَإِنَّهُۥ﴾: أي التَّكْذِيبَ.\n\n﴿لَحَسۡرَةٌ﴾: لَنَدامةٌ عَظِيمَةٌ."],[51,51,"﴿لَحَقُّ ٱلۡيَقِينِ﴾: الخبرُ الصِّدقُ."],[52,52,"﴿فَسَبِّحۡ﴾: فَنَزِّهْ."]]);
QTF("gharib",70,[[1,1,"﴿سَأَلَ سَآئِلُۢ﴾: دَعا داعٍ مِنَ المُشْرِكِينَ على نَفْسِهِ وقَوْمِهِ.\n\n﴿بِعَذَابࣲ﴾: بِنُزُولِ العَذابِ عَلَيهِم.\n\n﴿وَاقِعࣲ﴾: مُتَحَقِّقِ الوُقُوعِ."],[2,2,"﴿دَافِعࣱ﴾: مانِعٌ يَمْنَعُهُ مِنَ اللهِ عَزَّ وجَلَّ."],[3,3,"﴿ذِي ٱلۡمَعَارِجِ﴾: صاحِبِ العُلُوِّ والفَواضِلِ."],[4,4,"﴿تَعۡرُجُ﴾: تَصْعَدُ.\n\n﴿وَٱلرُّوحُ﴾: جِبْرِيلُ.\n\n﴿خَمۡسِينَ أَلۡفَ سَنَةࣲ﴾: أي مِن سَنَواتِ الدُّنيا عَلى الكافِرِ."],[6,6,"﴿يَرَوۡنَهُۥ بَعِيدࣰا﴾: يَرَونَ وقُوعَ العذابِ مُسْتَحِيلًا."],[8,8,"﴿كَٱلۡمُهۡلِ﴾: ما أُذِيب مِنَ النُّحاسِ وغَيرِهِ."],[9,9,"﴿كَٱلۡعِهۡنِ﴾: كالصُّوفِ."],[10,10,"﴿وَلَا يَسۡـَٔلُ حَمِيمٌ حَمِيمࣰا﴾: ولا يَتَفَرَّغُ قَرِيبٌ للسُّؤالِ عَنْ حالِ قَرِيبِهِ مِنَ الهَولِ والشُّغْلِ بِحالِ نَفْسِهِ."],[11,11,"﴿يُبَصَّرُونَهُمۡ﴾: يَرَونَهُم ويَعْرِفُونَهُم، ولا يَسْتَطِيعُ أحَدٌ أن يَنفَعَ أحَدًا.\n\n﴿يَوَدُّ﴾: يَتَمَنّى.\n\n﴿لَوۡ يَفۡتَدِي﴾: لو يُخَلِّصُ نَفْسَهُ بِفِدْيَةٍ."],[13,13,"﴿وَفَصِيلَتِهِ﴾: وعَشِيَرتِهِ.\n\n﴿تُـٔۡوِيهِ﴾: تَضُمُّهُ، ويَنْتَمِي إلَيها في القَرابَةِ."],[14,14,"﴿يُنجِيهِ﴾: يُنجِيهِ الافْتِداءُ مِنَ العَذابِ."],[15,15,"﴿كَلَّآ﴾: لا افْتِداءَ ولا إنْجاءَ."],[19,19,"﴿هَلُوعًا﴾: شَدِيدَ الجَزَعِ والحِرْصِ."],[21,21,"﴿ٱلۡخَيۡرُ﴾: ما يَنفَعُ الإنْسانَ.\n\n﴿مَنُوعًا﴾: كَثِيرَ المنْعِ للخيرِ."],[23,23,"﴿دَآئِمُونَ﴾: مُواظِبُونَ على أدائِها."],[24,24,"﴿حَقࣱّ مَّعۡلُومࣱ﴾: نَصِيبٌ مُعَيَّنٌ لِذَوِي الحاجاتِ."],[25,25,"﴿وَٱلۡمَحۡرُومِ﴾: الَّذِي يَتَعَفَّفُ عَن سُؤالِ النّاسِ مَعَ حاجَتِهِ فَلا يَتَفَطَّن لَهُ كَثِيرٌ مِنَ النّاسِ."],[26,26,"﴿بِيَوۡمِ ٱلدِّينِ﴾: بيومِ الجَزاءِ."],[27,27,"﴿مُّشۡفِقُونَ﴾: خائِفُونَ."],[28,28,"﴿غَيۡرُ مَأۡمُونࣲ﴾: لا يَأمَنُه أحَدٌ مِمَّنْ عَقَلَ عَنِ اللهِ أمْرَهُ إلا بِأَمانٍ مِنَ اللهِ تَبارَكَ وتَعالى."],[29,29,"﴿لِفُرُوجِهِمۡ حَـٰفِظُونَ﴾: يَحْفظُونَ أنْفُسَهُم مِنَ الحَرامِ."],[30,30,"﴿أَوۡ مَا مَلَكَتۡ أَيۡمَـٰنُهُمۡ﴾: النِّساءِ الإماءِ.\n\n﴿غَيۡرُ مَلُومِينَ﴾: غَيرُ مؤاخَذِينَ."],[31,31,"﴿وَرَآءَ ذَ ٰ⁠لِكَ﴾: غَيرَ الزَّوجاتِ والمملُوكاتِ.\n\n﴿ٱلۡعَادُونَ﴾: المُفْسِدُونَ."],[32,32,"﴿لِأَمَـٰنَـٰتِهِمۡ﴾: لأماناتِ اللهِ وأماناتِ النّاسِ الَّتِي اؤْتُمِنُوا عَلَيها.\n\n﴿وَعَهۡدِهِمۡ﴾: عُهُودِهِم مَعَ اللهِ ومَعَ العِبادِ.\n\n﴿رَ ٰ⁠عُونَ﴾: حافِظُونَ."],[33,33,"﴿بِشَهَـٰدَ ٰ⁠تِهِمۡ﴾: بِما عِنْدَهُم مِنَ الدَّلالةِ عَلى حَقِّ لِغَيرِهِم.\n\n﴿قَآئِمُونَ﴾: يَهْتَمُّونَ بِها ويَحْفَظُونَها إلى أن تُؤَدّى."],[34,34,"﴿يُحَافِظُونَ﴾: يعتَنُونَ باسْتِكْمالِ أرْكانِها وشُرُوطِها وأَوْقاتِها."],[35,35,"﴿مُّكۡرَمُونَ﴾: يُكْرَمُونَ بِحُسْنِ اللقاءِ والثَّناءِ وأَنْواعِ اللذّاتِ والمَسارِّ."],[36,36,"﴿فَمَالِ ٱلَّذِينَ كَفَرُواْ﴾: فأيُّ شَيءٍ ثَبَتَ لَهُم؟\n\n﴿قِبَلَكَ﴾: في حالِ كَونِهِم عنِدَك.\n\n﴿مُهۡطِعِينَ﴾: مُسْرِعِينَ، وقَدْ مَدُّوا أعْناقَهُم إليكَ مُقْبِلِينَ عَلَيكَ."],[37,37,"﴿عِزِينَ﴾: مُتَفَرِّقِينَ."],[39,39,"﴿مِّمَّا يَعۡلَمُونَ﴾: مِن مّاءٍ مَهِينٍ كَغَيرِهِم."],[40,40,"﴿ٱلۡمَشَـٰرِقِ﴾: مَشارِقِ الشَّمْسِ والكَواكِبِ.\n\n﴿وَٱلۡمَغَـٰرِبِ﴾: مَغارِبِ الشَّمْسِ والكَواكِبِ."],[41,41,"﴿وَمَا نَحۡنُ بِمَسۡبُوقِينَ﴾: وما أحَدٌ يَفُوتُنا ويُعْجِزُنا."],[42,42,"﴿فَذَرۡهُمۡ﴾: فاتْرُكْهُم.\n\n﴿يَخُوضُواْ﴾: يَتَكلَّمُوا في باطِلِهِم عَلى غَيرِ هُدىً.\n\n﴿وَيَلۡعَبُواْ﴾: في دُنْياهُم."],[43,43,"﴿ٱلۡأَجۡدَاثِ﴾: القُبُورِ.\n\n﴿سِرَاعࣰا﴾: مُسْرِعِينَ.\n\n﴿نُصُبࣲ﴾: أصْنامٍ.\n\n﴿يُوفِضُونَ﴾: يُهَرْوِلُونَ، ويُسْرِعُونَ أيُّهُم يَسْتَلِمُه أوَّلُ؟"],[44,44,"﴿خَـٰشِعَةً﴾: ذَلِيلةً مُنْكَسِرَةً.\n\n﴿تَرۡهَقُهُمۡ﴾: تَغْشاهُم.\n\n﴿ذِلَّةࣱ﴾: حَقارَةٌ ومَهانَةٌ."]]);
QTF("gharib",71,[[1,1,"﴿أَنذِرۡ﴾: حَذِّرْ."],[7,7,"﴿جَعَلُوٓاْ أَصَـٰبِعَهُمۡ فِيٓ ءَاذَانِهِمۡ﴾: أي لِئَلّا يَسْمَعُوا دَعْوةَ الحقِّ.\n\n﴿وَٱسۡتَغۡشَوۡاْ ثِيَابَهُمۡ﴾: تَغَطَّوا بِثيابِهِم عَلى أعْيُنِهِم كَي لا يَرَونِي.\n\n﴿وَأَصَرُّواْ﴾: أي عَلى ما هُم فِيهِ مِنَ الكُفْرِ."],[8,8,"﴿جِهَارࣰا﴾: ظاهِرًا عَلَنًا."],[9,9,"﴿أَعۡلَنتُ لَهُمۡ﴾: كَلامًا ظاهِرًا."],[11,11,"﴿يُرۡسِلِ ٱلسَّمَآءَ﴾: يُنْزِلِ اللهُ المَطَرَ.\n\n﴿مِّدۡرَارࣰا﴾: كَثِيرَ الدَّرِّ والصَّبِّ."],[12,12,"﴿وَيُمۡدِدۡكُم﴾: ويُعْطِكُم."],[13,13,"﴿لَا تَرۡجُونَ لِلَّهِ وَقَارࣰا﴾: لا تَخافُونَ عَظَمَةَ اللهِ وسُلْطانَهُ."],[14,14,"﴿وَقَدۡ خَلَقَكُمۡ أَطۡوَارًا﴾: أطوارًا مُتَدَرِّجَةً: نُطْفَةً ثم عَلَقَةً ثم مُضْغَةً ثم عِظامًا ولحمًا."],[15,15,"﴿طِبَاقࣰا﴾: مُتَطابِقَةً بعضُها فَوقَ بَعْضٍ."],[16,16,"﴿سِرَاجࣰا﴾: مُضِيئًا."],[17,17,"﴿وَٱللَّهُ أَنۢبَتَكُم﴾: أنْشأَ أصْلَكُم.\n\n﴿نَبَاتࣰا﴾: إنْشاءً."],[18,18,"﴿وَيُخۡرِجُكُمۡ﴾: يَومَ البَعْثِ"],[19,19,"﴿بِسَاطࣰا﴾: مُمهَّدةً كالبِساطِ."],[20,20,"﴿سُبُلࣰا﴾: طُرُقًا.\n\n﴿فِجَاجࣰا﴾: واسِعةً."],[22,22,"﴿كُبَّارࣰا﴾: عَظِيمًا."],[23,23,"﴿لَا تَذَرُنَّ ءَالِهَتَكُمۡ﴾: لا تَترُكُوا عِبادةَ آلهتِكُم.\n\n﴿وَلَا تَذَرُنَّ وَدࣰّا وَلَا سُوَاعࣰا وَلَا يَغُوثَ وَيَعُوقَ وَنَسۡرࣰا﴾: ولا تَتْرُكُوا عِبادةَ هَذِهِ الأصْنامِ الَّتِي هي تَماثِيلُ رجالٍ صالِحِينَ."],[24,24,"﴿كَثِيرࣰا﴾: مِنَ النّاسِ.\n\n﴿ٱلظَّـٰلِمِينَ﴾: لِأَنفُسِهِم بالكُفْرِ والعِنادِ.\n\n﴿ضَلَـٰلࣰا﴾: بُعْدًا عَن الحقِّ."],[25,25,"﴿مِّمَّا خَطِيٓـَٔـٰتِهِمۡ﴾: بِسَبَبِ ذُنُوبِهِم وإصْرارِهِم عَلى الكُفْرِ والطُّغْيانِ.\n\n﴿أُغۡرِقُواْ﴾: بالطُّوفانِ.\n\n﴿أَنصَارࣰا﴾: مَن يَنْصُرُهُم، أو يَدْفَعُ عَنْهُم عَذابَ اللهِ."],[26,26,"﴿لَا تَذَرۡ﴾: لا تَتْرُكْ.\n\n﴿دَيَّارًا﴾: أحَدًا حَيًّا عَلى الأرْضِ، يَدُورُ ويَتَحَرَّكُ."],[27,27,"﴿إِن تَذَرۡهُمۡ﴾: إن تَتْرُكْهُم دُونَ إهْلاكٍ.\n\n﴿إِلَّا فَاجِرࣰا﴾: إلا مائِلًا عَنِ الحقِّ.\n\n﴿كَفَّارࣰا﴾: شَدِيدَ الكُفْرِ بِكَ والعِصْيانِ لَك."],[28,28,"﴿تَبَارَۢا﴾: هَلاكًا وخُسْرانًا في الدُّنيا والآخِرَةِ."]]);
QTF("gharib",72,[[1,1,"﴿ٱسۡتَمَعَ﴾: لِتِلاوَتِي لِلْقُرآنِ.\n\n﴿نَفَرࣱ﴾: جَماعَةٌ.\n\n﴿عَجَبࣰا﴾: بَدِيعًا في بَلاغَتِهِ وأَحْكامِهِ."],[2,2,"﴿يَهۡدِيٓ إِلَى ٱلرُّشۡدِ﴾: يَدْعُو إلى الحقِّ."],[3,3,"﴿تَعَـٰلَىٰ﴾: عَلَتْ وارْتَفَعَتْ.\n\n﴿جَدُّ رَبِّنَا﴾: عَظَمَةُ رَبِّنا وجَلالُهُ.\n\n﴿صَـٰحِبَةࣰ﴾: زَوْجةً."],[4,4,"﴿سَفِيهُنَا﴾: إبْلِيسُ.\n\n﴿شَطَطࣰا﴾: قَوْلًا بعِيدًا عَنِ الحقِّ والصَّوابِ."],[6,6,"﴿يَعُوذُونَ﴾: يَسْتَجِيرُونَ ويَلُوذُونَ.\n\n﴿فَزَادُوهُمۡ﴾: فَزادَ رِجالُ الجِنِّ الإنسَ باسْتِعاذَتِهم بِهِم.\n\n﴿رَهَقࣰا﴾: خَوْفًا."],[7,7,"﴿وَأَنَّهُمۡ﴾: وأَنَّ كُفارَ الإنْسِ.\n\n﴿ظَنُّواْ كَمَا ظَنَنتُمۡ﴾: حَسِبُوا كما حَسِبْتُم -يا مَعْشرَ الِجنِّ-.\n\n﴿أَن لَّن يَبۡعَثَ ٱللَّهُ أَحَدࣰا﴾: بَعْدَ الموتِ."],[8,8,"﴿لَمَسۡنَا ٱلسَّمَآءَ﴾: طَلَبْنا بُلُوغَ السَّماءِ لاسْتِماعِ كَلامِ أهْلِها.\n\n﴿حَرَسࣰا شَدِيدࣰا﴾: مَلائِكةً تَحْرُسُها.\n\n﴿وَشُهُبࣰا﴾: جَمْعُ شِهابٍ، وهي النُّجُومُ الَّتِي كانتْ تُرْجَمُ بِها الشَّياطِينُ."],[9,9,"﴿نَقۡعُدُ مِنۡهَا مَقَـٰعِدَ﴾: نَتَّخِذُ مِنَ السَّماءِ مَواضِعَ.\n\n﴿لِلسَّمۡعِ﴾: لِنَسْتَمِعَ إلى أخْبارِها.\n\n﴿فَمَن يَسۡتَمِعِ ٱلۡـَٔانَ﴾: فَمَن يُحاوِلِ الآنَ اسْتِراقَ السَّمْعِ.\n\n﴿شِهَابࣰا﴾: شِهابًا بالمِرْصادِ، يُحْرِقُه ويُهْلِكُهُ."],[10,10,"﴿رَشَدࣰا﴾: خَيرًا وهُدىً."],[11,11,"﴿وَمِنَّا دُونَ ذَ ٰ⁠لِكَ﴾: ومِنّا قَومٌ دُونَ ذَلِكَ كُفّارٌ وفُسّاقٌ.\n\n﴿طَرَآئِقَ﴾: فِرَقًا ومَذاهِبَ.\n\n﴿قِدَدࣰا﴾: مخْتَلِفَةً."],[12,12,"﴿ظَنَنَّآ﴾: أيْقَنّا.\n\n﴿أَن لَّن نُّعۡجِزَ ٱللَّهَ فِي ٱلۡأَرۡضِ﴾: أن لَن نَفُوتَ اللهَ إذا أرادَ بِنا أمْرًا فِي الأَرْضِ.\n\n﴿وَلَن نُّعۡجِزَهُۥ هَرَبࣰا﴾: ولَن نسْتَطِيعَ أن نُفْلِتَ مِن عِقابِهِ هَرَبًا."],[13,13,"﴿ٱلۡهُدَىٰٓ﴾: القُرآنَ.\n\n﴿بَخۡسࣰا﴾: نُقْصانًا مِن حَسَناتِه.\n\n﴿رَهَقࣰا﴾: ظُلمًا يَلْحَقُهُ بِزِيادةٍ في سَيِّئاتِهِ."],[14,14,"﴿ٱلۡمُسۡلِمُونَ﴾: الخاضِعُونَ للهِ بالطّاعةِ.\n\n﴿ٱلۡقَـٰسِطُونَ﴾: الجائِرُونَ العُصاةُ.\n\n﴿أَسۡلَمَ﴾: وخَضَعَ للهِ بالطّاعةِ.\n\n﴿تَحَرَّوۡاْ﴾: قَصَدُوا.\n\n﴿رَشَدࣰا﴾: طَرِيقَ الحقِّ والصَّوابِ."],[15,15,"﴿وَأَمَّا ٱلۡقَـٰسِطُونَ﴾: الجائِرُونَ عَن طَرِيقِ الإسْلامِ.\n\n﴿حَطَبࣰا﴾: وقُودًا."],[16,16,"﴿وَأَلَّوِ ٱسۡتَقَـٰمُواْ عَلَى ٱلطَّرِيقَةِ﴾: لَو سارَ الكُفّارُ مِنَ الإنْسِ والِجنِّ على طَرِيقَةِ الإسْلامِ.\n\n﴿غَدَقࣰا﴾: كَثِيرًا."],[17,17,"﴿لِّنَفۡتِنَهُمۡ فِيهِ﴾: لِنَخْتَبِرَهُم.\n\n﴿ذِكۡرِ رَبِّهِۦ﴾: طاعَةِ رَبِّهِ واسْتِماعِ القُرآنِ، والعَمَلِ بِهِ.\n\n﴿يَسۡلُكۡهُ﴾: يُدْخِلْهُ.\n\n﴿صَعَدࣰا﴾: شَدِيدًا شاقًّا."],[18,18,"﴿وَأَنَّ ٱلۡمَسَـٰجِدَ لِلَّهِ﴾: وأَنَّ المساجِدَ لِعبادَة اللهِ وحْدَهُ.\n\n﴿فَلَا تَدۡعُواْ مَعَ ٱللَّهِ أَحَدࣰا﴾: فلا تَعْبُدُوا فِيها غَيرَهُ."],[19,19,"﴿عَبۡدُ ٱللَّهِ﴾: مُحَمَّدٌ ﷺ.\n\n﴿لِبَدࣰا﴾: جَماعاتٍ مُتَراكِمَةً، بَعْضُها فَوْقَ بَعْضٍ؛ مِن شِدَّةِ ازْدِحامِهِم لِسَماعِ القُرآنِ مِنهُ."],[21,21,"﴿إِنِّي لَآ أَمۡلِكُ لَكُمۡ ضَرࣰّا﴾: لا أقْدِرُ أن أدْفَعَ عَنْكُم ضَرًّا.\n\n﴿وَلَا رَشَدࣰا﴾: ولا أجْلِبُ لَكُم نَفْعًا."],[22,22,"﴿لَن يُجِيرَنِي﴾: لَن يُنْقِذَني مِن عَذابِ اللهِ.\n\n﴿مُلۡتَحَدًا﴾: مَلْجَأً أفِرُّ إلَيهِ مِن عَذابِهِ."],[23,23,"﴿إِلَّا بَلَـٰغࣰا مِّنَ ٱللَّهِ وَرِسَـٰلَـٰتِهِۦ﴾: لَكِنْ أمْلِكُ أنْ أبَلِّغَكُم عَنِ اللهِ ما أمَرَنِي بِتَبْلِيغِهِ لَكُم."],[24,24,"﴿مَا يُوعَدُونَ﴾: ما يَعِدُهُم رَبُّهُم.\n\n﴿نَاصِرࣰا﴾: مُعِينًا.\n\n﴿عَدَدࣰا﴾: جُنْدًا."],[25,25,"﴿إِنۡ أَدۡرِيٓ﴾: ما أعْلَمُ.\n\n﴿مَّا تُوعَدُونَ﴾: ما يَعِدُكُم رَبُّكُم مِنَ العَذابِ وقِيامِ السّاعةِ.\n\n﴿أَمَدًا﴾: مُدَّةً طَوِيلَةً."],[26,26,"﴿ٱلۡغَيۡبِ﴾: ما غابَ عَنِ الأبْصارِ.\n\n﴿فَلَا يُظۡهِرُ﴾: فلا يُطْلِعُ."],[27,27,"﴿إِلَّا مَنِ ٱرۡتَضَىٰ مِن رَّسُولࣲ﴾: إلّا مَن اختارهم اللهُ لِرسالَتِهِ، فَإنَّه يُطْلِعُهُم عَلى بَعْضِ الغَيبِ.\n\n﴿يَسۡلُكُ مِنۢ بَيۡنِ يَدَيۡهِ وَمِنۡ خَلۡفِهِۦ رَصَدࣰا﴾: يُرْسِلُ مِن أمامِ الرَّسُولِ ومِن خَلْفِهِ ملائِكَةً يحفَظُونَهُ مِنَ الِجنِّ؛ لِئلّا يَسْتَرِقُوهُ ويَهْمِسُوا بِهِ إلى الكَهَنَةِ."],[28,28,"﴿وَأَحَاطَ بِمَا لَدَيۡهِمۡ﴾: وعَلِمَ اللهُ بِكُلِّ ما عَنْدَهُم.\n\n﴿وَأَحۡصَىٰ كُلَّ شَيۡءٍ عَدَدَۢا﴾: عَلِمَ اللهُ عَدَدَ الأَشْياءِ كُلِّها."]]);
QTF("gharib",73,[[1,1,"﴿ٱلۡمُزَّمِّلُ﴾: المتَغَطِّي بِثِيابِهِ."],[2,2,"﴿قُمِ ٱلَّيۡلَ﴾: قُمْ لِلصَّلاةِ في الليلِ.\n\n﴿إِلَّا قَلِيلࣰا﴾: إلا يسِيرًا مِنهُ."],[3,3,"﴿نِّصۡفَهُۥٓ﴾: قُمْ نِصْفَ الليلِ.\n\n﴿أَوِ ٱنقُصۡ مِنۡهُ قَلِيلًا﴾: أوِ انْقُصْ مِنَ النِّصْفِ قَلِيلا حتّى تَصِلَ إلى الثُلُثِّ."],[4,4,"﴿أَوۡ زِدۡ عَلَيۡهِ﴾: أوْ زِدْ عَلى النِّصْفِ حتّى تَصِلَ إلى الثُلُثَينِ.\n\n﴿وَرَتِّلِ ٱلۡقُرۡءَانَ تَرۡتِيلًا﴾: واقْرَأ القُرآنَ بتُؤَدَةٍ مُبَيِّنًا الحُرُوفَ والوُقُوفَ."],[5,5,"﴿سَنُلۡقِي عَلَيۡكَ﴾: سَنُنْزِلُ عَلَيكَ -أيُّها النَّبِيُّ-.\n\n﴿قَوۡلࣰا ثَقِيلًا﴾: قُرآنًا عَظِيمًا مُشْتَمِلًا عَلى الأَوامِرِ والنَّواهِي والأَحْكامِ الشَّرعِيَّةِ."],[6,6,"﴿نَاشِئَةَ ٱلَّيۡلِ﴾: العِبادةَ الَّتِي تَنْشَأُ في جَوْفِ الليلِ.\n\n﴿أَشَدُّ وَطۡـࣰٔا﴾: أشَدُّ تأثِيرًا في القَلْبِ.\n\n﴿وَأَقۡوَمُ قِيلًا﴾: وأَبْيَنُ قَوْلًا لِفَراغِ القَلْبِ مِن مَّشاغِل الدُّنيا."],[7,7,"﴿سَبۡحࣰا طَوِيلࣰا﴾: تَصَرُّفًا في مَصالِحِكَ، واشْتِغالًا بالرِّسالَةِ."],[8,8,"﴿وَتَبَتَّلۡ إِلَيۡهِ تَبۡتِيلࣰا﴾: وانْقَطِعْ إلَيهِ انْقِطاعًا تامًّا في عِبادَتِكَ."],[9,9,"﴿فَٱتَّخِذۡهُ وَكِيلࣰا﴾: فاعْتَمِدْ عَلَيهِ، وفَوِّضْ أُمُورَكَ إلَيه."],[10,10,"﴿وَٱهۡجُرۡهُمۡ هَجۡرࣰا جَمِيلࣰا﴾: وأعْرِضْ عَنْهُم، واتْرُكِ الانْتِقامَ مِنهُم."],[11,11,"﴿وَذَرۡنِي وَٱلۡمُكَذِّبِينَ﴾: دَعْنِي -أيُّها الرَّسُولُ- وهَؤُلاءِ المكَذِّبِينَ بآياتي.\n\n﴿أُوْلِي ٱلنَّعۡمَةِ﴾: أصْحابَ النَّعِيمِ والتَّرَفِ في الدُّنيا.\n\n﴿وَمَهِّلۡهُمۡ قَلِيلًا﴾: وأَخِّرْهُم زَمَنًا قَلِيلًا حتّى يَبْلُغَ الكِتابُ أجَلَه بِعَذابِهِم."],[12,12,"﴿إِنَّ لَدَيۡنَآ﴾: أي في الآخِرَةِ.\n\n﴿أَنكَالࣰا﴾: قُيُودًا ثَقِيلَةً.\n\n﴿وَجَحِيمࣰا﴾: ونارًا مُسْتَعِرَةً."],[13,13,"﴿وَطَعَامࣰا ذَا غُصَّةࣲ﴾: وطَعامًا كَرِيهًا ينشَبُ في الحُلُوقِ غَيَر مُسْتَساغٍ."],[14,14,"﴿تَرۡجُفُ﴾: تَضْطَرِبُ وتَتَزَلْزَلُ.\n\n﴿كَثِيبࣰا﴾: تَلًّا مِنَ الرَّملِ.\n\n﴿مَّهِيلًا﴾: سائِلًا مُنْهالًا مُتَناثِرًا."],[15,15,"﴿شَـٰهِدًا عَلَيۡكُمۡ﴾: بِما صَدَرَ مِنكُم مِنَ الكُفْرِ والعِصْيانِ."],[16,16,"﴿فَعَصَىٰ فِرۡعَوۡنُ ٱلرَّسُولَ﴾: فَكذَّبَ فِرْعَونُ بِمُوسى، ولَمْ يُؤْمِن بِرِسالَتِهِ.\n\n﴿فَأَخَذۡنَـٰهُ﴾: فَأَهْلكْناهُ.\n\n﴿وَبِيلࣰا﴾: شَدِيدًا."],[17,17,"﴿فَكَيۡفَ تَتَّقُونَ﴾: فَكَيفَ تَقُونَ أنْفُسَكُم عذابَ يومِ القِيامَة.\n\n﴿يَجۡعَلُ ٱلۡوِلۡدَ ٰ⁠نَ شِيبًا﴾: يَشِيبُ فِيهِ الوِلْدانُ الصِّغارُ؛ مِن شِدَّةِ هَوْلِه وكَرْبِهِ؟"],[18,18,"﴿ٱلسَّمَآءُ مُنفَطِرُۢ بِهِۦ﴾: السَّماءُ مُتَصَدِّعَةٌ في ذَلِكَ اليَوْمِ؛ لِشِدَّةِ هَوْلِهِ.\n\n﴿بِهِۦ﴾: أي: باللهِ، وهو نَظِيرُ قَوْلِهِ تَعالى:\n\n﴿وَيَوۡمَ تَشَقَّقُ ٱلسَّمَآءُ بِٱلۡغَمَـٰمِ﴾:.\n\n﴿مَفۡعُولًا﴾: واقِعًا لا مَحالَةَ."],[19,19,"﴿تَذۡكِرَةࣱ﴾: عِظَةٌ وعِبْرَةٌ للنّاسِ.\n\n﴿ٱتَّخَذَ إِلَىٰ رَبِّهِۦ سَبِيلًا﴾: اتَّخَذَ الطّاعةَ والتَّقْوى طَرِيقًا تُوصِلُه إلى رِضْوانِ رَبِهِ."],[20,20,"﴿تَقُومُ﴾: للتَّهجُّدِ مِنَ الليلِ.\n\n﴿أَدۡنَىٰ مِن ثُلُثَيِ﴾: أقَلَّ مِن ثُلُثِي الليلِ حِينًا.\n\n﴿وَنِصۡفَهُۥ﴾: وتَقُومُ نِصْفَ الليلِ حِينًا.\n\n﴿وَثُلُثَهُۥ﴾: وتَقُومُ ثُلُثَ الليلِ حِينًا آخرَ.\n\n﴿وَطَآئِفَةࣱ مِّنَ ٱلَّذِينَ مَعَكَ﴾: ويَقُومُ مَعَكَ طائِفَةٌ مِن أصْحابِكَ.\n\n﴿وَٱللَّهُ يُقَدِّرُ ٱلَّيۡلَ وَٱلنَّهَارَ﴾: يَعْلَمُ مَقادِيرَهُما.\n\n﴿تُحۡصُوهُ﴾: تُطيقُوا قيامَه كُلَّه.\n\n﴿فَتَابَ عَلَيۡكُمۡ﴾: فَخَفَّفَ عَلَيكُم.\n\n﴿فَٱقۡرَءُواْ مَا تَيَسَّرَ مِنَ ٱلۡقُرۡءَانِ﴾: في الصَّلاةِ بالليلِ.\n\n﴿وَءَاخَرُونَ يَضۡرِبُونَ فِي ٱلۡأَرۡضِ﴾: يَتَنَقَّلُونَ في الأرضِ للتِّجارَةِ والعَمَلِ.\n\n﴿يَبۡتَغُونَ مِن فَضۡلِ ٱللَّهِ﴾: يَطْلُبُونَ مِن رِّزْقِ اللهِ الحلالِ.\n\n﴿وَأَقۡرِضُواْ ٱللَّهَ قَرۡضًا حَسَنࣰا﴾: وتَصَدَّقُوا في وُجُوهِ البِرِّ والإحْسانِ مِن أمْوالِكُم.\n\n﴿وَمَا تُقَدِّمُواْ لِأَنفُسِكُم مِّنۡ خَيۡرࣲ﴾: وما تَفْعَلُوا مِن وُجُوهِ البِرِّ.\n\n﴿وَأَعۡظَمَ أَجۡرࣰا﴾: وأَعْظَمَ مِنهُ ثَوابًا."]]);
QTF("gharib",74,[[1,1,"﴿ٱلۡمُدَّثِّرُ﴾: المتَغَطِّي بِثِيابِهِ."],[2,2,"﴿قُمۡ﴾: أي مِن مَّضْجَعِكَ.\n\n﴿فَأَنذِرۡ﴾: فَحَذِّر النّاس مِن عَذابِ اللهِ."],[3,3,"﴿وَرَبَّكَ فَكَبِّرۡ﴾: وخُصَّ رَبَّكَ وحْدَهُ بالتَّعْظِيمِ والعِبادَةِ."],[4,4,"﴿وَثِيَابَكَ فَطَهِّرۡ﴾: أي مِنَ النَّجاساتِ."],[5,5,"﴿وَٱلرُّجۡزَ فَٱهۡجُرۡ﴾: ودُمْ على هَجْر أعْمالِ الشِّرْكِ كُلِّها."],[6,6,"﴿وَلَا تَمۡنُن تَسۡتَكۡثِرُ﴾: ولا تُعْطِ العَطِيَّةَ؛ كَي تَلْتَمِسَ أكْثَرَ مِنها."],[7,7,"﴿وَلِرَبِّكَ فَٱصۡبِرۡ﴾: ولِمَرْضاةِ رَبِّكَ فاصْبِرْ عَلى الأَوامِرِ والنَّواهِي."],[8,8,"﴿نُقِرَ﴾: نُفِخَ نَفْخَةَ البعثِ والنُّشُورِ.\n\n﴿ٱلنَّاقُورِ﴾: القَرْنِ الَّذِي يُنْفَخُ فِيهِ."],[11,11,"﴿ذَرۡنِي وَمَنۡ خَلَقۡتُ وَحِيدࣰا﴾: دَعْنِي -أيُّها الرَّسُولُ- أنا والَّذِي خَلَقْتُه في بَطْنِ أُمِّهِ وحِيدًا لا مالَ لَهُ ولا ولدَ."],[12,12,"﴿مَّمۡدُودࣰا﴾: مبسُوطًا واسِعًا."],[13,13,"﴿شُهُودࣰا﴾: حاضِرِينَ مَعَهُ في «مكَّةَ» لا يغِيبُونَ عَنْهُ."],[14,14,"﴿وَمَهَّدتُّ لَهُۥ﴾: ويَسَّرتُ لَهُ سُبُلَ العيشِ."],[15,15,"﴿أَنۡ أَزِيدَ﴾: أي في مالِهِ ووَلَدِهِ."],[16,16,"﴿كَلَّآ﴾: ليس الأمرُ كما يَزْعُمُ.\n\n﴿لِـَٔايَـٰتِنَا﴾: للقرآنِ.\n\n﴿عَنِيدࣰا﴾: معانِدًا مُكَذِّبًا."],[17,17,"﴿سَأُرۡهِقُهُۥ﴾: سَأُكَلِّفُه.\n\n﴿صَعُودًا﴾: مَشَقَّةً مِنَ العذابِ."],[18,18,"﴿فَكَّرَ﴾: في نَفْسِهِ.\n\n﴿وَقَدَّرَ﴾: وهَيَّأ ما يقُولُه مِنَ الطَّعنِ في مُحَمَّدٍ ﷺ والقرآنِ."],[19,19,"﴿فَقُتِلَ﴾: فَلُعِنَ، واسْتَحَقَّ بِذَلِكَ الهَلاكَ.\n\n﴿كَيۡفَ قَدَّرَ﴾: كَيفَ أعَدَّ في نفسهِ هَذا الطَّعْنَ."],[21,21,"﴿نَظَرَ﴾: تَأَمَّلَ فيما قَدَّرَ وهَيَّأَ مِنَ الطَّعْنِ في القرآنِ."],[22,22,"﴿عَبَسَ﴾: قَطَّبَ وجْهَهُ.\n\n﴿وَبَسَرَ﴾: واشْتَدَّ في العُبُوسِ."],[23,23,"﴿أَدۡبَرَ﴾: رَجَعَ مُعْرِضًا عَنِ الحقِّ.\n\n﴿وَٱسۡتَكۡبَرَ﴾: وتَعاظَمَ أن يَعْتَرِفَ بِهِ."],[24,24,"﴿إِنۡ هَـٰذَآ﴾: ما الَّذِي يَقُولُه مُحَمَّدٌ.\n\n﴿يُؤۡثَرُ﴾: يُنْقلُ عَنِ الأوّلِينَ."],[25,25,"﴿قَوۡلُ ٱلۡبَشَرِ﴾: كلامُ المخلُوقيِنَ، تَعَلَّمَهُ مُحَمَّدٌ مِنهُم، ثُمَّ ادَّعى أنَّهُ مِن عندِ اللهِ."],[26,26,"﴿سَأُصۡلِيهِ﴾: سَأُدْخِلُهُ.\n\n﴿سَقَرَ﴾: جَهَنَّمَ."],[27,27,"﴿وَمَآ أَدۡرَىٰكَ﴾: وما أعلَمَكَ.\n\n﴿مَا سَقَرُ﴾: أيُّ شَيءٍ جَهَنَّمُ؟"],[28,28,"﴿لَا تُبۡقِي﴾: لا تَتْرُكُ مِن أجْزاءِ المُعَذَّبِينَ شَيئًا.\n\n﴿وَلَا تَذَرُ﴾: ولا تَتْرُكُ مَن فيها مَيِّتًا، ولَكِنَّها تُحْرِقُهُم كُلَّما جُدِّدَ خَلْقُهُم."],[29,29,"﴿لَوَّاحَةࣱ﴾: حَرّاقَةٌ، مُغيِّرةٌ، مُسَوِّدةٌ.\n\n﴿لِّلۡبَشَرِ﴾: للجُلودِ، مُفْردُها: بَشَرةٌ."],[30,30,"﴿عَلَيۡهَا﴾: يَلِي أمَر جَهَنَّمَ ويَتَسَلَّطُ على أهْلِها بالعَذابِ.\n\n﴿تِسۡعَةَ عَشَرَ﴾: مَلَكًا مِنَ الزَّبانِيَةِ الأَشِداءِ."],[31,31,"﴿أَصۡحَـٰبَ ٱلنَّارِ﴾: خَزَنَةَ النّارِ.\n\n﴿عِدَّتَهُمۡ﴾: ذِكْرَ عَدَدِهِم.\n\n﴿فِتۡنَةࣰ﴾: اخْتِبارًا.\n\n﴿لِيَسۡتَيۡقِنَ﴾: وليَحْصُلَ اليقِينُ.\n\n﴿ٱلَّذِينَ أُوتُواْ ٱلۡكِتَـٰبَ﴾: اليهُودُ والنَّصارى.\n\n﴿وَلَا يَرۡتَابَ﴾: ولا يَشُكَّ.\n\n﴿مَّرَضࣱ﴾: نِفاقٌ.\n\n﴿مَاذَآ أَرَادَ ٱللَّهُ بِهَـٰذَا مَثَلࣰا﴾: ما الَّذِي أرادَهُ اللهُ بِهذا العَدَدِ؟\n\n﴿كَذَ ٰ⁠لِكَ﴾: بِمِثْلِ ذَلِكَ الَّذِي ذُكِرَ.\n\n﴿جُنُودَ رَبِّكَ﴾: عَدَدَهُم.\n\n﴿هِيَ﴾: النّارُ.\n\n﴿ذِكۡرَىٰ﴾: تَذْكِرَةٌ ومَوْعِظَةٌ."],[32,32,"﴿كَلَّا﴾: ليسَ الأمرُ كَما ذَكَرُوا."],[33,33,"﴿إِذۡ أَدۡبَرَ﴾: حِينَ ولّى وذَهَبَ."],[34,34,"﴿أَسۡفَرَ﴾: أضاءَ."],[35,35,"﴿إِنَّهَا﴾: إنَّ النّارَ.\n\n﴿ٱلۡكُبَرِ﴾: العَظائِمِ."],[36,36,"﴿نَذِيرࣰا﴾: إنْذارًا وتَخْوِيفًا."],[37,37,"﴿يَتَقَدَّمَ﴾: يَتَقَرَّبَ إلى رَبِّهِ بِفِعْلِ الطّاعاتِ.\n\n﴿أَوۡ يَتَأَخَّرَ﴾: بِفِعْلِ المعاصِي."],[38,38,"﴿بِمَا كَسَبَتۡ﴾: مِن أعْمالِ الخيرِ والشَّرِ.\n\n﴿رَهِينَةٌ﴾: مَحْبُوسَةٌ مَرْهُوَنةٌ بِكَسْبِها."],[39,39,"﴿إِلَّآ أَصۡحَـٰبَ ٱلۡيَمِينِ﴾: وهم المسْلِمُونَ المخلِصُونَ."],[40,40,"﴿يَتَسَآءَلُونَ﴾: يَسْأَلُ بَعْضُهُم بَعْضًا."],[41,41,"﴿عَنِ ٱلۡمُجۡرِمِينَ﴾: عَنِ الكافِرِينَ الَّذينَ أجْرمُوا في حَقِّ أنْفُسِهِم."],[42,42,"﴿مَا سَلَكَكُمۡ﴾: ما الَّذِي أدْخَلَكُم.\n\n﴿سَقَرَ﴾: جَهَنَّمَ."],[45,45,"﴿نَخُوضُ﴾: نَتَحَدَّثُ بالباطِلِ.\n\n﴿مَعَ ٱلۡخَآئِضِينَ﴾: مَعَ أهْلِ الضَّلالةِ."],[48,48,"﴿شَفَـٰعَةُ﴾: طَلَبُ قَضاءِ حاجَةِ المشْفُوعِ لَهُ عِنْدَ المَشْفُوعِ عنْدَهُ.\n\n﴿ٱلشَّـٰفِعِينَ﴾: الملائِكَةِ والنَّبِيِّينَ وغَيرِهِم."],[49,49,"﴿فَمَا لَهُمۡ﴾: فما لِهؤُلاءِ المشْرِكِينَ.\n\n﴿عَنِ ٱلتَّذۡكِرَةِ﴾: عَنِ القُرآنِ وما فِيهِ مِنَ المواعِظِ.\n\n﴿مُعۡرِضِينَ﴾: مُنْصَرِفِينَ."],[50,50,"﴿حُمُرࣱ﴾: حُمُرٌ وحْشِيِّةٌ.\n\n﴿مُّسۡتَنفِرَةࣱ﴾: شَدِيَدُة النِّفارِ."],[51,51,"﴿قَسۡوَرَةِۭ﴾: أسَدٍ كاسِرٍ."],[52,52,"﴿صُحُفࣰا﴾: كُتُبًا.\n\n﴿مُّنَشَّرَةࣰ﴾: مَفْتُوحَةً مَقْرُوءَةً."],[53,53,"﴿كَلَّا﴾: ليسَ الأمرُ كَما زَعَمُوا.\n\n﴿لَّا يَخَافُونَ ٱلۡـَٔاخِرَةَ﴾: لا يُصَدِّقُونَ بالبَعْثِ والجزاءِ."],[54,54,"﴿كَلَّآ﴾: حَقًّا.\n\n﴿إِنَّهُۥ﴾: إنَّ القُرآنَ.\n\n﴿تَذۡكِرَةࣱ﴾: مَوْعِظَةٌ بَلِيغَةٌ كافِيَةٌ لاتِّعاظِهِم."],[55,55,"﴿ذَكَرَهُۥ﴾: اتَّعظَ بِما فِيهِ وانْتَفَعَ بِهُداهُ."],[56,56,"﴿وَمَا يَذۡكُرُونَ﴾: وما يَتَّعِظُونَ بِه.\n\n﴿أَهۡلُ ٱلتَّقۡوَىٰ﴾: المسْتَحِقُّ لِأَن يُتَّقى ويُطاعَ.\n\n﴿وَأَهۡلُ ٱلۡمَغۡفِرَةِ﴾: والجديرُ بأن يَغْفِرَ لِمَن آمنَ بِهِ وأطاعَهُ."]]);
QTF("gharib",75,[[1,1,"﴿لَآ أُقۡسِمُ﴾: أحْلِفُ."],[2,2,"﴿وَلَآ أُقۡسِمُ﴾: وأحْلِفُ.\n\n﴿بِٱلنَّفۡسِ ٱللَّوَّامَةِ﴾: بالأنْفُسِ الَّتِي تَلُومُ صاحِبَها على تَرْكِ الطّاعاتِ وفِعْلِ السَّيئاتِ."],[3,3,"﴿أَيَحۡسَبُ﴾: أيَظُنُّ.\n\n﴿أَلَّن نَّجۡمَعَ عِظَامَهُۥ﴾: أن لَن نَّقَدِرَ على جَمْعِ عِظامِهِ بَعْدَ تَفَرُّقِها."],[4,4,"﴿بَلَىٰ﴾: بَلْ سَنَجْمَعُها.\n\n﴿أَن نُّسَوِّيَ بَنَانَهُۥ﴾: نُعيدَ خَلْقَ أصابِعِه أو أنامِلِه مُقَوَّمةً مُتْقَنةً."],[5,5,"﴿لِيَفۡجُرَ﴾: لِيَبْقى على فجُورِهِ.\n\n﴿أَمَامَهُۥ﴾: فِيما يَسْتَقْبِلُ مِن أيامِ عُمُرِهِ."],[6,6,"﴿أَيَّانَ﴾: مَتى."],[7,7,"﴿بَرِقَ ٱلۡبَصَرُ﴾: تَحَيَّر البَصَرُ ودُهِشَ فَزِعًا مما رَأى مِن أهْوالِ يَومِ القِيامَةِ."],[8,8,"﴿وَخَسَفَ ٱلۡقَمَرُ﴾: وذَهبَ نُورُ القَمَرِ."],[9,9,"﴿وَجُمِعَ ٱلشَّمۡسُ وَٱلۡقَمَرُ﴾: في ذَهابِ ضَوْئِهِما."],[11,11,"﴿كَلَّا﴾: ليسَ الأمرُ كَما تَتَمَنّاهُ.\n\n﴿لَا وَزَرَ﴾: لا مَلْجأَ لَكَ ولا مَنجى."],[12,12,"﴿ٱلۡمُسۡتَقَرُّ﴾: مَصِيرُ الخلائِقِ يومَ القِيامةِ."],[13,13,"﴿بِمَا قَدَّمَ وَأَخَّرَ﴾: بِجَمِيعِ أعْمالِهِ: مِن خَيرٍ وشَرٍّ، ما قدَّمَهُ مِنها في حياتِهِ وما أخَّرَهُ."],[14,14,"﴿عَلَىٰ نَفۡسِهِۦ بَصِيرَةࣱ﴾: بَصِيرٌ بِنَفْسِهِ، يعلَمُ اسْتِحْقاقَهُ لِلْعِقابِ."],[15,15,"﴿وَلَوۡ أَلۡقَىٰ مَعَاذِيرَهُۥ﴾: حتّى في حِينِ إخْبارِه باعْتِذاراتِهِ الكاذِبةِ."],[16,16,"﴿لَا تُحَرِّكۡ بِهِۦ لِسَانَكَ لِتَعۡجَلَ بِهِۦٓ﴾: لا تُحَرِّكْ –أيُّها النَّبِيُّ- بالقُرآنِ لِسانَكَ حتّى نُزُولِ الوحْيِ؛ لِأَجْلِ أن تَتَعَجَّلَ بِحِفْظِهِ، مخافَةَ أن يَتَفَلَّتَ مِنكَ."],[17,17,"﴿جَمۡعَهُۥ﴾: في صَدرِكَ.\n\n﴿وَقُرۡءَانَهُۥ﴾: أن تَقْرَأَهُ بِلِسانِكَ مَتى شِئْتَ."],[18,18,"﴿فَإِذَا قَرَأۡنَـٰهُ﴾: فَإذا قَرَأَهُ عَلَيكَ رَسُولُنا جِبْرِيلُ.\n\n﴿فَٱتَّبِعۡ قُرۡءَانَهُۥ﴾: فاسْتمِعْ لِقِراءتِه وأَنْصِتْ لَهُ، ثُمُّ اقْرَأْهُ كَما أقْرَأَكَ إيّاهُ."],[19,19,"﴿بَيَانَهُۥ﴾: تَوْضِيحَ ما أشْكَلَ عَلَيكَ فَهْمُهُ مِن مَّعانِيهِ وأَحْكامِهِ."],[20,20,"﴿كَلَّا﴾: ليسَ الأمرُ كَما زَعَمْتُم أن لّا بَعْثَ ولا جَزاءَ.\n\n﴿ٱلۡعَاجِلَةَ﴾: الدُّنيا وزِينَتَها."],[22,22,"﴿وُجُوهࣱ﴾: وُجُوهُ أهْلِ السَّعادةِ.\n\n﴿يَوۡمَئِذࣲ﴾: يومَ القيامةِ.\n\n﴿نَّاضِرَةٌ﴾: مُشْرِقَةٌ مُتَأَلِّقَةٌ."],[23,23,"﴿إِلَىٰ رَبِّهَا نَاظِرَةࣱ﴾: تَنْظُرُ إلى خالِقِها فَتَتَمَتَّعُ بِذَلِكَ."],[24,24,"﴿وَوُجُوهࣱ﴾: ووُجُوهُ الأشْقِياءِ.\n\n﴿يَوۡمَئِذِۭ﴾: يَومَ القِيامَةِ.\n\n﴿بَاسِرَةࣱ﴾: عابِسَةٌ كالِحَةٌ."],[25,25,"﴿تَظُنُّ﴾: تَتَوقَّعُ.\n\n﴿فَاقِرَةࣱ﴾: مُصِيَبةٌ عَظِيمَةٌ."],[26,26,"﴿كَلَّآ﴾: حَقًّا.\n\n﴿بَلَغَتِ ٱلتَّرَاقِيَ﴾: وصَلَتْ الرُّوحُ إلى الحُلْقُومِ."],[27,27,"﴿وَقِيلَ﴾: وقالَ بَعْضُ الحاضِرِينَ لِبَعْضٍ.\n\n﴿مَنۡۜ رَاقࣲ﴾: هَل مِن راقٍ يَرْقِيهِ ويَشْفيهِ؟"],[28,28,"﴿وَظَنَّ﴾: وأَيقَنَ المُحْتَضِرُ.\n\n﴿أَنَّهُ﴾: الأمرَ الَّذِي نَزَلَ بِهِ.\n\n﴿ٱلۡفِرَاقُ﴾: فراقُ الدُّنيا؛ لِمُعايَنَتِهِ مَلائِكَةَ الموْتِ."],[29,29,"﴿وَٱلۡتَفَّتِ ٱلسَّاقُ بِٱلسَّاقِ﴾: واتَّصَلَتْ شِدَّةُ آخِر الدُّنيا بِشِدَّةِ أوّلِ الآخِرَةِ."],[30,30,"﴿ٱلۡمَسَاقُ﴾: المرْجِعُ."],[31,31,"﴿فَلَا صَدَّقَ﴾: فلا آمنَ الكافِرُ بالرَّسُولِ ﷺ والقرآنِ."],[32,32,"﴿كَذَّبَ﴾: بالقرآنِ.\n\n﴿وَتَوَلَّىٰ﴾: وأَعْرَضَ عَنِ الإيمانِ."],[33,33,"﴿يَتَمَطَّىٰٓ﴾: يَتَبَخْتَرُ مُخْتالًا في مِشْيتِهِ."],[34,34,"﴿أَوۡلَىٰ لَكَ﴾: هَلاكٌ لَكَ.\n\n﴿فَأَوۡلَىٰ﴾: فَهَلاكٌ."],[36,36,"﴿ٱلۡإِنسَـٰنُ﴾: هو المُنْكِرُ لِلْبَعثِ.\n\n﴿سُدًى﴾: هَمَلًا لا يُحاسَبُ؟"],[37,37,"﴿نُطۡفَةࣰ﴾: ماءً قَلِيلًا.\n\n﴿مَّنِيࣲّ﴾: ماءِ الرَّجُلِ.\n\n﴿يُمۡنَىٰ﴾: يُراقُ ويُصَبُّ في الأرحامِ."],[38,38,"﴿عَلَقَةࣰ﴾: قِطْعَةً مِن دمٍ جامِدٍ.\n\n﴿فَسَوَّىٰ﴾: فعَدَّلَ صُورَتَهُ وقَوَّمَها في أحْسَنِ تَقْوِيمٍ."],[39,39,"﴿ٱلزَّوۡجَيۡنِ﴾: الصِّنْفَينِ."],[40,40,"﴿يُحۡـِۧيَ ٱلۡمَوۡتَىٰ﴾: يُعيدُ الخلْقَ بَعْدَ فَنائِهِم."]]);
QTF("gharib",76,[[1,1,"﴿هَلۡ أَتَىٰ﴾: قَدْ مَضى.\n\n﴿حِينࣱ مِّنَ ٱلدَّهۡرِ﴾: وقْتٌ طويلٌ مِنَ الزَّمانِ قَبلَ أن تُنفَخَ فيه الُّروحُ.\n\n﴿لَمۡ يَكُن شَيۡـࣰٔا مَّذۡكُورًا﴾: لمَ يكُنْ شَيئًا يُذكرُ."],[2,2,"﴿نُّطۡفَةٍ أَمۡشَاجࣲ﴾: مِن نُّطْفَةٍ مُخْتَلِطَةٍ مِن مّاءِ الرَّجُلِ وماءِ المرأةِ.\n\n﴿نَّبۡتَلِيهِ﴾: أي بتكاليفِ الشَّريعةِ."],[3,3,"﴿هَدَيۡنَـٰهُ﴾: بيَّنّا له.\n\n﴿ٱلسَّبِيلَ﴾: طَرِيقَ الهُدى والضَّلالِ.\n\n﴿كَفُورًا﴾: جاحِدًا."],[4,4,"﴿أَعۡتَدۡنَا﴾: أعْدَدْنا.\n\n﴿سَلَـٰسِلَاْ﴾: حِلَقًا غَلِيظَةً مِن حَدِيدٍ تُشَدُّ بِها أرْجُلُهُم.\n\n﴿وَأَغۡلَـٰلࣰا﴾: قُيُودًا تُغَلُّ بِها أيْدِيهِم.\n\n﴿وَسَعِيرًا﴾: ونارًا يُحرَقُونَ بِها."],[5,5,"﴿ٱلۡأَبۡرَارَ﴾: أهْلَ الطّاعةِ والإخلاصِ الَّذِينَ يُؤَدّونَ حقَّ اللهِ.\n\n﴿كَأۡسࣲ﴾: إناءٍ للخَمْرِ.\n\n﴿مِزَاجُهَا﴾: ما خُلِطَ بالخمْرِ لِتَخْفِيفِ حِدَّتِهِ.\n\n﴿كَافُورًا﴾: أحْسَنَ أنْواعِ الطِّيبِ."],[6,6,"﴿يَشۡرَبُ بِهَا﴾: يَشْرَبُ مِنها.\n\n﴿عِبَادُ ٱللَّهِ﴾: هم الأبرارُ.\n\n﴿يُفَجِّرُونَهَا﴾: يَسْتَقُونَ مِنها حيثُ شاؤُوا.\n\n﴿تَفۡجِيرࣰا﴾: إجراءً سَهْلا."],[7,7,"﴿يُوفُونَ﴾: يُؤَدُّونَ وافيًا دُونَ نَقْصٍ ولا تَقْصِيرٍ.\n\n﴿بِٱلنَّذۡرِ﴾: ما أوْجَبُوهُ على أنْفُسِهِم مِن فِعْلِ الخيرِ المُتَقرَّبِ بِهِ إلى اللهِ.\n\n﴿وَيَخَافُونَ يَوۡمࣰا﴾: ويخافُونَ عِقابَ اللهِ يومَ القِيامةِ.\n\n﴿مُسۡتَطِيرࣰا﴾: مُنْتَشِرًا."],[8,8,"﴿عَلَىٰ حُبِّهِۦ﴾: مَعَ حُبِّهِم لَهُ وحاجَتِهِم إلَيهِ.\n\n﴿مِسۡكِينࣰا﴾: مُحْتاجًا.\n\n﴿وَيَتِيمࣰا﴾: وطِفْلًا ماتَ أبُوهُ ولا مالَ لَهُ.\n\n﴿وَأَسِيرًا﴾: الَّذِي تَمَّ أسْرُهُ في الحرْبِ."],[9,9,"﴿لِوَجۡهِ ٱللَّهِ﴾: اْبتِغاءَ مَرْضاةِ اللهِ.\n\n﴿جَزَآءࣰ﴾: عِوَضًا."],[10,10,"﴿عَبُوسࣰا﴾: تَكْلَحُ فِيهِ الوُجُوهُ.\n\n﴿قَمۡطَرِيرࣰا﴾: تَتَقَطَّبُ الجِباهُ مِن فَظاعَةِ أمْرِهِ."],[11,11,"﴿وَلَقَّىٰهُمۡ﴾: جَعَلَهُم يَلْقَونَ.\n\n﴿نَضۡرَةࣰ﴾: نُورًا في وُجُوهِهِم."],[13,13,"﴿مُّتَّكِـِٔينَ﴾: جالِسِينَ على وجْهِ التَّمَكُّنِ والرّاحَةِ.\n\n﴿ٱلۡأَرَآئِكِ﴾: الأَسِرَّةِ المزيَّنَةِ بفاخرِ الثِّيابِ والسُّتُورِ.\n\n﴿شَمۡسࣰا﴾: حرَّ شَمْسٍ؛ لِعَدَمِ وُجُودِها.\n\n﴿زَمۡهَرِيرࣰا﴾: شِدّةَ بَرْدٍ."],[14,14,"﴿وَدَانِيَةً عَلَيۡهِمۡ﴾: وقَريبةً مِنهُم.\n\n﴿ظِلَـٰلُهَا﴾: أشْجارُ الجنَّةِ مُظَلَّلَةٌ عَليهِم.\n\n﴿وَذُلِّلَتۡ﴾: وسُهِّلَ لَهُم.\n\n﴿قُطُوفُهَا﴾: أخْذُ ثِمارِها."],[15,15,"﴿وَيُطَافُ عَلَيۡهِم﴾: ويَدُورُ عَلَيهِم الَخَدمُ.\n\n﴿بِـَٔانِيَةࣲ مِّن فِضَّةࣲ﴾: بأواني الطَّعامِ وأَوْعِيَتِهِ الفِضِّيَّةِ.\n\n﴿قَوَارِيرَا۠﴾: مِنَ الزُّجاجِ."],[16,16,"﴿قَدَّرُوهَا تَقۡدِيرࣰا﴾: قدَّرها السُّقاةُ على مِقْدارِ ما يَشْتَهِي الشارِبُونَ لا تَزِيدُ ولا تَنْقُصُ."],[17,17,"﴿كَأۡسࣰا﴾: إناءً مَمْلُوءًا خمَرًا.\n\n﴿مِزَاجُهَا﴾: ما تُخْلَطُ بِهِ."],[18,18,"﴿سَلۡسَبِيلࣰا﴾: الماءُ السَّهْلُ المَساغِ."],[19,19,"﴿وِلۡدَ ٰ⁠نࣱ﴾: غِلْمانٌ دائِمُونَ.\n\n﴿لُؤۡلُؤࣰا﴾: دُرًّا مُضِيئًا.\n\n﴿مَّنثُورࣰا﴾: مُفَرَّقًا."],[20,20,"﴿رَأَيۡتَ ثَمَّ﴾: أبْصَرْتَ أيَّ مَكانٍ في الجنَّةِ."],[21,21,"﴿عَـٰلِيَهُمۡ﴾: يَعْلُوهُم ويُجَمِّلُ أبْدانَهُم.\n\n﴿ثِيَابُ سُندُسٍ خُضۡرࣱ﴾: ثِيابٌ بطائِنُها مِنَ الحريرِ الرَّقِيقِ الأخْضَرِ.\n\n﴿وَإِسۡتَبۡرَقࣱ﴾: وظاهِرُها مِنَ الحريرِ الغلِيظِ.\n\n﴿وَحُلُّوٓاْ﴾: وأُلْبِسُوا للزِّينَةِ.\n\n﴿أَسَاوِرَ﴾: جَمْعُ سِوارٍ، وهو ما يُلْبسُ في المِعْصَمِ مِنَ الحُليِّ.\n\n﴿طَهُورًا﴾: لا رِجْسَ فِيهِ ولا دَنَسَ."],[22,22,"﴿سَعۡيُكُم﴾: عَمَلُكُم في الدُّنيا.\n\n﴿مَّشۡكُورًا﴾: مَرْضِيًّا عِنْدَ اللهِ مَقْبُولًا."],[24,24,"﴿فَٱصۡبِرۡ لِحُكۡمِ رَبِّكَ﴾: فاصْبِرْ لحُكْمِ رَبِّكَ القَدَريِّ واقْبَلْهُ، ولِحُكْمِهِ الدِّينِيِّ فامْضِ عَلَيهِ.\n\n﴿ءَاثِمًا﴾: عاصِيًا.\n\n﴿أَوۡ كَفُورࣰا﴾: أو مُبالِغًا في الكُفْرِ والضَّلالِ."],[25,25,"﴿بُكۡرَةࣰ﴾: أوَّلَ النَّهارِ.\n\n﴿وَأَصِيلࣰا﴾: آخِرَ النَّهارِ."],[26,26,"﴿فَٱسۡجُدۡ لَهُۥ﴾: فاخْضَعْ لِربِّكَ.\n\n﴿وَسَبِّحۡهُ﴾: وصَلِّ لَهُ، وتهجَّدْ لَهُ."],[27,27,"﴿ٱلۡعَاجِلَةَ﴾: الدُّنيا.\n\n﴿ثَقِيلࣰا﴾: عَظِيمَ الشَّدائِدِ."],[28,28,"﴿وَشَدَدۡنَآ﴾: وأحكمنا.\n\n﴿أَسۡرَهُمۡ﴾: خَلْقَهُم.\n\n﴿بَدَّلۡنَآ أَمۡثَـٰلَهُمۡ﴾: أهْلَكْناهُم، وجِئْنا بِقَوْمٍ مُطِيعِينَ."],[29,29,"﴿تَذۡكِرَةࣱ﴾: عِظَةٌ للعالَمِينَ.\n\n﴿سَبِيلࣰا﴾: طَرِيقًا يُوصِلُهُ إلى مَغْفِرَةِ اللهِ ورِضْوانِهِ."]]);
QTF("gharib",77,[[1,1,"﴿وَٱلۡمُرۡسَلَـٰتِ﴾: أُقسِمُ بالرِّياحِ حِينَ تَهُبُّ.\n\n﴿عُرۡفࣰا﴾: مُتَتابِعةً يَتْبَعُ بَعْضُها بَعْضًا كعُرْفِ الفَرَسِ."],[2,2,"﴿فَٱلۡعَـٰصِفَـٰتِ﴾: وبالرِّياحِ الشَّدَيدَةِ الهُبُوبِ المُهْلِكَةِ.\n\n﴿عَصۡفࣰا﴾: هُبُوبًا شَدِيدًا."],[3,3,"﴿وَٱلنَّـٰشِرَ ٰ⁠تِ نَشۡرࣰا﴾: وبالملائِكةِ المُوَكَّلِينَ بالسُّحُبِ يَسُوقُونَها حَيثُ شاء اللهُ."],[4,4,"﴿فَٱلۡفَـٰرِقَـٰتِ فَرۡقࣰا﴾: وبالملائِكةِ الَّتِي تَنْزِلُ مِن عِندِ اللهِ بما يَفْرُقُ بَينَ الحقِّ والباطِلِ والحَلالِ والحَرامِ."],[5,5,"﴿فَٱلۡمُلۡقِيَـٰتِ ذِكۡرًا﴾: وبالملائِكةِ الَّتِي تَتَلَقّى الوَحْيَ مِن عِنْدِ اللهِ وتُبَلّغُهُ رُسُلَهُ."],[6,6,"﴿عُذۡرًا أَوۡ نُذۡرًا﴾: إعْذارًا وإنْذارًا مِنَ اللهِ إلى خَلْقِهِ."],[7,7,"﴿لَوَ ٰ⁠قِعࣱ﴾: لَنازِلٌ بِكُم لا مَحالَةَ."],[8,8,"﴿طُمِسَتۡ﴾: ذَهَبَ ضِياؤُها."],[9,9,"﴿فُرِجَتۡ﴾: تَصَدَّعتْ."],[10,10,"﴿نُسِفَتۡ﴾: تَطايَرَتْ وتَناثَرَتْ."],[11,11,"﴿أُقِّتَتۡ﴾: عُيِّنَ لَهُم وقْتٌ لِلْفَصْلِ بَينَهُم وبَينَ الأُمَمِ."],[13,13,"﴿لِيَوۡمِ ٱلۡفَصۡلِ﴾: لِيومِ القضاءِ بين الخلائِقِ."],[14,14,"﴿وَمَآ أَدۡرَىٰكَ﴾: وما أعْلَمَكَ."],[15,15,"﴿وَيۡلࣱ﴾: هَلاكٌ عَظِيمٌ."],[16,16,"﴿ٱلۡأَوَّلِينَ﴾: السابِقِينَ مِنَ الأُمَم الماضِيةِ."],[17,17,"﴿ثُمَّ نُتۡبِعُهُمُ ٱلۡـَٔاخِرِينَ﴾: ثم نُلحِقُ بِهِمُ المُتَأخِّرِينَ المُكَذِّبِينَ."],[18,18,"﴿كَذَ ٰ⁠لِكَ﴾: مِثلَ ذلِك الإهْلاكِ الفَظِيعِ.\n\n﴿بِٱلۡمُجۡرِمِينَ﴾: مِن كُفّارِ «مكَّةَ»."],[19,19,"﴿وَيۡلࣱ﴾: هَلاكٌ وعَذابٌ شَدِيدٌ."],[20,20,"﴿مَّآءࣲ مَّهِينࣲ﴾: ماءٍ ضَعِيفٍ حَقِيرٍ وهو النطْفَةُ."],[21,21,"﴿فِي قَرَارࣲ مَّكِينٍ﴾: في مَكانٍ حَصِينٍ، وهو رَحِمُ المرأَةِ."],[22,22,"﴿إِلَىٰ قَدَرࣲ مَّعۡلُومࣲ﴾: وقتٍ مَعْلُومٍ عِندَ اللهِ تَعالى."],[23,23,"﴿فَقَدَرۡنَا﴾: فَقَدَرْنا على خَلْقِهِ وتَصْوِيِرهِ وإخْراجِهِ.\n\n﴿ٱلۡقَـٰدِرُونَ﴾: على الأشياءِ."],[24,24,"﴿وَيۡلࣱ﴾: هَلاكٌ وعَذابٌ شَدِيدٌ."],[25,25,"﴿كِفَاتًا﴾: وِعاءً جامِعًا."],[26,26,"﴿أَحۡيَآءࣰ﴾: تَضُمُّ على ظَهْرِها أحياءً.\n\n﴿وَأَمۡوَ ٰ⁠تࣰا﴾: و تَضُمُّ في بَطْنِها أمْواتًا."],[27,27,"﴿رَوَ ٰ⁠سِيَ﴾: جِبالًا ثَوابِتَ.\n\n﴿شَـٰمِخَـٰتࣲ﴾: عالياتٍ.\n\n﴿فُرَاتࣰا﴾: عَذْبًا سائِغًا."],[28,28,"﴿وَيۡلࣱ﴾: هلاكٌ ودمارٌ."],[29,29,"﴿ٱنطَلِقُوٓاْ إِلَىٰ مَا كُنتُم بِهِۦ تُكَذِّبُونَ﴾: يُقال لِلْكافِرينَ يومَ القيامةِ: سيرُوا إلى عذابِ جَهَنَّم الَّذِي كُنْتُم بِهِ تُكَذِّبُونَ في الدُّنيا."],[30,30,"﴿ٱنطَلِقُوٓاْ إِلَىٰ ظِلࣲّ﴾: سِيرُوا، فاسْتَظِلُّوا بِدُخانِ جَهَنَّمَ.\n\n﴿شُعَبࣲ﴾: قِطَعٍ."],[31,31,"﴿لَّا ظَلِيلࣲ﴾: لا يُظِلُّ ذلك الظِّلُّ مِن حَرِّ ذَلِكَ اليومِ.\n\n﴿وَلَا يُغۡنِي مِنَ ٱللَّهَبِ﴾: ولا يَدْفَعُ مِنَ حرِّ اللهبِ شيئًا."],[32,32,"﴿إِنَّهَا﴾: إنّ جَهَنَّمَ.\n\n﴿بِشَرَرࣲ﴾: اسْمِ جَمْعِ شَرَرَةٍ: وهي القِطعَةُ المشْتَعِلَةُ مِن دَقِيقِ الحَطَبِ يَدْفَعُها لَهَبُ النّارِ في الهواءِ.\n\n﴿كَٱلۡقَصۡرِ﴾: كالبِناءِ العَظِيمِ العالِي."],[33,33,"﴿جِمَـٰلَتࣱ﴾: جمعُ جَمَلٍ، طائِفَةٌ مِنَ الإبِلِ الذُّكُورِ لا إناثَ فيها.\n\n﴿صُفۡرࣱ﴾: سُودٌ يمِيلُ لونُها إلى الصُّفْرةِ."],[34,34,"﴿وَيۡلࣱ﴾: هَلاكٌ وعذابٌ شَدِيدٌ."],[35,35,"﴿لَا يَنطِقُونَ﴾: لا يَنْطِقُ فيه المُكَذِّبُونَ بِكَلامٍ يَنْفَعُهُم."],[38,38,"﴿يَوۡمُ ٱلۡفَصۡلِ﴾: يومٌ يَفْصِلُ اللهُ فِيهِ بَينَ الخلائِقِ.\n\n﴿جَمَعۡنَـٰكُمۡ وَٱلۡأَوَّلِينَ﴾: جَمَعْناكُم مَعَ الكُفّارِ مِنَ الأُمَمِ الماضِيةِ."],[39,39,"﴿كَيۡدࣱ﴾: حِيلةٌ في الخلاصِ مِنَ العذابِ.\n\n﴿فَكِيدُونِ﴾: فاحْتالُوا، وأنقذوا أنفُسَكُم مِن بَطْشِ اللهِ وانتِقامِهِ."],[41,41,"﴿وَعُيُونࣲ﴾: وعُيُونِ الماءِ الجاريةِ."],[43,43,"﴿هَنِيٓـَٔۢا﴾: سائِغًا."],[50,50,"﴿فَبِأَيِّ حَدِيثِۭ﴾: فبأيِّ كِتابٍ وكَلامٍ."]]);
QTF("gharib",78,[[1,1,"﴿عَمَّ﴾: عَنْ أيِّ شَيءٍ.\n\n﴿يَتَسَآءَلُونَ﴾: يَسْأَلُ بعضُ كُفّارِ قُريشٍ بَعْضًا."],[2,2,"﴿ٱلنَّبَإِ ٱلۡعَظِيمِ﴾: الخبرِ العَظِيمِ الشَّأنِ، وهو القُرآنُ العَظِيمُ الَّذي يُنْبِئُ عَنِ البَعْثِ."],[4,4,"﴿كَلَّا﴾: ليسَ الأمْرُ كَما يَزْعُمُ هَؤلاءِ المشْرِكُونَ.\n\n﴿سَيَعۡلَمُونَ﴾: أي: عاقبةَ تَكْذِيبِهِم."],[6,6,"﴿مِهَـٰدࣰا﴾: مُمَهَّدَةً لَكُم كالفِراشِ."],[7,7,"﴿أَوۡتَادࣰا﴾: رَواسِيَ."],[8,8,"﴿أَزۡوَ ٰ⁠جࣰا﴾: أصْنافًا ذَكَرًا وأُنْثى."],[9,9,"﴿سُبَاتࣰا﴾: راحةً لأبدانِكُم، وتَسْكُنونَ؟"],[10,10,"﴿لِبَاسࣰا﴾: تَلْبَسُكُم ظُلْمَتُهُ، كَما يَسْتُرُ الثَّوبُ لابِسَهُ."],[11,11,"﴿مَعَاشࣰا﴾: تَنتَشِرُونَ فِيهَ لِمصالِحِكُم."],[12,12,"﴿سَبۡعࣰا﴾: سَبْعَ سَمَواتٍ.\n\n﴿شِدَادࣰا﴾: مَتِينَةَ البِناءِ، مُحْكَمةَ الخَلْقِ والإنْشاءِ."],[13,13,"﴿سِرَاجࣰا﴾: شَمْسًا.\n\n﴿وَهَّاجࣰا﴾: وقّادًا مُضِيئًا."],[14,14,"﴿ٱلۡمُعۡصِرَ ٰ⁠تِ﴾: السُّحُبِ المُمْطِرَةِ.\n\n﴿ثَجَّاجࣰا﴾: منصَبًّا بِكَثْرِةٍ."],[16,16,"﴿أَلۡفَافًا﴾: مُلْتَفَّةً بعْضُها بِبَعْضٍ."],[17,17,"﴿يَوۡمَ ٱلۡفَصۡلِ﴾: بينَ الخلْقِ، وهوَ يومُ القِيامَةِ.\n\n﴿مِيقَـٰتࣰا﴾: وقْتًا ومِيعادًا مُحَدَّدًا للأولِينَ والآخِرِينَ."],[18,18,"﴿يُنفَخُ فِي ٱلصُّورِ﴾: يَنفُخُ المَلَكُ في «القَرْنِ» إيذانًا بالبَعْثِ.\n\n﴿أَفۡوَاجࣰا﴾: أُمَمًا، كلُّ أُمَّةٍ مع إمامِهِم."],[19,19,"﴿وَفُتِحَتِ﴾: شُقِّقَتْ وصُدِّعتْ.\n\n﴿أَبۡوَ ٰ⁠بࣰا﴾: ذاتَ أبوابٍ كَثِيرةٍ."],[20,20,"﴿وَسُيِّرَتِ ٱلۡجِبَالُ﴾: ونُسِفَتِ الجِبالُ.\n\n﴿سَرَابًا﴾: يَظُنُّ مَن يَراهُ مِن بُعْدٍ ماءً، وهو في الحقِيقَةِ هَباءٌ."],[21,21,"﴿مِرۡصَادࣰا﴾: تَرْقُبُ مَن يجتازُها."],[22,22,"﴿لِّلطَّـٰغِينَ﴾: للكافِرِينَ الَّذِينَ طَغَوا.\n\n﴿مَـَٔابࣰا﴾: مَرْجِعًا."],[23,23,"﴿لَّـٰبِثِينَ﴾: ماكِثِينَ.\n\n﴿أَحۡقَابࣰا﴾: دُهُورًا مُتَعاقِبةً لا تَنْقَطِعُ."],[24,24,"﴿لَّا يَذُوقُونَ﴾: لا يُحِسُّونَ.\n\n﴿بَرۡدࣰا﴾: نَسِيمًا باردًا.\n\n﴿شَرَابًا﴾: ماءً يُرْوي."],[25,25,"﴿حَمِيمࣰا﴾: ماءً حارًّا.\n\n﴿وَغَسَّاقࣰا﴾: وصَدِيدَ أهْلِ النّارِ."],[26,26,"﴿وِفَاقًا﴾: مُوافِقًا لأَعْمالِهِم."],[27,27,"﴿لَا يَرۡجُونَ حِسَابࣰا﴾: لا يَتَوَقَّعُونَ وُقُوعَ الجَزاءِ يَومَ القِيامَةِ."],[28,28,"﴿بِـَٔايَـٰتِنَا﴾: بِما جاءَتْهُم بِهِ الرُّسُلُ."],[29,29,"﴿كِتَـٰبࣰا﴾: كَتَبْناهُ في اللَّوحِ المَحْفُوظِ."],[31,31,"﴿مَفَازًا﴾: فَوْزًا بِدُخُولِهِم الجنَّةَ."],[33,33,"﴿وَكَوَاعِبَ﴾: نَواهِدَ، أثْداؤُهنَّ مُرْتَفِعَةٌ لم تَتَدَلَّ.\n\n﴿أَتۡرَابࣰا﴾: مُسْتَوِياتٍ في سِنٍّ واحِدةٍ."],[34,34,"﴿دِهَاقࣰا﴾: مَمْلُوءةً خَمْرًا."],[35,35,"﴿لَّا يَسۡمَعُونَ فِيهَا لَغۡوࣰا﴾: باطِلًا مِنَ القول.\n\n﴿وَلَا كِذَّ ٰ⁠بࣰا﴾: ولا تَكْذِيبًا."],[36,36,"﴿حِسَابࣰا﴾: كَثِيرًا كافيًا لَهُم."],[37,37,"﴿لَا يَمۡلِكُونَ مِنۡهُ خِطَابࣰا﴾: لا يَسْتَطِيعُونَ خِطابًا يُبَلِّغُونَهُ إلى اللهِ."],[38,38,"﴿ٱلرُّوحُ﴾: جِبْريِلُ.\n\n﴿صَفࣰّا﴾: مُصْطَفِّينَ.\n\n﴿صَوَابࣰا﴾: حَقًّا وسَدادًا."],[39,39,"﴿ٱلۡيَوۡمُ ٱلۡحَقُّ﴾: الثابِتُ الَّذِي لا رَيْبَ في وُقُوعِهِ.\n\n﴿مَـَٔابًا﴾: مَرْجِعًا."],[40,40,"﴿أَنذَرۡنَـٰكُمۡ﴾: حَذَّرْناكُم.\n\n﴿مَا قَدَّمَتۡ يَدَاهُ﴾: ما عَمِلَ من خِيرٍ أو شَرٍّ.\n\n﴿يَـٰلَيۡتَنِي كُنتُ تُرَ ٰ⁠بَۢا﴾: فلم أُبْعَثْ."]]);
QTF("gharib",79,[[1,1,"﴿وَٱلنَّـٰزِعَـٰتِ﴾: أُقْسِمُ بالملائِكةِ الَّتِي تَنْزِعُ أرْواحَ الكُفّارِ.\n\n﴿غَرۡقࣰا﴾: نَزْعًا غَرْقًا، أي مُغْرِقًا، أي تَنْزِعُ الأرْواحَ من أقاصِي الأَجْسادِ."],[2,2,"﴿وَٱلنَّـٰشِطَـٰتِ﴾: والملائِكَةِ الَّتِي تَقْبِضُ أرْواحَ المؤمِنِينَ.\n\n﴿نَشۡطࣰا﴾: بِنَشاطٍ ورِفقٍ."],[3,3,"﴿وَٱلسَّـٰبِحَـٰتِ﴾: والملائِكَةِ الَّتِي تَسْبَحُ في نُزُولِها مِنَ السَّماءِ وصُعُودِها إليها."],[4,4,"﴿فَٱلسَّـٰبِقَـٰتِ﴾: فالملائِكَةِ الَّتِي تُسارِعُ إلى تَنِفيذِ أمْرِ اللهِ."],[5,5,"﴿فَٱلۡمُدَبِّرَ ٰ⁠تِ أَمۡرࣰا﴾: فالملائِكةِ المُنَفِّذاتِ أمْرَ رَبِّها."],[6,6,"﴿يَوۡمَ تَرۡجُفُ ٱلرَّاجِفَةُ﴾: يومَ تَضْطَرِبُ الأرضُ بالنَّفْخَةِ الأُولى نَفْخَةِ الإماتَةِ."],[7,7,"﴿تَتۡبَعُهَا ٱلرَّادِفَةُ﴾: تَتْبَعُها نَفْخَةٌ أُخْرى لِبَعْثِ الخَلْقِ."],[8,8,"﴿قُلُوبࣱ﴾: قُلُوبُ الكُفّارِ.\n\n﴿وَاجِفَةٌ﴾: مُضْطَرِبَةٌ مِن شِدَّةِ الخوفِ."],[9,9,"﴿خَـٰشِعَةࣱ﴾: ذَلِيلَةٌ مِن هَوْلِ ما تَرى."],[10,10,"﴿أَءِنَّا لَمَرۡدُودُونَ﴾: أنُرَدُّ بَعْدَ مَوتِنا؟.\n\n﴿ٱلۡحَافِرَةِ﴾: إلى أوَّلِ حالِنا، فَنَصِيرُ أحياءً بَعْدَ مَوْتِنا."],[11,11,"﴿أَءِذَا كُنَّا عِظَـٰمࣰا نَّخِرَةࣰ﴾: أنُرَدُّ وقَدْ صِرْنا عِظامًا بالِيةً."],[12,12,"﴿كَرَّةٌ خَاسِرَةࣱ﴾: رَجْعَةٌ خائِبةٌ كاذِبةٌ."],[13,13,"﴿زَجۡرَةࣱ وَ ٰ⁠حِدَةࣱ﴾: نَفْخَةٌ واحِدَةٌ."],[14,14,"﴿بِٱلسَّاهِرَةِ﴾: على وجْهِ الأَرْضِ."],[16,16,"﴿ٱلۡمُقَدَّسِ﴾: الُمطَهَّرِ المبارَكِ.\n\n﴿طُوًى﴾: وادٍ في جانِبِ جَبَلِ الطُّورِ."],[17,17,"﴿طَغَىٰ﴾: أفْرَطَ في العِصْيانِ."],[18,18,"﴿هَل لَّكَ﴾: أتَوَدُّ.\n\n﴿تَزَكَّىٰ﴾: تُطَهِّرَ نَفْسَكَ."],[20,20,"﴿فَأَرَىٰهُ﴾: فَأَرى مُوسى فِرْعَونَ.\n\n﴿ٱلۡـَٔايَةَ ٱلۡكُبۡرَىٰ﴾: العلامةَ العُظْمى: العَصا واليدَ."],[22,22,"﴿أَدۡبَرَ﴾: ولّى مُعْرِضًا عَنِ الإيمانِ.\n\n﴿يَسۡعَىٰ﴾: في مُعارَضَةِ مُوسى."],[23,23,"﴿فَحَشَرَ﴾: فَجَمَعَ النّاسَ."],[25,25,"﴿فَأَخَذَهُ ٱللَّهُ﴾: فَعاقَبَهُ.\n\n﴿نَكَالَ ٱلۡـَٔاخِرَةِ﴾: عَذابَ الآخِرَةِ.\n\n﴿وَٱلۡأُولَىٰٓ﴾: وعَذابَ الدُّنيا."],[26,26,"﴿لَعِبۡرَةࣰ﴾: لَمَوْعِظَةً."],[27,27,"﴿ءَأَنتُمۡ أَشَدُّ خَلۡقًا أَمِ ٱلسَّمَآءُ﴾: أبَعْثُكُم-أيُّها الناسُ- بَعْدَ الموتِ أشَدُّ في تَقْدِيرِكُم أم خَلْقُ السَّماءِ؟\n\n﴿بَنَىٰهَا﴾: خَلَقَها."],[28,28,"﴿رَفَعَ سَمۡكَهَا﴾: رَفَعَها فَوقَكُم كالبِناءِ فَأَعلى سَقْفَها في الهواءِ.\n\n﴿فَسَوَّىٰهَا﴾: فعَدَّلَ أجْزاءَها بإتْقان."],[29,29,"﴿وَأَغۡطَشَ لَيۡلَهَا﴾: وأَظْلَمَ لَيلَها.\n\n﴿وَأَخۡرَجَ ضُحَىٰهَا﴾: وأَبْرَزَ نَهارَها."],[30,30,"﴿بَعۡدَ ذَ ٰ⁠لِكَ﴾: بَعْدَ خَلْقِ السَّماءِ.\n\n﴿دَحَىٰهَآ﴾: بَسَطَها وأَوْدَعَ فِيها منافِعَها."],[31,31,"﴿وَمَرۡعَىٰهَا﴾: وأَنبَتَ فِيها ما يُرعى مِنَ النباتاتِ."],[32,32,"﴿أَرۡسَىٰهَا﴾: أثْبتَها في الأرضِ."],[33,33,"﴿مَتَـٰعࣰا لَّكُمۡ﴾: مَنفَعَةً لَكُم."],[34,34,"﴿ٱلطَّآمَّةُ ٱلۡكُبۡرَىٰ﴾: القِيامَةُ الكُبْرى والشِدَّةُ العُظْمى وهي النَّفْخَةُ الثّانِيةُ."],[35,35,"﴿يَتَذَكَّرُ ٱلۡإِنسَـٰنُ مَا سَعَىٰ﴾: يُعْرَضُ عَلى الإنسانِ عَمَلُهُ، فَيَتَذَكَّرُهُ ويَعْتَرِفُ بِهِ."],[36,36,"﴿وَبُرِّزَتِ﴾: وأُظهِرَتْ."],[37,37,"﴿طَغَىٰ﴾: أفْرَطَ في العِصيانِ."],[38,38,"﴿وَءَاثَرَ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا﴾: وفَضَّل الحياةَ الدُّنيا على الآخِرَةِ."],[39,39,"﴿ٱلۡمَأۡوَىٰ﴾: المصِيرُ والمآلُ."],[40,40,"﴿مَقَامَ رَبِّهِۦ﴾: القِيامَ بينَ يَدَيِ اللهِ لِلحِسابِ.\n\n﴿ٱلۡهَوَىٰ﴾: الأَهْواءِ الفاسِدةِ."],[41,41,"﴿ٱلۡمَأۡوَىٰ﴾: مَسْكَنُهُ."],[42,42,"﴿أَيَّانَ مُرۡسَىٰهَا﴾: مَتى وقْتُ السّاعةِ؟"],[43,43,"﴿فِيمَ أَنتَ مِن ذِكۡرَىٰهَآ﴾: لَسْتَ في شَيءٍ مِن عِلْمِها."],[44,44,"﴿إِلَىٰ رَبِّكَ مُنتَهَىٰهَآ﴾: مَرَدُّ ذَلِكَ إلى اللهِ عَزَّ وجَلَّ."],[45,45,"﴿مُنذِرُ﴾: مُحذِّرٌ مِنها."],[46,46,"﴿عَشِيَّةً﴾: ما بَينَ الظُّهْرِ إلى غُرُوبِ الشَّمسِ.\n\n﴿ضُحَىٰهَا﴾: ما بَينَ طُلُوعِ الشَّمسِ إلى نِصْفِ النَّهارِ."]]);
QTF("gharib",80,[[1,1,"﴿عَبَسَ﴾: ظَهَرَ التغَيُّر والعُبُوسُ في وجْهِ الرَّسُولِ ﷺ.\n\n﴿وَتَوَلَّىٰٓ﴾: وأَعْرَضَ."],[2,2,"﴿جَآءَهُ ٱلۡأَعۡمَىٰ﴾: لِأَجْلِ أن جاءَهُ."],[3,3,"﴿وَمَا يُدۡرِيكَ﴾: وأيُّ شَيءٍ يَجْعَلُكَ عالمًِا بِحَقِيقَةِ أمْرِهِ؟.\n\n﴿يَزَّكَّىٰٓ﴾: تَزْكُو نَفسُهُ وتَطْهُرُ."],[4,4,"﴿أَوۡ يَذَّكَّرُ﴾: أو يتَّعِظُ."],[5,5,"﴿ٱسۡتَغۡنَىٰ﴾: عَنْ هَدْيِكَ."],[6,6,"﴿تَصَدَّىٰ﴾: تَتَعَرَّضُ لَهُ وتُصْغِي لِكَلامِهِ."],[7,7,"﴿وَمَا عَلَيۡكَ أَلَّا يَزَّكَّىٰ﴾: وأيُّ شَيءٍ عَلَيكَ ألّا يَتَطَهَّرَ مِن كُفْرِهِ؟"],[8,8,"﴿مَن جَآءَكَ يَسۡعَىٰ﴾: مَن كانَ حَرِيصًا عَلى لِقائِكَ."],[9,9,"﴿يَخۡشَىٰ﴾: يَخْشى اللهِ."],[10,10,"﴿تَلَهَّىٰ﴾: تَتَشاغَلُ."],[11,11,"﴿كَلَّآ﴾: ليسَ الأمرُ كما فَعَلْتَ أيهُّا الرَّسُولُ.\n\n﴿إِنَّهَا تَذۡكِرَةࣱ﴾: إنّ هَذهِ السُّورَةَ مَوعِظَةٌ لَكَ ولِكُلِّ مَن شاءَ الاتِّعاظَ."],[12,12,"﴿فَمَن شَآءَ ذَكَرَهُۥ﴾: فَمَن شاءَ ذَكَرَ الله وعَمِلَ بِهَدْيِهِ."],[13,13,"﴿فِي صُحُفࣲ مُّكَرَّمَةࣲ﴾: هَذا القرآنَ في صُحُفٍ مُعَظَّمَةٍ."],[14,14,"﴿مَّرۡفُوعَةࣲ﴾: عالية القَدْرِ.\n\n﴿مُّطَهَّرَةِۭ﴾: مُطَهَّرةٍ منَ الدنَسِ والزِّيادةِ والنَّقْصِ."],[15,15,"﴿بِأَيۡدِي سَفَرَةࣲ﴾: بِأيدِي مَلائِكَةٍ يُسْفِرُونَ بالوَحْيِ، أي: يَسْعونَ بِهِ بَينَ اللهِ ورُسُلِهِ."],[16,16,"﴿كِرَامِۭ﴾: أي عَلى رَبِّهِم.\n\n﴿بَرَرَةࣲ﴾: أخلاقُهُم وأَفعالُهم بارَّةٌ طاهِرَةٌ."],[17,17,"﴿قُتِلَ ٱلۡإِنسَـٰنُ﴾: لُعِنَ الإنسانُ الكافرُ وعُذِّبَ.\n\n﴿مَآ أَكۡفَرَهُۥ﴾: ما أشَدَّ كُفْرَهُ بِرَبِّهِ!!"],[18,18,"﴿مِنۡ أَيِّ شَيۡءٍ خَلَقَهُۥ﴾: أي أوَّلَ مَرَّةٍ؟."],[19,19,"﴿مِن نُّطۡفَةٍ خَلَقَهُۥ﴾: خَلَقَه اللهُ مِن مّاءِ قَلِيلٍ -وهو المَنِيُّ-.\n\n﴿فَقَدَّرَهُۥ﴾: فَقَدَّرهُ أطْوارا."],[20,20,"﴿ثُمَّ ٱلسَّبِيلَ يَسَّرَهُۥ﴾: ثم بَيَّنَ لَهُ طَرِيقَ الخيرِ والشَّرِّ."],[21,21,"﴿فَأَقۡبَرَهُۥ﴾: فَجَعَلَ لَهُ مَكانًا يُقْبَرُ فِيهِ."],[22,22,"﴿أَنشَرَهُۥ﴾: أحْياهُ، وبَعَثَهُ بَعْدَ مَوتِهِ للْحِسابِ والجَزاءِ."],[23,23,"﴿كَلَّا﴾: ليسَ الأمرُ كما يقُولُ الكافِرُ ويَفَعْلُ\n\n﴿لَمَّا يَقۡضِ مَآ أَمَرَهُۥ﴾: لم يُؤَدِّ ما أمَرهُ اللهُ بِهِ."],[24,24,"﴿فَلۡيَنظُرِ ٱلۡإِنسَـٰنُ إِلَىٰ طَعَامِهِۦٓ﴾: فَلْيَتَدَبَّرِ الإنْسانُ: كَيفَ خَلَقَ اللهُ طَعامَه الَّذِي هُوَ قِوامُ حياتِهِ؟."],[25,25,"﴿صَبَبۡنَا﴾: أنْزَلَناهُ."],[26,26,"﴿ثُمَّ شَقَقۡنَا ٱلۡأَرۡضَ﴾: أي بِما أخْرَجْنا مِنها مِن نَّباتٍ شَتّى."],[28,28,"﴿وَقَضۡبࣰا﴾: وعَلَفًا للدَّوابِّ."],[30,30,"﴿غُلۡبࣰا﴾: عَظِيمةَ الأشْجارِ."],[31,31,"﴿وَأَبࣰّا﴾: كَلَأً."],[32,32,"﴿مَّتَـٰعࣰا﴾: تَنْعَمُونَ بِها وتَنْتَفِعُونَ."],[33,33,"﴿ٱلصَّآخَّةُ﴾: صَيحَةُ يَوْم القِيامَةِ الَّتِي تُصَمُّ مِن هَوْلِها الأَسْماعُ."],[36,36,"﴿وَصَـٰحِبَتِهِۦ﴾: وزَوْجِه."],[37,37,"﴿شَأۡنࣱ يُغۡنِيهِ﴾: أمْرٌ يَشْغَلُهُ."],[41,41,"﴿تَرۡهَقُهَا﴾: تَغْشاها.\n\n﴿قَتَرَةٌ﴾: شِبْهُ دُخانٍ يَغْشى الوجْهَ مِن كَرْبٍ شَدِيدٍ."],[42,42,"﴿ٱلۡفَجَرَةُ﴾: الَّذِين تَجَرَّؤُوا عَلى مَحارِمِ اللهِ بالفُجُورِ والطُّغيانِ."]]);
QTF("gharib",81,[[1,1,"﴿كُوِّرَتۡ﴾: لُفَّتْ، وذَهَبَ ضَوْءُها."],[2,2,"﴿ٱنكَدَرَتۡ﴾: تَناثَرَتْ، فَذَهَبَ نُورُها."],[3,3,"﴿سُيِّرَتۡ﴾: سُيِّرَتْ عن وجْهِ الأرْضِ فَصارَتْ هَباءً."],[4,4,"﴿ٱلۡعِشَارُ﴾: النُوقُ الحوامِلُ.\n\n﴿عُطِّلَتۡ﴾: تُرِكَتْ وأُهْمِلَتْ."],[5,5,"﴿ٱلۡوُحُوشُ﴾: الحيواناتُ الوَحْشِيِّةُ.\n\n﴿حُشِرَتۡ﴾: جُمِعَتْ واخْتَلَطَتْ، لِيَقْتَصَّ اللهُ مِن بَعْضِها لِبَعْضٍ."],[6,6,"﴿سُجِّرَتۡ﴾: أُوقِدَتْ."],[7,7,"﴿زُوِّجَتۡ﴾: قُرِنَتْ بأَمثالِها."],[8,8,"﴿ٱلۡمَوۡءُۥدَةُ﴾: الطِّفْلةُ المدفُونةُ حَيَةً.\n\n﴿سُئِلَتۡ﴾: سُؤالَ تَطْيِيبٍ لها ولَومٍ لِوائِدِها."],[10,10,"﴿ٱلصُّحُفُ﴾: صُحُفُ الأَعْمالِ.\n\n﴿نُشِرَتۡ﴾: عُرِضَتْ."],[11,11,"﴿كُشِطَتۡ﴾: أُزِيلَتْ مِن مَّكانِها."],[12,12,"﴿سُعِّرَتۡ﴾: أُوقِدَتْ."],[13,13,"﴿أُزۡلِفَتۡ﴾: قُرِّبَتْ مِن أهْلِها."],[14,14,"﴿أَحۡضَرَتۡ﴾: قَدَّمَتْ من خَيرٍ أو شَرٍّ."],[15,15,"﴿بِٱلۡخُنَّسِ﴾: بِالنُّجُومِ المُخْتَفِيَةِ أنْوارُها نهارًا."],[16,16,"﴿ٱلۡجَوَارِ﴾: الجارِيةِ.\n\n﴿ٱلۡكُنَّسِ﴾: المسْتَتِرَةِ في أبْراجِها."],[17,17,"﴿عَسۡعَسَ﴾: أقْبَلَ بِظَلامِهِ."],[18,18,"﴿تَنَفَّسَ﴾: ظَهَرَ ضِياؤُه."],[19,19,"﴿إِنَّهُۥ﴾: إنَّ القُرآنَ.\n\n﴿رَسُولࣲ كَرِيمࣲ﴾: هو جِبْرِيلُ -عَلَيه السَّلامُ-."],[20,20,"﴿ذِي ٱلۡعَرۡشِ﴾: اللهِ.\n\n﴿مَكِينࣲ﴾: صاحبِ مَكانَةٍ رَفِيعَةٍ."],[21,21,"﴿ثَمَّ﴾: هُناكَ.\n\n﴿أَمِينࣲ﴾: مُؤْتَمَنٍ على الوَحْيِ الَّذِي يَنْزِلُ بِه."],[22,22,"﴿صَاحِبُكُم﴾: مُحَمَّدٌ ﷺ الَّذِي تَعْرِفُونَهُ."],[23,23,"﴿وَلَقَدۡ رَءَاهُ﴾: ولَقَدْ رَأى مُحَمَّدٌ جِبْرِيلَ.\n\n﴿بِٱلۡأُفُقِ ٱلۡمُبِينِ﴾: بالأُفُقِ العَظِيمِ."],[24,24,"﴿عَلَى ٱلۡغَيۡبِ﴾: بِتَبْلِيغ الوَحْيِ.\n\n﴿بِضَنِينࣲ﴾: ببَخِيلٍ."],[25,25,"﴿رَّجِيمࣲ﴾: مَطْرُودٍ منِ رَّحْمَةِ اللهِ."],[26,26,"﴿فَأَيۡنَ تَذۡهَبُونَ﴾: فَأَينَ تَذْهَبُ بِكُم عُقُولُكُم فَي التَّكْذِيبِ بالقُرآنِ بَعْدَ هذِه الحُجَجِ القاطِعَةِ؟"],[27,27,"﴿ذِكۡرࣱ﴾: مَوعِظَةٌ."],[28,28,"﴿يَسۡتَقِيمَ﴾: على الحقِّ والإيمانِ."]]);
QTF("gharib",82,[[1,1,"﴿ٱنفَطَرَتۡ﴾: انْشَقَّتْ، واخْتَلَّ نِظامُها."],[2,2,"﴿ٱنتَثَرَتۡ﴾: تَساقَطَتْ."],[3,3,"﴿فُجِّرَتۡ﴾: فَجَّرَ اللهُ بَعْضَها في بَعْضٍ، فَمَلأَ جَمِيعَها."],[4,4,"﴿بُعۡثِرَتۡ﴾: قُلِبتْ بِبَعْثِ مَن كانَ فِيها."],[5,5,"﴿نَفۡسࣱ﴾: كلُّ نَفْسٍ.\n\n﴿مَّا قَدَّمَتۡ وَأَخَّرَتۡ﴾: ما تَقَدَّمَ مِن أعْمالِها وما تَأَخَّرَ."],[6,6,"﴿ٱلۡإِنسَـٰنُ﴾: المنْكِرُ لِلْبَعْثِ.\n\n﴿مَا غَرَّكَ بِرَبِّكَ﴾: ما الَّذِي خَدَعَكَ حتّى كَفَرْتَ بِرَبِّكَ؟.\n\n﴿ٱلۡكَرِيمِ﴾: الجَوادِ الكَثِيرِ الخيرِ."],[7,7,"﴿فَسَوَّىٰكَ﴾: فَجَعَلَكَ قَوِيمًا سَلِيمًا.\n\n﴿فَعَدَلَكَ﴾: فَجَعَلَكَ مُسْتَقِيمَ القامَةِ مُتَناسِبَ الأجْزاءِ."],[8,8,"﴿مَّا شَآءَ رَكَّبَكَ﴾: رَكَّبكَ التَّرْكِيبَ الَّذِي شاءَهُ."],[9,9,"﴿كَلَّا﴾: لَيسَ الأمرُ كَما تَقُولُونَ.\n\n﴿بِٱلدِّينِ﴾: بِيومِ الِحسابِ."],[10,10,"﴿لَحَـٰفِظِينَ﴾: لمَلائِكَةً رُقَباءَ."],[11,11,"﴿كِرَامࣰا﴾: على اللهِ.\n\n﴿كَـٰتِبِينَ﴾: لِما وُكِّلُوا بإحْصائِهِ."],[13,13,"﴿ٱلۡأَبۡرَارَ﴾: القائِمينَ بِحُقُوقِ اللهِ وحُقُوقِ عِبادِهِ.\n\n﴿نَعِيمࣲ﴾: التَّنَعُّمِ الدّائِم في الجنَّةِ."],[14,14,"﴿ٱلۡفُجَّارَ﴾: الَّذِينَ قَصَّرُوا في حُقُوقِ اللهِ وحُقُوقِ عِبادِهِ."],[15,15,"﴿يَصۡلَوۡنَهَا﴾: يُصِيبُهُم لَهَبُها.\n\n﴿يَوۡمَ ٱلدِّينِ﴾: يوم الجزاءِ."],[16,16,"﴿عَنۡهَا﴾: عذابِ جَهَنَّمَ.\n\n﴿بِغَآئِبِينَ﴾: لا بِخُرُوج ولا بِمَوتٍ."],[17,17,"﴿وَمَآ أَدۡرَىٰكَ﴾: وما أعْلَمَكَ؟\n\n﴿مَا يَوۡمُ ٱلدِّينِ﴾: ما عَظَمَةُ يَومِ الحِسابِ."],[19,19,"﴿لَا تَمۡلِكُ نَفۡسࣱ لِّنَفۡسࣲ شَيۡـࣰٔا﴾: لا يَقْدِرُ أحدٌ على نَفْعِ أحَدٍ."]]);
QTF("gharib",83,[[1,1,"﴿وَيۡلࣱ﴾: عذابٌ شَدِيدٌ.\n\n﴿لِّلۡمُطَفِّفِينَ﴾: وهُمُ الَّذِينَ يَبْخَسُونَ المِكْيالَ والِميزانَ."],[2,2,"﴿ٱلَّذِينَ إِذَا ٱكۡتَالُواْ عَلَى ٱلنَّاسِ﴾: الَّذِينَ إذا اشْتَرَوا مِنَ النّاسِ مَكِيلًا أو مَوزُونًا.\n\n﴿يَسۡتَوۡفُونَ﴾: يَطْلُبُونَ وفاءَ نَصِيبِهِم."],[3,3,"﴿وَإِذَا كَالُوهُمۡ﴾: وإذا باعُوا النّاس مَكِيلا.\n\n﴿وَّزَنُوهُمۡ﴾: باعُوا النّاسَ مَوزُونًا.\n\n﴿يُخۡسِرُونَ﴾: يَنْقُصُونَ في المِكيالِ والِميزانِ."],[4,4,"﴿يَظُنُّ﴾: يَعْتَقِدُ."],[7,7,"﴿كَلَّآ﴾: ليسَ الأَمْرُ كَما يَظُنُّ هَؤُلِاءِ الكُفّارُ، أنّهم غَيرُ مَبْعُوثِينَ.\n\n﴿كِتَـٰبَ ٱلۡفُجَّارِ﴾: صَحِيفةَ أعْمالِ المُشْرِكِينَ.\n\n﴿لَفِي سِجِّينࣲ﴾: أسْفَلِ الأرْضِ السّابِعَةِ."],[8,8,"﴿وَمَآ أَدۡرَىٰكَ﴾: وأيُّ شَيءٍ أعْلَمكَ؟"],[9,9,"﴿مَّرۡقُومࣱ﴾: مَكْتُوبٌ كِتابَةً بَيِّنةً."],[10,10,"﴿وَيۡلࣱ﴾: عذابٌ شَدِيدٌ."],[11,11,"﴿بِيَوۡمِ ٱلدِّينِ﴾: بُوقُوعِ يَومِ الجَزاءِ."],[12,12,"﴿مُعۡتَدٍ﴾: ظالِمٍ.\n\n﴿أَثِيمٍ﴾: كَثِيرِ الإثْمِ."],[13,13,"﴿أَسَـٰطِيرُ ٱلۡأَوَّلِينَ﴾: أباطِيلُ السّابِقِينَ."],[14,14,"﴿رَانَ عَلَىٰ قُلُوبِهِم مَّا كَانُواْ يَكۡسِبُونَ﴾: غَطّى عَلى قُلُوبِهِم كَثْرَةُ ما يَرْتَكِبُونَهُ مِنَ الذُّنُوبِ."],[15,15,"﴿عَن رَّبِّهِمۡ﴾: عَن رُّؤْيَةِ رَبِّهِم -جَلَّ وعَلا-.\n\n﴿لَّمَحۡجُوبُونَ﴾: لَمَمْنُوعُونَ."],[16,16,"﴿لَصَالُواْ ٱلۡجَحِيمِ﴾: لَداخِلُو النّارِ."],[18,18,"﴿كَلَّآ﴾: حَقًّا.\n\n﴿كِتَـٰبَ﴾: صَحائِفَ أعْمالِ.\n\n﴿ٱلۡأَبۡرَارِ﴾: الأَتْقِياءِ.\n\n﴿لَفِي عِلِّيِّينَ﴾: لَفِي المراتِبِ العالِيَةِ في الجنَّةِ."],[20,20,"﴿كِتَـٰبࣱ مَّرۡقُومࣱ﴾: مَكْتُوبٌ كِتابَةً بَيِّنةً."],[21,21,"﴿يَشۡهَدُهُ﴾: يَطَّلِعُ عَلَيهِ."],[22,22,"﴿ٱلۡأَبۡرَارَ﴾: أهْلَ الصِّدْقِ والطّاعَةِ.\n\n﴿لَفِي نَعِيمٍ﴾: لَفِي الجنَّةِ يَتَنَعَّمُونَ."],[23,23,"﴿ٱلۡأَرَآئِكِ﴾: الأَسِرَّةِ.\n\n﴿يَنظُرُونَ﴾: يَنْظُرُونَ إلى رَبِّهِم، وإلى ما أعَدَّ لَهُم مِن خَيراتٍ."],[24,24,"﴿نَضۡرَةَ ٱلنَّعِيمِ﴾: بَهْجَةَ النَّعِيمِ وحُسْنَه."],[25,25,"﴿رَّحِيقࣲ﴾: خَمْرٍ صافِيةٍ.\n\n﴿مَّخۡتُومٍ﴾: مُحْكَمٍ إناؤُها."],[26,26,"﴿خِتَـٰمُهُۥ﴾: آخِرُهُ.\n\n﴿مِسۡكࣱ﴾: رائِحَةُ مِسْكٍ.\n\n﴿فَلۡيَتَنَافَسِ ٱلۡمُتَنَـٰفِسُونَ﴾: فَليَتَسابَقِ المُتَسابِقُونَ."],[27,27,"﴿وَمِزَاجُهُۥ مِن تَسۡنِيمٍ﴾: وخَلْطُه مِن عَينٍ في الجنَّةِ تُعْرَفُ ب«تَسْنِيمٍ»."],[28,28,"﴿يَشۡرَبُ بِهَا﴾: مِنها.\n\n﴿ٱلۡمُقَرَّبُونَ﴾: الملائكةُ المُقرَّبُونَ مِنَ اللهِ."],[29,29,"﴿أَجۡرَمُواْ﴾: ارْتَكَبُوا الإثمَ العَظِيمَ، وهو الشِّرْكُ.\n\n﴿يَضۡحَكُونَ﴾: يَهْزَؤُونَ."],[30,30,"﴿يَتَغَامَزُونَ﴾: يُشِيرُونَ بأطْرافِ العُيُونِ سُخْرِيَةً بِهم."],[31,31,"﴿وَإِذَا ٱنقَلَبُوٓاْ﴾: رَجَعُوا.\n\n﴿فَكِهِينَ﴾: مُتَفَكِّهِينَ بالسُّخْرِيَةِ مِنَ المؤُمِنِينَ."],[32,32,"﴿رَأَوۡهُمۡ﴾: رَأى هَؤُلاءِ الكُفّارُ أصْحابَ مُحَمَّدٍ ﷺ."],[33,33,"﴿حَـٰفِظِينَ﴾: رُقَباءَ عَلى أصْحابِ مُحَمَّدٍ ﷺ."],[35,35,"﴿ٱلۡأَرَآئِكِ﴾: المجالِسِ الفاخِرَةِ.\n\n﴿يَنظُرُونَ﴾: يَنْظُرُ المؤمِنُونَ إلى ما أعْطاهُم اللهُ مِنَ الكَرامةِ والنَّعِيم في الجنَّةِ."],[36,36,"﴿هَلۡ ثُوِّبَ ٱلۡكُفَّارُ﴾: هل جُوزِي الكُفّارُ مِن جِنْسِ أعمالِهِم؟"]]);
QTF("gharib",84,[[1,1,"﴿ٱنشَقَّتۡ﴾: تَصَدَّعتْ يومَ القِيامَةِ."],[2,2,"﴿وَأَذِنَتۡ لِرَبِّهَا﴾: وأَطاعَتْ أمْرَ رَبِّها.\n\n﴿وَحُقَّتۡ﴾: وحُقَّ لَها أن تَنقادَ لِأَمْرِهِ."],[3,3,"﴿مُدَّتۡ﴾: بُسِطَتْ ووُسِّعَتْ."],[4,4,"﴿وَأَلۡقَتۡ مَا فِيهَا﴾: وقَذَفَتْ ما في بَطْنِها مِنَ الأمْواتِ.\n\n﴿وَتَخَلَّتۡ﴾: لم يَبْقَ شَيءٌ مِمّا في بَطْنِها."],[5,5,"﴿وَأَذِنَتۡ لِرَبِّهَا﴾: وانْقادَتْ لِرَبِها فِيما أمَرها بِهِ."],[6,6,"﴿كَادِحٌ﴾: ساعٍ إلى اللهِ.\n\n﴿فَمُلَـٰقِيهِ﴾: تُلاقِي الله يَومَ القِيامَةِ."],[7,7,"﴿أُوتِيَ كِتَـٰبَهُۥ﴾: أُعطِيَ صَحِيفةَ أعمالِهِ."],[8,8,"﴿يَسِيرࣰا﴾: سَهْلا."],[9,9,"﴿وَيَنقَلِبُ﴾: ويَرْجِعُ."],[10,10,"﴿كِتَـٰبَهُۥ﴾: صَحِيفةَ أعْمالِهِ."],[11,11,"﴿ثُبُورࣰا﴾: بِالهَلاكِ."],[12,12,"﴿وَيَصۡلَىٰ سَعِيرًا﴾: ويَدْخُلُ النّارَ مُقاسِيًا حَرَّها."],[13,13,"﴿مَسۡرُورًا﴾: مَغْرُورًا لا يُفَكِّرُ في العواقِبِ."],[14,14,"﴿يَحُورَ﴾: يَرْجِعَ إلى خالِقِه لِلْحِسابِ."],[16,16,"﴿بِٱلشَّفَقِ﴾: باحْمِرارِ الأُفُقِ عِنْدَ الغُرُوب."],[17,17,"﴿وَمَا وَسَقَ﴾: وما جَمَعَ من الدَّوابِّ والحَشراتِ والهَوامِّ وغَيرِ ذَلِكَ."],[18,18,"﴿ٱتَّسَقَ﴾: تَكامَلَ نُورُهُ."],[19,19,"﴿طَبَقًا عَن طَبَقࣲ﴾: أطوارًا مُتَعَدِّدَةً وأَحْوالًا مُتَبايِنَةً: مِنَ النُّطْفَةِ إلى العَلَقَةِ إلى المُضْغةِ إلى نَفْخِ الرُّوحِ، إلى الموتِ، إلى البعْثِ والنُّشُورِ."],[20,20,"﴿فَمَا لَهُمۡ لَا يُؤۡمِنُونَ﴾: فأيُّ شَيءٍ يَمْنَعُهُم مِنَ الإيمانِ بَعْدَ ما وُضِّحَتْ لَهُمُ الآياتُ؟"],[21,21,"﴿لَا يَسۡجُدُونَ﴾: لا يَخْضَعُونَ للهِ، ولا يُسَلِّمُونَ بِما جاءَ في القُرآنِ."],[23,23,"﴿بِمَا يُوعُونَ﴾: بِما يَكْتُمُونَ مِن العِنادِ مَعَ عِلْمِهِم بأنّ ما جاءَ بهِ القرآنُ حَقٌّ."],[24,24,"﴿فَبَشِّرۡهُم﴾: أي هَؤُلاءِ المكذِّبِينَ."],[25,25,"﴿غَيۡرُ مَمۡنُونِۭ﴾: غَيرُ مَقْطُوعٍ ولا مَنقُوصٍ."]]);
QTF("gharib",85,[[1,1,"﴿ذَاتِ ٱلۡبُرُوجِ﴾: ذاتِ المنازِل."],[2,2,"﴿وَٱلۡيَوۡمِ ٱلۡمَوۡعُودِ﴾: أقَسَم اللهُ تَعالى بِاليَومِ الَّذِي وعَدَ اللهُ الخلْقَ أن يَجْمَعَهُم فِيهِ."],[3,3,"﴿وَشَاهِدࣲ﴾: الرائِي، أو الُمخْبِرِ بِحَقٍّ.\n\n﴿وَمَشۡهُودࣲ﴾: المَرئي، أو المشهود عليه بحق."],[4,4,"﴿قُتِلَ﴾: لُعِنَ.\n\n﴿أَصۡحَـٰبُ ٱلۡأُخۡدُودِ﴾: الَّذِين شَقُّوا في الأرضِ شَقًّا عَظِيمًا؛ لِتَعذِيبِ المؤمِنِينَ."],[5,5,"﴿ٱلۡوَقُودِ﴾: ما تُوقَدُ بِهِ النّارُ مِن حَطَبٍ ونَحوِهِ."],[6,6,"﴿إِذۡ هُمۡ﴾: هَؤُلاءِ الكُفّارُ مِن أصحابِ الأُخْدُودِ.\n\n﴿عَلَيۡهَا﴾: عَلى حافَةِ النّارِ الَّتِي في الأُخْدُودِ."],[7,7,"﴿شُهُودࣱ﴾: حُضُورٌ."],[8,8,"﴿وَمَا نَقَمُواْ﴾: وما أنْكَرُوا عَلَيهِم.\n\n﴿ٱلۡعَزِيزِ﴾: الشَّدِيدِ في انْتِقامِهِ مِمَّن انْتَقَمَ مِنهُ.\n\n﴿ٱلۡحَمِيدِ﴾: الَمحْمودِ في أقْوالِهِ وأَفْعالِهِ."],[9,9,"﴿شَهِيدٌ﴾: مُطَّلِعٌ لا يَخْفى عَلَيهِ شَيءٌ."],[10,10,"﴿فَتَنُواْ﴾: حَرَّقُوا."],[11,11,"﴿مِن تَحۡتِهَا﴾: مِن تَحْتِ قُصُورِها وأَشْجارِها."],[13,13,"﴿يُبۡدِئُ﴾: يَبْدَأُ الخَلْقَ.\n\n﴿وَيُعِيدُ﴾: الخَلْقَ لِلْحِسابِ."],[14,14,"﴿ٱلۡغَفُورُ﴾: لمِن تابَ.\n\n﴿ٱلۡوَدُودُ﴾: كَثِيرُ المحَبَّةِ لأوليائِهِ."],[15,15,"﴿ذُو ٱلۡعَرۡشِ﴾: صاحِبُ العرْشِ.\n\n﴿ٱلۡمَجِيدُ﴾: الَّذِي بَلَغَ المُنْتَهى في الفَضلِ."],[16,16,"﴿فَعَّالࣱ لِّمَا يُرِيدُ﴾: لا يَمْتَنِعُ عَلَيهِ شَيءٌ يُريدُهُ."],[17,17,"﴿حَدِيثُ ٱلۡجُنُودِ﴾: خَبَرُ الجُمُوعِ الكافِرةِ المُكَذِّبةِ لأَنْبِيائِها."],[21,21,"﴿مَّجِيدࣱ﴾: عَظِيمٌ كَرِيمٌ."],[22,22,"﴿فِي لَوۡحࣲ مَّحۡفُوظِۭ﴾: لا ينالُه تَبْدِيلٌ ولا تَحْرِيفٌ."]]);
QTF("gharib",86,[[1,1,"﴿وَٱلطَّارِقِ﴾: أقْسَمَ اللهُ سُبحانَهُ بالنَّجْمِ الَّذِي يَطْرُقُ ليلًا."],[2,2,"﴿وَمَآ أَدۡرَىٰكَ﴾: وأيُّ شَيءٍ أعْلَمَكَ؟.\n\n﴿مَا ٱلطَّارِقُ﴾: ما عِظَمُ هذا النَّجمِ؟"],[3,3,"﴿ٱلنَّجۡمُ ٱلثَّاقِبُ﴾: النَّجمُ المُضِيءُ المُتَوهِّجُ."],[4,4,"﴿إِن﴾: ما.\n\n﴿لَّمَّا﴾: إلّا.\n\n﴿عَلَيۡهَا حَافِظࣱ﴾: أُوكِلَ بها مَلَكٌ رَقِيبٌ يَحْفَظُ عَلَيها أعْمالَها."],[6,6,"﴿مَّآءࣲ دَافِقࣲ﴾: مَنيٍّ مُنْصَبٍّ بِسُرعَةٍ في الرَّحِم."],[7,7,"﴿ٱلصُّلۡبِ﴾: العَمُودِ العَظْميِّ في وسَطِ الظَّهْرِ، وهو ذُو الفِقْراتِ.\n\n﴿وَٱلتَّرَآئِبِ﴾: جَمْع ترِيبةٍ، وهي عظامُ الصَّدرِ الَّتِي بَينَ التَّرقُوَتَينِ والثَّديينِ."],[8,8,"﴿رَجۡعِهِۦ﴾: إعادَتِهِ إلى الحياةِ بَعْدَ الموتِ."],[9,9,"﴿تُبۡلَى﴾: تُخْتَبرُ.\n\n﴿ٱلسَّرَآئِرُ﴾: ما يُخْفيهِ الإنسانُ مِنَ العقائِدِ والأعْمالِ."],[10,10,"﴿قُوَّةࣲ﴾: يدفعُ بِها عَن نَّفْسِهِ."],[11,11,"﴿ذَاتِ ٱلرَّجۡعِ﴾: ذاتِ المطَرِ الَّذِي يَرْجِعُ و يَتَكَرَّرُ."],[12,12,"﴿ٱلصَّدۡعِ﴾: التَّشَقُّقِ بِما يَتَخلَّلُها مِن نَّباتٍ."],[13,13,"﴿فَصۡلࣱ﴾: فاصِلٌ بَيْنَ الحقِّ والباطِلِ."],[14,14,"﴿بِٱلۡهَزۡلِ﴾: باللَّعِبِ والباطِل."],[15,15,"﴿يَكِيدُونَ كَيۡدࣰا﴾: يُخْفونَ قَصْدَ الضُّرِّ ويُظْهِرُونَ خِلافَه."],[16,16,"﴿وَأَكِيدُ كَيۡدࣰا﴾: لإظْهارِ الحقِّ."],[17,17,"﴿فَمَهِّلِ ٱلۡكَـٰفِرِينَ﴾: فأنْظِرْهُم.\n\n﴿أَمۡهِلۡهُمۡ﴾: أنْظِرْهُم.\n\n﴿رُوَيۡدَۢا﴾: مُهلةً غيرَ طويلةٍ."]]);
QTF("gharib",87,[[1,1,"﴿سَبِّحِ﴾: نَزِّه عَن كُلِّ ما لا يَليقُ بِهِ."],[2,2,"﴿فَسَوَّىٰ﴾: فَأَتْقَنَ خَلْقَ الإنسانِ."],[3,3,"﴿فَهَدَىٰ﴾: الإنسانَ لِسبيلِ الخير والشر، وهدى الأنعام لمراتعها."],[4,4,"﴿ٱلۡمَرۡعَىٰ﴾: الكلأ الأخضر."],[5,5,"﴿غُثَآءً﴾: هشيمًا جافًّا.\n\n﴿أَحۡوَىٰ﴾: مُتَغَيِّرًا إلى السَّوادِ بَعْدَ الخُضْرَةِ."],[6,6,"﴿سَنُقۡرِئُكَ﴾: سنُعْلِمُكَ بِقراءةِ جِبريلَ عَلَيكَ."],[7,7,"﴿إِلَّا مَا شَآءَ ٱللَّهُ﴾: أن تَنْساهُ وما نَسَخَ اللهُ تِلاوتَهُ."],[8,8,"﴿وَنُيَسِّرُكَ﴾: وُنَهوِّنُ عَلَيكَ.\n\n﴿لِلۡيُسۡرَىٰ﴾: عَمَلِ أهْلِ الجنَّةِ."],[9,9,"﴿فَذَكِّرۡ﴾: فَعِظْ بالقرآنِ.\n\n﴿إِن نَّفَعَتِ ٱلذِّكۡرَىٰ﴾: إن رُجِيَ مِنهُ التَّذَكُّرُ."],[10,10,"﴿سَيَذَّكَّرُ﴾: سيَتَّعِظُ."],[11,11,"﴿ٱلۡأَشۡقَى﴾: الَّذِي لا يَخْشى رَبَّهُ، وشَقِيَ فِي عِلْمِ اللهِ."],[12,12,"﴿يَصۡلَى﴾: يُقاسِي حرَّها.\n\n﴿ٱلنَّارَ ٱلۡكُبۡرَىٰ﴾: نارَ جَهَنَّمَ العُظْمى."],[13,13,"﴿لَا يَمُوتُ فِيهَا﴾: فَيَسْتَرِيحَ.\n\n﴿وَلَا يَحۡيَىٰ﴾: حياةً تَنفَعُهُ."],[14,14,"﴿أَفۡلَحَ﴾: فازَ.\n\n﴿تَزَكَّىٰ﴾: طَهَّرَ نَفسَهُ مِنَ الأخْلاقِ السَّيِّئةِ."],[16,16,"﴿تُؤۡثِرُونَ﴾: تُفَضِّلُونَ."],[18,18,"﴿هَـٰذَا﴾: ما ذُكِرَ مِن قولِه تعالى:(قَدۡ أفۡلَحَ مَن تَزَكّى) إلى تَمامِ أرْبَعِ آياتٍ.\n\n﴿ٱلصُّحُفِ ٱلۡأُولَىٰ﴾: الكُتُبِ الأُولى الَّتِي أُنزِلَت قَبْلَ القُرآنِ."]]);
QTF("gharib",88,[[1,1,"﴿هَلۡ﴾: قَدْ.\n\n﴿ٱلۡغَـٰشِيَةِ﴾: القِيامةِ الَّتِي تَغْشى النّاسَ بأهْوالِها."],[2,2,"﴿وُجُوهࣱ﴾: وُجُوهُ الكُفّارِ.\n\n﴿خَـٰشِعَةٌ﴾: ذَلِيلةٌ بالعذابِ."],[3,3,"﴿عَامِلَةࣱ﴾: مُجْهَدَةٌ بالعَمَلِ.\n\n﴿نَّاصِبَةࣱ﴾: مُتْعَبَةٌ."],[4,4,"﴿تَصۡلَىٰ﴾: تُقاسِي نارًا.\n\n﴿حَامِيَةࣰ﴾: شَدِيدَة التَّوَهُّجِ."],[5,5,"﴿ءَانِيَةࣲ﴾: بَلَغَتْ مُنْتَهى الحرارةِ."],[6,6,"﴿ضَرِيعࣲ﴾: نَبْتٍ ذي شَوْكٍ لاصِقٍ بالأرْضِ."],[7,7,"﴿وَلَا يُغۡنِي مِن جُوعࣲ﴾: ولا يَسُدُّ جُوعَهُ."],[8,8,"﴿وُجُوهࣱ﴾: وُجُوهُ المؤمِنينَ.\n\n﴿نَّاعِمَةࣱ﴾: ذاتُ نِعْمَةٍ وكَرامةٍ."],[9,9,"﴿لِّسَعۡيِهَا﴾: لِعَمَلِها الَّذِي عَمِلَتْهُ في الدُّنيا.\n\n﴿رَاضِيَةࣱ﴾: في الآخِرَةِ حِينَ أُعْطِيَتِ الجنَّةَ بِعَمَلِها."],[10,10,"﴿عَالِيَةࣲ﴾: رَفِيعةِ المكانِ والمكانةِ."],[11,11,"﴿لَـٰغِيَةࣰ﴾: كَلِمةَ لَغْوٍ."],[12,12,"﴿جَارِيَةࣱ﴾: تَتَدَفَّقُ مِياهُها."],[14,14,"﴿مَّوۡضُوعَةࣱ﴾: مُعَدَّةٌ للشّارِبِينَ."],[15,15,"﴿وَنَمَارِقُ﴾: ووَسائِدُ ومَرافِقُ.\n\n﴿مَصۡفُوفَةࣱ﴾: بَعضُها بِجَنبِ بَعْضٍ."],[16,16,"﴿وَزَرَابِيُّ﴾: وبُسُطٌ.\n\n﴿مَبۡثُوثَةٌ﴾: كَثِيرةٌ مَفْرُوشَةٌ."],[18,18,"﴿كَيۡفَ رُفِعَتۡ﴾: عَنِ الأرْضِ بِلا عَمَدٍ؟"],[19,19,"﴿نُصِبَتۡ﴾: رُفِعتْ حتّى كانتْ بارزةً على وجْهِ الأرضِ."],[20,20,"﴿سُطِحَتۡ﴾: بُسِطَتْ و مُهِّدتْ."],[21,21,"﴿فَذَكِّرۡ﴾: فَعِظْ.\n\n﴿مُذَكِّرࣱ﴾: واعِظٌ."],[22,22,"﴿بِمُصَيۡطِرٍ﴾: بِمُسَلَّطٍ، فَتُكْرِهَهُم على الإيمانِ."],[23,23,"﴿تَوَلَّىٰ﴾: أعْرَضَ وأصَرَّ عَلى الكُفْرِ."],[24,24,"﴿ٱلۡعَذَابَ ٱلۡأَكۡبَرَ﴾: النّارَ."],[25,25,"﴿إِيَابَهُمۡ﴾: مَرْجِعَهُم بَعْدَ الموتِ."],[26,26,"﴿حِسَابَهُم﴾: جَزاءَهُم."]]);
QTF("gharib",89,[[1,1,"﴿وَٱلۡفَجۡرِ﴾: أقْسَم اللهُ بِوَقْتِ الفجْرِ."],[2,2,"﴿وَلَيَالٍ عَشۡرࣲ﴾: هي الليالي العَشْرُ الأُوَلُ مِن ذِي الحِجَّةِ."],[3,3,"﴿وَٱلشَّفۡعِ﴾: كُلُّ شَيءٍ خَلَقَه اللهُ زَوْجًا فهو شَفْعٌ.\n\n﴿وَٱلۡوَتۡرِ﴾: الفَرْدِ."],[4,4,"﴿يَسۡرِ﴾: يَسْرِي بِظَلامِهِ."],[5,5,"﴿قَسَمࣱ﴾: مَقْنَعٌ ومُكْتَفىً في القَسَمِ.\n\n﴿لِّذِي حِجۡرٍ﴾: لِصاحِبِ عَقْلٍ."],[7,7,"﴿إِرَمَ﴾: قَبِيلةِ إرَمَ.\n\n﴿ذَاتِ ٱلۡعِمَادِ﴾: صاحبةِ القُوُّةِ والأبْنِيَةِ المَرْفُوعَةِ على الأعْمِدَةِ."],[8,8,"﴿مِثۡلُهَا﴾: مِثْلُ تِلْكَ القَبِيلةِ في الطُّولِ والقُوَّةِ."],[9,9,"﴿جَابُواْ﴾: قَطَعُوا.\n\n﴿ٱلصَّخۡرَ﴾: الحَجَرَ العَظِيمَ الصُّلْبَ الَّذِي عَمِلُوا مِنهُ البُيوتَ.\n\n﴿بِٱلۡوَادِ﴾: بِوادِي القُرى."],[10,10,"﴿ذِي ٱلۡأَوۡتَادِ﴾: صاحِبِ الجُنُودِ الَّذِين ثَبَّتُوا مُلكَهُ، وقَوَّوا لَهُ أمْرَهُ."],[11,11,"﴿طَغَوۡاْ﴾: تَجاوَزُوا الحدَّ في الظُّلْمِ."],[13,13,"﴿فَصَبَّ عَلَيۡهِمۡ﴾: فَغَشّاهُم.\n\n﴿سَوۡطَ عَذَابٍ﴾: عَذابًا شَدِيدا."],[14,14,"﴿لَبِٱلۡمِرۡصَادِ﴾: لا يفُوتُه شَيءٌ مِن أعْمالِ العِبادِ."],[15,15,"﴿ٱبۡتَلَىٰهُ﴾: اخْتَبَرَهُ.\n\n﴿فَأَكۡرَمَهُۥ﴾: بَسَطَ لَهُ في رِزقِهِ.\n\n﴿وَنَعَّمَهُۥ﴾: جَعَلَه في أطْيَبِ عَيْشٍ."],[16,16,"﴿ٱبۡتَلَىٰهُ﴾: اخْتَبَرَهُ.\n\n﴿فَقَدَرَ﴾: فَضَيَّقَ.\n\n﴿أَهَـٰنَنِ﴾: أذَلَّنِي بالفَقْرِ."],[17,17,"﴿كَلَّا﴾: ليسَ الأمرُ كَما يَظُنُّ هَذا الإنْسانُ.\n\n﴿لَّا تُكۡرِمُونَ﴾: لا تُحْسنُونَ مُعامَلةَ.\n\n﴿ٱلۡيَتِيمَ﴾: الطِّفْلَ الَّذِي ماتَ أبُوهُ وهو صَغِيرٌ."],[18,18,"﴿وَلَا تَحَـٰٓضُّونَ﴾: ولا يَحثُّ بعضُكُم بعْضًا.\n\n﴿ٱلۡمِسۡكِينِ﴾: المُحْتاجِ الَّذِي لا يَمْلِكُ ما يَكْفِيهِ."],[19,19,"﴿ٱلتُّرَاثَ﴾: حُقُوقَ الآخرِينَ في الِميراثِ.\n\n﴿لَّمࣰّا﴾: شَدِيدًا، وهو أن يأكُلَ نَصِيبَهُ ونَصِيبَ غَيرِه."],[20,20,"﴿جَمࣰّا﴾: كَثِيرًا مُفْرِطًا."],[21,21,"﴿كَلَّآ﴾: لا ينبغِي أن يكُونَ حالُكُم كَما ذُكِر.\n\n﴿دُكَّتِ ٱلۡأَرۡضُ﴾: زُلْزِلَتِ الأرْضُ وكَسَّرَ بَعْضُها بَعْضًا.\n\n﴿دَكࣰّا دَكࣰّا﴾: مَرَّةً بعدَ مَرَّةٍ."],[22,22,"﴿وَٱلۡمَلَكُ﴾: والملائِكةُ.\n\n﴿صَفࣰّا صَفࣰّا﴾: صُفُوفًا صفُوفًا."],[23,23,"﴿يَتَذَكَّرُ ٱلۡإِنسَـٰنُ﴾: يتَّعِظُ الكافِرُ ويتُوبُ.\n\n﴿وَأَنَّىٰ لَهُ ٱلذِّكۡرَىٰ﴾: ومِن أينَ لَهُ التَّوبةُ؟."],[24,24,"﴿قَدَّمۡتُ﴾: العملَ الصّالحَ.\n\n﴿لِحَيَاتِي﴾: في الآخِرةِ."],[26,26,"﴿وَلَا يُوثِقُ﴾: ولا يَشُدُّ ويَربِطُ للعذابِ.\n\n﴿وَثَاقَهُۥٓ﴾: رَبْطَهُ بالسَّلاسِلِ ونَحْوِها للعذابِ."],[27,27,"﴿ٱلۡمُطۡمَئِنَّةُ﴾: الموقِنَةُ بِأنّ اللهَ ربُّها، المطيعةُ لَهُ."],[28,28,"﴿رَاضِيَةࣰ﴾: بالثَّوابِ.\n\n﴿مَّرۡضِيَّةࣰ﴾: مَرْضِيًّا عَنكِ."],[29,29,"﴿فِي عِبَـٰدِي﴾: مَعَ عِبادِي، وقيل: في جُمْلةِ عِبادِي الصّالحِينَ المُطِيعِينَ."]]);
QTF("gharib",90,[[1,1,"﴿لَآ أُقۡسِمُ بِهَـٰذَا ٱلۡبَلَدِ﴾: أقْسَمَ اللهُ بِهذا البَلَدِ الحَرامِ، وهو «مَكَّةُ»."],[2,2,"﴿حِلُّۢ بِهَـٰذَا ٱلۡبَلَدِ﴾: مُقِيمٌ في هذا البلدِ الحرامِ. أو حَلالٌ يَحِلُّ لَكَ القِتالُ فِيه ساعَةً من نَّهارِ يَومِ فتحِ مَكَّةَ."],[3,3,"﴿وَوَالِدࣲ﴾: آدمَ عَلَيهِ السَّلامُ.\n\n﴿وَمَا وَلَدَ﴾: وما تَناسَلَ مِنهُ مِن ولَدٍ."],[4,4,"﴿فِي كَبَدٍ﴾: في شِدَّةٍ وعَناءٍ مِن مُّكابَدَةِ الدُّنيا."],[5,5,"﴿أَيَحۡسَبُ﴾: أيَظُنُّ بِما جَمَعَهُ مِن مالٍ."],[6,6,"﴿أَهۡلَكۡتُ﴾: أنفَقْتُ.\n\n﴿لُّبَدًا﴾: كَثِيرًا."],[7,7,"﴿أَيَحۡسَبُ﴾: أيَظُنُّ في فِعْلِهِ هَذا.\n\n﴿أَن لَّمۡ يَرَهُۥٓ أَحَدٌ﴾: أنَّ اللهَ عَزَّ وجَلَّ لا يراهُ، ولا يحاسِبُهُ على الصَّغِيرِ والكَبِيرِ."],[10,10,"﴿وَهَدَيۡنَـٰهُ ٱلنَّجۡدَيۡنِ﴾: وبيَّنّا لَهُ سَبيلَي الخيرِ والشَّرِّ؟"],[11,11,"﴿فَلَا ٱقۡتَحَمَ ٱلۡعَقَبَةَ﴾: فَهَلّا تَجاوَزَ مَشَقَّةَ الآخِرةِ بإنفاقِ مالِه، فَيأمَنَ."],[12,12,"﴿وَمَآ أَدۡرَىٰكَ﴾: وأيُّ شَيءٍ أعْلَمَكَ؟.\n\n﴿مَا ٱلۡعَقَبَةُ﴾: ما مَشَقَّةُ الآخِرَةِ، وما يُعِينُ عَلى تَجاوُزِها؟"],[13,13,"﴿فَكُّ رَقَبَةٍ﴾: عِتْقُ رَقَبَةٍ مُؤْمِنَةٍ مِن أسْرِ الرِّقِ."],[14,14,"﴿ذِي مَسۡغَبَةࣲ﴾: صاحِبِ مجاعَةٍ شَدِيدَةٍ."],[15,15,"﴿ذَا مَقۡرَبَةٍ﴾: مِن ذَويِ القرابةِ."],[16,16,"﴿أَوۡ مِسۡكِينࣰا ذَا مَتۡرَبَةࣲ﴾: أو فَقِيرًا مُعْدَمًا لا شَيءَ عِنْدَهُ."],[17,17,"﴿وَتَوَاصَوۡاْ﴾: وأَوْصى بعضُهُم بَعْضًا.\n\n﴿بِٱلۡمَرۡحَمَةِ﴾: بالرَّحْمَةِ بالخلقِ."],[18,18,"﴿أَصۡحَـٰبُ ٱلۡمَيۡمَنَةِ﴾: هُمْ أصْحابُ اليمِينِ، الَّذِينَ يُؤخذُ بِهم يومَ القيامةِ ذاتَ اليمِينِ إلى الجنَّةِ."],[19,19,"﴿بِـَٔايَـٰتِنَا﴾: بالقُرْآنِ\n\n﴿أَصۡحَـٰبُ ٱلۡمَشۡـَٔمَةِ﴾: الَّذِينَ يُؤخَذُ بِهم يومَ القيامِة ذاتَ الشِّمالِ إلى النّار."],[20,20,"﴿مُّؤۡصَدَةُۢ﴾: مُطْبَقةٌ مُغْلَقَةٌ عَلَيهِم."]]);
QTF("gharib",91,[[1,1,"﴿وَضُحَىٰهَا﴾: أقْسَمَ اللهُ بإشْراقِ الشَّمْسِ ضُحىً."],[2,2,"﴿تَلَىٰهَا﴾: تَبِعَها في الطُّلُوعِ والأُفُول."],[3,3,"﴿جَلَّىٰهَا﴾: جَلّى الظُّلْمةَ وكَشَفَها."],[4,4,"﴿يَغۡشَىٰهَا﴾: يُغَطِّي الأَرْضَ فيكُونُ ما عَلَيها مُظْلِمًا."],[5,5,"﴿وَمَا بَنَىٰهَا﴾: وبِنائِها المُحْكَمِ."],[6,6,"﴿وَمَا طَحَىٰهَا﴾: وبَسْطِها."],[7,7,"﴿وَمَا سَوَّىٰهَا﴾: وإكْمالِ اللهِ خَلْقَها لأداءِ مُهِمَّتِها."],[8,8,"﴿فَأَلۡهَمَهَا﴾: فَبيَّنَ لَها.\n\n﴿فُجُورَهَا﴾: طَرِيقَ الشَّرِّ.\n\n﴿وَتَقۡوَىٰهَا﴾: وطَرِيقَ الخيرِ."],[9,9,"﴿أَفۡلَحَ﴾: فاز.\n\n﴿زَكَّىٰهَا﴾: طَهَّرَها، ونَمّاها بالخيرِ."],[10,10,"﴿خَابَ﴾: خَسِرَ.\n\n﴿دَسَّىٰهَا﴾: أخْفى نَفْسَهُ في المعاصِي."],[11,11,"﴿بِطَغۡوَىٰهَآ﴾: بِبُلُوغِها الغايةَ في العِصْيانِ."],[12,12,"﴿ٱنۢبَعَثَ﴾: نَهَضَ لِعَقْرِ النّاقةِ.\n\n﴿أَشۡقَىٰهَا﴾: أكْثَرُ القبيلةِ شَقاوَةً."],[13,13,"﴿نَاقَةَ ٱللَّهِ﴾: احْذَرُوا أن تَمَسُّوا النّاقَةَ بسُوءٍ.\n\n﴿وَسُقۡيَـٰهَا﴾: واحذَرُوا أن تَعْتَدُوا على سَقْيِها."],[14,14,"﴿فَعَقَرُوهَا﴾: فَنَحَرُوها.\n\n﴿فَدَمۡدَمَ عَلَيۡهِمۡ﴾: فَأَطْبَقَ عليهِم العُقُوبةَ.\n\n﴿فَسَوَّىٰهَا﴾: فَجَعَلَها عَلَيهِم على السَّواءِ، فلم يُفْلِتْ مِنهُم أحَدٌ."],[15,15,"﴿عُقۡبَـٰهَا﴾: تَبِعةَ ما أنزَلَهُ بِهِم مِنَ العِقابِ."]]);
QTF("gharib",92,[[1,1,"﴿يَغۡشَىٰ﴾: يُغَطِّي بِظلامِهِ الأَرْضَ وما عَلَيها."],[2,2,"﴿تَجَلَّىٰ﴾: انكَشَفَ عَن ظَلام الليلِ بضِيائِهِ."],[3,3,"﴿وَمَا خَلَقَ ٱلذَّكَرَ وَٱلۡأُنثَىٰٓ﴾: أقْسَمَ اللهُ بِخَلْقِ الزَّوجِينِ."],[4,4,"﴿إِنَّ سَعۡيَكُمۡ لَشَتَّىٰ﴾: عَمَلَكُم لَمُخْتَلِفٌ بَينَ عامِلٍ للدُّنيا وعامِلٍ للآخِرَةِ."],[5,5,"﴿أَعۡطَىٰ﴾: بَذَلَ مِن مّالِهِ."],[6,6,"﴿بِٱلۡحُسۡنَىٰ﴾: ب «لا إلَه إلا اللهُ» وما دَلَّتْ عَلَيهِ، وما تَرتَّبَ عَلَيها مِنَ الجَزاءِ."],[7,7,"﴿فَسَنُيَسِّرُهُۥ﴾: فَسَنُوَفِّقُهُ.\n\n﴿لِلۡيُسۡرَىٰ﴾: لِعَمَلِ الخيرِ والشَّرِيعةِ السَّهْلَةِ."],[8,8,"﴿بَخِلَ﴾: بِمالِهِ.\n\n﴿وَٱسۡتَغۡنَىٰ﴾: عَن جزاءِ اللهِ."],[9,9,"﴿بِٱلۡحُسۡنَىٰ﴾: بِالعِوَضِ مِنَ اللهِ."],[10,10,"﴿فَسَنُيَسِّرُهُۥ﴾: فسَنُهَيُّئهُ في الدُّنيا.\n\n﴿لِلۡعُسۡرَىٰ﴾: للْخَصْلَةِ العُسْرى، فَتَتَعَسَّرُ عَلَيه أسبابُ الخيرِ."],[11,11,"﴿وَمَا يُغۡنِي عَنۡهُ﴾: ولا يَنفَعُهُ.\n\n﴿تَرَدَّىٰٓ﴾: وقَعَ في النّارِ."],[12,12,"﴿لَلۡهُدَىٰ﴾: بيانَ طَرِيقِ الهُدى المُوصِلِ إلى اللهِ."],[13,13,"﴿وَإِنَّ لَنَا لَلۡـَٔاخِرَةَ﴾: وإنَّ لَنا مُلْكَ الحياةِ الآخِرَةِ.\n\n﴿وَٱلۡأُولَىٰ﴾: والحياةَ الدُّنيا."],[14,14,"﴿فَأَنذَرۡتُكُمۡ﴾: فَحَذَّرْتُكُم.\n\n﴿نَارࣰا تَلَظَّىٰ﴾: نارًا تَتَوهَّجُ، وهي نارُ جَهَنَّمَ."],[15,15,"﴿لَا يَصۡلَىٰهَآ﴾: لا يُقاسِي حَرَّها."],[16,16,"﴿كَذَّبَ﴾: لم يُصَدِّق نبيَّ اللهِ محمدًا ﷺ.\n\n﴿وَتَوَلَّىٰ﴾: وأَعْرَضَ عَنِ الإيمانِ باللهِ ورسولِه، وطاعَتِهِما."],[17,17,"﴿وَسَيُجَنَّبُهَا﴾: وسَيُزَحْزَحُ عَنْها."],[18,18,"﴿يُؤۡتِي مَالَهُۥ﴾: يَبْذُلُ مالَهُ.\n\n﴿يَتَزَكَّىٰ﴾: يَطلبُ المزيدَ مِنَ الخيرِ."],[19,19,"﴿وَمَا لِأَحَدٍ عِندَهُۥ مِن نِّعۡمَةࣲ تُجۡزَىٰٓ﴾: ولَيسَ إنفاقُه ذاكَ مُكافأةً لِمنْ أسْدى إلَيهِ معرُوفًا."],[20,20,"﴿إِلَّا﴾: لَكِنَّهُ."]]);
QTF("gharib",93,[[1,1,"﴿وَٱلضُّحَىٰ﴾: أقْسَمَ اللهُ بِوقتِ الضُّحى، والمرادُ بِهِ النَّهارُ كُلُّهُ."],[2,2,"﴿سَجَىٰ﴾: اشْتَدَّ ظَلامُهُ."],[3,3,"﴿مَا وَدَّعَكَ﴾: ما تَرَكَكَ.\n\n﴿وَمَا قَلَىٰ﴾: وما أبْغَضَكَ حِينَ أبْطَأَ الوحْيُ عَنكَ."],[5,5,"﴿وَلَسَوۡفَ يُعۡطِيكَ رَبُّكَ﴾: -أيُّها النَّبِيُّ- مِن أنواعِ الإنْعام في الآخِرَةِ."],[6,6,"﴿فَـَٔاوَىٰ﴾: فَآواكَ ورَعاكَ."],[7,7,"﴿ضَآلࣰّا﴾: لا تَدْرِي ما الكِتابُ ولا الإيمانُ؟.\n\n﴿فَهَدَىٰ﴾: فَعَلَّمكَ مالَمْ تَكُن تَعْلَمُ."],[8,8,"﴿عَآئِلࣰا﴾: فقِيرًا.\n\n﴿فَأَغۡنَىٰ﴾: فَساقَ لَكَ رِزْقَكَ، وأَغْنى نَفسَكَ بالقناعَةِ والصَّبْرِ؟"],[9,9,"﴿فَلَا تَقۡهَرۡ﴾: فلا تُسِئْ مُعامَلَتَهُ."],[10,10,"﴿فَلَا تَنۡهَرۡ﴾: فَلا تَزْجُرْهُ."]]);
QTF("gharib",94,[[1,1,"﴿أَلَمۡ نَشۡرَحۡ لَكَ صَدۡرَكَ﴾: ألَمْ نُوَسِّعْ -أيُّها النَّبِيُّ- لَكَ صَدْرَكَ لِشرائِعِ الدِّينِ، والدَّعْوةِ إلى اللهِ، والاتِّصافِ بِمكارِمِ الأخلاقِ."],[2,2,"﴿وَوَضَعۡنَا عَنكَ وِزۡرَكَ﴾: وحَطَطْنا عَنكَ بِذَلِكَ حِمْلكَ."],[3,3,"﴿أَنقَضَ﴾: أثْقَلَ."],[5,5,"﴿فَإِنَّ مَعَ ٱلۡعُسۡرِ يُسۡرًا﴾: فإنّ مَعَ الضِّيقِ فَرَجًا."],[7,7,"﴿فَرَغۡتَ﴾: أتْمَمْتَ عَمَلًا مِن أُمُورِ الدُّنيا.\n\n﴿فَٱنصَبۡ﴾: فَجِدَّ في الِعبادةِ."]]);
QTF("gharib",95,[[2,2,"﴿وَطُورِ سِينِينَ﴾: أقَسَمَ اللهُ بِجَبَلِ «طُورِ سَيناءَ» الَّذِي كَلَّمَ اللهُ عَلَيه مُوسى تَكْلِيمًا."],[3,3,"﴿وَهَـٰذَا ٱلۡبَلَدِ﴾: وأَقَسَمَ اللهُ بمَكَّةَ."],[4,4,"﴿فِيٓ أَحۡسَنِ تَقۡوِيمࣲ﴾: في أحَسَنِ صُورَةٍ."],[5,5,"﴿أَسۡفَلَ سَـٰفِلِينَ﴾: أي: إلى النّارِ."],[6,6,"﴿أَجۡرٌ غَيۡرُ مَمۡنُونࣲ﴾: أجْرٌ عظِيمٌ غَيرُ مَقْطُوعٍ."],[7,7,"﴿فَمَا يُكَذِّبُكَ بَعۡدُ بِٱلدِّينِ﴾: أيُّ شَيءٍ يَحْمِلُكَ -أيُّها الإنسانُ- عَلى أن تُكَذِّبَ بالبَعْثِ والجزاءِ مَعَ وُضُوحِ الأدِلَّةِ عَلى قُدْرَةِ اللهِ تعالى؟"],[8,8,"﴿بِأَحۡكَمِ ٱلۡحَـٰكِمِينَ﴾: بأَحْكَمِ مَن حَكَمَ في أحْكامِهِ وفَصْلِ قَضائِهِ."]]);
QTF("gharib",96,[[1,1,"﴿ٱقۡرَأۡ﴾: اقْرَأْ -أيُّها النَّبِيُّ- ما أُنِزلَ إلَيكَ مِن القُرآنِ.\n\n﴿بِٱسۡمِ رَبِّكَ﴾: مُفْتَتِحًا باسْمِ رَبِّكَ.\n\n﴿ٱلَّذِي خَلَقَ﴾: المُتَفَرِّدِ بالخَلْقِ."],[2,2,"﴿عَلَقٍ﴾: قِطْعَةِ دَمٍ غَلِيظ أحْمَرَ."],[3,3,"﴿ٱلۡأَكۡرَمُ﴾: الكثِيرُ الإحسانِ."],[4,4,"﴿بِٱلۡقَلَمِ﴾: الكِتابة بالقَلَمِ."],[6,6,"﴿كَلَّآ﴾: حَقًّا.\n\n﴿لَيَطۡغَىٰٓ﴾: لَيتَجاوَزُ حُدُودَ اللهِ."],[7,7,"﴿أَن رَّءَاهُ ٱسۡتَغۡنَىٰٓ﴾: لِأَجْلِ أنَّهُ وجَدَ نَفْسَه مُسْتَغْنِيًا شَدِيدَ الغِنى."],[8,8,"﴿ٱلرُّجۡعَىٰٓ﴾: المَصِيرَ."],[9,9,"﴿أَرَءَيۡتَ ٱلَّذِي يَنۡهَىٰ﴾: أرأيتَ أعْجَبَ مِن طُغيانِ هذا الرَّجُلِ -وهو أبو جَهْلٍ- الَّذِي يَنْهى."],[10,10,"﴿عَبۡدًا﴾: هو مُحَمَّدٌ ﷺ."],[11,11,"﴿أَرَءَيۡتَ إِن كَانَ عَلَى ٱلۡهُدَىٰٓ﴾: أرأيت إن كان المَنهِيُّ عَنِ الصَّلاةِ عَلى الهُدى فَكَيفَ يَنْهاهُ؟"],[13,13,"﴿وَتَوَلَّىٰٓ﴾: وأَعْرَضَ عَنْهُ."],[15,15,"﴿كَلَّا﴾: لَيسَ الأمرُ كَما يَزْعُمُ أبو جَهْلٍ.\n\n﴿لَنَسۡفَعَۢا بِٱلنَّاصِيَةِ﴾: لَنَأْخُذَنَّ بِمُقَدَّمِ رَأْسِهِ أخْذًا عَنِيفًا، وليُطْرَحَنَّ في النّارِ."],[17,17,"﴿فَلۡيَدۡعُ نَادِيَهُۥ﴾: فليُحْضِرْ أهْلَ نادِيهِ الَّذِين يَسْتَنْصِرُ بِهِم."],[18,18,"﴿سَنَدۡعُ ٱلزَّبَانِيَةَ﴾: سَنَدعُو ملائِكةَ العذابِ."],[19,19,"﴿كَلَّا﴾: لَيس الأمرُ على ما يَظُنُّ. إنُّه لَن يَنالَكَ -أيُّها الرَّسُولُ- بِسُوءٍ.\n\n﴿لَا تُطِعۡهُ﴾: فلا تُطِعْهُ فيما دَعاكَ إلَيهِ.\n\n﴿وَٱقۡتَرِب﴾: واجْتَهِدْ في القُربِ مِن اللهِ."]]);
QTF("gharib",97,[[1,1,"﴿أَنزَلۡنَـٰهُ﴾: أنْزَلْنا القُرآنَ.\n\n﴿ٱلۡقَدۡرِ﴾: الشَّرَفِ والفَضْلِ، وهي إحْدى لَيالِي شَهْرِ رَمَضانَ."],[2,2,"﴿وَمَآ أَدۡرَىٰكَ﴾: وأيُّ شَيءٍ أعْلَمَكَ؟"],[3,3,"﴿خَيۡرࣱ مِّنۡ أَلۡفِ شَهۡرࣲ﴾: فَضْلُها خَيرٌ مِن فَضْلِ ألْفِ شَهْرٍ."],[4,4,"﴿تَنَزَّلُ ٱلۡمَلَـٰٓئِكَةُ وَٱلرُّوحُ فِيهَا﴾: يَكْثُرُ نُزُولُ الملائِكةِ وجِبْريلَ عَلَيهِ السَّلامُ فِيها.\n\n﴿بِإِذۡنِ رَبِّهِم﴾: أي في النُّزُولِ.\n\n﴿مِّن كُلِّ أَمۡرࣲ﴾: مِن أجْلِ كُلِّ أمْرٍ أرادَ اللهُ قَضاءَه في تِلْك السَّنةِ."],[5,5,"﴿سَلَـٰمٌ هِيَ﴾: هي أمْنٌ كُلُّها.\n\n﴿حَتَّىٰ مَطۡلَعِ ٱلۡفَجۡرِ﴾: إلى طُلُوعِ الفجْرِ."]]);
QTF("gharib",98,[[1,1,"﴿مُنفَكِّينَ﴾: تاركِينَ كُفْرَهُم.\n\n﴿ٱلۡبَيِّنَةُ﴾: العَلامةُ الَّتِي وُعِدُوا بِها في الكُتُبِ السّابِقَةِ."],[2,2,"﴿صُحُفࣰا﴾: قُرآنًا في صُحُفٍ."],[3,3,"﴿كُتُبࣱ قَيِّمَةࣱ﴾: أخْبارٌ صادِقَةٌ، تهدِي إلى الحقِّ."],[4,4,"﴿جَآءَتۡهُمُ ٱلۡبَيِّنَةُ﴾: تَبيَّنُوا أنُّه النَّبِيُّ الَّذِي وُعِدُوا بِهِ."],[5,5,"﴿مُخۡلِصِينَ لَهُ ٱلدِّينَ﴾: قاصِدِينَ بِعِبادَتِهِم وجْهَهُ.\n\n﴿حُنَفَآءَ﴾: مائِلِينَ عَنِ الشِّركِ إلى الإيمانِ.\n\n﴿دِينُ ٱلۡقَيِّمَةِ﴾: دِينُ الاسْتِقامةِ، وهو الإسلامُ."],[6,6,"﴿شَرُّ﴾: أشَدُّ شَرًّا."],[7,7,"﴿ٱلۡبَرِيَّةِ﴾: الخَلْقِ."],[8,8,"﴿جَنَّـٰتُ عَدۡنࣲ﴾: جَنّاتُ إقامَةٍ واسْتِقرارٍ في مُنْتَهى الحُسْنِ.\n\n﴿مِن تَحۡتِهَا﴾: مِن تَحْتِ قُصُورِها وأشجارِها.\n\n﴿خَشِيَ رَبَّهُۥ﴾: خافَ اللهَ واجْتَنَبَ مَعاصيَهُ."]]);
QTF("gharib",99,[[1,1,"﴿زُلۡزِلَتِ﴾: رُجَّتْ.\n\n﴿زِلۡزَالَهَا﴾: رَجًّا شَدِيدًا."],[2,2,"﴿أَثۡقَالَهَا﴾: ما في بَطْنِها مِن مَوتى وكُنُوزٍ."],[3,3,"﴿مَا لَهَا﴾: ما الَّذِي حَدَثَ لَها؟"],[4,4,"﴿يَوۡمَئِذࣲ﴾: يَومَ القيامةِ.\n\n﴿تُحَدِّثُ أَخۡبَارَهَا﴾: تُخْبِرُ الأَرْضُ بِما عُمِلَ عَلَيها مِن خَيرٍ أو شَرٍّ."],[5,5,"﴿أَوۡحَىٰ لَهَا﴾: أمَرَها بأن تُخْبِرَ بِما عُمِلَ عَلَيها."],[6,6,"﴿يَصۡدُرُ ٱلنَّاسُ﴾: يَرْجِعُ النّاسُ عَن مَوقِفِ الحِسابِ.\n\n﴿أَشۡتَاتࣰا﴾: أصنافًا مُتَفَرِّقِينَ.\n\n﴿لِّيُرَوۡاْ أَعۡمَـٰلَهُمۡ﴾: لِيُرِيَهُم اللهُ ما عَمِلُوا."],[7,7,"﴿مِثۡقَالَ ذَرَّةٍ﴾: وزنَ نَمْلَةٍ صَغِيرَةٍ.\n\n﴿يَرَهُۥ﴾: يَرَ ثَوابَهُ في الآخِرَةِ."]]);
QTF("gharib",100,[[1,1,"﴿وَٱلۡعَـٰدِيَـٰتِ﴾: أقْسَمَ اللهُ تَعالى بالخَيلِ الجارياتِ في سَبِيلِ اللهِ.\n\n﴿ضَبۡحࣰا﴾: حِينَ يَظْهَرُ صَوْتُها مِن سُرْعَةِ عَدْوِها."],[2,2,"﴿فَٱلۡمُورِيَـٰتِ قَدۡحࣰا﴾: فالخَيلِ اللاتِي تَنْقَدِحُ النّارُ مِن حَوافِرِها؛ من شِدَّةِ عَدْوِها."],[3,3,"﴿فَٱلۡمُغِيرَ ٰ⁠تِ﴾: فالمُغِيراتِ عَلى الأعداءِ.\n\n﴿صُبۡحࣰا﴾: عِنْدَ الصُّبْحِ."],[4,4,"﴿فَأَثَرۡنَ بِهِۦ﴾: فهَيَّجْنَ بِهذا العَدْوِ.\n\n﴿نَقۡعࣰا﴾: غُبارًا."],[5,5,"﴿فَوَسَطۡنَ بِهِۦ﴾: فتوسَّطْنَ بِرُكْبانِهِنَّ.\n\n﴿جَمۡعًا﴾: جُموعَ الأعداءِ."],[6,6,"﴿لِرَبِّهِۦ لَكَنُودࣱ﴾: لِنِعَمِ رَبَّهِ لَجَحُودٌ."],[7,7,"﴿عَلَىٰ ذَ ٰ⁠لِكَ لَشَهِيدࣱ﴾: مُقِرٌّ بِجُحُودِهِ."],[8,8,"﴿ٱلۡخَيۡرِ﴾: المالِ."],[9,9,"﴿بُعۡثِرَ مَا فِي ٱلۡقُبُورِ﴾: أخْرَجَ اللهُ الأمواتَ مِنَ القُبُورِ لِلْحِسابِ؟"],[10,10,"﴿وَحُصِّلَ﴾: واسْتُخْرِجَ.\n\n﴿مَا فِي ٱلصُّدُورِ﴾: ما اسْتَتَرَ في الصُّدُورِ مِن خَيْرٍ أو شَرٍّ."],[11,11,"﴿لَّخَبِيرُۢ﴾: لَمُطَّلِعٌ على باطِنِ أمْرِهِم فلا يَخْفى عَلَيهِ شيءٌ مِن ذَلِكَ."]]);
QTF("gharib",101,[[1,1,"﴿ٱلۡقَارِعَةُ﴾: السّاعةُ الَّتِي تَقْرَعُ قُلُوبَ النّاسِ بِأَهْوالِها."],[3,3,"﴿وَمَآ أَدۡرَىٰكَ﴾: وأيُّ شَيءٍ أعَلَمَكَ بِها؟"],[4,4,"﴿كَٱلۡفَرَاشِ ٱلۡمَبۡثُوثِ﴾: كالفَراشِ المُنْتَشِرِ."],[5,5,"﴿كَٱلۡعِهۡنِ ٱلۡمَنفُوشِ﴾: كالصُّوفِ المُتَعَدِّدِ الألوانِ الَّذِي يُنْفَشُ باليدِ، فَيَصِيرُ هَباءً ويَزُولُ."],[6,6,"﴿مَن ثَقُلَتۡ مَوَ ٰ⁠زِينُهُۥ﴾: مَن رَجَحَتْ مَوازِينُ حَسَناتِهِ."],[7,7,"﴿عِيشَةࣲ رَّاضِيَةࣲ﴾: حياةٍ مُرْضِيَةٍ في الجنَّةِ."],[8,8,"﴿مَنۡ خَفَّتۡ مَوَ ٰ⁠زِينُهُۥ﴾: مَن خَفَّتْ مَوازِينُ حسناتِهِ ورَجَحَتْ مَوازينُ سَيِّئاتِهِ."],[9,9,"﴿فَأُمُّهُۥ هَاوِيَةࣱ﴾: فَمَأواهُ جَهَنَّمُ؛ لِأنّهُ يَهْوِي فِيها عَلى أُمِّ رَأْسِهِ."],[10,10,"﴿وَمَآ أَدۡرَىٰكَ﴾: وأيُّ شَيءٍ أعْلَمكَ؟\n\n﴿مَا هِيَهۡ﴾: ما هذهِ الهاوِيةُ؟."],[11,11,"﴿حَامِيَةُۢ﴾: قَدْ حَمِيَتْ مِنَ الوَقُودِ عَلَيها."]]);
QTF("gharib",102,[[1,1,"﴿أَلۡهَىٰكُمُ﴾: شَغَلَكُم عَن طاعَةِ اللهِ.\n\n﴿ٱلتَّكَاثُرُ﴾: التَّفاخُرُ بِكَثْرةِ الأَمْوالِ والأولادِ."],[2,2,"﴿حَتَّىٰ زُرۡتُمُ ٱلۡمَقَابِرَ﴾: وانْشَغَلتُم بِذَلِكَ إلى أن دُفِنتم في المقابِر."],[3,3,"﴿كَلَّا﴾: ما هَكَذا ينبغي أن يُلْهيَكُم التكاثُرُ بالأَمْوالِ.\n\n﴿سَوۡفَ تَعۡلَمُونَ﴾: أنَّ الدّارَ الآخِرةَ خَيرٌ لَكُم."],[5,5,"﴿لَوۡ تَعۡلَمُونَ عِلۡمَ ٱلۡيَقِينِ﴾: لو تَعْلَمُونَ حَقَّ العِلْمِ لانْزَجَرْتُم، ولَبادَرْتُم إلى إنقاذِ أنفُسِكُم مِنَ الهَلاكِ."],[6,6,"﴿لَتَرَوُنَّ ٱلۡجَحِيمَ﴾: لَتُبصِرُنَّ الجحِيمَ."],[7,7,"﴿ثُمَّ لَتَرَوُنَّهَا عَيۡنَ ٱلۡيَقِينِ﴾: ثُمَّ لَتُبْصِرُنَّها دُونَ رَيبٍ."],[8,8,"﴿يَوۡمَئِذٍ﴾: يومَ القِيامةِ.\n\n﴿عَنِ ٱلنَّعِيمِ﴾: عَن كُلِّ أنَواعِ النَّعِيمِ."]]);
QTF("gharib",103,[[1,1,"﴿وَٱلۡعَصۡرِ﴾: أقْسَمَ اللهُ بالدَّهْرِ."],[2,2,"﴿إِنَّ ٱلۡإِنسَـٰنَ﴾: إنّ بَنِي آدَمَ.\n\n﴿لَفِي خُسۡرٍ﴾: لَفِي هَلَكَةٍ ونُقْصانٍ، وسُوءِ عاقبةٍ."],[3,3,"﴿وَتَوَاصَوۡاْ﴾: وأوصى بَعْضُهم بَعْضًا.\n\n﴿بِٱلۡحَقِّ﴾: بالاسْتِمساكِ بالحقِّ، والعملِ بِطاعةِ اللهِ."]]);
QTF("gharib",104,[[1,1,"﴿وَيۡلࣱ﴾: شَرٌّ وهَلاكٌ.\n\n﴿لِّكُلِّ هُمَزَةࣲ﴾: لِكُلِّ مُغْتابٍ للنّاسِ.\n\n﴿لُّمَزَةٍ﴾: طَعّانٍ فِيهِم."],[2,2,"﴿جَمَعَ مَالࣰا وَعَدَّدَهُۥ﴾: كانَ همُّه جَمْعَ المالِ وتَعْدادَهُ."],[3,3,"﴿أَخۡلَدَهُۥ﴾: جَعَلَه خالِدًا في الدُّنيا."],[4,4,"﴿لَيُنۢبَذَنَّ﴾: ليُطْرَحَنَّ.\n\n﴿فِي ٱلۡحُطَمَةِ﴾: في النّارِ الَّتِي تُحَطِّم كُلَّ ما يُلْقى فِيها."],[5,5,"﴿وَمَآ أَدۡرَىٰكَ﴾: وأيُّ شيءٍ أعْلَمَكَ؟"],[6,6,"﴿ٱلۡمُوقَدَةُ﴾: المسْتَعِرَةُ الَّتِي لا يزُولُ لَهِيبُها."],[7,7,"﴿تَطَّلِعُ عَلَى ٱلۡأَفۡـِٔدَةِ﴾: من شِدَّتِها تَنفُذُ مِنَ الأجْسام إلى القُلُوبِ."],[8,8,"﴿مُّؤۡصَدَةࣱ﴾: مُغْلَقةٌ غَلْقًا مُطْبِقًا."],[9,9,"﴿فِي عَمَدࣲ﴾: مَوْثُوقِينَ في سَلاسِلَ وأغلالٍ.\n\n﴿مُّمَدَّدَةِۭ﴾: مُطَوَّلَةٍ؛ لئلّا يَخرُجُوا مِنها."]]);
QTF("gharib",105,[[1,1,"﴿أَلَمۡ تَرَ﴾: ألَمْ تَعْلَمْ.\n\n﴿بِأَصۡحَـٰبِ ٱلۡفِيلِ﴾: أبْرَهَة الحَبَشِيِّ وجَيشِهِ الَّذِين أرادُوا تَدمِيرَ الكعْبةِ."],[2,2,"﴿كَيۡدَهُمۡ﴾: ما دبَّرُوهُ مِن شَرٍّ.\n\n﴿فِي تَضۡلِيلࣲ﴾: في إبطالٍ وتَضْيِيعٍ؟."],[3,3,"﴿أَبَابِيلَ﴾: في جماعاتٍ مُتَتابِعةٍ."],[4,4,"﴿تَرۡمِيهِم﴾: تَقْذِفُهُم.\n\n﴿سِجِّيلࣲ﴾: طِينٍ مُتَحَجِّرٍ."],[5,5,"﴿كَعَصۡفࣲ مَّأۡكُولِۭ﴾: كَأَوْراقِ الزَّرعِ اليابِسةِ الَّتِي أكَلَتْها البهائِمُ ثُمَّ رَمَتْ بِها."]]);
QTF("gharib",106,[[1,1,"﴿لِإِيلَـٰفِ قُرَيۡشٍ﴾: اعْجَبُوا لِعادَةِ قُرَيشٍ. وقُرِيشٌ: اسمُ قَبِيلةٍ."],[2,2,"﴿إِۦلَـٰفِهِمۡ رِحۡلَةَ ٱلشِّتَآءِ وَٱلصَّيۡفِ﴾: تَعَوُّدِهِم عَلى انْتِظامِ رِحْلَتَيهِم في الشِّتاءِ إلى «اليمن»، وفي الصَّيفِ إلى «الشّامِ». والرِّحْلةُ: اسْمٌ للارْتِحالِ."],[3,3,"﴿هَـٰذَا ٱلۡبَيۡتِ﴾: هُوَ الكَعْبَةُ."]]);
QTF("gharib",107,[[1,1,"﴿بِٱلدِّينِ﴾: بالبَعْثِ والجزاءِ."],[2,2,"﴿يَدُعُّ ٱلۡيَتِيمَ﴾: يَدفعُ اليتيمَ بِعُنفٍ."],[3,3,"﴿وَلَا يَحُضُّ عَلَىٰ طَعَامِ ٱلۡمِسۡكِينِ﴾: ولا يَحُضُّ غَيرَهُ عَلى إطْعامِ المِسْكِينِ."],[4,4,"﴿فَوَيۡلࣱ﴾: فَعَذابٌ شَدِيدٌ."],[5,5,"﴿سَاهُونَ﴾: لاهُونَ، لا يُقيمُونَها على وجْهِهِا، ولا يُؤَدُّونَها في وقْتِها."],[6,6,"﴿ٱلَّذِينَ هُمۡ يُرَآءُونَ﴾: الَّذِين هُم يَعْمَلُونَ الخيرَ مُراءاةً للنّاسِ."],[7,7,"﴿وَيَمۡنَعُونَ ٱلۡمَاعُونَ﴾: ويَمْنَعُونَ إعارَةَ ما لا تَضُرُّ إعارَتُهُ مِنَ الآنِيةِ وغَيرِها."]]);
QTF("gharib",108,[[1,1,"﴿ٱلۡكَوۡثَرَ﴾: الخيرَ الكَثِيرَ في الدُّنيا والآخِرَةِ، ومِن ذَلِكَ نَهرُ الكَوْثَرِ في الجنَّةِ."],[2,2,"﴿وَٱنۡحَرۡ﴾: واذْبَحْ ذَبيحَتكَ للهِ."],[3,3,"﴿شَانِئَكَ﴾: مُبْغِضَكَ.\n\n﴿هُوَ ٱلۡأَبۡتَرُ﴾: هُوَ المُنْقَطِعُ أثَرُهُ، المقطُوعُ مِن كُلِّ خَيرٍ."]]);
QTF("gharib",109,[[2,2,"﴿لَآ أَعۡبُدُ مَا تَعۡبُدُونَ﴾: لا تَحصُلُ منِّي عِبادَةُ ما تَعْبُدُونَ مِنَ الأصْنامِ والآلِهَةَ الزّائِفَةِ."],[3,3,"﴿وَلَآ أَنتُمۡ عَـٰبِدُونَ مَآ أَعۡبُدُ﴾: وما أنتُم عابِدُونَ في المسْتَقْبَلِ ما أعْبُدُ مِن إلهٍ واحدٍ، هُوَ اللهُ رَبُّ العالمَينَ المُسْتَحِقُّ وحْدَهُ لِلعِبادةِ."],[4,4,"﴿وَلَآ أَنَا۠ عَابِدࣱ مَّا عَبَدتُّمۡ﴾: ولا أنا عابِدٌ ما عبدتُم مِنَ الأصْنامِ والآلِهَةِ الباطِلةِ فيما مَضى مِنَ الأزْمانِ."],[5,5,"﴿وَلَآ أَنتُمۡ عَـٰبِدُونَ مَآ أَعۡبُدُ﴾: ولا أنتُم عابِدُونَ مُسْتَقْبلًا ما أعْبُدُ."],[6,6,"﴿لَكُمۡ دِينُكُمۡ﴾: الَّذِي أصْرَرْتُم على اتِّباعِهِ، يختصُّ بِكُم وأنا بَرِيءٌ مِنهُ.\n\n﴿وَلِيَ دِينِ﴾: الَّذِي أنا مُخْتَصٌّ بِهِ لا تَشْرَكُونِي فِيه، ولَيسَ في الآيةِ إقْرارٌ لِدِينِهِم."]]);
QTF("gharib",110,[[1,1,"﴿نَصۡرُ ٱللَّهِ﴾: النَّصْرُ عَلى كُفّارِ قُرَيشٍ.\n\n﴿وَٱلۡفَتۡحُ﴾: وتَمَّ لَكَ فَتْحُ «مَكَّةَ»."],[2,2,"﴿أَفۡوَاجࣰا﴾: جماعات جَماعاتٍ."],[3,3,"﴿فَسَبِّحۡ﴾: فنزِّهْ رَبَّكَ.\n\n﴿بِحَمۡدِ رَبِّكَ﴾: مُتلَبِّسًا بِحَمْدِ رَبّكَ."]]);
QTF("gharib",111,[[1,1,"﴿تَبَّتۡ يَدَآ أَبِي لَهَبࣲ﴾: خَسِرتْ يدا أبي لَهَبٍ وشَقِيَ بِإيذائِهِ رَسُولَ اللهِ مُحَمَّدًا ﷺ.\n\n﴿وَتَبَّ﴾: وقَد تَحقَّقَ خُسْرانُ أبي لَهَبٍ."],[2,2,"﴿مَآ أَغۡنَىٰ عَنۡهُ مَالُهُۥ﴾: ما دَفعَ عنه مالُه، ولَن يَرُدَّ عنْهُ شَيئًا مِن عَذابِ اللهِ إذا نَزَلَ بِهِ.\n\n﴿وَمَا كَسَبَ﴾: وكَسْبُه الَّذِي جَمَعَ."],[3,3,"﴿سَيَصۡلَىٰ﴾: سَيَدْخُلُ.\n\n﴿ذَاتَ لَهَبࣲ﴾: مُتَأَجِّجَةً."],[4,4,"﴿وَٱمۡرَأَتُهُۥ حَمَّالَةَ ٱلۡحَطَبِ﴾: هُوَ وامْرأتُه الَّتِي كانتْ تَحْمِلُ الشَّوكَ، فَتَطْرَحُهُ في طَرِيقِ النَّبِيِّ ﷺ؛ لِأذِيَّتِهِ."],[5,5,"﴿فِي جِيدِهَا﴾: في عُنُقِها.\n\n﴿مِّن مَّسَدِۭ﴾: حَبْلٌ مُحْكَمُ الفَتْلِ مِن لِيفٍ شَدِيدٍ خَشِنٍ، تُرْفَعُ بِهِ في نارِ جَهَنَّمَ، ثُمَّ تُرْمى إلى أسْفَلِها."]]);
QTF("gharib",112,[[1,1,"﴿هُوَ ٱللَّهُ أَحَدٌ﴾: هُو اللهُ المتفرِّدُ بالأُلُوهِيَّةِ والرُّبُوبِيَّةِ والأسْماءِ والصِّفاتِ، لا يُشارِكُه أحَدٌ فِيها."],[2,2,"﴿ٱللَّهُ ٱلصَّمَدُ﴾: اللهُ وحْدَهُ السَّيِّدُ الكاملُ الصفات، المَقْصُودُ في قَضاءِ الحوائِجِ."],[3,3,"﴿لَمۡ يَلِدۡ وَلَمۡ يُولَدۡ﴾: لَيسَ لَهُ ولَدٌ ولا والِدٌ ولا صاحِبَةٌ."],[4,4,"﴿وَلَمۡ يَكُن لَّهُۥ كُفُوًا أَحَدُۢ﴾: ولَمْ يَكُن لَهُ مُماثِلًا ولا مشابهًا أحدٌ مِن خَلْقِهِ، لا في أسمائِهِ ولا في صِفاتِهِ، ولا في أفعالِهِ، تَبارك وتَعالى وتَقَدَّسَ."]]);
QTF("gharib",113,[[1,1,"﴿أَعُوذُ بِرَبِّ ٱلۡفَلَقِ﴾: أعْتَصِمُ بِرَبِّ الصُّبْحِ."],[2,2,"﴿مِن شَرِّ مَا خَلَقَ﴾: مِن شَرِّ جَمِيعِ المخلوقات وأذاها."],[3,3,"﴿غَاسِقٍ﴾: لَيلٍ شَدِيدِ الظُّلْمَةِ.\n\n﴿إِذَا وَقَبَ﴾: دَخَلَ ظَلامُهُ في كُلِّ شَيءٍ."],[4,4,"﴿ٱلنَّفَّـٰثَـٰتِ فِي ٱلۡعُقَدِ﴾: السّاحِراتِ اللاتِي يَنفُخْنَ فِيما يَعْقِدْنَ مِن عُقَدٍ بِقَصْدِ السِّحْرِ."],[5,5,"﴿وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ﴾: ومِن شَرِّ حاسِدٍ مُبْغِضٍ للنّاسِ، إذا حَسَدَهُم عَلى ما وهَبَهُم اللهُ مِنَ النِّعَمِ."]]);
QTF("gharib",114,[[1,1,"﴿أَعُوذُ بِرَبِّ ٱلنَّاسِ﴾: أعْتَصِمُ بِرَبِّ النّاسِ."],[2,2,"﴿مَلِكِ ٱلنَّاسِ﴾: المُتَصرِّفِ في كُلِّ شُؤُونِهِم، الغَنِيِّ عَنْهُم."],[3,3,"﴿إِلَـٰهِ ٱلنَّاسِ﴾: الَّذِي لا مَعْبُودَ بِحَقٍّ سِواهُ."],[4,4,"﴿مِن شَرِّ ٱلۡوَسۡوَاسِ﴾: مِن أذى الشَّيطانِ الَّذِي يُوسْوِسُ عِنْدَ الغَفْلةِ.\n\n﴿ٱلۡخَنَّاسِ﴾: الَّذِي يَخْتفِي عِنْدَ ذِكْرِ اللهِ."],[5,5,"﴿يُوَسۡوِسُ فِي صُدُورِ ٱلنَّاسِ﴾: يَبُثُّ الشَّرَّ والشُّكُوكَ في صُدُورِ النّاسِ."],[6,6,"﴿مِنَ ٱلۡجِنَّةِ وَٱلنَّاسِ﴾: مِن شياطِينِ الجِنِّ والإنْسِ."]]);